--
-- Name: app_has_permission(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_has_permission(permission text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.membership_roles mr
    JOIN public.role_permissions rp USING (organization_id, role_id)
    JOIN public.roles role ON role.organization_id=mr.organization_id AND role.id=mr.role_id AND role.active
    WHERE mr.organization_id = nullif(current_setting('app.organization_id', true), '')::uuid
      AND mr.user_id = nullif(current_setting('app.user_id', true), '')::uuid
      AND rp.permission_code = permission
  )
$$;


--
-- Name: auth_cancel_mfa_setup(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_cancel_mfa_setup(requested_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE own_session uuid := public.auth_mfa_locked_session();
BEGIN
  DELETE FROM public.user_mfa_setups p WHERE p.session_id = own_session AND p.id = requested_id;
END $$;


--
-- Name: auth_change_password(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_change_password(expected_hash text, new_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE changed_user uuid := nullif(current_setting('app.user_id', true), '')::uuid; new_revision integer;
BEGIN
  PERFORM 1 FROM public.users WHERE id = changed_user AND active FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  UPDATE public.credentials SET password_hash = new_hash, revision = revision + 1, updated_at = now()
    WHERE user_id = changed_user AND password_hash = expected_hash RETURNING revision INTO new_revision;
  IF NOT FOUND THEN RETURN false; END IF;
  UPDATE public.users SET must_change_password = false, updated_at = now(), revision = revision + 1 WHERE id = changed_user;
  UPDATE public.sessions SET revoked_at = now() WHERE user_id = changed_user
    AND id <> nullif(current_setting('app.session_id', true), '')::uuid AND revoked_at IS NULL;
  UPDATE public.sessions SET credential_revision = new_revision WHERE id = nullif(current_setting('app.session_id', true), '')::uuid;
  UPDATE public.password_resets SET used_at = now() WHERE user_id = changed_user AND used_at IS NULL;
  INSERT INTO public.account_events (user_id, organization_id, kind)
    VALUES (changed_user, nullif(current_setting('app.organization_id', true), '')::uuid, 'password_changed');
  RETURN true;
END $$;


--
-- Name: auth_clear_attempts(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_clear_attempts(requested_hash text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  DELETE FROM public.login_limits WHERE lookup_hash = requested_hash
$$;


--
-- Name: auth_complete_reset(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_complete_reset(requested_hash text, new_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE found_user uuid; reset_row public.password_resets%ROWTYPE; credential public.credentials%ROWTYPE;
BEGIN
  SELECT user_id INTO found_user FROM public.password_resets WHERE token_hash = requested_hash;
  IF found_user IS NULL THEN RETURN false; END IF;
  PERFORM 1 FROM public.users WHERE id = found_user AND active FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT * INTO credential FROM public.credentials WHERE user_id = found_user FOR UPDATE;
  SELECT * INTO reset_row FROM public.password_resets WHERE token_hash = requested_hash FOR UPDATE;
  IF reset_row.used_at IS NOT NULL OR reset_row.expires_at <= now() OR reset_row.credential_revision <> credential.revision THEN RETURN false; END IF;
  UPDATE public.credentials SET password_hash = new_hash, revision = revision + 1, updated_at = now() WHERE user_id = found_user;
  UPDATE public.users SET must_change_password = false, updated_at = now(), revision = revision + 1 WHERE id = found_user;
  UPDATE public.sessions SET revoked_at = now() WHERE user_id = found_user AND revoked_at IS NULL;
  UPDATE public.password_resets SET used_at = now() WHERE user_id = found_user AND used_at IS NULL;
  INSERT INTO public.account_events (user_id, kind) VALUES (found_user, 'password_reset');
  RETURN true;
END $$;


--
-- Name: auth_create_session(uuid, uuid, text, text, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_create_session(requested_user uuid, requested_organization uuid, expected_password text, expected_mfa_secret text, verified_step bigint, requested_token_hash text, requested_csrf_hash text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE credential public.credentials%ROWTYPE; mfa public.user_mfa%ROWTYPE; expiry timestamptz;
BEGIN
  PERFORM 1 FROM public.users WHERE id = requested_user AND active FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO credential FROM public.credentials WHERE user_id = requested_user FOR UPDATE;
  IF credential.password_hash IS DISTINCT FROM expected_password THEN RETURN NULL; END IF;
  PERFORM 1 FROM public.memberships m JOIN public.organizations o ON o.id = m.organization_id
    WHERE m.user_id = requested_user AND m.organization_id = requested_organization AND m.active AND o.active
    FOR SHARE OF m, o;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO mfa FROM public.user_mfa WHERE user_id = requested_user FOR UPDATE;
  IF coalesce(mfa.enabled, false) THEN
    IF mfa.encrypted_secret IS DISTINCT FROM expected_mfa_secret OR verified_step <= mfa.last_used_step
       OR verified_step NOT BETWEEN floor(extract(epoch FROM clock_timestamp()) / 30)::bigint - 1
                              AND floor(extract(epoch FROM clock_timestamp()) / 30)::bigint + 1 THEN
      RETURN NULL;
    END IF;
    UPDATE public.user_mfa SET last_used_step = verified_step WHERE user_id = requested_user;
  ELSIF expected_mfa_secret IS NOT NULL THEN RETURN NULL;
  END IF;
  UPDATE public.sessions SET revoked_at = now() WHERE id IN (
    SELECT id FROM public.sessions WHERE user_id = requested_user AND revoked_at IS NULL AND expires_at > now()
    ORDER BY created_at DESC, id OFFSET 4
  );
  expiry := now() + interval '12 hours';
  INSERT INTO public.sessions (organization_id, user_id, token_hash, csrf_hash, credential_revision, expires_at)
    VALUES (requested_organization, requested_user, requested_token_hash, requested_csrf_hash, credential.revision, expiry);
  INSERT INTO public.account_events (user_id, organization_id, kind) VALUES (requested_user, requested_organization, 'sign_in');
  RETURN expiry;
END $$;


--
-- Name: auth_disable_mfa(integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_disable_mfa(expected_revision integer, requested_change uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  own_session uuid := public.auth_mfa_locked_session();
  account_id uuid := nullif(current_setting('app.user_id', true), '')::uuid;
  mfa public.user_mfa%ROWTYPE;
  changed_revision integer;
BEGIN
  IF expected_revision IS NULL OR expected_revision < 0 OR requested_change IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO mfa FROM public.user_mfa m WHERE m.user_id = account_id;
  IF NOT mfa.enabled AND mfa.change_id = requested_change AND mfa.change_session_id = own_session THEN RETURN mfa.revision; END IF;
  IF coalesce(mfa.revision, 0) <> expected_revision THEN RETURN NULL; END IF;
  IF NOT coalesce(mfa.enabled, false) THEN RETURN coalesce(mfa.revision, 0); END IF;
  UPDATE public.user_mfa SET encrypted_secret = NULL, enabled = false, last_used_step = -1,
    revision = revision + 1, change_id = requested_change, change_session_id = own_session
    WHERE user_id = account_id RETURNING revision INTO changed_revision;
  DELETE FROM public.user_mfa_setups p USING public.sessions s WHERE s.id = p.session_id AND s.user_id = account_id;
  INSERT INTO public.account_events(user_id, organization_id, kind)
    VALUES (account_id, nullif(current_setting('app.organization_id', true), '')::uuid, 'mfa_disabled');
  RETURN changed_revision;
END $$;


--
-- Name: auth_enable_mfa(uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_enable_mfa(requested_id uuid, expected_secret text, verified_step bigint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  own_session uuid := public.auth_mfa_locked_session();
  account_id uuid := nullif(current_setting('app.user_id', true), '')::uuid;
  setup public.user_mfa_setups%ROWTYPE;
  mfa public.user_mfa%ROWTYPE;
  changed_revision integer;
BEGIN
  SELECT * INTO mfa FROM public.user_mfa m WHERE m.user_id = account_id;
  IF mfa.enabled AND mfa.change_id = requested_id AND mfa.change_session_id = own_session THEN RETURN mfa.revision; END IF;
  IF coalesce(mfa.enabled, false) THEN RETURN NULL; END IF;
  SELECT p.* INTO setup FROM public.user_mfa_setups p
    JOIN public.credentials c ON c.user_id = account_id AND c.revision = p.credential_revision
    WHERE p.session_id = own_session AND p.id = requested_id AND p.expires_at > clock_timestamp()
      AND p.mfa_revision = coalesce(mfa.revision, 0);
  IF NOT FOUND OR expected_secret IS NULL OR setup.encrypted_secret IS DISTINCT FROM expected_secret
    OR verified_step IS NULL OR verified_step NOT BETWEEN floor(extract(epoch FROM clock_timestamp()) / 30)::bigint - 1
      AND floor(extract(epoch FROM clock_timestamp()) / 30)::bigint + 1 THEN RETURN NULL; END IF;
  INSERT INTO public.user_mfa AS target(user_id, encrypted_secret, enabled, last_used_step, revision, change_id, change_session_id)
    VALUES (account_id, setup.encrypted_secret, true, verified_step, 1, requested_id, own_session)
    ON CONFLICT (user_id) DO UPDATE SET encrypted_secret = excluded.encrypted_secret, enabled = true,
      last_used_step = excluded.last_used_step, revision = target.revision + 1,
      change_id = excluded.change_id, change_session_id = excluded.change_session_id
    RETURNING revision INTO changed_revision;
  DELETE FROM public.user_mfa_setups p USING public.sessions s WHERE s.id = p.session_id AND s.user_id = account_id;
  INSERT INTO public.account_events(user_id, organization_id, kind)
    VALUES (account_id, nullif(current_setting('app.organization_id', true), '')::uuid, 'mfa_enabled');
  RETURN changed_revision;
END $$;


--
-- Name: auth_is_platform_administrator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_is_platform_administrator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.sessions session
    JOIN public.platform_administrators administrator ON administrator.organization_id=session.organization_id AND administrator.user_id=session.user_id
    JOIN public.users person ON person.id=session.user_id AND person.active AND NOT person.must_change_password
    JOIN public.credentials credential ON credential.user_id=person.id AND credential.revision=session.credential_revision
    JOIN public.memberships member ON member.organization_id=session.organization_id AND member.user_id=person.id AND member.active
    JOIN public.organizations organization ON organization.id=session.organization_id AND organization.active
    WHERE session.id=nullif(current_setting('app.session_id',true),'')::uuid
      AND session.user_id=nullif(current_setting('app.user_id',true),'')::uuid
      AND session.organization_id=nullif(current_setting('app.organization_id',true),'')::uuid
      AND session.revoked_at IS NULL AND session.expires_at>clock_timestamp()
  )
$$;


--
-- Name: auth_lock_login_aliases(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_lock_login_aliases(aliases text[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE alias text;
BEGIN
  IF aliases IS NULL OR array_ndims(aliases) IS DISTINCT FROM 1 OR cardinality(aliases) NOT BETWEEN 1 AND 2
    OR EXISTS (SELECT 1 FROM unnest(aliases) value WHERE value IS NULL OR length(trim(value)) NOT BETWEEN 1 AND 320) THEN
    RAISE EXCEPTION 'Invalid login aliases' USING ERRCODE='22023';
  END IF;
  FOR alias IN SELECT DISTINCT lower(trim(value)) FROM unnest(aliases) value ORDER BY 1 LOOP
    PERFORM pg_advisory_xact_lock(hashtext('sampleify_login_alias'),hashtext(alias));
  END LOOP;
END $$;


--
-- Name: auth_login_principals(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_login_principals(identifier text) RETURNS TABLE(user_id uuid, organization_id uuid, password_hash text, encrypted_secret text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT u.id, chosen.organization_id, c.password_hash, CASE WHEN mfa.enabled THEN mfa.encrypted_secret ELSE NULL END
  FROM public.users u
  JOIN public.credentials c ON c.user_id = u.id
  LEFT JOIN public.user_mfa mfa ON mfa.user_id = u.id
  LEFT JOIN LATERAL (
    SELECT m.organization_id FROM public.memberships m
    JOIN public.organizations o ON o.id = m.organization_id AND o.active
    WHERE m.user_id = u.id AND m.active
      AND (m.is_default OR 1 = (SELECT count(*) FROM public.memberships m2
        JOIN public.organizations o2 ON o2.id = m2.organization_id AND o2.active
        WHERE m2.user_id = u.id AND m2.active))
  ) chosen ON true
  WHERE u.active AND (lower(u.username) = lower(trim(identifier)) OR lower(u.email) = lower(trim(identifier)))
  ORDER BY u.id LIMIT 2
$$;


--
-- Name: auth_mfa_locked_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_mfa_locked_session() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  account_id uuid := nullif(current_setting('app.user_id', true), '')::uuid;
  account_organization uuid := nullif(current_setting('app.organization_id', true), '')::uuid;
  session_id uuid := nullif(current_setting('app.session_id', true), '')::uuid;
  account_credential_revision integer;
BEGIN
  -- Match sign-in/password-change lock order and revalidate after every wait.
  PERFORM 1 FROM public.users u WHERE u.id = account_id AND u.active FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'No active account' USING ERRCODE = '28000'; END IF;
  SELECT c.revision INTO account_credential_revision FROM public.credentials c WHERE c.user_id = account_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'No active credential' USING ERRCODE = '28000'; END IF;
  PERFORM 1 FROM public.memberships m JOIN public.organizations o ON o.id = m.organization_id
    WHERE m.user_id = account_id AND m.organization_id = account_organization AND m.active AND o.active FOR SHARE OF m, o;
  IF NOT FOUND THEN RAISE EXCEPTION 'No active membership' USING ERRCODE = '28000'; END IF;
  PERFORM 1 FROM public.sessions s WHERE s.id = session_id AND s.user_id = account_id
    AND s.organization_id = account_organization AND s.credential_revision = account_credential_revision
    AND s.revoked_at IS NULL AND s.expires_at > clock_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'No active session' USING ERRCODE = '28000'; END IF;
  RETURN session_id;
END $$;


--
-- Name: auth_mfa_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_mfa_state() RETURNS TABLE(enabled boolean, revision integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT coalesce(m.enabled, false), coalesce(m.revision, 0)
  FROM public.users u LEFT JOIN public.user_mfa m ON m.user_id = u.id
  WHERE u.id = nullif(current_setting('app.user_id', true), '')::uuid
$$;


--
-- Name: auth_own_credential(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_own_credential() RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT c.password_hash FROM public.credentials c
  WHERE c.user_id = nullif(current_setting('app.user_id', true), '')::uuid
$$;


--
-- Name: auth_read_mfa_setup(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_read_mfa_setup(requested_id uuid) RETURNS TABLE(encrypted_secret text, completed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  own_session uuid := public.auth_mfa_locked_session();
  account_id uuid := nullif(current_setting('app.user_id', true), '')::uuid;
BEGIN
  IF EXISTS (SELECT 1 FROM public.user_mfa m WHERE m.user_id = account_id AND m.enabled
    AND m.change_id = requested_id AND m.change_session_id = own_session) THEN
    RETURN QUERY SELECT NULL::text, true;
    RETURN;
  END IF;
  RETURN QUERY SELECT p.encrypted_secret, false FROM public.user_mfa_setups p
    JOIN public.sessions s ON s.id = p.session_id
    JOIN public.credentials c ON c.user_id = s.user_id AND c.revision = p.credential_revision
    LEFT JOIN public.user_mfa m ON m.user_id = s.user_id
    WHERE p.session_id = own_session AND p.id = requested_id AND p.expires_at > clock_timestamp()
      AND NOT coalesce(m.enabled, false) AND p.mfa_revision = coalesce(m.revision, 0);
END $$;


--
-- Name: auth_request_reset(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_request_reset(requested_email text, requested_hash text) RETURNS TABLE(request_id uuid, recipient text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE found_user uuid; found_revision integer; new_id uuid;
BEGIN
  IF (SELECT count(*) FROM public.users WHERE lower(email) = lower(trim(requested_email)) AND active) <> 1 THEN RETURN; END IF;
  SELECT id INTO found_user FROM public.users WHERE lower(email) = lower(trim(requested_email)) AND active FOR UPDATE;
  SELECT revision INTO found_revision FROM public.credentials WHERE user_id = found_user FOR UPDATE;
  IF found_revision IS NULL THEN RETURN; END IF;
  UPDATE public.password_resets SET used_at = now() WHERE user_id = found_user AND used_at IS NULL;
  INSERT INTO public.password_resets (user_id, token_hash, credential_revision, expires_at)
    VALUES (found_user, requested_hash, found_revision, now() + interval '30 minutes') RETURNING id INTO new_id;
  RETURN QUERY SELECT new_id, u.email FROM public.users u WHERE u.id = found_user;
END $$;


--
-- Name: auth_reserve_attempt(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_reserve_attempt(requested_hash text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  INSERT INTO public.login_limits AS limits (lookup_hash, attempts)
  VALUES (requested_hash, 1)
  ON CONFLICT (lookup_hash) DO UPDATE SET
    attempts = CASE WHEN limits.window_started_at <= now() - interval '15 minutes' THEN 1 ELSE least(limits.attempts + 1, 6) END,
    window_started_at = CASE WHEN limits.window_started_at <= now() - interval '15 minutes' THEN now() ELSE limits.window_started_at END
  RETURNING attempts <= 5
$$;


--
-- Name: auth_revoke_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_revoke_session() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE affected public.sessions%ROWTYPE;
BEGIN
  UPDATE public.sessions SET revoked_at = now()
    WHERE id = nullif(current_setting('app.session_id', true), '')::uuid AND revoked_at IS NULL
    RETURNING * INTO affected;
  IF FOUND THEN INSERT INTO public.account_events (user_id, organization_id, kind)
    VALUES (affected.user_id, affected.organization_id, 'sign_out'); END IF;
END $$;


--
-- Name: auth_session_context(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_session_context(requested_hash text) RETURNS TABLE(session_id uuid, user_id uuid, organization_id uuid, csrf_hash text, username text, email text, display_name text, organization_name text, must_change_password boolean, revision integer, mfa_enabled boolean, role_names text[], role_ids uuid[], permission_codes text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE found_user uuid; found_organization uuid;
BEGIN
  PERFORM set_config('app.user_id', '', true);
  PERFORM set_config('app.organization_id', '', true);
  PERFORM set_config('app.session_id', '', true);
  SELECT s.user_id, s.organization_id INTO found_user, found_organization
  FROM public.sessions s
  JOIN public.users u ON u.id = s.user_id AND u.active
  JOIN public.credentials c ON c.user_id = u.id AND c.revision = s.credential_revision
  JOIN public.memberships m ON m.organization_id = s.organization_id AND m.user_id = s.user_id AND m.active
  JOIN public.organizations o ON o.id = s.organization_id AND o.active
  WHERE s.token_hash = requested_hash AND s.revoked_at IS NULL AND s.expires_at > now();
  IF found_user IS NULL THEN RETURN; END IF;
  PERFORM set_config('app.user_id', found_user::text, true);
  PERFORM set_config('app.organization_id', found_organization::text, true);
  PERFORM set_config('app.session_id', (SELECT s.id::text FROM public.sessions s WHERE s.token_hash = requested_hash), true);
  RETURN QUERY SELECT s.id, u.id, o.id, s.csrf_hash, u.username, u.email, u.display_name, o.name,
    u.must_change_password, u.revision, coalesce(mfa.enabled, false),
    ARRAY(SELECT r.name FROM public.membership_roles mr JOIN public.roles r
      ON r.organization_id = mr.organization_id AND r.id = mr.role_id AND r.active
      WHERE mr.organization_id = o.id AND mr.user_id = u.id ORDER BY r.name),
    ARRAY(SELECT r.id FROM public.membership_roles mr JOIN public.roles r
      ON r.organization_id = mr.organization_id AND r.id = mr.role_id AND r.active
      WHERE mr.organization_id = o.id AND mr.user_id = u.id ORDER BY r.name),
    ARRAY(SELECT DISTINCT rp.permission_code FROM public.membership_roles mr JOIN public.role_permissions rp
      ON rp.organization_id = mr.organization_id AND rp.role_id = mr.role_id
      JOIN public.roles role ON role.organization_id=mr.organization_id AND role.id=mr.role_id AND role.active
      WHERE mr.organization_id = o.id AND mr.user_id = u.id ORDER BY rp.permission_code)
  FROM public.sessions s JOIN public.users u ON u.id = s.user_id
  JOIN public.organizations o ON o.id = s.organization_id
  LEFT JOIN public.user_mfa mfa ON mfa.user_id = u.id
  WHERE s.token_hash = requested_hash;
END $$;


--
-- Name: auth_start_mfa_setup(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_start_mfa_setup(candidate_secret text) RETURNS TABLE(id uuid, encrypted_secret text, expires_at timestamp with time zone, mfa_revision integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  own_session uuid := public.auth_mfa_locked_session();
  account_id uuid := nullif(current_setting('app.user_id', true), '')::uuid;
  current_revision integer;
  account_credential_revision integer;
  started_at timestamptz;
  expiry timestamptz;
BEGIN
  IF candidate_secret IS NULL OR candidate_secret !~ '^[A-Za-z0-9_-]{60,220}$' THEN
    RAISE EXCEPTION 'Invalid encrypted setup' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.user_mfa m WHERE m.user_id = account_id AND m.enabled) THEN RETURN; END IF;
  current_revision := coalesce((SELECT m.revision FROM public.user_mfa m WHERE m.user_id = account_id), 0);
  SELECT c.revision INTO account_credential_revision FROM public.credentials c WHERE c.user_id = account_id;
  DELETE FROM public.user_mfa_setups p USING public.sessions s WHERE s.id = p.session_id AND s.user_id = account_id
    AND (p.expires_at <= clock_timestamp() OR p.credential_revision <> account_credential_revision
      OR p.mfa_revision <> current_revision OR s.revoked_at IS NOT NULL OR s.expires_at <= clock_timestamp());
  IF NOT EXISTS (SELECT 1 FROM public.user_mfa_setups p WHERE p.session_id = own_session) THEN
    started_at := clock_timestamp();
    SELECT least(s.expires_at, started_at + interval '10 minutes') INTO expiry FROM public.sessions s WHERE s.id = own_session;
    IF expiry <= started_at THEN RAISE EXCEPTION 'No active session' USING ERRCODE = '28000'; END IF;
    INSERT INTO public.user_mfa_setups(session_id, encrypted_secret, credential_revision, mfa_revision, created_at, expires_at)
      VALUES (own_session, candidate_secret, account_credential_revision, current_revision, started_at, expiry);
  END IF;
  RETURN QUERY SELECT p.id, p.encrypted_secret, p.expires_at, p.mfa_revision
    FROM public.user_mfa_setups p WHERE p.session_id = own_session;
END $_$;


--
-- Name: auth_update_profile(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_update_profile(requested_name text, requested_username text, expected_revision integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE changed_user uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
BEGIN
  PERFORM public.auth_mfa_locked_session();
  PERFORM public.auth_lock_login_aliases(ARRAY[requested_username]);
  PERFORM public.auth_mfa_locked_session();
  IF EXISTS (SELECT 1 FROM public.users WHERE id<>changed_user AND lower(email)=lower(trim(requested_username))) THEN
    RAISE EXCEPTION 'Username conflicts with an existing sign-in identifier' USING ERRCODE='23505';
  END IF;
  UPDATE public.users SET display_name=trim(requested_name),username=trim(requested_username),revision=revision+1,updated_at=now()
    WHERE id=changed_user AND revision=expected_revision AND active;
  IF NOT FOUND THEN RETURN false; END IF;
  INSERT INTO public.account_events(user_id,organization_id,kind)
    VALUES(changed_user,nullif(current_setting('app.organization_id',true),'')::uuid,'profile_changed');
  RETURN true;
END $$;


--
-- Name: checklists_assert_version(uuid, uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checklists_assert_version(org uuid, target uuid, target_revision integer, check_head boolean) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.checklist_versions; head public.checklists;
BEGIN
  SELECT * INTO version FROM public.checklist_versions WHERE organization_id=org AND checklist_id=target AND revision=target_revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'Checklist version is missing' USING ERRCODE='23514'; END IF;
  IF version.item_count<>(SELECT count(*) FROM public.checklist_version_items WHERE organization_id=org AND checklist_id=target AND revision=target_revision) THEN
    RAISE EXCEPTION 'Checklist history requires all its ordered items' USING ERRCODE='23514';
  END IF;
  IF check_head THEN
    SELECT * INTO head FROM public.checklists WHERE organization_id=org AND id=target;
    IF (head.revision,head.name,head.is_active,head.retired_at,head.updated_by,head.updated_at)
      IS DISTINCT FROM (version.revision,version.name,version.is_active,version.retired_at,version.saved_by,version.saved_at)
      OR EXISTS (
        (SELECT id,prompt,display_order FROM public.checklist_items WHERE organization_id=org AND checklist_id=target
          EXCEPT ALL SELECT id,prompt,display_order FROM public.checklist_version_items WHERE organization_id=org AND checklist_id=target AND revision=target_revision)
        UNION ALL
        (SELECT id,prompt,display_order FROM public.checklist_version_items WHERE organization_id=org AND checklist_id=target AND revision=target_revision
          EXCEPT ALL SELECT id,prompt,display_order FROM public.checklist_items WHERE organization_id=org AND checklist_id=target)
      ) THEN
      RAISE EXCEPTION 'Current checklist must match its complete saved version' USING ERRCODE='23514';
    END IF;
  END IF;
END $$;


--
-- Name: checklists_check_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checklists_check_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE head public.checklists; org uuid; target uuid;
BEGIN
  org:=CASE WHEN TG_OP='DELETE' THEN OLD.organization_id ELSE NEW.organization_id END;
  IF TG_TABLE_NAME='checklists' THEN target:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;
  ELSE target:=NEW.checklist_id; END IF;
  SELECT * INTO head FROM public.checklists WHERE organization_id=org AND id=target;
  IF TG_TABLE_NAME='checklist_versions' THEN
    PERFORM public.checklists_assert_version(org,target,NEW.revision,head.revision=NEW.revision);
  ELSIF head.revision>0 THEN
    PERFORM public.checklists_assert_version(org,target,head.revision,true);
  END IF;
  RETURN NULL;
END $$;


--
-- Name: checklists_guard_head(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checklists_guard_head() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    IF OLD.revision>0 THEN RAISE EXCEPTION 'Saved checklists cannot be deleted' USING ERRCODE='55000'; END IF;
    RETURN OLD;
  END IF;
  IF (NEW.organization_id,NEW.id,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.organization_id,OLD.id,OLD.created_by,OLD.created_at)
    OR NEW.revision<>OLD.revision+1 OR OLD.retired_at IS NOT NULL THEN
    RAISE EXCEPTION 'Checklist identity, creation evidence and sequential revision are immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: checklists_guard_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checklists_guard_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.checklist_versions; head public.checklists;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Checklist history is immutable' USING ERRCODE='55000'; END IF;
  IF TG_TABLE_NAME='checklist_versions' THEN
    SELECT * INTO head FROM public.checklists WHERE organization_id=NEW.organization_id AND id=NEW.checklist_id;
    IF NEW.saved_by IS DISTINCT FROM public.checklists_require_actor()
      OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
      OR NEW.created_transaction_id<>pg_current_xact_id() OR NEW.saved_at<>transaction_timestamp()
      OR (NEW.revision,NEW.name,NEW.is_active,NEW.retired_at,NEW.saved_by,NEW.saved_at)
        IS DISTINCT FROM (head.revision,head.name,head.is_active,head.retired_at,head.updated_by,head.updated_at)
      OR (NEW.operation='create' AND (head.created_by,head.created_at) IS DISTINCT FROM (NEW.saved_by,NEW.saved_at))
      OR (NEW.operation='retire' AND NEW.retired_at IS DISTINCT FROM NEW.saved_at) THEN
      RAISE EXCEPTION 'Checklist history requires the actual current head, editor and transaction' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO version FROM public.checklist_versions WHERE organization_id=NEW.organization_id AND checklist_id=NEW.checklist_id AND revision=NEW.revision;
    IF version.checklist_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
      OR version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
      OR version.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid THEN
      RAISE EXCEPTION 'Checklist items require their actual version transaction' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: checklists_guard_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checklists_guard_items() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE head public.checklists; version public.checklist_versions; org uuid; target uuid;
BEGIN
  IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'Replace checklist items through a saved revision' USING ERRCODE='23514'; END IF;
  org:=CASE WHEN TG_OP='DELETE' THEN OLD.organization_id ELSE NEW.organization_id END;
  target:=CASE WHEN TG_OP='DELETE' THEN OLD.checklist_id ELSE NEW.checklist_id END;
  SELECT * INTO head FROM public.checklists WHERE organization_id=org AND id=target;
  IF head.revision>0 THEN
    SELECT * INTO version FROM public.checklist_versions WHERE organization_id=org AND checklist_id=target AND revision=head.revision;
    IF version.checklist_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
      OR version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
      OR org IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid THEN
      RAISE EXCEPTION 'Checklist items require their current saved revision transaction' USING ERRCODE='23514';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: checklists_guard_retirement(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checklists_guard_retirement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF OLD.retired_at IS NULL AND NEW.retired_at IS NOT NULL AND EXISTS
    (SELECT 1 FROM public.workflow_transitions WHERE organization_id=NEW.organization_id AND checklist_master_id=NEW.id) THEN
    RAISE EXCEPTION 'Checklist is referenced by a workflow' USING ERRCODE='23514',CONSTRAINT='checklist_in_use';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: checklists_require_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checklists_require_actor() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.sessions session
    JOIN public.users person ON person.id=session.user_id AND person.active AND NOT person.must_change_password
    JOIN public.credentials credential ON credential.user_id=person.id AND credential.revision=session.credential_revision
    JOIN public.memberships membership ON membership.organization_id=session.organization_id AND membership.user_id=person.id AND membership.active
    JOIN public.organizations organization ON organization.id=session.organization_id AND organization.active
    WHERE session.id=nullif(current_setting('app.session_id',true),'')::uuid AND session.user_id=actor AND session.organization_id=org
      AND session.revoked_at IS NULL AND session.expires_at>clock_timestamp()
  ) OR NOT public.app_has_permission('checklists.manage') THEN
    RAISE EXCEPTION 'Active checklist management session required' USING ERRCODE='42501',CONSTRAINT='checklist_session_required';
  END IF;
  RETURN actor;
END $$;


--
-- Name: checklists_write(text, uuid, integer, uuid, text, boolean, uuid[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checklists_write(operation text, target uuid, expected_revision integer, requested_id uuid, requested_name text, requested_active boolean, requested_item_ids uuid[], requested_prompts text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid; org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  head public.checklists; prior public.checklist_versions; next_revision integer;
  next_name text; next_active boolean; next_retired_at timestamptz; next_item_ids uuid[]; next_prompts text[]; next_orders integer[];
BEGIN
  actor:=public.checklists_require_actor();
  PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
  actor:=public.checklists_require_actor();
  IF operation IS NULL OR operation NOT IN ('create','update','retire') OR target IS NULL OR requested_id IS NULL
    OR expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 2147483646
    OR (operation='create' AND (expected_revision<>0 OR requested_name IS NULL OR requested_item_ids IS NULL))
    OR (operation='retire' AND num_nonnulls(requested_name,requested_active,requested_item_ids,requested_prompts)<>0)
    OR (requested_name IS NOT NULL AND (length(trim(requested_name)) NOT BETWEEN 1 AND 200 OR requested_name<>trim(requested_name)))
    OR ((requested_item_ids IS NULL)<>(requested_prompts IS NULL))
    OR (requested_item_ids IS NOT NULL AND (coalesce(array_ndims(requested_item_ids),1)<>1 OR array_lower(requested_item_ids,1)<>1
      OR cardinality(requested_item_ids) NOT BETWEEN 1 AND 200 OR cardinality(requested_item_ids)<>(SELECT count(DISTINCT item) FROM unnest(requested_item_ids) item)
      OR coalesce(array_ndims(requested_prompts),1)<>1 OR array_lower(requested_prompts,1)<>1
      OR cardinality(requested_prompts)<>cardinality(requested_item_ids)
      OR cardinality(requested_prompts)<>(SELECT count(DISTINCT item) FROM unnest(requested_prompts) item)
      OR EXISTS (SELECT 1 FROM unnest(requested_prompts) item WHERE item IS NULL OR length(trim(item)) NOT BETWEEN 1 AND 500 OR item<>trim(item)))) THEN
    RAISE EXCEPTION 'Invalid checklist command' USING ERRCODE='23514',CONSTRAINT='checklist_invalid_input';
  END IF;
  SELECT * INTO prior FROM public.checklist_versions WHERE organization_id=org AND request_id=requested_id;
  IF FOUND THEN
    IF prior.checklist_id<>target OR prior.operation<>operation OR coalesce(prior.previous_revision,0)<>expected_revision OR prior.saved_by<>actor
      OR prior.name_provided<>(requested_name IS NOT NULL) OR prior.active_provided<>(requested_active IS NOT NULL) OR prior.items_provided<>(requested_item_ids IS NOT NULL)
      OR (requested_name IS NOT NULL AND prior.name IS DISTINCT FROM requested_name)
      OR (requested_active IS NOT NULL AND prior.is_active IS DISTINCT FROM requested_active)
      OR (requested_item_ids IS NOT NULL AND (requested_item_ids IS DISTINCT FROM ARRAY(SELECT id FROM public.checklist_version_items
        WHERE organization_id=org AND checklist_id=target AND revision=prior.revision ORDER BY display_order)
        OR requested_prompts IS DISTINCT FROM ARRAY(SELECT prompt FROM public.checklist_version_items
          WHERE organization_id=org AND checklist_id=target AND revision=prior.revision ORDER BY display_order))) THEN
      RAISE EXCEPTION 'Checklist request was used for a different change' USING ERRCODE='23514',CONSTRAINT='checklist_request_reused';
    END IF;
    RETURN prior.revision;
  END IF;
  SELECT * INTO head FROM public.checklists WHERE organization_id=org AND id=target FOR UPDATE;
  IF operation='create' AND FOUND THEN RAISE EXCEPTION 'Checklist already exists' USING ERRCODE='23514',CONSTRAINT='checklist_identifier_exists'; END IF;
  IF operation<>'create' AND (head.id IS NULL OR head.retired_at IS NOT NULL) THEN
    RAISE EXCEPTION 'Checklist was not found' USING ERRCODE='P0002',CONSTRAINT='checklist_not_found';
  END IF;
  IF operation<>'create' AND head.revision<>expected_revision THEN
    RAISE EXCEPTION 'Checklist changed; reload before saving' USING ERRCODE='23514',CONSTRAINT='checklist_stale';
  END IF;
  next_name:=coalesce(requested_name,head.name); next_active:=coalesce(requested_active,head.is_active,true);
  IF operation<>'retire' AND (operation='create' OR next_name IS DISTINCT FROM head.name)
    AND EXISTS (SELECT 1 FROM public.checklists WHERE organization_id=org AND id<>target AND retired_at IS NULL AND name=next_name) THEN
    RAISE EXCEPTION 'Checklist name already exists' USING ERRCODE='23514',CONSTRAINT='checklist_name_conflict';
  END IF;
  IF head.revision>0 THEN PERFORM public.checklists_assert_version(org,target,head.revision,true); END IF;
  next_revision:=expected_revision+1;
  next_retired_at:=CASE WHEN operation='retire' THEN transaction_timestamp() ELSE NULL END;
  IF requested_item_ids IS NULL THEN
    SELECT coalesce(array_agg(id ORDER BY display_order),'{}'::uuid[]),coalesce(array_agg(prompt ORDER BY display_order),'{}'::text[]),
      coalesce(array_agg(display_order ORDER BY display_order),'{}'::integer[]) INTO next_item_ids,next_prompts,next_orders
      FROM public.checklist_items WHERE organization_id=org AND checklist_id=target;
  ELSE
    next_item_ids:=requested_item_ids; next_prompts:=requested_prompts;
    next_orders:=ARRAY(SELECT generate_series(0,cardinality(next_item_ids)-1));
  END IF;
  IF operation='create' THEN
    INSERT INTO public.checklists(organization_id,id,name,is_active,revision,created_by,created_at,updated_by,updated_at)
      VALUES(org,target,next_name,next_active,next_revision,actor,transaction_timestamp(),actor,transaction_timestamp());
  ELSE
    UPDATE public.checklists SET name=next_name,is_active=next_active,revision=next_revision,updated_by=actor,updated_at=transaction_timestamp(),retired_at=next_retired_at
      WHERE organization_id=org AND id=target;
  END IF;
  INSERT INTO public.checklist_versions(organization_id,checklist_id,revision,request_id,previous_revision,operation,name,is_active,retired_at,item_count,
    name_provided,active_provided,items_provided,saved_by)
    VALUES(org,target,next_revision,requested_id,CASE WHEN operation='create' THEN NULL ELSE expected_revision END,operation,next_name,next_active,next_retired_at,
      cardinality(next_item_ids),requested_name IS NOT NULL,requested_active IS NOT NULL,requested_item_ids IS NOT NULL,actor);
  INSERT INTO public.checklist_version_items(organization_id,checklist_id,revision,id,prompt,display_order)
    SELECT org,target,next_revision,item.id,item.prompt,item.position FROM unnest(next_item_ids,next_prompts,next_orders) item(id,prompt,position);
  DELETE FROM public.checklist_items WHERE organization_id=org AND checklist_id=target;
  INSERT INTO public.checklist_items(organization_id,checklist_id,id,prompt,display_order)
    SELECT org,target,item.id,item.prompt,item.position FROM unnest(next_item_ids,next_prompts,next_orders) item(id,prompt,position);
  RETURN next_revision;
END $$;


--
-- Name: custom_field_guard_attachment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_field_guard_attachment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE definition public.custom_field_definitions;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Custom Field attachment bytes are immutable' USING ERRCODE='55000'; END IF;
  IF session_user='sampleify_app' AND current_user='sampleify_app' AND (
    NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR NEW.uploaded_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
    OR NEW.uploaded_at IS DISTINCT FROM transaction_timestamp() OR NOT public.app_has_permission('masters.manage')
  ) THEN RAISE EXCEPTION 'Attachment upload requires its actual tenant, actor and time' USING ERRCODE='42501'; END IF;
  -- The owner-only users command holds the shared definition advisory before account rows.
  -- A raw definition UPDATE can already hold its row while waiting on that advisory.
  SELECT * INTO definition FROM public.custom_field_definitions WHERE organization_id=NEW.organization_id AND id=NEW.field_id;
  IF definition.associated_with NOT IN ('users','instrument') THEN
    SELECT * INTO definition FROM public.custom_field_definitions WHERE organization_id=NEW.organization_id AND id=NEW.field_id FOR SHARE;
  END IF;
  IF definition.id IS NULL OR NOT definition.active OR definition.field_type<>'attachment'
    OR definition.associated_with NOT IN ('product','parameter','method_of_analysis','users','customer','vendor','instrument') OR definition.revision<>NEW.field_revision THEN
    RAISE EXCEPTION 'Attachment upload requires a current active supported field' USING ERRCODE='23514',CONSTRAINT='custom_field_attachment_current_definition';
  END IF;
  IF definition.associated_with IN ('customer','vendor') THEN
    IF current_user='sampleify_app' THEN RAISE EXCEPTION 'Party master attachments require their upload command' USING ERRCODE='42501'; END IF;
    IF definition.associated_with='customer' THEN PERFORM public.masters_require_customer_write();
    ELSE PERFORM public.masters_require_vendor_write(); END IF;
    IF NEW.organization_id IS DISTINCT FROM public.organization_module_scope()
      OR NEW.uploaded_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid OR NEW.uploaded_at IS DISTINCT FROM transaction_timestamp() THEN
      RAISE EXCEPTION 'Party master attachments require the actual organization, editor and transaction' USING ERRCODE='42501';
    END IF;
  ELSIF definition.associated_with='instrument' THEN
    IF current_user='sampleify_app' THEN RAISE EXCEPTION 'Instrument attachments require their upload command' USING ERRCODE='42501'; END IF;
    IF NEW.uploaded_by IS DISTINCT FROM public.instruments_require_writer()
      OR NEW.organization_id IS DISTINCT FROM public.organization_module_scope()
      OR NEW.uploaded_at IS DISTINCT FROM transaction_timestamp() THEN
      RAISE EXCEPTION 'Instrument attachment requires the actual tenant, editor and transaction time' USING ERRCODE='42501';
    END IF;
  ELSIF definition.associated_with='users' THEN
    IF current_user='sampleify_app' THEN RAISE EXCEPTION 'User attachments require their upload command' USING ERRCODE='42501'; END IF;
    IF NEW.uploaded_by IS DISTINCT FROM public.users_require_manager()
      OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
      OR NEW.uploaded_at IS DISTINCT FROM transaction_timestamp() THEN
      RAISE EXCEPTION 'User attachment requires the actual tenant, editor and transaction time' USING ERRCODE='42501';
    END IF;
  ELSIF session_user='sampleify_app' AND (
    NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR NEW.uploaded_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
    OR NEW.uploaded_at IS DISTINCT FROM transaction_timestamp() OR NOT public.app_has_permission('masters.manage')
  ) THEN RAISE EXCEPTION 'Attachment upload requires its actual tenant, actor and time' USING ERRCODE='42501'; END IF;
  RETURN NEW;
END $$;


--
-- Name: dynamic_api_authenticate(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dynamic_api_authenticate(p_token_hash text) RETURNS TABLE(organization_id uuid, api_id uuid, url_key text, http_method text, live_code text, enabled boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE token public.dynamic_api_tokens;
BEGIN
  SELECT * INTO token FROM public.dynamic_api_tokens WHERE token_hash=p_token_hash AND revoked_at IS NULL;
  IF NOT FOUND THEN RETURN; END IF;
  -- Bare "organization_id" here is ambiguous: the RETURNS TABLE's own
  -- organization_id OUT parameter is in scope as a PL/pgSQL variable for the
  -- whole function body, colliding with the table column of the same name
  -- (42702) unless the table is qualified via its alias.
  UPDATE public.dynamic_api_tokens t SET last_used_at=now() WHERE t.organization_id=token.organization_id AND t.id=token.id;
  RETURN QUERY SELECT api.organization_id, api.id, api.url_key, api.http_method, api.live_code, api.enabled
    FROM public.dynamic_apis api WHERE api.organization_id=token.organization_id AND api.id=token.api_id;
END $$;


--
-- Name: dynamic_api_list_customers(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dynamic_api_list_customers(p_organization_id uuid, p_search text, p_limit integer) RETURNS TABLE(id uuid, code text, name text, active boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT id, code, name, active FROM public.customers
  WHERE organization_id=p_organization_id AND (p_search IS NULL OR name ILIKE '%'||replace(replace(p_search,'\','\\'),'%','\%')||'%' ESCAPE '\')
  ORDER BY name LIMIT LEAST(coalesce(p_limit,20),200)
$$;


