$$;


--
-- Name: laboratory_capture_can_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_capture_can_write() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  capture_id uuid:=nullif(current_setting('app.capture_id',true),'')::uuid;
  capture public.template_instances; sheet public.datasheets;
BEGIN
  IF org IS NULL OR actor IS NULL OR capture_id IS NULL THEN RETURN false; END IF;
  SELECT * INTO capture FROM public.template_instances WHERE organization_id=org AND id=capture_id;
  IF capture.id IS NULL OR capture.status<>'editing' THEN RETURN false; END IF;
  SELECT * INTO sheet FROM public.datasheets WHERE organization_id=org AND template_instance_id=capture_id;
  IF sheet.id IS NOT NULL THEN
    RETURN sheet.status IN ('in_progress','rejected') AND public.laboratory_request_can_work(sheet.test_request_id);
  END IF;
  RETURN capture.created_by=actor AND (public.app_has_permission('datasheets.execute')
    OR (capture.revision=1 AND (public.app_has_permission('test_requests.allocate') OR public.app_has_permission('samples.manage'))));
END $$;


--
-- Name: laboratory_complete_auto_job_capture(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_complete_auto_job_capture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF session_user='sampleify_app' AND NOT (public.app_has_permission('datasheets.execute') OR public.app_has_permission('test_requests.allocate') OR public.app_has_permission('samples.manage'))
    AND EXISTS (SELECT 1 FROM public.template_versions WHERE organization_id=NEW.organization_id AND id=NEW.version_id AND kind='datasheet')
    AND NOT EXISTS (SELECT 1 FROM public.datasheets sheet JOIN public.test_requests member ON member.organization_id=sheet.organization_id AND member.id=sheet.test_request_id
      JOIN public.test_requests job ON job.organization_id=member.organization_id AND job.id=member.parent_test_request_id
      WHERE sheet.organization_id=NEW.organization_id AND sheet.template_instance_id=NEW.id AND sheet.created_by=NEW.created_by AND sheet.created_at=NEW.created_at
        AND job.is_job AND job.is_auto_created AND job.created_at=transaction_timestamp() AND public.laboratory_new_generated_request(member.id))
  THEN RAISE EXCEPTION 'Automatic initialization must remain bound to its actual new child' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END $$;


--
-- Name: laboratory_complete_capture_subjects(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_complete_capture_subjects() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE sheet public.datasheets; owner public.test_requests; allowed_subjects uuid[]; inconsistent boolean;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.template_repeat_groups WHERE organization_id=NEW.organization_id AND version_id=NEW.version_id AND source='test_requests') THEN RETURN NEW; END IF;
  SELECT * INTO sheet FROM public.datasheets WHERE organization_id=NEW.organization_id AND template_instance_id=NEW.id;
  SELECT * INTO owner FROM public.test_requests WHERE organization_id=NEW.organization_id AND id=sheet.test_request_id;
  IF sheet.id IS NULL THEN RAISE EXCEPTION 'Parameter loops require a real datasheet owner' USING ERRCODE='23514'; END IF;
  IF owner.is_job THEN
    SELECT array_agg(id ORDER BY job_member_position) INTO allowed_subjects FROM public.test_requests WHERE organization_id=NEW.organization_id AND parent_test_request_id=owner.id;
  ELSE allowed_subjects:=ARRAY[owner.id]; END IF;
  IF coalesce(cardinality(allowed_subjects),0)=0 THEN RAISE EXCEPTION 'Parameter loops require at least one request subject' USING ERRCODE='23514'; END IF;
  WITH RECURSIVE active_occurrences AS MATERIALIZED (
    SELECT occurrence.id,occurrence.parent_id,occurrence.group_id,binding.test_request_id AS own_subject
    FROM public.template_occurrences occurrence LEFT JOIN public.datasheet_subjects binding
      ON binding.organization_id=occurrence.organization_id AND binding.instance_id=occurrence.instance_id AND binding.occurrence_id=occurrence.id
    WHERE occurrence.organization_id=NEW.organization_id AND occurrence.instance_id=NEW.id AND occurrence.removed_revision IS NULL
  ), ancestry AS (
    SELECT id,parent_id,group_id,own_subject AS subject FROM active_occurrences WHERE group_id IS NULL
    UNION ALL SELECT child.id,child.parent_id,child.group_id,coalesce(child.own_subject,parent.subject)
      FROM active_occurrences child JOIN ancestry parent ON parent.id=child.parent_id
  ), counts AS (
    SELECT child.parent_id,child.group_id,count(*) AS total,
      bool_and(CASE WHEN parent.subject IS NULL THEN child.subject=ANY(allowed_subjects) ELSE child.subject=parent.subject END) AS valid
      FROM ancestry child JOIN ancestry parent ON parent.id=child.parent_id GROUP BY child.parent_id,child.group_id
  ) SELECT EXISTS(SELECT 1 FROM ancestry parent JOIN public.template_repeat_groups definition
      ON definition.organization_id=NEW.organization_id AND definition.version_id=NEW.version_id AND definition.source='test_requests'
        AND definition.parent_group_id IS NOT DISTINCT FROM parent.group_id
      LEFT JOIN counts ON counts.parent_id=parent.id AND counts.group_id=definition.id
      WHERE coalesce(counts.total,0)<>CASE WHEN parent.subject IS NULL THEN cardinality(allowed_subjects) ELSE 1 END OR counts.valid IS DISTINCT FROM true)
    INTO inconsistent;
  IF inconsistent THEN RAISE EXCEPTION 'Parameter loops must contain their exact request subjects' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_complete_group_capture(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_complete_group_capture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.status='frozen' AND OLD.status='editing' AND EXISTS (
    SELECT 1 FROM public.datasheets child_sheet JOIN public.test_requests child ON child.organization_id=child_sheet.organization_id AND child.id=child_sheet.test_request_id
      JOIN public.datasheets parent_sheet ON parent_sheet.organization_id=child.organization_id AND parent_sheet.test_request_id=child.parent_test_request_id
      JOIN public.datasheet_submissions parent ON parent.organization_id=parent_sheet.organization_id AND parent.datasheet_id=parent_sheet.id AND parent.xmin::text=pg_current_xact_id()::text
      WHERE child_sheet.organization_id=NEW.organization_id AND child_sheet.template_instance_id=NEW.id
        AND NOT EXISTS (SELECT 1 FROM public.job_submission_members member JOIN public.datasheet_submissions submission
          ON submission.organization_id=member.organization_id AND submission.id=member.submission_id
          WHERE member.organization_id=NEW.organization_id AND member.parent_submission_id=parent.id AND submission.instance_id=NEW.id AND submission.capture_revision=NEW.revision)
  ) THEN RAISE EXCEPTION 'A grouped capture freeze requires its actual covered submission' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END $$;


--
-- Name: laboratory_complete_group_submission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_complete_group_submission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE job_id uuid;
BEGIN
  SELECT job.id INTO job_id FROM public.datasheets sheet JOIN public.test_requests job ON job.organization_id=sheet.organization_id AND job.id=sheet.test_request_id AND job.is_job
    WHERE sheet.organization_id=NEW.organization_id AND sheet.id=NEW.datasheet_id;
  IF job_id IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM public.test_requests WHERE organization_id=NEW.organization_id AND parent_test_request_id=job_id)
    OR EXISTS (SELECT 1 FROM public.test_requests child WHERE child.organization_id=NEW.organization_id AND child.parent_test_request_id=job_id
      AND NOT EXISTS (SELECT 1 FROM public.job_submission_members WHERE organization_id=NEW.organization_id AND parent_submission_id=NEW.id AND test_request_id=child.id))) THEN
    RAISE EXCEPTION 'Every job child needs an explicit submitted result in the same transaction' USING ERRCODE='23514';
  END IF;
  IF NEW.source='result_widget' AND NOT EXISTS (SELECT 1 FROM public.job_submission_members member JOIN public.datasheet_submissions parent
      ON parent.organization_id=member.organization_id AND parent.id=member.parent_submission_id
      WHERE member.organization_id=NEW.organization_id AND member.submission_id=NEW.id AND parent.datasheet_id=NEW.source_datasheet_id
        AND parent.instance_id=NEW.instance_id AND parent.capture_revision=NEW.capture_revision AND parent.submitted_by=NEW.submitted_by AND parent.submitted_at=NEW.submitted_at) THEN
    RAISE EXCEPTION 'A summary result must retain the actual frozen parent submission' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: laboratory_complete_job_creation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_complete_job_creation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE member_count integer; last_position integer; first_position integer; selected_sample uuid;
  job public.test_requests; settings public.organization_laboratory_settings; analyst uuid; sample_state uuid; summary_template uuid;
BEGIN
  SELECT * INTO job FROM public.test_requests WHERE organization_id=NEW.organization_id AND id=NEW.id;
  SELECT * INTO settings FROM public.organization_laboratory_settings WHERE organization_id=NEW.organization_id FOR SHARE;
  SELECT sample_id INTO selected_sample FROM public.sample_products WHERE organization_id=NEW.organization_id AND id=NEW.job_sample_product_id;
  SELECT resolved.template_id INTO summary_template FROM public.laboratory_product_job_templates(selected_sample,ARRAY[job.job_sample_product_id],job.is_auto_created) resolved;
  IF summary_template IS NULL OR job.datasheet_template_id IS DISTINCT FROM summary_template THEN
    RAISE EXCEPTION 'Jobs require the configured organization or product summary template' USING ERRCODE='23514';
  END IF;
  IF job.is_auto_created THEN
    IF NOT settings.auto_create_jobs OR NOT public.laboratory_job_generation_sample(selected_sample) OR job.status<>'created' OR job.revision<>1
      OR EXISTS (SELECT 1 FROM public.test_request_assignments WHERE organization_id=job.organization_id AND test_request_id=job.id)
      OR EXISTS (SELECT 1 FROM public.datasheets WHERE organization_id=job.organization_id AND test_request_id=job.id)
      OR EXISTS (SELECT 1 FROM public.workflow_runs WHERE organization_id=job.organization_id AND test_request_id=job.id)
    THEN RAISE EXCEPTION 'Automatic jobs stay unassigned until explicit allocation' USING ERRCODE='23514'; END IF;
    analyst:=job.created_by;
  ELSE
  -- Match workflowAllowedActions: a configured allocation capability applies
  -- to this actor; otherwise the allocator permission is the fallback.
  SELECT current_state_id INTO sample_state FROM public.workflow_runs WHERE organization_id=NEW.organization_id AND sample_id=selected_sample;
  IF EXISTS (SELECT 1 FROM public.workflow_state_capability_roles WHERE organization_id=NEW.organization_id AND workflow_state_id=sample_state AND capability='allocate')
    AND NOT EXISTS (SELECT 1 FROM public.workflow_state_capability_roles capability JOIN public.membership_roles role
      ON role.organization_id=capability.organization_id AND role.role_id=capability.role_id
      WHERE capability.organization_id=NEW.organization_id AND capability.workflow_state_id=sample_state AND capability.capability='allocate' AND role.user_id=NEW.created_by)
  THEN RAISE EXCEPTION 'The sample state does not allow this actor to create jobs' USING ERRCODE='42501'; END IF;
  SELECT assigned_user_id INTO analyst FROM public.test_request_assignments
    WHERE organization_id=NEW.organization_id AND test_request_id=NEW.id AND assignment_type='analyst' AND unassigned_at IS NULL
      AND assigned_by=NEW.created_by AND assigned_at=transaction_timestamp();
  IF job.status<>'allocated' OR analyst IS NULL OR NOT EXISTS (SELECT 1 FROM public.datasheets
    WHERE organization_id=NEW.organization_id AND test_request_id=NEW.id AND attempt_number=1 AND status='in_progress')
  THEN RAISE EXCEPTION 'A manual job requires its actual analyst and summary capture' USING ERRCODE='23514'; END IF;
  END IF;
  SELECT count(*)::integer,min(job_member_position),max(job_member_position) INTO member_count,first_position,last_position
    FROM public.test_requests WHERE organization_id=NEW.organization_id AND parent_test_request_id=NEW.id;
  IF member_count=0 OR first_position<>0 OR last_position<>member_count-1 THEN
    RAISE EXCEPTION 'A job requires an ordered set of linked requests' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.test_requests member WHERE member.organization_id=NEW.organization_id AND member.parent_test_request_id=NEW.id
    AND ((job.is_auto_created AND NOT public.laboratory_new_generated_request(member.id)) OR member.status<>'allocated' OR NOT EXISTS (SELECT 1 FROM public.test_request_assignments assignment
      WHERE assignment.organization_id=member.organization_id AND assignment.test_request_id=member.id AND assignment.assignment_type='analyst'
        AND assignment.assigned_user_id=analyst AND assignment.unassigned_at IS NULL AND assignment.assigned_by=NEW.created_by AND assignment.assigned_at=transaction_timestamp())
      OR NOT EXISTS (SELECT 1 FROM public.datasheets sheet WHERE sheet.organization_id=member.organization_id AND sheet.test_request_id=member.id AND sheet.attempt_number=1 AND sheet.status='in_progress')))
  THEN RAISE EXCEPTION 'Job members require their actual analyst and individual captures' USING ERRCODE='23514'; END IF;
  IF job.is_auto_created AND EXISTS (SELECT 1 FROM public.test_requests member
    WHERE member.organization_id=job.organization_id AND member.parent_test_request_id=job.id AND member.using_dynamic_workflow
      AND NOT EXISTS (SELECT 1 FROM public.workflow_runs run JOIN public.workflow_versions version
        ON version.organization_id=run.organization_id AND version.id=run.workflow_version_id
        JOIN public.workflow_run_history history ON history.organization_id=run.organization_id AND history.workflow_run_id=run.id AND history.action='started'
        WHERE run.organization_id=member.organization_id AND run.test_request_id=member.id AND version.workflow_id=settings.test_request_workflow_id
          AND run.started_by=job.created_by AND run.started_at=transaction_timestamp() AND history.actor_user_id=job.created_by AND history.occurred_at=transaction_timestamp()))
  THEN RAISE EXCEPTION 'Automatic children require their actual configured initial workflows' USING ERRCODE='23514'; END IF;
  IF job.is_auto_created AND EXISTS (SELECT 1 FROM public.test_requests member
    JOIN public.sample_tests selected ON selected.organization_id=member.organization_id AND selected.id=member.sample_test_id
    JOIN public.sample_products product ON product.organization_id=selected.organization_id AND product.id=selected.sample_product_id
    JOIN public.sample_category_workflows mapping ON mapping.organization_id=product.organization_id AND mapping.sample_category_id=product.sample_category_id AND mapping.applies_to='test_request' AND mapping.is_default
    JOIN public.workflows workflow ON workflow.organization_id=mapping.organization_id AND workflow.id=mapping.workflow_id AND workflow.active
    JOIN public.workflow_versions version ON version.organization_id=workflow.organization_id AND version.workflow_id=workflow.id AND version.status='published'
    WHERE member.organization_id=job.organization_id AND member.parent_test_request_id=job.id AND member.using_dynamic_workflow IS NULL
      AND NOT EXISTS (SELECT 1 FROM public.workflow_runs run JOIN public.workflow_run_history history ON history.organization_id=run.organization_id AND history.workflow_run_id=run.id AND history.action='started'
        WHERE run.organization_id=member.organization_id AND run.test_request_id=member.id AND run.workflow_version_id=version.id
          AND run.started_by=job.created_by AND run.started_at=transaction_timestamp() AND history.actor_user_id=job.created_by AND history.occurred_at=transaction_timestamp()))
  THEN RAISE EXCEPTION 'Automatic children require their actual configured initial workflows' USING ERRCODE='23514'; END IF;
  INSERT INTO public.sample_events(organization_id,sample_id,test_request_id,event_type,actor_user_id,description)
    VALUES(NEW.organization_id,selected_sample,NEW.id,'test_request_job_created',NEW.created_by,
      format('%s job with %s test request%s.',CASE WHEN job.is_auto_created THEN 'Automatically created' ELSE 'Created' END,member_count,CASE WHEN member_count=1 THEN '' ELSE 's' END));
  RETURN NEW;
END $$;


--
-- Name: laboratory_complete_job_result(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_complete_job_result() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF session_user='sampleify_app' AND NEW.origin='entered'
    AND EXISTS (SELECT 1 FROM public.template_occurrences WHERE organization_id=NEW.organization_id AND instance_id=NEW.instance_id AND id=NEW.occurrence_id AND created_revision<NEW.revision)
    AND EXISTS (SELECT 1 FROM public.template_fields WHERE organization_id=NEW.organization_id AND version_id=NEW.version_id AND id=NEW.field_id AND widget='result_widget')
    AND EXISTS (SELECT 1 FROM public.datasheets sheet JOIN public.test_requests job ON job.organization_id=sheet.organization_id AND job.id=sheet.test_request_id AND job.is_job
      WHERE sheet.organization_id=NEW.organization_id AND sheet.template_instance_id=NEW.instance_id)
    AND NOT EXISTS (SELECT 1 FROM public.template_sections WHERE organization_id=NEW.organization_id AND version_id=NEW.version_id AND is_final_result)
    AND public.laboratory_result_subject(NEW.organization_id,NEW.instance_id,NEW.occurrence_id) IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.job_result_entries WHERE organization_id=NEW.organization_id AND instance_id=NEW.instance_id
      AND field_id=NEW.field_id AND occurrence_id=NEW.occurrence_id AND value_revision=NEW.revision) THEN
    RAISE EXCEPTION 'A changed job result and its actual child provenance must commit together' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: laboratory_complete_subject_occurrence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_complete_subject_occurrence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE repeat_source text;
BEGIN
  SELECT source INTO repeat_source FROM public.template_repeat_groups WHERE organization_id=NEW.organization_id AND version_id=NEW.version_id AND id=NEW.group_id;
  IF repeat_source IS DISTINCT FROM 'test_requests' THEN RETURN NEW; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.datasheet_subjects WHERE organization_id=NEW.organization_id AND instance_id=NEW.instance_id AND occurrence_id=NEW.id) THEN
    RAISE EXCEPTION 'A parameter occurrence requires its recorded request subject' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND NEW.removed_revision IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.template_occurrences
    WHERE organization_id=NEW.organization_id AND instance_id=NEW.instance_id AND id=NEW.parent_id AND removed_revision=NEW.removed_revision)
  THEN RAISE EXCEPTION 'A parameter occurrence cannot be removed independently of its parent' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_finish_auto_job_member(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_finish_auto_job_member() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; member_id uuid:=public.laboratory_auto_job_request(); next_revision integer;
BEGIN
  IF member_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.datasheets sheet JOIN public.template_instances capture
    ON capture.organization_id=sheet.organization_id AND capture.id=sheet.template_instance_id
    WHERE sheet.organization_id=org AND sheet.test_request_id=member_id AND sheet.attempt_number=1 AND sheet.status='in_progress'
      AND capture.id=public.laboratory_auto_job_capture()) THEN RAISE EXCEPTION 'The automatic child requires its actual initialized capture' USING ERRCODE='23514'; END IF;
  UPDATE public.test_requests request SET datasheet_template_id=coalesce(request.datasheet_template_id,public.laboratory_auto_job_template()),revision=request.revision+1
    WHERE request.organization_id=org AND request.id=member_id RETURNING revision INTO next_revision;
  RETURN next_revision;
END $$;


--
-- Name: laboratory_generation_job_settings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_generation_job_settings(p_sample_id uuid) RETURNS TABLE(auto_create_jobs boolean, result_summary_template_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NOT public.laboratory_job_generation_sample(p_sample_id) THEN RAISE EXCEPTION 'Actual test request generation is required' USING ERRCODE='42501'; END IF;
  RETURN QUERY SELECT settings.auto_create_jobs,CASE WHEN EXISTS (SELECT 1 FROM public.templates template JOIN public.template_versions version
    ON version.organization_id=template.organization_id AND version.template_id=template.id WHERE template.organization_id=settings.organization_id
      AND template.id=settings.result_summary_template_id AND template.active AND version.kind='datasheet') THEN settings.result_summary_template_id END
    FROM public.organization_laboratory_settings settings
    WHERE settings.organization_id=nullif(current_setting('app.organization_id',true),'')::uuid FOR SHARE OF settings;
END $$;


--
-- Name: laboratory_group_capture(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_group_capture(capture_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.datasheets sheet WHERE sheet.organization_id=nullif(current_setting('app.organization_id',true),'')::uuid
    AND sheet.template_instance_id=capture_id AND sheet.status IN ('in_progress','rejected')
    AND public.laboratory_group_submission_for_request(sheet.test_request_id) IS NOT NULL)
$$;


--
-- Name: laboratory_group_submission_for_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_group_submission_for_request(request_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT parent.id FROM public.datasheet_submissions parent JOIN public.datasheets sheet ON sheet.organization_id=parent.organization_id AND sheet.id=parent.datasheet_id
    JOIN public.test_requests job ON job.organization_id=sheet.organization_id AND job.id=sheet.test_request_id AND job.is_job
    JOIN public.test_requests child ON child.organization_id=job.organization_id AND child.parent_test_request_id=job.id AND child.id=request_id
    JOIN public.template_instances capture ON capture.organization_id=parent.organization_id AND capture.id=parent.instance_id
    WHERE parent.organization_id=nullif(current_setting('app.organization_id',true),'')::uuid
      AND parent.id=nullif(current_setting('app.job_submission_id',true),'')::uuid
      AND parent.submitted_by=nullif(current_setting('app.user_id',true),'')::uuid AND parent.xmin::text=pg_current_xact_id()::text
      AND parent.source_datasheet_id=parent.datasheet_id AND capture.status='frozen' AND capture.revision=parent.capture_revision
      AND public.app_has_permission('datasheets.execute')
      AND NOT EXISTS (SELECT 1 FROM public.workflow_runs run JOIN public.approval_cases approval ON approval.organization_id=run.organization_id AND approval.workflow_run_id=run.id
        WHERE run.organization_id=child.organization_id AND run.test_request_id=child.id AND approval.status='pending')
$$;


--
-- Name: laboratory_guard_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_actor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE recorded_actor uuid; actual_actor uuid := nullif(current_setting('app.user_id', true), '')::uuid;
BEGIN
  IF current_user <> 'sampleify_app' THEN RETURN NEW; END IF;
  CASE TG_TABLE_NAME
    WHEN 'samples' THEN recorded_actor := NEW.registered_by;
    WHEN 'analytical_specifications' THEN recorded_actor := NEW.recorded_by;
    WHEN 'test_requests', 'datasheets', 'workflow_versions' THEN recorded_actor := NEW.created_by;
    WHEN 'test_request_assignments' THEN recorded_actor := NEW.assigned_by;
    WHEN 'workflow_runs' THEN recorded_actor := NEW.started_by;
    WHEN 'workflow_run_history', 'sample_events' THEN recorded_actor := NEW.actor_user_id;
  END CASE;
  IF actual_actor IS NULL OR actual_actor IS DISTINCT FROM recorded_actor THEN
    RAISE EXCEPTION 'Recorded actor must match the authenticated user' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_alternate_capture(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_alternate_capture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.analytical_specifications WHERE organization_id=NEW.organization_id AND id=NEW.specification_id AND basis_specification_id IS NOT NULL)
    AND NOT EXISTS (SELECT 1 FROM public.template_instances capture
      JOIN public.template_versions version ON version.organization_id=capture.organization_id AND version.id=capture.version_id
      JOIN public.test_requests request ON request.organization_id=capture.organization_id AND request.id=NEW.test_request_id
      WHERE capture.organization_id=NEW.organization_id AND capture.id=NEW.template_instance_id
        AND capture.status='editing' AND capture.revision=1 AND capture.created_by=NEW.created_by AND capture.created_at=NEW.created_at
        AND version.template_id=request.datasheet_template_id AND version.kind='datasheet' AND version.status='frozen')
  THEN RAISE EXCEPTION 'An alternate method requires a new capture of its assigned template' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE request_status text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF (NEW.test_request_id, NEW.assigned_user_id, NEW.assignment_type, NEW.assigned_by, NEW.assigned_at)
      IS DISTINCT FROM (OLD.test_request_id, OLD.assigned_user_id, OLD.assignment_type, OLD.assigned_by, OLD.assigned_at)
      OR OLD.unassigned_at IS NOT NULL OR NEW.unassigned_at IS NULL THEN
      RAISE EXCEPTION 'Assignment history can only end an active assignment' USING ERRCODE = '55000';
    END IF;
  ELSE
    SELECT status INTO request_status FROM public.test_requests WHERE organization_id = NEW.organization_id AND id = NEW.test_request_id FOR UPDATE;
    IF request_status IS NULL OR request_status IN ('approved', 'cancelled') THEN RAISE EXCEPTION 'Closed test requests cannot be allocated' USING ERRCODE = '23514'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.memberships m JOIN public.users u ON u.id = m.user_id
      WHERE m.organization_id = NEW.organization_id AND m.user_id = NEW.assigned_user_id AND m.active AND u.active) THEN
      RAISE EXCEPTION 'The selected user is not active in this organization' USING ERRCODE = '23514';
    END IF;
    IF NEW.assignment_type IN ('analyst', 'reviewer') AND EXISTS (SELECT 1 FROM public.test_request_assignments
      WHERE organization_id = NEW.organization_id AND test_request_id = NEW.test_request_id AND assigned_user_id = NEW.assigned_user_id
        AND assignment_type = CASE NEW.assignment_type WHEN 'analyst' THEN 'reviewer' ELSE 'analyst' END AND unassigned_at IS NULL) THEN
      RAISE EXCEPTION 'Assignee and reviewer cannot be the same' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_capture_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_capture_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.template_instance_id IS NOT NULL AND NEW.template_instance_id IS DISTINCT FROM OLD.template_instance_id THEN
    RAISE EXCEPTION 'A runtime capture cannot be replaced silently' USING ERRCODE = '55000';
  END IF;
  IF NEW.template_instance_id IS NULL THEN RETURN NEW; END IF;
  PERFORM 1 FROM public.template_instances WHERE organization_id = NEW.organization_id AND id = NEW.template_instance_id FOR UPDATE;
  IF TG_TABLE_NAME = 'samples' THEN
    IF EXISTS (SELECT 1 FROM public.datasheets WHERE organization_id = NEW.organization_id AND template_instance_id = NEW.template_instance_id)
      OR NOT EXISTS (SELECT 1 FROM public.template_instances i JOIN public.template_versions v ON v.organization_id = i.organization_id AND v.id = i.version_id
        WHERE i.organization_id = NEW.organization_id AND i.id = NEW.template_instance_id AND v.kind = 'sample') THEN
      RAISE EXCEPTION 'Sample capture ownership or template type is invalid' USING ERRCODE = '23514';
    END IF;
  ELSIF EXISTS (SELECT 1 FROM public.samples WHERE organization_id = NEW.organization_id AND template_instance_id = NEW.template_instance_id) THEN
    RAISE EXCEPTION 'A capture cannot belong to both a sample and a datasheet' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_datasheet(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_datasheet() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF (NEW.test_request_id, NEW.template_instance_id, NEW.specification_id, NEW.method_id, NEW.attempt_number, NEW.created_by, NEW.created_at)
      IS DISTINCT FROM (OLD.test_request_id, OLD.template_instance_id, OLD.specification_id, OLD.method_id, OLD.attempt_number, OLD.created_by, OLD.created_at)
      OR NEW.revision <> OLD.revision + 1 THEN RAISE EXCEPTION 'Datasheet identity is immutable and revisions are sequential' USING ERRCODE = '23514'; END IF;
  ELSE
    PERFORM 1 FROM public.analytical_specifications WHERE organization_id = NEW.organization_id AND id = NEW.specification_id FOR SHARE;
    IF NEW.status <> 'in_progress' OR NEW.revision <> 1 OR NOT EXISTS (SELECT 1 FROM public.template_instances i JOIN public.template_versions v
      ON v.organization_id = i.organization_id AND v.id = i.version_id
      WHERE i.organization_id = NEW.organization_id AND i.id = NEW.template_instance_id AND i.status = 'editing' AND v.kind = 'datasheet') THEN
      RAISE EXCEPTION 'A datasheet requires a new editable capture with a datasheet template' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_datasheet_subject(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_datasheet_subject() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE sheet public.datasheets; owner public.test_requests; subject public.test_requests; occurrence public.template_occurrences;
  capture public.template_instances; repeat_source text;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Parameter subject history is immutable' USING ERRCODE='55000'; END IF;
  SELECT * INTO sheet FROM public.datasheets WHERE organization_id=NEW.organization_id AND id=NEW.datasheet_id;
  SELECT * INTO owner FROM public.test_requests WHERE organization_id=NEW.organization_id AND id=sheet.test_request_id;
  SELECT * INTO subject FROM public.test_requests WHERE organization_id=NEW.organization_id AND id=NEW.test_request_id;
  SELECT * INTO capture FROM public.template_instances WHERE organization_id=NEW.organization_id AND id=NEW.instance_id FOR UPDATE;
  SELECT * INTO occurrence FROM public.template_occurrences WHERE organization_id=NEW.organization_id AND instance_id=NEW.instance_id AND version_id=NEW.version_id AND id=NEW.occurrence_id;
  SELECT source INTO repeat_source FROM public.template_repeat_groups WHERE organization_id=NEW.organization_id AND version_id=NEW.version_id AND id=occurrence.group_id;
  IF sheet.id IS NULL OR subject.id IS NULL OR capture.status IS DISTINCT FROM 'editing' OR sheet.template_instance_id<>NEW.instance_id
    OR repeat_source IS DISTINCT FROM 'test_requests' OR occurrence.removed_revision IS NOT NULL
    OR NEW.created_revision IS DISTINCT FROM occurrence.created_revision OR NEW.created_revision<>capture.revision
    OR NEW.created_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid OR NEW.created_at IS DISTINCT FROM transaction_timestamp()
  THEN RAISE EXCEPTION 'Parameter subjects require their current capture, actor and occurrence' USING ERRCODE='23514'; END IF;
  IF owner.is_job THEN
    IF subject.is_job OR subject.parent_test_request_id IS DISTINCT FROM owner.id OR NEW.specification_id<>subject.specification_id THEN
      RAISE EXCEPTION 'Job parameter subjects must use a member and its frozen specification' USING ERRCODE='23514';
    END IF;
  ELSIF subject.id<>owner.id OR NEW.specification_id IS DISTINCT FROM sheet.specification_id THEN
    RAISE EXCEPTION 'An individual datasheet must use its own frozen specification' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.datasheet_subjects binding JOIN public.template_occurrences other
    ON other.organization_id=binding.organization_id AND other.instance_id=binding.instance_id AND other.id=binding.occurrence_id
    WHERE binding.organization_id=NEW.organization_id AND binding.instance_id=NEW.instance_id AND binding.test_request_id=NEW.test_request_id
      AND other.group_id=occurrence.group_id AND other.parent_id=occurrence.parent_id AND other.removed_revision IS NULL)
  THEN RAISE EXCEPTION 'Each parameter occurs once within its parent loop' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_dynamic_workflow_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_dynamic_workflow_binding() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE selected_id uuid;
BEGIN
  IF session_user='sampleify_app' AND NEW.test_request_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.test_requests WHERE organization_id=NEW.organization_id AND id=NEW.test_request_id AND using_dynamic_workflow) THEN
    selected_id:=public.laboratory_test_request_workflow(NEW.test_request_id);
    PERFORM 1 FROM public.workflows workflow JOIN public.workflow_versions version
      ON version.organization_id=workflow.organization_id AND version.workflow_id=workflow.id
      WHERE workflow.organization_id=NEW.organization_id AND workflow.id=selected_id AND workflow.active
        AND workflow.applies_to='test_request' AND version.id=NEW.workflow_version_id AND version.status='published' FOR SHARE OF workflow;
    IF NOT FOUND THEN RAISE EXCEPTION 'Dynamic requests require the configured published workflow'
      USING ERRCODE='23514',CONSTRAINT='test_request_workflow_binding'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF (NEW.organization_id, NEW.id) IS DISTINCT FROM (OLD.organization_id, OLD.id) THEN
    RAISE EXCEPTION 'Laboratory record identity is immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_job_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_job_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.event_type='test_request_job_created' AND (pg_trigger_depth()<2
    OR NEW.actor_user_id IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid OR NEW.occurred_at IS DISTINCT FROM transaction_timestamp())
  THEN RAISE EXCEPTION 'Job events require the actual creation action' USING ERRCODE='42501'; END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_job_submission_member(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_job_submission_member() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.parent_submission_id IS DISTINCT FROM public.laboratory_group_submission_for_request(NEW.test_request_id)
    OR NOT EXISTS (SELECT 1 FROM public.datasheet_submissions submission JOIN public.datasheets sheet
      ON sheet.organization_id=submission.organization_id AND sheet.id=submission.datasheet_id AND sheet.latest_submission_id=submission.id
      JOIN public.test_requests request ON request.organization_id=sheet.organization_id AND request.id=sheet.test_request_id AND request.final_datasheet_id=sheet.id
      WHERE submission.organization_id=NEW.organization_id AND submission.id=NEW.submission_id AND request.id=NEW.test_request_id
        AND sheet.status IN ('under_review','approved') AND request.status IN ('under_review','approved')) THEN
    RAISE EXCEPTION 'A job must cover the actual current submission of its child' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_master_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_master_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.revision <> OLD.revision + 1 THEN
    RAISE EXCEPTION 'Master changes require the next revision and original creation time' USING ERRCODE = '23514';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_method_datasheet(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_method_datasheet() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE request public.test_requests; basis public.analytical_specifications; supplied public.analytical_specifications;
  method public.methods_of_analysis; expected public.analytical_specifications;
BEGIN
  SELECT * INTO request FROM public.test_requests WHERE organization_id=NEW.organization_id AND id=NEW.test_request_id FOR UPDATE;
  IF TG_OP='INSERT' AND request.is_job THEN
    IF NEW.specification_id IS NOT NULL OR NEW.method_id IS NOT NULL OR NEW.attempt_number<>1
      OR NOT public.app_has_permission('test_requests.allocate') OR request.status NOT IN ('created','allocated')
      OR EXISTS (SELECT 1 FROM public.datasheets WHERE organization_id=NEW.organization_id AND test_request_id=request.id)
      OR NOT EXISTS (SELECT 1 FROM public.template_instances capture JOIN public.template_versions version
        ON version.organization_id=capture.organization_id AND version.id=capture.version_id
        WHERE capture.organization_id=NEW.organization_id AND capture.id=NEW.template_instance_id
          AND capture.created_by=NEW.created_by AND capture.created_at=NEW.created_at AND capture.revision=1
          AND version.template_id=request.datasheet_template_id AND version.kind='datasheet' AND version.status='frozen')
    THEN RAISE EXCEPTION 'A job requires one new summary capture and has no individual method' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='UPDATE' THEN
    IF OLD.status='void' THEN RAISE EXCEPTION 'Retired methods are immutable' USING ERRCODE='55000'; END IF;
    -- Cancellation has already changed the request status in its authorized
    -- workflow command. It retires every method, including submitted ones.
    IF NEW.status='void' AND request.status<>'cancelled' THEN
      IF OLD.status NOT IN ('in_progress','rejected') OR NOT public.laboratory_request_can_work(request.id) THEN
        RAISE EXCEPTION 'Only the assigned analyst can retire an open method' USING ERRCODE='42501';
      END IF;
      IF NOT EXISTS (SELECT 1 FROM public.datasheets WHERE organization_id=NEW.organization_id AND test_request_id=request.id AND id<>NEW.id AND status<>'void') THEN
        RAISE EXCEPTION 'At least one method must remain' USING ERRCODE='23514';
      END IF;
      IF NOT EXISTS (SELECT 1 FROM public.template_instances WHERE organization_id=NEW.organization_id AND id=NEW.template_instance_id AND status='frozen') THEN
        RAISE EXCEPTION 'A retired method must preserve a frozen capture' USING ERRCODE='23514';
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO supplied FROM public.analytical_specifications WHERE organization_id=NEW.organization_id AND id=NEW.specification_id;
  IF supplied.id=request.specification_id AND NOT EXISTS (SELECT 1 FROM public.datasheets WHERE organization_id=NEW.organization_id AND test_request_id=request.id) THEN RETURN NEW; END IF;
  IF request.is_job OR NOT public.laboratory_request_can_work(request.id) OR supplied.basis_specification_id IS DISTINCT FROM request.specification_id THEN
    RAISE EXCEPTION 'An alternate datasheet must use its open request specification' USING ERRCODE='42501';
  END IF;
  IF NEW.created_at IS DISTINCT FROM transaction_timestamp() OR NEW.created_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Method creation must record the actual actor and time' USING ERRCODE='42501';
  END IF;
  IF NEW.attempt_number<>(SELECT coalesce(max(attempt_number),0)+1 FROM public.datasheets WHERE organization_id=NEW.organization_id AND test_request_id=request.id)
    OR EXISTS (SELECT 1 FROM public.datasheets WHERE organization_id=NEW.organization_id AND test_request_id=request.id AND method_id=NEW.method_id AND status<>'void') THEN
    RAISE EXCEPTION 'The method already exists or its attempt number changed' USING ERRCODE='23514';
  END IF;
  SELECT * INTO basis FROM public.analytical_specifications WHERE organization_id=NEW.organization_id AND id=request.specification_id;
  SELECT * INTO method FROM public.methods_of_analysis WHERE organization_id=NEW.organization_id AND id=NEW.method_id FOR SHARE;
  IF basis.basis_specification_id IS NOT NULL OR NOT method.active OR (EXISTS (SELECT 1 FROM public.parameter_methods WHERE organization_id=NEW.organization_id AND test_parameter_id=basis.test_parameter_id)
    AND NOT EXISTS (SELECT 1 FROM public.parameter_methods WHERE organization_id=NEW.organization_id AND test_parameter_id=basis.test_parameter_id AND method_id=NEW.method_id)) THEN
    RAISE EXCEPTION 'The method is not applicable to this parameter' USING ERRCODE='23514';
  END IF;
  expected:=basis; expected.id:=supplied.id; expected.basis_specification_id:=basis.id;
  expected.method_id:=method.id; expected.method_revision:=method.revision; expected.method_code:=method.code; expected.method_name:=method.name;
  expected.method_description:=method.description; expected.method_uuid:=method.method_uuid; expected.decimal_scale:=method.decimal_scale; expected.parse_number:=method.parse_number;
  expected.recorded_by:=NEW.created_by; expected.recorded_at:=NEW.created_at;
  IF supplied IS DISTINCT FROM expected OR EXISTS (
    (SELECT id,lower_limit,upper_limit,lower_inclusive,upper_inclusive,outcome,narration,display_order FROM public.analytical_specification_limits WHERE organization_id=NEW.organization_id AND specification_id=basis.id
      EXCEPT SELECT id,lower_limit,upper_limit,lower_inclusive,upper_inclusive,outcome,narration,display_order FROM public.analytical_specification_limits WHERE organization_id=NEW.organization_id AND specification_id=supplied.id)
    UNION ALL
    (SELECT id,lower_limit,upper_limit,lower_inclusive,upper_inclusive,outcome,narration,display_order FROM public.analytical_specification_limits WHERE organization_id=NEW.organization_id AND specification_id=supplied.id
      EXCEPT SELECT id,lower_limit,upper_limit,lower_inclusive,upper_inclusive,outcome,narration,display_order FROM public.analytical_specification_limits WHERE organization_id=NEW.organization_id AND specification_id=basis.id)
  ) THEN RAISE EXCEPTION 'An alternate method must retain the frozen request criterion' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_method_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_method_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.event_type IN ('datasheet_method_added','datasheet_method_voided') AND
    (pg_trigger_depth()<2 OR NEW.actor_user_id IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid OR NEW.occurred_at IS DISTINCT FROM transaction_timestamp()) THEN
    RAISE EXCEPTION 'Method events must originate from the actual method change' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_request_workflow_mode(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_request_workflow_mode() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='INSERT' AND session_user='sampleify_app' AND NEW.using_dynamic_workflow IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'New requests require dynamic workflows' USING ERRCODE='42501';
  END IF;
  IF TG_OP='UPDATE' AND NEW.using_dynamic_workflow IS DISTINCT FROM OLD.using_dynamic_workflow THEN
    RAISE EXCEPTION 'Request workflow mode is immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_result_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_result_number() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE config public.template_numeric_config;
BEGIN
  IF NEW.origin<>'entered' OR NEW.state<>'present' OR NOT EXISTS (SELECT 1 FROM public.template_fields
    WHERE organization_id=NEW.organization_id AND version_id=NEW.version_id AND id=NEW.field_id AND widget='result_widget') THEN RETURN NEW; END IF;
  IF NEW.value_type='result' AND NEW.text_value IS NOT NULL THEN
    IF length(NEW.text_value) NOT BETWEEN 1 AND 16000 OR NEW.lexical IS NOT NULL
      OR NEW.text_value<>btrim(NEW.text_value,U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')
      OR NEW.text_value ~ '^[+-]?([0-9]|[.][0-9]|Infinity)' THEN
      RAISE EXCEPTION 'Scientific result interpretation is unresolved' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  -- Validate lexical shape and bounds before casts. No rounding or numeric
  -- prefixes are chosen while the source numeric-policy decision is pending.
  IF NEW.number_value IS NULL OR NEW.lexical IS NULL OR length(NEW.lexical)>1000 OR NEW.lexical !~ '^-?[0-9]+([.][0-9]+)?$'
    OR length(ltrim(split_part(NEW.lexical,'.',1),'-0'))>18 OR length(split_part(NEW.lexical,'.',2))>12 THEN
    RAISE EXCEPTION 'Scientific result interpretation is unresolved' USING ERRCODE='23514';
  END IF;
  SELECT * INTO config FROM public.template_numeric_config WHERE organization_id=NEW.organization_id AND version_id=NEW.version_id AND field_id=NEW.field_id;
  IF NEW.number_value<>NEW.lexical::numeric OR NEW.number_value<>round(NEW.number_value,2)
    OR NEW.number_value::float8::text::numeric<>NEW.number_value
    OR (config.display_scale IS NOT NULL AND length(split_part(NEW.lexical,'.',2))>config.display_scale)
    OR (config.minimum IS NOT NULL AND NEW.number_value<config.minimum) OR (config.maximum IS NOT NULL AND NEW.number_value>config.maximum) THEN
    RAISE EXCEPTION 'Scientific result interpretation is unresolved' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $_$;


--
-- Name: laboratory_guard_rule_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_rule_limit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM 1 FROM public.decision_rules WHERE organization_id = OLD.organization_id AND id = OLD.decision_rule_id FOR UPDATE;
    RETURN OLD;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.decision_rule_id IS DISTINCT FROM OLD.decision_rule_id THEN
    RAISE EXCEPTION 'A rule limit cannot move to another rule' USING ERRCODE = '23514';
  END IF;
  PERFORM 1 FROM public.decision_rules WHERE organization_id = NEW.organization_id AND id = NEW.decision_rule_id FOR UPDATE;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_sample(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_sample() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF (NEW.sample_number, NEW.registered_by, NEW.registered_at)
    IS DISTINCT FROM (OLD.sample_number, OLD.registered_by, OLD.registered_at)
    OR NEW.revision <> OLD.revision + 1 THEN RAISE EXCEPTION 'Sample registration identity is immutable and revisions are sequential' USING ERRCODE = '23514'; END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_sample_edit_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_sample_edit_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.event_type='sample_updated' THEN
    IF session_user='sampleify_app' AND NOT public.app_has_permission('samples.manage') THEN
      RAISE EXCEPTION 'Sample management permission required' USING ERRCODE='42501';
    END IF;
    IF NEW.test_request_id IS NOT NULL OR NEW.datasheet_id IS NOT NULL THEN
      RAISE EXCEPTION 'A sample header edit event belongs to the sample' USING ERRCODE='23514',CONSTRAINT='sample_edit_event_owner';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_sample_line_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_sample_line_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE product public.sample_products; sample public.samples;
BEGIN
  IF session_user='sampleify_app' AND (OLD.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR NOT public.app_has_permission('samples.manage')) THEN
    RAISE EXCEPTION 'Sample management permission required' USING ERRCODE='42501';
  END IF;
  IF TG_TABLE_NAME='sample_products' THEN product := OLD;
  ELSE SELECT * INTO product FROM public.sample_products WHERE organization_id=OLD.organization_id AND id=OLD.sample_product_id; END IF;
  SELECT * INTO sample FROM public.samples WHERE organization_id=product.organization_id AND id=product.sample_id FOR UPDATE;
  IF session_user='sampleify_app' AND (sample.sample_type IN ('quality_control','amendment')
    OR (TG_TABLE_NAME='sample_products' AND sample.sample_type='complaint')) THEN
    RAISE EXCEPTION 'This sample does not allow line removal' USING ERRCODE='42501';
  END IF;
  IF TG_TABLE_NAME='sample_products' THEN
    IF public.laboratory_sample_line_in_use(OLD.organization_id,OLD.sample_id,OLD.id) THEN
      RAISE EXCEPTION 'A used sample line cannot be removed' USING ERRCODE='55000';
    END IF;
  ELSIF OLD.status<>'planned' OR EXISTS (SELECT 1 FROM public.test_requests WHERE organization_id=OLD.organization_id AND sample_test_id=OLD.id)
    OR EXISTS (SELECT 1 FROM public.sample_reports WHERE organization_id=OLD.organization_id AND sample_test_id=OLD.id)
    OR EXISTS (SELECT 1 FROM public.sample_report_tests WHERE organization_id=OLD.organization_id AND sample_test_id=OLD.id) THEN
    RAISE EXCEPTION 'A requested test cannot be removed' USING ERRCODE='55000';
  END IF;
  RETURN OLD;
END $$;


--
-- Name: laboratory_guard_sample_product_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_sample_product_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE product public.products; selected_revision integer; sample public.samples;
BEGIN
  IF TG_OP='UPDATE' THEN
    IF NEW.sample_id IS DISTINCT FROM OLD.sample_id OR (NEW.product_id=OLD.product_id AND
      (NEW.product_revision,NEW.product_code,NEW.product_name) IS DISTINCT FROM (OLD.product_revision,OLD.product_code,OLD.product_name)) THEN
      RAISE EXCEPTION 'A saved sample line retains its Product identity and captured history' USING ERRCODE='55000';
    END IF;
    IF (NEW.product_id,NEW.sample_category_id) IS DISTINCT FROM (OLD.product_id,OLD.sample_category_id) THEN
      SELECT * INTO sample FROM public.samples WHERE organization_id=OLD.organization_id AND id=OLD.sample_id FOR UPDATE;
      IF public.laboratory_sample_line_in_use(OLD.organization_id,OLD.sample_id,OLD.id) THEN
        RAISE EXCEPTION 'A used sample line retains its Product and category' USING ERRCODE='55000';
      END IF;
      IF session_user='sampleify_app' AND (NOT public.app_has_permission('samples.manage')
        OR sample.sample_type IN ('quality_control','amendment','complaint')) THEN
        RAISE EXCEPTION 'This sample does not allow Product or category changes' USING ERRCODE='42501';
      END IF;
    END IF;
    IF NEW.product_id=OLD.product_id THEN RETURN NEW; END IF;
  ELSIF session_user<>'sampleify_app' THEN
    -- Owner fixtures/imports retain explicitly supplied provenance. No history
    -- or actor is inferred for an older line.
    RETURN NEW;
  END IF;
  IF session_user='sampleify_app' AND (NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR nullif(current_setting('app.user_id',true),'')::uuid IS NULL
    OR NOT (public.app_has_permission('samples.manage') OR (TG_OP='INSERT' AND public.app_has_permission('samples.create')))) THEN
    RAISE EXCEPTION 'Sample registration or management permission required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO product FROM public.products WHERE organization_id=NEW.organization_id AND id=NEW.product_id FOR SHARE;
  IF NOT FOUND AND TG_OP='UPDATE' THEN
    RAISE EXCEPTION 'The selected Product is unavailable' USING ERRCODE='55000';
  END IF;
  IF NOT FOUND OR NOT product.active OR (NEW.product_code,NEW.product_name) IS DISTINCT FROM (product.code,product.name) THEN
    RAISE EXCEPTION 'Capture the selected active Product name and key' USING ERRCODE='23514',CONSTRAINT='sample_product_current_history';
  END IF;
  SELECT revision INTO selected_revision FROM public.product_versions
    WHERE organization_id=product.organization_id AND product_id=product.id AND revision=product.revision;
  IF NEW.product_revision IS NOT NULL AND NEW.product_revision IS DISTINCT FROM selected_revision THEN
    RAISE EXCEPTION 'Capture the selected current Product revision' USING ERRCODE='23514',CONSTRAINT='sample_product_current_history';
  END IF;
  NEW.product_revision := selected_revision;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_sample_product_tests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_sample_product_tests() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE product public.sample_products;
BEGIN
  IF (NEW.product_id,NEW.sample_category_id) IS NOT DISTINCT FROM (OLD.product_id,OLD.sample_category_id) THEN RETURN NULL; END IF;
  SELECT * INTO product FROM public.sample_products WHERE organization_id=NEW.organization_id AND id=NEW.id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF EXISTS (SELECT 1 FROM public.sample_tests chosen JOIN public.decision_rules rule ON rule.organization_id=chosen.organization_id AND rule.id=chosen.decision_rule_id
    WHERE chosen.organization_id=product.organization_id AND chosen.sample_product_id=product.id AND (rule.product_id<>product.product_id
      OR rule.test_parameter_id<>chosen.test_parameter_id OR (rule.method_id IS NOT NULL AND rule.method_id<>chosen.method_id)
      OR (
        EXISTS (SELECT 1 FROM public.decision_rule_sample_categories category WHERE category.organization_id=rule.organization_id AND category.decision_rule_id=rule.id)
        AND NOT EXISTS (SELECT 1 FROM public.decision_rule_sample_categories category WHERE category.organization_id=rule.organization_id AND category.decision_rule_id=rule.id AND category.sample_category_id=product.sample_category_id)
      ))) THEN
    RAISE EXCEPTION 'Decision rule does not match the selected test and product' USING ERRCODE='23514',CONSTRAINT='sample_product_test_context';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: laboratory_guard_sample_registration(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_sample_registration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF current_user = 'sampleify_app' THEN
    IF NOT public.app_has_permission('samples.create') OR NEW.status <> 'registered' OR NEW.revision <> 1
      OR NEW.id IS DISTINCT FROM nullif(current_setting('app.registration_sample_id', true), '')::uuid THEN
      RAISE EXCEPTION 'Sample creation permission and registration context required' USING ERRCODE = '42501';
    END IF;
    NEW.registered_at := transaction_timestamp();
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_sample_test(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_sample_test() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE product public.sample_products; sample public.samples; details_changed boolean;
BEGIN
  SELECT * INTO product FROM public.sample_products WHERE organization_id=NEW.organization_id AND id=NEW.sample_product_id;
  IF TG_OP='UPDATE' THEN
    IF NEW.sample_product_id IS DISTINCT FROM OLD.sample_product_id THEN
      RAISE EXCEPTION 'A selected test cannot move to another sample product' USING ERRCODE='23514';
    END IF;
    details_changed := (NEW.test_parameter_id,NEW.method_id,NEW.decision_rule_id,NEW.requested_quantity,NEW.requested_size,NEW.rate,NEW.currency_code,
      NEW.estimated_duration_minutes,NEW.is_accredited,NEW.is_retest,NEW.is_subcontracted,NEW.display_order)
      IS DISTINCT FROM (OLD.test_parameter_id,OLD.method_id,OLD.decision_rule_id,OLD.requested_quantity,OLD.requested_size,OLD.rate,OLD.currency_code,
      OLD.estimated_duration_minutes,OLD.is_accredited,OLD.is_retest,OLD.is_subcontracted,OLD.display_order);
    IF details_changed THEN
      SELECT * INTO sample FROM public.samples WHERE organization_id=product.organization_id AND id=product.sample_id FOR UPDATE;
      IF session_user='sampleify_app' AND (NOT public.app_has_permission('samples.manage') OR sample.sample_type IN ('quality_control','amendment')) THEN
        RAISE EXCEPTION 'Sample management permission and an editable sample are required' USING ERRCODE='42501';
      END IF;
      IF (NEW.test_parameter_id,NEW.method_id,NEW.is_retest) IS DISTINCT FROM (OLD.test_parameter_id,OLD.method_id,OLD.is_retest)
        AND (OLD.status<>'planned' OR EXISTS (SELECT 1 FROM public.test_requests WHERE organization_id=OLD.organization_id AND sample_test_id=OLD.id)) THEN
        RAISE EXCEPTION 'Requested test identity cannot be edited' USING ERRCODE='55000';
      END IF;
    END IF;
  ELSIF session_user='sampleify_app' AND NOT (public.app_has_permission('samples.manage')
    OR coalesce(NEW.status='planned' AND product.sample_id=public.laboratory_registering_sample(),false)) THEN
    RAISE EXCEPTION 'Sample creation or management permission required' USING ERRCODE='42501';
  END IF;
  IF NEW.decision_rule_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.decision_rules rule
    WHERE rule.organization_id=NEW.organization_id AND rule.id=NEW.decision_rule_id AND rule.product_id=product.product_id
      AND rule.test_parameter_id=NEW.test_parameter_id AND (rule.method_id IS NULL OR rule.method_id=NEW.method_id)
      AND (
        NOT EXISTS (SELECT 1 FROM public.decision_rule_sample_categories category WHERE category.organization_id=rule.organization_id AND category.decision_rule_id=rule.id)
        OR EXISTS (SELECT 1 FROM public.decision_rule_sample_categories category WHERE category.organization_id=rule.organization_id AND category.decision_rule_id=rule.id AND category.sample_category_id=product.sample_category_id)
      )) THEN
    RAISE EXCEPTION 'Decision rule does not match the selected test and product' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_settings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE selected_ids uuid[]; matched integer; retained_common boolean:=false;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Organization settings cannot be deleted' USING ERRCODE='55000'; END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.revision<>1 THEN RAISE EXCEPTION 'Settings revisions start at one' USING ERRCODE='23514'; END IF;
  ELSE
    IF NEW.organization_id<>OLD.organization_id OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'Settings identity and revision are invalid' USING ERRCODE='23514'; END IF;
  END IF;
  IF session_user='sampleify_app' AND (NEW.updated_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid OR NEW.updated_at IS DISTINCT FROM transaction_timestamp()) THEN
    RAISE EXCEPTION 'Settings changes require the actual actor and time' USING ERRCODE='42501';
  END IF;
  IF NEW.result_summary_template_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.result_summary_template_id IS DISTINCT FROM OLD.result_summary_template_id)
    AND NOT EXISTS (SELECT 1 FROM public.templates template JOIN public.template_versions version
    ON version.organization_id=template.organization_id AND version.template_id=template.id
    WHERE template.organization_id=NEW.organization_id AND template.id=NEW.result_summary_template_id AND template.active AND version.kind='datasheet')
  THEN RAISE EXCEPTION 'Select an active datasheet summary template' USING ERRCODE='23514'; END IF;
  -- The source single control synchronizes both keys, including an unchanged
  -- historical selection that became unavailable. Never introduce a new one.
  IF TG_OP='UPDATE' THEN
    retained_common:=coalesce(NEW.test_request_workflow_id=NEW.job_workflow_id
      AND NEW.test_request_workflow_id IN (OLD.test_request_workflow_id,OLD.job_workflow_id),false);
  END IF;
  SELECT array_agg(DISTINCT selected.next_id) INTO selected_ids FROM unnest(
    ARRAY[NEW.test_request_workflow_id,NEW.job_workflow_id],
    CASE WHEN TG_OP='UPDATE' THEN ARRAY[OLD.test_request_workflow_id,OLD.job_workflow_id] ELSE ARRAY[NULL,NULL]::uuid[] END) selected(next_id,previous_id)
    WHERE selected.next_id IS NOT NULL AND selected.next_id IS DISTINCT FROM selected.previous_id AND NOT retained_common;
  IF cardinality(selected_ids)>0 THEN
    PERFORM 1 FROM public.workflows workflow WHERE workflow.organization_id=NEW.organization_id AND workflow.id=ANY(selected_ids)
      AND workflow.active AND workflow.applies_to='test_request' AND EXISTS (SELECT 1 FROM public.workflow_versions version
        WHERE version.organization_id=workflow.organization_id AND version.workflow_id=workflow.id AND version.status='published')
      ORDER BY workflow.id FOR SHARE OF workflow;
    GET DIAGNOSTICS matched=ROW_COUNT;
    IF matched<>cardinality(selected_ids) THEN
      RAISE EXCEPTION 'Select an active published test request workflow' USING ERRCODE='23514',CONSTRAINT='test_request_workflow_active_reference';
    END IF;
  END IF;
  SELECT array_agg(DISTINCT selected.next_id) INTO selected_ids FROM unnest(ARRAY[NEW.sample_workflow_base_id,NEW.sample_workflow_iqc_id,NEW.sample_workflow_ilc_id,NEW.sample_workflow_pt_id,NEW.sample_workflow_amendment_id,NEW.sample_workflow_complaint_id],
    CASE WHEN TG_OP='UPDATE' THEN ARRAY[OLD.sample_workflow_base_id,OLD.sample_workflow_iqc_id,OLD.sample_workflow_ilc_id,OLD.sample_workflow_pt_id,OLD.sample_workflow_amendment_id,OLD.sample_workflow_complaint_id] ELSE ARRAY[NULL,NULL,NULL,NULL,NULL,NULL]::uuid[] END) selected(next_id,previous_id)
    WHERE selected.next_id IS NOT NULL AND selected.next_id IS DISTINCT FROM selected.previous_id;
  IF cardinality(selected_ids)>0 THEN
    -- Acquire each workflow lock once, in a consistent order, and recheck after waiting.
    PERFORM 1 FROM public.workflows workflow WHERE workflow.organization_id=NEW.organization_id AND workflow.id=ANY(selected_ids)
      AND workflow.active AND workflow.applies_to='sample' AND EXISTS (SELECT 1 FROM public.workflow_versions version
        WHERE version.organization_id=workflow.organization_id AND version.workflow_id=workflow.id AND version.status='published')
      ORDER BY workflow.id FOR SHARE OF workflow;
    GET DIAGNOSTICS matched=ROW_COUNT;
    IF matched<>cardinality(selected_ids) THEN
      RAISE EXCEPTION 'Select an active published sample workflow' USING ERRCODE='23514',CONSTRAINT='sample_workflow_active_reference';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_specification_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_specification_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  PERFORM 1 FROM public.analytical_specifications WHERE organization_id = NEW.organization_id AND id = NEW.specification_id FOR UPDATE;
  IF EXISTS (SELECT 1 FROM public.test_requests WHERE organization_id = NEW.organization_id AND specification_id = NEW.specification_id)
    OR EXISTS (SELECT 1 FROM public.datasheets WHERE organization_id = NEW.organization_id AND specification_id = NEW.specification_id) THEN
    RAISE EXCEPTION 'A referenced analytical specification is frozen' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_submission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_submission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE sheet public.datasheets; capture public.template_instances; selected public.template_values;
  field public.template_fields; unit public.measurement_units; specification public.analytical_specifications;
  scalar_text text; expected_number integer; current_actor uuid := nullif(current_setting('app.user_id', true), '')::uuid;
BEGIN
  SELECT * INTO sheet FROM public.datasheets WHERE organization_id=NEW.organization_id AND id=NEW.datasheet_id;
  NEW.source_datasheet_id:=coalesce(NEW.source_datasheet_id,NEW.datasheet_id);
  IF NEW.source<>'result_widget' THEN
    NEW.specification_id:=coalesce(NEW.specification_id,sheet.specification_id);
    IF NEW.specification_id IS DISTINCT FROM sheet.specification_id THEN RAISE EXCEPTION 'Own result must retain its datasheet specification' USING ERRCODE='23514'; END IF;
  ELSE
    IF public.laboratory_group_submission_for_request(sheet.test_request_id) IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.job_result_entries entry JOIN public.datasheet_subjects subject ON subject.organization_id=entry.organization_id AND subject.id=entry.subject_id
      WHERE entry.organization_id=NEW.organization_id AND entry.id=NEW.job_result_entry_id AND entry.datasheet_id=NEW.source_datasheet_id
        AND entry.child_datasheet_id=NEW.datasheet_id AND entry.instance_id=NEW.instance_id AND entry.field_id=NEW.field_id
        AND entry.occurrence_id=NEW.occurrence_id AND entry.value_revision=NEW.value_revision AND subject.specification_id=NEW.specification_id
        AND subject.test_request_id=sheet.test_request_id
        AND entry.id=(SELECT candidate.id FROM public.job_result_entries candidate JOIN public.datasheet_subjects bound
          ON bound.organization_id=candidate.organization_id AND bound.id=candidate.subject_id
          WHERE candidate.organization_id=entry.organization_id AND candidate.datasheet_id=entry.datasheet_id AND bound.test_request_id=subject.test_request_id
          AND candidate.value_revision<=NEW.capture_revision ORDER BY candidate.value_revision DESC,candidate.position DESC LIMIT 1)
    ) THEN RAISE EXCEPTION 'Grouped result must pin the actual latest summary input and its scientific subject' USING ERRCODE='23514'; END IF;
  END IF;
  SELECT * INTO capture FROM public.template_instances WHERE organization_id=NEW.organization_id AND id=NEW.instance_id;
  SELECT * INTO selected FROM public.template_values WHERE organization_id=NEW.organization_id AND instance_id=NEW.instance_id
    AND field_id=NEW.field_id AND occurrence_id=NEW.occurrence_id AND revision<=NEW.capture_revision AND (NEW.source<>'result_widget' OR revision=NEW.value_revision) ORDER BY revision DESC LIMIT 1;
  SELECT * INTO field FROM public.template_fields WHERE organization_id=NEW.organization_id AND version_id=NEW.version_id AND id=NEW.field_id;
  SELECT coalesce(max(number),0)+1 INTO expected_number FROM public.datasheet_submissions WHERE organization_id=NEW.organization_id AND datasheet_id=NEW.datasheet_id;
  IF sheet.id IS NULL OR capture.id IS NULL OR field.id IS NULL OR selected.field_id IS NULL
    OR NOT EXISTS (SELECT 1 FROM public.datasheets source WHERE source.organization_id=NEW.organization_id AND source.id=NEW.source_datasheet_id AND source.template_instance_id=NEW.instance_id) OR capture.version_id IS DISTINCT FROM NEW.version_id
    OR capture.status<>'frozen' OR NEW.capture_revision<>capture.revision OR NEW.number<>expected_number
    OR selected.revision IS DISTINCT FROM NEW.value_revision OR selected.state NOT IN ('present','not_applicable')
    OR (NEW.source<>'result_widget' AND NOT EXISTS (SELECT 1 FROM public.template_occurrences WHERE organization_id=NEW.organization_id AND instance_id=NEW.instance_id
      AND id=NEW.occurrence_id AND created_revision<=NEW.capture_revision AND (removed_revision IS NULL OR removed_revision>NEW.capture_revision))) THEN
    RAISE EXCEPTION 'Submission must pin the current frozen capture and its latest active value' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.template_columns column_detail JOIN public.template_rows row_detail
    ON row_detail.organization_id=column_detail.organization_id AND row_detail.version_id=column_detail.version_id AND row_detail.id=column_detail.row_id
    JOIN public.template_sections section ON section.organization_id=row_detail.organization_id AND section.version_id=row_detail.version_id AND section.id=row_detail.section_id
    WHERE column_detail.organization_id=NEW.organization_id AND column_detail.version_id=NEW.version_id AND column_detail.id=field.column_id
      AND ((NEW.source='result_widget' AND field.widget='result_widget') OR (NEW.source='column' AND column_detail.is_final_result) OR (NEW.source='section' AND section.is_final_result AND field.widget IN ('input_widget','formula_widget','result_widget')))) THEN
    RAISE EXCEPTION 'The selected value is not a final result in this template version' USING ERRCODE = '23514';
  END IF;
  IF selected.state='not_applicable' THEN scalar_text := 'NA';
  ELSIF selected.value_type IN ('text','result') AND selected.text_value IS NOT NULL THEN scalar_text := selected.text_value;
  ELSIF selected.value_type='date' THEN scalar_text := selected.date_value::text;
  ELSIF selected.value_type='option' THEN
    SELECT value INTO scalar_text FROM public.template_options WHERE organization_id=NEW.organization_id AND version_id=NEW.version_id AND field_id=NEW.field_id AND id=selected.option_id;
  END IF;
  IF selected.state='present' AND selected.value_type='boolean' THEN
    IF NEW.result_type<>'boolean' OR NEW.boolean_value IS DISTINCT FROM selected.boolean_value THEN RAISE EXCEPTION 'Submitted boolean differs from recorded value' USING ERRCODE='23514'; END IF;
  ELSIF selected.state='present' AND selected.value_type IN ('numeric','result') AND selected.number_value IS NOT NULL THEN
    IF NEW.result_type<>'numeric' OR NEW.number_value IS DISTINCT FROM selected.number_value THEN RAISE EXCEPTION 'Submitted number differs from recorded value' USING ERRCODE='23514'; END IF;
  ELSIF btrim(scalar_text) ~ '^-?[0-9]+([.][0-9]+)?$' THEN
    IF NEW.result_type<>'numeric' OR NEW.number_value IS DISTINCT FROM btrim(scalar_text)::numeric THEN RAISE EXCEPTION 'Submitted number differs from recorded text' USING ERRCODE='23514'; END IF;
  ELSE
    IF NEW.result_type<>'text' OR NEW.text_value IS DISTINCT FROM scalar_text THEN RAISE EXCEPTION 'Submitted text differs from recorded value' USING ERRCODE='23514'; END IF;
  END IF;
  IF NEW.measurement_unit_id IS NOT NULL THEN
    SELECT * INTO specification FROM public.analytical_specifications WHERE organization_id=NEW.organization_id AND id=NEW.specification_id;
    IF NEW.measurement_unit_id=specification.measurement_unit_id THEN
      IF (NEW.unit_revision,NEW.unit_code,NEW.unit_name,NEW.unit_symbol,NEW.unit_dimension) IS DISTINCT FROM
        (specification.unit_revision,specification.unit_code,specification.unit_name,specification.unit_symbol,specification.unit_dimension) THEN
        RAISE EXCEPTION 'Submitted unit must retain the pinned scientific specification' USING ERRCODE='23514';
      END IF;
    ELSE
      SELECT * INTO unit FROM public.measurement_units WHERE organization_id=NEW.organization_id AND id=NEW.measurement_unit_id FOR SHARE;
      IF unit.id IS NULL OR NOT unit.active OR (NEW.unit_revision,NEW.unit_code,NEW.unit_name,NEW.unit_symbol,NEW.unit_dimension) IS DISTINCT FROM
        (unit.revision,unit.code,unit.name,unit.symbol,unit.dimension) THEN RAISE EXCEPTION 'Submitted unit snapshot is invalid' USING ERRCODE='23514'; END IF;
    END IF;
  END IF;
  IF session_user='sampleify_app' THEN
    IF NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id', true), '')::uuid OR NEW.submitted_by IS DISTINCT FROM current_actor
      OR NOT public.app_has_permission('datasheets.execute') OR sheet.status NOT IN ('in_progress','rejected')
      OR (public.laboratory_group_submission_for_request(sheet.test_request_id) IS NULL AND NOT EXISTS (SELECT 1 FROM public.test_request_assignments WHERE organization_id=NEW.organization_id AND test_request_id=sheet.test_request_id
        AND assignment_type='analyst' AND assigned_user_id=current_actor AND unassigned_at IS NULL))
      OR NOT EXISTS (SELECT 1 FROM public.template_instances WHERE organization_id=NEW.organization_id AND id=NEW.instance_id AND xmin::text=pg_current_xact_id()::text)
      OR NOT EXISTS (SELECT 1 FROM public.test_requests WHERE organization_id=NEW.organization_id AND id=sheet.test_request_id AND status IN ('allocated','in_progress','rejected'))
      OR EXISTS (SELECT 1 FROM public.approval_cases approval JOIN public.workflow_runs run ON run.organization_id=approval.organization_id AND run.id=approval.workflow_run_id
        WHERE run.organization_id=NEW.organization_id AND run.test_request_id=sheet.test_request_id AND approval.status='pending') THEN
      RAISE EXCEPTION 'Only the assigned analyst can submit an open datasheet' USING ERRCODE='42501';
    END IF;
    NEW.submitted_at := now();
  END IF;
  RETURN NEW;
END $_$;


--
-- Name: laboratory_guard_submission_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_submission_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF session_user='sampleify_app' AND NEW.latest_submission_id IS DISTINCT FROM OLD.latest_submission_id THEN
    IF NEW.status<>'under_review' OR NOT EXISTS (SELECT 1 FROM public.datasheet_submissions WHERE organization_id=NEW.organization_id AND datasheet_id=NEW.id
      AND id=NEW.latest_submission_id AND submitted_by=nullif(current_setting('app.user_id', true), '')::uuid AND xmin::text=pg_current_xact_id()::text) THEN
      RAISE EXCEPTION 'Current result must be an actual new submission' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_test_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_test_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE specification public.analytical_specifications; selected public.sample_tests; job public.test_requests;
BEGIN
  IF TG_OP='UPDATE' THEN
    IF (NEW.sample_test_id,NEW.specification_id,NEW.request_number,NEW.attempt_number,NEW.created_by,NEW.created_at,NEW.is_job,NEW.is_auto_created,NEW.job_sample_product_id)
      IS DISTINCT FROM (OLD.sample_test_id,OLD.specification_id,OLD.request_number,OLD.attempt_number,OLD.created_by,OLD.created_at,OLD.is_job,OLD.is_auto_created,OLD.job_sample_product_id)
      OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'Test request identity is immutable and revisions are sequential' USING ERRCODE='23514'; END IF;
    IF (NEW.parent_test_request_id,NEW.job_member_position,NEW.job_linked_by,NEW.job_linked_at)
      IS DISTINCT FROM (OLD.parent_test_request_id,OLD.job_member_position,OLD.job_linked_by,OLD.job_linked_at) THEN
      SELECT * INTO job FROM public.test_requests WHERE organization_id=NEW.organization_id AND id=NEW.parent_test_request_id FOR UPDATE;
      IF OLD.parent_test_request_id IS NOT NULL OR NEW.parent_test_request_id IS NULL OR OLD.status<>'created' OR NEW.is_job
        OR NOT (public.app_has_permission('test_requests.allocate') OR coalesce(job.is_auto_created AND public.laboratory_new_generated_request(NEW.id),false))
        OR (job.is_auto_created AND NOT public.laboratory_new_generated_request(NEW.id))
        OR NEW.job_linked_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid OR NEW.job_linked_at IS DISTINCT FROM transaction_timestamp()
        OR EXISTS (SELECT 1 FROM public.test_request_assignments WHERE organization_id=NEW.organization_id AND test_request_id=NEW.id AND assignment_type='analyst' AND unassigned_at IS NULL)
      THEN RAISE EXCEPTION 'Only an unallocated request can join a new job' USING ERRCODE='42501'; END IF;
      IF NOT coalesce(job.is_job,false) OR job.created_at IS DISTINCT FROM transaction_timestamp() OR job.created_by IS DISTINCT FROM NEW.job_linked_by
        OR NOT EXISTS (SELECT 1 FROM public.sample_tests WHERE organization_id=NEW.organization_id AND id=NEW.sample_test_id AND sample_product_id=job.job_sample_product_id)
      THEN RAISE EXCEPTION 'Job members must belong to the same product line and creation action' USING ERRCODE='23514'; END IF;
    END IF;
    IF NEW.datasheet_template_id IS DISTINCT FROM OLD.datasheet_template_id AND
      (OLD.datasheet_template_id IS NOT NULL OR NEW.datasheet_template_id IS NULL OR NOT (public.app_has_permission('test_requests.allocate') OR coalesce(NEW.id=public.laboratory_auto_job_request(),false))
        OR NOT EXISTS (SELECT 1 FROM public.datasheets sheet JOIN public.template_instances capture
          ON capture.organization_id=sheet.organization_id AND capture.id=sheet.template_instance_id
          JOIN public.template_versions version ON version.organization_id=capture.organization_id AND version.id=capture.version_id
          WHERE sheet.organization_id=NEW.organization_id AND sheet.test_request_id=NEW.id AND sheet.attempt_number=1 AND version.template_id=NEW.datasheet_template_id))
    THEN RAISE EXCEPTION 'A request template can only be selected during its first allocation' USING ERRCODE='23514'; END IF;
  ELSE
    IF NEW.status<>'created' OR NEW.revision<>1 OR NEW.parent_test_request_id IS NOT NULL THEN
      RAISE EXCEPTION 'Test requests start as ungrouped created records' USING ERRCODE='23514';
    END IF;
    IF NEW.is_job THEN
      IF NOT (public.app_has_permission('test_requests.allocate') OR coalesce(NEW.is_auto_created AND public.laboratory_job_generation_sample((SELECT sample_id FROM public.sample_products WHERE organization_id=NEW.organization_id AND id=NEW.job_sample_product_id)),false)) OR NEW.created_at IS DISTINCT FROM transaction_timestamp()
        OR NEW.created_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid OR NEW.attempt_number<>1
      THEN RAISE EXCEPTION 'Job creation requires allocation permission and actual provenance' USING ERRCODE='42501'; END IF;
    ELSE
      SELECT * INTO specification FROM public.analytical_specifications WHERE organization_id=NEW.organization_id AND id=NEW.specification_id FOR SHARE;
      SELECT * INTO selected FROM public.sample_tests WHERE organization_id=NEW.organization_id AND id=NEW.sample_test_id;
      IF specification.id IS NULL OR selected.id IS NULL OR (specification.test_parameter_id,specification.method_id,specification.decision_rule_id)
        IS DISTINCT FROM (selected.test_parameter_id,selected.method_id,selected.decision_rule_id)
      THEN RAISE EXCEPTION 'Analytical specification does not match the selected test' USING ERRCODE='23514'; END IF;
    END IF;
  END IF;
  NEW.updated_at:=now();
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_workflow_definition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_workflow_definition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid; ver uuid; state_id uuid; state text;
BEGIN
  IF TG_OP = 'DELETE' THEN org := OLD.organization_id; ELSE org := NEW.organization_id; END IF;
  IF TG_TABLE_NAME = 'workflow_states' THEN
    IF TG_OP = 'DELETE' THEN ver := OLD.workflow_version_id; ELSE ver := NEW.workflow_version_id; END IF;
    IF TG_OP = 'UPDATE' AND NEW.workflow_version_id IS DISTINCT FROM OLD.workflow_version_id THEN
      RAISE EXCEPTION 'Workflow state ownership is immutable' USING ERRCODE = '23514';
    END IF;
  ELSE
    IF TG_OP = 'DELETE' THEN state_id := OLD.workflow_state_id; ELSE state_id := NEW.workflow_state_id; END IF;
    IF TG_OP = 'UPDATE' AND (NEW.organization_id, NEW.workflow_state_id) IS DISTINCT FROM (OLD.organization_id, OLD.workflow_state_id) THEN
      RAISE EXCEPTION 'Workflow capability ownership is immutable' USING ERRCODE = '23514';
    END IF;
    SELECT workflow_version_id INTO ver FROM public.workflow_states WHERE organization_id = org AND id = state_id;
  END IF;
  SELECT status INTO state FROM public.workflow_versions WHERE organization_id = org AND id = ver FOR UPDATE;
  IF state IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'Only draft workflow definitions may change' USING ERRCODE = '55000'; END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_workflow_publication(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_workflow_publication() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.status = 'published' AND OLD.status = 'draft' THEN
    IF (SELECT count(*) FROM public.workflow_states WHERE organization_id = NEW.organization_id AND workflow_version_id = NEW.id AND state_type = 'final') <> 1 THEN
      RAISE EXCEPTION 'Published workflow requires exactly one final state' USING ERRCODE = '23514';
    END IF;
    IF EXISTS (SELECT 1 FROM public.workflow_states s WHERE s.organization_id = NEW.organization_id AND s.workflow_version_id = NEW.id
      AND s.state_type IN ('initial', 'normal') AND NOT EXISTS (SELECT 1 FROM public.workflow_transitions t
        WHERE t.organization_id = s.organization_id AND t.workflow_version_id = s.workflow_version_id AND t.source_state_id = s.id)) THEN
      RAISE EXCEPTION 'Every initial or normal state requires an outgoing transition' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_workflow_run(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_workflow_run() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE owner_type text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT w.applies_to INTO owner_type FROM public.workflow_versions v JOIN public.workflows w
      ON w.organization_id = v.organization_id AND w.id = v.workflow_id
      JOIN public.workflow_states s ON s.organization_id = v.organization_id AND s.workflow_version_id = v.id
      WHERE v.organization_id = NEW.organization_id AND v.id = NEW.workflow_version_id AND v.status = 'published' AND w.active
        AND s.id = NEW.current_state_id AND s.state_type = 'initial';
    IF owner_type IS DISTINCT FROM (CASE WHEN NEW.sample_id IS NOT NULL THEN 'sample' WHEN NEW.document_id IS NOT NULL THEN 'document' ELSE 'test_request' END)
      OR NEW.revision <> 1 OR NEW.status <> 'active' THEN
      RAISE EXCEPTION 'Workflow run requires a published initial state for its owner type' USING ERRCODE = '23514';
    END IF;
  ELSE
    IF (NEW.workflow_version_id, NEW.sample_id, NEW.test_request_id, NEW.document_id, NEW.started_by, NEW.started_at)
      IS DISTINCT FROM (OLD.workflow_version_id, OLD.sample_id, OLD.test_request_id, OLD.document_id, OLD.started_by, OLD.started_at)
      OR NEW.revision <> OLD.revision + 1 THEN RAISE EXCEPTION 'Workflow run identity is immutable and revisions are sequential' USING ERRCODE = '23514'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_workflow_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_workflow_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid; ver uuid; state text;
BEGIN
  IF TG_OP = 'DELETE' THEN org := OLD.organization_id; ver := OLD.workflow_version_id;
  ELSE org := NEW.organization_id; ver := NEW.workflow_version_id; END IF;
  IF TG_OP = 'UPDATE' AND NEW.workflow_version_id IS DISTINCT FROM OLD.workflow_version_id THEN
    RAISE EXCEPTION 'Workflow transition ownership is immutable' USING ERRCODE = '23514';
  END IF;
  SELECT status INTO state FROM public.workflow_versions WHERE organization_id = org AND id = ver FOR UPDATE;
  IF state IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'Only draft workflow transitions may change' USING ERRCODE = '55000'; END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_guard_workflow_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_guard_workflow_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' OR NEW.revision <> 1 THEN RAISE EXCEPTION 'Workflow versions start as drafts' USING ERRCODE = '23514'; END IF;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN RAISE EXCEPTION 'Published workflow history cannot be deleted' USING ERRCODE = '55000'; END IF;
    RETURN OLD;
  ELSE
    IF (NEW.workflow_id, NEW.number, NEW.created_by, NEW.created_at) IS DISTINCT FROM (OLD.workflow_id, OLD.number, OLD.created_by, OLD.created_at)
      OR NEW.revision <> OLD.revision + 1 THEN RAISE EXCEPTION 'Workflow identity is immutable and revisions are sequential' USING ERRCODE = '23514'; END IF;
    IF OLD.status <> 'draft' AND (OLD.status <> 'published' OR NEW.status <> 'retired'
      OR (NEW.change_summary, NEW.published_at, NEW.published_by) IS DISTINCT FROM (OLD.change_summary, OLD.published_at, OLD.published_by)) THEN
      RAISE EXCEPTION 'Published workflow versions are immutable' USING ERRCODE = '55000';
    END IF;
  END IF;
  IF NEW.status = 'published' AND NOT EXISTS (SELECT 1 FROM public.workflow_states
    WHERE organization_id = NEW.organization_id AND workflow_version_id = NEW.id AND state_type = 'initial') THEN
    RAISE EXCEPTION 'Published workflow requires an initial state' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_job_generation_sample(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_job_generation_sample(p_sample_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid; current_state uuid; generates boolean;
BEGIN
  IF org IS NULL OR actor IS NULL OR p_sample_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.sample_events event WHERE event.organization_id=org AND event.sample_id=p_sample_id
      AND event.event_type='test_requests_generated' AND event.actor_user_id=actor AND event.occurred_at=transaction_timestamp()
      AND event.xmin::text=pg_current_xact_id()::text) THEN RETURN false; END IF;
  IF p_sample_id IS NOT DISTINCT FROM public.workflow_generating_sample() THEN RETURN true; END IF;
  IF public.app_has_permission('samples.create') AND EXISTS (SELECT 1 FROM public.samples sample
    JOIN public.workflow_runs run ON run.organization_id=sample.organization_id AND run.sample_id=sample.id
    JOIN public.workflow_run_history history ON history.organization_id=run.organization_id AND history.workflow_run_id=run.id AND history.action='started'
    JOIN public.workflow_states state ON state.organization_id=history.organization_id AND state.id=history.to_state_id
    WHERE sample.organization_id=org AND sample.id=p_sample_id AND sample.registered_by=actor AND sample.registered_at=transaction_timestamp()
      AND sample.xmin::text=pg_current_xact_id()::text AND history.actor_user_id=actor AND history.occurred_at=transaction_timestamp()
      AND state.state_type='initial' AND state.generate_test_requests) THEN RETURN true; END IF;
  IF NOT (public.app_has_permission('samples.manage') OR public.app_has_permission('test_requests.allocate')) THEN RETURN false; END IF;
  SELECT run.current_state_id,state.generate_test_requests INTO current_state,generates FROM public.workflow_runs run
    JOIN public.workflow_states state ON state.organization_id=run.organization_id AND state.id=run.current_state_id
    WHERE run.organization_id=org AND run.sample_id=p_sample_id;
  IF NOT EXISTS (SELECT 1 FROM public.workflow_state_capability_roles WHERE organization_id=org AND workflow_state_id=current_state AND capability='allocate') THEN RETURN true; END IF;
  RETURN coalesce(generates,false) AND EXISTS (SELECT 1 FROM public.workflow_state_capability_roles capability
    JOIN public.membership_roles role ON role.organization_id=capability.organization_id AND role.role_id=capability.role_id
    WHERE capability.organization_id=org AND capability.workflow_state_id=current_state AND capability.capability='allocate' AND role.user_id=actor);
END $$;


--
-- Name: laboratory_job_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_job_settings() RETURNS TABLE(auto_create_jobs boolean, result_summary_template_id uuid, job_workflow_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  IF org IS NULL OR NOT public.app_has_permission('test_requests.allocate') THEN
    RAISE EXCEPTION 'Job allocation permission required' USING ERRCODE='42501';
  END IF;
  RETURN QUERY SELECT settings.auto_create_jobs,settings.result_summary_template_id,settings.job_workflow_id
    FROM public.organization_laboratory_settings settings WHERE settings.organization_id=org FOR SHARE;
END $$;


--
-- Name: laboratory_lock_datasheet(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_lock_datasheet(sheet_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; request_id uuid; capture_id uuid;
BEGIN
  IF org IS NULL OR NOT public.app_has_permission('datasheets.execute') THEN RAISE EXCEPTION 'Datasheet execution permission required' USING ERRCODE='42501'; END IF;
  SELECT test_request_id INTO request_id FROM public.datasheets WHERE organization_id=org AND id=sheet_id;
  IF request_id IS NULL THEN RETURN false; END IF;
  PERFORM public.laboratory_lock_request_sample(request_id);
  PERFORM 1 FROM public.test_requests WHERE organization_id=org AND id=request_id FOR UPDATE;
  SELECT template_instance_id INTO capture_id FROM public.datasheets WHERE organization_id=org AND id=sheet_id FOR UPDATE;
  PERFORM 1 FROM public.template_instances WHERE organization_id=org AND id=capture_id FOR UPDATE;
  RETURN true;
END $$;


--
-- Name: laboratory_lock_job_members(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_lock_job_members(sheet_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; job_id uuid;
BEGIN
  SELECT job.id INTO job_id FROM public.datasheets sheet JOIN public.test_requests job ON job.organization_id=sheet.organization_id AND job.id=sheet.test_request_id AND job.is_job
    WHERE sheet.organization_id=org AND sheet.id=sheet_id;
  IF job_id IS NULL OR NOT public.laboratory_request_can_work(job_id) THEN RAISE EXCEPTION 'Current assigned job access required' USING ERRCODE='42501'; END IF;
  PERFORM public.laboratory_lock_request_sample(job_id);
  PERFORM 1 FROM public.test_requests WHERE organization_id=org AND parent_test_request_id=job_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.datasheets sheet JOIN public.test_requests child ON child.organization_id=sheet.organization_id AND child.id=sheet.test_request_id
    WHERE child.organization_id=org AND child.parent_test_request_id=job_id ORDER BY sheet.id FOR UPDATE OF sheet;
  PERFORM 1 FROM public.template_instances capture JOIN public.datasheets sheet ON sheet.organization_id=capture.organization_id AND sheet.template_instance_id=capture.id
    JOIN public.test_requests child ON child.organization_id=sheet.organization_id AND child.id=sheet.test_request_id
    WHERE child.organization_id=org AND child.parent_test_request_id=job_id ORDER BY capture.id FOR UPDATE OF capture;
END $$;


--
-- Name: laboratory_lock_references(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_lock_references(relation_name text, record_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE org uuid := nullif(current_setting('app.organization_id', true), '')::uuid; key_column text := 'id';
BEGIN
  IF org IS NULL OR NOT (public.laboratory_can_read() OR public.app_has_permission('samples.create') OR public.app_has_permission('masters.manage')) THEN
    RAISE EXCEPTION 'Laboratory reference permission required' USING ERRCODE = '42501';
  END IF;
  IF relation_name IS NULL OR relation_name NOT IN ('sample_categories', 'customers', 'customer_quotations', 'products', 'product_sample_categories',
    'test_parameters', 'methods_of_analysis', 'parameter_methods', 'decision_rules', 'measurement_units', 'laboratories', 'tags', 'product_tags')
    OR record_ids IS NULL OR cardinality(record_ids) > 5000 OR array_position(record_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid scientific reference selection' USING ERRCODE = '23514';
  END IF;
  IF relation_name IN ('product_sample_categories', 'product_tags') THEN key_column := 'product_id'; END IF;
  IF relation_name = 'parameter_methods' THEN key_column := 'test_parameter_id'; END IF;
  EXECUTE format('SELECT 1 FROM public.%I WHERE organization_id = $1 AND %I = ANY($2) ORDER BY %I FOR SHARE', relation_name, key_column, key_column)
    USING org, record_ids;
END $_$;


--
-- Name: laboratory_lock_request_sample(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_lock_request_sample(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  IF org IS NULL OR NOT public.laboratory_can_read() THEN RAISE EXCEPTION 'Laboratory permission required' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.test_requests request
    JOIN public.laboratory_test_request_context product ON product.organization_id=request.organization_id AND product.test_request_id=request.id
    JOIN public.samples sample ON sample.organization_id=product.organization_id AND sample.id=product.sample_id
    WHERE request.organization_id=org AND request.id=p_request_id FOR KEY SHARE OF sample;
END $$;


--
-- Name: laboratory_lock_sample(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_lock_sample(sample_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid := nullif(current_setting('app.organization_id', true), '')::uuid;
BEGIN
  IF org IS NULL OR NOT (public.app_has_permission('samples.manage') OR public.app_has_permission('test_requests.allocate')
    OR sample_id IS NOT DISTINCT FROM public.laboratory_registering_sample() AND sample_id IS NOT NULL
    OR sample_id IS NOT DISTINCT FROM public.workflow_generating_sample() AND sample_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Sample allocation permission required' USING ERRCODE = '42501';
  END IF;
  PERFORM 1 FROM public.samples WHERE organization_id = org AND id = sample_id FOR UPDATE;
  RETURN FOUND;
END $$;


--
-- Name: laboratory_new_generated_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_new_generated_request(p_request_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.test_requests request JOIN public.sample_tests selected
    ON selected.organization_id=request.organization_id AND selected.id=request.sample_test_id
    JOIN public.sample_products product ON product.organization_id=selected.organization_id AND product.id=selected.sample_product_id
    WHERE request.organization_id=nullif(current_setting('app.organization_id',true),'')::uuid AND request.id=p_request_id AND NOT request.is_job
      AND request.created_by=nullif(current_setting('app.user_id',true),'')::uuid AND request.created_at=transaction_timestamp()
      AND request.xmin::text=pg_current_xact_id()::text AND public.laboratory_job_generation_sample(product.sample_id))
$$;


--
-- Name: laboratory_next_number(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_next_number(sequence_name text, period text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE org uuid := nullif(current_setting('app.organization_id', true), '')::uuid; next_number bigint; result_prefix text; width integer;
BEGIN
  IF org IS NULL OR sequence_name IS NULL OR period IS NULL OR period !~ '^[0-9]{4}$'
    OR sequence_name NOT IN ('sample', 'test_request', 'job') THEN RAISE EXCEPTION 'Invalid number sequence' USING ERRCODE = '23514'; END IF;
  IF NOT (sequence_name = 'sample' AND public.app_has_permission('samples.create')
    OR sequence_name <> 'sample' AND (public.app_has_permission('samples.manage') OR public.app_has_permission('test_requests.allocate') OR public.laboratory_registering_sample() IS NOT NULL OR (sequence_name IN ('test_request','job') AND public.workflow_generating_sample() IS NOT NULL))) THEN
    RAISE EXCEPTION 'Number allocation permission required' USING ERRCODE = '42501';
  END IF;
  result_prefix := CASE sequence_name WHEN 'sample' THEN 'SMP-' WHEN 'test_request' THEN 'TR-' ELSE 'JOB-' END || period || '-';
  INSERT INTO public.number_sequences (organization_id, sequence_key, period_key, prefix, minimum_width)
    VALUES (org, sequence_name, period, result_prefix, CASE sequence_name WHEN 'job' THEN 4 ELSE 6 END) ON CONFLICT DO NOTHING;
  UPDATE public.number_sequences SET next_value = next_value + 1 WHERE organization_id = org AND sequence_key = sequence_name AND period_key = period
    RETURNING next_value - 1, prefix, minimum_width INTO next_number, result_prefix, width;
  RETURN result_prefix || lpad(next_number::text, greatest(width, length(next_number::text)), '0');
END $_$;


--
-- Name: laboratory_parameter_context_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_parameter_context_scope() RETURNS TABLE(organization_id uuid, report_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid; selected_report uuid; selected_sample uuid;
BEGIN
  IF session_user NOT IN ('sampleify_app','sampleify_report_worker') THEN RETURN; END IF;
  org:=nullif(current_setting('app.organization_id',true),'')::uuid;
  PERFORM 1 FROM public.memberships membership JOIN public.users person ON person.id=membership.user_id
    JOIN public.organizations organization ON organization.id=membership.organization_id
    WHERE membership.organization_id=org AND membership.user_id=nullif(current_setting('app.user_id',true),'')::uuid
      AND membership.active AND person.active AND organization.active;
  IF NOT FOUND THEN RETURN; END IF;
  IF session_user='sampleify_app' THEN
    IF org IS NOT NULL AND public.laboratory_can_read() THEN RETURN QUERY SELECT org,NULL::uuid; END IF;
  ELSIF session_user='sampleify_report_worker' THEN
    org:=public.report_pdf_context_org();
    IF org IS NULL THEN RETURN; END IF;
    SELECT report.id,report.sample_id INTO selected_report,selected_sample FROM public.report_pdf_jobs job
      JOIN public.sample_reports report ON report.organization_id=job.organization_id AND report.id=job.report_id
      WHERE job.organization_id=org AND job.id=nullif(current_setting('app.report_pdf_job_id',true),'')::uuid;
    IF selected_report IS NOT NULL
      AND (public.app_has_permission('samples.read') OR public.app_has_permission('samples.manage'))
      AND public.report_can_print(selected_sample) THEN RETURN QUERY SELECT org,selected_report; END IF;
  END IF;
END $$;


--
-- Name: laboratory_parameter_read_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_parameter_read_scope() RETURNS TABLE(organization_id uuid, report_id uuid, specification_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; selected_specification uuid;
BEGIN
  RETURN QUERY SELECT scope.organization_id,scope.report_id,NULL::uuid FROM public.laboratory_parameter_context_scope() scope;
  IF FOUND OR session_user<>'sampleify_app' OR NOT public.app_has_permission('samples.create') THEN RETURN; END IF;
  PERFORM 1 FROM public.memberships membership JOIN public.users person ON person.id=membership.user_id
    JOIN public.organizations organization ON organization.id=membership.organization_id
    WHERE membership.organization_id=org AND membership.user_id=nullif(current_setting('app.user_id',true),'')::uuid
      AND membership.active AND person.active AND organization.active;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT request.specification_id INTO selected_specification FROM public.test_requests request
    WHERE request.organization_id=org AND request.id=public.laboratory_auto_job_request();
  IF selected_specification IS NOT NULL THEN RETURN QUERY SELECT org,NULL::uuid,selected_specification; END IF;
END $$;


