--
-- Name: laboratory_product_job_templates(uuid, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_product_job_templates(p_sample_id uuid, product_line_ids uuid[], automatic boolean) RETURNS TABLE(sample_product_id uuid, template_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  settings public.organization_laboratory_settings;
BEGIN
  IF org IS NULL OR automatic IS NULL OR p_sample_id IS NULL
    OR NOT (CASE WHEN automatic THEN public.laboratory_job_generation_sample(p_sample_id) ELSE public.app_has_permission('test_requests.allocate') END)
  THEN RAISE EXCEPTION 'Job allocation or actual generation is required' USING ERRCODE='42501'; END IF;
  IF product_line_ids IS NULL OR cardinality(product_line_ids) NOT BETWEEN 1 AND 500 OR array_position(product_line_ids,NULL) IS NOT NULL
    OR (SELECT count(DISTINCT selected_id) FROM unnest(product_line_ids) selected_id)<>cardinality(product_line_ids)
  THEN RAISE EXCEPTION 'Select distinct product lines for one sample' USING ERRCODE='23514'; END IF;
  PERFORM 1 FROM public.samples WHERE organization_id=org AND id=p_sample_id FOR UPDATE;
  IF NOT FOUND OR (SELECT count(*) FROM public.sample_products line WHERE line.organization_id=org AND line.sample_id=p_sample_id
    AND line.id=ANY(product_line_ids))<>cardinality(product_line_ids)
  THEN RAISE EXCEPTION 'The selected product lines are unavailable' USING ERRCODE='23514'; END IF;
  PERFORM 1 FROM public.products product WHERE product.organization_id=org AND product.id IN
    (SELECT line.product_id FROM public.sample_products line WHERE line.organization_id=org AND line.sample_id=p_sample_id AND line.id=ANY(product_line_ids))
    ORDER BY product.id FOR SHARE;
  SELECT * INTO settings FROM public.organization_laboratory_settings WHERE organization_id=org FOR SHARE;
  -- A configured organization template takes precedence even if unavailable.
  -- Existing sample references remain usable after a Product is retired.
  RETURN QUERY SELECT line.id,CASE WHEN (NOT automatic OR coalesce(settings.auto_create_jobs,false)) AND template.active AND latest.kind='datasheet' THEN template.id END
    FROM public.sample_products line JOIN public.products product ON product.organization_id=line.organization_id AND product.id=line.product_id
    LEFT JOIN public.templates template ON template.organization_id=line.organization_id AND template.id=coalesce(settings.result_summary_template_id,product.job_template_id)
    LEFT JOIN LATERAL (SELECT version.kind FROM public.template_versions version WHERE version.organization_id=template.organization_id AND version.template_id=template.id
      AND version.status<>'building' ORDER BY (version.status='draft') DESC,version.number DESC LIMIT 1) latest ON true
    WHERE line.organization_id=org AND line.sample_id=p_sample_id AND line.id=ANY(product_line_ids) ORDER BY line.id;
END $$;


--
-- Name: laboratory_quick_customer(text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_quick_customer(display_name text, legal_name text, contact_name text, contact_email text, contact_phone text, billing_address text, shipping_address text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE org uuid := nullif(current_setting('app.organization_id', true), '')::uuid;
  created_customer_id uuid := gen_random_uuid(); customer_code text;
BEGIN
  PERFORM public.organization_require_module_access('customer');
  IF org IS NULL OR NOT public.app_has_permission('samples.create') THEN
    RAISE EXCEPTION 'Sample registration permission required' USING ERRCODE = '42501';
  END IF;
  IF NOT coalesce(length(trim(display_name)) BETWEEN 1 AND 250 AND length(trim(legal_name)) BETWEEN 1 AND 250
    AND length(trim(contact_name)) BETWEEN 1 AND 200 AND length(trim(contact_email)) BETWEEN 3 AND 320
    AND trim(contact_email) ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
    AND length(trim(contact_phone)) BETWEEN 1 AND 50 AND length(trim(billing_address)) BETWEEN 1 AND 4000
    AND length(trim(shipping_address)) BETWEEN 1 AND 4000, false) THEN
    RAISE EXCEPTION 'Complete the customer contact and address fields' USING ERRCODE = '23514';
  END IF;
  customer_code := left(trim(both '-' from regexp_replace(upper(trim(display_name)), '[^A-Z0-9._/-]+', '-', 'g')), 64);
  IF customer_code = '' THEN customer_code := 'CUSTOMER'; END IF;
  INSERT INTO public.customers(organization_id, id, code, name, legal_name, credit_days,save_request_id,save_source)
    VALUES (org, created_customer_id, customer_code, trim(display_name), trim(legal_name), 30,gen_random_uuid(),'registration');
  INSERT INTO public.customer_contacts(organization_id, customer_id, name, email, phone, is_primary)
    VALUES (org, created_customer_id, trim(contact_name), trim(contact_email), trim(contact_phone), true);
  INSERT INTO public.customer_addresses(organization_id, customer_id, address_type, freeform_address, is_default)
    VALUES (org, created_customer_id, 'billing', trim(billing_address), true), (org, created_customer_id, 'shipping', trim(shipping_address), true);
  PERFORM public.masters_record_customer(created_customer_id,NULL,'create',NULL,
    ARRAY(SELECT address.id FROM public.customer_addresses address WHERE address.organization_id=org AND address.customer_id=created_customer_id ORDER BY address.id),
    ARRAY(SELECT contact.id FROM public.customer_contacts contact WHERE contact.organization_id=org AND contact.customer_id=created_customer_id ORDER BY contact.id));
  RETURN created_customer_id;
END $_$;


--
-- Name: laboratory_record_job_results(uuid, uuid[], uuid[], integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_record_job_results(capture_id uuid, field_ids uuid[], occurrence_ids uuid[], positions integer[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  sheet public.datasheets; capture public.template_instances; selected public.template_values;
  subject public.datasheet_subjects; member_sheet uuid; item record; recorded integer:=0;
BEGIN
  IF capture_id IS DISTINCT FROM nullif(current_setting('app.capture_id',true),'')::uuid OR NOT public.laboratory_capture_can_write() THEN
    RAISE EXCEPTION 'Current assigned capture access required' USING ERRCODE='42501';
  END IF;
  SELECT source.* INTO sheet FROM public.datasheets source JOIN public.test_requests job ON job.organization_id=source.organization_id AND job.id=source.test_request_id AND job.is_job
    WHERE source.organization_id=org AND source.template_instance_id=capture_id;
  IF sheet.id IS NULL THEN RETURN 0; END IF;
  PERFORM public.laboratory_lock_job_members(sheet.id);
  SELECT * INTO capture FROM public.template_instances WHERE organization_id=org AND id=capture_id;
  IF EXISTS (SELECT 1 FROM public.template_sections WHERE organization_id=org AND version_id=capture.version_id AND is_final_result) THEN RETURN 0; END IF;
  IF cardinality(field_ids) IS NULL OR cardinality(field_ids) NOT BETWEEN 1 AND 1000
    OR cardinality(occurrence_ids) IS DISTINCT FROM cardinality(field_ids) OR cardinality(positions) IS DISTINCT FROM cardinality(field_ids)
    OR EXISTS (SELECT 1 FROM unnest(field_ids,occurrence_ids,positions) entry(field_id,occurrence_id,position)
      WHERE field_id IS NULL OR occurrence_id IS NULL OR position IS NULL OR position NOT BETWEEN 0 AND 999)
    OR (SELECT count(DISTINCT position) FROM unnest(positions) position)<>cardinality(positions) THEN
    RAISE EXCEPTION 'Result changes require distinct bounded input positions' USING ERRCODE='23514';
  END IF;
  FOR item IN SELECT * FROM unnest(field_ids,occurrence_ids,positions) entry(field_id,occurrence_id,position) ORDER BY position LOOP
    SELECT value.* INTO selected FROM public.template_values value JOIN public.template_fields field
      ON field.organization_id=value.organization_id AND field.version_id=value.version_id AND field.id=value.field_id AND field.widget='result_widget'
      WHERE value.organization_id=org AND value.instance_id=capture_id AND value.field_id=item.field_id AND value.occurrence_id=item.occurrence_id
        AND value.revision=capture.revision AND value.origin='entered' AND value.saved_by=actor AND value.xmin::text=pg_current_xact_id()::text;
    IF selected.field_id IS NULL THEN RAISE EXCEPTION 'Result history must reference an actual current input' USING ERRCODE='23514'; END IF;
    SELECT * INTO subject FROM public.datasheet_subjects WHERE organization_id=org
      AND id=public.laboratory_result_subject(org,capture_id,item.occurrence_id);
    IF subject.id IS NULL THEN CONTINUE; END IF;
    SELECT candidate.id INTO member_sheet FROM public.test_requests member JOIN public.datasheets candidate
      ON candidate.organization_id=member.organization_id AND candidate.test_request_id=member.id AND candidate.status<>'void'
      WHERE member.organization_id=org AND member.id=subject.test_request_id AND member.parent_test_request_id=sheet.test_request_id AND NOT member.is_job
      ORDER BY (candidate.id=member.final_datasheet_id) DESC NULLS LAST,candidate.attempt_number DESC,candidate.created_at DESC,candidate.id LIMIT 1;
    IF member_sheet IS NULL THEN RAISE EXCEPTION 'A linked test request needs an active datasheet' USING ERRCODE='23514'; END IF;
    INSERT INTO public.job_result_entries(organization_id,datasheet_id,child_datasheet_id,subject_id,instance_id,field_id,occurrence_id,value_revision,position,recorded_by)
      VALUES(org,sheet.id,member_sheet,subject.id,capture_id,item.field_id,item.occurrence_id,capture.revision,item.position,actor);
    recorded:=recorded+1;
  END LOOP;
  RETURN recorded;
END $$;


--
-- Name: laboratory_record_method_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_record_method_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE event_type text; selected_sample uuid;
BEGIN
  IF TG_OP='INSERT' THEN
    IF NOT EXISTS (SELECT 1 FROM public.analytical_specifications WHERE organization_id=NEW.organization_id AND id=NEW.specification_id AND basis_specification_id IS NOT NULL) THEN RETURN NEW; END IF;
    event_type:='datasheet_method_added';
  ELSE
    IF NEW.status<>'void' OR OLD.status='void' OR EXISTS (SELECT 1 FROM public.test_requests WHERE organization_id=NEW.organization_id AND id=NEW.test_request_id AND status='cancelled') THEN RETURN NEW; END IF;
    event_type:='datasheet_method_voided';
  END IF;
  SELECT product.sample_id INTO selected_sample FROM public.test_requests request
    JOIN public.sample_tests selected ON selected.organization_id=request.organization_id AND selected.id=request.sample_test_id
    JOIN public.sample_products product ON product.organization_id=selected.organization_id AND product.id=selected.sample_product_id
    WHERE request.organization_id=NEW.organization_id AND request.id=NEW.test_request_id;
  INSERT INTO public.sample_events(organization_id,sample_id,test_request_id,datasheet_id,event_type,actor_user_id,description)
    VALUES(NEW.organization_id,selected_sample,NEW.test_request_id,NEW.id,event_type,nullif(current_setting('app.user_id',true),'')::uuid,
      CASE WHEN event_type='datasheet_method_added' THEN 'Added method to test request.' ELSE 'Deleted method from test request; datasheet history retained.' END);
  RETURN NEW;
END $$;


--
-- Name: laboratory_registering_sample(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_registering_sample() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT id FROM public.samples
  WHERE organization_id = nullif(current_setting('app.organization_id', true), '')::uuid
    AND id = nullif(current_setting('app.registration_sample_id', true), '')::uuid
    AND registered_by = nullif(current_setting('app.user_id', true), '')::uuid
    AND registered_at = transaction_timestamp() AND revision = 1 AND status = 'registered'
    AND public.app_has_permission('samples.create')
$$;


--
-- Name: laboratory_registration_capture(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_registration_capture() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT i.id FROM public.template_instances i JOIN public.template_versions v ON v.organization_id = i.organization_id AND v.id = i.version_id
    WHERE i.organization_id = nullif(current_setting('app.organization_id', true), '')::uuid
      AND i.id = nullif(current_setting('app.capture_id', true), '')::uuid AND i.created_by = nullif(current_setting('app.user_id', true), '')::uuid
      AND i.created_at = transaction_timestamp() AND i.revision = 1 AND i.status = 'editing' AND v.kind = 'sample' AND public.app_has_permission('samples.create')
      AND NOT EXISTS (SELECT 1 FROM public.samples s WHERE s.organization_id = i.organization_id AND s.template_instance_id = i.id)
$$;


--
-- Name: laboratory_request_can_work(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_request_can_work(p_request_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT public.app_has_permission('datasheets.execute') AND EXISTS (
    SELECT 1 FROM public.test_requests request
    JOIN public.laboratory_test_request_context product ON product.organization_id=request.organization_id AND product.test_request_id=request.id
    WHERE request.organization_id=nullif(current_setting('app.organization_id',true),'')::uuid
      AND request.id=p_request_id AND request.status IN ('allocated','in_progress','rejected')
      AND EXISTS (SELECT 1 FROM public.test_request_assignments assignment JOIN public.memberships member
        ON member.organization_id=assignment.organization_id AND member.user_id=assignment.assigned_user_id
        JOIN public.users actor ON actor.id=member.user_id
        WHERE assignment.organization_id=request.organization_id AND assignment.test_request_id=request.id
          AND assignment.assignment_type='analyst' AND assignment.unassigned_at IS NULL
          AND assignment.assigned_user_id=nullif(current_setting('app.user_id',true),'')::uuid AND member.active AND actor.active)
      AND NOT EXISTS (SELECT 1 FROM public.workflow_runs run JOIN public.approval_cases approval
        ON approval.organization_id=run.organization_id AND approval.workflow_run_id=run.id
        WHERE run.organization_id=request.organization_id AND run.test_request_id=request.id AND approval.status='pending')
      -- Match workflowAllowedActions: the flag applies when this sample state
      -- has configured capabilities; otherwise execution permission is fallback.
      AND NOT EXISTS (SELECT 1 FROM public.workflow_runs run JOIN public.workflow_states state
        ON state.organization_id=run.organization_id AND state.id=run.current_state_id
        WHERE run.organization_id=request.organization_id AND run.sample_id=product.sample_id AND NOT state.can_work_on_test_request
          AND EXISTS (SELECT 1 FROM public.workflow_state_capability_roles capability
            WHERE capability.organization_id=state.organization_id AND capability.workflow_state_id=state.id))
  )
$$;


--
-- Name: laboratory_require_method_retirement_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_require_method_retirement_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
BEGIN
  IF session_user='sampleify_app' AND NOT EXISTS (
    SELECT 1 FROM public.sample_events event WHERE event.organization_id=NEW.organization_id
      AND event.test_request_id=NEW.test_request_id AND event.datasheet_id=NEW.id AND event.event_type='datasheet_method_voided'
      AND event.actor_user_id=actor AND event.occurred_at=transaction_timestamp()
  ) AND NOT EXISTS (
    SELECT 1 FROM public.workflow_runs run JOIN public.workflow_run_history history
      ON history.organization_id=run.organization_id AND history.workflow_run_id=run.id AND history.to_state_id=run.current_state_id
    JOIN public.test_requests request ON request.organization_id=run.organization_id AND request.id=run.test_request_id
    WHERE run.organization_id=NEW.organization_id AND run.test_request_id=NEW.test_request_id AND run.status='cancelled' AND request.status='cancelled'
      AND history.action='cancelled' AND history.actor_user_id=actor AND history.occurred_at=transaction_timestamp()
  ) AND NOT EXISTS (
    SELECT 1 FROM public.job_workflow_effects effect JOIN public.job_submission_members member
      ON member.organization_id=effect.organization_id AND member.id=effect.job_submission_member_id
    JOIN public.workflow_run_history history ON history.organization_id=effect.organization_id AND history.id=effect.parent_history_id
    JOIN public.test_requests request ON request.organization_id=member.organization_id AND request.id=member.test_request_id
    WHERE effect.organization_id=NEW.organization_id AND member.test_request_id=NEW.test_request_id AND request.status='cancelled'
      AND history.action='cancelled' AND history.actor_user_id=actor AND history.occurred_at=transaction_timestamp()
      AND effect.xmin::text=pg_current_xact_id()::text
  ) THEN RAISE EXCEPTION 'Method retirement requires its actual change or workflow cancellation evidence'  USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: laboratory_result_subject(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_result_subject(org uuid, capture_id uuid, occurrence_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH RECURSIVE ancestors AS (
    SELECT id,parent_id,0 AS depth FROM public.template_occurrences WHERE organization_id=org AND instance_id=capture_id AND id=occurrence_id
    UNION ALL SELECT parent.id,parent.parent_id,ancestor.depth+1 FROM ancestors ancestor JOIN public.template_occurrences parent
      ON parent.organization_id=org AND parent.instance_id=capture_id AND parent.id=ancestor.parent_id
  ) SELECT subject.id FROM ancestors ancestor JOIN public.datasheet_subjects subject
    ON subject.organization_id=org AND subject.instance_id=capture_id AND subject.occurrence_id=ancestor.id
    ORDER BY ancestor.depth LIMIT 1
$$;


--
-- Name: laboratory_sample_line_in_use(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_sample_line_in_use(p_org uuid, p_sample uuid, p_line uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.sample_tests chosen WHERE chosen.organization_id=p_org AND chosen.sample_product_id=p_line
    AND (chosen.status<>'planned' OR EXISTS (SELECT 1 FROM public.test_requests request WHERE request.organization_id=p_org AND request.sample_test_id=chosen.id)))
    OR EXISTS (SELECT 1 FROM public.test_requests job WHERE job.organization_id=p_org AND job.job_sample_product_id=p_line)
    OR EXISTS (SELECT 1 FROM public.sample_reports report
      LEFT JOIN public.sample_line_contexts context ON context.organization_id=report.organization_id AND context.report_id=report.id
      WHERE report.organization_id=p_org AND report.sample_id=p_sample AND (report.sample_product_id=p_line OR report.product_context_line_id=p_line
        OR context.sample_product_id=p_line OR EXISTS (SELECT 1 FROM public.sample_report_tests member
          WHERE member.organization_id=p_org AND member.report_id=report.id AND member.sample_product_id=p_line)))
$$;


--
-- Name: laboratory_sample_workflow(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_sample_workflow(p_sample_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; sample_kind text; selected_id uuid;
BEGIN
  IF org IS NULL OR NOT public.app_has_permission('samples.create')
    OR public.laboratory_registering_sample() IS DISTINCT FROM p_sample_id THEN
    RAISE EXCEPTION 'Sample registration context required' USING ERRCODE='42501';
  END IF;
  SELECT sample.sample_type INTO sample_kind FROM public.samples sample WHERE sample.organization_id=org AND sample.id=p_sample_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Sample registration context required' USING ERRCODE='42501'; END IF;
  -- Meteor's registration form and ILC/PT models use the base workflow for these flags.
  SELECT CASE sample_kind
    WHEN 'customer' THEN settings.sample_workflow_base_id
    WHEN 'internal' THEN settings.sample_workflow_base_id
    WHEN 'interlaboratory' THEN settings.sample_workflow_base_id
    WHEN 'proficiency' THEN settings.sample_workflow_base_id
    WHEN 'quality_control' THEN settings.sample_workflow_iqc_id
    WHEN 'amendment' THEN settings.sample_workflow_amendment_id
    WHEN 'complaint' THEN settings.sample_workflow_complaint_id END
    INTO selected_id FROM public.organization_laboratory_settings settings WHERE settings.organization_id=org FOR SHARE;
  RETURN selected_id;
END $$;


--
-- Name: laboratory_settings_options(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_settings_options() RETURNS TABLE(id uuid, kind text, label text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  IF org IS NULL OR NOT (public.app_has_permission('settings.read') OR public.app_has_permission('settings.manage')) THEN
    RAISE EXCEPTION 'Settings permission required' USING ERRCODE='42501';
  END IF;
  RETURN QUERY SELECT template.id,'template'::text,latest.name FROM public.templates template
    JOIN LATERAL (SELECT version.name,version.kind FROM public.template_versions version
      WHERE version.organization_id=template.organization_id AND version.template_id=template.id ORDER BY version.number DESC LIMIT 1) latest ON latest.kind='datasheet'
    WHERE template.organization_id=org AND template.active
    UNION ALL SELECT workflow.id,'workflow'::text,workflow.name FROM public.workflows workflow
      WHERE workflow.organization_id=org AND workflow.active AND workflow.applies_to='test_request'
      AND EXISTS (SELECT 1 FROM public.workflow_versions version WHERE version.organization_id=org AND version.workflow_id=workflow.id AND version.status='published')
    UNION ALL SELECT workflow.id,'sample_workflow'::text,workflow.name FROM public.workflows workflow
      WHERE workflow.organization_id=org AND workflow.active AND workflow.applies_to='sample'
      AND EXISTS (SELECT 1 FROM public.workflow_versions version WHERE version.organization_id=org AND version.workflow_id=workflow.id AND version.status='published')
    UNION ALL SELECT workflow.id,'sample_workflow_retained'::text,workflow.name FROM public.workflows workflow
      JOIN public.organization_laboratory_settings settings ON settings.organization_id=workflow.organization_id
      WHERE workflow.organization_id=org AND workflow.id IN (settings.sample_workflow_base_id,settings.sample_workflow_iqc_id,settings.sample_workflow_ilc_id,settings.sample_workflow_pt_id,settings.sample_workflow_amendment_id,settings.sample_workflow_complaint_id)
      AND NOT (workflow.active AND workflow.applies_to='sample' AND EXISTS (SELECT 1 FROM public.workflow_versions version
        WHERE version.organization_id=org AND version.workflow_id=workflow.id AND version.status='published'))
    UNION ALL SELECT workflow.id,'workflow_retained'::text,workflow.name FROM public.workflows workflow
      JOIN public.organization_laboratory_settings settings ON settings.organization_id=workflow.organization_id
      WHERE workflow.organization_id=org AND workflow.id IN (settings.test_request_workflow_id,settings.job_workflow_id)
      AND NOT (workflow.active AND workflow.applies_to='test_request' AND EXISTS (SELECT 1 FROM public.workflow_versions version
        WHERE version.organization_id=org AND version.workflow_id=workflow.id AND version.status='published'));
END $$;


--
-- Name: laboratory_snapshot_method(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_snapshot_method(p_request_id uuid, p_method_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  request public.test_requests; snapshot public.analytical_specifications; method public.methods_of_analysis; basis_id uuid;
BEGIN
  PERFORM public.laboratory_lock_request_sample(p_request_id);
  SELECT * INTO request FROM public.test_requests WHERE organization_id=org AND id=p_request_id FOR UPDATE;
  IF request.id IS NULL OR request.is_job OR NOT public.laboratory_request_can_work(p_request_id) THEN
    RAISE EXCEPTION 'Only the assigned analyst can change an open method' USING ERRCODE='42501';
  END IF;
  SELECT * INTO snapshot FROM public.analytical_specifications WHERE organization_id=org AND id=request.specification_id;
  PERFORM public.laboratory_lock_references('test_parameters',ARRAY[snapshot.test_parameter_id]);
  PERFORM public.laboratory_lock_references('parameter_methods',ARRAY[snapshot.test_parameter_id]);
  PERFORM public.laboratory_lock_references('methods_of_analysis',ARRAY[p_method_id]);
  SELECT * INTO method FROM public.methods_of_analysis WHERE organization_id=org AND id=p_method_id AND active;
  IF method.id IS NULL OR (EXISTS (SELECT 1 FROM public.parameter_methods WHERE organization_id=org AND test_parameter_id=snapshot.test_parameter_id)
    AND NOT EXISTS (SELECT 1 FROM public.parameter_methods WHERE organization_id=org AND test_parameter_id=snapshot.test_parameter_id AND method_id=method.id)) THEN
    RAISE EXCEPTION 'The method is not applicable to this parameter' USING ERRCODE='23514';
  END IF;
  IF snapshot.basis_specification_id IS NOT NULL THEN RAISE EXCEPTION 'A method snapshot requires the original request specification' USING ERRCODE='23514'; END IF;
  basis_id:=snapshot.id;
  snapshot.id:=gen_random_uuid(); snapshot.basis_specification_id:=basis_id;
  snapshot.method_id:=method.id; snapshot.method_revision:=method.revision; snapshot.method_code:=method.code; snapshot.method_name:=method.name;
  snapshot.method_description:=method.description; snapshot.method_uuid:=method.method_uuid; snapshot.decimal_scale:=method.decimal_scale; snapshot.parse_number:=method.parse_number;
  snapshot.recorded_by:=nullif(current_setting('app.user_id',true),'')::uuid; snapshot.recorded_at:=transaction_timestamp();
  INSERT INTO public.analytical_specifications SELECT (snapshot).*;
  INSERT INTO public.analytical_specification_limits(organization_id,specification_id,id,lower_limit,upper_limit,lower_inclusive,upper_inclusive,outcome,narration,display_order)
    SELECT organization_id,snapshot.id,id,lower_limit,upper_limit,lower_inclusive,upper_inclusive,outcome,narration,display_order
    FROM public.analytical_specification_limits WHERE organization_id=org AND specification_id=basis_id;
  RETURN snapshot.id;
END $$;


--
-- Name: laboratory_start_auto_job(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_start_auto_job(member_ids uuid[]) RETURNS TABLE(id uuid, request_number text, member_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  product_line uuid; selected_sample uuid; settings public.organization_laboratory_settings; job_id uuid:=gen_random_uuid(); job_number text; summary_template uuid;
BEGIN
  IF member_ids IS NULL OR cardinality(member_ids) NOT BETWEEN 1 AND 500 OR array_position(member_ids,NULL) IS NOT NULL
    OR (SELECT count(DISTINCT member_id) FROM unnest(member_ids) member_id)<>cardinality(member_ids) THEN RAISE EXCEPTION 'Select distinct new requests for an automatic job' USING ERRCODE='23514'; END IF;
  SELECT selected.sample_product_id,product.sample_id INTO product_line,selected_sample FROM public.test_requests request
    JOIN public.sample_tests selected ON selected.organization_id=request.organization_id AND selected.id=request.sample_test_id
    JOIN public.sample_products product ON product.organization_id=selected.organization_id AND product.id=selected.sample_product_id
    WHERE request.organization_id=org AND request.id=member_ids[1];
  IF NOT public.laboratory_job_generation_sample(selected_sample) THEN RAISE EXCEPTION 'Automatic jobs require the actual generation action' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.samples WHERE organization_id=org AND public.samples.id=selected_sample FOR UPDATE;
  PERFORM 1 FROM public.test_requests request WHERE request.organization_id=org AND request.id=ANY(member_ids) ORDER BY request.id FOR UPDATE;
  IF (SELECT count(*) FROM public.test_requests request JOIN public.sample_tests selected
    ON selected.organization_id=request.organization_id AND selected.id=request.sample_test_id
    WHERE request.organization_id=org AND request.id=ANY(member_ids) AND public.laboratory_new_generated_request(request.id)
      AND request.status='created' AND request.parent_test_request_id IS NULL AND selected.sample_product_id=product_line
      AND NOT EXISTS (SELECT 1 FROM public.test_request_assignments assignment WHERE assignment.organization_id=org
        AND assignment.test_request_id=request.id AND assignment.assignment_type='analyst' AND assignment.unassigned_at IS NULL))<>cardinality(member_ids)
  THEN RAISE EXCEPTION 'Automatic jobs can group only their newly generated product-line requests' USING ERRCODE='23514'; END IF;
  SELECT * INTO settings FROM public.organization_laboratory_settings WHERE organization_id=org FOR SHARE;
  SELECT resolved.template_id INTO summary_template FROM public.laboratory_product_job_templates(selected_sample,ARRAY[product_line],true) resolved;
  IF NOT coalesce(settings.auto_create_jobs,false) OR summary_template IS NULL
  THEN RAISE EXCEPTION 'Automatic job settings are unavailable' USING ERRCODE='23514'; END IF;
  job_number:=public.laboratory_next_number('job',extract(year FROM now() AT TIME ZONE 'UTC')::integer::text);
  INSERT INTO public.test_requests(organization_id,id,request_number,is_job,is_auto_created,job_sample_product_id,priority,due_at,datasheet_template_id,created_by)
    SELECT org,job_id,job_number,true,true,product_line,
      CASE WHEN bool_or(request.priority='urgent') THEN 'urgent' WHEN bool_or(request.priority='high') THEN 'high' ELSE min(request.priority) END,
      min(request.due_at),summary_template,actor FROM public.test_requests request WHERE request.organization_id=org AND request.id=ANY(member_ids);
  UPDATE public.test_requests request SET parent_test_request_id=job_id,job_member_position=member.ordinality-1,job_linked_by=actor,
    job_linked_at=now(),revision=request.revision+1 FROM unnest(member_ids) WITH ORDINALITY member(member_id,ordinality)
    WHERE request.organization_id=org AND request.id=member.member_id;
  INSERT INTO public.test_request_assignments(organization_id,test_request_id,assignment_type,assigned_user_id,assigned_by)
    SELECT org,member_id,'analyst',actor,actor FROM unnest(member_ids) member_id;
  UPDATE public.test_requests request SET status='allocated',revision=request.revision+1 WHERE request.organization_id=org AND request.id=ANY(member_ids);
  INSERT INTO public.sample_events(organization_id,sample_id,test_request_id,event_type,actor_user_id,description)
    SELECT org,selected_sample,member_id,'test_request_assigned',actor,'Test request analyst assigned during automatic job creation' FROM unnest(member_ids) member_id;
  RETURN QUERY SELECT job_id,job_number,cardinality(member_ids);
END $$;


--
-- Name: laboratory_submission_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_submission_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF session_user='sampleify_app' AND NOT EXISTS (SELECT 1 FROM public.datasheets sheet JOIN public.test_requests request
    ON request.organization_id=sheet.organization_id AND request.id=sheet.test_request_id JOIN public.template_instances capture
    ON capture.organization_id=sheet.organization_id AND capture.id=NEW.instance_id
    WHERE sheet.organization_id=NEW.organization_id AND sheet.id=NEW.datasheet_id AND sheet.latest_submission_id=NEW.id
      AND ((sheet.status IN ('under_review','approved') AND request.status IN ('under_review','approved'))
        OR (sheet.status='void' AND request.status='cancelled' AND (
          EXISTS (SELECT 1 FROM public.workflow_run_history history JOIN public.workflow_runs run
            ON run.organization_id=history.organization_id AND run.id=history.workflow_run_id WHERE run.organization_id=NEW.organization_id AND run.test_request_id=request.id
              AND history.datasheet_submission_id=NEW.id AND history.action='cancelled' AND history.xmin::text=pg_current_xact_id()::text)
          OR EXISTS (SELECT 1 FROM public.job_workflow_effects effect JOIN public.job_submission_members member ON member.organization_id=effect.organization_id AND member.id=effect.job_submission_member_id
            JOIN public.workflow_run_history history ON history.organization_id=effect.organization_id AND history.id=effect.parent_history_id
            WHERE member.organization_id=NEW.organization_id AND member.submission_id=NEW.id AND member.test_request_id=request.id
              AND history.action='cancelled' AND effect.xmin::text=pg_current_xact_id()::text))))
      AND sheet.completed_by=NEW.submitted_by AND sheet.completed_at=NEW.submitted_at AND request.final_datasheet_id=sheet.id AND capture.status='frozen' AND capture.revision=NEW.capture_revision
      AND EXISTS (SELECT 1 FROM public.sample_events event WHERE event.organization_id=sheet.organization_id AND event.test_request_id=request.id
        AND event.event_type='datasheet_submitted' AND event.actor_user_id=NEW.submitted_by AND event.xmin::text=pg_current_xact_id()::text)) THEN
    RAISE EXCEPTION 'Submission, frozen capture, owner status and actual audit event must commit together' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: laboratory_test_request_workflow(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.laboratory_test_request_workflow(p_request_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; job boolean; selected_id uuid;
BEGIN
  IF org IS NULL OR p_request_id IS NULL OR (NOT public.app_has_permission('test_requests.allocate')
    AND public.laboratory_auto_job_request() IS DISTINCT FROM p_request_id) THEN
    RAISE EXCEPTION 'Request allocation context required' USING ERRCODE='42501';
  END IF;
  SELECT request.is_job INTO job FROM public.test_requests request
    WHERE request.organization_id=org AND request.id=p_request_id AND request.using_dynamic_workflow;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dynamic request allocation context required' USING ERRCODE='42501'; END IF;
  SELECT CASE WHEN job THEN settings.job_workflow_id ELSE settings.test_request_workflow_id END
    INTO selected_id FROM public.organization_laboratory_settings settings WHERE settings.organization_id=org FOR SHARE;
  RETURN selected_id;
END $$;


--
-- Name: master_bulk_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.master_bulk_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE expected_columns integer;
BEGIN
  IF TG_TABLE_NAME='master_bulk_batches' THEN
    IF NEW.column_count<>(SELECT count(*) FROM public.master_bulk_columns WHERE organization_id=NEW.organization_id AND batch_id=NEW.id)
      OR NEW.row_count<>(SELECT count(*) FROM public.master_bulk_rows WHERE organization_id=NEW.organization_id AND batch_id=NEW.id) THEN
      RAISE EXCEPTION 'Complete the uploaded row and column shape' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT column_count INTO expected_columns FROM public.master_bulk_batches WHERE organization_id=NEW.organization_id AND id=NEW.batch_id;
    IF expected_columns<>(SELECT count(*) FROM public.master_bulk_cells
      WHERE organization_id=NEW.organization_id AND batch_id=NEW.batch_id AND row_id=NEW.row_id AND revision=NEW.revision) THEN
      RAISE EXCEPTION 'Complete every input cell, including missing cells' USING ERRCODE='23514';
    END IF;
    IF EXISTS (SELECT 1 FROM public.master_bulk_batches WHERE organization_id=NEW.organization_id AND id=NEW.batch_id AND resource='users')
      AND NOT EXISTS (SELECT 1 FROM public.master_bulk_user_credentials WHERE organization_id=NEW.organization_id AND batch_id=NEW.batch_id
        AND row_id=NEW.row_id AND input_revision=NEW.revision) THEN
      RAISE EXCEPTION 'Complete the protected User credential state' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: master_bulk_copy_user_credential(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.master_bulk_copy_user_credential(batch uuid, row_identity uuid, revision integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=public.users_require_manager(); org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  INSERT INTO public.master_bulk_user_credentials(organization_id,batch_id,row_id,input_revision,state,fingerprint,password_hash,saved_by)
    SELECT org,batch,row_identity,revision,state,fingerprint,password_hash,actor FROM public.master_bulk_user_credentials
    WHERE organization_id=org AND batch_id=batch AND row_id=row_identity AND input_revision=revision-1;
  IF NOT FOUND THEN RAISE EXCEPTION 'The previous User credential is unavailable' USING ERRCODE='23503'; END IF;
END $$;


--
-- Name: master_bulk_create_user(uuid, uuid, integer, uuid, text, text, text, text, text, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.master_bulk_create_user(batch uuid, row_identity uuid, requested_revision integer, review_identity uuid, requested_username text, requested_email text, requested_name text, phone text, designation text, unit uuid, default_role uuid, laboratory uuid) RETURNS TABLE(id uuid, profile_revision integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=public.users_require_manager(); org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  reviewed public.master_bulk_reviews; credential public.master_bulk_user_credentials; saved_revision integer;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('custom-field-definitions:'||org::text,0));
  PERFORM 1 FROM public.master_bulk_rows WHERE organization_id=org AND batch_id=batch AND master_bulk_rows.id=row_identity AND master_bulk_rows.revision=requested_revision FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'The User input revision changed' USING ERRCODE='23514',CONSTRAINT='master_bulk_user_review'; END IF;
  actor:=public.users_require_manager();
  SELECT * INTO reviewed FROM public.master_bulk_reviews WHERE organization_id=org AND master_bulk_reviews.id=review_identity
    AND batch_id=batch AND row_id=row_identity AND input_revision=requested_revision;
  SELECT * INTO credential FROM public.master_bulk_user_credentials WHERE organization_id=org AND batch_id=batch
    AND row_id=row_identity AND input_revision=requested_revision;
  IF reviewed.id IS NULL OR NOT reviewed.valid OR reviewed.operation<>'create' OR reviewed.expected_revision<>0
    OR credential.state IS DISTINCT FROM 'valid' THEN
    RAISE EXCEPTION 'Validate the User row and its password before creation' USING ERRCODE='23514',CONSTRAINT='master_bulk_user_review';
  END IF;
  saved_revision:=public.users_create_account(reviewed.candidate_id,reviewed.id,decode(reviewed.command_sha256,'hex'),requested_username,requested_email,requested_name,
    credential.password_hash,NULL,false,phone,true,designation,true,false,true,unit,true,default_role,laboratory,NULL,false,NULL);
  RETURN QUERY SELECT reviewed.candidate_id,saved_revision;
END $$;


--
-- Name: master_bulk_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.master_bulk_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  upload public.master_bulk_batches; current_row public.master_bulk_rows; reviewed public.master_bulk_reviews;
  parent_transaction xid8; actual_request uuid; actual_actor uuid; actual_transaction xid8;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Bulk input and outcomes are retained' USING ERRCODE='55000'; END IF;
  IF TG_TABLE_NAME='master_bulk_batches' THEN upload:=NEW;
  ELSE SELECT * INTO upload FROM public.master_bulk_batches WHERE organization_id=NEW.organization_id AND id=NEW.batch_id; END IF;
  IF NOT public.master_bulk_has_permission(upload.resource) OR actor IS NULL
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Bulk resource management permission required' USING ERRCODE='42501';
  END IF;
  -- Initial children require this transaction's batch; corrections advance its row.
  -- Hold the same authorization locks as native party saves for each mutation.
  IF upload.resource IN ('customers','vendors') AND (TG_TABLE_NAME IN ('master_bulk_batches','master_bulk_reviews','master_bulk_attempts') OR TG_OP='UPDATE') THEN
    IF upload.resource='vendors' THEN PERFORM public.masters_require_vendor_write();
    ELSE PERFORM public.masters_require_customer_write(); END IF;
  END IF;
  IF TG_TABLE_NAME='master_bulk_rows' AND TG_OP='UPDATE' THEN
    IF (NEW.organization_id,NEW.batch_id,NEW.id,NEW.ordinal,NEW.source_row_number) IS DISTINCT FROM
      (OLD.organization_id,OLD.batch_id,OLD.id,OLD.ordinal,OLD.source_row_number) OR NEW.revision<>OLD.revision+1
      OR EXISTS (SELECT 1 FROM public.master_bulk_attempts WHERE organization_id=OLD.organization_id AND batch_id=OLD.batch_id AND row_id=OLD.id AND committed) THEN
      RAISE EXCEPTION 'Advance an uncommitted input revision without changing its source identity' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Bulk history is immutable' USING ERRCODE='55000'; END IF;
  IF TG_TABLE_NAME NOT IN ('master_bulk_columns','master_bulk_rows','master_bulk_cells') THEN
    IF NEW.saved_by IS DISTINCT FROM actor OR NEW.saved_at IS DISTINCT FROM transaction_timestamp()
      OR NEW.created_transaction_id IS DISTINCT FROM pg_current_xact_id() THEN
      RAISE EXCEPTION 'Record the actual bulk actor and transaction' USING ERRCODE='23514';
    END IF;
  END IF;
  IF TG_TABLE_NAME='master_bulk_batches' THEN RETURN NEW; END IF;
  IF upload.id IS NULL THEN RAISE EXCEPTION 'Upload was not found' USING ERRCODE='23514'; END IF;
  IF TG_TABLE_NAME IN ('master_bulk_columns','master_bulk_rows') THEN
    IF upload.created_transaction_id<>pg_current_xact_id() THEN RAISE EXCEPTION 'Original upload shape is immutable' USING ERRCODE='55000'; END IF;
    IF TG_TABLE_NAME='master_bulk_columns' THEN
      IF upload.resource='users' AND (trim(NEW.source_header) NOT IN ('','name','email','phone','username','designation','unit_name','role_name','password','lab_name')
        OR (trim(NEW.source_header)='password' AND num_nonnulls(NEW.source_type,NEW.formula,NEW.has_result,NEW.error_code,NEW.hyperlink,NEW.number_format)<>0)) THEN
        RAISE EXCEPTION 'Use redacted User upload headers' USING ERRCODE='23514';
      END IF;
      IF NEW.column_number>upload.column_count THEN RAISE EXCEPTION 'Column exceeds upload shape' USING ERRCODE='23514'; END IF;
    ELSE
      IF NEW.ordinal>upload.row_count OR NEW.source_row_number<=upload.header_row_number OR NEW.revision<>1 THEN
        RAISE EXCEPTION 'Invalid original source row' USING ERRCODE='23514';
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_TABLE_NAME='master_bulk_cells' THEN
    SELECT created_transaction_id INTO parent_transaction FROM public.master_bulk_row_versions
      WHERE organization_id=NEW.organization_id AND batch_id=NEW.batch_id AND row_id=NEW.row_id AND revision=NEW.revision;
    IF parent_transaction IS DISTINCT FROM pg_current_xact_id() THEN RAISE EXCEPTION 'Input cells are immutable after their revision commits' USING ERRCODE='55000'; END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO current_row FROM public.master_bulk_rows WHERE organization_id=NEW.organization_id AND batch_id=NEW.batch_id AND id=NEW.row_id FOR UPDATE;
  IF current_row.id IS NULL OR EXISTS (SELECT 1 FROM public.master_bulk_attempts
    WHERE organization_id=NEW.organization_id AND batch_id=NEW.batch_id AND row_id=NEW.row_id AND committed) THEN
    RAISE EXCEPTION 'This upload row is missing or already committed' USING ERRCODE='23514';
  END IF;
  IF TG_TABLE_NAME='master_bulk_row_versions' THEN
    IF NEW.revision<>current_row.revision THEN RAISE EXCEPTION 'Input revision must match the current row' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.input_revision<>current_row.revision THEN RAISE EXCEPTION 'Input changed before review or processing' USING ERRCODE='23514'; END IF;
  IF TG_TABLE_NAME='master_bulk_reviews' THEN
    IF upload.resource IN ('customers','vendors') AND NEW.valid AND (NEW.operation IS DISTINCT FROM 'create' OR NEW.expected_revision IS DISTINCT FROM 0) THEN
      RAISE EXCEPTION 'Party master uploads create records only' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO reviewed FROM public.master_bulk_reviews WHERE organization_id=NEW.organization_id AND id=NEW.review_id;
  IF NEW.committed THEN
    IF NOT reviewed.valid OR NEW.result_revision<>reviewed.expected_revision+1
      OR coalesce(NEW.product_id,NEW.parameter_id,NEW.method_id,NEW.user_id,NEW.customer_id,NEW.vendor_id) IS DISTINCT FROM reviewed.candidate_id THEN
      RAISE EXCEPTION 'Bulk outcome does not match its reviewed command' USING ERRCODE='23514';
    END IF;
    IF upload.resource='products' AND NEW.product_id IS NOT NULL THEN
      SELECT request_id,saved_by,created_transaction_id INTO actual_request,actual_actor,actual_transaction FROM public.product_versions
        WHERE organization_id=NEW.organization_id AND product_id=NEW.product_id AND revision=NEW.result_revision;
    ELSIF upload.resource='test-parameters' AND NEW.parameter_id IS NOT NULL THEN
      SELECT request_id,saved_by,created_transaction_id INTO actual_request,actual_actor,actual_transaction FROM public.test_parameter_versions
        WHERE organization_id=NEW.organization_id AND parameter_id=NEW.parameter_id AND revision=NEW.result_revision;
    ELSIF upload.resource='methods' AND NEW.method_id IS NOT NULL THEN
      SELECT request_id,saved_by,created_transaction_id INTO actual_request,actual_actor,actual_transaction FROM public.method_versions
        WHERE organization_id=NEW.organization_id AND method_id=NEW.method_id AND revision=NEW.result_revision;
    ELSIF upload.resource='customers' AND NEW.customer_id IS NOT NULL AND reviewed.operation='create' AND reviewed.expected_revision=0 AND NEW.result_revision=1 THEN
      SELECT request_id,saved_by,created_transaction_id INTO actual_request,actual_actor,actual_transaction FROM public.customer_versions
        WHERE organization_id=NEW.organization_id AND customer_id=NEW.customer_id AND revision=NEW.result_revision AND operation='create' AND save_source='master';
    ELSIF upload.resource='vendors' AND NEW.vendor_id IS NOT NULL AND reviewed.operation='create' AND reviewed.expected_revision=0 AND NEW.result_revision=1 THEN
      SELECT request_id,saved_by,created_transaction_id INTO actual_request,actual_actor,actual_transaction FROM public.vendor_versions
        WHERE organization_id=NEW.organization_id AND vendor_id=NEW.vendor_id AND revision=NEW.result_revision AND operation='create';
    ELSIF upload.resource='users' AND NEW.user_id IS NOT NULL AND reviewed.operation='create' AND reviewed.expected_revision=0 AND NEW.result_revision=1 THEN
      SELECT request_id,created_by,created_transaction_id INTO actual_request,actual_actor,actual_transaction FROM public.user_creation_commands
        WHERE organization_id=NEW.organization_id AND user_id=NEW.user_id AND profile_revision=NEW.result_revision;
    END IF;
    IF actual_request IS DISTINCT FROM reviewed.id OR actual_actor IS DISTINCT FROM actor OR actual_transaction IS DISTINCT FROM pg_current_xact_id() THEN
      RAISE EXCEPTION 'Bulk success requires an actual master save in this transaction' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: master_bulk_guard_inserted_cells(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.master_bulk_guard_inserted_cells() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  IF actor IS NULL OR org IS NULL
    OR EXISTS (SELECT 1 FROM inserted_master_bulk_cells WHERE organization_id IS DISTINCT FROM org) THEN
    RAISE EXCEPTION 'Master management permission required' USING ERRCODE='42501';
  END IF;
  IF EXISTS (SELECT 1 FROM (SELECT DISTINCT organization_id,batch_id FROM inserted_master_bulk_cells) inserted
    LEFT JOIN public.master_bulk_batches batch ON batch.organization_id=inserted.organization_id AND batch.id=inserted.batch_id
    WHERE NOT public.master_bulk_has_permission(batch.resource)) THEN
    RAISE EXCEPTION 'Bulk resource management permission required' USING ERRCODE='42501';
  END IF;
  IF EXISTS (SELECT 1 FROM inserted_master_bulk_cells cell
    JOIN public.master_bulk_batches batch ON batch.organization_id=cell.organization_id AND batch.id=cell.batch_id AND batch.resource='users'
    JOIN public.master_bulk_columns column_header ON column_header.organization_id=cell.organization_id AND column_header.batch_id=cell.batch_id
      AND column_header.column_number=cell.column_number AND trim(column_header.source_header)='password'
    WHERE cell.value_kind<>'text' OR cell.text_value IS DISTINCT FROM ''
      OR num_nonnulls(cell.source_type,cell.formula,cell.has_result,cell.error_code,cell.hyperlink,cell.number_format)<>0) THEN
    RAISE EXCEPTION 'Password values and provenance must be redacted' USING ERRCODE='23514';
  END IF;
  IF EXISTS (
    SELECT 1 FROM (SELECT DISTINCT organization_id,batch_id,row_id,revision FROM inserted_master_bulk_cells) inserted
    LEFT JOIN public.master_bulk_row_versions parent ON parent.organization_id=inserted.organization_id AND parent.batch_id=inserted.batch_id
      AND parent.row_id=inserted.row_id AND parent.revision=inserted.revision
    WHERE parent.created_transaction_id IS DISTINCT FROM pg_current_xact_id() OR parent.saved_by IS DISTINCT FROM actor
  ) THEN RAISE EXCEPTION 'Input cells require the actual actor and an uncommitted input revision' USING ERRCODE='55000'; END IF;
  RETURN NULL;
END $$;


--
-- Name: master_bulk_guard_user_credential(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.master_bulk_guard_user_credential() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid; parent public.master_bulk_row_versions; resource text;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Bulk credential history is immutable' USING ERRCODE='55000'; END IF;
  actor:=public.users_require_manager();
  IF NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR NEW.saved_by IS DISTINCT FROM actor OR NEW.saved_at IS DISTINCT FROM transaction_timestamp()
    OR NEW.created_transaction_id IS DISTINCT FROM pg_current_xact_id() THEN
    RAISE EXCEPTION 'Record the actual User upload actor and transaction' USING ERRCODE='23514';
  END IF;
  SELECT * INTO parent FROM public.master_bulk_row_versions WHERE organization_id=NEW.organization_id AND batch_id=NEW.batch_id
    AND row_id=NEW.row_id AND revision=NEW.input_revision;
  SELECT batch.resource INTO resource FROM public.master_bulk_batches batch WHERE organization_id=NEW.organization_id AND id=NEW.batch_id;
  IF parent.created_transaction_id IS DISTINCT FROM pg_current_xact_id() OR parent.saved_by IS DISTINCT FROM actor OR resource IS DISTINCT FROM 'users' THEN
    RAISE EXCEPTION 'Credentials require a current User input revision' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: master_bulk_has_permission(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.master_bulk_has_permission(resource text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT CASE WHEN resource='users' THEN public.app_has_permission('users.manage')
    WHEN resource='customers' THEN public.app_has_permission('masters.manage') AND public.organization_has_module_access('customer')
    WHEN resource='vendors' THEN public.app_has_permission('masters.manage') AND public.organization_has_module_access('vendor')
    WHEN resource IN ('products','test-parameters','methods') THEN public.app_has_permission('masters.manage') ELSE false END
$$;


--
-- Name: master_bulk_store_user_credential(uuid, uuid, integer, text, bytea, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.master_bulk_store_user_credential(batch uuid, row_identity uuid, revision integer, requested_state text, requested_fingerprint bytea, requested_hash text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=public.users_require_manager(); org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  INSERT INTO public.master_bulk_user_credentials(organization_id,batch_id,row_id,input_revision,state,fingerprint,password_hash,saved_by)
    VALUES(org,batch,row_identity,revision,requested_state,requested_fingerprint,requested_hash,actor);
END $$;


--
-- Name: master_bulk_user_aliases(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.master_bulk_user_aliases(requested text[]) RETURNS TABLE(alias text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  PERFORM public.users_require_manager();
  IF requested IS NULL OR (cardinality(requested)>0 AND array_ndims(requested) IS DISTINCT FROM 1) OR cardinality(requested)>5000
    OR EXISTS (SELECT 1 FROM unnest(requested) value WHERE value IS NULL OR length(value) NOT BETWEEN 1 AND 320) THEN
    RAISE EXCEPTION 'Provide bounded sign-in identifiers' USING ERRCODE='22023';
  END IF;
  RETURN QUERY SELECT DISTINCT lower(value) FROM unnest(requested) value
    WHERE EXISTS (SELECT 1 FROM public.users person WHERE lower(person.username)=lower(value) OR lower(person.email)=lower(value));
END $$;


--
-- Name: masters_assert_custom_field_links(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_assert_custom_field_links(target_organization uuid, target_field uuid, target_revision integer) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.custom_field_versions; link_count integer; minimum_position integer; maximum_position integer;
BEGIN
  SELECT * INTO version FROM public.custom_field_versions
    WHERE organization_id=target_organization AND field_id=target_field AND revision=target_revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'Custom field history is missing' USING ERRCODE='23514'; END IF;
  SELECT count(*),min(position),max(position) INTO link_count,minimum_position,maximum_position FROM public.custom_field_version_options
    WHERE organization_id=target_organization AND field_id=target_field AND revision=target_revision;
  IF link_count<>version.option_count OR (link_count>0 AND (minimum_position<>0 OR maximum_position<>link_count-1)) THEN
    RAISE EXCEPTION 'Custom field options require a complete ordered version' USING ERRCODE='23514';
  END IF;
  SELECT count(*),min(position),max(position) INTO link_count,minimum_position,maximum_position FROM public.custom_field_version_edit_roles
    WHERE organization_id=target_organization AND field_id=target_field AND revision=target_revision;
  IF link_count<>version.edit_role_count OR (link_count>0 AND (minimum_position<>0 OR maximum_position<>link_count-1)) THEN
    RAISE EXCEPTION 'Custom field roles require a complete ordered version' USING ERRCODE='23514';
  END IF;
  IF version.operation='retire' AND (EXISTS (
    SELECT id,key,label,position FROM public.custom_field_version_options WHERE organization_id=target_organization AND field_id=target_field AND revision=target_revision
    EXCEPT SELECT id,key,label,position FROM public.custom_field_version_options WHERE organization_id=target_organization AND field_id=target_field AND revision=version.previous_revision
  ) OR EXISTS (
    SELECT id,key,label,position FROM public.custom_field_version_options WHERE organization_id=target_organization AND field_id=target_field AND revision=version.previous_revision
    EXCEPT SELECT id,key,label,position FROM public.custom_field_version_options WHERE organization_id=target_organization AND field_id=target_field AND revision=target_revision
  ) OR EXISTS (
    SELECT role_id,position FROM public.custom_field_version_edit_roles WHERE organization_id=target_organization AND field_id=target_field AND revision=target_revision
    EXCEPT SELECT role_id,position FROM public.custom_field_version_edit_roles WHERE organization_id=target_organization AND field_id=target_field AND revision=version.previous_revision
  ) OR EXISTS (
    SELECT role_id,position FROM public.custom_field_version_edit_roles WHERE organization_id=target_organization AND field_id=target_field AND revision=version.previous_revision
    EXCEPT SELECT role_id,position FROM public.custom_field_version_edit_roles WHERE organization_id=target_organization AND field_id=target_field AND revision=target_revision
  )) THEN RAISE EXCEPTION 'Custom field retirement preserves its last options and roles' USING ERRCODE='23514'; END IF;
END $$;


--
-- Name: masters_assert_customer_custom_field_preservation(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_assert_customer_custom_field_preservation(target_organization uuid, target_customer uuid, target_revision integer) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.customer_versions;
BEGIN
  SELECT * INTO version FROM public.customer_versions WHERE organization_id=target_organization AND customer_id=target_customer AND revision=target_revision;
  IF version.custom_fields_provided THEN RETURN; END IF;
  IF EXISTS (SELECT "organization_id","customer_id","field_id","field_revision","field_type","position","is_array","value_count","display_kind","display_text","display_number","display_boolean","time_zone","time_zone_data_version","date_parser_version" FROM public.customer_version_custom_fields WHERE organization_id=target_organization AND customer_id=target_customer AND revision=target_revision EXCEPT SELECT "organization_id","customer_id","field_id","field_revision","field_type","position","is_array","value_count","display_kind","display_text","display_number","display_boolean","time_zone","time_zone_data_version","date_parser_version" FROM public.customer_version_custom_fields WHERE organization_id=target_organization AND customer_id=target_customer AND revision=version.previous_revision) OR EXISTS (SELECT "organization_id","customer_id","field_id","field_revision","field_type","position","is_array","value_count","display_kind","display_text","display_number","display_boolean","time_zone","time_zone_data_version","date_parser_version" FROM public.customer_version_custom_fields WHERE organization_id=target_organization AND customer_id=target_customer AND revision=version.previous_revision EXCEPT SELECT "organization_id","customer_id","field_id","field_revision","field_type","position","is_array","value_count","display_kind","display_text","display_number","display_boolean","time_zone","time_zone_data_version","date_parser_version" FROM public.customer_version_custom_fields WHERE organization_id=target_organization AND customer_id=target_customer AND revision=target_revision) OR EXISTS (SELECT "organization_id","customer_id","field_id","position","raw_kind","raw_text","raw_number","raw_boolean","raw_number_text","interpretation_state","parsed_number","parsed_boolean","parsed_date","parsed_timestamp","option_id","option_revision","user_id","attachment_id","lookup_source_id","lookup_revision","lookup_line_id" FROM public.customer_version_custom_field_values WHERE organization_id=target_organization AND customer_id=target_customer AND revision=target_revision EXCEPT SELECT "organization_id","customer_id","field_id","position","raw_kind","raw_text","raw_number","raw_boolean","raw_number_text","interpretation_state","parsed_number","parsed_boolean","parsed_date","parsed_timestamp","option_id","option_revision","user_id","attachment_id","lookup_source_id","lookup_revision","lookup_line_id" FROM public.customer_version_custom_field_values WHERE organization_id=target_organization AND customer_id=target_customer AND revision=version.previous_revision) OR EXISTS (SELECT "organization_id","customer_id","field_id","position","raw_kind","raw_text","raw_number","raw_boolean","raw_number_text","interpretation_state","parsed_number","parsed_boolean","parsed_date","parsed_timestamp","option_id","option_revision","user_id","attachment_id","lookup_source_id","lookup_revision","lookup_line_id" FROM public.customer_version_custom_field_values WHERE organization_id=target_organization AND customer_id=target_customer AND revision=version.previous_revision EXCEPT SELECT "organization_id","customer_id","field_id","position","raw_kind","raw_text","raw_number","raw_boolean","raw_number_text","interpretation_state","parsed_number","parsed_boolean","parsed_date","parsed_timestamp","option_id","option_revision","user_id","attachment_id","lookup_source_id","lookup_revision","lookup_line_id" FROM public.customer_version_custom_field_values WHERE organization_id=target_organization AND customer_id=target_customer AND revision=target_revision) THEN
    RAISE EXCEPTION 'Customer Custom Field omission and retirement preserve every prior field and item' USING ERRCODE='23514',CONSTRAINT='customer_custom_field_preserve';
  END IF;
END $$;


--
-- Name: masters_assert_customer_custom_field_uniqueness(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_assert_customer_custom_field_uniqueness(target_organization uuid, target_customer uuid, target_revision integer) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.customer_version_custom_fields field JOIN public.custom_field_versions definition
      ON definition.organization_id=field.organization_id AND definition.field_id=field.field_id AND definition.revision=field.field_revision
    WHERE field.organization_id=target_organization AND field.customer_id=target_customer AND field.revision=target_revision
      AND definition.validate_uniqueness
  ) THEN RETURN; END IF;
  IF EXISTS (
    SELECT field.field_id,public.masters_product_custom_field_unique_text(field.is_array,value.raw_kind,value.raw_text,value.raw_number,value.raw_boolean,value.raw_number_text)
    FROM public.customer_version_custom_fields field JOIN public.custom_field_versions definition
      ON definition.organization_id=field.organization_id AND definition.field_id=field.field_id AND definition.revision=field.field_revision
    JOIN public.customer_version_custom_field_values value ON value.organization_id=field.organization_id AND value.customer_id=field.customer_id
      AND value.revision=field.revision AND value.field_id=field.field_id
    WHERE field.organization_id=target_organization AND field.customer_id=target_customer AND field.revision=target_revision AND definition.validate_uniqueness
      AND public.masters_product_custom_field_unique_text(field.is_array,value.raw_kind,value.raw_text,value.raw_number,value.raw_boolean,value.raw_number_text) IS NOT NULL
    GROUP BY field.field_id,public.masters_product_custom_field_unique_text(field.is_array,value.raw_kind,value.raw_text,value.raw_number,value.raw_boolean,value.raw_number_text)
    HAVING count(*)>1
  ) THEN RAISE EXCEPTION 'A unique Custom Field contains duplicate values' USING ERRCODE='23514',CONSTRAINT='customer_custom_field_unique'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.customer_version_custom_fields field JOIN public.custom_field_versions definition
      ON definition.organization_id=field.organization_id AND definition.field_id=field.field_id AND definition.revision=field.field_revision
    JOIN public.customer_version_custom_field_values value ON value.organization_id=field.organization_id AND value.customer_id=field.customer_id
      AND value.revision=field.revision AND value.field_id=field.field_id
    CROSS JOIN LATERAL (SELECT public.masters_product_custom_field_unique_text(field.is_array,value.raw_kind,value.raw_text,value.raw_number,value.raw_boolean,value.raw_number_text) AS text) incoming
    JOIN public.customer_version_custom_field_values existing ON existing.organization_id=field.organization_id AND existing.field_id=field.field_id
      AND existing.raw_text IS NOT NULL AND md5(existing.raw_text)=md5(incoming.text) AND existing.raw_text=incoming.text
    JOIN public.customers customer ON customer.organization_id=existing.organization_id AND customer.id=existing.customer_id AND customer.revision=existing.revision AND NOT customer.retired
    WHERE field.organization_id=target_organization AND field.customer_id=target_customer AND field.revision=target_revision
      AND definition.validate_uniqueness AND incoming.text IS NOT NULL AND existing.customer_id<>target_customer
  ) THEN RAISE EXCEPTION 'A unique Custom Field value is already in use' USING ERRCODE='23514',CONSTRAINT='customer_custom_field_unique'; END IF;
END $$;


--
-- Name: masters_assert_customer_custom_fields(uuid, uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_assert_customer_custom_fields(target_organization uuid, target_customer uuid, target_revision integer, check_definition_set boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.customer_versions; field_count integer; minimum_position integer; maximum_position integer; item_count integer;
BEGIN
  SELECT * INTO version FROM public.customer_versions
    WHERE organization_id=target_organization AND customer_id=target_customer AND revision=target_revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'Customer Custom Field history is missing' USING ERRCODE='23514',CONSTRAINT='customer_custom_field_complete'; END IF;
  SELECT count(*),min(position),max(position),coalesce(sum(value_count),0) INTO field_count,minimum_position,maximum_position,item_count
    FROM public.customer_version_custom_fields
    WHERE organization_id=target_organization AND customer_id=target_customer AND revision=target_revision;
  IF field_count<>version.custom_field_count OR item_count>5000
    OR (field_count>0 AND (minimum_position<>0 OR maximum_position<>field_count-1)) THEN
    RAISE EXCEPTION 'Customer Custom Fields require a complete ordered version' USING ERRCODE='23514',CONSTRAINT='customer_custom_field_complete';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.customer_version_custom_fields field LEFT JOIN LATERAL (
      SELECT count(*) AS count,min(position) AS minimum,max(position) AS maximum
      FROM public.customer_version_custom_field_values value
      WHERE value.organization_id=field.organization_id AND value.customer_id=field.customer_id
        AND value.revision=field.revision AND value.field_id=field.field_id
    ) items ON true
    WHERE field.organization_id=target_organization AND field.customer_id=target_customer AND field.revision=target_revision
      AND (items.count<>field.value_count OR (items.count>0 AND (items.minimum<>0 OR items.maximum<>items.count-1)))
  ) THEN RAISE EXCEPTION 'Customer Custom Field items require a complete ordered version' USING ERRCODE='23514',CONSTRAINT='customer_custom_value_complete'; END IF;
  IF version.custom_fields_provided THEN
    IF check_definition_set AND (EXISTS (
      SELECT id,revision FROM public.custom_field_definitions WHERE organization_id=target_organization AND active AND associated_with='customer'
      EXCEPT SELECT field_id,field_revision FROM public.customer_version_custom_fields
        WHERE organization_id=target_organization AND customer_id=target_customer AND revision=target_revision
    ) OR EXISTS (
      SELECT field_id,field_revision FROM public.customer_version_custom_fields
        WHERE organization_id=target_organization AND customer_id=target_customer AND revision=target_revision
      EXCEPT SELECT id,revision FROM public.custom_field_definitions WHERE organization_id=target_organization AND active AND associated_with='customer'
    )) THEN RAISE EXCEPTION 'Customer Custom Field definitions changed' USING ERRCODE='23514',CONSTRAINT='customer_custom_field_definition_set'; END IF;
    IF EXISTS (
      SELECT 1 FROM public.customer_version_custom_fields field JOIN public.custom_field_versions definition
        ON definition.organization_id=field.organization_id AND definition.field_id=field.field_id AND definition.revision=field.field_revision
      WHERE field.organization_id=target_organization AND field.customer_id=target_customer AND field.revision=target_revision AND definition.is_required
      AND NOT (
        (field.is_array AND definition.field_type<>'multi_user_select'
          AND (NOT definition.allows_multiple OR definition.field_type='attachment'))
        OR EXISTS (
        SELECT 1 FROM public.customer_version_custom_field_values value
        WHERE value.organization_id=field.organization_id AND value.customer_id=field.customer_id AND value.revision=field.revision AND value.field_id=field.field_id
          AND CASE
            WHEN definition.field_type='multi_user_select'
              OR (definition.allows_multiple AND definition.field_type IN ('select','lookup')) THEN field.is_array
            WHEN definition.allows_multiple AND definition.field_type<>'attachment' AND NOT field.is_array THEN false
            WHEN NOT field.is_array THEN value.raw_kind<>'text' OR value.raw_text<>''
            WHEN value.raw_kind='boolean' THEN value.raw_boolean
            WHEN value.raw_kind='number' THEN true
            ELSE public.masters_custom_field_trim(value.raw_text)<>''
          END
        )
      )
    ) THEN RAISE EXCEPTION 'A required Customer Custom Field is empty' USING ERRCODE='23514',CONSTRAINT='customer_custom_field_required'; END IF;
  END IF;
END $$;


