--
-- Name: masters_check_vendor_relations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_check_vendor_relations() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE contact_count integer;
BEGIN
  SELECT count(*) INTO contact_count FROM public.vendor_version_contacts WHERE organization_id=NEW.organization_id AND vendor_id=NEW.vendor_id AND revision=NEW.revision;
  IF contact_count<>NEW.contact_count OR EXISTS (
    SELECT 1 FROM public.vendor_version_contacts WHERE organization_id=NEW.organization_id AND vendor_id=NEW.vendor_id AND revision=NEW.revision AND position>=contact_count
  ) THEN RAISE EXCEPTION 'Vendor contacts require a complete ordered snapshot' USING ERRCODE='23514',CONSTRAINT='vendor_relations_complete'; END IF;
  RETURN NULL;
END $$;


--
-- Name: masters_custom_field_trim(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_custom_field_trim(value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT btrim(value,U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')
$$;


--
-- Name: masters_customer_prior_request(uuid, integer, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_customer_prior_request(target_customer uuid, expected_revision integer, request_id uuid, request_fingerprint text, requested_operation text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE org uuid:=public.organization_module_scope(); prior public.customer_versions;
BEGIN
  PERFORM public.masters_require_customer_write();
  IF target_customer IS NULL OR expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 2147483646 OR request_id IS NULL
    OR request_fingerprint IS NULL OR request_fingerprint !~ '^[a-f0-9]{64}$' OR requested_operation IS NULL
    OR requested_operation NOT IN ('create','update','retire') THEN
    RAISE EXCEPTION 'Invalid Customer command' USING ERRCODE='23514',CONSTRAINT='customer_command_input';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('customer-save:'||org::text||':'||request_id::text,0));
  SELECT * INTO prior FROM public.customer_versions version WHERE version.organization_id=org AND version.request_id=masters_customer_prior_request.request_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF prior.customer_id IS DISTINCT FROM target_customer OR coalesce(prior.previous_revision,0) IS DISTINCT FROM expected_revision
    OR prior.operation IS DISTINCT FROM requested_operation OR prior.request_fingerprint IS DISTINCT FROM request_fingerprint
    OR prior.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Customer request was already used for another change' USING ERRCODE='23514',CONSTRAINT='customer_request_reused';
  END IF;
  RETURN prior.revision;
END $_$;


--
-- Name: masters_customer_scheme_context(boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_customer_scheme_context(include_customers boolean, include_samples boolean) RETURNS TABLE("currentYearDigits" text, "nextYearDigits" text, separator text, "currentMonthFormat" text, "nonNablStartNumber" text, "customerCount" double precision, "sampleCount" double precision)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=public.organization_module_scope();
BEGIN
  IF org IS NULL OR NOT public.app_has_permission('masters.manage') OR NOT public.organization_has_module_access('customer') THEN
    RAISE EXCEPTION 'Customer scheme generation requires permission' USING ERRCODE='42501';
  END IF;
  RETURN QUERY SELECT settings.scheme_current_year_digits,settings.scheme_next_year_digits,settings.scheme_separator,
    settings.scheme_month_format,settings.scheme_non_nabl_start_number,
    CASE WHEN include_customers THEN (SELECT count(*)::double precision FROM public.customers customer WHERE customer.organization_id=org AND NOT customer.retired) ELSE 0::double precision END,
    CASE WHEN include_samples THEN (SELECT count(*)::double precision FROM public.samples sample WHERE sample.organization_id=org) ELSE 0::double precision END
  FROM public.organizations organization LEFT JOIN public.organization_laboratory_settings settings ON settings.organization_id=organization.id
  WHERE organization.id=org;
END $$;


--
-- Name: masters_guard_current_product_sample_categories(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_current_product_sample_categories() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE record_organization uuid; record_product uuid; version public.product_versions;
BEGIN
  IF session_user<>'sampleify_app' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'Replace product sample category links through a new saved revision' USING ERRCODE='23514'; END IF;
  record_organization := CASE WHEN TG_OP='DELETE' THEN OLD.organization_id ELSE NEW.organization_id END;
  record_product := CASE WHEN TG_OP='DELETE' THEN OLD.product_id ELSE NEW.product_id END;
  SELECT history.* INTO version FROM public.products product JOIN public.product_versions history
    ON history.organization_id=product.organization_id AND history.product_id=product.id AND history.revision=product.revision AND history.request_id=product.save_request_id
    WHERE product.organization_id=record_organization AND product.id=record_product;
  IF version.product_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
    OR version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Product sample category changes require their new active revision' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' AND NOT EXISTS (SELECT 1 FROM public.product_version_sample_categories
    WHERE organization_id=record_organization AND product_id=record_product AND revision=version.revision AND sample_category_id=NEW.sample_category_id) THEN
    RAISE EXCEPTION 'A current product sample category must belong to the new saved revision' USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_current_product_tags(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_current_product_tags() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE record_organization uuid; record_product uuid; version public.product_versions;
BEGIN
  IF session_user<>'sampleify_app' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'Replace product tag links through a new saved revision' USING ERRCODE='23514'; END IF;
  record_organization := CASE WHEN TG_OP='DELETE' THEN OLD.organization_id ELSE NEW.organization_id END;
  record_product := CASE WHEN TG_OP='DELETE' THEN OLD.product_id ELSE NEW.product_id END;
  SELECT history.* INTO version FROM public.products product JOIN public.product_versions history
    ON history.organization_id=product.organization_id AND history.product_id=product.id AND history.revision=product.revision AND history.request_id=product.save_request_id
    WHERE product.organization_id=record_organization AND product.id=record_product;
  IF version.product_id IS NULL OR version.created_transaction_id<>pg_current_xact_id() OR version.operation='retire'
    OR version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Product tag changes require their new active revision' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' AND NOT EXISTS (SELECT 1 FROM public.product_version_tags
    WHERE organization_id=record_organization AND product_id=record_product AND revision=version.revision AND tag_id=NEW.tag_id) THEN
    RAISE EXCEPTION 'A current product tag must belong to the new saved revision' USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_custom_field_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_custom_field_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.custom_field_versions;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Custom field history is immutable' USING ERRCODE='55000'; END IF;
  IF TG_TABLE_NAME='custom_field_versions' THEN
    IF NEW.created_transaction_id<>pg_current_xact_id() OR NEW.saved_at<>transaction_timestamp()
      OR (session_user='sampleify_app' AND NEW.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid) THEN
      RAISE EXCEPTION 'Custom field history requires the actual editor and transaction' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO version FROM public.custom_field_versions
      WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=NEW.revision;
    IF version.field_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
      OR NOT EXISTS (SELECT 1 FROM public.custom_field_definitions WHERE organization_id=NEW.organization_id AND id=NEW.field_id
        AND revision=NEW.revision AND save_request_id=version.request_id)
      OR (session_user='sampleify_app' AND version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid) THEN
      RAISE EXCEPTION 'Custom field links require their new version transaction' USING ERRCODE='23514';
    END IF;
    IF NEW.position>=(CASE WHEN TG_TABLE_NAME='custom_field_version_options' THEN version.option_count ELSE version.edit_role_count END) THEN
      RAISE EXCEPTION 'Custom field link position exceeds its saved count' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_customer_custom_field_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_customer_custom_field_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE expected_count integer;
BEGIN
  IF NEW.save_source IS NULL AND session_user<>'sampleify_app' THEN RETURN NEW; END IF;
  IF NEW.save_source='registration' THEN
    PERFORM public.organization_require_module_access('customer');
    IF TG_OP<>'INSERT' OR NOT public.app_has_permission('samples.create') OR NEW.custom_fields_provided OR NEW.custom_field_count<>0 THEN
      RAISE EXCEPTION 'Registration fields require the native quick-create command' USING ERRCODE='42501';
    END IF;
    RETURN NEW;
  END IF;
  PERFORM public.masters_require_customer_write();
  IF NEW.organization_id IS DISTINCT FROM public.organization_module_scope() THEN
    RAISE EXCEPTION 'Customer fields require the authenticated organization' USING ERRCODE='42501';
  END IF;
  IF TG_OP='UPDATE' AND EXISTS (
    SELECT 1 FROM public.customer_versions WHERE organization_id=OLD.organization_id AND customer_id=OLD.id AND revision=OLD.revision
  ) THEN PERFORM public.masters_assert_customer_custom_fields(OLD.organization_id,OLD.id,OLD.revision); END IF;
  IF NEW.retired AND NEW.custom_fields_provided THEN
    RAISE EXCEPTION 'Customer retirement preserves Custom Fields' USING ERRCODE='23514',CONSTRAINT='customer_custom_field_preserve';
  END IF;
  IF NEW.custom_fields_provided THEN
    SELECT count(*) INTO expected_count FROM public.custom_field_definitions
      WHERE organization_id=NEW.organization_id AND associated_with='customer' AND active;
    IF expected_count<>NEW.custom_field_count THEN
      RAISE EXCEPTION 'Provide the current Customer Custom Fields' USING ERRCODE='23514',CONSTRAINT='customer_custom_field_definition_set';
    END IF;
  ELSE
    expected_count := CASE WHEN TG_OP='INSERT' THEN 0 ELSE OLD.custom_field_count END;
    IF NEW.custom_field_count<>expected_count OR (NOT NEW.retired AND EXISTS (
      SELECT 1 FROM public.custom_field_definitions WHERE organization_id=NEW.organization_id AND associated_with='customer' AND active
    )) THEN RAISE EXCEPTION 'Customer Custom Field omission requires no current definitions' USING ERRCODE='23514',CONSTRAINT='customer_custom_field_preserve'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_customer_custom_field_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_customer_custom_field_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.customer_versions; field public.customer_version_custom_fields; definition public.custom_field_versions;
  related_count integer; previous_field_ids uuid[];
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Customer Custom Field history is immutable' USING ERRCODE='55000'; END IF;
  SELECT * INTO version FROM public.customer_versions WHERE organization_id=NEW.organization_id AND customer_id=NEW.customer_id AND revision=NEW.revision;
  IF NEW.organization_id IS DISTINCT FROM public.organization_module_scope() OR version.customer_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
    OR (version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
      OR NOT EXISTS (SELECT 1 FROM public.customers WHERE organization_id=NEW.organization_id AND id=NEW.customer_id
        AND revision=NEW.revision AND save_request_id=version.request_id)) THEN
    RAISE EXCEPTION 'Customer Custom Fields require their new version transaction' USING ERRCODE='23514',CONSTRAINT='customer_custom_field_transaction';
  END IF;
  IF TG_TABLE_NAME='customer_version_custom_fields' THEN
    IF NEW.position>=version.custom_field_count THEN RAISE EXCEPTION 'Customer Custom Field position exceeds its saved count' USING ERRCODE='23514'; END IF;
    SELECT * INTO definition FROM public.custom_field_versions
      WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=NEW.field_revision;
    IF NOT FOUND OR definition.field_type<>NEW.field_type THEN
      RAISE EXCEPTION 'Customer Custom Field type must match its definition' USING ERRCODE='23514',CONSTRAINT='customer_custom_field_type';
    END IF;
    IF version.custom_fields_provided AND NOT EXISTS (
      SELECT 1 FROM public.custom_field_definitions WHERE organization_id=NEW.organization_id AND id=NEW.field_id
        AND revision=NEW.field_revision AND associated_with='customer' AND active
    ) THEN RAISE EXCEPTION 'Select the current Customer Custom Field revision' USING ERRCODE='23514',CONSTRAINT='customer_custom_field_definition_set'; END IF;
  ELSE
    SELECT * INTO field FROM public.customer_version_custom_fields
      WHERE organization_id=NEW.organization_id AND customer_id=NEW.customer_id AND revision=NEW.revision AND field_id=NEW.field_id;
    IF NOT FOUND OR NEW.position>=field.value_count THEN
      RAISE EXCEPTION 'Customer Custom Field items require their declared field and count' USING ERRCODE='23514',CONSTRAINT='customer_custom_value_complete';
    END IF;
    IF field.is_array AND NEW.raw_kind='text' AND public.masters_custom_field_trim(NEW.raw_text)='' THEN
      RAISE EXCEPTION 'Remove blank repeated Customer Custom Field items' USING ERRCODE='23514';
    END IF;
    IF field.field_type='lookup' THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      IF NEW.interpretation_state='invalid' AND version.previous_revision>0 THEN
        SELECT array_agg(previous.field_id) INTO previous_field_ids
          FROM public.customer_version_custom_fields previous JOIN public.custom_field_versions saved_definition
            ON saved_definition.organization_id=previous.organization_id AND saved_definition.field_id=previous.field_id
              AND saved_definition.revision=previous.field_revision
          WHERE previous.organization_id=NEW.organization_id AND previous.customer_id=NEW.customer_id
            AND previous.revision=version.previous_revision AND saved_definition.key=definition.key;
      END IF;
    ELSIF field.field_type='select' AND version.previous_revision>0 AND (
      NEW.interpretation_state='invalid' OR version.custom_fields_provided AND NEW.option_revision<>field.field_revision
    ) THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      -- Restrict prior items to the same saved key before checking their raw values.
      WITH key_definitions AS MATERIALIZED (
        SELECT field_id,revision FROM public.custom_field_versions WHERE organization_id=NEW.organization_id AND key=definition.key
      ) SELECT array_agg(previous_field.field_id) INTO previous_field_ids
        FROM key_definitions previous_definition JOIN LATERAL (
          SELECT field_id FROM public.customer_version_custom_fields
            WHERE organization_id=NEW.organization_id AND customer_id=NEW.customer_id AND revision=version.previous_revision
              AND field_id=previous_definition.field_id AND field_revision=previous_definition.revision LIMIT 1
        ) previous_field ON true;
    ELSIF field.field_type='attachment' AND NEW.interpretation_state='valid' THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      IF version.previous_revision>0 THEN
        WITH key_definitions AS MATERIALIZED (
          SELECT field_id,revision FROM public.custom_field_versions WHERE organization_id=NEW.organization_id AND key=definition.key
        ) SELECT array_agg(previous_field.field_id) INTO previous_field_ids
          FROM key_definitions previous_definition JOIN LATERAL (
            SELECT field_id FROM public.customer_version_custom_fields
              WHERE organization_id=NEW.organization_id AND customer_id=NEW.customer_id AND revision=version.previous_revision
                AND field_id=previous_definition.field_id AND field_revision=previous_definition.revision LIMIT 1
          ) previous_field ON true;
      END IF;
    END IF;
    related_count := num_nonnulls(NEW.parsed_number,NEW.parsed_boolean,NEW.parsed_date,NEW.parsed_timestamp,NEW.option_id,NEW.option_revision,NEW.user_id,NEW.attachment_id,NEW.lookup_source_id,NEW.lookup_revision,NEW.lookup_line_id);
    IF NEW.interpretation_state='valid' THEN
      CASE field.field_type
        WHEN 'number' THEN
          IF NEW.parsed_number IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A numeric field requires its typed numeric interpretation' USING ERRCODE='23514'; END IF;
        WHEN 'checkbox' THEN
          IF NEW.parsed_boolean IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A checkbox requires its typed boolean interpretation' USING ERRCODE='23514'; END IF;
        WHEN 'date' THEN
          IF NEW.parsed_date IS NULL OR NEW.parsed_timestamp IS NULL OR related_count<>2 THEN RAISE EXCEPTION 'A date requires its local date and parsed instant' USING ERRCODE='23514'; END IF;
        WHEN 'date_time' THEN
          IF NEW.parsed_timestamp IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A date-time field requires its parsed instant' USING ERRCODE='23514'; END IF;
        WHEN 'select' THEN
          IF NEW.option_id IS NULL OR NEW.option_revision IS NULL OR related_count<>2 OR NOT EXISTS (
            SELECT 1 FROM public.custom_field_version_options option WHERE option.organization_id=NEW.organization_id
              AND option.field_id=NEW.field_id AND option.revision=NEW.option_revision AND option.id=NEW.option_id
              AND option.key=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
          ) THEN RAISE EXCEPTION 'A selection requires its exact field option' USING ERRCODE='23514',CONSTRAINT='customer_custom_value_option'; END IF;
          IF version.custom_fields_provided AND NEW.option_revision<>field.field_revision AND NOT EXISTS (
            SELECT 1 FROM public.customer_version_custom_field_values previous
            WHERE previous.organization_id=NEW.organization_id AND previous.customer_id=NEW.customer_id AND previous.revision=version.previous_revision
              AND previous.field_id=ANY(previous_field_ids)
              AND previous.field_id=NEW.field_id AND previous.option_id=NEW.option_id AND previous.option_revision=NEW.option_revision
              AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
                IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
          ) THEN RAISE EXCEPTION 'An older selection must belong to the previous Customer revision' USING ERRCODE='23514',CONSTRAINT='customer_custom_value_option'; END IF;
        WHEN 'multi_user_select' THEN
          IF NEW.user_id IS NULL OR related_count<>1 OR NEW.raw_kind<>'text' OR lower(NEW.raw_text)<>NEW.user_id::text THEN
            RAISE EXCEPTION 'A user selection requires its member reference' USING ERRCODE='23514',CONSTRAINT='customer_custom_value_user';
          END IF;
        WHEN 'attachment' THEN
          IF NEW.attachment_id IS NULL OR related_count<>1 OR NEW.raw_kind<>'text' OR lower(NEW.raw_text)<>NEW.attachment_id::text OR NOT EXISTS (
            SELECT 1 FROM public.custom_field_attachments attachment JOIN public.custom_field_versions uploaded_definition
              ON uploaded_definition.organization_id=attachment.organization_id AND uploaded_definition.field_id=attachment.field_id
                AND uploaded_definition.revision=attachment.field_revision
            WHERE attachment.organization_id=NEW.organization_id AND attachment.id=NEW.attachment_id
              AND uploaded_definition.associated_with='customer' AND uploaded_definition.field_type='attachment'
              AND (attachment.field_id=NEW.field_id OR uploaded_definition.key=definition.key OR EXISTS (
                SELECT 1 FROM public.customer_version_custom_field_values previous
                WHERE previous.organization_id=NEW.organization_id AND previous.customer_id=NEW.customer_id
                  AND previous.revision=version.previous_revision AND previous.field_id=ANY(previous_field_ids)
                  AND previous.attachment_id=NEW.attachment_id
              ))
          ) THEN RAISE EXCEPTION 'An attachment must belong to its Custom Field' USING ERRCODE='23514',CONSTRAINT='customer_custom_value_attachment'; END IF;
        WHEN 'lookup' THEN
          IF NEW.lookup_source_id IS NULL OR NEW.lookup_revision IS NULL OR NEW.lookup_line_id IS NULL OR related_count<>3
            OR definition.lookup_source_id IS DISTINCT FROM NEW.lookup_source_id
            OR NEW.lookup_line_id IS DISTINCT FROM (CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END)
            OR NOT EXISTS (
              SELECT 1 FROM public.custom_field_lookup_lines line
              WHERE line.organization_id=NEW.organization_id AND line.source_id=NEW.lookup_source_id
                AND line.revision=NEW.lookup_revision AND line.original_line_id=NEW.lookup_line_id
                AND (NOT version.custom_fields_provided OR EXISTS (
                  SELECT 1 FROM public.custom_field_lookup_sources source
                    WHERE source.organization_id=line.organization_id AND source.id=line.source_id AND source.revision=line.revision
                ))
            ) THEN RAISE EXCEPTION 'A lookup requires its exact observed line and current source for a new capture' USING ERRCODE='23514',CONSTRAINT='customer_custom_value_lookup'; END IF;
        ELSE
          IF related_count<>0 THEN RAISE EXCEPTION 'Text fields cannot contain another field type interpretation' USING ERRCODE='23514'; END IF;
      END CASE;
    ELSIF NEW.interpretation_state='invalid' AND field.field_type='select' THEN
      -- Keep an unavailable saved value without claiming a foreign definition's option.
      IF (version.custom_fields_provided AND EXISTS (
        SELECT 1 FROM public.custom_field_version_options option WHERE option.organization_id=NEW.organization_id
          AND option.field_id=NEW.field_id AND option.revision=field.field_revision
          AND option.key=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
      )) OR NOT EXISTS (
        SELECT 1 FROM public.customer_version_custom_field_values previous
          WHERE previous.organization_id=NEW.organization_id AND previous.customer_id=NEW.customer_id AND previous.revision=version.previous_revision
            AND previous.field_id=ANY(previous_field_ids)
            AND (previous.field_id<>NEW.field_id OR previous.option_id IS NULL)
            AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
              IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
      ) THEN RAISE EXCEPTION 'An unresolved selection requires the same previous saved-key value' USING ERRCODE='23514',CONSTRAINT='customer_custom_value_option'; END IF;
    ELSIF NEW.interpretation_state='invalid' AND field.field_type='lookup' THEN
      -- Newly supplied captures use current choices; omitted fields preserve their exact frozen interpretation.
      IF (version.custom_fields_provided AND EXISTS (
        SELECT 1 FROM public.custom_field_lookup_lines line JOIN public.custom_field_lookup_sources source
          ON source.organization_id=line.organization_id AND source.id=line.source_id AND source.revision=line.revision
        WHERE line.organization_id=NEW.organization_id AND line.source_id=definition.lookup_source_id
          AND line.original_line_id=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
      )) OR NOT EXISTS (
        SELECT 1 FROM public.customer_version_custom_field_values previous
          WHERE previous.organization_id=NEW.organization_id AND previous.customer_id=NEW.customer_id AND previous.revision=version.previous_revision
            AND previous.field_id=ANY(previous_field_ids)
            AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
              IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
      ) THEN RAISE EXCEPTION 'An unavailable lookup requires the same previous saved-key value' USING ERRCODE='23514',CONSTRAINT='customer_custom_value_lookup'; END IF;
    ELSIF NEW.interpretation_state IN ('invalid','out_of_range') AND field.field_type NOT IN ('number','date','date_time') THEN
      RAISE EXCEPTION 'Only numeric and date fields retain invalid interpretations' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_customer_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_customer_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.customer_versions;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Customer history is immutable' USING ERRCODE='55000'; END IF;
  IF TG_TABLE_NAME='customer_versions' THEN
    IF NEW.created_transaction_id IS DISTINCT FROM pg_current_xact_id() OR NEW.saved_at IS DISTINCT FROM transaction_timestamp()
      OR NEW.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
      OR NEW.organization_id IS DISTINCT FROM public.organization_module_scope()
      OR NOT EXISTS (SELECT 1 FROM public.customers customer WHERE customer.organization_id=NEW.organization_id AND customer.id=NEW.customer_id
        AND customer.revision=NEW.revision AND customer.save_request_id=NEW.request_id AND customer.save_source=NEW.save_source) THEN
      RAISE EXCEPTION 'Customer history requires its actual saved command' USING ERRCODE='23514',CONSTRAINT='customer_history_transaction';
    END IF;
  ELSE
    SELECT * INTO version FROM public.customer_versions WHERE organization_id=NEW.organization_id AND customer_id=NEW.customer_id AND revision=NEW.revision;
    IF version.customer_id IS NULL OR version.created_transaction_id IS DISTINCT FROM pg_current_xact_id()
      OR version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid THEN
      RAISE EXCEPTION 'Customer relationships require their actual save transaction' USING ERRCODE='23514',CONSTRAINT='customer_history_transaction';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_decision_rule_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_decision_rule_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Decision Rule history is immutable' USING ERRCODE='55000'; END IF;
  IF NEW.created_transaction_id<>pg_current_xact_id() OR NEW.saved_at<>transaction_timestamp()
    OR (session_user='sampleify_app' AND NEW.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid) THEN
    RAISE EXCEPTION 'Decision Rule history requires the actual editor and transaction' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_instrument_custom_field_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_instrument_custom_field_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE expected_count integer;
BEGIN
  PERFORM public.instruments_require_writer();
  IF NEW.organization_id IS DISTINCT FROM public.organization_module_scope() THEN
    RAISE EXCEPTION 'Instrument fields require the authenticated organization' USING ERRCODE='42501';
  END IF;
  IF TG_OP='UPDATE' AND EXISTS (
    SELECT 1 FROM public.instrument_versions WHERE organization_id=OLD.organization_id AND instrument_id=OLD.id AND revision=OLD.revision
  ) THEN PERFORM public.masters_assert_instrument_custom_fields(OLD.organization_id,OLD.id,OLD.revision); END IF;
  IF NEW.retired AND NEW.custom_fields_provided THEN
    RAISE EXCEPTION 'Instrument retirement preserves Custom Fields' USING ERRCODE='23514',CONSTRAINT='instrument_custom_field_preserve';
  END IF;
  IF NEW.custom_fields_provided THEN
    SELECT count(*) INTO expected_count FROM public.custom_field_definitions
      WHERE organization_id=NEW.organization_id AND associated_with='instrument' AND active;
    IF expected_count<>NEW.custom_field_count THEN
      RAISE EXCEPTION 'Provide the current Instrument Custom Fields' USING ERRCODE='23514',CONSTRAINT='instrument_custom_field_definition_set';
    END IF;
  ELSE
    expected_count := CASE WHEN TG_OP='INSERT' THEN 0 ELSE OLD.custom_field_count END;
    IF NEW.custom_field_count<>expected_count OR (NOT NEW.retired AND EXISTS (
      SELECT 1 FROM public.custom_field_definitions WHERE organization_id=NEW.organization_id AND associated_with='instrument' AND active
    )) THEN RAISE EXCEPTION 'Instrument Custom Field omission requires no current definitions' USING ERRCODE='23514',CONSTRAINT='instrument_custom_field_preserve'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_instrument_custom_field_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_instrument_custom_field_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.instrument_versions; field public.instrument_version_custom_fields; definition public.custom_field_versions;
  related_count integer; previous_field_ids uuid[];
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Instrument Custom Field history is immutable' USING ERRCODE='55000'; END IF;
  SELECT * INTO version FROM public.instrument_versions WHERE organization_id=NEW.organization_id AND instrument_id=NEW.instrument_id AND revision=NEW.revision;
  IF NEW.organization_id IS DISTINCT FROM public.organization_module_scope() OR version.instrument_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
    OR (version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
      OR NOT EXISTS (SELECT 1 FROM public.instruments WHERE organization_id=NEW.organization_id AND id=NEW.instrument_id
        AND revision=NEW.revision AND save_request_id=version.request_id)) THEN
    RAISE EXCEPTION 'Instrument Custom Fields require their new version transaction' USING ERRCODE='23514',CONSTRAINT='instrument_custom_field_transaction';
  END IF;
  IF TG_TABLE_NAME='instrument_version_custom_fields' THEN
    IF NEW.position>=version.custom_field_count THEN RAISE EXCEPTION 'Instrument Custom Field position exceeds its saved count' USING ERRCODE='23514'; END IF;
    SELECT * INTO definition FROM public.custom_field_versions
      WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=NEW.field_revision;
    IF NOT FOUND OR definition.field_type<>NEW.field_type THEN
      RAISE EXCEPTION 'Instrument Custom Field type must match its definition' USING ERRCODE='23514',CONSTRAINT='instrument_custom_field_type';
    END IF;
    IF version.custom_fields_provided AND NOT EXISTS (
      SELECT 1 FROM public.custom_field_definitions WHERE organization_id=NEW.organization_id AND id=NEW.field_id
        AND revision=NEW.field_revision AND associated_with='instrument' AND active
    ) THEN RAISE EXCEPTION 'Select the current Instrument Custom Field revision' USING ERRCODE='23514',CONSTRAINT='instrument_custom_field_definition_set'; END IF;
  ELSE
    SELECT * INTO field FROM public.instrument_version_custom_fields
      WHERE organization_id=NEW.organization_id AND instrument_id=NEW.instrument_id AND revision=NEW.revision AND field_id=NEW.field_id;
    IF NOT FOUND OR NEW.position>=field.value_count THEN
      RAISE EXCEPTION 'Instrument Custom Field items require their declared field and count' USING ERRCODE='23514',CONSTRAINT='instrument_custom_value_complete';
    END IF;
    IF field.is_array AND NEW.raw_kind='text' AND public.masters_custom_field_trim(NEW.raw_text)='' THEN
      RAISE EXCEPTION 'Remove blank repeated Instrument Custom Field items' USING ERRCODE='23514';
    END IF;
    IF field.field_type='lookup' THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      IF NEW.interpretation_state='invalid' AND version.previous_revision>0 THEN
        SELECT array_agg(previous.field_id) INTO previous_field_ids
          FROM public.instrument_version_custom_fields previous JOIN public.custom_field_versions saved_definition
            ON saved_definition.organization_id=previous.organization_id AND saved_definition.field_id=previous.field_id
              AND saved_definition.revision=previous.field_revision
          WHERE previous.organization_id=NEW.organization_id AND previous.instrument_id=NEW.instrument_id
            AND previous.revision=version.previous_revision AND saved_definition.key=definition.key;
      END IF;
    ELSIF field.field_type='select' AND version.previous_revision>0 AND (
      NEW.interpretation_state='invalid' OR version.custom_fields_provided AND NEW.option_revision<>field.field_revision
    ) THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      -- Restrict prior items to the same saved key before checking their raw values.
      WITH key_definitions AS MATERIALIZED (
        SELECT field_id,revision FROM public.custom_field_versions WHERE organization_id=NEW.organization_id AND key=definition.key
      ) SELECT array_agg(previous_field.field_id) INTO previous_field_ids
        FROM key_definitions previous_definition JOIN LATERAL (
          SELECT field_id FROM public.instrument_version_custom_fields
            WHERE organization_id=NEW.organization_id AND instrument_id=NEW.instrument_id AND revision=version.previous_revision
              AND field_id=previous_definition.field_id AND field_revision=previous_definition.revision LIMIT 1
        ) previous_field ON true;
    ELSIF field.field_type='attachment' AND NEW.interpretation_state='valid' THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      IF version.previous_revision>0 THEN
        WITH key_definitions AS MATERIALIZED (
          SELECT field_id,revision FROM public.custom_field_versions WHERE organization_id=NEW.organization_id AND key=definition.key
        ) SELECT array_agg(previous_field.field_id) INTO previous_field_ids
          FROM key_definitions previous_definition JOIN LATERAL (
            SELECT field_id FROM public.instrument_version_custom_fields
              WHERE organization_id=NEW.organization_id AND instrument_id=NEW.instrument_id AND revision=version.previous_revision
                AND field_id=previous_definition.field_id AND field_revision=previous_definition.revision LIMIT 1
          ) previous_field ON true;
      END IF;
    END IF;
    related_count := num_nonnulls(NEW.parsed_number,NEW.parsed_boolean,NEW.parsed_date,NEW.parsed_timestamp,NEW.option_id,NEW.option_revision,NEW.user_id,NEW.attachment_id,NEW.lookup_source_id,NEW.lookup_revision,NEW.lookup_line_id);
    IF NEW.interpretation_state='valid' THEN
      CASE field.field_type
        WHEN 'number' THEN
          IF NEW.parsed_number IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A numeric field requires its typed numeric interpretation' USING ERRCODE='23514'; END IF;
        WHEN 'checkbox' THEN
          IF NEW.parsed_boolean IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A checkbox requires its typed boolean interpretation' USING ERRCODE='23514'; END IF;
        WHEN 'date' THEN
          IF NEW.parsed_date IS NULL OR NEW.parsed_timestamp IS NULL OR related_count<>2 THEN RAISE EXCEPTION 'A date requires its local date and parsed instant' USING ERRCODE='23514'; END IF;
        WHEN 'date_time' THEN
          IF NEW.parsed_timestamp IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A date-time field requires its parsed instant' USING ERRCODE='23514'; END IF;
        WHEN 'select' THEN
          IF NEW.option_id IS NULL OR NEW.option_revision IS NULL OR related_count<>2 OR NOT EXISTS (
            SELECT 1 FROM public.custom_field_version_options option WHERE option.organization_id=NEW.organization_id
              AND option.field_id=NEW.field_id AND option.revision=NEW.option_revision AND option.id=NEW.option_id
              AND option.key=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
          ) THEN RAISE EXCEPTION 'A selection requires its exact field option' USING ERRCODE='23514',CONSTRAINT='instrument_custom_value_option'; END IF;
          IF version.custom_fields_provided AND NEW.option_revision<>field.field_revision AND NOT EXISTS (
            SELECT 1 FROM public.instrument_version_custom_field_values previous
            WHERE previous.organization_id=NEW.organization_id AND previous.instrument_id=NEW.instrument_id AND previous.revision=version.previous_revision
              AND previous.field_id=ANY(previous_field_ids)
              AND previous.field_id=NEW.field_id AND previous.option_id=NEW.option_id AND previous.option_revision=NEW.option_revision
              AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
                IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
          ) THEN RAISE EXCEPTION 'An older selection must belong to the previous Instrument revision' USING ERRCODE='23514',CONSTRAINT='instrument_custom_value_option'; END IF;
        WHEN 'multi_user_select' THEN
          IF NEW.user_id IS NULL OR related_count<>1 OR NEW.raw_kind<>'text' OR lower(NEW.raw_text)<>NEW.user_id::text THEN
            RAISE EXCEPTION 'A user selection requires its member reference' USING ERRCODE='23514',CONSTRAINT='instrument_custom_value_user';
          END IF;
        WHEN 'attachment' THEN
          IF NEW.attachment_id IS NULL OR related_count<>1 OR NEW.raw_kind<>'text' OR lower(NEW.raw_text)<>NEW.attachment_id::text OR NOT EXISTS (
            SELECT 1 FROM public.custom_field_attachments attachment JOIN public.custom_field_versions uploaded_definition
              ON uploaded_definition.organization_id=attachment.organization_id AND uploaded_definition.field_id=attachment.field_id
                AND uploaded_definition.revision=attachment.field_revision
            WHERE attachment.organization_id=NEW.organization_id AND attachment.id=NEW.attachment_id
              AND uploaded_definition.associated_with='instrument' AND uploaded_definition.field_type='attachment'
              AND (attachment.field_id=NEW.field_id OR uploaded_definition.key=definition.key OR EXISTS (
                SELECT 1 FROM public.instrument_version_custom_field_values previous
                WHERE previous.organization_id=NEW.organization_id AND previous.instrument_id=NEW.instrument_id
                  AND previous.revision=version.previous_revision AND previous.field_id=ANY(previous_field_ids)
                  AND previous.attachment_id=NEW.attachment_id
              ))
          ) THEN RAISE EXCEPTION 'An attachment must belong to its Custom Field' USING ERRCODE='23514',CONSTRAINT='instrument_custom_value_attachment'; END IF;
        WHEN 'lookup' THEN
          IF NEW.lookup_source_id IS NULL OR NEW.lookup_revision IS NULL OR NEW.lookup_line_id IS NULL OR related_count<>3
            OR definition.lookup_source_id IS DISTINCT FROM NEW.lookup_source_id
            OR NEW.lookup_line_id IS DISTINCT FROM (CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END)
            OR NOT EXISTS (
              SELECT 1 FROM public.custom_field_lookup_lines line
              WHERE line.organization_id=NEW.organization_id AND line.source_id=NEW.lookup_source_id
                AND line.revision=NEW.lookup_revision AND line.original_line_id=NEW.lookup_line_id
                AND (NOT version.custom_fields_provided OR EXISTS (
                  SELECT 1 FROM public.custom_field_lookup_sources source
                    WHERE source.organization_id=line.organization_id AND source.id=line.source_id AND source.revision=line.revision
                ))
            ) THEN RAISE EXCEPTION 'A lookup requires its exact observed line and current source for a new capture' USING ERRCODE='23514',CONSTRAINT='instrument_custom_value_lookup'; END IF;
        ELSE
          IF related_count<>0 THEN RAISE EXCEPTION 'Text fields cannot contain another field type interpretation' USING ERRCODE='23514'; END IF;
      END CASE;
    ELSIF NEW.interpretation_state='invalid' AND field.field_type='select' THEN
      -- Keep an unavailable saved value without claiming a foreign definition's option.
      IF (version.custom_fields_provided AND EXISTS (
        SELECT 1 FROM public.custom_field_version_options option WHERE option.organization_id=NEW.organization_id
          AND option.field_id=NEW.field_id AND option.revision=field.field_revision
          AND option.key=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
      )) OR NOT EXISTS (
        SELECT 1 FROM public.instrument_version_custom_field_values previous
          WHERE previous.organization_id=NEW.organization_id AND previous.instrument_id=NEW.instrument_id AND previous.revision=version.previous_revision
            AND previous.field_id=ANY(previous_field_ids)
            AND (previous.field_id<>NEW.field_id OR previous.option_id IS NULL)
            AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
              IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
      ) THEN RAISE EXCEPTION 'An unresolved selection requires the same previous saved-key value' USING ERRCODE='23514',CONSTRAINT='instrument_custom_value_option'; END IF;
    ELSIF NEW.interpretation_state='invalid' AND field.field_type='lookup' THEN
      -- Newly supplied captures use current choices; omitted fields preserve their exact frozen interpretation.
      IF (version.custom_fields_provided AND EXISTS (
        SELECT 1 FROM public.custom_field_lookup_lines line JOIN public.custom_field_lookup_sources source
          ON source.organization_id=line.organization_id AND source.id=line.source_id AND source.revision=line.revision
        WHERE line.organization_id=NEW.organization_id AND line.source_id=definition.lookup_source_id
          AND line.original_line_id=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
      )) OR NOT EXISTS (
        SELECT 1 FROM public.instrument_version_custom_field_values previous
          WHERE previous.organization_id=NEW.organization_id AND previous.instrument_id=NEW.instrument_id AND previous.revision=version.previous_revision
            AND previous.field_id=ANY(previous_field_ids)
            AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
              IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
      ) THEN RAISE EXCEPTION 'An unavailable lookup requires the same previous saved-key value' USING ERRCODE='23514',CONSTRAINT='instrument_custom_value_lookup'; END IF;
    ELSIF NEW.interpretation_state IN ('invalid','out_of_range') AND field.field_type NOT IN ('number','date','date_time') THEN
      RAISE EXCEPTION 'Only numeric and date fields retain invalid interpretations' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_lookup_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_lookup_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.custom_field_lookup_versions; source public.custom_field_lookup_sources;
  actor uuid := nullif(current_setting('app.user_id',true),'')::uuid;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Lookup observations are immutable' USING ERRCODE='55000'; END IF;
  SELECT * INTO source FROM public.custom_field_lookup_sources
    WHERE organization_id=NEW.organization_id AND id=NEW.source_id;
  IF TG_TABLE_NAME='custom_field_lookup_versions' THEN
    IF NEW.created_transaction_id<>pg_current_xact_id() OR NEW.observed_at<>transaction_timestamp()
      OR actor IS NULL OR NEW.observed_by IS DISTINCT FROM actor OR source.id IS NULL
      OR (NEW.revision,NEW.request_id,NEW.name,NEW.line_count) IS DISTINCT FROM (source.revision,source.request_id,source.name,source.line_count) THEN
      RAISE EXCEPTION 'Lookup history requires the actual observation transaction and source head' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO version FROM public.custom_field_lookup_versions
      WHERE organization_id=NEW.organization_id AND source_id=NEW.source_id AND revision=NEW.revision;
    IF version.source_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
      OR source.id IS NULL OR (source.revision,source.request_id) IS DISTINCT FROM (version.revision,version.request_id)
      OR actor IS NULL OR version.observed_by IS DISTINCT FROM actor OR NEW.position>=version.line_count THEN
      RAISE EXCEPTION 'Lookup lines require their new observation transaction' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_material(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_material() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid; issued numeric;
BEGIN
  IF session_user<>'sampleify_app' THEN RETURN NEW; END IF;
  PERFORM public.masters_lock_field_writer();
  IF NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR actor IS NULL OR NEW.updated_by IS DISTINCT FROM actor OR NEW.updated_at<>transaction_timestamp() OR NEW.save_request_id IS NULL THEN
    RAISE EXCEPTION 'Material writes require actual organization, editor, request and time' USING ERRCODE='23514';
  END IF;
  IF NEW.name<>trim(NEW.name) OR NEW.code<>trim(NEW.code) OR NEW.description<>trim(NEW.description) THEN
    RAISE EXCEPTION 'Material text must be trimmed' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NOT NEW.active OR NEW.revision<>1 OR NEW.created_at<>transaction_timestamp() OR NEW.created_by IS DISTINCT FROM actor
      OR NEW.initial_stock_id IS NOT NULL OR NEW.initial_stock_created_at IS NOT NULL OR NEW.initial_stock_created_by IS NOT NULL THEN
      RAISE EXCEPTION 'New materials require actual creation metadata and revision one' USING ERRCODE='23514';
    END IF;
  ELSE
    IF NOT OLD.active OR NEW.revision<>OLD.revision+1
      OR (NEW.organization_id,NEW.id,NEW.created_by,NEW.created_at,NEW.initial_stock_id,NEW.initial_stock_created_at,NEW.initial_stock_created_by)
        IS DISTINCT FROM (OLD.organization_id,OLD.id,OLD.created_by,OLD.created_at,OLD.initial_stock_id,OLD.initial_stock_created_at,OLD.initial_stock_created_by) THEN
      RAISE EXCEPTION 'Material writes preserve identity and advance the active revision' USING ERRCODE='23514';
    END IF;
    IF NOT NEW.active AND (NEW.name,NEW.code,NEW.description,NEW.category_id,NEW.measurement_unit_id,NEW.initial_quantity,NEW.minimum_quantity,NEW.maximum_quantity)
      IS DISTINCT FROM (OLD.name,OLD.code,OLD.description,OLD.category_id,OLD.measurement_unit_id,OLD.initial_quantity,OLD.minimum_quantity,OLD.maximum_quantity) THEN
      RAISE EXCEPTION 'Material retirement preserves its last values' USING ERRCODE='23514';
    END IF;
  END IF;
  IF (TG_OP='INSERT' OR NEW.category_id IS DISTINCT FROM OLD.category_id) AND NOT EXISTS(
    SELECT 1 FROM public.material_categories WHERE organization_id=NEW.organization_id AND id=NEW.category_id AND active) THEN
    RAISE EXCEPTION 'Select an available material category' USING ERRCODE='23514',CONSTRAINT='material_category_available';
  END IF;
  IF (TG_OP='INSERT' OR NEW.measurement_unit_id IS DISTINCT FROM OLD.measurement_unit_id) AND NOT EXISTS(
    SELECT 1 FROM public.measurement_units WHERE organization_id=NEW.organization_id AND id=NEW.measurement_unit_id AND active) THEN
    RAISE EXCEPTION 'Select an available unit of measure' USING ERRCODE='23514',CONSTRAINT='material_unit_available';
  END IF;
  SELECT coalesce(sum(quantity),0) INTO issued FROM public.material_transactions
    WHERE organization_id=NEW.organization_id AND material_id=NEW.id AND transaction_type IN ('out','out_damaged') AND batch_serial_number='Initial Stock';
  IF NEW.initial_quantity<issued THEN
    RAISE EXCEPTION 'Initial quantity cannot be below the quantity already issued from initial stock' USING ERRCODE='23514',CONSTRAINT='material_initial_below_issued';
  END IF;
  IF NEW.initial_quantity=0 THEN
    NEW.initial_stock_id:=NULL; NEW.initial_stock_created_at:=NULL; NEW.initial_stock_created_by:=NULL;
  ELSIF TG_OP='INSERT' OR OLD.initial_quantity=0 THEN
    NEW.initial_stock_id:=gen_random_uuid(); NEW.initial_stock_created_at:=transaction_timestamp(); NEW.initial_stock_created_by:=actor;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_material_category_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_material_category_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Material category history is immutable' USING ERRCODE='55000'; END IF;
  IF NEW.created_transaction_id<>pg_current_xact_id() OR NEW.saved_at<>transaction_timestamp()
    OR (session_user='sampleify_app' AND NEW.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid) THEN
    RAISE EXCEPTION 'Category history requires the actual editor and transaction' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_material_category_use(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_material_category_use() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF session_user='sampleify_app' AND OLD.active AND NOT NEW.active THEN
    PERFORM public.masters_lock_field_writer();
    IF EXISTS(SELECT 1 FROM public.materials WHERE organization_id=OLD.organization_id AND category_id=OLD.id AND active) THEN
      RAISE EXCEPTION 'This category is assigned to one or more materials' USING ERRCODE='23514',CONSTRAINT='material_category_in_use';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_material_transaction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_material_transaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE material public.materials%ROWTYPE; expirable boolean; available numeric; batch_available numeric; actual_supplier text; actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Material transactions are immutable' USING ERRCODE='55000'; END IF;
  IF session_user<>'sampleify_app' THEN RETURN NEW; END IF;
  PERFORM public.masters_lock_field_writer();
  IF NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid OR actor IS NULL
    OR NEW.created_by IS DISTINCT FROM actor OR NEW.created_at<>transaction_timestamp() OR NEW.created_transaction_id<>pg_current_xact_id() THEN
    RAISE EXCEPTION 'Material transactions require actual actor and transaction metadata' USING ERRCODE='23514';
  END IF;
  IF NEW.batch_serial_number<>trim(NEW.batch_serial_number) OR NEW.supplier<>trim(NEW.supplier) THEN
    RAISE EXCEPTION 'Material transaction text must be trimmed' USING ERRCODE='23514';
  END IF;
  SELECT * INTO material FROM public.materials WHERE organization_id=NEW.organization_id AND id=NEW.material_id FOR UPDATE;
  IF NOT FOUND OR NOT material.active THEN RAISE EXCEPTION 'Material was not found' USING ERRCODE='23514',CONSTRAINT='material_transaction_available'; END IF;
  IF NEW.id=material.initial_stock_id THEN RAISE EXCEPTION 'Transaction identifier belongs to opening stock' USING ERRCODE='23514',CONSTRAINT='material_transaction_opening_id'; END IF;
  SELECT category.expirable INTO expirable FROM public.material_categories category WHERE category.organization_id=material.organization_id AND category.id=material.category_id;
  IF NEW.category_expirable IS DISTINCT FROM expirable THEN RAISE EXCEPTION 'Material transactions retain the actual category rule' USING ERRCODE='23514'; END IF;
  IF NEW.measurement_unit_id IS DISTINCT FROM material.measurement_unit_id OR NOT EXISTS(SELECT 1 FROM public.measurement_units unit
    WHERE unit.organization_id=material.organization_id AND unit.id=NEW.measurement_unit_id AND unit.name=NEW.unit_name AND unit.symbol=NEW.unit_symbol) THEN
    RAISE EXCEPTION 'Material transactions retain their actual unit' USING ERRCODE='23514';
  END IF;
  IF NEW.transaction_type='in' THEN
    IF EXISTS(SELECT 1 FROM public.material_transactions WHERE organization_id=NEW.organization_id AND material_id=NEW.material_id
      AND transaction_type='in' AND lower(batch_serial_number)=lower(NEW.batch_serial_number))
      OR (material.initial_quantity>0 AND lower(NEW.batch_serial_number)='initial stock') THEN
      RAISE EXCEPTION 'This Batch/Serial No already exists. Enter a unique one.' USING ERRCODE='23514',CONSTRAINT='material_duplicate_in_batch';
    END IF;
    IF (expirable AND (NEW.expiry_date IS NULL OR NEW.expiry_date<(transaction_timestamp() AT TIME ZONE 'UTC')::date))
      OR (NOT expirable AND NEW.expiry_date IS NOT NULL) THEN
      RAISE EXCEPTION 'Select a valid nonpast expiry date for an expirable material' USING ERRCODE='23514',CONSTRAINT='material_expiry_required';
    END IF;
  ELSE
    SELECT material.initial_quantity+coalesce(sum(CASE WHEN transaction_type='in' THEN quantity ELSE -quantity END),0),
      CASE WHEN NEW.batch_serial_number='Initial Stock' THEN material.initial_quantity ELSE 0 END
        +coalesce(sum(CASE WHEN transaction_type='in' THEN quantity ELSE -quantity END) FILTER(WHERE batch_serial_number=NEW.batch_serial_number),0)
      INTO available,batch_available FROM public.material_transactions WHERE organization_id=NEW.organization_id AND material_id=NEW.material_id;
    IF NEW.quantity>available OR NEW.quantity>batch_available OR batch_available<=0 THEN
      RAISE EXCEPTION 'OUT quantity cannot exceed available material or selected batch quantity' USING ERRCODE='23514',CONSTRAINT='material_insufficient_stock';
    END IF;
    SELECT supplier INTO actual_supplier FROM (
      SELECT supplier,created_at,id FROM public.material_transactions WHERE organization_id=NEW.organization_id AND material_id=NEW.material_id
        AND transaction_type='in' AND batch_serial_number=NEW.batch_serial_number AND supplier<>''
      UNION ALL SELECT 'Initial Stock',material.initial_stock_created_at,material.initial_stock_id WHERE material.initial_quantity>0 AND NEW.batch_serial_number='Initial Stock'
    ) receipts ORDER BY created_at,id LIMIT 1;
    IF NEW.supplier IS DISTINCT FROM coalesce(actual_supplier,'') THEN RAISE EXCEPTION 'OUT supplier must match the selected batch' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_method_custom_field_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_method_custom_field_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE expected_count integer;
BEGIN
  IF session_user<>'sampleify_app' THEN RETURN NEW; END IF;
  PERFORM public.masters_lock_method_field_writer();
  IF NEW.organization_id IS DISTINCT FROM public.organization_module_scope() THEN
    RAISE EXCEPTION 'Method fields require the authenticated organization' USING ERRCODE='42501';
  END IF;
  IF TG_OP='UPDATE' AND EXISTS (
    SELECT 1 FROM public.method_versions WHERE organization_id=OLD.organization_id AND method_id=OLD.id AND revision=OLD.revision
  ) THEN PERFORM public.masters_assert_method_custom_fields(OLD.organization_id,OLD.id,OLD.revision); END IF;
  IF TG_OP='UPDATE' AND OLD.active AND NOT NEW.active AND NEW.custom_fields_provided THEN
    RAISE EXCEPTION 'Method retirement preserves Custom Fields' USING ERRCODE='23514',CONSTRAINT='method_custom_field_preserve';
  END IF;
  IF NEW.custom_fields_provided THEN
    SELECT count(*) INTO expected_count FROM public.custom_field_definitions
      WHERE organization_id=NEW.organization_id AND associated_with='method_of_analysis' AND active;
    IF expected_count<>NEW.custom_field_count THEN
      RAISE EXCEPTION 'Provide the current Method Custom Fields' USING ERRCODE='23514',CONSTRAINT='method_custom_field_definition_set';
    END IF;
  ELSE
    expected_count := CASE WHEN TG_OP='INSERT' THEN 0 ELSE OLD.custom_field_count END;
    IF NEW.custom_field_count<>expected_count OR (NEW.active AND EXISTS (
      SELECT 1 FROM public.custom_field_definitions WHERE organization_id=NEW.organization_id AND associated_with='method_of_analysis' AND active
    )) THEN RAISE EXCEPTION 'Method Custom Field omission requires no current definitions' USING ERRCODE='23514',CONSTRAINT='method_custom_field_preserve'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_method_custom_field_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_method_custom_field_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.method_versions; field public.method_version_custom_fields; definition public.custom_field_versions;
  related_count integer; previous_field_ids uuid[];
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Method Custom Field history is immutable' USING ERRCODE='55000'; END IF;
  SELECT * INTO version FROM public.method_versions WHERE organization_id=NEW.organization_id AND method_id=NEW.method_id AND revision=NEW.revision;
  IF version.method_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
    OR (session_user='sampleify_app' AND (version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
      OR NOT EXISTS (SELECT 1 FROM public.methods_of_analysis WHERE organization_id=NEW.organization_id AND id=NEW.method_id
        AND revision=NEW.revision AND save_request_id=version.request_id))) THEN
    RAISE EXCEPTION 'Method Custom Fields require their new version transaction' USING ERRCODE='23514',CONSTRAINT='method_custom_field_transaction';
  END IF;
  IF TG_TABLE_NAME='method_version_custom_fields' THEN
    IF NEW.position>=version.custom_field_count THEN RAISE EXCEPTION 'Method Custom Field position exceeds its saved count' USING ERRCODE='23514'; END IF;
    SELECT * INTO definition FROM public.custom_field_versions
      WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=NEW.field_revision;
    IF NOT FOUND OR definition.field_type<>NEW.field_type THEN
      RAISE EXCEPTION 'Method Custom Field type must match its definition' USING ERRCODE='23514',CONSTRAINT='method_custom_field_type';
    END IF;
    IF version.custom_fields_provided AND NOT EXISTS (
      SELECT 1 FROM public.custom_field_definitions WHERE organization_id=NEW.organization_id AND id=NEW.field_id
        AND revision=NEW.field_revision AND associated_with='method_of_analysis' AND active
    ) THEN RAISE EXCEPTION 'Select the current Method Custom Field revision' USING ERRCODE='23514',CONSTRAINT='method_custom_field_definition_set'; END IF;
  ELSE
    SELECT * INTO field FROM public.method_version_custom_fields
      WHERE organization_id=NEW.organization_id AND method_id=NEW.method_id AND revision=NEW.revision AND field_id=NEW.field_id;
    IF NOT FOUND OR NEW.position>=field.value_count THEN
      RAISE EXCEPTION 'Method Custom Field items require their declared field and count' USING ERRCODE='23514',CONSTRAINT='method_custom_value_complete';
    END IF;
    IF field.is_array AND NEW.raw_kind='text' AND public.masters_custom_field_trim(NEW.raw_text)='' THEN
      RAISE EXCEPTION 'Remove blank repeated Method Custom Field items' USING ERRCODE='23514';
    END IF;
    IF field.field_type='lookup' THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      IF NEW.interpretation_state='invalid' AND version.previous_revision>0 THEN
        SELECT array_agg(previous.field_id) INTO previous_field_ids
          FROM public.method_version_custom_fields previous JOIN public.custom_field_versions saved_definition
            ON saved_definition.organization_id=previous.organization_id AND saved_definition.field_id=previous.field_id
              AND saved_definition.revision=previous.field_revision
          WHERE previous.organization_id=NEW.organization_id AND previous.method_id=NEW.method_id
            AND previous.revision=version.previous_revision AND saved_definition.key=definition.key;
      END IF;
    ELSIF field.field_type='select' AND version.previous_revision>0 AND (
      NEW.interpretation_state='invalid' OR version.custom_fields_provided AND NEW.option_revision<>field.field_revision
    ) THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      -- Restrict prior items to the same saved key before checking their raw values.
      WITH key_definitions AS MATERIALIZED (
        SELECT field_id,revision FROM public.custom_field_versions WHERE organization_id=NEW.organization_id AND key=definition.key
      ) SELECT array_agg(previous_field.field_id) INTO previous_field_ids
        FROM key_definitions previous_definition JOIN LATERAL (
          SELECT field_id FROM public.method_version_custom_fields
            WHERE organization_id=NEW.organization_id AND method_id=NEW.method_id AND revision=version.previous_revision
              AND field_id=previous_definition.field_id AND field_revision=previous_definition.revision LIMIT 1
        ) previous_field ON true;
    ELSIF field.field_type='attachment' AND NEW.interpretation_state='valid' THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      IF version.previous_revision>0 THEN
        WITH key_definitions AS MATERIALIZED (
          SELECT field_id,revision FROM public.custom_field_versions WHERE organization_id=NEW.organization_id AND key=definition.key
        ) SELECT array_agg(previous_field.field_id) INTO previous_field_ids
          FROM key_definitions previous_definition JOIN LATERAL (
            SELECT field_id FROM public.method_version_custom_fields
              WHERE organization_id=NEW.organization_id AND method_id=NEW.method_id AND revision=version.previous_revision
                AND field_id=previous_definition.field_id AND field_revision=previous_definition.revision LIMIT 1
          ) previous_field ON true;
      END IF;
    END IF;
    related_count := num_nonnulls(NEW.parsed_number,NEW.parsed_boolean,NEW.parsed_date,NEW.parsed_timestamp,NEW.option_id,NEW.option_revision,NEW.user_id,NEW.attachment_id,NEW.lookup_source_id,NEW.lookup_revision,NEW.lookup_line_id);
    IF NEW.interpretation_state='valid' THEN
      CASE field.field_type
        WHEN 'number' THEN
          IF NEW.parsed_number IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A numeric field requires its typed numeric interpretation' USING ERRCODE='23514'; END IF;
        WHEN 'checkbox' THEN
          IF NEW.parsed_boolean IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A checkbox requires its typed boolean interpretation' USING ERRCODE='23514'; END IF;
        WHEN 'date' THEN
          IF NEW.parsed_date IS NULL OR NEW.parsed_timestamp IS NULL OR related_count<>2 THEN RAISE EXCEPTION 'A date requires its local date and parsed instant' USING ERRCODE='23514'; END IF;
        WHEN 'date_time' THEN
          IF NEW.parsed_timestamp IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A date-time field requires its parsed instant' USING ERRCODE='23514'; END IF;
        WHEN 'select' THEN
          IF NEW.option_id IS NULL OR NEW.option_revision IS NULL OR related_count<>2 OR NOT EXISTS (
            SELECT 1 FROM public.custom_field_version_options option WHERE option.organization_id=NEW.organization_id
              AND option.field_id=NEW.field_id AND option.revision=NEW.option_revision AND option.id=NEW.option_id
              AND option.key=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
          ) THEN RAISE EXCEPTION 'A selection requires its exact field option' USING ERRCODE='23514',CONSTRAINT='method_custom_value_option'; END IF;
          IF version.custom_fields_provided AND NEW.option_revision<>field.field_revision AND NOT EXISTS (
            SELECT 1 FROM public.method_version_custom_field_values previous
            WHERE previous.organization_id=NEW.organization_id AND previous.method_id=NEW.method_id AND previous.revision=version.previous_revision
              AND previous.field_id=ANY(previous_field_ids)
              AND previous.field_id=NEW.field_id AND previous.option_id=NEW.option_id AND previous.option_revision=NEW.option_revision
              AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
                IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
          ) THEN RAISE EXCEPTION 'An older selection must belong to the previous Method revision' USING ERRCODE='23514',CONSTRAINT='method_custom_value_option'; END IF;
        WHEN 'multi_user_select' THEN
          IF NEW.user_id IS NULL OR related_count<>1 OR NEW.raw_kind<>'text' OR lower(NEW.raw_text)<>NEW.user_id::text THEN
            RAISE EXCEPTION 'A user selection requires its member reference' USING ERRCODE='23514',CONSTRAINT='method_custom_value_user';
          END IF;
        WHEN 'attachment' THEN
          IF NEW.attachment_id IS NULL OR related_count<>1 OR NEW.raw_kind<>'text' OR lower(NEW.raw_text)<>NEW.attachment_id::text OR NOT EXISTS (
            SELECT 1 FROM public.custom_field_attachments attachment JOIN public.custom_field_versions uploaded_definition
              ON uploaded_definition.organization_id=attachment.organization_id AND uploaded_definition.field_id=attachment.field_id
                AND uploaded_definition.revision=attachment.field_revision
            WHERE attachment.organization_id=NEW.organization_id AND attachment.id=NEW.attachment_id
              AND uploaded_definition.associated_with IN ('product','parameter','method_of_analysis') AND uploaded_definition.field_type='attachment'
              AND (attachment.field_id=NEW.field_id OR uploaded_definition.key=definition.key OR EXISTS (
                SELECT 1 FROM public.method_version_custom_field_values previous
                WHERE previous.organization_id=NEW.organization_id AND previous.method_id=NEW.method_id
                  AND previous.revision=version.previous_revision AND previous.field_id=ANY(previous_field_ids)
                  AND previous.attachment_id=NEW.attachment_id
              ))
          ) THEN RAISE EXCEPTION 'An attachment must belong to its Custom Field' USING ERRCODE='23514',CONSTRAINT='method_custom_value_attachment'; END IF;
        WHEN 'lookup' THEN
          IF NEW.lookup_source_id IS NULL OR NEW.lookup_revision IS NULL OR NEW.lookup_line_id IS NULL OR related_count<>3
            OR definition.lookup_source_id IS DISTINCT FROM NEW.lookup_source_id
            OR NEW.lookup_line_id IS DISTINCT FROM (CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END)
            OR NOT EXISTS (
              SELECT 1 FROM public.custom_field_lookup_lines line
              WHERE line.organization_id=NEW.organization_id AND line.source_id=NEW.lookup_source_id
                AND line.revision=NEW.lookup_revision AND line.original_line_id=NEW.lookup_line_id
                AND (NOT version.custom_fields_provided OR EXISTS (
                  SELECT 1 FROM public.custom_field_lookup_sources source
                    WHERE source.organization_id=line.organization_id AND source.id=line.source_id AND source.revision=line.revision
                ))
            ) THEN RAISE EXCEPTION 'A lookup requires its exact observed line and current source for a new capture' USING ERRCODE='23514',CONSTRAINT='method_custom_value_lookup'; END IF;
        ELSE
          IF related_count<>0 THEN RAISE EXCEPTION 'Text fields cannot contain another field type interpretation' USING ERRCODE='23514'; END IF;
      END CASE;
    ELSIF NEW.interpretation_state='invalid' AND field.field_type='select' THEN
      -- Keep an unavailable saved value without claiming a foreign definition's option.
      IF (version.custom_fields_provided AND EXISTS (
        SELECT 1 FROM public.custom_field_version_options option WHERE option.organization_id=NEW.organization_id
          AND option.field_id=NEW.field_id AND option.revision=field.field_revision
          AND option.key=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
      )) OR NOT EXISTS (
        SELECT 1 FROM public.method_version_custom_field_values previous
          WHERE previous.organization_id=NEW.organization_id AND previous.method_id=NEW.method_id AND previous.revision=version.previous_revision
            AND previous.field_id=ANY(previous_field_ids)
            AND (previous.field_id<>NEW.field_id OR previous.option_id IS NULL)
            AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
              IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
      ) THEN RAISE EXCEPTION 'An unresolved selection requires the same previous saved-key value' USING ERRCODE='23514',CONSTRAINT='method_custom_value_option'; END IF;
    ELSIF NEW.interpretation_state='invalid' AND field.field_type='lookup' THEN
      -- Newly supplied captures use current choices; omitted fields preserve their exact frozen interpretation.
      IF (version.custom_fields_provided AND EXISTS (
        SELECT 1 FROM public.custom_field_lookup_lines line JOIN public.custom_field_lookup_sources source
          ON source.organization_id=line.organization_id AND source.id=line.source_id AND source.revision=line.revision
        WHERE line.organization_id=NEW.organization_id AND line.source_id=definition.lookup_source_id
          AND line.original_line_id=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
      )) OR NOT EXISTS (
        SELECT 1 FROM public.method_version_custom_field_values previous
          WHERE previous.organization_id=NEW.organization_id AND previous.method_id=NEW.method_id AND previous.revision=version.previous_revision
            AND previous.field_id=ANY(previous_field_ids)
            AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
              IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
      ) THEN RAISE EXCEPTION 'An unavailable lookup requires the same previous saved-key value' USING ERRCODE='23514',CONSTRAINT='method_custom_value_lookup'; END IF;
    ELSIF NEW.interpretation_state IN ('invalid','out_of_range') AND field.field_type NOT IN ('number','date','date_time') THEN
      RAISE EXCEPTION 'Only numeric and date fields retain invalid interpretations' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_method_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_method_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.method_versions;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Method history is immutable' USING ERRCODE='55000'; END IF;
  IF TG_TABLE_NAME='method_versions' THEN
    IF NEW.created_transaction_id<>pg_current_xact_id() OR NEW.saved_at<>transaction_timestamp()
      OR (session_user='sampleify_app' AND NEW.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid) THEN
      RAISE EXCEPTION 'Method history requires the actual editor and transaction' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO version FROM public.method_versions WHERE organization_id=NEW.organization_id AND method_id=NEW.method_id AND revision=NEW.revision;
    IF version.method_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
      OR (session_user='sampleify_app' AND version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid) THEN
      RAISE EXCEPTION 'Method user history requires its new version transaction' USING ERRCODE='23514';
    END IF;
    IF version.operation<>'retire' THEN
      PERFORM 1 FROM public.memberships member JOIN public.users person ON person.id=member.user_id
        WHERE member.organization_id=NEW.organization_id AND member.user_id=NEW.user_id AND member.active AND person.active
        FOR SHARE OF member,person;
      IF NOT FOUND THEN RAISE EXCEPTION 'Select active users in this organization' USING ERRCODE='23514',CONSTRAINT='method_active_user'; END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_parameter_custom_field_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_parameter_custom_field_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE expected_count integer; unique_field uuid;
BEGIN
  IF session_user<>'sampleify_app' THEN RETURN NEW; END IF;
  PERFORM public.masters_lock_field_writer();
  FOR unique_field IN SELECT id FROM public.custom_field_definitions
    WHERE organization_id=NEW.organization_id AND associated_with='parameter' AND active AND validate_uniqueness ORDER BY id LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('parameter-custom-field-unique:'||NEW.organization_id::text||':'||unique_field::text,0));
  END LOOP;
  IF TG_OP='UPDATE' AND EXISTS (
    SELECT 1 FROM public.test_parameter_versions WHERE organization_id=OLD.organization_id AND parameter_id=OLD.id AND revision=OLD.revision
  ) THEN PERFORM public.masters_assert_parameter_custom_fields(OLD.organization_id,OLD.id,OLD.revision); END IF;
  IF TG_OP='UPDATE' AND OLD.active AND NOT NEW.active AND NEW.custom_fields_provided THEN
    RAISE EXCEPTION 'Parameter retirement preserves Custom Fields' USING ERRCODE='23514',CONSTRAINT='parameter_custom_field_preserve';
  END IF;
  IF NEW.custom_fields_provided THEN
    SELECT count(*) INTO expected_count FROM public.custom_field_definitions
      WHERE organization_id=NEW.organization_id AND associated_with='parameter' AND active;
    IF expected_count<>NEW.custom_field_count THEN
      RAISE EXCEPTION 'Provide the current Parameter Custom Fields' USING ERRCODE='23514',CONSTRAINT='parameter_custom_field_definition_set';
    END IF;
  ELSE
    expected_count := CASE WHEN TG_OP='INSERT' THEN 0 ELSE OLD.custom_field_count END;
    IF NEW.custom_field_count<>expected_count OR (NEW.active AND EXISTS (
      SELECT 1 FROM public.custom_field_definitions WHERE organization_id=NEW.organization_id AND associated_with='parameter' AND active
    )) THEN RAISE EXCEPTION 'Parameter Custom Field omission requires no current definitions' USING ERRCODE='23514',CONSTRAINT='parameter_custom_field_preserve'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_parameter_custom_field_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_parameter_custom_field_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.test_parameter_versions; field public.parameter_version_custom_fields; definition public.custom_field_versions;
  related_count integer; previous_field_ids uuid[];
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Parameter Custom Field history is immutable' USING ERRCODE='55000'; END IF;
  SELECT * INTO version FROM public.test_parameter_versions WHERE organization_id=NEW.organization_id AND parameter_id=NEW.parameter_id AND revision=NEW.revision;
  IF version.parameter_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
    OR (session_user='sampleify_app' AND (version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
      OR NOT EXISTS (SELECT 1 FROM public.test_parameters WHERE organization_id=NEW.organization_id AND id=NEW.parameter_id
        AND revision=NEW.revision AND save_request_id=version.request_id))) THEN
    RAISE EXCEPTION 'Parameter Custom Fields require their new version transaction' USING ERRCODE='23514',CONSTRAINT='parameter_custom_field_transaction';
  END IF;
  IF TG_TABLE_NAME='parameter_version_custom_fields' THEN
    IF NEW.position>=version.custom_field_count THEN RAISE EXCEPTION 'Parameter Custom Field position exceeds its saved count' USING ERRCODE='23514'; END IF;
    SELECT * INTO definition FROM public.custom_field_versions
      WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=NEW.field_revision;
    IF NOT FOUND OR definition.field_type<>NEW.field_type THEN
      RAISE EXCEPTION 'Parameter Custom Field type must match its definition' USING ERRCODE='23514',CONSTRAINT='parameter_custom_field_type';
    END IF;
    IF version.custom_fields_provided AND NOT EXISTS (
      SELECT 1 FROM public.custom_field_definitions WHERE organization_id=NEW.organization_id AND id=NEW.field_id
        AND revision=NEW.field_revision AND associated_with='parameter' AND active
    ) THEN RAISE EXCEPTION 'Select the current Parameter Custom Field revision' USING ERRCODE='23514',CONSTRAINT='parameter_custom_field_definition_set'; END IF;
  ELSE
    SELECT * INTO field FROM public.parameter_version_custom_fields
      WHERE organization_id=NEW.organization_id AND parameter_id=NEW.parameter_id AND revision=NEW.revision AND field_id=NEW.field_id;
    IF NOT FOUND OR NEW.position>=field.value_count THEN
      RAISE EXCEPTION 'Parameter Custom Field items require their declared field and count' USING ERRCODE='23514',CONSTRAINT='parameter_custom_value_complete';
    END IF;
    IF field.is_array AND NEW.raw_kind='text' AND public.masters_custom_field_trim(NEW.raw_text)='' THEN
      RAISE EXCEPTION 'Remove blank repeated Parameter Custom Field items' USING ERRCODE='23514';
    END IF;
    IF field.field_type='lookup' THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      IF NEW.interpretation_state='invalid' AND version.previous_revision>0 THEN
        SELECT array_agg(previous.field_id) INTO previous_field_ids
          FROM public.parameter_version_custom_fields previous JOIN public.custom_field_versions saved_definition
            ON saved_definition.organization_id=previous.organization_id AND saved_definition.field_id=previous.field_id
              AND saved_definition.revision=previous.field_revision
          WHERE previous.organization_id=NEW.organization_id AND previous.parameter_id=NEW.parameter_id
            AND previous.revision=version.previous_revision AND saved_definition.key=definition.key;
      END IF;
    ELSIF field.field_type='select' AND version.previous_revision>0 AND (
      NEW.interpretation_state='invalid' OR version.custom_fields_provided AND NEW.option_revision<>field.field_revision
    ) THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      -- Restrict prior items to the same saved key before checking their raw values.
      WITH key_definitions AS MATERIALIZED (
        SELECT field_id,revision FROM public.custom_field_versions WHERE organization_id=NEW.organization_id AND key=definition.key
      ) SELECT array_agg(previous_field.field_id) INTO previous_field_ids
        FROM key_definitions previous_definition JOIN LATERAL (
          SELECT field_id FROM public.parameter_version_custom_fields
            WHERE organization_id=NEW.organization_id AND parameter_id=NEW.parameter_id AND revision=version.previous_revision
              AND field_id=previous_definition.field_id AND field_revision=previous_definition.revision LIMIT 1
        ) previous_field ON true;
    ELSIF field.field_type='attachment' AND NEW.interpretation_state='valid' THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      IF version.previous_revision>0 THEN
        WITH key_definitions AS MATERIALIZED (
          SELECT field_id,revision FROM public.custom_field_versions WHERE organization_id=NEW.organization_id AND key=definition.key
        ) SELECT array_agg(previous_field.field_id) INTO previous_field_ids
          FROM key_definitions previous_definition JOIN LATERAL (
            SELECT field_id FROM public.parameter_version_custom_fields
              WHERE organization_id=NEW.organization_id AND parameter_id=NEW.parameter_id AND revision=version.previous_revision
                AND field_id=previous_definition.field_id AND field_revision=previous_definition.revision LIMIT 1
          ) previous_field ON true;
      END IF;
    END IF;
    related_count := num_nonnulls(NEW.parsed_number,NEW.parsed_boolean,NEW.parsed_date,NEW.parsed_timestamp,NEW.option_id,NEW.option_revision,NEW.user_id,NEW.attachment_id,NEW.lookup_source_id,NEW.lookup_revision,NEW.lookup_line_id);
    IF NEW.interpretation_state='valid' THEN
      CASE field.field_type
        WHEN 'number' THEN
          IF NEW.parsed_number IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A numeric field requires its typed numeric interpretation' USING ERRCODE='23514'; END IF;
        WHEN 'checkbox' THEN
          IF NEW.parsed_boolean IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A checkbox requires its typed boolean interpretation' USING ERRCODE='23514'; END IF;
        WHEN 'date' THEN
          IF NEW.parsed_date IS NULL OR NEW.parsed_timestamp IS NULL OR related_count<>2 THEN RAISE EXCEPTION 'A date requires its local date and parsed instant' USING ERRCODE='23514'; END IF;
        WHEN 'date_time' THEN
          IF NEW.parsed_timestamp IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A date-time field requires its parsed instant' USING ERRCODE='23514'; END IF;
        WHEN 'select' THEN
          IF NEW.option_id IS NULL OR NEW.option_revision IS NULL OR related_count<>2 OR NOT EXISTS (
            SELECT 1 FROM public.custom_field_version_options option WHERE option.organization_id=NEW.organization_id
              AND option.field_id=NEW.field_id AND option.revision=NEW.option_revision AND option.id=NEW.option_id
              AND option.key=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
          ) THEN RAISE EXCEPTION 'A selection requires its exact field option' USING ERRCODE='23514',CONSTRAINT='parameter_custom_value_option'; END IF;
          IF version.custom_fields_provided AND NEW.option_revision<>field.field_revision AND NOT EXISTS (
            SELECT 1 FROM public.parameter_version_custom_field_values previous
            WHERE previous.organization_id=NEW.organization_id AND previous.parameter_id=NEW.parameter_id AND previous.revision=version.previous_revision
              AND previous.field_id=ANY(previous_field_ids)
              AND previous.field_id=NEW.field_id AND previous.option_id=NEW.option_id AND previous.option_revision=NEW.option_revision
              AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
                IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
          ) THEN RAISE EXCEPTION 'An older selection must belong to the previous Parameter revision' USING ERRCODE='23514',CONSTRAINT='parameter_custom_value_option'; END IF;
        WHEN 'multi_user_select' THEN
          IF NEW.user_id IS NULL OR related_count<>1 OR NEW.raw_kind<>'text' OR lower(NEW.raw_text)<>NEW.user_id::text THEN
            RAISE EXCEPTION 'A user selection requires its member reference' USING ERRCODE='23514',CONSTRAINT='parameter_custom_value_user';
          END IF;
        WHEN 'attachment' THEN
          IF NEW.attachment_id IS NULL OR related_count<>1 OR NEW.raw_kind<>'text' OR lower(NEW.raw_text)<>NEW.attachment_id::text OR NOT EXISTS (
            SELECT 1 FROM public.custom_field_attachments attachment JOIN public.custom_field_versions uploaded_definition
              ON uploaded_definition.organization_id=attachment.organization_id AND uploaded_definition.field_id=attachment.field_id
                AND uploaded_definition.revision=attachment.field_revision
            WHERE attachment.organization_id=NEW.organization_id AND attachment.id=NEW.attachment_id
              AND uploaded_definition.associated_with IN ('product','parameter','method_of_analysis') AND uploaded_definition.field_type='attachment'
              AND (attachment.field_id=NEW.field_id OR uploaded_definition.key=definition.key OR EXISTS (
                SELECT 1 FROM public.parameter_version_custom_field_values previous
                WHERE previous.organization_id=NEW.organization_id AND previous.parameter_id=NEW.parameter_id
                  AND previous.revision=version.previous_revision AND previous.field_id=ANY(previous_field_ids)
                  AND previous.attachment_id=NEW.attachment_id
              ))
          ) THEN RAISE EXCEPTION 'An attachment must belong to its Custom Field' USING ERRCODE='23514',CONSTRAINT='parameter_custom_value_attachment'; END IF;
        WHEN 'lookup' THEN
          IF NEW.lookup_source_id IS NULL OR NEW.lookup_revision IS NULL OR NEW.lookup_line_id IS NULL OR related_count<>3
            OR definition.lookup_source_id IS DISTINCT FROM NEW.lookup_source_id
            OR NEW.lookup_line_id IS DISTINCT FROM (CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END)
            OR NOT EXISTS (
              SELECT 1 FROM public.custom_field_lookup_lines line
              WHERE line.organization_id=NEW.organization_id AND line.source_id=NEW.lookup_source_id
                AND line.revision=NEW.lookup_revision AND line.original_line_id=NEW.lookup_line_id
                AND (NOT version.custom_fields_provided OR EXISTS (
                  SELECT 1 FROM public.custom_field_lookup_sources source
                    WHERE source.organization_id=line.organization_id AND source.id=line.source_id AND source.revision=line.revision
                ))
            ) THEN RAISE EXCEPTION 'A lookup requires its exact observed line and current source for a new capture' USING ERRCODE='23514',CONSTRAINT='parameter_custom_value_lookup'; END IF;
        ELSE
          IF related_count<>0 THEN RAISE EXCEPTION 'Text fields cannot contain another field type interpretation' USING ERRCODE='23514'; END IF;
      END CASE;
    ELSIF NEW.interpretation_state='invalid' AND field.field_type='select' THEN
      -- Keep an unavailable saved value without claiming a foreign definition's option.
      IF (version.custom_fields_provided AND EXISTS (
        SELECT 1 FROM public.custom_field_version_options option WHERE option.organization_id=NEW.organization_id
          AND option.field_id=NEW.field_id AND option.revision=field.field_revision
          AND option.key=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
      )) OR NOT EXISTS (
        SELECT 1 FROM public.parameter_version_custom_field_values previous
          WHERE previous.organization_id=NEW.organization_id AND previous.parameter_id=NEW.parameter_id AND previous.revision=version.previous_revision
            AND previous.field_id=ANY(previous_field_ids)
            AND (previous.field_id<>NEW.field_id OR previous.option_id IS NULL)
            AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
              IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
      ) THEN RAISE EXCEPTION 'An unresolved selection requires the same previous saved-key value' USING ERRCODE='23514',CONSTRAINT='parameter_custom_value_option'; END IF;
    ELSIF NEW.interpretation_state='invalid' AND field.field_type='lookup' THEN
      -- Newly supplied captures use current choices; omitted fields preserve their exact frozen interpretation.
      IF (version.custom_fields_provided AND EXISTS (
        SELECT 1 FROM public.custom_field_lookup_lines line JOIN public.custom_field_lookup_sources source
          ON source.organization_id=line.organization_id AND source.id=line.source_id AND source.revision=line.revision
        WHERE line.organization_id=NEW.organization_id AND line.source_id=definition.lookup_source_id
          AND line.original_line_id=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
      )) OR NOT EXISTS (
        SELECT 1 FROM public.parameter_version_custom_field_values previous
          WHERE previous.organization_id=NEW.organization_id AND previous.parameter_id=NEW.parameter_id AND previous.revision=version.previous_revision
            AND previous.field_id=ANY(previous_field_ids)
            AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
              IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
      ) THEN RAISE EXCEPTION 'An unavailable lookup requires the same previous saved-key value' USING ERRCODE='23514',CONSTRAINT='parameter_custom_value_lookup'; END IF;
    ELSIF NEW.interpretation_state IN ('invalid','out_of_range') AND field.field_type NOT IN ('number','date','date_time') THEN
      RAISE EXCEPTION 'Only numeric and date fields retain invalid interpretations' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_parameter_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_parameter_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.test_parameter_versions;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Parameter history is immutable' USING ERRCODE='55000'; END IF;
  IF TG_TABLE_NAME='test_parameter_versions' THEN
    IF NEW.created_transaction_id<>pg_current_xact_id() OR NEW.saved_at<>transaction_timestamp()
      OR (session_user='sampleify_app' AND NEW.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid) THEN
      RAISE EXCEPTION 'Parameter history requires the actual editor and transaction' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO version FROM public.test_parameter_versions WHERE organization_id=NEW.organization_id AND parameter_id=NEW.parameter_id AND revision=NEW.revision;
    IF version.parameter_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
      OR (session_user='sampleify_app' AND version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid) THEN
      RAISE EXCEPTION 'Parameter child history requires its new version transaction' USING ERRCODE='23514';
    END IF;
    IF TG_TABLE_NAME='parameter_uncertainty_cells' THEN
      IF EXISTS (SELECT 1 FROM public.parameter_uncertainty_columns
        WHERE organization_id=NEW.organization_id AND parameter_id=NEW.parameter_id AND revision=NEW.revision AND id=NEW.column_id AND position=0) THEN
        RAISE EXCEPTION 'Uncertainty serial numbers are derived from row order' USING ERRCODE='23514';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_product_custom_field_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_product_custom_field_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE expected_count integer; unique_field uuid;
BEGIN
  IF session_user<>'sampleify_app' THEN RETURN NEW; END IF;
  PERFORM public.masters_lock_field_writer();
  FOR unique_field IN SELECT id FROM public.custom_field_definitions
    WHERE organization_id=NEW.organization_id AND associated_with='product' AND active AND validate_uniqueness ORDER BY id LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('product-custom-field-unique:'||NEW.organization_id::text||':'||unique_field::text,0));
  END LOOP;
  IF TG_OP='UPDATE' AND EXISTS (
    SELECT 1 FROM public.product_versions WHERE organization_id=OLD.organization_id AND product_id=OLD.id AND revision=OLD.revision
  ) THEN PERFORM public.masters_assert_product_custom_fields(OLD.organization_id,OLD.id,OLD.revision); END IF;
  IF NOT NEW.active AND NEW.custom_fields_provided THEN
    RAISE EXCEPTION 'Product retirement preserves Custom Fields' USING ERRCODE='23514',CONSTRAINT='product_custom_field_preserve';
  END IF;
  IF NEW.custom_fields_provided THEN
    SELECT count(*) INTO expected_count FROM public.custom_field_definitions
      WHERE organization_id=NEW.organization_id AND associated_with='product' AND active;
    IF expected_count<>NEW.custom_field_count THEN
      RAISE EXCEPTION 'Provide the current Product Custom Fields' USING ERRCODE='23514',CONSTRAINT='product_custom_field_definition_set';
    END IF;
  ELSE
    expected_count := CASE WHEN TG_OP='INSERT' THEN 0 ELSE OLD.custom_field_count END;
    IF NEW.custom_field_count<>expected_count OR (NEW.active AND EXISTS (
      SELECT 1 FROM public.custom_field_definitions WHERE organization_id=NEW.organization_id AND associated_with='product' AND active
    )) THEN RAISE EXCEPTION 'Product Custom Field omission requires no current definitions' USING ERRCODE='23514',CONSTRAINT='product_custom_field_preserve'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_product_custom_field_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_product_custom_field_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.product_versions; field public.product_version_custom_fields; definition public.custom_field_versions;
  related_count integer; previous_field_ids uuid[];
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Product Custom Field history is immutable' USING ERRCODE='55000'; END IF;
  SELECT * INTO version FROM public.product_versions WHERE organization_id=NEW.organization_id AND product_id=NEW.product_id AND revision=NEW.revision;
  IF version.product_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
    OR (session_user='sampleify_app' AND (version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
      OR NOT EXISTS (SELECT 1 FROM public.products WHERE organization_id=NEW.organization_id AND id=NEW.product_id
        AND revision=NEW.revision AND save_request_id=version.request_id))) THEN
    RAISE EXCEPTION 'Product Custom Fields require their new version transaction' USING ERRCODE='23514',CONSTRAINT='product_custom_field_transaction';
  END IF;
  IF TG_TABLE_NAME='product_version_custom_fields' THEN
    IF NEW.position>=version.custom_field_count THEN RAISE EXCEPTION 'Product Custom Field position exceeds its saved count' USING ERRCODE='23514'; END IF;
    SELECT * INTO definition FROM public.custom_field_versions
      WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=NEW.field_revision;
    IF NOT FOUND OR definition.field_type<>NEW.field_type THEN
      RAISE EXCEPTION 'Product Custom Field type must match its definition' USING ERRCODE='23514',CONSTRAINT='product_custom_field_type';
    END IF;
    IF version.custom_fields_provided AND NOT EXISTS (
      SELECT 1 FROM public.custom_field_definitions WHERE organization_id=NEW.organization_id AND id=NEW.field_id
        AND revision=NEW.field_revision AND associated_with='product' AND active
    ) THEN RAISE EXCEPTION 'Select the current Product Custom Field revision' USING ERRCODE='23514',CONSTRAINT='product_custom_field_definition_set'; END IF;
  ELSE
    SELECT * INTO field FROM public.product_version_custom_fields
      WHERE organization_id=NEW.organization_id AND product_id=NEW.product_id AND revision=NEW.revision AND field_id=NEW.field_id;
    IF NOT FOUND OR NEW.position>=field.value_count THEN
      RAISE EXCEPTION 'Product Custom Field items require their declared field and count' USING ERRCODE='23514',CONSTRAINT='product_custom_value_complete';
    END IF;
    IF field.is_array AND NEW.raw_kind='text' AND public.masters_custom_field_trim(NEW.raw_text)='' THEN
      RAISE EXCEPTION 'Remove blank repeated Product Custom Field items' USING ERRCODE='23514';
    END IF;
    IF field.field_type='lookup' THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      IF NEW.interpretation_state='invalid' AND version.previous_revision>0 THEN
        SELECT array_agg(previous.field_id) INTO previous_field_ids
          FROM public.product_version_custom_fields previous JOIN public.custom_field_versions saved_definition
            ON saved_definition.organization_id=previous.organization_id AND saved_definition.field_id=previous.field_id
              AND saved_definition.revision=previous.field_revision
          WHERE previous.organization_id=NEW.organization_id AND previous.product_id=NEW.product_id
            AND previous.revision=version.previous_revision AND saved_definition.key=definition.key;
      END IF;
    ELSIF field.field_type='select' AND version.previous_revision>0 AND (
      NEW.interpretation_state='invalid' OR version.custom_fields_provided AND NEW.option_revision<>field.field_revision
    ) THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      -- Restrict prior items to the same saved key before checking their raw values.
      WITH key_definitions AS MATERIALIZED (
        SELECT field_id,revision FROM public.custom_field_versions WHERE organization_id=NEW.organization_id AND key=definition.key
      ) SELECT array_agg(previous_field.field_id) INTO previous_field_ids
        FROM key_definitions previous_definition JOIN LATERAL (
          SELECT field_id FROM public.product_version_custom_fields
            WHERE organization_id=NEW.organization_id AND product_id=NEW.product_id AND revision=version.previous_revision
              AND field_id=previous_definition.field_id AND field_revision=previous_definition.revision LIMIT 1
        ) previous_field ON true;
    ELSIF field.field_type='attachment' AND NEW.interpretation_state='valid' THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      IF version.previous_revision>0 THEN
        WITH key_definitions AS MATERIALIZED (
          SELECT field_id,revision FROM public.custom_field_versions WHERE organization_id=NEW.organization_id AND key=definition.key
        ) SELECT array_agg(previous_field.field_id) INTO previous_field_ids
          FROM key_definitions previous_definition JOIN LATERAL (
            SELECT field_id FROM public.product_version_custom_fields
              WHERE organization_id=NEW.organization_id AND product_id=NEW.product_id AND revision=version.previous_revision
                AND field_id=previous_definition.field_id AND field_revision=previous_definition.revision LIMIT 1
          ) previous_field ON true;
      END IF;
    END IF;
    related_count := num_nonnulls(NEW.parsed_number,NEW.parsed_boolean,NEW.parsed_date,NEW.parsed_timestamp,NEW.option_id,NEW.option_revision,NEW.user_id,NEW.attachment_id,NEW.lookup_source_id,NEW.lookup_revision,NEW.lookup_line_id);
    IF NEW.interpretation_state='valid' THEN
      CASE field.field_type
        WHEN 'number' THEN
          IF NEW.parsed_number IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A numeric field requires its typed numeric interpretation' USING ERRCODE='23514'; END IF;
        WHEN 'checkbox' THEN
          IF NEW.parsed_boolean IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A checkbox requires its typed boolean interpretation' USING ERRCODE='23514'; END IF;
        WHEN 'date' THEN
          IF NEW.parsed_date IS NULL OR NEW.parsed_timestamp IS NULL OR related_count<>2 THEN RAISE EXCEPTION 'A date requires its local date and parsed instant' USING ERRCODE='23514'; END IF;
        WHEN 'date_time' THEN
          IF NEW.parsed_timestamp IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A date-time field requires its parsed instant' USING ERRCODE='23514'; END IF;
        WHEN 'select' THEN
          IF NEW.option_id IS NULL OR NEW.option_revision IS NULL OR related_count<>2 OR NOT EXISTS (
            SELECT 1 FROM public.custom_field_version_options option WHERE option.organization_id=NEW.organization_id
              AND option.field_id=NEW.field_id AND option.revision=NEW.option_revision AND option.id=NEW.option_id
              AND option.key=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
          ) THEN RAISE EXCEPTION 'A selection requires its exact field option' USING ERRCODE='23514',CONSTRAINT='product_custom_value_option'; END IF;
          IF version.custom_fields_provided AND NEW.option_revision<>field.field_revision AND NOT EXISTS (
            SELECT 1 FROM public.product_version_custom_field_values previous
            WHERE previous.organization_id=NEW.organization_id AND previous.product_id=NEW.product_id AND previous.revision=version.previous_revision
              AND previous.field_id=ANY(previous_field_ids)
              AND previous.field_id=NEW.field_id AND previous.option_id=NEW.option_id AND previous.option_revision=NEW.option_revision
              AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
                IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
          ) THEN RAISE EXCEPTION 'An older selection must belong to the previous Product revision' USING ERRCODE='23514',CONSTRAINT='product_custom_value_option'; END IF;
        WHEN 'multi_user_select' THEN
          IF NEW.user_id IS NULL OR related_count<>1 OR NEW.raw_kind<>'text' OR lower(NEW.raw_text)<>NEW.user_id::text THEN
            RAISE EXCEPTION 'A user selection requires its member reference' USING ERRCODE='23514',CONSTRAINT='product_custom_value_user';
          END IF;
        WHEN 'attachment' THEN
          IF NEW.attachment_id IS NULL OR related_count<>1 OR NEW.raw_kind<>'text' OR lower(NEW.raw_text)<>NEW.attachment_id::text OR NOT EXISTS (
            SELECT 1 FROM public.custom_field_attachments attachment JOIN public.custom_field_versions uploaded_definition
              ON uploaded_definition.organization_id=attachment.organization_id AND uploaded_definition.field_id=attachment.field_id
                AND uploaded_definition.revision=attachment.field_revision
            WHERE attachment.organization_id=NEW.organization_id AND attachment.id=NEW.attachment_id
              AND uploaded_definition.associated_with IN ('product','parameter','method_of_analysis') AND uploaded_definition.field_type='attachment'
              AND (attachment.field_id=NEW.field_id OR uploaded_definition.key=definition.key OR EXISTS (
                SELECT 1 FROM public.product_version_custom_field_values previous
                WHERE previous.organization_id=NEW.organization_id AND previous.product_id=NEW.product_id
                  AND previous.revision=version.previous_revision AND previous.field_id=ANY(previous_field_ids)
                  AND previous.attachment_id=NEW.attachment_id
              ))
          ) THEN RAISE EXCEPTION 'An attachment must belong to its Custom Field' USING ERRCODE='23514',CONSTRAINT='product_custom_value_attachment'; END IF;
        WHEN 'lookup' THEN
          IF NEW.lookup_source_id IS NULL OR NEW.lookup_revision IS NULL OR NEW.lookup_line_id IS NULL OR related_count<>3
            OR definition.lookup_source_id IS DISTINCT FROM NEW.lookup_source_id
            OR NEW.lookup_line_id IS DISTINCT FROM (CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END)
            OR NOT EXISTS (
              SELECT 1 FROM public.custom_field_lookup_lines line
              WHERE line.organization_id=NEW.organization_id AND line.source_id=NEW.lookup_source_id
                AND line.revision=NEW.lookup_revision AND line.original_line_id=NEW.lookup_line_id
                AND (NOT version.custom_fields_provided OR EXISTS (
                  SELECT 1 FROM public.custom_field_lookup_sources source
                    WHERE source.organization_id=line.organization_id AND source.id=line.source_id AND source.revision=line.revision
                ))
            ) THEN RAISE EXCEPTION 'A lookup requires its exact observed line and current source for a new capture' USING ERRCODE='23514',CONSTRAINT='product_custom_value_lookup'; END IF;
        ELSE
          IF related_count<>0 THEN RAISE EXCEPTION 'Text fields cannot contain another field type interpretation' USING ERRCODE='23514'; END IF;
      END CASE;
    ELSIF NEW.interpretation_state='invalid' AND field.field_type='select' THEN
      -- Keep an unavailable saved value without claiming a foreign definition's option.
      IF (version.custom_fields_provided AND EXISTS (
        SELECT 1 FROM public.custom_field_version_options option WHERE option.organization_id=NEW.organization_id
          AND option.field_id=NEW.field_id AND option.revision=field.field_revision
          AND option.key=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
      )) OR NOT EXISTS (
        SELECT 1 FROM public.product_version_custom_field_values previous
          WHERE previous.organization_id=NEW.organization_id AND previous.product_id=NEW.product_id AND previous.revision=version.previous_revision
            AND previous.field_id=ANY(previous_field_ids)
            AND (previous.field_id<>NEW.field_id OR previous.option_id IS NULL)
            AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
              IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
      ) THEN RAISE EXCEPTION 'An unresolved selection requires the same previous saved-key value' USING ERRCODE='23514',CONSTRAINT='product_custom_value_option'; END IF;
    ELSIF NEW.interpretation_state='invalid' AND field.field_type='lookup' THEN
      -- Newly supplied captures use current choices; omitted fields preserve their exact frozen interpretation.
      IF (version.custom_fields_provided AND EXISTS (
        SELECT 1 FROM public.custom_field_lookup_lines line JOIN public.custom_field_lookup_sources source
          ON source.organization_id=line.organization_id AND source.id=line.source_id AND source.revision=line.revision
        WHERE line.organization_id=NEW.organization_id AND line.source_id=definition.lookup_source_id
          AND line.original_line_id=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
      )) OR NOT EXISTS (
        SELECT 1 FROM public.product_version_custom_field_values previous
          WHERE previous.organization_id=NEW.organization_id AND previous.product_id=NEW.product_id AND previous.revision=version.previous_revision
            AND previous.field_id=ANY(previous_field_ids)
            AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
              IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
      ) THEN RAISE EXCEPTION 'An unavailable lookup requires the same previous saved-key value' USING ERRCODE='23514',CONSTRAINT='product_custom_value_lookup'; END IF;
    ELSIF NEW.interpretation_state IN ('invalid','out_of_range') AND field.field_type NOT IN ('number','date','date_time') THEN
      RAISE EXCEPTION 'Only numeric and date fields retain invalid interpretations' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_product_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_product_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.product_versions;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Product history is immutable' USING ERRCODE='55000'; END IF;
  IF TG_TABLE_NAME='product_versions' THEN
    IF NEW.created_transaction_id<>pg_current_xact_id() OR NEW.saved_at<>transaction_timestamp()
      OR (session_user='sampleify_app' AND NEW.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid) THEN
      RAISE EXCEPTION 'Product history requires the actual editor and transaction' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO version FROM public.product_versions WHERE organization_id=NEW.organization_id AND product_id=NEW.product_id AND revision=NEW.revision;
    IF version.product_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
      OR (session_user='sampleify_app' AND (version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
        OR NOT EXISTS (SELECT 1 FROM public.products WHERE organization_id=NEW.organization_id AND id=NEW.product_id
          AND revision=NEW.revision AND save_request_id=version.request_id))) THEN
      RAISE EXCEPTION 'Product links require their new version transaction' USING ERRCODE='23514';
    END IF;
    IF TG_TABLE_NAME='product_version_tags' THEN
      IF NEW.position>=version.tag_count THEN RAISE EXCEPTION 'Product tag position exceeds its saved count' USING ERRCODE='23514'; END IF;
      IF version.operation='retire' THEN
        IF NOT EXISTS (SELECT 1 FROM public.product_tags WHERE organization_id=NEW.organization_id AND product_id=NEW.product_id AND tag_id=NEW.tag_id) THEN
          RAISE EXCEPTION 'Product retirement preserves its tags' USING ERRCODE='23514';
        END IF;
      ELSE
        PERFORM 1 FROM public.tags WHERE organization_id=NEW.organization_id AND id=NEW.tag_id AND active FOR SHARE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Select active tags in this organization' USING ERRCODE='23514',CONSTRAINT='product_active_tag'; END IF;
      END IF;
    ELSIF TG_TABLE_NAME='product_version_sample_categories' THEN
      IF version.operation='retire' THEN
        IF NOT EXISTS (SELECT 1 FROM public.product_sample_categories WHERE organization_id=NEW.organization_id AND product_id=NEW.product_id AND sample_category_id=NEW.sample_category_id) THEN
          RAISE EXCEPTION 'Product retirement preserves its sample categories' USING ERRCODE='23514';
        END IF;
      ELSE
        PERFORM 1 FROM public.sample_categories WHERE organization_id=NEW.organization_id AND id=NEW.sample_category_id AND active FOR SHARE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Select active Sample Categories in this organization' USING ERRCODE='23514',CONSTRAINT='product_active_sample_category'; END IF;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_guard_sample_category_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_guard_sample_category_history() RETURNS trigger
