--
-- Name: masters_lock_field_writer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_lock_field_writer() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('custom-field-definitions:'||org::text,0));
  PERFORM 1 FROM public.users WHERE id=actor FOR NO KEY UPDATE;
  PERFORM 1 FROM public.organizations WHERE id=org FOR NO KEY UPDATE;
  PERFORM 1 FROM public.memberships WHERE organization_id=org AND user_id=actor FOR SHARE;
  PERFORM 1 FROM public.sessions WHERE id=nullif(current_setting('app.session_id',true),'')::uuid FOR SHARE;
  IF NOT EXISTS (
    SELECT 1 FROM public.sessions session
    JOIN public.users person ON person.id=session.user_id AND person.active AND NOT person.must_change_password
    JOIN public.credentials credential ON credential.user_id=person.id AND credential.revision=session.credential_revision
    JOIN public.memberships membership ON membership.organization_id=session.organization_id AND membership.user_id=person.id AND membership.active
    JOIN public.organizations organization ON organization.id=session.organization_id AND organization.active
    WHERE session.id=nullif(current_setting('app.session_id',true),'')::uuid AND session.user_id=actor AND session.organization_id=org
      AND session.revoked_at IS NULL AND session.expires_at>clock_timestamp()
  ) OR NOT public.app_has_permission('masters.manage') THEN
    RAISE EXCEPTION 'Active master management session required' USING ERRCODE='42501',CONSTRAINT='master_field_session_required';
  END IF;
  RETURN actor;
END $$;


--
-- Name: masters_lock_lookup_observer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_lock_lookup_observer() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('custom-field-definitions:'||org::text,0));
  PERFORM 1 FROM public.users WHERE id=actor FOR UPDATE;
  PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
  PERFORM 1 FROM public.memberships WHERE organization_id=org AND user_id=actor FOR SHARE;
  PERFORM 1 FROM public.sessions WHERE id=nullif(current_setting('app.session_id',true),'')::uuid FOR SHARE;
  IF NOT EXISTS (
    SELECT 1 FROM public.sessions session
    JOIN public.users person ON person.id=session.user_id AND person.active AND NOT person.must_change_password
    JOIN public.credentials credential ON credential.user_id=person.id AND credential.revision=session.credential_revision
    JOIN public.memberships membership ON membership.organization_id=session.organization_id AND membership.user_id=person.id AND membership.active
    JOIN public.organizations organization ON organization.id=session.organization_id AND organization.active
    WHERE session.id=nullif(current_setting('app.session_id',true),'')::uuid AND session.user_id=actor AND session.organization_id=org
      AND session.revoked_at IS NULL AND session.expires_at>clock_timestamp()
  ) OR NOT public.app_has_permission('masters.manage') THEN
    RAISE EXCEPTION 'Active lookup observation management session required' USING ERRCODE='42501',CONSTRAINT='custom_lookup_session_required';
  END IF;
  RETURN actor;
END $$;


--
-- Name: masters_lock_method_field_writer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_lock_method_field_writer() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF current_setting('transaction_isolation') NOT IN ('read committed','read uncommitted') THEN
    RAISE EXCEPTION 'Method field writes require a current snapshot' USING ERRCODE='25001',CONSTRAINT='method_field_write_isolation';
  END IF;
  RETURN public.masters_lock_field_writer();
END $$;


--
-- Name: masters_method_scheme_context(boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_method_scheme_context(include_methods boolean, include_samples boolean) RETURNS TABLE("currentYearDigits" text, "nextYearDigits" text, separator text, "currentMonthFormat" text, "nonNablStartNumber" text, "methodCount" double precision, "sampleCount" double precision)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=public.organization_module_scope();
BEGIN
  IF org IS NULL OR NOT public.app_has_permission('masters.manage') THEN
    RAISE EXCEPTION 'Method scheme generation requires permission' USING ERRCODE='42501';
  END IF;
  RETURN QUERY SELECT settings.scheme_current_year_digits,settings.scheme_next_year_digits,settings.scheme_separator,
    settings.scheme_month_format,settings.scheme_non_nabl_start_number,
    CASE WHEN include_methods THEN (SELECT count(*)::double precision FROM public.methods_of_analysis method WHERE method.organization_id=org AND method.active) ELSE 0::double precision END,
    CASE WHEN include_samples THEN (SELECT count(*)::double precision FROM public.samples sample WHERE sample.organization_id=org) ELSE 0::double precision END
  FROM public.organizations organization LEFT JOIN public.organization_laboratory_settings settings ON settings.organization_id=organization.id
  WHERE organization.id=org;
END $$;


