--
-- Name: masters_product_custom_field_unique_text(boolean, text, text, double precision, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_product_custom_field_unique_text(is_array boolean, raw_kind text, raw_text text, raw_number double precision, raw_boolean boolean, raw_number_text text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    SET extra_float_digits TO '3'
    AS $$
DECLARE normalized text;
BEGIN
  IF NOT is_array AND ((raw_kind='boolean' AND NOT raw_boolean) OR (raw_kind='number' AND raw_number=-1)
    OR (raw_kind='text' AND raw_text IN ('','-1'))) THEN RETURN NULL; END IF;
  CASE raw_kind
    WHEN 'text' THEN normalized := public.masters_custom_field_trim(raw_text);
    WHEN 'boolean' THEN normalized := raw_boolean::text;
    WHEN 'number' THEN normalized := raw_number_text;
    ELSE RAISE EXCEPTION 'Unsupported raw Custom Field type' USING ERRCODE='23514';
  END CASE;
  IF normalized='' OR (is_array AND normalized='-1') THEN RETURN NULL; END IF;
  RETURN normalized;
END $$;


--
-- Name: masters_product_scheme_context(boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_product_scheme_context(include_products boolean, include_samples boolean) RETURNS TABLE("currentYearDigits" text, "nextYearDigits" text, separator text, "currentMonthFormat" text, "nonNablStartNumber" text, "productCount" double precision, "sampleCount" double precision)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  IF org IS NULL OR NOT public.app_has_permission('masters.manage') THEN
    RAISE EXCEPTION 'Product scheme generation requires permission' USING ERRCODE='42501';
  END IF;
  RETURN QUERY SELECT settings.scheme_current_year_digits,settings.scheme_next_year_digits,settings.scheme_separator,
    settings.scheme_month_format,settings.scheme_non_nabl_start_number,
    CASE WHEN include_products THEN (SELECT count(*)::double precision FROM public.products product WHERE product.organization_id=org AND product.active) ELSE 0::double precision END,
    CASE WHEN include_samples THEN (SELECT count(*)::double precision FROM public.samples sample WHERE sample.organization_id=org) ELSE 0::double precision END
  FROM public.organizations organization LEFT JOIN public.organization_laboratory_settings settings ON settings.organization_id=organization.id
  WHERE organization.id=org;
END $$;


--
-- Name: masters_record_customer(uuid, integer, text, text, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_record_customer(target_customer uuid, previous_revision integer, operation text, request_fingerprint text, address_ids uuid[], contact_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=public.organization_module_scope(); actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid; saved_revision integer;
BEGIN
  INSERT INTO public.customer_versions(organization_id,customer_id,revision,request_id,request_fingerprint,previous_revision,operation,
    code,name,legal_name,abbreviation,tax_identifier,credit_days,total_balance,default_invoice_notes,feedback_applicable,
    igst_percent,sgst_percent,cgst_percent,discount_percent,is_kaleen_bandhu,active,retired,save_source,custom_field_count,custom_fields_provided,
    address_count,contact_count,saved_by)
    SELECT organization_id,id,revision,save_request_id,request_fingerprint,previous_revision,operation,
      code,name,legal_name,abbreviation,tax_identifier,credit_days,total_balance,default_invoice_notes,feedback_applicable,
      igst_percent,sgst_percent,cgst_percent,discount_percent,is_kaleen_bandhu,active,retired,save_source,custom_field_count,custom_fields_provided,
      cardinality(address_ids),cardinality(contact_ids),actor FROM public.customers WHERE organization_id=org AND id=target_customer
    RETURNING revision INTO saved_revision;
  IF saved_revision IS NULL THEN RAISE EXCEPTION 'Customer was not found' USING ERRCODE='P0002',CONSTRAINT='customer_not_found'; END IF;
  INSERT INTO public.customer_version_addresses(organization_id,customer_id,revision,id,position,address_type,attention_to,line_1,line_2,city,state,
    postal_code,country_code,freeform_address,is_default)
    SELECT address.organization_id,address.customer_id,saved_revision,address.id,ordered.position-1,address.address_type,address.attention_to,
      address.line_1,address.line_2,address.city,address.state,address.postal_code,address.country_code,address.freeform_address,address.is_default
    FROM unnest(address_ids) WITH ORDINALITY ordered(id,position) JOIN public.customer_addresses address
      ON address.organization_id=org AND address.customer_id=target_customer AND address.id=ordered.id;
  INSERT INTO public.customer_version_contacts(organization_id,customer_id,revision,id,position,name,email,phone,designation,is_primary)
    SELECT contact.organization_id,contact.customer_id,saved_revision,contact.id,ordered.position-1,contact.name,contact.email,contact.phone,contact.designation,contact.is_primary
    FROM unnest(contact_ids) WITH ORDINALITY ordered(id,position) JOIN public.customer_contacts contact
      ON contact.organization_id=org AND contact.customer_id=target_customer AND contact.id=ordered.id;
  RETURN saved_revision;
END $$;


--
-- Name: masters_record_vendor(uuid, integer, text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_record_vendor(target_vendor uuid, previous_revision integer, operation text, request_fingerprint text, contact_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=public.organization_module_scope(); actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid; saved_revision integer;
BEGIN
  INSERT INTO public.vendor_versions(organization_id,vendor_id,revision,request_id,request_fingerprint,previous_revision,operation,
    code,name,legal_name,abbreviation,tax_identifier,total_balance,active,retired,custom_field_count,custom_fields_provided,contact_count,saved_by)
    SELECT organization_id,id,revision,save_request_id,request_fingerprint,previous_revision,operation,
      code,name,legal_name,abbreviation,tax_identifier,total_balance,active,retired,custom_field_count,custom_fields_provided,
      cardinality(contact_ids),actor FROM public.vendors WHERE organization_id=org AND id=target_vendor
    RETURNING revision INTO saved_revision;
  IF saved_revision IS NULL THEN RAISE EXCEPTION 'Vendor was not found' USING ERRCODE='P0002',CONSTRAINT='vendor_not_found'; END IF;
  INSERT INTO public.vendor_version_contacts(organization_id,vendor_id,revision,id,position,name,email,phone,is_primary)
    SELECT contact.organization_id,contact.vendor_id,saved_revision,contact.id,ordered.position-1,contact.name,contact.email,contact.phone,contact.is_primary
    FROM unnest(contact_ids) WITH ORDINALITY ordered(id,position) JOIN public.vendor_contacts contact
      ON contact.organization_id=org AND contact.vendor_id=target_vendor AND contact.id=ordered.id;
  RETURN saved_revision;
END $$;


