--
-- Name: masters_retire_customer(uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_retire_customer(target_customer uuid, expected_revision integer, request_id uuid, request_fingerprint text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=public.organization_module_scope(); current_customer public.customers; prior integer; address_ids uuid[]; contact_ids uuid[];
BEGIN
  prior:=public.masters_customer_prior_request(target_customer,expected_revision,request_id,request_fingerprint,'retire');
  IF prior IS NOT NULL THEN RETURN prior; END IF;
  SELECT * INTO current_customer FROM public.customers WHERE organization_id=org AND id=target_customer FOR UPDATE;
  IF current_customer.id IS NULL OR current_customer.retired THEN RAISE EXCEPTION 'Customer was not found' USING ERRCODE='P0002',CONSTRAINT='customer_not_found'; END IF;
  IF current_customer.revision<>expected_revision THEN RAISE EXCEPTION 'Customer changed; reload before deleting' USING ERRCODE='40001',CONSTRAINT='customer_stale_revision'; END IF;
  IF EXISTS(SELECT 1 FROM public.samples WHERE organization_id=org AND customer_id=target_customer)
    OR EXISTS(SELECT 1 FROM public.customer_quotations WHERE organization_id=org AND customer_id=target_customer) THEN
    RAISE EXCEPTION 'Customer is in use' USING ERRCODE='23503',CONSTRAINT='customer_in_use';
  END IF;
  SELECT coalesce(array_agg(address.id ORDER BY saved.position NULLS LAST,address.id),'{}') INTO address_ids FROM public.customer_addresses address
    LEFT JOIN public.customer_version_addresses saved ON saved.organization_id=address.organization_id AND saved.customer_id=address.customer_id
      AND saved.id=address.id AND saved.revision=current_customer.revision WHERE address.organization_id=org AND address.customer_id=target_customer;
  SELECT coalesce(array_agg(contact.id ORDER BY saved.position NULLS LAST,contact.id),'{}') INTO contact_ids FROM public.customer_contacts contact
    LEFT JOIN public.customer_version_contacts saved ON saved.organization_id=contact.organization_id AND saved.customer_id=contact.customer_id
      AND saved.id=contact.id AND saved.revision=current_customer.revision WHERE contact.organization_id=org AND contact.customer_id=target_customer;
  UPDATE public.customers SET retired=true,active=false,revision=revision+1,save_request_id=request_id,save_source='master',custom_fields_provided=false,
    updated_at=transaction_timestamp() WHERE organization_id=org AND id=target_customer;
  RETURN public.masters_record_customer(target_customer,expected_revision,'retire',request_fingerprint,address_ids,contact_ids);
END $$;


--
-- Name: masters_retire_vendor(uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_retire_vendor(target_vendor uuid, expected_revision integer, request_id uuid, request_fingerprint text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=public.organization_module_scope(); current_vendor public.vendors; prior integer; contact_ids uuid[];
BEGIN
  prior:=public.masters_vendor_prior_request(target_vendor,expected_revision,request_id,request_fingerprint,'retire');
  IF prior IS NOT NULL THEN RETURN prior; END IF;
  SELECT * INTO current_vendor FROM public.vendors WHERE organization_id=org AND id=target_vendor FOR UPDATE;
  IF current_vendor.id IS NULL OR current_vendor.retired THEN RAISE EXCEPTION 'Vendor was not found' USING ERRCODE='P0002',CONSTRAINT='vendor_not_found'; END IF;
  IF current_vendor.revision<>expected_revision THEN RAISE EXCEPTION 'Vendor changed; reload before deleting' USING ERRCODE='40001',CONSTRAINT='vendor_stale_revision'; END IF;
  SELECT array_agg(contact.id ORDER BY saved.position NULLS LAST,contact.id) INTO contact_ids FROM public.vendor_contacts contact
    LEFT JOIN public.vendor_version_contacts saved ON saved.organization_id=contact.organization_id AND saved.vendor_id=contact.vendor_id
      AND saved.id=contact.id AND saved.revision=current_vendor.revision WHERE contact.organization_id=org AND contact.vendor_id=target_vendor;
  UPDATE public.vendors SET retired=true,active=false,revision=revision+1,save_request_id=request_id,custom_fields_provided=false,
    updated_at=transaction_timestamp() WHERE organization_id=org AND id=target_vendor;
  RETURN public.masters_record_vendor(target_vendor,expected_revision,'retire',request_fingerprint,contact_ids);
END $$;


--
-- Name: masters_save_customer(uuid, integer, uuid, text, text, text, text, text, text, integer, numeric, text, boolean, numeric, numeric, numeric, numeric, boolean, boolean, integer, boolean, uuid[], text[], text[], text[], text[], text[], text[], text[], text[], text[], boolean[], uuid[], text[], text[], text[], text[], boolean[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_save_customer(target_customer uuid, expected_revision integer, request_id uuid, request_fingerprint text, code text, name text, legal_name text, abbreviation text, tax_identifier text, credit_days integer, total_balance numeric, default_invoice_notes text, feedback_applicable boolean, igst_percent numeric, sgst_percent numeric, cgst_percent numeric, discount_percent numeric, is_kaleen_bandhu boolean, active boolean, custom_field_count integer, custom_fields_provided boolean, address_ids uuid[], address_types text[], attention_tos text[], line_1s text[], line_2s text[], cities text[], states text[], postal_codes text[], country_codes text[], freeform_addresses text[], address_defaults boolean[], contact_ids uuid[], contact_names text[], contact_emails text[], contact_phones text[], contact_designations text[], contact_primaries boolean[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE org uuid:=public.organization_module_scope(); current_customer public.customers; prior integer;
  address_count integer:=cardinality(address_ids); contact_count integer:=cardinality(contact_ids);
BEGIN
  prior:=public.masters_customer_prior_request(target_customer,expected_revision,request_id,request_fingerprint,CASE WHEN expected_revision=0 THEN 'create' ELSE 'update' END);
  IF prior IS NOT NULL THEN RETURN prior; END IF;
  SELECT * INTO current_customer FROM public.customers WHERE organization_id=org AND id=target_customer FOR UPDATE;
  IF expected_revision>0 AND (current_customer.id IS NULL OR current_customer.retired) THEN
    RAISE EXCEPTION 'Customer was not found' USING ERRCODE='P0002',CONSTRAINT='customer_not_found';
  END IF;
  IF coalesce(current_customer.revision,0)<>expected_revision THEN
    RAISE EXCEPTION 'Customer changed; reload before saving' USING ERRCODE='40001',CONSTRAINT='customer_stale_revision';
  END IF;
  IF NOT coalesce(length(trim(code)) BETWEEN 1 AND 64 AND length(trim(name)) BETWEEN 1 AND 250 AND length(trim(legal_name)) BETWEEN 1 AND 250
    AND (abbreviation IS NULL OR length(abbreviation)<=64) AND (tax_identifier IS NULL OR length(tax_identifier)<=100)
    AND credit_days BETWEEN 0 AND 3650 AND total_balance NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)
    AND (default_invoice_notes IS NULL OR length(default_invoice_notes)<=10000) AND igst_percent BETWEEN 0 AND 100 AND sgst_percent BETWEEN 0 AND 100
    AND cgst_percent BETWEEN 0 AND 100 AND discount_percent BETWEEN 0 AND 100 AND feedback_applicable IS NOT NULL AND is_kaleen_bandhu IS NOT NULL AND active IS NOT NULL
    AND custom_field_count BETWEEN 0 AND 500 AND custom_fields_provided IS NOT NULL,false) THEN
    RAISE EXCEPTION 'Invalid Customer details' USING ERRCODE='23514',CONSTRAINT='customer_command_input';
  END IF;
  IF NOT coalesce(address_count BETWEEN 0 AND 100 AND contact_count BETWEEN 0 AND 100
    AND cardinality(address_types)=address_count AND cardinality(attention_tos)=address_count AND cardinality(line_1s)=address_count AND cardinality(line_2s)=address_count
    AND cardinality(cities)=address_count AND cardinality(states)=address_count AND cardinality(postal_codes)=address_count AND cardinality(country_codes)=address_count
    AND cardinality(freeform_addresses)=address_count AND cardinality(address_defaults)=address_count AND cardinality(contact_names)=contact_count
    AND cardinality(contact_emails)=contact_count AND cardinality(contact_phones)=contact_count AND cardinality(contact_designations)=contact_count AND cardinality(contact_primaries)=contact_count,false)
    OR (SELECT count(DISTINCT id) FROM unnest(address_ids) ids(id))<>address_count OR (SELECT count(DISTINCT id) FROM unnest(contact_ids) ids(id))<>contact_count THEN
    RAISE EXCEPTION 'Invalid Customer relationships' USING ERRCODE='23514',CONSTRAINT='customer_relation_input';
  END IF;
  IF EXISTS (SELECT 1 FROM public.customer_addresses WHERE organization_id=org AND id=ANY(address_ids) AND customer_id<>target_customer)
    OR EXISTS (SELECT 1 FROM public.customer_contacts WHERE organization_id=org AND id=ANY(contact_ids) AND customer_id<>target_customer)
    OR EXISTS (SELECT 1 FROM public.customer_version_addresses WHERE organization_id=org AND id=ANY(address_ids) AND customer_id<>target_customer)
    OR EXISTS (SELECT 1 FROM public.customer_version_contacts WHERE organization_id=org AND id=ANY(contact_ids) AND customer_id<>target_customer) THEN
    RAISE EXCEPTION 'Customer relationships cannot be reassigned' USING ERRCODE='23514',CONSTRAINT='customer_relation_owner';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(address_ids,address_types,attention_tos,line_1s,line_2s,cities,states,postal_codes,country_codes,freeform_addresses,address_defaults)
      incoming(id,address_type,attention_to,line_1,line_2,city,state,postal_code,country_code,freeform_address,is_default)
    LEFT JOIN public.customer_addresses stored ON stored.organization_id=org AND stored.customer_id=target_customer AND stored.id=incoming.id
    WHERE (stored.id IS NULL OR (incoming.address_type,incoming.attention_to,incoming.line_1,incoming.line_2,incoming.city,incoming.state,incoming.postal_code,incoming.country_code,incoming.freeform_address)
      IS DISTINCT FROM (stored.address_type,stored.attention_to,stored.line_1,stored.line_2,stored.city,stored.state,stored.postal_code,stored.country_code,stored.freeform_address))
    AND NOT coalesce(incoming.address_type IN ('billing','shipping','registered','other') AND incoming.is_default IS NOT NULL
      AND ((incoming.freeform_address IS NOT NULL AND length(trim(incoming.freeform_address)) BETWEEN 1 AND 4000
        AND num_nonnulls(incoming.attention_to,incoming.line_1,incoming.line_2,incoming.city,incoming.state,incoming.postal_code,incoming.country_code)=0)
      OR (incoming.freeform_address IS NULL AND length(trim(incoming.line_1)) BETWEEN 1 AND 250 AND length(trim(incoming.city)) BETWEEN 1 AND 120
        AND incoming.country_code ~ '^[A-Z]{2}$' AND (incoming.attention_to IS NULL OR length(incoming.attention_to)<=200)
        AND (incoming.line_2 IS NULL OR length(incoming.line_2)<=250) AND (incoming.state IS NULL OR length(incoming.state)<=120)
        AND (incoming.postal_code IS NULL OR length(incoming.postal_code)<=30))),false)
  ) OR EXISTS (
    SELECT 1 FROM unnest(contact_ids,contact_names,contact_emails,contact_phones,contact_designations,contact_primaries) incoming(id,name,email,phone,designation,is_primary)
    LEFT JOIN public.customer_contacts stored ON stored.organization_id=org AND stored.customer_id=target_customer AND stored.id=incoming.id
    WHERE (stored.id IS NULL OR (incoming.name,incoming.email,incoming.phone,incoming.designation) IS DISTINCT FROM (stored.name,stored.email,stored.phone,stored.designation))
    AND NOT coalesce(length(trim(incoming.name)) BETWEEN 1 AND 200 AND incoming.is_primary IS NOT NULL
      AND (incoming.email IS NULL OR (length(incoming.email)<=320 AND incoming.email ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'))
      AND (incoming.phone IS NULL OR length(trim(incoming.phone)) BETWEEN 1 AND 50) AND (incoming.designation IS NULL OR length(incoming.designation)<=120)
      AND num_nonnulls(incoming.email,incoming.phone)>0,false)
  ) THEN RAISE EXCEPTION 'Invalid Customer contact or address values' USING ERRCODE='23514',CONSTRAINT='customer_relation_input'; END IF;
  IF expected_revision=0 THEN
    INSERT INTO public.customers(organization_id,id,code,name,legal_name,abbreviation,tax_identifier,credit_days,total_balance,default_invoice_notes,feedback_applicable,
      igst_percent,sgst_percent,cgst_percent,discount_percent,is_kaleen_bandhu,active,save_request_id,save_source,custom_field_count,custom_fields_provided)
      VALUES(org,target_customer,code,name,legal_name,abbreviation,tax_identifier,credit_days,total_balance,default_invoice_notes,feedback_applicable,
        igst_percent,sgst_percent,cgst_percent,discount_percent,is_kaleen_bandhu,active,request_id,'master',custom_field_count,custom_fields_provided);
  ELSE
    UPDATE public.customers customer SET code=masters_save_customer.code,name=masters_save_customer.name,legal_name=masters_save_customer.legal_name,
      abbreviation=masters_save_customer.abbreviation,tax_identifier=masters_save_customer.tax_identifier,credit_days=masters_save_customer.credit_days,
      total_balance=masters_save_customer.total_balance,default_invoice_notes=masters_save_customer.default_invoice_notes,feedback_applicable=masters_save_customer.feedback_applicable,
      igst_percent=masters_save_customer.igst_percent,sgst_percent=masters_save_customer.sgst_percent,cgst_percent=masters_save_customer.cgst_percent,
      discount_percent=masters_save_customer.discount_percent,is_kaleen_bandhu=masters_save_customer.is_kaleen_bandhu,active=masters_save_customer.active,
      save_request_id=request_id,save_source='master',custom_field_count=masters_save_customer.custom_field_count,custom_fields_provided=masters_save_customer.custom_fields_provided,
      revision=customer.revision+1,updated_at=transaction_timestamp() WHERE customer.organization_id=org AND customer.id=target_customer;
  END IF;
  -- Same-ID rows are updated in place. Clear old default flags before applying
  -- the complete set, so switching the default never transiently duplicates it.
  DELETE FROM public.customer_addresses WHERE organization_id=org AND customer_id=target_customer AND NOT(id=ANY(address_ids));
  DELETE FROM public.customer_contacts WHERE organization_id=org AND customer_id=target_customer AND NOT(id=ANY(contact_ids));
  UPDATE public.customer_addresses SET is_default=false WHERE organization_id=org AND customer_id=target_customer AND is_default;
  UPDATE public.customer_contacts SET is_primary=false WHERE organization_id=org AND customer_id=target_customer AND is_primary;
  INSERT INTO public.customer_addresses(organization_id,customer_id,id,address_type,attention_to,line_1,line_2,city,state,postal_code,country_code,freeform_address,is_default)
    SELECT org,target_customer,* FROM unnest(address_ids,address_types,attention_tos,line_1s,line_2s,cities,states,postal_codes,country_codes,freeform_addresses,address_defaults)
    ON CONFLICT(organization_id,id) DO UPDATE SET address_type=excluded.address_type,attention_to=excluded.attention_to,line_1=excluded.line_1,line_2=excluded.line_2,
      city=excluded.city,state=excluded.state,postal_code=excluded.postal_code,country_code=excluded.country_code,freeform_address=excluded.freeform_address,is_default=excluded.is_default
    WHERE customer_addresses.customer_id=target_customer;
  INSERT INTO public.customer_contacts(organization_id,customer_id,id,name,email,phone,designation,is_primary)
    SELECT org,target_customer,* FROM unnest(contact_ids,contact_names,contact_emails,contact_phones,contact_designations,contact_primaries)
    ON CONFLICT(organization_id,id) DO UPDATE SET name=excluded.name,email=excluded.email,phone=excluded.phone,designation=excluded.designation,is_primary=excluded.is_primary
    WHERE customer_contacts.customer_id=target_customer;
  RETURN public.masters_record_customer(target_customer,nullif(expected_revision,0),CASE WHEN expected_revision=0 THEN 'create' ELSE 'update' END,request_fingerprint,address_ids,contact_ids);
END $_$;


--
-- Name: masters_save_vendor(uuid, integer, uuid, text, text, text, text, text, text, numeric, boolean, integer, boolean, uuid[], text[], text[], text[], boolean[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_save_vendor(target_vendor uuid, expected_revision integer, request_id uuid, request_fingerprint text, code text, name text, legal_name text, abbreviation text, tax_identifier text, total_balance numeric, active boolean, custom_field_count integer, custom_fields_provided boolean, contact_ids uuid[], contact_names text[], contact_emails text[], contact_phones text[], contact_primaries boolean[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE org uuid:=public.organization_module_scope(); current_vendor public.vendors; prior integer; contact_count integer:=cardinality(contact_ids);
BEGIN
  prior:=public.masters_vendor_prior_request(target_vendor,expected_revision,request_id,request_fingerprint,CASE WHEN expected_revision=0 THEN 'create' ELSE 'update' END);
  IF prior IS NOT NULL THEN RETURN prior; END IF;
  SELECT * INTO current_vendor FROM public.vendors WHERE organization_id=org AND id=target_vendor FOR UPDATE;
  IF expected_revision>0 AND (current_vendor.id IS NULL OR current_vendor.retired) THEN
    RAISE EXCEPTION 'Vendor was not found' USING ERRCODE='P0002',CONSTRAINT='vendor_not_found';
  END IF;
  IF coalesce(current_vendor.revision,0)<>expected_revision THEN
    RAISE EXCEPTION 'Vendor changed; reload before saving' USING ERRCODE='40001',CONSTRAINT='vendor_stale_revision';
  END IF;
  IF NOT coalesce(length(trim(code)) BETWEEN 1 AND 64 AND code ~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$'
    AND length(trim(name)) BETWEEN 1 AND 250 AND length(trim(legal_name)) BETWEEN 1 AND 250
    AND (abbreviation IS NULL OR length(abbreviation)<=64) AND (tax_identifier IS NULL OR length(tax_identifier)<=100)
    AND total_balance NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) AND active IS NOT NULL
    AND custom_field_count BETWEEN 0 AND 500 AND custom_fields_provided IS NOT NULL,false) THEN
    RAISE EXCEPTION 'Invalid Vendor details' USING ERRCODE='23514',CONSTRAINT='vendor_command_input';
  END IF;
  IF NOT coalesce(contact_count BETWEEN 1 AND 100 AND cardinality(contact_names)=contact_count AND cardinality(contact_emails)=contact_count
    AND cardinality(contact_phones)=contact_count AND cardinality(contact_primaries)=contact_count,false)
    OR (SELECT count(DISTINCT id) FROM unnest(contact_ids) ids(id))<>contact_count THEN
    RAISE EXCEPTION 'Invalid Vendor contacts' USING ERRCODE='23514',CONSTRAINT='vendor_relation_input';
  END IF;
  IF EXISTS (SELECT 1 FROM public.vendor_contacts WHERE organization_id=org AND id=ANY(contact_ids) AND vendor_id<>target_vendor)
    OR EXISTS (SELECT 1 FROM public.vendor_version_contacts WHERE organization_id=org AND id=ANY(contact_ids) AND vendor_id<>target_vendor) THEN
    RAISE EXCEPTION 'Vendor contacts cannot be reassigned' USING ERRCODE='23514',CONSTRAINT='vendor_relation_owner';
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(contact_ids,contact_names,contact_emails,contact_phones,contact_primaries) incoming(id,name,email,phone,is_primary)
    WHERE NOT coalesce(length(trim(incoming.name)) BETWEEN 1 AND 200 AND length(incoming.email) BETWEEN 3 AND 320
      AND incoming.email ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
      AND length(trim(incoming.phone)) BETWEEN 1 AND 50 AND incoming.is_primary IS NOT NULL,false)
  ) OR (SELECT count(*) FROM unnest(contact_primaries) flags(is_primary) WHERE is_primary)>1 THEN
    RAISE EXCEPTION 'Invalid Vendor contact values' USING ERRCODE='23514',CONSTRAINT='vendor_relation_input';
  END IF;
  IF expected_revision=0 THEN
    INSERT INTO public.vendors(organization_id,id,code,name,legal_name,abbreviation,tax_identifier,total_balance,active,save_request_id,custom_field_count,custom_fields_provided)
      VALUES(org,target_vendor,code,name,legal_name,abbreviation,tax_identifier,total_balance,active,request_id,custom_field_count,custom_fields_provided);
  ELSE
    UPDATE public.vendors vendor SET code=masters_save_vendor.code,name=masters_save_vendor.name,legal_name=masters_save_vendor.legal_name,
      abbreviation=masters_save_vendor.abbreviation,tax_identifier=masters_save_vendor.tax_identifier,total_balance=masters_save_vendor.total_balance,
      active=masters_save_vendor.active,save_request_id=request_id,custom_field_count=masters_save_vendor.custom_field_count,
      custom_fields_provided=masters_save_vendor.custom_fields_provided,revision=vendor.revision+1,updated_at=transaction_timestamp()
      WHERE vendor.organization_id=org AND vendor.id=target_vendor;
  END IF;
  -- Update retained contacts in place and clear old primary flags before switching.
  DELETE FROM public.vendor_contacts WHERE organization_id=org AND vendor_id=target_vendor AND NOT(id=ANY(contact_ids));
  UPDATE public.vendor_contacts SET is_primary=false WHERE organization_id=org AND vendor_id=target_vendor AND is_primary;
  INSERT INTO public.vendor_contacts(organization_id,vendor_id,id,name,email,phone,is_primary)
    SELECT org,target_vendor,* FROM unnest(contact_ids,contact_names,contact_emails,contact_phones,contact_primaries)
    ON CONFLICT(organization_id,id) DO UPDATE SET name=excluded.name,email=excluded.email,phone=excluded.phone,is_primary=excluded.is_primary
    WHERE vendor_contacts.vendor_id=target_vendor;
  RETURN public.masters_record_vendor(target_vendor,nullif(expected_revision,0),CASE WHEN expected_revision=0 THEN 'create' ELSE 'update' END,request_fingerprint,contact_ids);
END $_$;


--
-- Name: masters_track_custom_field(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_track_custom_field() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid := nullif(current_setting('app.user_id',true),'')::uuid; operation text;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Retire custom fields to preserve history' USING ERRCODE='55000'; END IF;
  IF actor IS NULL OR (session_user='sampleify_app' AND (NOT public.app_has_permission('masters.manage')
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid)) THEN
    RAISE EXCEPTION 'Master management permission and actual editor required' USING ERRCODE='42501';
  END IF;
  IF NEW.updated_at<>transaction_timestamp() THEN
    RAISE EXCEPTION 'Custom field writes require the actual transaction time' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.revision<>1 OR NOT NEW.active OR NEW.created_at<>transaction_timestamp() THEN
      RAISE EXCEPTION 'New custom fields start active at revision one with their creation time' USING ERRCODE='23514';
    END IF;
    operation := 'create';
  ELSE
    IF (NEW.organization_id,NEW.id,NEW.created_at) IS DISTINCT FROM (OLD.organization_id,OLD.id,OLD.created_at)
      OR NEW.revision<>OLD.revision+1 OR NOT OLD.active THEN
      RAISE EXCEPTION 'Custom field writes preserve identity and advance the active revision' USING ERRCODE='23514';
    END IF;
    PERFORM public.masters_assert_custom_field_links(OLD.organization_id,OLD.id,OLD.revision);
    operation := CASE WHEN NEW.active THEN 'update' ELSE 'retire' END;
    IF NOT NEW.active AND ((NEW.key,NEW.label,NEW.description,NEW.auto_generated,NEW.scheme,NEW.nabl_display_term,NEW.non_nabl_display_term,NEW.field_type,NEW.associated_with,NEW.show_in_list,NEW.show_in_filter,NEW.allows_multiple,NEW.is_required,NEW.padded_number,NEW.display_order,NEW.date_format,NEW.datetime_format,NEW.generated_at,NEW.associate_role_specific_users,NEW.associated_with_role_id,NEW.splitter,NEW.filter_search_type,NEW.show_in_dashboard,NEW.show_in_report,NEW.validate_uniqueness,NEW.hide_from_sample_creation,NEW.option_count,NEW.edit_role_count,NEW.lookup_source_id,NEW.edit_on_reissue) IS DISTINCT FROM (OLD.key,OLD.label,OLD.description,OLD.auto_generated,OLD.scheme,OLD.nabl_display_term,OLD.non_nabl_display_term,OLD.field_type,OLD.associated_with,OLD.show_in_list,OLD.show_in_filter,OLD.allows_multiple,OLD.is_required,OLD.padded_number,OLD.display_order,OLD.date_format,OLD.datetime_format,OLD.generated_at,OLD.associate_role_specific_users,OLD.associated_with_role_id,OLD.splitter,OLD.filter_search_type,OLD.show_in_dashboard,OLD.show_in_report,OLD.validate_uniqueness,OLD.hide_from_sample_creation,OLD.option_count,OLD.edit_role_count,OLD.lookup_source_id,OLD.edit_on_reissue)) THEN
      RAISE EXCEPTION 'Custom field retirement preserves its last settings' USING ERRCODE='23514';
    END IF;
  END IF;
  INSERT INTO public.custom_field_versions(organization_id,field_id,revision,request_id,previous_revision,operation,key,label,description,auto_generated,scheme,nabl_display_term,non_nabl_display_term,field_type,associated_with,show_in_list,show_in_filter,allows_multiple,is_required,padded_number,display_order,date_format,datetime_format,generated_at,associate_role_specific_users,associated_with_role_id,splitter,filter_search_type,show_in_dashboard,show_in_report,validate_uniqueness,hide_from_sample_creation,option_count,edit_role_count,active,saved_by,lookup_source_id,edit_on_reissue)
  VALUES(NEW.organization_id,NEW.id,NEW.revision,NEW.save_request_id,CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.revision END,operation,NEW.key,NEW.label,NEW.description,NEW.auto_generated,NEW.scheme,NEW.nabl_display_term,NEW.non_nabl_display_term,NEW.field_type,NEW.associated_with,NEW.show_in_list,NEW.show_in_filter,NEW.allows_multiple,NEW.is_required,NEW.padded_number,NEW.display_order,NEW.date_format,NEW.datetime_format,NEW.generated_at,NEW.associate_role_specific_users,NEW.associated_with_role_id,NEW.splitter,NEW.filter_search_type,NEW.show_in_dashboard,NEW.show_in_report,NEW.validate_uniqueness,NEW.hide_from_sample_creation,NEW.option_count,NEW.edit_role_count,NEW.active,actor,NEW.lookup_source_id,NEW.edit_on_reissue);
  RETURN NEW;
END $$;


