--
-- Name: masters_track_lookup_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_track_lookup_source() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid := nullif(current_setting('app.user_id',true),'')::uuid;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Preserve lookup source identities and observations' USING ERRCODE='55000'; END IF;
  IF actor IS NULL OR (session_user='sampleify_app' AND (NOT public.app_has_permission('masters.manage')
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid)) THEN
    RAISE EXCEPTION 'Lookup observations require master management and the actual observer' USING ERRCODE='42501';
  END IF;
  IF session_user='sampleify_app' THEN
    PERFORM public.masters_lock_lookup_observer();
  ELSE
    PERFORM pg_advisory_xact_lock(hashtextextended('custom-field-definitions:'||NEW.organization_id::text,0));
  END IF;
  IF NEW.updated_at<>transaction_timestamp() THEN RAISE EXCEPTION 'Lookup updates require their actual transaction time' USING ERRCODE='23514'; END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.revision<>1 OR NEW.created_at<>transaction_timestamp() THEN
      RAISE EXCEPTION 'Lookup observations start at revision one in their creation transaction' USING ERRCODE='23514';
    END IF;
  ELSE
    IF (NEW.organization_id,NEW.id,NEW.source_system,NEW.original_source_id,NEW.created_at)
        IS DISTINCT FROM (OLD.organization_id,OLD.id,OLD.source_system,OLD.original_source_id,OLD.created_at)
      OR NEW.revision<>OLD.revision+1 THEN
      RAISE EXCEPTION 'Lookup observations preserve source identity and advance one revision' USING ERRCODE='23514';
    END IF;
    PERFORM public.masters_assert_lookup_lines(OLD.organization_id,OLD.id,OLD.revision);
  END IF;
  INSERT INTO public.custom_field_lookup_versions(organization_id,source_id,revision,previous_revision,request_id,name,line_count,observed_by)
    VALUES(NEW.organization_id,NEW.id,NEW.revision,NEW.revision-1,NEW.request_id,NEW.name,NEW.line_count,actor);
  RETURN NEW;
END $$;


--
-- Name: masters_track_material(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_track_material() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF session_user<>'sampleify_app' THEN RETURN NEW; END IF;
  INSERT INTO public.material_versions(organization_id,material_id,revision,request_id,previous_revision,operation,name,code,description,
    category_id,category_name,category_reusable,category_expirable,measurement_unit_id,unit_name,unit_symbol,
    initial_quantity,minimum_quantity,maximum_quantity,initial_stock_id,initial_stock_created_at,initial_stock_created_by,active,maximum_provided,saved_by)
  SELECT NEW.organization_id,NEW.id,NEW.revision,NEW.save_request_id,CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.revision END,
    CASE WHEN TG_OP='INSERT' THEN 'create' WHEN NEW.active THEN 'update' ELSE 'retire' END,NEW.name,NEW.code,NEW.description,
    category.id,category.name,category.reusable,category.expirable,unit.id,unit.name,unit.symbol,
    NEW.initial_quantity,NEW.minimum_quantity,NEW.maximum_quantity,NEW.initial_stock_id,NEW.initial_stock_created_at,NEW.initial_stock_created_by,NEW.active,NEW.maximum_provided,NEW.updated_by
  FROM public.material_categories category JOIN public.measurement_units unit ON unit.organization_id=category.organization_id
  WHERE category.organization_id=NEW.organization_id AND category.id=NEW.category_id AND unit.id=NEW.measurement_unit_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Material references are unavailable' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: masters_track_material_category(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_track_material_category() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid; operation text;
BEGIN
  -- Offline owner imports retain their real provenance; they do not acquire invented editor history.
  IF session_user<>'sampleify_app' THEN RETURN NEW; END IF;
  IF actor IS NULL OR NOT public.app_has_permission('masters.manage')
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Master management permission required' USING ERRCODE='42501';
  END IF;
  IF NEW.save_request_id IS NULL OR NEW.updated_at<>transaction_timestamp() OR NEW.updated_by IS DISTINCT FROM actor THEN
    RAISE EXCEPTION 'Category writes require the actual editor, request and transaction time' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.revision<>1 OR NOT NEW.active OR NEW.created_at<>transaction_timestamp() OR NEW.created_by IS DISTINCT FROM actor THEN
      RAISE EXCEPTION 'New categories require revision one and actual creation metadata' USING ERRCODE='23514';
    END IF;
    operation:='create';
  ELSE
    IF (NEW.organization_id,NEW.id,NEW.created_at,NEW.created_by) IS DISTINCT FROM (OLD.organization_id,OLD.id,OLD.created_at,OLD.created_by)
      OR NEW.revision<>OLD.revision+1 OR NOT OLD.active THEN
      RAISE EXCEPTION 'Category writes preserve identity and advance the active revision' USING ERRCODE='23514';
    END IF;
    operation:=CASE WHEN NEW.active THEN 'update' ELSE 'retire' END;
    IF NOT NEW.active AND (NEW.name,NEW.description,NEW.reusable,NEW.expirable) IS DISTINCT FROM (OLD.name,OLD.description,OLD.reusable,OLD.expirable) THEN
      RAISE EXCEPTION 'Category retirement preserves its last values' USING ERRCODE='23514';
    END IF;
  END IF;
  INSERT INTO public.material_category_versions(organization_id,category_id,revision,request_id,previous_revision,operation,name,description,reusable,expirable,active,saved_by)
  VALUES(NEW.organization_id,NEW.id,NEW.revision,NEW.save_request_id,CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.revision END,operation,
    NEW.name,NEW.description,NEW.reusable,NEW.expirable,NEW.active,actor);
  RETURN NEW;
END $$;


--
-- Name: masters_track_method(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_track_method() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid := nullif(current_setting('app.user_id',true),'')::uuid; operation text;
BEGIN
  -- Existing migration/fixture records do not acquire fabricated past actors.
  IF session_user<>'sampleify_app' THEN RETURN NEW; END IF;
  IF actor IS NULL OR NOT public.app_has_permission('masters.manage')
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Master management permission required' USING ERRCODE='42501';
  END IF;
  IF NEW.save_request_id IS NULL OR NEW.updated_at<>transaction_timestamp() THEN
    RAISE EXCEPTION 'Method writes require an actual save request and transaction time' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.revision<>1 OR NOT NEW.active THEN RAISE EXCEPTION 'New methods start active at revision one' USING ERRCODE='23514'; END IF;
    operation := 'create';
  ELSE
    IF (NEW.organization_id,NEW.id,NEW.created_at,NEW.code) IS DISTINCT FROM (OLD.organization_id,OLD.id,OLD.created_at,OLD.code)
      OR NEW.revision<>OLD.revision+1 OR (NOT OLD.active AND (NEW.active OR NOT EXISTS (
        SELECT 1 FROM public.master_bulk_reviews review
        JOIN public.master_bulk_batches batch ON batch.organization_id=review.organization_id AND batch.id=review.batch_id
        JOIN public.master_bulk_rows row ON row.organization_id=review.organization_id AND row.batch_id=review.batch_id AND row.id=review.row_id AND row.revision=review.input_revision
        WHERE review.organization_id=NEW.organization_id AND review.id=NEW.save_request_id AND review.valid
          AND review.candidate_id=NEW.id AND review.expected_revision=OLD.revision AND review.operation='update_retired' AND batch.resource='methods'
      ))) THEN
      RAISE EXCEPTION 'Method writes preserve identity and advance the revision without an unsupported status change' USING ERRCODE='23514';
    END IF;
    operation := CASE WHEN OLD.active AND NOT NEW.active THEN 'retire' ELSE 'update' END;
    IF OLD.active AND NOT NEW.active AND (NEW.method_uuid,NEW.name,NEW.description,NEW.decimal_scale,NEW.parse_number,NEW.access_user_count)
      IS DISTINCT FROM (OLD.method_uuid,OLD.name,OLD.description,OLD.decimal_scale,OLD.parse_number,OLD.access_user_count) THEN
      RAISE EXCEPTION 'Method retirement preserves its last settings' USING ERRCODE='23514';
    END IF;
  END IF;
  INSERT INTO public.method_versions(organization_id,method_id,revision,request_id,previous_revision,operation,code,method_uuid,name,description,
    decimal_scale,parse_number,active,access_user_count,saved_by)
  VALUES(NEW.organization_id,NEW.id,NEW.revision,NEW.save_request_id,CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.revision END,operation,
    NEW.code,NEW.method_uuid,NEW.name,NEW.description,NEW.decimal_scale,NEW.parse_number,NEW.active,NEW.access_user_count,actor);
  RETURN NEW;
END $$;


--
-- Name: masters_track_product(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_track_product() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid := nullif(current_setting('app.user_id',true),'')::uuid; operation text;
BEGIN
  -- Existing migration/fixture records gain history only on an actual app edit.
  IF session_user<>'sampleify_app' THEN RETURN NEW; END IF;
  IF actor IS NULL OR NOT public.app_has_permission('masters.manage')
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Master management permission required' USING ERRCODE='42501';
  END IF;
  IF NEW.save_request_id IS NULL OR NEW.updated_at<>transaction_timestamp() THEN
    RAISE EXCEPTION 'Product writes require an actual save request and transaction time' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.revision<>1 OR NOT NEW.active THEN RAISE EXCEPTION 'New products start active at revision one' USING ERRCODE='23514'; END IF;
    operation := 'create';
  ELSE
    IF (NEW.organization_id,NEW.id,NEW.created_at) IS DISTINCT FROM (OLD.organization_id,OLD.id,OLD.created_at)
      OR NEW.revision<>OLD.revision+1 OR (NOT OLD.active AND (NOT NEW.active OR NOT EXISTS (
        SELECT 1 FROM public.master_bulk_reviews review
        JOIN public.master_bulk_batches batch ON batch.organization_id=review.organization_id AND batch.id=review.batch_id
        JOIN public.master_bulk_rows row ON row.organization_id=review.organization_id AND row.batch_id=review.batch_id AND row.id=review.row_id AND row.revision=review.input_revision
        WHERE review.organization_id=NEW.organization_id AND review.id=NEW.save_request_id AND review.valid
          AND review.candidate_id=NEW.id AND review.expected_revision=OLD.revision AND review.operation='reactivate' AND batch.resource='products'
      ))) THEN
      RAISE EXCEPTION 'Product writes preserve identity and advance the revision without an unsupported status change' USING ERRCODE='23514';
    END IF;
    -- Check an earlier save before a second edit can replace its operational links.
    IF EXISTS (SELECT 1 FROM public.product_versions WHERE organization_id=OLD.organization_id AND product_id=OLD.id AND revision=OLD.revision) THEN
      PERFORM public.masters_assert_product_tags(OLD.organization_id,OLD.id,OLD.revision,true);
      PERFORM public.masters_assert_product_sample_categories(OLD.organization_id,OLD.id,OLD.revision,true);
    END IF;
    operation := CASE WHEN NEW.active THEN 'update' ELSE 'retire' END;
    IF NOT NEW.active AND ((NEW.code,NEW.name,NEW.description,NEW.abbreviation,NEW.job_template_id)
      IS DISTINCT FROM (OLD.code,OLD.name,OLD.description,OLD.abbreviation,OLD.job_template_id)
      OR NEW.tag_count<>(SELECT count(*) FROM public.product_tags WHERE organization_id=NEW.organization_id AND product_id=NEW.id)) THEN
      RAISE EXCEPTION 'Product retirement preserves its last settings and tags' USING ERRCODE='23514';
    END IF;
  END IF;
  IF operation<>'retire' AND NEW.job_template_id IS NOT NULL THEN
    PERFORM 1 FROM public.templates template WHERE template.organization_id=NEW.organization_id AND template.id=NEW.job_template_id AND template.active
      AND EXISTS (SELECT 1 FROM public.template_versions WHERE organization_id=NEW.organization_id AND template_id=NEW.job_template_id AND status<>'building') FOR SHARE OF template;
    IF NOT FOUND THEN RAISE EXCEPTION 'Select an active template in this organization' USING ERRCODE='23514',CONSTRAINT='product_active_template'; END IF;
  END IF;
  INSERT INTO public.product_versions(organization_id,product_id,revision,request_id,previous_revision,operation,code,name,description,abbreviation,
    job_template_id,active,tag_count,saved_by)
  VALUES(NEW.organization_id,NEW.id,NEW.revision,NEW.save_request_id,CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.revision END,operation,
    NEW.code,NEW.name,NEW.description,NEW.abbreviation,NEW.job_template_id,NEW.active,NEW.tag_count,actor);
  RETURN NEW;
END $$;


