    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid := nullif(current_setting('app.user_id',true),'')::uuid; operation text;
BEGIN
  -- Existing migration/fixture records gain history only on an actual app edit.
  IF session_user<>'sampleify_app' THEN RETURN NEW; END IF;
  IF actor IS NULL OR NOT public.app_has_permission('masters.manage')
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Master management permission required' USING ERRCODE='42501';
  END IF;
  IF NEW.save_request_id IS NULL OR NEW.updated_at<>transaction_timestamp() THEN
    RAISE EXCEPTION 'Sample Category writes require an actual save request and transaction time' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.revision<>1 OR NOT NEW.active THEN RAISE EXCEPTION 'New Sample Categories start active at revision one' USING ERRCODE='23514'; END IF;
    operation := 'create';
  ELSE
    IF (NEW.organization_id,NEW.id,NEW.created_at) IS DISTINCT FROM (OLD.organization_id,OLD.id,OLD.created_at)
      OR NEW.revision<>OLD.revision+1 OR NOT OLD.active THEN
      RAISE EXCEPTION 'Sample Category writes preserve identity and advance the active revision' USING ERRCODE='23514';
    END IF;
    operation := CASE WHEN NEW.active THEN 'update' ELSE 'retire' END;
    IF NOT NEW.active AND (NEW.code,NEW.name,NEW.description,NEW.abbreviation,NEW.retention_days,NEW.estimated_time_in_days,NEW.enable_events,NEW.enable_reissue)
      IS DISTINCT FROM (OLD.code,OLD.name,OLD.description,OLD.abbreviation,OLD.retention_days,OLD.estimated_time_in_days,OLD.enable_events,OLD.enable_reissue) THEN
      RAISE EXCEPTION 'Sample Category retirement preserves its last settings' USING ERRCODE='23514';
    END IF;
  END IF;
  INSERT INTO public.sample_category_versions(organization_id,sample_category_id,revision,request_id,previous_revision,operation,
    code,name,description,abbreviation,retention_days,estimated_time_in_days,enable_events,enable_reissue,active,saved_by)
  VALUES(NEW.organization_id,NEW.id,NEW.revision,NEW.save_request_id,CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.revision END,operation,
    NEW.code,NEW.name,NEW.description,NEW.abbreviation,NEW.retention_days,NEW.estimated_time_in_days,NEW.enable_events,NEW.enable_reissue,NEW.active,actor);
  RETURN NEW;
END $$;


--
-- Name: masters_track_test_parameter(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_track_test_parameter() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid := nullif(current_setting('app.user_id',true),'')::uuid; operation text;
BEGIN
  -- Migration/fixture owners maintain their explicit provenance separately.
  IF session_user<>'sampleify_app' THEN RETURN NEW; END IF;
  IF NOT public.app_has_permission('masters.manage') OR actor IS NULL
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Master management permission required' USING ERRCODE='42501';
  END IF;
  IF NEW.save_request_id IS NULL OR NEW.updated_at<>transaction_timestamp() THEN
    RAISE EXCEPTION 'Parameter writes require an actual save request and transaction time' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.revision<>1 OR NOT NEW.active THEN RAISE EXCEPTION 'New parameters start active at revision one' USING ERRCODE='23514'; END IF;
    operation := 'create';
  ELSE
    IF (NEW.organization_id,NEW.id,NEW.created_at,NEW.code) IS DISTINCT FROM (OLD.organization_id,OLD.id,OLD.created_at,OLD.code)
      OR NEW.revision<>OLD.revision+1 OR (NOT OLD.active AND (NEW.active OR NOT EXISTS (
        SELECT 1 FROM public.master_bulk_reviews review
        JOIN public.master_bulk_batches batch ON batch.organization_id=review.organization_id AND batch.id=review.batch_id
        JOIN public.master_bulk_rows row ON row.organization_id=review.organization_id AND row.batch_id=review.batch_id AND row.id=review.row_id AND row.revision=review.input_revision
        WHERE review.organization_id=NEW.organization_id AND review.id=NEW.save_request_id AND review.valid
          AND review.candidate_id=NEW.id AND review.expected_revision=OLD.revision AND review.operation='update_retired' AND batch.resource='test-parameters'
      ))) THEN
      RAISE EXCEPTION 'Parameter writes preserve identity and advance the revision without an unsupported status change' USING ERRCODE='23514';
    END IF;
    operation := CASE WHEN OLD.active AND NOT NEW.active THEN 'retire' ELSE 'update' END;
    IF OLD.active AND NOT NEW.active AND (NEW.name,NEW.description,NEW.master_key,NEW.scheme_abbreviation,NEW.display_order,NEW.laboratory_id,NEW.measurement_unit_id,NEW.default_scale,NEW.uncertainty_configured)
      IS DISTINCT FROM (OLD.name,OLD.description,OLD.master_key,OLD.scheme_abbreviation,OLD.display_order,OLD.laboratory_id,OLD.measurement_unit_id,OLD.default_scale,OLD.uncertainty_configured) THEN
      RAISE EXCEPTION 'Parameter retirement preserves its last settings' USING ERRCODE='23514';
    END IF;
  END IF;
  INSERT INTO public.test_parameter_versions(organization_id,parameter_id,revision,request_id,previous_revision,operation,
    code,name,description,master_key,scheme_abbreviation,display_order,active,laboratory_id,measurement_unit_id,default_scale,has_uncertainty,saved_by)
  VALUES(NEW.organization_id,NEW.id,NEW.revision,NEW.save_request_id,CASE WHEN TG_OP='INSERT' THEN NULL ELSE OLD.revision END,operation,
    NEW.code,NEW.name,NEW.description,NEW.master_key,NEW.scheme_abbreviation,NEW.display_order,NEW.active,NEW.laboratory_id,NEW.measurement_unit_id,NEW.default_scale,NEW.uncertainty_configured,actor);
  INSERT INTO public.test_parameter_version_methods(organization_id,parameter_id,revision,method_id,is_default,method_revision,method_name)
    SELECT NEW.organization_id,NEW.id,NEW.revision,link.method_id,link.is_default,method.revision,method.name
    FROM public.parameter_methods link
    JOIN public.methods_of_analysis method ON method.organization_id=link.organization_id AND method.id=link.method_id
    WHERE link.organization_id=NEW.organization_id AND link.test_parameter_id=NEW.id;
  RETURN NEW;
END $$;


--
-- Name: masters_upload_customer_attachment(uuid, uuid, integer, text, text, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_upload_customer_attachment(target_id uuid, target_field uuid, target_revision integer, file_name text, file_type text, file_content bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=public.organization_module_scope(); actor uuid; prior public.custom_field_attachments; definition public.custom_field_definitions;
BEGIN
  PERFORM public.masters_require_customer_write();
  actor:=nullif(current_setting('app.user_id',true),'')::uuid;
  IF target_id IS NULL OR target_field IS NULL OR target_revision IS NULL OR target_revision<1 OR file_content IS NULL OR octet_length(file_content)>20971520 THEN
    RAISE EXCEPTION 'Invalid Customer attachment' USING ERRCODE='23514',CONSTRAINT='customer_attachment_input';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('custom-field-upload:'||org::text||':'||target_id::text,0));
  SELECT * INTO prior FROM public.custom_field_attachments WHERE organization_id=org AND id=target_id;
  IF FOUND THEN
    IF (prior.field_id,prior.field_revision,prior.original_name,prior.media_type,prior.content,prior.uploaded_by)
      IS DISTINCT FROM (target_field,target_revision,file_name,file_type,file_content,actor)
      OR NOT EXISTS (SELECT 1 FROM public.custom_field_versions WHERE organization_id=org AND field_id=prior.field_id AND revision=prior.field_revision AND associated_with='customer') THEN
      RAISE EXCEPTION 'Attachment request already used' USING ERRCODE='23514',CONSTRAINT='customer_attachment_request_reused';
    END IF;
    RETURN true;
  END IF;
  SELECT * INTO definition FROM public.custom_field_definitions WHERE organization_id=org AND id=target_field;
  IF definition.id IS NULL OR NOT definition.active OR definition.associated_with<>'customer' OR definition.field_type<>'attachment' THEN
    RAISE EXCEPTION 'Customer attachment field was not found' USING ERRCODE='P0002',CONSTRAINT='customer_attachment_field_not_found';
  END IF;
  IF definition.revision<>target_revision THEN RAISE EXCEPTION 'Custom Field changed' USING ERRCODE='23514',CONSTRAINT='customer_attachment_field_changed'; END IF;
  INSERT INTO public.custom_field_attachments(organization_id,id,field_id,field_revision,original_name,media_type,content,byte_length,sha256,uploaded_by)
    VALUES(org,target_id,target_field,target_revision,file_name,file_type,file_content,octet_length(file_content),encode(sha256(file_content),'hex'),actor);
  RETURN false;
END $$;


