--
-- Name: masters_vendor_prior_request(uuid, integer, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_vendor_prior_request(target_vendor uuid, expected_revision integer, request_id uuid, request_fingerprint text, requested_operation text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE org uuid:=public.organization_module_scope(); prior public.vendor_versions;
BEGIN
  PERFORM public.masters_require_vendor_write();
  IF target_vendor IS NULL OR expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 2147483646 OR request_id IS NULL
    OR request_fingerprint IS NULL OR request_fingerprint !~ '^[a-f0-9]{64}$' OR requested_operation IS NULL
    OR requested_operation NOT IN ('create','update','retire') THEN
    RAISE EXCEPTION 'Invalid Vendor command' USING ERRCODE='23514',CONSTRAINT='vendor_command_input';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('vendor-save:'||org::text||':'||request_id::text,0));
  SELECT * INTO prior FROM public.vendor_versions version WHERE version.organization_id=org AND version.request_id=masters_vendor_prior_request.request_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF prior.vendor_id IS DISTINCT FROM target_vendor OR coalesce(prior.previous_revision,0) IS DISTINCT FROM expected_revision
    OR prior.operation IS DISTINCT FROM requested_operation OR prior.request_fingerprint IS DISTINCT FROM request_fingerprint
    OR prior.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Vendor request was already used for another change' USING ERRCODE='23514',CONSTRAINT='vendor_request_reused';
  END IF;
  RETURN prior.revision;
END $_$;


--
-- Name: masters_vendor_scheme_context(boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.masters_vendor_scheme_context(include_vendors boolean, include_samples boolean) RETURNS TABLE("currentYearDigits" text, "nextYearDigits" text, separator text, "currentMonthFormat" text, "nonNablStartNumber" text, "vendorCount" double precision, "sampleCount" double precision)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=public.organization_module_scope();
BEGIN
  IF org IS NULL OR NOT public.app_has_permission('masters.manage') OR NOT public.organization_has_module_access('vendor') THEN
    RAISE EXCEPTION 'Vendor scheme generation requires permission' USING ERRCODE='42501';
  END IF;
  RETURN QUERY SELECT settings.scheme_current_year_digits,settings.scheme_next_year_digits,settings.scheme_separator,
    settings.scheme_month_format,settings.scheme_non_nabl_start_number,
    CASE WHEN include_vendors THEN (SELECT count(*)::double precision FROM public.vendors vendor WHERE vendor.organization_id=org AND NOT vendor.retired) ELSE 0::double precision END,
    CASE WHEN include_samples THEN (SELECT count(*)::double precision FROM public.samples sample WHERE sample.organization_id=org) ELSE 0::double precision END
  FROM public.organizations organization LEFT JOIN public.organization_laboratory_settings settings ON settings.organization_id=organization.id
  WHERE organization.id=org;
END $$;


--
-- Name: nabl_check_head_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nabl_check_head_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.nabl_certifications head JOIN public.nabl_certificate_versions version
    ON version.organization_id=head.organization_id AND version.certification_id=head.id AND version.revision=head.revision
    WHERE head.organization_id=NEW.organization_id AND head.id=NEW.id AND version.active=head.active
      AND version.saved_at=head.updated_at AND version.created_transaction_id=pg_current_xact_id()) THEN
    RAISE EXCEPTION 'Certification changes require their complete current version' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: nabl_check_scope_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nabl_check_scope_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE invalid boolean;
BEGIN
  WITH scoped AS MATERIALIZED (SELECT * FROM public.nabl_scope_rows
    WHERE organization_id=NEW.organization_id AND certification_id=NEW.certification_id AND revision=NEW.revision),
  observations AS (
    SELECT item.parameter_id,expected.kind,expected.quantity AS expected_count,NULL::integer AS position
      FROM scoped item CROSS JOIN LATERAL (VALUES ('product',item.product_count),('method',item.method_count)) expected(kind,quantity)
    UNION ALL
    SELECT parameter_id,'product',0,position FROM public.nabl_scope_products
      WHERE organization_id=NEW.organization_id AND certification_id=NEW.certification_id AND revision=NEW.revision
    UNION ALL
    SELECT parameter_id,'method',0,position FROM public.nabl_scope_methods
      WHERE organization_id=NEW.organization_id AND certification_id=NEW.certification_id AND revision=NEW.revision
  )
  SELECT (SELECT count(*) FROM scoped)<>NEW.scope_count
    OR (NEW.scope_count>0 AND ((SELECT min(position) FROM scoped)<>0 OR (SELECT max(position) FROM scoped)<>NEW.scope_count-1))
    OR EXISTS (SELECT 1 FROM observations GROUP BY parameter_id,kind
      HAVING sum(expected_count)<>count(position)
        OR (count(position)>0 AND (min(position)<>0 OR max(position)<>count(position)-1))) INTO invalid;
  IF invalid THEN RAISE EXCEPTION 'Certification history requires complete ordered scope rows' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END $$;


--
-- Name: nabl_guard_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nabl_guard_file() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.organization_id IS DISTINCT FROM public.nabl_scope_organization()
    OR NEW.uploaded_by IS DISTINCT FROM public.nabl_lock_writer()
    OR NEW.uploaded_at IS DISTINCT FROM transaction_timestamp() OR NEW.created_transaction_id IS DISTINCT FROM pg_current_xact_id()
    OR NOT EXISTS (SELECT 1 FROM public.users WHERE id=NEW.uploaded_by AND username=NEW.uploaded_by_username AND display_name=NEW.uploaded_by_name) THEN
    RAISE EXCEPTION 'File provenance must describe the actual upload' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: nabl_guard_head(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nabl_guard_head() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Certifications are retired with history' USING ERRCODE='55000'; END IF;
  IF NEW.organization_id IS DISTINCT FROM public.nabl_scope_organization() OR NOT public.app_has_permission('compliance.manage')
    OR NEW.updated_at IS DISTINCT FROM transaction_timestamp()
    OR (TG_OP='INSERT' AND (NEW.revision<>1 OR NOT NEW.active OR NEW.created_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid OR NEW.created_at<>transaction_timestamp())) THEN
    RAISE EXCEPTION 'Certification identity requires its actual authoring transaction' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND (NOT OLD.active OR NEW.revision<>OLD.revision+1
    OR (NEW.organization_id,NEW.id,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.organization_id,OLD.id,OLD.created_by,OLD.created_at)) THEN
    RAISE EXCEPTION 'Certification changes preserve identity and advance the active revision' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: nabl_guard_scope_batch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nabl_guard_scope_batch() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM inserted_scopes item LEFT JOIN public.nabl_certificate_versions version
    ON version.organization_id=item.organization_id AND version.certification_id=item.certification_id AND version.revision=item.revision
    WHERE version.created_transaction_id IS DISTINCT FROM pg_current_xact_id()
      OR version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
      OR item.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid) THEN
    RAISE EXCEPTION 'Scope rows belong to the actual new version transaction' USING ERRCODE='23514';
  END IF;
  IF TG_TABLE_NAME='nabl_scope_rows' THEN
    IF EXISTS (SELECT 1 FROM inserted_scopes item JOIN public.test_parameters reference
      ON reference.organization_id=item.organization_id AND reference.id=item.parameter_id
      WHERE (item.parameter_name,item.scheme_abbreviation,item.parameter_revision) IS DISTINCT FROM (reference.name,reference.scheme_abbreviation,reference.revision)) THEN
      RAISE EXCEPTION 'Parameter observations must describe the selected reference' USING ERRCODE='23514';
    END IF;
  ELSIF TG_TABLE_NAME='nabl_scope_products' THEN
    IF EXISTS (SELECT 1 FROM inserted_scopes item JOIN public.products reference
      ON reference.organization_id=item.organization_id AND reference.id=item.product_id
      WHERE (item.product_name,item.product_revision) IS DISTINCT FROM (reference.name,reference.revision)) THEN
      RAISE EXCEPTION 'Product observations must describe the selected reference' USING ERRCODE='23514';
    END IF;
  ELSE
    IF EXISTS (SELECT 1 FROM inserted_scopes item JOIN public.methods_of_analysis reference
      ON reference.organization_id=item.organization_id AND reference.id=item.method_id
      WHERE (item.method_name,item.method_revision) IS DISTINCT FROM (reference.name,reference.revision)) THEN
      RAISE EXCEPTION 'Method observations must describe the selected reference' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: nabl_guard_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nabl_guard_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.organization_id IS DISTINCT FROM public.nabl_scope_organization()
    OR NEW.saved_by IS DISTINCT FROM public.nabl_lock_writer()
    OR NEW.saved_at IS DISTINCT FROM transaction_timestamp() OR NEW.created_transaction_id IS DISTINCT FROM pg_current_xact_id()
    OR NOT EXISTS (SELECT 1 FROM public.nabl_certifications head JOIN public.users actor ON actor.id=NEW.saved_by
      WHERE head.organization_id=NEW.organization_id AND head.id=NEW.certification_id
        AND head.revision=NEW.revision AND head.active=NEW.active AND head.updated_at=NEW.saved_at
        AND actor.username=NEW.saved_by_username AND actor.display_name=NEW.saved_by_name) THEN
    RAISE EXCEPTION 'Version provenance must describe the actual certification save' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: nabl_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nabl_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN RAISE EXCEPTION 'NABL history and original files are immutable' USING ERRCODE='55000'; END $$;


--
-- Name: nabl_lock_writer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nabl_lock_writer() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  IF actor IS NULL OR org IS NULL OR public.nabl_scope_organization() IS DISTINCT FROM org OR NOT public.app_has_permission('compliance.manage') THEN
    RAISE EXCEPTION 'Active compliance management session required' USING ERRCODE='42501',CONSTRAINT='nabl_session_required';
  END IF;
  -- Observations do not modify identity. SHARE also remains compatible with
  -- Method access-history user locks acquired after the method head.
  PERFORM 1 FROM public.users WHERE id=actor FOR SHARE;
  PERFORM 1 FROM public.organizations WHERE id=org FOR SHARE;
  PERFORM 1 FROM public.memberships WHERE organization_id=org AND user_id=actor FOR SHARE;
  PERFORM 1 FROM public.sessions WHERE id=nullif(current_setting('app.session_id',true),'')::uuid FOR SHARE;
  IF public.nabl_scope_organization() IS DISTINCT FROM org OR NOT public.app_has_permission('compliance.manage') THEN
    RAISE EXCEPTION 'Active compliance management session required' USING ERRCODE='42501',CONSTRAINT='nabl_session_required';
  END IF;
  RETURN actor;
END $$;


--
-- Name: nabl_scope_organization(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nabl_scope_organization() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT session.organization_id FROM public.sessions session
  JOIN public.users person ON person.id=session.user_id AND person.active AND NOT person.must_change_password
  JOIN public.credentials credential ON credential.user_id=person.id AND credential.revision=session.credential_revision
  JOIN public.memberships membership ON membership.organization_id=session.organization_id AND membership.user_id=person.id AND membership.active
  JOIN public.organizations organization ON organization.id=session.organization_id AND organization.active
  WHERE session.id=nullif(current_setting('app.session_id',true),'')::uuid
    AND session.user_id=nullif(current_setting('app.user_id',true),'')::uuid
    AND session.organization_id=nullif(current_setting('app.organization_id',true),'')::uuid
    AND session.revoked_at IS NULL AND session.expires_at>clock_timestamp()
    AND (public.app_has_permission('compliance.read') OR public.app_has_permission('compliance.manage'))
$$;


--
-- Name: nabl_upload_file(uuid, text, text, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nabl_upload_file(requested_id uuid, requested_name text, requested_type text, requested_content bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=public.nabl_lock_writer(); org uuid:=public.nabl_scope_organization(); stored public.nabl_files%ROWTYPE;
BEGIN
  IF requested_id IS NULL OR requested_content IS NULL OR octet_length(requested_content)>26214400 THEN
    RAISE EXCEPTION 'Invalid NABL attachment' USING ERRCODE='23514',CONSTRAINT='nabl_invalid_file';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('nabl-file:'||org::text||':'||requested_id::text,0));
  PERFORM public.nabl_lock_writer();
  SELECT * INTO stored FROM public.nabl_files WHERE organization_id=org AND id=requested_id;
  IF FOUND THEN
    IF (stored.uploaded_by,stored.original_name,stored.media_type,stored.content)
      IS DISTINCT FROM (actor,requested_name,requested_type,requested_content) THEN
      RAISE EXCEPTION 'Upload request already used' USING ERRCODE='23514',CONSTRAINT='nabl_file_request_reused';
    END IF;
    RETURN true;
  END IF;
  INSERT INTO public.nabl_files(organization_id,id,original_name,media_type,content,byte_length,sha256,uploaded_by,uploaded_by_username,uploaded_by_name)
    SELECT org,requested_id,requested_name,requested_type,requested_content,octet_length(requested_content),encode(sha256(requested_content),'hex'),actor,username,display_name
      FROM public.users WHERE id=actor;
  RETURN false;
END $$;


--
-- Name: nabl_write_certificate(text, uuid, integer, uuid, date, date, uuid, uuid, uuid[], uuid[], uuid[], uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nabl_write_certificate(requested_operation text, target uuid, expected_revision integer, requested_id uuid, requested_from date, requested_to date, requested_scope_file uuid, requested_certificate_file uuid, requested_parameters uuid[], requested_product_parameters uuid[], requested_products uuid[], requested_method_parameters uuid[], requested_methods uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=public.nabl_lock_writer(); org uuid:=public.nabl_scope_organization();
  head public.nabl_certifications%ROWTYPE; stored public.nabl_certificate_versions%ROWTYPE;
  operation_value text; invalid boolean; parameters uuid[]; product_parameters uuid[]; selected_products uuid[]; method_parameters uuid[]; selected_methods uuid[];
BEGIN
  IF requested_operation IS NULL OR requested_operation NOT IN ('save','retire') OR target IS NULL OR requested_id IS NULL
    OR expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 2147483646
    OR (requested_operation='retire' AND (expected_revision=0 OR requested_from IS NOT NULL OR requested_to IS NOT NULL
      OR requested_scope_file IS NOT NULL OR requested_certificate_file IS NOT NULL OR requested_parameters IS NOT NULL
      OR requested_product_parameters IS NOT NULL OR requested_products IS NOT NULL OR requested_method_parameters IS NOT NULL OR requested_methods IS NOT NULL)) THEN
    RAISE EXCEPTION 'Invalid certification command' USING ERRCODE='23514',CONSTRAINT='nabl_invalid_input';
  END IF;
  operation_value:=CASE WHEN requested_operation='retire' THEN 'retire' WHEN expected_revision=0 THEN 'create' ELSE 'update' END;
  IF requested_operation='save' THEN
    IF requested_from IS NULL OR requested_to IS NULL OR requested_from NOT BETWEEN DATE '0001-01-01' AND DATE '9999-12-31'
      OR requested_to NOT BETWEEN requested_from AND DATE '9999-12-31'
      OR requested_parameters IS NULL OR requested_product_parameters IS NULL OR requested_products IS NULL OR requested_method_parameters IS NULL OR requested_methods IS NULL
      OR coalesce(array_ndims(requested_parameters),1)<>1 OR coalesce(array_lower(requested_parameters,1),1)<>1
      OR coalesce(array_ndims(requested_products),1)<>1 OR coalesce(array_lower(requested_products,1),1)<>1
      OR coalesce(array_ndims(requested_product_parameters),1)<>1 OR coalesce(array_lower(requested_product_parameters,1),1)<>1
      OR coalesce(array_ndims(requested_methods),1)<>1 OR coalesce(array_lower(requested_methods,1),1)<>1
      OR coalesce(array_ndims(requested_method_parameters),1)<>1 OR coalesce(array_lower(requested_method_parameters,1),1)<>1
      OR cardinality(requested_parameters)>2000 OR cardinality(requested_products)<>cardinality(requested_product_parameters)
      OR cardinality(requested_methods)<>cardinality(requested_method_parameters)
      OR array_position(requested_parameters,NULL) IS NOT NULL OR array_position(requested_products,NULL) IS NOT NULL
      OR array_position(requested_methods,NULL) IS NOT NULL OR array_position(requested_product_parameters,NULL) IS NOT NULL
      OR array_position(requested_method_parameters,NULL) IS NOT NULL THEN
      RAISE EXCEPTION 'Invalid certification fields' USING ERRCODE='23514',CONSTRAINT='nabl_invalid_input';
    END IF;
    IF (SELECT count(DISTINCT id) FROM unnest(requested_parameters) id)<>cardinality(requested_parameters)
      OR EXISTS (SELECT 1 FROM unnest(requested_product_parameters,requested_products) item(parameter_id,id)
        GROUP BY parameter_id HAVING count(*)>500 OR count(DISTINCT id)<>count(*) OR NOT parameter_id=ANY(requested_parameters))
      OR EXISTS (SELECT 1 FROM unnest(requested_method_parameters,requested_methods) item(parameter_id,id)
        GROUP BY parameter_id HAVING count(*)>500 OR count(DISTINCT id)<>count(*) OR NOT parameter_id=ANY(requested_parameters)) THEN
      RAISE EXCEPTION 'Invalid or duplicate scope selections' USING ERRCODE='23514',CONSTRAINT='nabl_invalid_input';
    END IF;
    -- Canonical grouping preserves the authored order within each parameter.
    parameters:=requested_parameters;
    SELECT coalesce(array_agg(item.parameter_id ORDER BY array_position(parameters,item.parameter_id),item.position),'{}'::uuid[]),
      coalesce(array_agg(item.id ORDER BY array_position(parameters,item.parameter_id),item.position),'{}'::uuid[])
      INTO product_parameters,selected_products FROM unnest(requested_product_parameters,requested_products) WITH ORDINALITY item(parameter_id,id,position);
    SELECT coalesce(array_agg(item.parameter_id ORDER BY array_position(parameters,item.parameter_id),item.position),'{}'::uuid[]),
      coalesce(array_agg(item.id ORDER BY array_position(parameters,item.parameter_id),item.position),'{}'::uuid[])
      INTO method_parameters,selected_methods FROM unnest(requested_method_parameters,requested_methods) WITH ORDINALITY item(parameter_id,id,position);
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('nabl-request:'||org::text||':'||requested_id::text,0));
  PERFORM pg_advisory_xact_lock(hashtextextended('nabl-certificate:'||org::text||':'||target::text,0));
  PERFORM public.nabl_lock_writer();
  SELECT * INTO stored FROM public.nabl_certificate_versions WHERE organization_id=org AND request_id=requested_id;
  IF FOUND THEN
    IF (stored.certification_id,coalesce(stored.previous_revision,0),stored.operation,stored.saved_by)
      IS DISTINCT FROM (target,expected_revision,operation_value,actor) THEN
      RAISE EXCEPTION 'Save request already used' USING ERRCODE='23514',CONSTRAINT='nabl_request_reused';
    END IF;
    IF requested_operation='save' AND (
      (stored.valid_from,stored.valid_to,stored.scope_file_id,stored.certificate_file_id) IS DISTINCT FROM (requested_from,requested_to,requested_scope_file,requested_certificate_file)
      OR parameters IS DISTINCT FROM ARRAY(SELECT parameter_id FROM public.nabl_scope_rows WHERE organization_id=org AND certification_id=target AND revision=stored.revision ORDER BY position)
      OR product_parameters IS DISTINCT FROM ARRAY(SELECT item.parameter_id FROM public.nabl_scope_products item JOIN public.nabl_scope_rows scope USING(organization_id,certification_id,revision,parameter_id)
        WHERE item.organization_id=org AND item.certification_id=target AND item.revision=stored.revision ORDER BY scope.position,item.position)
      OR selected_products IS DISTINCT FROM ARRAY(SELECT item.product_id FROM public.nabl_scope_products item JOIN public.nabl_scope_rows scope USING(organization_id,certification_id,revision,parameter_id)
        WHERE item.organization_id=org AND item.certification_id=target AND item.revision=stored.revision ORDER BY scope.position,item.position)
      OR method_parameters IS DISTINCT FROM ARRAY(SELECT item.parameter_id FROM public.nabl_scope_methods item JOIN public.nabl_scope_rows scope USING(organization_id,certification_id,revision,parameter_id)
        WHERE item.organization_id=org AND item.certification_id=target AND item.revision=stored.revision ORDER BY scope.position,item.position)
      OR selected_methods IS DISTINCT FROM ARRAY(SELECT item.method_id FROM public.nabl_scope_methods item JOIN public.nabl_scope_rows scope USING(organization_id,certification_id,revision,parameter_id)
        WHERE item.organization_id=org AND item.certification_id=target AND item.revision=stored.revision ORDER BY scope.position,item.position)) THEN
      RAISE EXCEPTION 'Save request already used' USING ERRCODE='23514',CONSTRAINT='nabl_request_reused';
    END IF;
    RETURN stored.revision;
  END IF;
  SELECT * INTO head FROM public.nabl_certifications WHERE organization_id=org AND id=target FOR UPDATE;
  IF NOT FOUND AND expected_revision>0 THEN RAISE EXCEPTION 'Certification not found' USING ERRCODE='23514',CONSTRAINT='nabl_not_found'; END IF;
  IF (head.id IS NOT NULL AND (head.revision<>expected_revision OR NOT head.active)) OR (head.id IS NULL AND expected_revision<>0) THEN
    RAISE EXCEPTION 'Certification changed' USING ERRCODE='23514',CONSTRAINT='nabl_stale';
  END IF;
  IF requested_operation='retire' THEN
    SELECT * INTO stored FROM public.nabl_certificate_versions WHERE organization_id=org AND certification_id=target AND revision=head.revision;
    requested_from:=stored.valid_from; requested_to:=stored.valid_to;
    requested_scope_file:=stored.scope_file_id; requested_certificate_file:=stored.certificate_file_id;
    parameters:=ARRAY(SELECT parameter_id FROM public.nabl_scope_rows WHERE organization_id=org AND certification_id=target AND revision=head.revision ORDER BY position);
    SELECT coalesce(array_agg(item.parameter_id ORDER BY scope.position,item.position),'{}'::uuid[]),coalesce(array_agg(item.product_id ORDER BY scope.position,item.position),'{}'::uuid[])
      INTO product_parameters,selected_products FROM public.nabl_scope_products item JOIN public.nabl_scope_rows scope USING(organization_id,certification_id,revision,parameter_id)
      WHERE item.organization_id=org AND item.certification_id=target AND item.revision=head.revision;
    SELECT coalesce(array_agg(item.parameter_id ORDER BY scope.position,item.position),'{}'::uuid[]),coalesce(array_agg(item.method_id ORDER BY scope.position,item.position),'{}'::uuid[])
      INTO method_parameters,selected_methods FROM public.nabl_scope_methods item JOIN public.nabl_scope_rows scope USING(organization_id,certification_id,revision,parameter_id)
      WHERE item.organization_id=org AND item.certification_id=target AND item.revision=head.revision;
  END IF;
  PERFORM 1 FROM public.test_parameters WHERE organization_id=org AND id=ANY(parameters) ORDER BY id FOR SHARE;
  IF (SELECT count(*) FROM public.test_parameters WHERE organization_id=org AND id=ANY(parameters))<>cardinality(parameters) THEN
    RAISE EXCEPTION 'Parameter unavailable' USING ERRCODE='23514',CONSTRAINT='nabl_invalid_reference';
  END IF;
  PERFORM 1 FROM public.products WHERE organization_id=org AND id=ANY(selected_products) ORDER BY id FOR SHARE;
  PERFORM 1 FROM public.methods_of_analysis WHERE organization_id=org AND id=ANY(selected_methods) ORDER BY id FOR SHARE;
  IF EXISTS (SELECT id FROM unnest(selected_products) id EXCEPT SELECT id FROM public.products WHERE organization_id=org AND id=ANY(selected_products))
    OR EXISTS (SELECT id FROM unnest(selected_methods) id EXCEPT SELECT id FROM public.methods_of_analysis WHERE organization_id=org AND id=ANY(selected_methods))
    OR (requested_scope_file IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.nabl_files WHERE organization_id=org AND id=requested_scope_file))
    OR (requested_certificate_file IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.nabl_files WHERE organization_id=org AND id=requested_certificate_file)) THEN
    RAISE EXCEPTION 'Scope or file reference unavailable' USING ERRCODE='23514',CONSTRAINT='nabl_invalid_reference';
  END IF;
  IF requested_operation='save' THEN
    WITH available AS MATERIALIZED (SELECT test_parameter_id,product_id,method_id FROM public.decision_rules
      WHERE organization_id=org AND active AND test_parameter_id=ANY(parameters)
        AND (product_id=ANY(ARRAY(SELECT DISTINCT id FROM unnest(selected_products) id))
          OR method_id=ANY(ARRAY(SELECT DISTINCT id FROM unnest(selected_methods) id))) ORDER BY id FOR SHARE)
    SELECT EXISTS (SELECT item.parameter_id,item.id FROM unnest(product_parameters,selected_products) item(parameter_id,id)
        EXCEPT SELECT test_parameter_id,product_id FROM available)
      OR EXISTS (SELECT item.parameter_id,item.id FROM unnest(method_parameters,selected_methods) item(parameter_id,id)
        EXCEPT SELECT test_parameter_id,method_id FROM available) INTO invalid;
    IF invalid THEN RAISE EXCEPTION 'Selections require an active Decision Rule for this parameter' USING ERRCODE='23514',CONSTRAINT='nabl_invalid_scope'; END IF;
  END IF;
  PERFORM public.nabl_lock_writer();
  IF expected_revision=0 THEN
    INSERT INTO public.nabl_certifications(organization_id,id,created_by) VALUES(org,target,actor);
  ELSE
    UPDATE public.nabl_certifications SET revision=expected_revision+1,active=requested_operation='save',updated_at=transaction_timestamp()
      WHERE organization_id=org AND id=target;
  END IF;
  INSERT INTO public.nabl_certificate_versions(organization_id,certification_id,revision,previous_revision,request_id,operation,valid_from,valid_to,
    scope_file_id,certificate_file_id,scope_count,active,saved_by,saved_by_username,saved_by_name)
    SELECT org,target,expected_revision+1,nullif(expected_revision,0),requested_id,operation_value,requested_from,requested_to,
      requested_scope_file,requested_certificate_file,cardinality(parameters),requested_operation='save',actor,username,display_name FROM public.users WHERE id=actor;
  WITH product_counts AS (SELECT parameter_id,count(*) AS count FROM unnest(product_parameters) parameter_id GROUP BY parameter_id),
    method_counts AS (SELECT parameter_id,count(*) AS count FROM unnest(method_parameters) parameter_id GROUP BY parameter_id)
  INSERT INTO public.nabl_scope_rows(organization_id,certification_id,revision,parameter_id,position,parameter_name,scheme_abbreviation,parameter_revision,product_count,method_count)
    SELECT org,target,expected_revision+1,item.id,item.position-1,reference.name,reference.scheme_abbreviation,reference.revision,coalesce(product.count,0),coalesce(method.count,0)
      FROM unnest(parameters) WITH ORDINALITY item(id,position)
      JOIN public.test_parameters reference ON reference.organization_id=org AND reference.id=item.id
      LEFT JOIN product_counts product ON product.parameter_id=item.id LEFT JOIN method_counts method ON method.parameter_id=item.id;
  INSERT INTO public.nabl_scope_products(organization_id,certification_id,revision,parameter_id,product_id,position,product_name,product_revision)
    SELECT org,target,expected_revision+1,item.parameter_id,item.id,row_number() OVER(PARTITION BY item.parameter_id ORDER BY item.position)-1,reference.name,reference.revision
      FROM unnest(product_parameters,selected_products) WITH ORDINALITY item(parameter_id,id,position)
      JOIN public.products reference ON reference.organization_id=org AND reference.id=item.id;
  INSERT INTO public.nabl_scope_methods(organization_id,certification_id,revision,parameter_id,method_id,position,method_name,method_revision)
    SELECT org,target,expected_revision+1,item.parameter_id,item.id,row_number() OVER(PARTITION BY item.parameter_id ORDER BY item.position)-1,reference.name,reference.revision
      FROM unnest(method_parameters,selected_methods) WITH ORDINALITY item(parameter_id,id,position)
      JOIN public.methods_of_analysis reference ON reference.organization_id=org AND reference.id=item.id;
  RETURN expected_revision+1;
END $$;


--
-- Name: organization_check_module_access_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.organization_check_module_access_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF (SELECT array_agg(module_key ORDER BY module_key) FROM public.organization_module_access_modules
      WHERE organization_id=NEW.organization_id AND revision=NEW.revision) IS DISTINCT FROM
      (CASE NEW.module_count
        WHEN 2 THEN ARRAY['customer','vendor']::text[]
        WHEN 3 THEN ARRAY['customer','instrument','vendor']::text[]
        WHEN 4 THEN ARRAY['customer','instrument','service_agreements','vendor']::text[]
        ELSE ARRAY['customer','instrument','inventory','service_agreements','vendor']::text[] END) THEN
    RAISE EXCEPTION 'Capture the complete configured module set' USING ERRCODE='23514',CONSTRAINT='module_access_complete';
  END IF;
  IF EXISTS (
    WITH facts AS (
      SELECT module_key,'role'::text AS kind,role_count AS expected,NULL::integer AS position
        FROM public.organization_module_access_modules WHERE organization_id=NEW.organization_id AND revision=NEW.revision
      UNION ALL SELECT module_key,'user',user_count,NULL FROM public.organization_module_access_modules
        WHERE organization_id=NEW.organization_id AND revision=NEW.revision
      UNION ALL SELECT module_key,'role',NULL,position FROM public.organization_module_access_roles
        WHERE organization_id=NEW.organization_id AND revision=NEW.revision
      UNION ALL SELECT module_key,'user',NULL,position FROM public.organization_module_access_users
        WHERE organization_id=NEW.organization_id AND revision=NEW.revision
    ) SELECT 1 FROM facts GROUP BY module_key,kind
      HAVING max(expected) IS DISTINCT FROM count(position)
        OR (count(position)>0 AND (min(position)<>0 OR max(position)<>count(position)-1))
  ) THEN RAISE EXCEPTION 'Module assignments require complete ordered sets' USING ERRCODE='23514',CONSTRAINT='module_access_complete'; END IF;
  RETURN NULL;
END $$;


--
-- Name: organization_guard_module_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.organization_guard_module_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN RAISE EXCEPTION 'Module access history is immutable' USING ERRCODE='55000'; END $$;


--
-- Name: organization_has_module_access(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.organization_has_module_access(requested_module text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.organization_module_access_modules module
    WHERE module.organization_id=public.organization_module_scope() AND module.module_key=requested_module AND module.enabled
      AND module.revision=(SELECT max(version.revision) FROM public.organization_module_access_versions version
        JOIN public.organization_laboratory_settings settings ON settings.organization_id=version.organization_id AND settings.revision>=version.revision
        WHERE version.organization_id=module.organization_id)
      AND (
        EXISTS (SELECT 1 FROM public.organization_module_access_users selection
          WHERE selection.organization_id=module.organization_id AND selection.revision=module.revision
            AND selection.module_key=module.module_key AND selection.user_id=nullif(current_setting('app.user_id',true),'')::uuid)
        OR EXISTS (SELECT 1 FROM public.organization_module_access_roles selection
          JOIN public.user_profiles profile ON profile.organization_id=selection.organization_id AND profile.default_role_id=selection.role_id
          JOIN public.membership_roles assignment ON assignment.organization_id=profile.organization_id AND assignment.user_id=profile.user_id AND assignment.role_id=profile.default_role_id
          JOIN public.roles role ON role.organization_id=selection.organization_id AND role.id=selection.role_id AND role.active
          WHERE selection.organization_id=module.organization_id AND selection.revision=module.revision
            AND selection.module_key=module.module_key AND profile.user_id=nullif(current_setting('app.user_id',true),'')::uuid)
      )
  )
$$;


--
-- Name: organization_lock_settings_writer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.organization_lock_settings_writer() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  PERFORM 1 FROM public.users WHERE id=actor FOR NO KEY UPDATE;
  PERFORM 1 FROM public.organizations WHERE id=org FOR NO KEY UPDATE;
  PERFORM 1 FROM public.memberships WHERE organization_id=org AND user_id=actor FOR SHARE;
  PERFORM 1 FROM public.sessions WHERE id=nullif(current_setting('app.session_id',true),'')::uuid FOR SHARE;
  IF NOT EXISTS (
    SELECT 1 FROM public.sessions session
    JOIN public.users person ON person.id=session.user_id AND person.active AND NOT person.must_change_password
    JOIN public.credentials credential ON credential.user_id=person.id AND credential.revision=session.credential_revision
    JOIN public.memberships membership ON membership.organization_id=session.organization_id AND membership.user_id=person.id AND membership.active
    JOIN public.organizations organization ON organization.id=session.organization_id AND organization.active
    WHERE session.id=nullif(current_setting('app.session_id',true),'')::uuid AND session.user_id=actor AND session.organization_id=org
      AND session.revoked_at IS NULL AND session.expires_at>clock_timestamp()
  ) OR NOT public.app_has_permission('settings.manage') THEN
    RAISE EXCEPTION 'Active settings management session required' USING ERRCODE='42501',CONSTRAINT='organization_settings_session_required';
  END IF;
  RETURN actor;
END $$;


--
-- Name: organization_module_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.organization_module_scope() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT session.organization_id FROM public.sessions session
  JOIN public.users person ON person.id=session.user_id AND person.active AND NOT person.must_change_password
  JOIN public.credentials credential ON credential.user_id=person.id AND credential.revision=session.credential_revision
  JOIN public.memberships membership ON membership.organization_id=session.organization_id AND membership.user_id=person.id AND membership.active
  JOIN public.organizations organization ON organization.id=session.organization_id AND organization.active
  WHERE session.id=nullif(current_setting('app.session_id',true),'')::uuid
    AND session.user_id=nullif(current_setting('app.user_id',true),'')::uuid
    AND session.organization_id=nullif(current_setting('app.organization_id',true),'')::uuid
    AND session.revoked_at IS NULL AND session.expires_at>clock_timestamp()
$$;


--
-- Name: organization_require_module_access(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.organization_require_module_access(requested_module text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=public.organization_module_scope(); actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
BEGIN
  IF current_setting('transaction_isolation') IN ('repeatable read','serializable') THEN
    RAISE EXCEPTION 'Module-authorized writes require statement snapshots'
      USING ERRCODE='25001',CONSTRAINT='module_access_write_isolation';
  END IF;
  IF org IS NULL THEN
    RAISE EXCEPTION 'Configured module access required' USING ERRCODE='42501',CONSTRAINT='organization_module_access_required';
  END IF;
  PERFORM 1 FROM public.users WHERE id=actor FOR SHARE;
  PERFORM 1 FROM public.organizations WHERE id=org FOR SHARE;
  PERFORM 1 FROM public.memberships WHERE organization_id=org AND user_id=actor FOR SHARE;
  PERFORM 1 FROM public.sessions WHERE id=nullif(current_setting('app.session_id',true),'')::uuid FOR SHARE;
  IF org IS NULL OR public.organization_module_scope() IS DISTINCT FROM org OR NOT public.organization_has_module_access(requested_module) THEN
    RAISE EXCEPTION 'Configured module access required' USING ERRCODE='42501',CONSTRAINT='organization_module_access_required';
  END IF;
  RETURN actor;
END $$;


--
-- Name: organization_save_module_access(integer, text[], boolean[], text[], uuid[], text[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.organization_save_module_access(p_revision integer, p_modules text[], p_enabled boolean[], p_role_modules text[], p_role_ids uuid[], p_user_modules text[], p_user_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=public.organization_lock_settings_writer(); org uuid:=public.organization_module_scope();
  head public.organization_laboratory_settings; previous_module public.organization_module_access_modules; omitted_module text;
BEGIN
  SELECT * INTO head FROM public.organization_laboratory_settings WHERE organization_id=org FOR UPDATE;
  IF head.organization_id IS NULL OR head.revision IS DISTINCT FROM p_revision
    OR head.updated_by IS DISTINCT FROM actor OR head.updated_at IS DISTINCT FROM transaction_timestamp() THEN
    RAISE EXCEPTION 'Module access requires this transaction''s settings save' USING ERRCODE='23514',CONSTRAINT='module_access_current_settings';
  END IF;
  IF (p_modules IS DISTINCT FROM ARRAY['customer','vendor']::text[] AND p_modules IS DISTINCT FROM ARRAY['customer','vendor','instrument']::text[]
    AND p_modules IS DISTINCT FROM ARRAY['customer','vendor','instrument','service_agreements']::text[]
    AND p_modules IS DISTINCT FROM ARRAY['customer','vendor','instrument','service_agreements','inventory']::text[])
    OR cardinality(p_enabled) IS DISTINCT FROM cardinality(p_modules) OR array_ndims(p_enabled) IS DISTINCT FROM 1 OR array_position(p_enabled,NULL) IS NOT NULL
    OR cardinality(p_role_ids) IS NULL OR cardinality(p_role_ids)>2000 OR cardinality(p_role_modules) IS DISTINCT FROM cardinality(p_role_ids)
    OR cardinality(p_user_ids) IS NULL OR cardinality(p_user_ids)>2000 OR cardinality(p_user_modules) IS DISTINCT FROM cardinality(p_user_ids)
    OR (cardinality(p_role_ids)>0 AND (array_ndims(p_role_ids)<>1 OR array_ndims(p_role_modules)<>1))
    OR (cardinality(p_user_ids)>0 AND (array_ndims(p_user_ids)<>1 OR array_ndims(p_user_modules)<>1))
    OR EXISTS (SELECT 1 FROM unnest(p_role_modules,p_role_ids) entry(module_key,id) WHERE module_key IS NULL OR NOT (module_key=ANY(p_modules)) OR id IS NULL)
    OR EXISTS (SELECT 1 FROM unnest(p_user_modules,p_user_ids) entry(module_key,id) WHERE module_key IS NULL OR NOT (module_key=ANY(p_modules)) OR id IS NULL) THEN
    RAISE EXCEPTION 'Module access arrays must be aligned and bounded' USING ERRCODE='23514',CONSTRAINT='module_access_input';
  END IF;
  -- Preserve modules absent from an older caller's complete supported prefix.
  -- The settings writer holds the organization and current settings head locks.
  FOREACH omitted_module IN ARRAY ARRAY['instrument','service_agreements','inventory'] LOOP
    IF omitted_module=ANY(p_modules) THEN CONTINUE; END IF;
    SELECT * INTO previous_module FROM public.organization_module_access_modules module
      WHERE module.organization_id=org AND module.module_key=omitted_module
        AND module.revision=(SELECT max(version.revision) FROM public.organization_module_access_versions version
          WHERE version.organization_id=org AND version.revision<p_revision);
    p_modules:=array_append(p_modules,omitted_module);
    p_enabled:=array_append(p_enabled,coalesce(previous_module.enabled,false));
    IF previous_module.module_key IS NOT NULL THEN
      SELECT p_role_modules||coalesce(array_agg(module_key ORDER BY position),ARRAY[]::text[]),
        p_role_ids||coalesce(array_agg(role_id ORDER BY position),ARRAY[]::uuid[])
        INTO p_role_modules,p_role_ids FROM public.organization_module_access_roles
        WHERE organization_id=org AND revision=previous_module.revision AND module_key=omitted_module;
      SELECT p_user_modules||coalesce(array_agg(module_key ORDER BY position),ARRAY[]::text[]),
        p_user_ids||coalesce(array_agg(user_id ORDER BY position),ARRAY[]::uuid[])
        INTO p_user_modules,p_user_ids FROM public.organization_module_access_users
        WHERE organization_id=org AND revision=previous_module.revision AND module_key=omitted_module;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM unnest(p_role_ids) selection(id) WHERE NOT EXISTS (
      SELECT 1 FROM public.roles role WHERE role.organization_id=org AND role.id=selection.id))
    OR EXISTS (SELECT 1 FROM unnest(p_user_ids) selection(id) WHERE NOT EXISTS (
      SELECT 1 FROM public.memberships membership WHERE membership.organization_id=org AND membership.user_id=selection.id)) THEN
    RAISE EXCEPTION 'Module assignments require same-organization references' USING ERRCODE='23514',CONSTRAINT='module_access_reference';
  END IF;
  INSERT INTO public.organization_module_access_versions(organization_id,revision,module_count,saved_by) VALUES(org,p_revision,5,actor);
  INSERT INTO public.organization_module_access_modules(organization_id,revision,module_key,enabled,role_count,user_count)
    SELECT org,p_revision,module.key,module.enabled,
      (SELECT count(*) FROM unnest(p_role_modules) selection(key) WHERE selection.key=module.key),
      (SELECT count(*) FROM unnest(p_user_modules) selection(key) WHERE selection.key=module.key)
    FROM unnest(p_modules,p_enabled) module(key,enabled);
  INSERT INTO public.organization_module_access_roles(organization_id,revision,module_key,role_id,position,role_name,role_active)
    SELECT org,p_revision,selection.module_key,selection.id,
      row_number() OVER (PARTITION BY selection.module_key ORDER BY selection.ordinality)-1,role.name,role.active
    FROM unnest(p_role_modules,p_role_ids) WITH ORDINALITY selection(module_key,id,ordinality)
    JOIN public.roles role ON role.organization_id=org AND role.id=selection.id;
  -- Membership FKs preserve the selected identities. Nonlocking label reads avoid
  -- reversing the user-profile writer's user-before-organization lock order.
  INSERT INTO public.organization_module_access_users(organization_id,revision,module_key,user_id,position,user_name,user_username,user_active)
    SELECT org,p_revision,selection.module_key,selection.id,
      row_number() OVER (PARTITION BY selection.module_key ORDER BY selection.ordinality)-1,
      coalesce(nullif(person.display_name,''),nullif(person.email,''),person.id::text),person.username,person.active AND membership.active
    FROM unnest(p_user_modules,p_user_ids) WITH ORDINALITY selection(module_key,id,ordinality)
    JOIN public.memberships membership ON membership.organization_id=org AND membership.user_id=selection.id
    JOIN public.users person ON person.id=membership.user_id;
END $$;


--
-- Name: platform_create_organization(text, text, text, text, text, text[], text[], text[], text, text, date, date, text, text, text, text, text, text, text, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_create_organization(p_name text, p_admin_username text, p_admin_email text, p_admin_display_name text, p_admin_password_hash text, p_permission_codes text[], p_permission_descriptions text[], p_capability_keys text[], p_domain text, p_status text, p_active_from_date date, p_active_till_date date, p_account_type text, p_purchase_order_number text, p_address text, p_contact_person text, p_contact_phone text, p_project_manager text, p_sales_person text, p_pricing_plan text, p_subscription_cost numeric, p_custom_development_cost numeric) RETURNS TABLE(organization_id uuid, admin_user_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org_id uuid; admin_id uuid; role_id uuid; permission_count integer:=cardinality(p_permission_codes);
  code_base text; candidate_code text; suffix integer:=0;
BEGIN
  IF NOT public.auth_is_platform_administrator() THEN
    RAISE EXCEPTION 'Platform administrator access is required' USING ERRCODE='42501',CONSTRAINT='platform_administrator_required';
  END IF;
  IF length(trim(p_name)) NOT BETWEEN 1 AND 200
    OR length(trim(p_admin_username)) NOT BETWEEN 1 AND 100 OR length(trim(p_admin_email)) NOT BETWEEN 1 AND 320
    OR length(trim(p_admin_display_name)) NOT BETWEEN 1 AND 200 OR length(p_admin_password_hash)=0
    OR cardinality(p_permission_descriptions) IS DISTINCT FROM permission_count OR cardinality(p_capability_keys) IS NULL THEN
    RAISE EXCEPTION 'Organization and administrator fields are invalid' USING ERRCODE='23514',CONSTRAINT='platform_organization_values';
  END IF;
  -- The organization code is never user-facing (matches PERN) — derive it from the
  -- domain or name, resolving collisions under an advisory lock the way PERN's own
  -- resolveOrganizationCode does, just server-side instead of at the API layer.
  PERFORM pg_advisory_xact_lock(hashtext('sampleify_organization_code'));
  code_base:=upper(regexp_replace(coalesce(nullif(trim(p_domain),''),p_name,'ORGANIZATION'),'[^A-Za-z0-9]+','-','g'));
  code_base:=trim(both '-' from code_base);
  IF code_base='' THEN code_base:='ORGANIZATION'; END IF;
  code_base:=left(code_base,64);
  LOOP
    candidate_code:=CASE WHEN suffix=0 THEN code_base ELSE left(code_base,64-length('-'||suffix::text))||'-'||suffix::text END;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.organizations WHERE lower(code)=lower(candidate_code));
    suffix:=suffix+1;
    IF suffix>1000 THEN RAISE EXCEPTION 'Could not derive a unique organization code' USING ERRCODE='23514',CONSTRAINT='platform_organization_values'; END IF;
  END LOOP;
  INSERT INTO public.organizations(code,name,active,domain,status,active_from_date,active_till_date,account_type,purchase_order_number,
      address,contact_person,contact_phone,project_manager,sales_person,pricing_plan,subscription_cost,custom_development_cost)
    VALUES(candidate_code,p_name,p_status='active',p_domain,p_status,p_active_from_date,p_active_till_date,p_account_type,p_purchase_order_number,
      p_address,p_contact_person,p_contact_phone,p_project_manager,p_sales_person,p_pricing_plan,p_subscription_cost,p_custom_development_cost)
    RETURNING id INTO org_id;
  INSERT INTO public.users(username,email,display_name,must_change_password) VALUES(p_admin_username,p_admin_email,p_admin_display_name,true) RETURNING id INTO admin_id;
  INSERT INTO public.credentials(user_id,password_hash) VALUES(admin_id,p_admin_password_hash);
  INSERT INTO public.memberships(organization_id,user_id,is_default) VALUES(org_id,admin_id,true);
  INSERT INTO public.roles(organization_id,name,description,protected) VALUES(org_id,'System Administrator','Full organization administration.',true) RETURNING id INTO role_id;
  INSERT INTO public.membership_roles(organization_id,user_id,role_id) VALUES(org_id,admin_id,role_id);
  INSERT INTO public.role_capabilities(organization_id,role_id,capability_key)
    SELECT org_id,role_id,item.key FROM unnest(p_capability_keys) item(key);
  INSERT INTO public.permissions(code,description)
    SELECT perm.code,perm.description FROM unnest(p_permission_codes,p_permission_descriptions) AS perm(code,description)
    ON CONFLICT DO NOTHING;
  INSERT INTO public.role_permissions(organization_id,role_id,permission_code)
    SELECT org_id,role_id,item.code FROM unnest(p_permission_codes) item(code);
  RETURN QUERY SELECT org_id,admin_id;
END $$;


--
-- Name: platform_create_seed_session(uuid, uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_create_seed_session(actor_organization uuid, actor_user uuid, requested_organization uuid, requested_token_hash text, requested_csrf_hash text, requested_user uuid DEFAULT NULL::uuid) RETURNS TABLE(user_id uuid, expires_at timestamp with time zone, restore_password_change boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE chosen uuid; credential public.credentials%ROWTYPE; expiry timestamptz; had_flag boolean;
BEGIN
  PERFORM 1 FROM public.platform_administrators pa
  JOIN public.memberships m ON m.organization_id = pa.organization_id AND m.user_id = pa.user_id AND m.active
  JOIN public.users u ON u.id = pa.user_id AND u.active
  WHERE pa.organization_id = actor_organization AND pa.user_id = actor_user;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'platform administrator access is required'
      USING ERRCODE = 'insufficient_privilege', CONSTRAINT = 'platform_administrator_required';
  END IF;

  IF requested_user IS NULL THEN
    SELECT m.user_id INTO chosen
    FROM public.memberships m
    JOIN public.users u ON u.id = m.user_id AND u.active
    JOIN public.organizations o ON o.id = m.organization_id AND o.active
    WHERE m.organization_id = requested_organization AND m.active
    ORDER BY m.is_default DESC, u.created_at, u.id
    LIMIT 1;
  ELSE
    -- Scoped deliberately: a platform administrator may seed as a member of the
    -- organization being seeded, and as nobody else.
    SELECT m.user_id INTO chosen
    FROM public.memberships m
    JOIN public.users u ON u.id = m.user_id AND u.active
    JOIN public.organizations o ON o.id = m.organization_id AND o.active
    WHERE m.organization_id = requested_organization AND m.active AND m.user_id = requested_user;
  END IF;
  IF chosen IS NULL THEN RETURN; END IF;

  SELECT * INTO credential FROM public.credentials WHERE credentials.user_id = chosen FOR UPDATE;
  IF credential.revision IS NULL THEN RETURN; END IF;

  -- Capture the flag before lifting it so it can be put back exactly as it was.
  SELECT u.must_change_password INTO had_flag FROM public.users u WHERE u.id = chosen FOR UPDATE;
  UPDATE public.users SET must_change_password = false WHERE id = chosen;

  expiry := now() + interval '30 minutes';
  INSERT INTO public.sessions (organization_id, user_id, token_hash, csrf_hash, credential_revision, expires_at)
    VALUES (requested_organization, chosen, requested_token_hash, requested_csrf_hash, credential.revision, expiry);
  INSERT INTO public.account_events (user_id, organization_id, kind)
    VALUES (chosen, requested_organization, 'sign_in');

  RETURN QUERY SELECT chosen, expiry, had_flag;
END $$;


--
-- Name: platform_end_seed_session(uuid, uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_end_seed_session(actor_organization uuid, actor_user uuid, seeded_user uuid, requested_token_hash text, restore_password_change boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  PERFORM 1 FROM public.platform_administrators pa
  WHERE pa.organization_id = actor_organization AND pa.user_id = actor_user;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'platform administrator access is required'
      USING ERRCODE = 'insufficient_privilege', CONSTRAINT = 'platform_administrator_required';
  END IF;

  UPDATE public.sessions SET revoked_at = now()
    WHERE token_hash = requested_token_hash AND revoked_at IS NULL;
  IF restore_password_change THEN
    UPDATE public.users SET must_change_password = true WHERE id = seeded_user;
  END IF;
END $$;


--
-- Name: platform_organization_seed_counts(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_organization_seed_counts(actor_organization uuid, actor_user uuid, requested_organization uuid) RETURNS TABLE(members integer, laboratories integer, customers integer, vendors integer, products integer, methods integer, test_parameters integer, templates integer, samples integer, instruments integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  PERFORM 1 FROM public.platform_administrators pa
  WHERE pa.organization_id = actor_organization AND pa.user_id = actor_user;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'platform administrator access is required'
      USING ERRCODE = 'insufficient_privilege', CONSTRAINT = 'platform_administrator_required';
  END IF;

  RETURN QUERY SELECT
    (SELECT count(*)::integer FROM public.memberships WHERE organization_id = requested_organization),
    (SELECT count(*)::integer FROM public.laboratories WHERE organization_id = requested_organization),
    (SELECT count(*)::integer FROM public.customers WHERE organization_id = requested_organization),
    (SELECT count(*)::integer FROM public.vendors WHERE organization_id = requested_organization),
    (SELECT count(*)::integer FROM public.products WHERE organization_id = requested_organization),
    (SELECT count(*)::integer FROM public.methods_of_analysis WHERE organization_id = requested_organization),
    (SELECT count(*)::integer FROM public.test_parameters WHERE organization_id = requested_organization),
    (SELECT count(*)::integer FROM public.templates WHERE organization_id = requested_organization),
    (SELECT count(*)::integer FROM public.samples WHERE organization_id = requested_organization),
    (SELECT count(*)::integer FROM public.instruments WHERE organization_id = requested_organization);
END $$;


--
-- Name: platform_reset_organization_data(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_reset_organization_data(actor_organization uuid, actor_user uuid, target_organization uuid) RETURNS TABLE(passes integer, rows_deleted bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  -- Cleared wholesale; everything else org-scoped is discovered.
  preserved constant text[] := ARRAY['seed_runs', 'seed_run_steps', 'platform_administrators',
    'memberships', 'membership_roles', 'roles', 'role_permissions', 'sessions', 'account_events'];
  target_table text;
  deleted bigint;
  still_present boolean;
  pass_deleted bigint;
  total bigint := 0;
  pass integer := 0;
  leftovers text;
BEGIN
  PERFORM 1 FROM public.platform_administrators pa
  JOIN public.memberships m ON m.organization_id = pa.organization_id AND m.user_id = pa.user_id AND m.active
  JOIN public.users u ON u.id = pa.user_id AND u.active
  WHERE pa.organization_id = actor_organization AND pa.user_id = actor_user;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'platform administrator access is required'
      USING ERRCODE = 'insufficient_privilege', CONSTRAINT = 'platform_administrator_required';
  END IF;

  -- An organization that administers the platform is never resettable: doing so
  -- would delete the platform administrators' own working data.
  IF EXISTS (SELECT 1 FROM public.platform_administrators WHERE organization_id = target_organization) THEN
    RAISE EXCEPTION 'a platform administrator organization cannot be reset'
      USING ERRCODE = 'insufficient_privilege', CONSTRAINT = 'platform_organization_protected';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = target_organization) THEN
    RAISE EXCEPTION 'organization was not found' USING ERRCODE = 'no_data_found', CONSTRAINT = 'platform_organization_not_found';
  END IF;

  -- Transaction-local: other sessions keep every guard and constraint.
  BEGIN
    SET LOCAL session_replication_role = replica;
  EXCEPTION WHEN insufficient_privilege THEN
    RAISE EXCEPTION 'resetting an organization requires the migration role to own the schema guards'
      USING ERRCODE = 'insufficient_privilege', CONSTRAINT = 'platform_reset_not_permitted';
  END;

  CREATE TEMP TABLE preserved_users ON COMMIT DROP AS
    SELECT DISTINCT m.user_id
    FROM public.memberships m
    JOIN public.membership_roles mr ON mr.organization_id = m.organization_id AND mr.user_id = m.user_id
    JOIN public.roles r ON r.organization_id = mr.organization_id AND r.id = mr.role_id AND r.protected
    WHERE m.organization_id = target_organization;

  CREATE TEMP TABLE clearable_tables ON COMMIT DROP AS
    SELECT c.table_name::text AS name
    FROM information_schema.columns c
    JOIN information_schema.tables t
      ON t.table_schema = c.table_schema AND t.table_name = c.table_name AND t.table_type = 'BASE TABLE'
    WHERE c.table_schema = 'public' AND c.column_name = 'organization_id'
      AND NOT (c.table_name = ANY (preserved));

  LOOP
    pass := pass + 1;
    EXIT WHEN pass > 60;
    pass_deleted := 0;
    FOR target_table IN SELECT name FROM clearable_tables LOOP
      BEGIN
        EXECUTE format('DELETE FROM public.%I WHERE organization_id = $1', target_table) USING target_organization;
        GET DIAGNOSTICS deleted = ROW_COUNT;
        pass_deleted := pass_deleted + deleted;
        -- A table that is already empty need not be visited again.
        IF deleted = 0 THEN
          EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.%I WHERE organization_id = $1)', target_table)
            INTO STRICT still_present USING target_organization;
          IF NOT still_present THEN DELETE FROM clearable_tables WHERE name = target_table; END IF;
        END IF;
      EXCEPTION WHEN foreign_key_violation OR restrict_violation THEN
        -- Something still referencing these rows has yet to be cleared; a later
        -- pass reaches this table once its dependants are gone.
        NULL;
      END;
    END LOOP;
    total := total + pass_deleted;
    EXIT WHEN pass_deleted = 0;
  END LOOP;

  -- Identity is cleared last and only for users this organization introduced.
  DELETE FROM public.sessions s WHERE s.organization_id = target_organization
    AND s.user_id NOT IN (SELECT user_id FROM preserved_users);
  DELETE FROM public.account_events e WHERE e.organization_id = target_organization
    AND e.user_id NOT IN (SELECT user_id FROM preserved_users);
  DELETE FROM public.membership_roles mr WHERE mr.organization_id = target_organization
    AND mr.user_id NOT IN (SELECT user_id FROM preserved_users);
  DELETE FROM public.memberships m WHERE m.organization_id = target_organization
    AND m.user_id NOT IN (SELECT user_id FROM preserved_users);
  DELETE FROM public.role_permissions rp WHERE rp.organization_id = target_organization
    AND rp.role_id IN (SELECT id FROM public.roles WHERE organization_id = target_organization AND NOT protected);
  DELETE FROM public.roles r WHERE r.organization_id = target_organization AND NOT r.protected;

  -- A user whose only membership was this organization's has nothing left to
  -- belong to; one who is also a member elsewhere keeps their account.
  CREATE TEMP TABLE orphaned_users ON COMMIT DROP AS
    SELECT u.id FROM public.users u
    WHERE NOT EXISTS (SELECT 1 FROM public.memberships m WHERE m.user_id = u.id)
      AND NOT EXISTS (SELECT 1 FROM public.platform_administrators pa WHERE pa.user_id = u.id);
  DELETE FROM public.sessions WHERE user_id IN (SELECT id FROM orphaned_users);
  DELETE FROM public.account_events WHERE user_id IN (SELECT id FROM orphaned_users);
  DELETE FROM public.user_mfa WHERE user_id IN (SELECT id FROM orphaned_users);
  DELETE FROM public.credentials WHERE user_id IN (SELECT id FROM orphaned_users);
  DELETE FROM public.users WHERE id IN (SELECT id FROM orphaned_users);

  -- Prove it: anything still standing means the loop gave up, and silently
  -- seeding on top of a half-cleared organization is worse than failing.
  FOR target_table IN SELECT name FROM clearable_tables LOOP
    EXECUTE format('SELECT count(*) FROM public.%I WHERE organization_id = $1', target_table)
      INTO STRICT deleted USING target_organization;
    IF deleted > 0 THEN
      leftovers := concat_ws(', ', leftovers, format('%s (%s rows)', target_table, deleted));
    END IF;
  END LOOP;
  IF leftovers IS NOT NULL THEN
    RAISE EXCEPTION 'organization data could not be fully cleared: %', leftovers
      USING ERRCODE = 'data_exception', CONSTRAINT = 'platform_organization_not_cleared';
  END IF;

  RETURN QUERY SELECT pass, total;
END $_$;


--
-- Name: platform_update_organization(uuid, text, text, text, date, date, text, text, text, text, text, text, text, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_update_organization(target_id uuid, p_name text, p_domain text, p_status text, p_active_from_date date, p_active_till_date date, p_account_type text, p_purchase_order_number text, p_address text, p_contact_person text, p_contact_phone text, p_project_manager text, p_sales_person text, p_pricing_plan text, p_subscription_cost numeric, p_custom_development_cost numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NOT public.auth_is_platform_administrator() THEN
    RAISE EXCEPTION 'Platform administrator access is required' USING ERRCODE='42501',CONSTRAINT='platform_administrator_required';
  END IF;
  IF length(trim(p_name)) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'Organization fields are invalid' USING ERRCODE='23514',CONSTRAINT='platform_organization_values';
  END IF;
  UPDATE public.organizations SET name=p_name,domain=p_domain,status=p_status,active=(p_status='active'),
    active_from_date=p_active_from_date,active_till_date=p_active_till_date,account_type=p_account_type,
    purchase_order_number=p_purchase_order_number,address=p_address,contact_person=p_contact_person,contact_phone=p_contact_phone,
    project_manager=p_project_manager,sales_person=p_sales_person,pricing_plan=p_pricing_plan,subscription_cost=p_subscription_cost,
    custom_development_cost=p_custom_development_cost,updated_at=transaction_timestamp() WHERE id=target_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Organization was not found' USING ERRCODE='P0002',CONSTRAINT='platform_organization_not_found';
  END IF;
END $$;


--
-- Name: report_can_print(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_can_print(sample_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
  SELECT EXISTS (SELECT 1 FROM public.samples sample WHERE sample.organization_id=nullif(current_setting('app.organization_id', true), '')::uuid AND sample.id=$1) AND CASE WHEN EXISTS (
    SELECT 1 FROM public.workflow_runs run JOIN public.workflow_state_capability_roles capability
      ON capability.organization_id=run.organization_id AND capability.workflow_state_id=run.current_state_id AND capability.capability='download_report'
    WHERE run.organization_id=nullif(current_setting('app.organization_id', true), '')::uuid AND run.sample_id=$1
  ) THEN EXISTS (
    SELECT 1 FROM public.workflow_runs run JOIN public.workflow_state_capability_roles capability
      ON capability.organization_id=run.organization_id AND capability.workflow_state_id=run.current_state_id AND capability.capability='download_report'
    JOIN public.membership_roles assignment ON assignment.organization_id=capability.organization_id AND assignment.role_id=capability.role_id
      AND assignment.user_id=nullif(current_setting('app.user_id', true), '')::uuid
    WHERE run.organization_id=nullif(current_setting('app.organization_id', true), '')::uuid AND run.sample_id=$1
  ) ELSE public.app_has_permission('samples.manage') END
$_$;


--
-- Name: report_can_reissue(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_can_reissue(sample_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
  SELECT public.report_can_print($1)
    AND EXISTS (SELECT 1 FROM public.samples sample JOIN public.sample_categories category
      ON category.organization_id=sample.organization_id AND category.id=sample.sample_category_id
      WHERE sample.organization_id=nullif(current_setting('app.organization_id', true), '')::uuid AND sample.id=$1 AND category.enable_reissue)
    AND (NOT EXISTS (SELECT 1 FROM public.workflow_runs run WHERE run.organization_id=nullif(current_setting('app.organization_id', true), '')::uuid AND run.sample_id=$1)
      OR EXISTS (SELECT 1 FROM public.workflow_runs run JOIN public.workflow_states state
        ON state.organization_id=run.organization_id AND state.workflow_version_id=run.workflow_version_id AND state.id=run.current_state_id
        WHERE run.organization_id=nullif(current_setting('app.organization_id', true), '')::uuid AND run.sample_id=$1 AND state.show_sample_reissue))
$_$;


--
-- Name: report_current_custom_css(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_current_custom_css() RETURNS TABLE(kind text, id uuid, revision integer, css_content text, saved_at timestamp with time zone, image_ids uuid[], media_type text, content bytea, image_bytes bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.memberships member JOIN public.users person ON person.id=member.user_id AND person.active
    JOIN public.organizations organization ON organization.id=member.organization_id AND organization.active
    WHERE member.organization_id=org AND member.user_id=actor AND member.active) THEN
    RAISE EXCEPTION 'Organization membership required' USING ERRCODE='42501';
  END IF;
  RETURN QUERY WITH latest AS (
    SELECT version.* FROM public.organization_custom_css_versions version WHERE version.organization_id=org ORDER BY version.revision DESC LIMIT 1
  ), images AS (
    SELECT image.* FROM public.report_image_assets image JOIN public.organization_custom_css_images link
      ON link.organization_id=image.organization_id AND link.image_id=image.id
    WHERE link.organization_id=org AND link.version_id=(SELECT version.id FROM latest version)
  ), size AS (SELECT coalesce(sum(image.byte_length),0)::bigint AS bytes FROM images image)
  SELECT 'stylesheet',version.id,version.revision,version.css_content,version.saved_at,
    ARRAY(SELECT link.image_id FROM public.organization_custom_css_images link WHERE link.organization_id=org AND link.version_id=version.id ORDER BY link.image_id),
    NULL::text,NULL::bytea,(SELECT bytes FROM size) FROM latest version
  UNION ALL SELECT 'image',image.id,NULL,NULL,NULL,NULL,image.media_type,CASE WHEN (SELECT bytes FROM size)<=25165824 THEN image.content ELSE NULL END,
    (SELECT bytes FROM size) FROM images image;
END $$;


--
-- Name: report_document_options(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_document_options() RETURNS TABLE(id uuid, type text, name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NOT (public.app_has_permission('templates.read') OR public.app_has_permission('templates.manage')) THEN
    RAISE EXCEPTION 'Template permission required' USING ERRCODE='42501';
  END IF;
  RETURN QUERY SELECT document.id,document.type,version.name FROM public.report_documents document
    JOIN LATERAL (SELECT * FROM public.report_document_versions item WHERE item.organization_id=document.organization_id AND item.document_id=document.id ORDER BY item.revision DESC LIMIT 1) version ON true
    WHERE document.organization_id=nullif(current_setting('app.organization_id',true),'')::uuid AND NOT version.is_retired ORDER BY version.name,document.id;
END $$;


--
-- Name: report_final_line_contexts(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_final_line_contexts(p_report_ids uuid[]) RETURNS TABLE(organization_id uuid, report_id uuid, instance_id uuid, datasheet_id uuid, sample_product_id uuid, product_id uuid, sample_category_id uuid, product_name text, category_name text, description text, quantity numeric, sample_size text, quality text, identification_mark text, received_condition text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF session_user NOT IN ('sampleify_app','sampleify_report_worker') THEN RETURN; END IF;
  IF p_report_ids IS NULL OR cardinality(p_report_ids) NOT BETWEEN 1 AND 1000 OR array_position(p_report_ids,NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'Select a bounded batch of reports' USING ERRCODE='22023';
  END IF;
  RETURN QUERY
WITH scope AS MATERIALIZED (SELECT * FROM public.laboratory_parameter_context_scope())
SELECT DISTINCT report.organization_id,report.id AS report_id,submission.instance_id,context.datasheet_id,
  context.sample_product_id,context.product_id,context.sample_category_id,context.product_name,context.category_name,
  context.description,context.quantity,context.sample_size,context.quality,context.identification_mark,context.received_condition
FROM scope JOIN public.sample_reports report ON report.organization_id=scope.organization_id
  AND report.id=ANY(p_report_ids) AND (scope.report_id IS NULL OR report.id=scope.report_id)
JOIN public.sample_report_tests chosen ON chosen.organization_id=report.organization_id AND chosen.report_id=report.id
JOIN public.datasheet_submissions submission ON submission.organization_id=chosen.organization_id AND submission.id=chosen.submission_id AND submission.source='section'
JOIN public.sample_line_contexts context ON context.organization_id=submission.organization_id AND context.datasheet_id=submission.source_datasheet_id
WHERE (public.app_has_permission('samples.read') OR public.app_has_permission('samples.manage')) AND public.report_can_print(report.sample_id);
END $$;


--
-- Name: report_finalize_sample(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_finalize_sample(p_event_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid := nullif(current_setting('app.organization_id', true), '')::uuid;
  actor uuid := nullif(current_setting('app.user_id', true), '')::uuid;
  event public.sample_events; sample public.samples; receipt public.sample_report_finalizations;
BEGIN
  IF NOT public.app_has_permission('samples.manage') OR org IS NULL OR actor IS NULL THEN
    RAISE EXCEPTION 'Sample management permission required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO event FROM public.sample_events WHERE organization_id=org AND id=p_event_id;
  IF NOT FOUND OR event.event_type<>'reports_finalized' OR event.actor_user_id<>actor OR NOT public.report_can_print(event.sample_id) THEN
    RAISE EXCEPTION 'Report finalisation is not allowed' USING ERRCODE='42501';
  END IF;
  SELECT * INTO sample FROM public.samples WHERE organization_id=org AND id=event.sample_id FOR NO KEY UPDATE;
  SELECT * INTO receipt FROM public.sample_report_finalizations WHERE organization_id=org AND event_id=p_event_id;
  IF FOUND THEN RETURN receipt.completed_revision; END IF;
  IF sample.status='cancelled' OR event.occurred_at IS DISTINCT FROM now()
    OR NOT EXISTS (SELECT 1 FROM public.sample_reports WHERE organization_id=org AND generated_event_id=p_event_id)
    OR EXISTS (SELECT 1 FROM public.sample_reports WHERE organization_id=org AND generated_event_id=p_event_id
      AND (NOT is_finalized OR sample_id<>sample.id OR sample_revision<>sample.revision OR generated_by<>actor OR generated_at<>now())) THEN
    RAISE EXCEPTION 'Finalisation requires the current generated reports' USING ERRCODE='23514';
  END IF;
  INSERT INTO public.sample_report_finalizations(organization_id,event_id,sample_id,previous_revision,completed_revision,finalized_by,finalized_at,transaction_id)
    VALUES(org,p_event_id,sample.id,sample.revision,sample.revision+1,actor,now(),pg_current_xact_id());
  UPDATE public.samples SET status='completed',revision=samples.revision+1 WHERE organization_id=org AND id=sample.id;
  RETURN sample.revision+1;
END $$;


