-- Name: report_guard_print_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_guard_print_settings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Generated print settings are immutable' USING ERRCODE='55000'; END IF;
  IF session_user='sampleify_app' AND NOT EXISTS (SELECT 1 FROM public.sample_reports WHERE organization_id=NEW.organization_id AND id=NEW.report_id
      AND generated_by=nullif(current_setting('app.user_id', true), '')::uuid AND xmin::text=pg_current_xact_id()::text) THEN
    RAISE EXCEPTION 'Print settings must belong to this generation' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: report_guard_product_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_guard_product_context() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE selected_line uuid;
BEGIN
  IF session_user='sampleify_app' THEN
    IF NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
      OR NOT public.app_has_permission('samples.manage') OR NOT public.report_can_print(NEW.sample_id) THEN
      RAISE EXCEPTION 'Report generation permission required' USING ERRCODE='42501';
    END IF;
    PERFORM 1 FROM public.samples WHERE organization_id=NEW.organization_id AND id=NEW.sample_id FOR NO KEY UPDATE;
    SELECT line.id INTO selected_line FROM public.sample_products line WHERE line.organization_id=NEW.organization_id AND line.sample_id=NEW.sample_id
      AND (NEW.sample_product_id IS NULL OR line.id=NEW.sample_product_id) ORDER BY line.display_order,line.id LIMIT 1 FOR SHARE;
    IF selected_line IS NULL OR (NEW.product_context_line_id IS NOT NULL AND NEW.product_context_line_id IS DISTINCT FROM selected_line) THEN
      RAISE EXCEPTION 'Capture the selected report Product line' USING ERRCODE='23514',CONSTRAINT='report_product_context';
    END IF;
    NEW.product_context_line_id:=selected_line;
  END IF;
  -- An importer may supply only recorded history, and any supplied reference
  -- must belong to this sample even when it uses the same organization.
  IF NEW.product_context_line_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.sample_products WHERE organization_id=NEW.organization_id AND id=NEW.product_context_line_id AND sample_id=NEW.sample_id
  ) THEN RAISE EXCEPTION 'Report Product context belongs to another sample' USING ERRCODE='23514',CONSTRAINT='report_product_context'; END IF;
  RETURN NEW;
END $$;


--
-- Name: report_guard_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_guard_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE sample public.samples; previous public.sample_reports; require_approved boolean; source public.sample_reports;
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Generated report revisions are immutable' USING ERRCODE='55000'; END IF;
  IF TG_OP = 'UPDATE' THEN
    IF (OLD.organization_id, OLD.id, OLD.sample_id, OLD.template_version_id, OLD.report_number, OLD.revision, OLD.report_type, OLD.group_key,
        OLD.sample_product_id, OLD.sample_test_id, OLD.product_context_line_id, OLD.generated_by, OLD.generated_at, OLD.generated_event_id, OLD.is_finalized,
        OLD.sample_revision, OLD.sample_number, OLD.sample_type, OLD.sample_category_name, OLD.customer_name, OLD.customer_address,
        OLD.customer_reference, OLD.received_at, OLD.registered_at, OLD.due_at, OLD.description,
        OLD.is_reissued, OLD.reissue_source_id, OLD.reissue_batch_id, OLD.reissued_by, OLD.reissued_at) IS DISTINCT FROM
      (NEW.organization_id, NEW.id, NEW.sample_id, NEW.template_version_id, NEW.report_number, NEW.revision, NEW.report_type, NEW.group_key,
        NEW.sample_product_id, NEW.sample_test_id, NEW.product_context_line_id, NEW.generated_by, NEW.generated_at, NEW.generated_event_id, NEW.is_finalized,
        NEW.sample_revision, NEW.sample_number, NEW.sample_type, NEW.sample_category_name, NEW.customer_name, NEW.customer_address,
        NEW.customer_reference, NEW.received_at, NEW.registered_at, NEW.due_at, NEW.description,
        NEW.is_reissued, NEW.reissue_source_id, NEW.reissue_batch_id, NEW.reissued_by, NEW.reissued_at)
    THEN RAISE EXCEPTION 'Generated report revisions are immutable' USING ERRCODE='55000'; END IF;
    IF session_user <> 'sampleify_app' THEN RETURN NEW; END IF;
    IF OLD.status='draft' AND NEW.status='issued' THEN
      IF NOT NEW.is_finalized OR NEW.issued_by IS DISTINCT FROM nullif(current_setting('app.user_id', true), '')::uuid OR NEW.issued_at IS DISTINCT FROM now()
        OR NOT public.app_has_permission('samples.manage') OR NOT public.report_can_print(NEW.sample_id)
        OR EXISTS (SELECT 1 FROM public.sample_report_tests test WHERE test.organization_id=NEW.organization_id AND test.report_id=NEW.id
          AND (test.request_status<>'approved' OR test.datasheet_status<>'approved'))
      THEN RAISE EXCEPTION 'Report issue is not allowed' USING ERRCODE='42501'; END IF;
      RETURN NEW;
    ELSIF OLD.status='issued' AND NEW.status='superseded' THEN
      IF NEW.issued_by IS DISTINCT FROM OLD.issued_by OR NEW.issued_at IS DISTINCT FROM OLD.issued_at OR NOT public.app_has_permission('samples.manage') THEN
        RAISE EXCEPTION 'Report supersession is not allowed' USING ERRCODE='42501';
      END IF;
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'Generated report revisions are immutable' USING ERRCODE='55000';
  END IF;
  IF session_user <> 'sampleify_app' THEN RETURN NEW; END IF;
  IF NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id', true), '')::uuid
    OR NEW.generated_by IS DISTINCT FROM nullif(current_setting('app.user_id', true), '')::uuid
    OR NEW.generated_at IS DISTINCT FROM now() OR NEW.status <> 'draft'
    OR NOT public.app_has_permission('samples.manage') OR NOT public.report_can_print(NEW.sample_id) THEN
    RAISE EXCEPTION 'Report generation is not allowed' USING ERRCODE='42501';
  END IF;
  IF NEW.is_reissued THEN
    IF NOT public.report_can_reissue(NEW.sample_id) THEN RAISE EXCEPTION 'Report reissue is not allowed' USING ERRCODE='42501'; END IF;
    SELECT * INTO source FROM public.sample_reports WHERE organization_id=NEW.organization_id AND id=NEW.reissue_source_id
      AND sample_id=NEW.sample_id AND status='issued' AND NOT is_reissued;
    IF NOT FOUND OR NEW.reissued_by IS DISTINCT FROM NEW.generated_by OR NEW.reissued_at IS DISTINCT FROM NEW.generated_at
      OR NEW.revision <= source.revision OR NOT NEW.is_finalized
      OR (NEW.template_version_id, NEW.report_number, NEW.report_type, NEW.group_key, NEW.sample_product_id, NEW.sample_test_id, NEW.is_nabl,
          NEW.sample_revision, NEW.sample_number, NEW.sample_type, NEW.sample_category_name, NEW.received_at, NEW.registered_at, NEW.due_at, NEW.description)
        IS DISTINCT FROM (source.template_version_id, source.report_number, source.report_type, source.group_key, source.sample_product_id, source.sample_test_id, source.is_nabl,
          source.sample_revision, source.sample_number, source.sample_type, source.sample_category_name, source.received_at, source.registered_at, source.due_at, source.description)
    THEN RAISE EXCEPTION 'Reissued report must preserve its source report exactly, aside from allowed edits' USING ERRCODE='23514'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.sample_events event WHERE event.organization_id=NEW.organization_id AND event.id=NEW.generated_event_id
      AND event.sample_id=NEW.sample_id AND event.event_type='report_reissued' AND event.actor_user_id=NEW.generated_by
      AND event.occurred_at=NEW.generated_at AND event.xmin::text=pg_current_xact_id()::text)
    THEN RAISE EXCEPTION 'Report provenance is invalid' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO sample FROM public.samples WHERE organization_id=NEW.organization_id AND id=NEW.sample_id FOR NO KEY UPDATE;
  IF NOT FOUND OR sample.status='cancelled' OR
    (NEW.sample_revision, NEW.sample_number, NEW.sample_type, NEW.sample_category_name, NEW.customer_name, NEW.customer_address,
      NEW.customer_reference, NEW.received_at, NEW.registered_at, NEW.due_at, NEW.description) IS DISTINCT FROM
    (sample.revision, sample.sample_number, sample.sample_type, sample.category_name, sample.customer_name, sample.customer_address,
      sample.customer_reference, sample.received_at, sample.registered_at, sample.due_at, sample.description) THEN
    RAISE EXCEPTION 'Report sample snapshot does not match' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.sample_report_finalizations
      WHERE organization_id=NEW.organization_id AND sample_id=NEW.sample_id)
    OR EXISTS (SELECT 1 FROM public.sample_reports
      WHERE organization_id=NEW.organization_id AND sample_id=NEW.sample_id AND is_finalized
        AND generated_event_id<>NEW.generated_event_id) THEN
    RAISE EXCEPTION 'Reports for this sample are already finalised'
      USING ERRCODE='23514',CONSTRAINT='report_already_finalized';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.template_versions WHERE organization_id=NEW.organization_id AND id=NEW.template_version_id AND kind='report' AND status='frozen')
    OR NOT EXISTS (SELECT 1 FROM public.sample_events event WHERE event.organization_id=NEW.organization_id AND event.id=NEW.generated_event_id
      AND event.sample_id=NEW.sample_id AND event.event_type=CASE WHEN NEW.is_finalized THEN 'reports_finalized' ELSE 'reports_generated' END AND event.actor_user_id=NEW.generated_by
      AND event.occurred_at=NEW.generated_at AND event.xmin::text=pg_current_xact_id()::text)
    OR NEW.sample_product_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.sample_products WHERE organization_id=NEW.organization_id AND id=NEW.sample_product_id AND sample_id=NEW.sample_id)
    OR NEW.sample_test_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.sample_tests WHERE organization_id=NEW.organization_id AND id=NEW.sample_test_id AND sample_product_id=NEW.sample_product_id) THEN
    RAISE EXCEPTION 'Report provenance is invalid' USING ERRCODE='23514';
  END IF;
  SELECT * INTO previous FROM public.sample_reports WHERE organization_id=NEW.organization_id AND sample_id=NEW.sample_id AND group_key=NEW.group_key ORDER BY revision DESC LIMIT 1;
  IF NEW.revision IS DISTINCT FROM coalesce(previous.revision, 0)+1 OR previous.id IS NOT NULL AND NEW.report_number IS DISTINCT FROM previous.report_number THEN
    RAISE EXCEPTION 'Report revision changed' USING ERRCODE='40001';
  END IF;
  SELECT coalesce(bool_or(state.require_all_test_requests_approved), false) OR NOT EXISTS (
      SELECT 1 FROM public.workflow_runs run JOIN public.workflow_state_capability_roles capability
        ON capability.organization_id=run.organization_id AND capability.workflow_state_id=run.current_state_id AND capability.capability='download_report'
      WHERE run.organization_id=NEW.organization_id AND run.sample_id=NEW.sample_id)
    INTO require_approved FROM public.workflow_runs run JOIN public.workflow_states state ON state.organization_id=run.organization_id AND state.id=run.current_state_id
    WHERE run.organization_id=NEW.organization_id AND run.sample_id=NEW.sample_id;
  IF require_approved AND EXISTS (SELECT 1 FROM public.sample_products product JOIN public.sample_tests test ON test.organization_id=product.organization_id AND test.sample_product_id=product.id
    LEFT JOIN LATERAL (SELECT * FROM public.test_requests request WHERE request.organization_id=test.organization_id AND request.sample_test_id=test.id ORDER BY request.attempt_number DESC LIMIT 1) request ON true
    LEFT JOIN public.datasheets sheet ON sheet.organization_id=request.organization_id AND sheet.id=request.final_datasheet_id
    WHERE product.organization_id=NEW.organization_id AND product.sample_id=NEW.sample_id AND test.status <> 'cancelled'
      AND (test.status <> 'completed' OR sheet.status IS DISTINCT FROM 'approved')) THEN
    RAISE EXCEPTION 'Approve all test requests before generating reports' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: report_guard_template_assets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_guard_template_assets() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE chosen record;
BEGIN
  FOR chosen IN SELECT * FROM (VALUES (NEW.header_document_id,'header'),(NEW.footer_document_id,'footer'),
    (NEW.nabl_header_document_id,'header'),(NEW.nabl_footer_document_id,'footer')) selected(id,type) WHERE id IS NOT NULL LOOP
    IF NOT EXISTS (SELECT 1 FROM public.report_documents document WHERE document.organization_id=NEW.organization_id AND document.id=chosen.id AND document.type=chosen.type) THEN
      RAISE EXCEPTION 'Select a report asset of the matching type and organization' USING ERRCODE='23514',CONSTRAINT='template_report_asset_type';
    END IF;
  END LOOP;
  RETURN NEW;
END $$;


--
-- Name: report_guard_watermark_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_guard_watermark_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN RAISE EXCEPTION 'Watermark history is immutable' USING ERRCODE='55000'; END $$;


--
-- Name: report_lock_sample(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_lock_sample(sample_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid := nullif(current_setting('app.organization_id', true), '')::uuid;
BEGIN
  IF org IS NULL OR NOT public.app_has_permission('samples.manage') THEN RAISE EXCEPTION 'Report generation permission required' USING ERRCODE='42501'; END IF;
  -- The stable sample key need not be locked against FK checks from an in-flight
  -- datasheet event. All report generation locks this owner before its requests.
  PERFORM 1 FROM public.samples WHERE organization_id=org AND id=report_lock_sample.sample_id FOR NO KEY UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  PERFORM request.id FROM public.test_requests request JOIN public.sample_tests test ON test.organization_id=request.organization_id AND test.id=request.sample_test_id
    JOIN public.sample_products product ON product.organization_id=test.organization_id AND product.id=test.sample_product_id
    WHERE product.organization_id=org AND product.sample_id=report_lock_sample.sample_id ORDER BY request.id FOR NO KEY UPDATE OF request;
  RETURN true;
END $$;


--
-- Name: report_next_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_next_number() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid := nullif(current_setting('app.organization_id', true), '')::uuid;
  period text := extract(year FROM now() AT TIME ZONE 'UTC')::integer::text;
  next_number bigint; result_prefix text; width integer;
BEGIN
  IF org IS NULL OR NOT public.app_has_permission('samples.manage') THEN RAISE EXCEPTION 'Report generation permission required' USING ERRCODE='42501'; END IF;
  INSERT INTO public.number_sequences(organization_id, sequence_key, period_key, prefix, minimum_width)
    VALUES(org, 'sample_report', period, 'COA-' || period || '-', 6) ON CONFLICT DO NOTHING;
  UPDATE public.number_sequences SET next_value=next_value+1
    WHERE organization_id=org AND sequence_key='sample_report' AND period_key=period
    RETURNING next_value-1, prefix, minimum_width INTO next_number, result_prefix, width;
  RETURN result_prefix || lpad(next_number::text, greatest(width, length(next_number::text)), '0');
END $$;


--
-- Name: report_pdf_artifact_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_pdf_artifact_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Generated PDF artifacts are immutable' USING ERRCODE='55000'; END IF;
  RETURN NEW;
END $$;


--
-- Name: report_pdf_attempt_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_pdf_attempt_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' OR TG_OP='UPDATE' AND (OLD.status<>'running' OR NEW.status='running'
    OR (NEW.organization_id,NEW.job_id,NEW.attempt_number,NEW.worker_id,NEW.started_at) IS DISTINCT FROM (OLD.organization_id,OLD.job_id,OLD.attempt_number,OLD.worker_id,OLD.started_at)) THEN
    RAISE EXCEPTION 'Completed PDF attempt evidence is immutable' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: report_pdf_attempt_sequence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_pdf_attempt_sequence_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE job public.report_pdf_jobs; attempt public.report_pdf_attempts; target_job_id uuid; attempt_count integer;
BEGIN
  IF TG_TABLE_NAME='report_pdf_jobs' THEN target_job_id:=NEW.id; ELSE target_job_id:=NEW.job_id; END IF;
  SELECT * INTO job FROM public.report_pdf_jobs j WHERE j.organization_id=NEW.organization_id AND j.id=target_job_id;
  SELECT count(*) INTO attempt_count FROM public.report_pdf_attempts a WHERE a.organization_id=job.organization_id AND a.job_id=job.id;
  IF job.attempts<>attempt_count OR EXISTS (SELECT 1 FROM public.report_pdf_attempts a
    WHERE a.organization_id=job.organization_id AND a.job_id=job.id AND (a.attempt_number>job.attempts OR (a.attempt_number<job.attempts AND a.status NOT IN ('failed','expired')))) THEN
    RAISE EXCEPTION 'PDF job attempts must be consecutive and preserve prior failures' USING ERRCODE='23514';
  END IF;
  IF job.attempts=0 THEN
    IF job.status<>'queued' OR job.started_at IS NOT NULL THEN RAISE EXCEPTION 'An unstarted PDF job must be queued' USING ERRCODE='23514'; END IF;
  ELSE
    SELECT * INTO attempt FROM public.report_pdf_attempts a WHERE a.organization_id=job.organization_id AND a.job_id=job.id AND a.attempt_number=job.attempts;
    IF job.started_at IS DISTINCT FROM attempt.started_at OR
      (job.status='queued' AND attempt.status<>'failed') OR (job.status='running' AND attempt.status<>'running') OR
      (job.status='succeeded' AND attempt.status<>'succeeded') OR (job.status='failed' AND attempt.status NOT IN ('failed','expired')) THEN
      RAISE EXCEPTION 'PDF job state must match its current attempt' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: report_pdf_begin_read(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_pdf_begin_read(p_org_id uuid, p_job_id uuid, p_token uuid) RETURNS TABLE(organization_id uuid, user_id uuid, permission_codes text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE job public.report_pdf_jobs; report public.sample_reports;
BEGIN
  job:=public.report_pdf_require_lease(p_org_id,p_job_id,p_token);
  PERFORM 1 FROM public.memberships m JOIN public.users u ON u.id=m.user_id JOIN public.organizations o ON o.id=m.organization_id
    WHERE m.organization_id=job.organization_id AND m.user_id=job.requested_by AND m.active AND u.active AND o.active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Report requester is no longer active' USING ERRCODE='42501'; END IF;
  PERFORM set_config('app.organization_id',job.organization_id::text,true);
  PERFORM set_config('app.user_id',job.requested_by::text,true);
  SELECT * INTO report FROM public.sample_reports r WHERE r.organization_id=job.organization_id AND r.id=job.report_id;
  IF NOT (public.app_has_permission('samples.read') OR public.app_has_permission('samples.manage')) OR NOT public.report_can_print(report.sample_id) THEN
    RAISE EXCEPTION 'Report print permission was revoked' USING ERRCODE='42501'; END IF;
  PERFORM set_config('app.report_pdf_job_id',job.id::text,true);
  PERFORM set_config('app.report_pdf_lease_hash',encode(job.lease_token_hash,'hex'),true);
  RETURN QUERY SELECT job.organization_id,job.requested_by,ARRAY(SELECT DISTINCT rp.permission_code FROM public.membership_roles mr
    JOIN public.role_permissions rp ON rp.organization_id=mr.organization_id AND rp.role_id=mr.role_id
    WHERE mr.organization_id=job.organization_id AND mr.user_id=job.requested_by ORDER BY rp.permission_code);
END $$;


--
-- Name: report_pdf_claim(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_pdf_claim(p_renderer_id text, p_worker_id uuid) RETURNS TABLE(organization_id uuid, job_id uuid, report_id uuid, renderer_id text, attempt_number integer, lease_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE job public.report_pdf_jobs; at_time timestamptz; token uuid; scanned integer:=0;
BEGIN
  IF p_worker_id IS NULL OR p_renderer_id IS NULL OR p_renderer_id !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid worker identity' USING ERRCODE='22023'; END IF;
  LOOP
    scanned:=scanned+1;
    IF scanned>100 THEN RETURN; END IF;
    SELECT * INTO job FROM public.report_pdf_jobs j WHERE j.renderer_id=p_renderer_id
      AND ((j.status='queued' AND j.available_at<=clock_timestamp()) OR (j.status='running' AND j.lease_expires_at<=clock_timestamp()))
      ORDER BY j.available_at,j.requested_at,j.id FOR UPDATE SKIP LOCKED LIMIT 1;
    IF NOT FOUND THEN RETURN; END IF;
    at_time:=clock_timestamp();
    IF job.status='running' THEN
      UPDATE public.report_pdf_attempts a SET status='expired',completed_at=at_time,error_code='lease_expired',error_message='The previous worker lease expired.'
        WHERE a.organization_id=job.organization_id AND a.job_id=job.id AND a.attempt_number=job.attempts AND a.status='running';
    END IF;
    IF job.attempts>=5 THEN
      UPDATE public.report_pdf_jobs j SET status='failed',lease_token_hash=NULL,lease_expires_at=NULL,completed_at=at_time,
        last_error_code='attempts_exhausted',last_error_message='The report could not be rendered after five attempts.'
        WHERE j.organization_id=job.organization_id AND j.id=job.id;
      CONTINUE;
    END IF;
    token:=gen_random_uuid();
    UPDATE public.report_pdf_jobs j SET status='running',attempts=job.attempts+1,lease_token_hash=sha256(convert_to(token::text,'UTF8')),
      lease_expires_at=at_time+interval '2 minutes',started_at=at_time,completed_at=NULL,last_error_code=NULL,last_error_message=NULL
      WHERE j.organization_id=job.organization_id AND j.id=job.id;
    INSERT INTO public.report_pdf_attempts(organization_id,job_id,attempt_number,worker_id,started_at)
      VALUES(job.organization_id,job.id,job.attempts+1,p_worker_id,at_time);
    RETURN QUERY SELECT job.organization_id,job.id,job.report_id,job.renderer_id,job.attempts+1,token;
    RETURN;
  END LOOP;
END $_$;


--
-- Name: report_pdf_complete(uuid, uuid, uuid, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_pdf_complete(p_org_id uuid, p_job_id uuid, p_token uuid, p_content bytea) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE job public.report_pdf_jobs; at_time timestamptz; artifact_id uuid;
BEGIN
  job:=public.report_pdf_require_lease(p_org_id,p_job_id,p_token);
  -- Recheck current permissions after browser rendering and before publication.
  PERFORM * FROM public.report_pdf_begin_read(p_org_id,p_job_id,p_token);
  at_time:=clock_timestamp();
  INSERT INTO public.report_pdf_artifacts(organization_id,report_id,job_id,attempt_number,content,byte_length,sha256,created_at)
    VALUES(job.organization_id,job.report_id,job.id,job.attempts,p_content,octet_length(p_content),sha256(p_content),at_time) RETURNING id INTO artifact_id;
  UPDATE public.report_pdf_attempts a SET status='succeeded',completed_at=at_time WHERE a.organization_id=job.organization_id AND a.job_id=job.id AND a.attempt_number=job.attempts;
  UPDATE public.report_pdf_jobs j SET status='succeeded',lease_token_hash=NULL,lease_expires_at=NULL,completed_at=at_time,last_error_code=NULL,last_error_message=NULL
    WHERE j.organization_id=job.organization_id AND j.id=job.id;
  RETURN artifact_id;
END $$;


--
-- Name: report_pdf_consistency_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_pdf_consistency_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE job public.report_pdf_jobs; target_job_id uuid;
BEGIN
  IF TG_TABLE_NAME='report_pdf_jobs' THEN target_job_id:=NEW.id; ELSE target_job_id:=NEW.job_id; END IF;
  SELECT * INTO job FROM public.report_pdf_jobs j WHERE j.organization_id=NEW.organization_id AND j.id=target_job_id;
  IF job.status='succeeded' THEN
    IF NOT EXISTS (SELECT 1 FROM public.report_pdf_artifacts file JOIN public.report_pdf_attempts attempt
      ON attempt.organization_id=file.organization_id AND attempt.job_id=file.job_id AND attempt.attempt_number=file.attempt_number
      WHERE file.organization_id=job.organization_id AND file.job_id=job.id AND file.attempt_number=job.attempts AND attempt.status='succeeded') THEN
      RAISE EXCEPTION 'A successful PDF job requires its complete artifact and attempt' USING ERRCODE='23514'; END IF;
  ELSIF EXISTS (SELECT 1 FROM public.report_pdf_artifacts file WHERE file.organization_id=job.organization_id AND file.job_id=job.id) THEN
    RAISE EXCEPTION 'PDF artifacts require a successful job' USING ERRCODE='23514';
  END IF;
  IF TG_TABLE_NAME='report_pdf_attempts' THEN
    IF NEW.status='succeeded' AND (job.status<>'succeeded' OR NEW.attempt_number<>job.attempts) THEN
      RAISE EXCEPTION 'A successful PDF attempt must match the published artifact' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: report_pdf_context_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_pdf_context_org() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; job public.report_pdf_jobs;
BEGIN
  SELECT * INTO job FROM public.report_pdf_jobs j WHERE j.organization_id=org AND j.id=nullif(current_setting('app.report_pdf_job_id',true),'')::uuid;
  IF NOT FOUND OR job.status<>'running' OR job.lease_expires_at<=clock_timestamp()
    OR job.requested_by::text IS DISTINCT FROM current_setting('app.user_id',true)
    OR encode(job.lease_token_hash,'hex') IS DISTINCT FROM current_setting('app.report_pdf_lease_hash',true) THEN RETURN NULL; END IF;
  RETURN org;
END $$;


--
-- Name: report_pdf_enqueue(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_pdf_enqueue(p_report_id uuid, p_renderer_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  report public.sample_reports; result_id uuid;
BEGIN
  SELECT * INTO report FROM public.sample_reports WHERE organization_id=org AND id=p_report_id;
  IF NOT FOUND OR NOT (public.app_has_permission('samples.read') OR public.app_has_permission('samples.manage'))
    OR NOT public.report_can_print(report.sample_id) THEN RAISE EXCEPTION 'Report print permission required' USING ERRCODE='42501'; END IF;
  IF p_renderer_id IS NULL OR p_renderer_id !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid report renderer' USING ERRCODE='22023'; END IF;
  INSERT INTO public.report_pdf_jobs(organization_id,report_id,renderer_id,requested_by)
    VALUES(org,p_report_id,p_renderer_id,actor) ON CONFLICT ON CONSTRAINT report_pdf_job_report_key DO NOTHING RETURNING id INTO result_id;
  IF result_id IS NULL THEN SELECT id INTO result_id FROM public.report_pdf_jobs WHERE organization_id=org AND report_id=p_report_id; END IF;
  RETURN result_id;
END $_$;


--
-- Name: report_pdf_fail(uuid, uuid, uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_pdf_fail(p_org_id uuid, p_job_id uuid, p_token uuid, p_error_code text, p_error_message text, p_retry boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE job public.report_pdf_jobs; at_time timestamptz; retry boolean;
BEGIN
  job:=public.report_pdf_require_lease(p_org_id,p_job_id,p_token);
  at_time:=clock_timestamp(); retry:=coalesce(p_retry,false) AND job.attempts<5;
  UPDATE public.report_pdf_attempts a SET status='failed',completed_at=at_time,error_code=p_error_code,error_message=p_error_message
    WHERE a.organization_id=job.organization_id AND a.job_id=job.id AND a.attempt_number=job.attempts;
  UPDATE public.report_pdf_jobs j SET status=CASE WHEN retry THEN 'queued' ELSE 'failed' END,lease_token_hash=NULL,lease_expires_at=NULL,
    available_at=CASE WHEN retry THEN at_time+make_interval(secs=>power(2,job.attempts)::integer) ELSE j.available_at END,
    completed_at=CASE WHEN retry THEN NULL ELSE at_time END,last_error_code=p_error_code,last_error_message=p_error_message
    WHERE j.organization_id=job.organization_id AND j.id=job.id;
  RETURN true;
END $$;


--
-- Name: report_pdf_job_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_pdf_job_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PDF job history cannot be deleted' USING ERRCODE='55000'; END IF;
  IF OLD.status IN ('succeeded','failed') OR
    (NEW.organization_id,NEW.id,NEW.report_id,NEW.renderer_id,NEW.requested_by,NEW.requested_at) IS DISTINCT FROM
    (OLD.organization_id,OLD.id,OLD.report_id,OLD.renderer_id,OLD.requested_by,OLD.requested_at) THEN
    RAISE EXCEPTION 'PDF job identity and completed history are immutable' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: report_pdf_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.report_pdf_jobs (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    report_id uuid NOT NULL,
    renderer_id text NOT NULL,
    requested_by uuid NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_token_hash bytea,
    lease_expires_at timestamp with time zone,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    last_error_code text,
    last_error_message text,
    CONSTRAINT report_pdf_job_dates CHECK (((available_at >= requested_at) AND ((started_at IS NULL) OR (started_at >= requested_at)) AND ((completed_at IS NULL) OR (completed_at >= requested_at)))),
    CONSTRAINT report_pdf_job_error CHECK ((((last_error_code IS NULL) AND (last_error_message IS NULL) AND (status <> 'failed'::text)) OR ((last_error_code IS NOT NULL) AND (last_error_message IS NOT NULL) AND (last_error_code ~ '^[a-z0-9_]{1,80}$'::text) AND ((length(last_error_message) >= 1) AND (length(last_error_message) <= 2000)) AND (status <> 'succeeded'::text)))),
    CONSTRAINT report_pdf_job_state CHECK ((((status = 'queued'::text) AND (lease_token_hash IS NULL) AND (lease_expires_at IS NULL) AND (completed_at IS NULL)) OR ((status = 'running'::text) AND (attempts > 0) AND (lease_token_hash IS NOT NULL) AND (octet_length(lease_token_hash) = 32) AND (lease_expires_at IS NOT NULL) AND (started_at IS NOT NULL) AND (lease_expires_at > started_at) AND (completed_at IS NULL)) OR ((status = ANY (ARRAY['succeeded'::text, 'failed'::text])) AND (attempts > 0) AND (lease_token_hash IS NULL) AND (lease_expires_at IS NULL) AND (started_at IS NOT NULL) AND (completed_at IS NOT NULL)))),
    CONSTRAINT report_pdf_job_version CHECK (((renderer_id ~ '^[a-f0-9]{64}$'::text) AND ((attempts >= 0) AND (attempts <= 5))))
);


--
-- Name: report_pdf_require_lease(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_pdf_require_lease(p_org_id uuid, p_job_id uuid, p_token uuid) RETURNS public.report_pdf_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE job public.report_pdf_jobs;
BEGIN
  SELECT * INTO job FROM public.report_pdf_jobs WHERE organization_id=p_org_id AND id=p_job_id FOR UPDATE;
  IF NOT FOUND OR job.status<>'running' OR job.lease_expires_at<=clock_timestamp()
    OR job.lease_token_hash IS DISTINCT FROM sha256(convert_to(p_token::text,'UTF8')) THEN
    RAISE EXCEPTION 'Report job lease is unavailable' USING ERRCODE='40001';
  END IF;
  RETURN job;
END $$;


--
-- Name: report_require_complete_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_require_complete_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE item_count integer; first_position integer; last_position integer;
BEGIN
  IF session_user <> 'sampleify_app' THEN RETURN NULL; END IF;
  SELECT count(*), min(display_order), max(display_order) INTO item_count, first_position, last_position FROM public.sample_report_tests WHERE organization_id=NEW.organization_id AND report_id=NEW.id;
  IF item_count=0 OR first_position<>0 OR last_position<>item_count-1 OR NOT EXISTS (
    SELECT 1 FROM public.sample_report_print_settings WHERE organization_id=NEW.organization_id AND report_id=NEW.id
  ) THEN RAISE EXCEPTION 'A generated report needs its complete selection and print settings' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END $$;


--
-- Name: report_require_finalization(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_require_finalization() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE finalization_event uuid; receipt public.sample_report_finalizations;
BEGIN
  IF session_user<>'sampleify_app' THEN RETURN NULL; END IF;
  IF TG_TABLE_NAME='sample_reports' THEN
    IF NOT NEW.is_finalized OR NEW.is_reissued THEN RETURN NULL; END IF;
    finalization_event := NEW.generated_event_id;
  ELSIF TG_TABLE_NAME='sample_events' THEN
    IF NEW.event_type<>'reports_finalized' THEN RETURN NULL; END IF;
    finalization_event := NEW.id;
  ELSE
    finalization_event := NEW.event_id;
  END IF;
  SELECT * INTO receipt FROM public.sample_report_finalizations WHERE organization_id=NEW.organization_id AND event_id=finalization_event;
  IF NOT FOUND OR receipt.transaction_id<>pg_current_xact_id() OR receipt.finalized_at<>now()
    OR receipt.finalized_by IS DISTINCT FROM nullif(current_setting('app.user_id', true), '')::uuid
    OR NOT EXISTS (SELECT 1 FROM public.samples WHERE organization_id=receipt.organization_id AND id=receipt.sample_id
      AND status='completed' AND revision=receipt.completed_revision)
    OR NOT EXISTS (SELECT 1 FROM public.sample_events WHERE organization_id=receipt.organization_id AND id=receipt.event_id
      AND sample_id=receipt.sample_id AND event_type='reports_finalized' AND actor_user_id=receipt.finalized_by AND occurred_at=receipt.finalized_at)
    OR NOT EXISTS (SELECT 1 FROM public.sample_reports WHERE organization_id=receipt.organization_id AND generated_event_id=receipt.event_id)
    OR EXISTS (SELECT 1 FROM public.sample_reports WHERE organization_id=receipt.organization_id AND generated_event_id=receipt.event_id
      AND (NOT is_finalized OR sample_id<>receipt.sample_id OR sample_revision<>receipt.previous_revision
        OR generated_by<>receipt.finalized_by OR generated_at<>receipt.finalized_at)) THEN
    RAISE EXCEPTION 'Finalised reports require matching sample completion evidence' USING ERRCODE='23514',CONSTRAINT='report_finalization_complete';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: report_save_custom_css(uuid, integer, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_save_custom_css(p_version_id uuid, p_expected_revision integer, p_css text, p_image_ids uuid[]) RETURNS TABLE(version_id uuid, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  previous public.organization_custom_css_versions; existing public.organization_custom_css_versions;
  image_ids uuid[]; captured_ids uuid[];
BEGIN
  IF org IS NULL OR actor IS NULL OR NOT public.app_has_permission('report_settings.manage') THEN
    RAISE EXCEPTION 'Report settings management permission required' USING ERRCODE='42501';
  END IF;
  p_css:=replace(p_css,E'\r\n',E'\n');
  IF p_version_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR p_expected_revision>2147483646
    OR p_css IS NULL OR length(p_css)>1000000 OR p_css ~* '<[/]?[[:space:]]*(script|style)\y'
    OR p_image_ids IS NULL OR cardinality(p_image_ids)>100 OR array_position(p_image_ids,NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid Custom CSS' USING ERRCODE='23514',CONSTRAINT='custom_css_input';
  END IF;
  SELECT coalesce(array_agg(DISTINCT image_id ORDER BY image_id),'{}'::uuid[]) INTO image_ids FROM unnest(p_image_ids) image_id;
  PERFORM pg_advisory_xact_lock(hashtextextended('report-documents:'||org::text,0));
  SELECT * INTO existing FROM public.organization_custom_css_versions version WHERE version.organization_id=org AND version.id=p_version_id;
  IF existing.id IS NOT NULL THEN
    SELECT coalesce(array_agg(image.image_id ORDER BY image.image_id),'{}'::uuid[]) INTO captured_ids
      FROM public.organization_custom_css_images image WHERE image.organization_id=org AND image.version_id=p_version_id;
    IF (existing.revision,existing.css_content,existing.saved_by) IS DISTINCT FROM (p_expected_revision+1,p_css,actor) OR captured_ids IS DISTINCT FROM image_ids THEN
      RAISE EXCEPTION 'Custom CSS request was reused' USING ERRCODE='23514',CONSTRAINT='custom_css_request_reused';
    END IF;
    RETURN QUERY SELECT p_version_id,true; RETURN;
  END IF;
  SELECT * INTO previous FROM public.organization_custom_css_versions version WHERE version.organization_id=org ORDER BY version.revision DESC LIMIT 1;
  IF coalesce(previous.revision,0)<>p_expected_revision THEN RAISE EXCEPTION 'Custom CSS changed' USING ERRCODE='40001'; END IF;
  IF EXISTS (SELECT 1 FROM unnest(image_ids) AS selected(image_id) WHERE NOT EXISTS (
    SELECT 1 FROM public.report_image_assets image WHERE image.organization_id=org AND image.id=selected.image_id))
    OR (SELECT coalesce(sum(byte_length),0) FROM public.report_image_assets WHERE organization_id=org AND id=ANY(image_ids))>25165824 THEN
    RAISE EXCEPTION 'Custom CSS images are unavailable or exceed 24 MiB' USING ERRCODE='23514',CONSTRAINT='custom_css_images';
  END IF;
  INSERT INTO public.organization_custom_css_versions(organization_id,id,revision,css_content,saved_by,transaction_id)
    VALUES(org,p_version_id,p_expected_revision+1,p_css,actor,pg_current_xact_id());
  INSERT INTO public.organization_custom_css_images(organization_id,version_id,image_id) SELECT org,p_version_id,id FROM unnest(image_ids) id;
  RETURN QUERY SELECT p_version_id,false;
END $$;


--
-- Name: report_save_document(uuid, uuid, integer, text, text, text, boolean, boolean, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_save_document(p_document_id uuid, p_version_id uuid, p_expected_revision integer, p_type text, p_name text, p_html text, p_default boolean, p_retired boolean, p_image_ids uuid[]) RETURNS TABLE(version_id uuid, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  document public.report_documents; previous public.report_document_versions; existing public.report_document_versions;
  image_ids uuid[]; captured_ids uuid[];
BEGIN
  IF org IS NULL OR actor IS NULL OR NOT public.app_has_permission('report_settings.manage') THEN
    RAISE EXCEPTION 'Report settings management permission required' USING ERRCODE='42501';
  END IF;
  IF p_document_id IS NULL OR p_version_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR p_expected_revision>2147483646
    OR p_type IS NULL OR p_type NOT IN ('header','footer') OR p_name IS NULL OR length(trim(p_name)) NOT BETWEEN 1 AND 200
    OR p_html IS NULL OR length(p_html)>1000000 OR p_default IS NULL OR p_retired IS NULL
    OR (p_default AND (p_type<>'header' OR p_retired)) OR p_image_ids IS NULL OR cardinality(p_image_ids)>100
    OR array_position(p_image_ids,NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid report document' USING ERRCODE='23514',CONSTRAINT='report_document_input';
  END IF;
  SELECT coalesce(array_agg(DISTINCT image_id ORDER BY image_id),'{}'::uuid[]) INTO image_ids FROM unnest(p_image_ids) image_id;
  -- Save/default selection is infrequent. One tenant lock makes revision checks,
  -- default switching and response retries atomic without cross-tenant blocking.
  PERFORM pg_advisory_xact_lock(hashtextextended('report-documents:'||org::text,0));
  SELECT * INTO existing FROM public.report_document_versions version WHERE version.organization_id=org AND version.id=p_version_id;
  SELECT * INTO document FROM public.report_documents WHERE organization_id=org AND id=p_document_id;
  IF existing.id IS NOT NULL THEN
    SELECT coalesce(array_agg(image.image_id ORDER BY image.image_id),'{}'::uuid[]) INTO captured_ids
      FROM public.report_document_images image WHERE image.organization_id=org AND image.version_id=p_version_id;
    IF (existing.document_id,existing.revision,existing.name,existing.template_html,existing.requested_default,existing.is_retired,existing.saved_by)
      IS DISTINCT FROM (p_document_id,p_expected_revision+1,trim(p_name),p_html,p_default,p_retired,actor)
      OR document.type IS DISTINCT FROM p_type OR captured_ids IS DISTINCT FROM image_ids THEN
      RAISE EXCEPTION 'Report document request was reused' USING ERRCODE='23514',CONSTRAINT='report_document_request_reused';
    END IF;
    RETURN QUERY SELECT p_version_id,true; RETURN;
  END IF;
  SELECT * INTO previous FROM public.report_document_versions version WHERE version.organization_id=org AND version.document_id=p_document_id ORDER BY version.revision DESC LIMIT 1;
  IF coalesce(previous.revision,0)<>p_expected_revision THEN
    RAISE EXCEPTION 'Report document changed' USING ERRCODE='40001';
  END IF;
  IF previous.is_retired OR (p_retired AND previous.id IS NULL) THEN
    RAISE EXCEPTION 'Report document is unavailable' USING ERRCODE='23514',CONSTRAINT='report_document_retired';
  END IF;
  IF document.id IS NOT NULL AND document.type IS DISTINCT FROM p_type THEN
    RAISE EXCEPTION 'Report document type cannot change' USING ERRCODE='23514',CONSTRAINT='report_document_type';
  END IF;
  IF p_retired AND (p_name,p_html) IS DISTINCT FROM (previous.name,previous.template_html) THEN
    RAISE EXCEPTION 'Deletion must preserve the saved content' USING ERRCODE='23514',CONSTRAINT='report_document_input';
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(image_ids) AS selected(image_id) WHERE NOT EXISTS (SELECT 1 FROM public.report_image_assets image WHERE image.organization_id=org AND image.id=selected.image_id))
    OR (SELECT coalesce(sum(byte_length),0) FROM public.report_image_assets WHERE organization_id=org AND id=ANY(image_ids))>26214400 THEN
    RAISE EXCEPTION 'Report images are unavailable or exceed 25 MiB' USING ERRCODE='23514',CONSTRAINT='report_document_images';
  END IF;
  IF document.id IS NULL THEN
    INSERT INTO public.report_documents(organization_id,id,type,created_by) VALUES(org,p_document_id,p_type,actor);
  END IF;
  INSERT INTO public.report_document_versions(organization_id,id,document_id,revision,name,template_html,is_retired,requested_default,saved_by,transaction_id)
    VALUES(org,p_version_id,p_document_id,p_expected_revision+1,trim(p_name),p_html,p_retired,p_default,actor,pg_current_xact_id());
  INSERT INTO public.report_document_images(organization_id,version_id,image_id) SELECT org,p_version_id,id FROM unnest(image_ids) id;
  IF p_type='header' THEN
    IF p_default THEN
      INSERT INTO public.report_document_defaults(organization_id,default_header_id,changed_version_id) VALUES(org,p_document_id,p_version_id)
        ON CONFLICT(organization_id) DO UPDATE SET default_header_id=EXCLUDED.default_header_id,changed_version_id=EXCLUDED.changed_version_id;
    ELSE
      UPDATE public.report_document_defaults SET default_header_id=NULL,changed_version_id=p_version_id WHERE organization_id=org AND default_header_id=p_document_id;
    END IF;
  END IF;
  RETURN QUERY SELECT p_version_id,false;
END $$;


--
-- Name: report_save_watermark(uuid, uuid, integer, text, uuid, numeric, integer, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_save_watermark(p_watermark_id uuid, p_version_id uuid, p_expected_revision integer, p_name text, p_image_id uuid, p_opacity numeric, p_width integer, p_height integer, p_rotation integer, p_retired boolean) RETURNS TABLE(version_id uuid, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  previous public.report_watermark_versions; existing public.report_watermark_versions;
BEGIN
  IF org IS NULL OR actor IS NULL OR NOT public.app_has_permission('report_settings.manage') THEN
    RAISE EXCEPTION 'Report settings management permission required' USING ERRCODE='42501';
  END IF;
  IF p_watermark_id IS NULL OR p_version_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 OR p_expected_revision>2147483646
    OR p_name IS NULL OR length(trim(p_name)) NOT BETWEEN 1 AND 200 OR p_image_id IS NULL
    OR p_opacity IS NULL OR p_opacity NOT BETWEEN 0 AND 1 OR p_width IS NULL OR p_width NOT BETWEEN 1 AND 10000
    OR p_height IS NULL OR p_height NOT BETWEEN 1 AND 10000 OR p_rotation IS NULL OR p_rotation NOT IN (0,90,180,270,360) OR p_retired IS NULL THEN
    RAISE EXCEPTION 'Invalid watermark' USING ERRCODE='23514',CONSTRAINT='report_watermark_input';
  END IF;
  -- Infrequent settings writes serialize per tenant, including reuse of a save
  -- request across different identities. Report generation does not use this lock.
  PERFORM pg_advisory_xact_lock(hashtextextended('report-watermarks:'||org::text,0));
  SELECT * INTO existing FROM public.report_watermark_versions version WHERE version.organization_id=org AND version.id=p_version_id;
  IF existing.id IS NOT NULL THEN
    IF (existing.watermark_id,existing.revision,existing.name,existing.image_id,existing.opacity,existing.width,existing.height,existing.rotation,existing.is_retired,existing.saved_by)
      IS DISTINCT FROM (p_watermark_id,p_expected_revision+1,trim(p_name),p_image_id,p_opacity,p_width,p_height,p_rotation,p_retired,actor) THEN
      RAISE EXCEPTION 'Watermark request was reused' USING ERRCODE='23514',CONSTRAINT='report_watermark_request_reused';
    END IF;
    RETURN QUERY SELECT p_version_id,true; RETURN;
  END IF;
  SELECT * INTO previous FROM public.report_watermark_versions version WHERE version.organization_id=org AND version.watermark_id=p_watermark_id ORDER BY version.revision DESC LIMIT 1;
  IF coalesce(previous.revision,0)<>p_expected_revision THEN RAISE EXCEPTION 'Watermark changed' USING ERRCODE='40001'; END IF;
  IF previous.is_retired OR (p_retired AND previous.id IS NULL) THEN
    RAISE EXCEPTION 'Watermark is unavailable' USING ERRCODE='23514',CONSTRAINT='report_watermark_retired';
  END IF;
  IF p_retired AND (trim(p_name),p_image_id,p_opacity,p_width,p_height,p_rotation)
    IS DISTINCT FROM (previous.name,previous.image_id,previous.opacity,previous.width,previous.height,previous.rotation) THEN
    RAISE EXCEPTION 'Deletion must preserve watermark content' USING ERRCODE='23514',CONSTRAINT='report_watermark_input';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.report_image_assets image WHERE image.organization_id=org AND image.id=p_image_id) THEN
    RAISE EXCEPTION 'Watermark image is unavailable' USING ERRCODE='23514',CONSTRAINT='report_watermark_image';
  END IF;
  IF previous.id IS NULL THEN INSERT INTO public.report_watermarks(organization_id,id,created_by) VALUES(org,p_watermark_id,actor); END IF;
  INSERT INTO public.report_watermark_versions(organization_id,id,watermark_id,revision,name,image_id,opacity,width,height,rotation,is_retired,saved_by,transaction_id)
    VALUES(org,p_version_id,p_watermark_id,p_expected_revision+1,trim(p_name),p_image_id,p_opacity,p_width,p_height,p_rotation,p_retired,actor,pg_current_xact_id());
  RETURN QUERY SELECT p_version_id,false;
END $$;


--
-- Name: report_snapshot_assets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_snapshot_assets() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE definition public.template_versions; chosen record; version public.report_document_versions;
  header_id uuid; footer_id uuid; nabl_header_id uuid; nabl_footer_id uuid; css_id uuid; source public.sample_report_assets;
BEGIN
  IF NEW.is_reissued THEN
    SELECT * INTO source FROM public.sample_report_assets WHERE organization_id=NEW.organization_id AND report_id=NEW.reissue_source_id;
    INSERT INTO public.sample_report_assets(organization_id,report_id,header_version_id,footer_version_id,nabl_header_version_id,nabl_footer_version_id,css_version_id)
      VALUES(NEW.organization_id,NEW.id,source.header_version_id,source.footer_version_id,source.nabl_header_version_id,source.nabl_footer_version_id,source.css_version_id);
    RETURN NULL;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('report-documents:'||NEW.organization_id::text,0));
  SELECT * INTO definition FROM public.template_versions WHERE organization_id=NEW.organization_id AND id=NEW.template_version_id;
  FOR chosen IN SELECT * FROM (VALUES ('header',definition.header_document_id),('footer',definition.footer_document_id),
    ('nablHeader',definition.nabl_header_document_id),('nablFooter',definition.nabl_footer_document_id)) selected(slot,id) WHERE id IS NOT NULL LOOP
    SELECT * INTO version FROM public.report_document_versions item WHERE item.organization_id=NEW.organization_id AND item.document_id=chosen.id ORDER BY item.revision DESC LIMIT 1;
    IF NOT FOUND OR version.is_retired THEN
      RAISE EXCEPTION 'A selected report asset is unavailable' USING ERRCODE='23514',CONSTRAINT='report_asset_unavailable';
    END IF;
    CASE chosen.slot WHEN 'header' THEN header_id:=version.id; WHEN 'footer' THEN footer_id:=version.id;
      WHEN 'nablHeader' THEN nabl_header_id:=version.id; WHEN 'nablFooter' THEN nabl_footer_id:=version.id; END CASE;
  END LOOP;
  SELECT id INTO css_id FROM public.organization_custom_css_versions WHERE organization_id=NEW.organization_id ORDER BY revision DESC LIMIT 1;
  INSERT INTO public.sample_report_assets(organization_id,report_id,header_version_id,footer_version_id,nabl_header_version_id,nabl_footer_version_id,css_version_id)
    VALUES(NEW.organization_id,NEW.id,header_id,footer_id,nabl_header_id,nabl_footer_id,css_id);
  RETURN NULL;
END $$;


--
-- Name: roles_assert_version(uuid, uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roles_assert_version(org uuid, target uuid, target_revision integer, check_head boolean) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.role_versions; head public.roles; stored_permissions text[]; stored_capabilities text[];
BEGIN
  SELECT * INTO version FROM public.role_versions WHERE organization_id=org AND role_id=target AND revision=target_revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'Role version is missing' USING ERRCODE='23514'; END IF;
  SELECT ARRAY(SELECT permission_code FROM public.role_version_permissions WHERE organization_id=org AND role_id=target AND revision=target_revision ORDER BY permission_code),
    ARRAY(SELECT capability_key FROM public.role_version_capabilities WHERE organization_id=org AND role_id=target AND revision=target_revision ORDER BY capability_key)
    INTO stored_permissions,stored_capabilities;
  IF cardinality(stored_permissions)<>version.permission_count OR cardinality(stored_capabilities)<>version.capability_count THEN
    RAISE EXCEPTION 'Role history requires complete permission and capability sets' USING ERRCODE='23514';
  END IF;
  IF check_head THEN
    SELECT * INTO head FROM public.roles WHERE organization_id=org AND id=target;
    IF (head.revision,head.name,head.description,head.default_path,head.active,head.protected)
      IS DISTINCT FROM (version.revision,version.name,version.description,version.default_path,version.active,version.protected)
      OR stored_permissions IS DISTINCT FROM ARRAY(SELECT permission_code FROM public.role_permissions WHERE organization_id=org AND role_id=target ORDER BY permission_code)
      OR stored_capabilities IS DISTINCT FROM ARRAY(SELECT capability_key FROM public.role_capabilities WHERE organization_id=org AND role_id=target ORDER BY capability_key) THEN
      RAISE EXCEPTION 'Current role must match its saved version' USING ERRCODE='23514';
    END IF;
  END IF;
END $$;


--
-- Name: roles_check_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roles_check_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE head public.roles; org uuid; target uuid;
BEGIN
  org:=CASE WHEN TG_OP='DELETE' THEN OLD.organization_id ELSE NEW.organization_id END;
  IF TG_TABLE_NAME='roles' THEN target:=NEW.id;
  ELSE target:=CASE WHEN TG_OP='DELETE' THEN OLD.role_id ELSE NEW.role_id END; END IF;
  SELECT * INTO head FROM public.roles WHERE organization_id=org AND id=target;
  IF TG_TABLE_NAME='role_versions' THEN
    PERFORM public.roles_assert_version(org,target,NEW.revision,head.revision=NEW.revision);
  ELSIF head.revision>0 THEN
    PERFORM public.roles_assert_version(org,target,head.revision,true);
  END IF;
  RETURN NULL;
END $$;


--
-- Name: roles_guard_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roles_guard_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- The role command holds FOR UPDATE on this same row. Recheck active after waiting.
  PERFORM 1 FROM public.roles WHERE organization_id=NEW.organization_id AND id=NEW.role_id AND active FOR KEY SHARE;
  IF NOT FOUND AND EXISTS (SELECT 1 FROM public.roles WHERE organization_id=NEW.organization_id AND id=NEW.role_id) THEN
    RAISE EXCEPTION 'Select an active role in this organization' USING ERRCODE='23514',CONSTRAINT='role_inactive_assignment';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: roles_guard_current_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roles_guard_current_links() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE head public.roles; version public.role_versions; org uuid; target uuid;
BEGIN
  IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'Replace role links through a saved revision' USING ERRCODE='23514'; END IF;
  org:=CASE WHEN TG_OP='DELETE' THEN OLD.organization_id ELSE NEW.organization_id END;
  target:=CASE WHEN TG_OP='DELETE' THEN OLD.role_id ELSE NEW.role_id END;
  SELECT * INTO head FROM public.roles WHERE organization_id=org AND id=target;
  IF head.revision>0 THEN
    SELECT * INTO version FROM public.role_versions WHERE organization_id=org AND role_id=target AND revision=head.revision;
    IF version.role_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
      OR version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
      OR org IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid THEN
      RAISE EXCEPTION 'Role links require their current saved revision transaction' USING ERRCODE='23514';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: roles_guard_head(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roles_guard_head() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF OLD.revision>0 THEN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Saved roles cannot be deleted' USING ERRCODE='55000'; END IF;
    IF (NEW.organization_id,NEW.id,NEW.protected) IS DISTINCT FROM (OLD.organization_id,OLD.id,OLD.protected)
      OR NEW.revision<>OLD.revision+1 OR NOT OLD.active THEN
      RAISE EXCEPTION 'Role identity and active revision are immutable' USING ERRCODE='23514';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: roles_guard_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roles_guard_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.role_versions; stored_role public.roles;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Role history is immutable' USING ERRCODE='55000'; END IF;
  IF TG_TABLE_NAME='role_versions' THEN
    SELECT * INTO stored_role FROM public.roles WHERE organization_id=NEW.organization_id AND id=NEW.role_id;
    IF NEW.saved_by IS DISTINCT FROM public.roles_require_actor()
      OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
      OR NEW.created_transaction_id<>pg_current_xact_id() OR NEW.saved_at<>transaction_timestamp()
      OR (NEW.revision,NEW.name,NEW.description,NEW.default_path,NEW.active,NEW.protected)
        IS DISTINCT FROM (stored_role.revision,stored_role.name,stored_role.description,stored_role.default_path,stored_role.active,stored_role.protected) THEN
      RAISE EXCEPTION 'Role history requires the current head, actual editor and transaction' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO version FROM public.role_versions WHERE organization_id=NEW.organization_id AND role_id=NEW.role_id AND revision=NEW.revision;
    IF version.role_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
      OR version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
      OR version.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid THEN
      RAISE EXCEPTION 'Role links require their actual version transaction' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: roles_require_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roles_require_actor() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.sessions session
    JOIN public.users person ON person.id=session.user_id AND person.active AND NOT person.must_change_password
    JOIN public.credentials credential ON credential.user_id=person.id AND credential.revision=session.credential_revision
    JOIN public.memberships membership ON membership.organization_id=session.organization_id AND membership.user_id=person.id AND membership.active
    JOIN public.organizations organization ON organization.id=session.organization_id AND organization.active
    WHERE session.id=nullif(current_setting('app.session_id',true),'')::uuid AND session.user_id=actor AND session.organization_id=org
      AND session.revoked_at IS NULL AND session.expires_at>clock_timestamp()
  ) OR NOT public.app_has_permission('roles.manage') THEN
    RAISE EXCEPTION 'Active role management session required' USING ERRCODE='42501',CONSTRAINT='role_session_required';
  END IF;
  RETURN actor;
END $$;


--
-- Name: roles_write(text, uuid, integer, uuid, text, text, boolean, text, boolean, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.roles_write(operation text, target uuid, expected_revision integer, requested_id uuid, requested_name text, requested_description text, description_provided boolean, requested_path text, path_provided boolean, requested_permissions text[], requested_capabilities text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid; org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  stored_role public.roles; prior public.role_versions; next_revision integer;
  next_name text; next_description text; next_path text; next_permissions text[]; next_capabilities text[];
BEGIN
  actor:=public.roles_require_actor();
  -- Serializes all role changes in an organization, including two administrators removing each other's grants.
  PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
  actor:=public.roles_require_actor();
  IF operation IS NULL OR operation NOT IN ('create','update','retire') OR target IS NULL OR requested_id IS NULL
    OR expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 2147483646
    OR (operation='create' AND expected_revision<>0) OR description_provided IS NULL OR path_provided IS NULL
    OR (NOT description_provided AND requested_description IS NOT NULL) OR (description_provided AND requested_description IS NULL)
    OR (NOT path_provided AND requested_path IS NOT NULL)
    OR (operation='retire' AND (num_nonnulls(requested_name,requested_description,requested_path,requested_permissions,requested_capabilities)<>0 OR description_provided OR path_provided))
    OR (operation<>'retire' AND (requested_name IS NULL OR length(trim(requested_name)) NOT BETWEEN 1 AND 150 OR requested_name<>trim(requested_name)))
    OR length(requested_description)>2000 OR length(requested_path)>300
    OR (requested_permissions IS NOT NULL AND (coalesce(array_ndims(requested_permissions),1)<>1 OR cardinality(requested_permissions)>500
      OR cardinality(requested_permissions)<>(SELECT count(DISTINCT item) FROM unnest(requested_permissions) item)
      OR EXISTS (SELECT 1 FROM unnest(requested_permissions) item WHERE item IS NULL OR length(trim(item)) NOT BETWEEN 1 AND 150)))
    OR (requested_capabilities IS NOT NULL AND (coalesce(array_ndims(requested_capabilities),1)<>1 OR cardinality(requested_capabilities)>18
      OR cardinality(requested_capabilities)<>(SELECT count(DISTINCT item) FROM unnest(requested_capabilities) item))) THEN
    RAISE EXCEPTION 'Invalid role command' USING ERRCODE='23514',CONSTRAINT='role_invalid_input';
  END IF;
  SELECT * INTO prior FROM public.role_versions WHERE organization_id=org AND request_id=requested_id;
  IF FOUND THEN
    IF prior.role_id<>target OR prior.operation<>operation OR coalesce(prior.previous_revision,0)<>expected_revision OR prior.saved_by<>actor
      OR prior.description_provided<>description_provided OR prior.default_path_provided<>path_provided
      OR prior.permissions_provided<>(requested_permissions IS NOT NULL) OR prior.capabilities_provided<>(requested_capabilities IS NOT NULL)
      OR (operation<>'retire' AND prior.name IS DISTINCT FROM requested_name)
      OR (description_provided AND prior.description IS DISTINCT FROM requested_description)
      OR (path_provided AND prior.default_path IS DISTINCT FROM requested_path)
      OR (requested_permissions IS NOT NULL AND ARRAY(SELECT item FROM unnest(requested_permissions) item ORDER BY item)
        IS DISTINCT FROM ARRAY(SELECT permission_code FROM public.role_version_permissions WHERE organization_id=org AND role_id=target AND revision=prior.revision ORDER BY permission_code))
      OR (requested_capabilities IS NOT NULL AND ARRAY(SELECT item FROM unnest(requested_capabilities) item ORDER BY item)
        IS DISTINCT FROM ARRAY(SELECT capability_key FROM public.role_version_capabilities WHERE organization_id=org AND role_id=target AND revision=prior.revision ORDER BY capability_key)) THEN
      RAISE EXCEPTION 'Role request was used for a different change' USING ERRCODE='23514',CONSTRAINT='role_request_reused';
    END IF;
    RETURN prior.revision;
  END IF;
  SELECT * INTO stored_role FROM public.roles WHERE organization_id=org AND id=target FOR UPDATE;
  IF operation='create' AND FOUND THEN RAISE EXCEPTION 'Role already exists' USING ERRCODE='23514',CONSTRAINT='role_identifier_exists'; END IF;
  IF operation<>'create' AND (stored_role.id IS NULL OR NOT stored_role.active) THEN
    RAISE EXCEPTION 'Role was not found' USING ERRCODE='P0002',CONSTRAINT='role_not_found';
  END IF;
  IF operation<>'create' AND stored_role.revision<>expected_revision THEN
    RAISE EXCEPTION 'Role changed; reload before saving' USING ERRCODE='23514',CONSTRAINT='role_stale';
  END IF;
  IF operation='retire' THEN
    IF stored_role.protected THEN RAISE EXCEPTION 'Protected roles cannot be deleted' USING ERRCODE='23514',CONSTRAINT='role_protected'; END IF;
    IF EXISTS (SELECT 1 FROM public.membership_roles WHERE organization_id=org AND role_id=target) THEN
      RAISE EXCEPTION 'Assigned roles cannot be deleted' USING ERRCODE='23514',CONSTRAINT='role_assigned';
    END IF;
  END IF;
  IF stored_role.revision>0 THEN PERFORM public.roles_assert_version(org,target,stored_role.revision,true); END IF;
  next_revision:=expected_revision+1;
  next_name:=CASE WHEN operation='retire' THEN stored_role.name ELSE requested_name END;
  next_description:=CASE WHEN description_provided THEN requested_description ELSE coalesce(stored_role.description,'') END;
  next_path:=CASE WHEN path_provided THEN requested_path ELSE stored_role.default_path END;
  next_permissions:=coalesce(requested_permissions,ARRAY(SELECT permission_code FROM public.role_permissions WHERE organization_id=org AND role_id=target ORDER BY permission_code));
  next_capabilities:=coalesce(requested_capabilities,ARRAY(SELECT capability_key FROM public.role_capabilities WHERE organization_id=org AND role_id=target ORDER BY capability_key));
  IF EXISTS (SELECT 1 FROM unnest(next_permissions) candidate(code) WHERE NOT EXISTS (SELECT 1 FROM public.permissions permission WHERE permission.code=candidate.code)) THEN
    RAISE EXCEPTION 'Unknown API permission' USING ERRCODE='23514',CONSTRAINT='role_unknown_permission';
  END IF;
  -- Evaluate the proposed grants before mutating them, so the audit insert still has the actual editor's authority.
  IF NOT EXISTS (
    SELECT 1 FROM public.membership_roles assignment JOIN public.roles role ON role.organization_id=assignment.organization_id AND role.id=assignment.role_id AND role.active
    JOIN public.memberships membership ON membership.organization_id=assignment.organization_id AND membership.user_id=assignment.user_id AND membership.active
    JOIN public.users person ON person.id=membership.user_id AND person.active
    JOIN public.role_permissions permission ON permission.organization_id=role.organization_id AND permission.role_id=role.id AND permission.permission_code='roles.manage'
    WHERE assignment.organization_id=org AND (role.id<>target OR (operation<>'retire' AND 'roles.manage'=ANY(next_permissions)))
  ) THEN RAISE EXCEPTION 'The last active role administrator must be retained' USING ERRCODE='23514',CONSTRAINT='role_last_administrator'; END IF;
  -- User administration must remain available when role definitions and assignments change concurrently.
  IF EXISTS (
    SELECT 1 FROM public.membership_roles assignment JOIN public.roles role ON role.organization_id=assignment.organization_id AND role.id=assignment.role_id AND role.active
    JOIN public.memberships membership ON membership.organization_id=assignment.organization_id AND membership.user_id=assignment.user_id AND membership.active
    JOIN public.users person ON person.id=membership.user_id AND person.active
    JOIN public.role_permissions permission ON permission.organization_id=role.organization_id AND permission.role_id=role.id AND permission.permission_code='users.manage'
    WHERE assignment.organization_id=org
  ) AND NOT EXISTS (
    SELECT 1 FROM public.membership_roles assignment JOIN public.roles role ON role.organization_id=assignment.organization_id AND role.id=assignment.role_id AND role.active
    JOIN public.memberships membership ON membership.organization_id=assignment.organization_id AND membership.user_id=assignment.user_id AND membership.active
    JOIN public.users person ON person.id=membership.user_id AND person.active
    JOIN public.role_permissions permission ON permission.organization_id=role.organization_id AND permission.role_id=role.id AND permission.permission_code='users.manage'
    WHERE assignment.organization_id=org AND (role.id<>target OR (operation<>'retire' AND 'users.manage'=ANY(next_permissions)))
  ) THEN RAISE EXCEPTION 'The last active user administrator must be retained' USING ERRCODE='23514',CONSTRAINT='user_profile_last_administrator'; END IF;
  IF operation='create' THEN
    INSERT INTO public.roles(organization_id,id,name,description,default_path,revision) VALUES(org,target,next_name,next_description,next_path,next_revision);
  ELSE
    UPDATE public.roles SET name=next_name,description=next_description,default_path=next_path,active=operation<>'retire',revision=next_revision
      WHERE organization_id=org AND id=target;
  END IF;
  INSERT INTO public.role_versions(organization_id,role_id,revision,request_id,previous_revision,operation,name,description,default_path,active,protected,
    permission_count,capability_count,description_provided,default_path_provided,permissions_provided,capabilities_provided,saved_by)
    VALUES(org,target,next_revision,requested_id,CASE WHEN operation='create' THEN NULL ELSE expected_revision END,operation,next_name,next_description,next_path,
      operation<>'retire',coalesce(stored_role.protected,false),cardinality(next_permissions),cardinality(next_capabilities),description_provided,path_provided,
      requested_permissions IS NOT NULL,requested_capabilities IS NOT NULL,actor);
  INSERT INTO public.role_version_permissions(organization_id,role_id,revision,permission_code) SELECT org,target,next_revision,code FROM unnest(next_permissions) code;
  INSERT INTO public.role_version_capabilities(organization_id,role_id,revision,capability_key) SELECT org,target,next_revision,key FROM unnest(next_capabilities) key;
  DELETE FROM public.role_permissions WHERE organization_id=org AND role_id=target;
  DELETE FROM public.role_capabilities WHERE organization_id=org AND role_id=target;
  INSERT INTO public.role_permissions(organization_id,role_id,permission_code) SELECT org,target,code FROM unnest(next_permissions) code;
  INSERT INTO public.role_capabilities(organization_id,role_id,capability_key) SELECT org,target,key FROM unnest(next_capabilities) key;
  RETURN next_revision;
END $$;


--
-- Name: sample_line_guard_capture_size(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sample_line_guard_capture_size() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE expanded_bytes bigint; capture public.template_instances;
BEGIN
  IF TG_TABLE_NAME='datasheets' THEN
    SELECT * INTO capture FROM public.template_instances WHERE organization_id=NEW.organization_id AND id=NEW.template_instance_id;
  ELSE capture:=NEW; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.template_fields field WHERE field.organization_id=capture.organization_id
    AND field.version_id=capture.version_id AND field.widget='sample_line_item_data_widget') THEN RETURN NULL; END IF;
  SELECT sum(coalesce(octet_length(attribute.value),0)::bigint*occurrences.count) INTO expanded_bytes
  FROM public.datasheets sheet JOIN public.sample_line_contexts context ON context.organization_id=sheet.organization_id AND context.datasheet_id=sheet.id
  CROSS JOIN LATERAL (VALUES ('custom_category',context.category_name),('custom_product',context.product_name),('custom_description',context.description),
    ('custom_sample_quantity',context.quantity::text),('custom_sample_size',context.sample_size),('custom_quality',context.quality),
    ('custom_indentification_mark',context.identification_mark),('custom_condition',context.received_condition)) attribute(key,value)
  JOIN public.template_fields field ON field.organization_id=capture.organization_id AND field.version_id=capture.version_id
    AND field.widget='sample_line_item_data_widget' AND field.source_field=attribute.key
  JOIN (SELECT occurrence.group_id,count(*) AS count FROM public.template_occurrences occurrence
    WHERE occurrence.organization_id=capture.organization_id AND occurrence.instance_id=capture.id AND occurrence.created_revision<=capture.revision
      AND (occurrence.removed_revision IS NULL OR occurrence.removed_revision>capture.revision) GROUP BY occurrence.group_id) occurrences
    ON occurrences.group_id IS NOT DISTINCT FROM field.repeat_group_id
  WHERE sheet.organization_id=capture.organization_id AND sheet.template_instance_id=capture.id;
  IF expanded_bytes>16777216 THEN RAISE EXCEPTION 'The repeated line-item values exceed the supported document size'
    USING ERRCODE='23514',CONSTRAINT='sample_line_size_limit'; END IF;
  RETURN NULL;
END $$;


--
-- Name: sample_line_guard_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sample_line_guard_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'Captured line contexts are immutable' USING ERRCODE='55000';
END $$;


--
-- Name: sample_line_guard_report_members(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sample_line_guard_report_members() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.sample_line_contexts context WHERE context.organization_id=NEW.organization_id AND context.report_id=NEW.report_id) THEN
    RAISE EXCEPTION 'Report selections are already captured' USING ERRCODE='23514',CONSTRAINT='sample_line_report_members';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: sample_line_require_report_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sample_line_require_report_context() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.template_fields field WHERE field.organization_id=NEW.organization_id AND field.widget='sample_line_item_data_widget'
    AND (field.version_id=NEW.template_version_id OR EXISTS (
      SELECT 1 FROM public.sample_report_tests chosen JOIN public.datasheet_submissions submission
        ON submission.organization_id=chosen.organization_id AND submission.id=chosen.submission_id AND submission.source='section'
      WHERE chosen.organization_id=NEW.organization_id AND chosen.report_id=NEW.id AND submission.version_id=field.version_id)))
    AND NOT EXISTS (SELECT 1 FROM public.sample_line_contexts context WHERE context.organization_id=NEW.organization_id AND context.report_id=NEW.id) THEN
    RAISE EXCEPTION 'The report line context is unavailable' USING ERRCODE='23514',CONSTRAINT='sample_line_context_missing';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: sample_line_snapshot_datasheet(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sample_line_snapshot_datasheet() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.template_instances capture JOIN public.template_fields field
    ON field.organization_id=capture.organization_id AND field.version_id=capture.version_id
    WHERE capture.organization_id=NEW.organization_id AND capture.id=NEW.template_instance_id AND field.widget='sample_line_item_data_widget') THEN RETURN NULL; END IF;
  INSERT INTO public.sample_line_contexts(organization_id,datasheet_id,sample_product_id,product_id,sample_category_id,
    product_name,category_name,description,quantity,sample_size,quality,identification_mark,received_condition)
  SELECT NEW.organization_id,NEW.id,line.id,line.product_id,line.sample_category_id,product.name,category.name,
    line.description,line.quantity,line.sample_size,line.quality,line.identification_mark,line.received_condition
  FROM public.test_requests request LEFT JOIN public.sample_tests test ON test.organization_id=request.organization_id AND test.id=request.sample_test_id
  JOIN public.sample_products line ON line.organization_id=request.organization_id AND line.id=coalesce(request.job_sample_product_id,test.sample_product_id)
  JOIN public.products product ON product.organization_id=line.organization_id AND product.id=line.product_id
  JOIN public.sample_categories category ON category.organization_id=line.organization_id AND category.id=line.sample_category_id
  WHERE request.organization_id=NEW.organization_id AND request.id=NEW.test_request_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'The datasheet line context is unavailable' USING ERRCODE='23514',CONSTRAINT='sample_line_context_missing'; END IF;
  RETURN NULL;
END $$;


--
-- Name: sample_line_snapshot_reports(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sample_line_snapshot_reports(p_report_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
BEGIN
  IF session_user<>'sampleify_app' OR org IS NULL OR actor IS NULL OR NOT public.app_has_permission('samples.manage')
    OR NOT EXISTS (SELECT 1 FROM public.laboratory_parameter_context_scope()) THEN
    RAISE EXCEPTION 'Report generation permission required' USING ERRCODE='42501';
  END IF;
  IF p_report_ids IS NULL OR cardinality(p_report_ids) NOT BETWEEN 1 AND 1000
    OR cardinality(p_report_ids)<>(SELECT count(DISTINCT id) FROM unnest(p_report_ids) selected(id)) THEN
    RAISE EXCEPTION 'Select distinct reports from this generation' USING ERRCODE='23514';
  END IF;
  -- Reuse the existing report creation boundary, including its current
  -- transaction, actor, timestamp and print authority. This is not a late
  -- history repair or a way to attach values to an earlier report.
  IF (SELECT count(*) FROM public.sample_reports report WHERE report.organization_id=org AND report.id=ANY(p_report_ids)
    AND report.generated_by=actor AND report.generated_at=now() AND report.xmin::text=pg_current_xact_id()::text
    AND public.report_can_print(report.sample_id))<>cardinality(p_report_ids) THEN
    RAISE EXCEPTION 'Line contexts must belong to this report generation' USING ERRCODE='23514',CONSTRAINT='sample_line_creation';
  END IF;
  INSERT INTO public.sample_line_contexts(organization_id,report_id,sample_product_id,product_id,sample_category_id,
    product_name,category_name,description,quantity,sample_size,quality,identification_mark,received_condition)
  SELECT org,report.id,line.id,line.product_id,line.sample_category_id,product.name,category.name,
    line.description,line.quantity,line.sample_size,line.quality,line.identification_mark,line.received_condition
  FROM public.sample_reports report
  -- Meteor filters a generated child's lines by Product identity as well as
  -- unique line identity. Thus a selected second line of the same Product can
  -- still display the earlier line. Parameter loops do not change this choice.
  CROSS JOIN LATERAL (SELECT candidate.* FROM public.sample_products candidate
    WHERE candidate.organization_id=org AND candidate.sample_id=report.sample_id AND (
      (report.report_type<>'consolidated' AND (candidate.id=report.sample_product_id OR candidate.product_id=(
        SELECT grouped.product_id FROM public.sample_products grouped WHERE grouped.organization_id=org AND grouped.id=report.sample_product_id)))
      OR (report.report_type='consolidated' AND EXISTS (
        SELECT 1 FROM public.sample_products requested_line JOIN public.sample_tests test
          ON test.organization_id=requested_line.organization_id AND test.sample_product_id=requested_line.id
        JOIN public.test_requests request ON request.organization_id=test.organization_id AND request.sample_test_id=test.id AND NOT request.is_job
        JOIN public.analytical_specifications specification ON specification.organization_id=request.organization_id AND specification.id=request.specification_id
        WHERE requested_line.organization_id=org AND requested_line.sample_id=report.sample_id AND requested_line.product_id=candidate.product_id
          AND EXISTS (SELECT 1 FROM public.sample_report_tests chosen JOIN public.analytical_specifications selected
            ON selected.organization_id=chosen.organization_id AND selected.id=chosen.specification_id
            WHERE chosen.organization_id=org AND chosen.report_id=report.id AND selected.test_parameter_id=specification.test_parameter_id))))
    ORDER BY candidate.display_order,candidate.id LIMIT 1) line
  JOIN public.products product ON product.organization_id=org AND product.id=line.product_id
  JOIN public.sample_categories category ON category.organization_id=org AND category.id=line.sample_category_id
  WHERE report.organization_id=org AND report.id=ANY(p_report_ids) AND EXISTS (
    SELECT 1 FROM public.template_fields field WHERE field.organization_id=org AND field.widget='sample_line_item_data_widget'
      AND (field.version_id=report.template_version_id OR EXISTS (
        SELECT 1 FROM public.sample_report_tests chosen JOIN public.datasheet_submissions submission
          ON submission.organization_id=chosen.organization_id AND submission.id=chosen.submission_id AND submission.source='section'
        WHERE chosen.organization_id=org AND chosen.report_id=report.id AND submission.version_id=field.version_id)));
END $$;


--
-- Name: sample_receiving_date_edit_enabled(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sample_receiving_date_edit_enabled() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  IF org IS NULL OR NOT (public.app_has_permission('samples.create') OR public.app_has_permission('samples.read')) THEN
    RAISE EXCEPTION 'Sample permission required' USING ERRCODE='42501';
  END IF;
  RETURN coalesce((SELECT settings.allow_receiving_date_edit FROM public.organization_laboratory_settings settings WHERE settings.organization_id=org),false);
END $$;


--
-- Name: service_agreements_can_read(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_can_read() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT public.organization_module_scope() IS NOT NULL AND public.organization_has_module_access('service_agreements')
    AND (public.app_has_permission('masters.read') OR public.app_has_permission('masters.manage'));
$$;


--
-- Name: service_agreements_can_read_file(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_can_read_file(target_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT public.service_agreements_can_read() AND (public.app_has_permission('masters.manage') OR EXISTS (
    SELECT 1 FROM public.service_agreement_versions WHERE organization_id=public.organization_module_scope() AND attachment_file_id=target_id
  ));
$$;


--
-- Name: service_agreements_check_head_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_check_head_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.service_agreement_versions;
BEGIN
  SELECT * INTO version FROM public.service_agreement_versions WHERE organization_id=NEW.organization_id AND agreement_id=NEW.id AND revision=NEW.revision;
  IF version.agreement_id IS NULL OR
    (NEW.vendor_id,NEW.start_date,NEW.end_date,NEW.no_of_services,NEW.cost,NEW.notes,NEW.in_effect,NEW.attachment_file_id,NEW.retired,NEW.save_request_id,NEW.updated_at)
    IS DISTINCT FROM
    (version.vendor_id,version.start_date,version.end_date,version.no_of_services,version.cost,version.notes,version.in_effect,version.attachment_file_id,version.retired,version.request_id,version.saved_at) THEN
    RAISE EXCEPTION 'Service Agreement head requires matching immutable history' USING ERRCODE='23514',CONSTRAINT='service_agreement_head_history';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: service_agreements_check_relations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_check_relations() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.instrument_count IS DISTINCT FROM (SELECT count(*) FROM public.service_agreement_version_instruments WHERE organization_id=NEW.organization_id AND agreement_id=NEW.agreement_id AND revision=NEW.revision)
    OR EXISTS (SELECT 1 FROM public.service_agreement_version_instruments WHERE organization_id=NEW.organization_id AND agreement_id=NEW.agreement_id AND revision=NEW.revision AND position>=NEW.instrument_count)
    OR NEW.service_count IS DISTINCT FROM (SELECT count(*) FROM public.service_agreement_version_services WHERE organization_id=NEW.organization_id AND agreement_id=NEW.agreement_id AND revision=NEW.revision)
    OR EXISTS (SELECT 1 FROM public.service_agreement_version_services WHERE organization_id=NEW.organization_id AND agreement_id=NEW.agreement_id AND revision=NEW.revision AND position>=NEW.service_count) THEN
    RAISE EXCEPTION 'Service Agreement relationships require complete ordered snapshots' USING ERRCODE='23514',CONSTRAINT='service_agreement_relations_complete';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: service_agreements_copy_relations(uuid, integer, integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_copy_relations(target_id uuid, previous_revision integer, next_revision integer, copy_instruments boolean, copy_services boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=public.organization_module_scope();
BEGIN
  IF copy_instruments THEN
    INSERT INTO public.service_agreement_version_instruments(organization_id,agreement_id,revision,instrument_id,position,instrument_revision,instrument_name,instrument_code)
      SELECT organization_id,agreement_id,next_revision,instrument_id,position,instrument_revision,instrument_name,instrument_code
      FROM public.service_agreement_version_instruments WHERE organization_id=org AND agreement_id=target_id AND revision=previous_revision;
  END IF;
  IF copy_services THEN
    INSERT INTO public.service_agreement_version_services(organization_id,agreement_id,revision,service_code,position)
      SELECT organization_id,agreement_id,next_revision,service_code,position FROM public.service_agreement_version_services
      WHERE organization_id=org AND agreement_id=target_id AND revision=previous_revision;
  END IF;
END $$;


--
-- Name: service_agreements_guard_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_guard_file() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Service Agreement file bytes are immutable' USING ERRCODE='55000'; END IF;
  IF NEW.organization_id IS DISTINCT FROM public.organization_module_scope() OR NEW.uploaded_by IS DISTINCT FROM public.service_agreements_require_writer()
    OR NEW.uploaded_at IS DISTINCT FROM transaction_timestamp() THEN
    RAISE EXCEPTION 'Service Agreement files require their actual upload actor and transaction' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: service_agreements_guard_head(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_guard_head() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Retire Service Agreements without removing history' USING ERRCODE='55000'; END IF;
  IF (NEW.organization_id,NEW.id,NEW.created_at) IS DISTINCT FROM (OLD.organization_id,OLD.id,OLD.created_at) THEN
    RAISE EXCEPTION 'Service Agreement identity is immutable' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: service_agreements_guard_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_guard_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.service_agreement_versions; head public.service_agreements;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Service Agreement history is immutable' USING ERRCODE='55000'; END IF;
  SELECT * INTO head FROM public.service_agreements WHERE organization_id=NEW.organization_id AND id=NEW.agreement_id;
  IF TG_TABLE_NAME='service_agreement_versions' THEN version:=NEW;
  ELSE SELECT * INTO version FROM public.service_agreement_versions WHERE organization_id=NEW.organization_id AND agreement_id=NEW.agreement_id AND revision=NEW.revision; END IF;
  IF version.agreement_id IS NULL OR head.id IS NULL OR version.created_transaction_id IS DISTINCT FROM pg_current_xact_id()
    OR version.saved_at IS DISTINCT FROM transaction_timestamp() OR version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
    OR NEW.organization_id IS DISTINCT FROM public.organization_module_scope() OR head.revision IS DISTINCT FROM NEW.revision
    OR head.save_request_id IS DISTINCT FROM version.request_id THEN
    RAISE EXCEPTION 'Service Agreement history requires the actual saved command' USING ERRCODE='23514',CONSTRAINT='service_agreement_history_transaction';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: service_agreements_guard_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_guard_reference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_TABLE_NAME='vendors' THEN
    IF EXISTS (SELECT 1 FROM public.service_agreements WHERE organization_id=NEW.organization_id AND vendor_id=NEW.id AND NOT retired) THEN
      RAISE EXCEPTION 'Vendor is used by a Service Agreement' USING ERRCODE='23514',CONSTRAINT='vendor_in_use';
    END IF;
  ELSE
    IF EXISTS (SELECT 1 FROM public.service_agreements agreement JOIN public.service_agreement_version_instruments selection
      ON selection.organization_id=agreement.organization_id AND selection.agreement_id=agreement.id AND selection.revision=agreement.revision
      WHERE agreement.organization_id=NEW.organization_id AND NOT agreement.retired AND selection.instrument_id=NEW.id) THEN
      RAISE EXCEPTION 'Instrument is used by a Service Agreement' USING ERRCODE='23514',CONSTRAINT='instrument_in_use';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: service_agreements_prior_request(uuid, integer, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_prior_request(target_id uuid, expected_revision integer, requested_id uuid, fingerprint text, requested_operation text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE actor uuid:=public.service_agreements_require_writer(); org uuid:=public.organization_module_scope(); prior public.service_agreement_versions;
BEGIN
  IF target_id IS NULL OR expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 2147483646 OR requested_id IS NULL
    OR fingerprint IS NULL OR fingerprint !~ '^[a-f0-9]{64}$' OR requested_operation IS NULL OR requested_operation NOT IN ('create','update','retire')
    OR (requested_operation='create') IS DISTINCT FROM (expected_revision=0) THEN
    RAISE EXCEPTION 'Invalid Service Agreement command' USING ERRCODE='23514',CONSTRAINT='service_agreement_command_input';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('service-agreement-save:'||org::text||':'||requested_id::text,0));
  SELECT * INTO prior FROM public.service_agreement_versions WHERE organization_id=org AND request_id=requested_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF (prior.agreement_id,coalesce(prior.previous_revision,0),prior.operation,prior.request_fingerprint,prior.saved_by)
    IS DISTINCT FROM (target_id,expected_revision,requested_operation,fingerprint,actor) THEN
    RAISE EXCEPTION 'Service Agreement request was already used for another change' USING ERRCODE='23514',CONSTRAINT='service_agreement_request_reused';
  END IF;
  RETURN prior.revision;
END $_$;


--
-- Name: service_agreements_record(uuid, integer, text, text, integer, text, integer, integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_record(target_id uuid, previous_revision integer, operation text, fingerprint text, vendor_revision integer, vendor_name text, instrument_count integer, service_count integer, instruments_provided boolean, services_provided boolean) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  INSERT INTO public.service_agreement_versions(organization_id,agreement_id,revision,vendor_id,start_date,end_date,no_of_services,cost,notes,in_effect,attachment_file_id,retired,
    vendor_revision,vendor_name,request_id,request_fingerprint,previous_revision,operation,instrument_count,service_count,instruments_provided,services_provided,saved_by)
  SELECT head.organization_id,head.id,head.revision,head.vendor_id,head.start_date,head.end_date,head.no_of_services,head.cost,head.notes,head.in_effect,head.attachment_file_id,head.retired,
    vendor_revision,vendor_name,head.save_request_id,fingerprint,previous_revision,operation,instrument_count,service_count,instruments_provided,services_provided,
    nullif(current_setting('app.user_id',true),'')::uuid
  FROM public.service_agreements head WHERE head.organization_id=public.organization_module_scope() AND head.id=target_id;
$$;


--
-- Name: service_agreements_require_writer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_require_writer() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  PERFORM public.masters_lock_field_writer();
  RETURN public.organization_require_module_access('service_agreements');
END $$;


--
-- Name: service_agreements_retire(uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_retire(target_id uuid, expected_revision integer, requested_id uuid, fingerprint text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=public.organization_module_scope(); prior integer; head public.service_agreements; version public.service_agreement_versions;
BEGIN
  prior:=public.service_agreements_prior_request(target_id,expected_revision,requested_id,fingerprint,'retire'); IF prior IS NOT NULL THEN RETURN prior; END IF;
  SELECT * INTO head FROM public.service_agreements WHERE organization_id=org AND id=target_id FOR UPDATE;
  IF head.id IS NULL OR head.retired THEN RAISE EXCEPTION 'Service Agreement was not found' USING ERRCODE='P0002',CONSTRAINT='service_agreement_not_found'; END IF;
  IF head.revision<>expected_revision THEN
    RAISE EXCEPTION 'Service Agreement changed; reload before deleting' USING ERRCODE='23514',CONSTRAINT='service_agreement_stale_revision';
  END IF;
  SELECT * INTO version FROM public.service_agreement_versions WHERE organization_id=org AND agreement_id=target_id AND revision=expected_revision;
  UPDATE public.service_agreements SET retired=true,in_effect=false,revision=revision+1,save_request_id=requested_id,updated_at=transaction_timestamp()
    WHERE organization_id=org AND id=target_id;
  PERFORM public.service_agreements_record(target_id,expected_revision,'retire',fingerprint,version.vendor_revision,version.vendor_name,version.instrument_count,version.service_count,false,false);
  PERFORM public.service_agreements_copy_relations(target_id,expected_revision,expected_revision+1,true,true);
  RETURN expected_revision+1;
END $$;


--
-- Name: service_agreements_save(uuid, integer, uuid, text, uuid, date, date, integer, numeric, text, boolean, uuid, uuid[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_save(target_id uuid, expected_revision integer, requested_id uuid, fingerprint text, p_vendor_id uuid, p_start_date date, p_end_date date, p_no_of_services integer, p_cost numeric, p_notes text, p_in_effect boolean, p_file_id uuid, p_instruments uuid[], p_services text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=public.organization_module_scope(); prior integer; head public.service_agreements; version public.service_agreement_versions;
  vendor public.vendors; instrument_count integer; service_count integer; next_revision integer:=expected_revision+1;
BEGIN
  prior:=public.service_agreements_prior_request(target_id,expected_revision,requested_id,fingerprint,CASE WHEN expected_revision=0 THEN 'create' ELSE 'update' END);
  IF prior IS NOT NULL THEN RETURN prior; END IF;
  SELECT * INTO head FROM public.service_agreements WHERE organization_id=org AND id=target_id FOR UPDATE;
  IF expected_revision>0 AND (head.id IS NULL OR head.retired) THEN
    RAISE EXCEPTION 'Service Agreement was not found' USING ERRCODE='P0002',CONSTRAINT='service_agreement_not_found';
  END IF;
  IF coalesce(head.revision,0)<>expected_revision THEN
    RAISE EXCEPTION 'Service Agreement changed; reload before saving' USING ERRCODE='23514',CONSTRAINT='service_agreement_stale_revision';
  END IF;
  IF p_vendor_id IS NULL OR p_start_date IS NULL OR p_end_date IS NULL OR p_no_of_services IS NULL OR p_no_of_services<0
    OR p_cost IS NULL OR p_cost<0 OR p_cost IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) OR p_in_effect IS NULL
    OR (p_instruments IS NULL AND expected_revision=0)
    OR (p_instruments IS NOT NULL AND (cardinality(p_instruments) NOT BETWEEN 1 AND 500 OR array_ndims(p_instruments) IS DISTINCT FROM 1 OR array_position(p_instruments,NULL) IS NOT NULL
      OR cardinality(p_instruments)<>(SELECT count(DISTINCT id) FROM unnest(p_instruments) selection(id))))
    OR (p_services IS NOT NULL AND (cardinality(p_services)>3 OR (cardinality(p_services)>0 AND array_ndims(p_services) IS DISTINCT FROM 1)
      OR EXISTS (SELECT 1 FROM unnest(p_services) selection(code) WHERE code IS NULL OR code NOT IN ('calibration','preventivemaintenance','breakdown'))
      OR cardinality(p_services)<>(SELECT count(DISTINCT code) FROM unnest(p_services) selection(code)))) THEN
    RAISE EXCEPTION 'Check Service Agreement details and selections' USING ERRCODE='23514',CONSTRAINT='service_agreement_command_input';
  END IF;
  SELECT * INTO vendor FROM public.vendors WHERE organization_id=org AND id=p_vendor_id FOR SHARE;
  IF vendor.id IS NULL OR vendor.retired THEN
    RAISE EXCEPTION 'Select an available Vendor in this organization' USING ERRCODE='23514',CONSTRAINT='service_agreement_reference';
  END IF;
  IF p_instruments IS NOT NULL THEN
    PERFORM 1 FROM public.instruments WHERE organization_id=org AND id=ANY(p_instruments) ORDER BY id FOR SHARE;
    IF EXISTS (SELECT 1 FROM unnest(p_instruments) selected(id) WHERE NOT EXISTS (
      SELECT 1 FROM public.instruments instrument WHERE instrument.organization_id=org AND instrument.id=selected.id AND NOT instrument.retired)) THEN
      RAISE EXCEPTION 'Select available Instruments in this organization' USING ERRCODE='23514',CONSTRAINT='service_agreement_reference';
    END IF;
  END IF;
  IF p_file_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.service_agreement_files WHERE organization_id=org AND id=p_file_id) THEN
    RAISE EXCEPTION 'Select an Agreement attachment in this organization' USING ERRCODE='23514',CONSTRAINT='service_agreement_reference';
  END IF;
  IF expected_revision>0 THEN SELECT * INTO version FROM public.service_agreement_versions WHERE organization_id=org AND agreement_id=target_id AND revision=expected_revision; END IF;
  instrument_count:=coalesce(cardinality(p_instruments),version.instrument_count);
  service_count:=coalesce(cardinality(p_services),version.service_count,0);
  IF expected_revision=0 THEN
    INSERT INTO public.service_agreements(organization_id,id,vendor_id,start_date,end_date,no_of_services,cost,notes,in_effect,attachment_file_id,save_request_id)
      VALUES(org,target_id,p_vendor_id,p_start_date,p_end_date,p_no_of_services,p_cost,p_notes,p_in_effect,p_file_id,requested_id);
  ELSE
    UPDATE public.service_agreements SET vendor_id=p_vendor_id,start_date=p_start_date,end_date=p_end_date,no_of_services=p_no_of_services,cost=p_cost,notes=p_notes,
      in_effect=p_in_effect,attachment_file_id=p_file_id,revision=next_revision,save_request_id=requested_id,updated_at=transaction_timestamp()
      WHERE organization_id=org AND id=target_id;
  END IF;
  PERFORM public.service_agreements_record(target_id,CASE WHEN expected_revision=0 THEN NULL ELSE expected_revision END,
    CASE WHEN expected_revision=0 THEN 'create' ELSE 'update' END,fingerprint,vendor.revision,vendor.name,instrument_count,service_count,p_instruments IS NOT NULL,p_services IS NOT NULL);
  IF expected_revision>0 THEN PERFORM public.service_agreements_copy_relations(target_id,expected_revision,next_revision,p_instruments IS NULL,p_services IS NULL); END IF;
  IF p_instruments IS NOT NULL THEN
    INSERT INTO public.service_agreement_version_instruments(organization_id,agreement_id,revision,instrument_id,position,instrument_revision,instrument_name,instrument_code)
      SELECT org,target_id,next_revision,instrument.id,selection.position-1,instrument.revision,instrument.name,instrument.code
      FROM unnest(p_instruments) WITH ORDINALITY selection(id,position) JOIN public.instruments instrument ON instrument.organization_id=org AND instrument.id=selection.id;
  END IF;
  IF p_services IS NOT NULL THEN
    INSERT INTO public.service_agreement_version_services(organization_id,agreement_id,revision,service_code,position)
      SELECT org,target_id,next_revision,code,position-1 FROM unnest(p_services) WITH ORDINALITY selection(code,position);
  END IF;
  RETURN next_revision;
END $$;


--
-- Name: service_agreements_upload_file(uuid, text, text, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_agreements_upload_file(target_id uuid, file_name text, file_type text, file_content bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=public.service_agreements_require_writer(); org uuid:=public.organization_module_scope(); prior public.service_agreement_files; digest text;
BEGIN
  IF target_id IS NULL OR file_content IS NULL OR octet_length(file_content) NOT BETWEEN 1 AND 26214400 THEN
    RAISE EXCEPTION 'Invalid Service Agreement file' USING ERRCODE='23514',CONSTRAINT='service_agreement_file_values';
  END IF;
  digest:=encode(sha256(file_content),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended('service-agreement-file:'||org::text||':'||target_id::text,0));
  SELECT original_name,media_type,byte_length,sha256,uploaded_by INTO prior.original_name,prior.media_type,prior.byte_length,prior.sha256,prior.uploaded_by
    FROM public.service_agreement_files WHERE organization_id=org AND id=target_id;
  IF FOUND THEN
    IF (prior.original_name,prior.media_type,prior.byte_length,prior.sha256,prior.uploaded_by)
      IS DISTINCT FROM (file_name,file_type,octet_length(file_content),digest,actor) THEN
      RAISE EXCEPTION 'Service Agreement file request reused' USING ERRCODE='23514',CONSTRAINT='service_agreement_file_request_reused';
    END IF;
    RETURN true;
  END IF;
  INSERT INTO public.service_agreement_files(organization_id,id,original_name,media_type,content,byte_length,sha256,uploaded_by)
    VALUES(org,target_id,file_name,file_type,file_content,octet_length(file_content),digest,actor);
  RETURN false;
END $$;


--
-- Name: template_check_image_config(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_check_image_config() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid; ver uuid; field uuid;
BEGIN
  IF TG_OP='DELETE' THEN org:=OLD.organization_id; ver:=OLD.version_id; field:=OLD.field_id;
  ELSE org:=NEW.organization_id; ver:=NEW.version_id;
    IF TG_TABLE_NAME='template_fields' THEN field:=NEW.id; ELSE field:=NEW.field_id; END IF;
  END IF;
  IF EXISTS (SELECT 1 FROM public.template_fields f WHERE f.organization_id=org AND f.version_id=ver AND f.id=field AND f.widget='template_image_widget')
    AND NOT EXISTS (SELECT 1 FROM public.template_image_config c WHERE c.organization_id=org AND c.version_id=ver AND c.field_id=field) THEN
    RAISE EXCEPTION 'Template image requires its typed layout configuration' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: template_check_parameter_detail_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_check_parameter_detail_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF (SELECT count(*) FROM public.template_values value WHERE value.organization_id=NEW.organization_id
    AND value.instance_id=NEW.instance_id AND value.revision=NEW.revision AND value.origin='parameter')<>NEW.parameter_detail_field_count THEN
    RAISE EXCEPTION 'Parameter detail refresh must record every selected field' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: template_check_parameter_detail_value(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_check_parameter_detail_value() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE bound_specification uuid; sheet public.datasheets; parent_request public.test_requests;
  item_count integer; first_position integer; last_position integer; payload_bytes bigint;
BEGIN
  WITH RECURSIVE ancestors AS (
    SELECT occurrence.id,occurrence.parent_id,0 AS depth FROM public.template_occurrences occurrence
      WHERE occurrence.organization_id=NEW.organization_id AND occurrence.instance_id=NEW.instance_id AND occurrence.id=NEW.occurrence_id
    UNION ALL SELECT parent.id,parent.parent_id,child.depth+1 FROM public.template_occurrences parent JOIN ancestors child ON child.parent_id=parent.id
      WHERE parent.organization_id=NEW.organization_id AND parent.instance_id=NEW.instance_id AND child.depth<64
  ) SELECT subject.specification_id INTO bound_specification FROM ancestors JOIN public.datasheet_subjects subject
    ON subject.organization_id=NEW.organization_id AND subject.instance_id=NEW.instance_id AND subject.occurrence_id=ancestors.id
    ORDER BY ancestors.depth LIMIT 1;
  IF bound_specification IS NULL THEN
    SELECT * INTO sheet FROM public.datasheets WHERE organization_id=NEW.organization_id AND template_instance_id=NEW.instance_id;
    IF sheet.id IS NOT NULL THEN
      SELECT * INTO parent_request FROM public.test_requests WHERE organization_id=NEW.organization_id AND id=sheet.test_request_id;
      IF NOT parent_request.is_job THEN bound_specification:=sheet.specification_id;
      ELSIF (SELECT count(DISTINCT test.test_parameter_id) FROM public.sample_tests test
        JOIN public.sample_products product ON product.organization_id=test.organization_id AND product.id=test.sample_product_id
        JOIN public.sample_products job_product ON job_product.organization_id=product.organization_id AND job_product.sample_id=product.sample_id
        WHERE product.organization_id=NEW.organization_id AND job_product.id=parent_request.job_sample_product_id)=1
        AND (SELECT count(DISTINCT (specification.test_parameter_id,specification.parameter_revision))
        FROM public.test_requests child JOIN public.analytical_specifications specification
          ON specification.organization_id=child.organization_id AND specification.id=child.specification_id
        WHERE child.organization_id=NEW.organization_id AND child.parent_test_request_id=parent_request.id)=1
        AND EXISTS (SELECT 1 FROM public.test_requests child WHERE child.organization_id=NEW.organization_id
          AND child.parent_test_request_id=parent_request.id AND child.specification_id=NEW.parameter_detail_specification_id) THEN
        bound_specification:=NEW.parameter_detail_specification_id;
      END IF;
    END IF;
  END IF;
  IF bound_specification IS NULL OR bound_specification<>NEW.parameter_detail_specification_id THEN
    RAISE EXCEPTION 'Parameter detail must use its captured parameter binding' USING ERRCODE='23514';
  END IF;
  SELECT count(*),min(position),max(position),coalesce(sum(octet_length(coalesce(text_value,number_value::text,boolean_value::text,''))),0)
    INTO item_count,first_position,last_position,payload_bytes FROM public.template_parameter_detail_items
    WHERE organization_id=NEW.organization_id AND instance_id=NEW.instance_id AND field_id=NEW.field_id AND occurrence_id=NEW.occurrence_id AND revision=NEW.revision;
  IF item_count<>NEW.parameter_detail_item_count OR (item_count>0 AND (first_position<>0 OR last_position<>item_count-1)) OR payload_bytes>16777216 THEN
    RAISE EXCEPTION 'Parameter detail list must be complete, ordered and bounded' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: template_guard_definition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_guard_definition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid; ver uuid; state text;
BEGIN
  IF TG_OP = 'DELETE' THEN org := OLD.organization_id; ver := OLD.version_id;
  ELSE org := NEW.organization_id; ver := NEW.version_id; END IF;
  IF TG_OP = 'UPDATE' AND (NEW.organization_id, NEW.version_id) IS DISTINCT FROM (OLD.organization_id, OLD.version_id) THEN
    RAISE EXCEPTION 'Definition ownership is immutable' USING ERRCODE = '23514';
  END IF;
  SELECT status INTO state FROM public.template_versions WHERE organization_id = org AND id = ver FOR UPDATE;
  IF state IS DISTINCT FROM 'draft' AND (state IS DISTINCT FROM 'building' OR TG_OP <> 'INSERT') THEN
    RAISE EXCEPTION 'Only draft definitions may change' USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: template_guard_image_asset(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_guard_image_asset() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Template image bytes are immutable' USING ERRCODE='55000'; END IF;
  IF NEW.sha256<>encode(sha256(NEW.content),'hex') OR NEW.print_sha256<>encode(sha256(NEW.print_content),'hex')
    OR NEW.original_name ~ '[[:cntrl:]/\\]' OR NEW.original_name<>trim(NEW.original_name)
    OR substring(NEW.print_content FROM 1 FOR 8)<>decode('89504e470d0a1a0a','hex')
    OR (NEW.media_type='image/png' AND substring(NEW.content FROM 1 FOR 8)<>decode('89504e470d0a1a0a','hex'))
    OR (NEW.media_type='image/jpeg' AND substring(NEW.content FROM 1 FOR 3)<>decode('ffd8ff','hex'))
    OR (NEW.media_type='image/gif' AND substring(NEW.content FROM 1 FOR 6) NOT IN (convert_to('GIF87a','UTF8'),convert_to('GIF89a','UTF8')))
    OR (NEW.media_type='image/webp' AND (substring(NEW.content FROM 1 FOR 4)<>convert_to('RIFF','UTF8') OR substring(NEW.content FROM 9 FOR 4)<>convert_to('WEBP','UTF8'))) THEN
    RAISE EXCEPTION 'Template image content does not match its recorded metadata' USING ERRCODE='23514';
  END IF;
  IF current_user='sampleify_app' AND (NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR NEW.uploaded_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid OR NEW.uploaded_at IS DISTINCT FROM now()
    OR NOT public.app_has_permission('templates.manage')) THEN
    RAISE EXCEPTION 'Template image upload requires its actual tenant and actor' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: template_guard_inserted_values(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_guard_inserted_values() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE scope record; capture public.template_instances;
  invalid_occurrence boolean; invalid_formula boolean; invalid_image boolean; invalid_default boolean;
BEGIN
  FOR scope IN SELECT organization_id,instance_id FROM inserted_values
    GROUP BY organization_id,instance_id ORDER BY organization_id,instance_id LOOP
    SELECT * INTO capture FROM public.template_instances
      WHERE organization_id=scope.organization_id AND id=scope.instance_id FOR UPDATE;
    IF capture.status IS DISTINCT FROM 'editing' OR EXISTS (
      SELECT 1 FROM inserted_values value WHERE value.organization_id=scope.organization_id AND value.instance_id=scope.instance_id
        AND (value.version_id<>capture.version_id OR value.revision<>capture.revision)
    ) THEN
      RAISE EXCEPTION 'Value must use the editable capture version and current revision' USING ERRCODE='23514';
    END IF;
  END LOOP;
  SELECT bool_or(occurrence.id IS NULL OR field.id IS NULL OR occurrence.removed_revision IS NOT NULL
      OR field.repeat_group_id IS DISTINCT FROM occurrence.group_id),
    bool_or((field.widget='formula_widget') IS DISTINCT FROM (value.origin='calculated')),
    bool_or(field.widget='template_image_widget' AND value.origin<>'default'),
    bool_or(value.origin='default' AND (field.default_state='absent' OR occurrence.created_revision<>value.revision
      OR (value.state,value.number_value,value.text_value,value.boolean_value,value.date_value,value.option_id,value.image_id,value.lexical,value.error_code,value.error_message)
        IS DISTINCT FROM (field.default_state,field.default_number,field.default_text,field.default_boolean,field.default_date,NULL::uuid,field.default_image_id,field.default_lexical,NULL::text,NULL::text)))
    INTO invalid_occurrence,invalid_formula,invalid_image,invalid_default
    FROM inserted_values value
    LEFT JOIN LATERAL (
      SELECT id,group_id,removed_revision,created_revision FROM public.template_occurrences occurrence
      WHERE occurrence.organization_id=value.organization_id AND occurrence.instance_id=value.instance_id
        AND occurrence.version_id=value.version_id AND occurrence.id=value.occurrence_id LIMIT 1
    ) occurrence ON true
    LEFT JOIN LATERAL (
      SELECT id,repeat_group_id,widget,default_state,default_number,default_text,default_boolean,default_date,default_image_id,default_lexical
      FROM public.template_fields field WHERE field.organization_id=value.organization_id
        AND field.version_id=value.version_id AND field.id=value.field_id LIMIT 1
    ) field ON true;
  IF invalid_occurrence THEN RAISE EXCEPTION 'Value field and repeat occurrence do not match' USING ERRCODE='23514'; END IF;
  IF invalid_formula THEN RAISE EXCEPTION 'Calculated fields cannot accept entered values' USING ERRCODE='23514'; END IF;
  IF invalid_image THEN RAISE EXCEPTION 'Template images are frozen defaults' USING ERRCODE='23514'; END IF;
  IF invalid_default THEN RAISE EXCEPTION 'Default history must match its frozen field and new occurrence' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END $$;


--
-- Name: template_guard_instance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_guard_instance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Capture history cannot be deleted' USING ERRCODE = '55000'; END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'editing' OR NEW.revision <> 1 OR NOT EXISTS (SELECT 1 FROM public.template_versions
      WHERE organization_id = NEW.organization_id AND id = NEW.version_id AND status = 'frozen') THEN
      RAISE EXCEPTION 'Capture requires a frozen template and an initial editing revision' USING ERRCODE = '23514';
    END IF;
  ELSE
    IF OLD.status = 'frozen' THEN RAISE EXCEPTION 'Frozen capture is immutable' USING ERRCODE = '55000'; END IF;
    IF (NEW.organization_id, NEW.id, NEW.version_id, NEW.created_at, NEW.created_by)
      IS DISTINCT FROM (OLD.organization_id, OLD.id, OLD.version_id, OLD.created_at, OLD.created_by) OR NEW.revision <> OLD.revision + 1 THEN
      RAISE EXCEPTION 'Capture identity is immutable and revisions are sequential' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: template_guard_logical_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_guard_logical_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'template_expression_references' THEN
    IF (NEW.expression_id, NEW.alias) IS DISTINCT FROM (OLD.expression_id, OLD.alias) THEN
      RAISE EXCEPTION 'Expression reference identity is immutable' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME IN ('template_numeric_config','template_image_config') THEN
    IF NEW.field_id IS DISTINCT FROM OLD.field_id THEN RAISE EXCEPTION 'Configuration field identity is immutable' USING ERRCODE = '23514'; END IF;
  ELSE
    IF NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'Logical identity is immutable' USING ERRCODE = '23514'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: template_guard_occurrence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_guard_occurrence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE capture public.template_instances; parent public.template_occurrences; definition public.template_repeat_groups;
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Repeat history cannot be deleted' USING ERRCODE = '55000'; END IF;
  SELECT * INTO capture FROM public.template_instances WHERE organization_id = NEW.organization_id AND id = NEW.instance_id FOR UPDATE;
  IF capture.status IS DISTINCT FROM 'editing' OR capture.version_id <> NEW.version_id THEN
    RAISE EXCEPTION 'Repeat requires its editable capture version' USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.created_revision <> capture.revision THEN
    RAISE EXCEPTION 'Repeat creation revision must match capture' USING ERRCODE = '23514';
  END IF;
  IF TG_OP = 'UPDATE' AND ((NEW.organization_id, NEW.instance_id, NEW.version_id, NEW.id, NEW.group_id, NEW.parent_id, NEW.created_revision)
    IS DISTINCT FROM (OLD.organization_id, OLD.instance_id, OLD.version_id, OLD.id, OLD.group_id, OLD.parent_id, OLD.created_revision)
    OR OLD.removed_revision IS NOT NULL OR NEW.removed_revision IS DISTINCT FROM capture.revision) THEN
    RAISE EXCEPTION 'Repeat identity and removal history are immutable' USING ERRCODE = '23514';
  END IF;
  IF NEW.group_id IS NOT NULL THEN
    SELECT * INTO definition FROM public.template_repeat_groups WHERE organization_id = NEW.organization_id AND version_id = NEW.version_id AND id = NEW.group_id;
    SELECT * INTO parent FROM public.template_occurrences WHERE organization_id = NEW.organization_id AND instance_id = NEW.instance_id AND version_id = NEW.version_id AND id = NEW.parent_id;
    IF definition.id IS NULL OR parent.id IS NULL OR parent.removed_revision IS NOT NULL OR parent.group_id IS DISTINCT FROM definition.parent_group_id THEN
      RAISE EXCEPTION 'Repeat ancestry does not match its definition' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'INSERT' AND (SELECT count(*) FROM public.template_occurrences WHERE organization_id = NEW.organization_id AND instance_id = NEW.instance_id
      AND parent_id = NEW.parent_id AND group_id = NEW.group_id AND removed_revision IS NULL) >= definition.maximum THEN
      RAISE EXCEPTION 'Repeat limit exceeded' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: template_guard_occurrence_position(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_guard_occurrence_position() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.position IS DISTINCT FROM OLD.position THEN
    RAISE EXCEPTION 'Repeat occurrence positions are immutable' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: template_guard_parameter_detail_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_guard_parameter_detail_item() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Parameter detail history is immutable' USING ERRCODE='55000'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.template_values value WHERE value.organization_id=NEW.organization_id AND value.instance_id=NEW.instance_id
    AND value.field_id=NEW.field_id AND value.occurrence_id=NEW.occurrence_id AND value.revision=NEW.revision
    AND value.value_type='parameter_detail' AND value.parameter_detail_kind='array' AND NEW.position<value.parameter_detail_item_count) THEN
    RAISE EXCEPTION 'Parameter detail item requires its captured list value' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: template_guard_product_detail_value(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_guard_product_detail_value() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
