--
-- Name: template_guard_value(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_guard_value() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE capture public.template_instances; occurrence public.template_occurrences; field public.template_fields;
BEGIN
  IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Saved values are append-only' USING ERRCODE = '55000'; END IF;
  SELECT * INTO capture FROM public.template_instances WHERE organization_id = NEW.organization_id AND id = NEW.instance_id FOR UPDATE;
  IF capture.status IS DISTINCT FROM 'editing' OR capture.version_id <> NEW.version_id OR capture.revision <> NEW.revision THEN
    RAISE EXCEPTION 'Value must use the editable capture version and current revision' USING ERRCODE = '23514';
  END IF;
  SELECT * INTO occurrence FROM public.template_occurrences WHERE organization_id = NEW.organization_id AND instance_id = NEW.instance_id AND version_id = NEW.version_id AND id = NEW.occurrence_id;
  SELECT * INTO field FROM public.template_fields WHERE organization_id = NEW.organization_id AND version_id = NEW.version_id AND id = NEW.field_id;
  IF occurrence.id IS NULL OR field.id IS NULL OR occurrence.removed_revision IS NOT NULL OR field.repeat_group_id IS DISTINCT FROM occurrence.group_id THEN
    RAISE EXCEPTION 'Value field and repeat occurrence do not match' USING ERRCODE = '23514';
  END IF;
  IF (field.widget = 'formula_widget') IS DISTINCT FROM (NEW.origin = 'calculated') THEN
    RAISE EXCEPTION 'Calculated fields cannot accept entered values' USING ERRCODE = '23514';
  END IF;
  IF field.widget='template_image_widget' AND NEW.origin<>'default' THEN
    RAISE EXCEPTION 'Template images are frozen defaults' USING ERRCODE='23514';
  END IF;
  IF NEW.origin='default' AND (field.default_state='absent' OR occurrence.created_revision<>NEW.revision
    OR (NEW.state,NEW.number_value,NEW.text_value,NEW.boolean_value,NEW.date_value,NEW.option_id,NEW.image_id,NEW.lexical,NEW.error_code,NEW.error_message)
      IS DISTINCT FROM (field.default_state,field.default_number,field.default_text,field.default_boolean,field.default_date,NULL::uuid,field.default_image_id,field.default_lexical,NULL::text,NULL::text)) THEN
    RAISE EXCEPTION 'Default history must match its frozen field and new occurrence' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: template_guard_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_guard_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status NOT IN ('draft', 'building') THEN
      RAISE EXCEPTION 'New versions start as drafts or internal snapshots' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'building' AND current_user <> (
      SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid = 'public.template_versions'::regclass
    ) THEN
      RAISE EXCEPTION 'Runtime snapshots require the controlled copy operation' USING ERRCODE = '42501';
    END IF;
    IF NEW.status = 'building' AND NOT EXISTS (SELECT 1 FROM public.template_versions
      WHERE organization_id = NEW.organization_id AND id = NEW.snapshot_source_id
        AND status = 'draft' AND revision = NEW.snapshot_source_revision) THEN
      RAISE EXCEPTION 'Snapshot source revision is unavailable' USING ERRCODE = '40001';
    END IF;
  ELSE
    IF OLD.status = 'frozen' THEN RAISE EXCEPTION 'Frozen template versions are immutable' USING ERRCODE = '55000'; END IF;
    IF OLD.status = 'building' AND (TG_OP = 'DELETE' OR NEW.status <> 'frozen') THEN
      RAISE EXCEPTION 'Internal snapshots must finish as frozen versions' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    IF (NEW.organization_id, NEW.id, NEW.template_id, NEW.number, NEW.created_by, NEW.created_at,
        NEW.source_version_id, NEW.snapshot_source_id, NEW.snapshot_source_revision)
      IS DISTINCT FROM (OLD.organization_id, OLD.id, OLD.template_id, OLD.number, OLD.created_by, OLD.created_at,
        OLD.source_version_id, OLD.snapshot_source_id, OLD.snapshot_source_revision) THEN
      RAISE EXCEPTION 'Template version identity is immutable' USING ERRCODE = '23514';
    END IF;
    IF NEW.revision <> OLD.revision + 1 THEN RAISE EXCEPTION 'Template changes require the next revision' USING ERRCODE = '23514'; END IF;
  END IF;
  IF NEW.source_version_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.template_versions
    WHERE organization_id = NEW.organization_id AND id = NEW.source_version_id AND status = 'frozen') THEN
    RAISE EXCEPTION 'Source version must be frozen' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: template_guard_vertical_text_value(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_guard_vertical_text_value() RETURNS trigger
    LANGUAGE plpgsql
