    AND field.version_id=NEW.version_id AND field.id=NEW.field_id AND field.widget='vertical_text_widget') THEN
    RAISE EXCEPTION 'Vertical Text cannot accept captured values' USING ERRCODE='23514',CONSTRAINT='vertical_text_readonly';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: template_notify_version_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_notify_version_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.revision IS DISTINCT FROM OLD.revision THEN
    PERFORM pg_notify('template_designer_events', json_build_object(
      'organizationId', NEW.organization_id,
      'templateId', NEW.template_id,
      'templateVersionId', NEW.id,
      'revision', NEW.revision
    )::text);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: template_record_capture_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_record_capture_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE detail_request uuid; detail_count integer;
BEGIN
  IF TG_OP='UPDATE' AND NEW.id=nullif(current_setting('app.parameter_detail_capture_id',true),'')::uuid THEN
    detail_request:=nullif(current_setting('app.parameter_detail_request_id',true),'')::uuid;
    detail_count:=nullif(current_setting('app.parameter_detail_field_count',true),'')::integer;
  END IF;
  INSERT INTO public.template_capture_revisions(organization_id,instance_id,revision,status,transaction_id,recorded_by,database_role,recorded_at,
    parameter_detail_request_id,parameter_detail_field_count)
    VALUES(NEW.organization_id,NEW.id,NEW.revision,NEW.status,pg_current_xact_id(),
      nullif(current_setting('app.user_id',true),'')::uuid,session_user,transaction_timestamp(),detail_request,detail_count);
  RETURN NULL;
END $$;


--
-- Name: template_require_current_capture_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_require_current_capture_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE selected_revision integer;
BEGIN
  IF TG_TABLE_NAME IN ('template_values','template_parameter_detail_items') THEN selected_revision:=NEW.revision;
  ELSIF TG_OP='INSERT' THEN selected_revision:=NEW.created_revision;
  ELSE selected_revision:=NEW.removed_revision;
  END IF;
  IF session_user='sampleify_app' AND NOT EXISTS (
    SELECT 1 FROM public.template_capture_revisions revision
    WHERE revision.organization_id=NEW.organization_id AND revision.instance_id=NEW.instance_id
      AND revision.revision=selected_revision AND revision.status='editing' AND revision.transaction_id=pg_current_xact_id()
      AND revision.recorded_by=nullif(current_setting('app.user_id',true),'')::uuid
  ) THEN RAISE EXCEPTION 'Capture changes must belong to a revision created by this transaction' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: template_require_value_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_require_value_actor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF session_user='sampleify_app' AND (NEW.saved_by,NEW.saved_at) IS DISTINCT FROM
    (nullif(current_setting('app.user_id',true),'')::uuid,transaction_timestamp()) THEN
    RAISE EXCEPTION 'Saved values require the actual actor and transaction time' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: template_snapshot_finished(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_snapshot_finished() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.template_versions WHERE organization_id = NEW.organization_id AND id = NEW.id AND status = 'building') THEN
    RAISE EXCEPTION 'An unfinished runtime snapshot cannot be committed' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: template_snapshot_from_draft(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.template_snapshot_from_draft(source_id uuid, expected_revision integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE org uuid := nullif(current_setting('app.organization_id', true), '')::uuid;
  actor uuid := nullif(current_setting('app.user_id', true), '')::uuid;
  source public.template_versions; snapshot_id uuid; template_id uuid; relation text; column_names text;
BEGIN
  IF org IS NULL OR actor IS NULL OR NOT (
    public.app_has_permission('templates.manage') OR public.app_has_permission('test_requests.allocate')
    OR public.app_has_permission('samples.manage') OR public.app_has_permission('datasheets.execute')
    OR coalesce((SELECT v.template_id FROM public.template_versions v WHERE v.organization_id=org AND v.id=source_id)=public.laboratory_auto_job_template(),false)
  ) THEN RAISE EXCEPTION 'Runtime snapshot permission required' USING ERRCODE = '42501'; END IF;
  SELECT v.template_id INTO template_id FROM public.template_versions v WHERE v.organization_id = org AND v.id = source_id;
  PERFORM 1 FROM public.templates t WHERE t.organization_id = org AND t.id = template_id AND t.active FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Template is unavailable' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO source FROM public.template_versions v WHERE v.organization_id = org AND v.id = source_id FOR UPDATE;
  IF source.status <> 'draft' OR source.revision IS DISTINCT FROM expected_revision THEN
    RAISE EXCEPTION 'Template revision changed' USING ERRCODE = '40001';
  END IF;
  SELECT v.id INTO snapshot_id FROM public.template_versions v WHERE v.organization_id = org
    AND v.snapshot_source_id = source.id AND v.snapshot_source_revision = source.revision AND v.status = 'frozen';
  IF snapshot_id IS NOT NULL THEN RETURN snapshot_id; END IF;
  INSERT INTO public.template_versions (organization_id, template_id, number, status, name, description, kind,
    template_type, semantics, created_by, snapshot_source_id, snapshot_source_revision, header_document_id, footer_document_id, nabl_header_document_id, nabl_footer_document_id)
    SELECT org, source.template_id, coalesce(max(v.number), 0) + 1, 'building', source.name, source.description, source.kind,
      source.template_type, source.semantics, actor, source.id, source.revision, source.header_document_id, source.footer_document_id, source.nabl_header_document_id, source.nabl_footer_document_id
    FROM public.template_versions v WHERE v.organization_id = org AND v.template_id = source.template_id RETURNING id INTO snapshot_id;
  -- Only these definition tables are copied. Column identifiers come from PostgreSQL's
  -- catalog, never request data; new typed scalar columns are copied with their version.
  FOREACH relation IN ARRAY ARRAY['template_sections', 'template_rows', 'template_columns', 'template_repeat_groups',
    'template_fields', 'template_numeric_config', 'template_image_config', 'template_options', 'template_expressions', 'template_expression_references',
    'template_field_role_access'] LOOP
    SELECT string_agg(format('%I', attname), ', ' ORDER BY attnum) INTO column_names FROM pg_attribute
      WHERE attrelid = format('public.%I', relation)::regclass AND attnum > 0 AND NOT attisdropped
        AND attname NOT IN ('organization_id', 'version_id') AND attgenerated = '';
    EXECUTE format('INSERT INTO public.%I (organization_id, version_id, %s)
      SELECT $1, $2, %s FROM public.%I WHERE organization_id = $1 AND version_id = $3', relation, column_names, column_names, relation)
      USING org, snapshot_id, source.id;
  END LOOP;
  UPDATE public.template_versions SET status = 'frozen', revision = revision + 1, frozen_at = now(), frozen_by = actor
    WHERE organization_id = org AND id = snapshot_id;
  RETURN snapshot_id;
END $_$;


--
-- Name: users_assert_custom_field_uniqueness(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_assert_custom_field_uniqueness(target_organization uuid, target_user uuid, target_revision integer) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- Keep primary-key lookups parameterized even before a new organization's statistics are collected.
  IF NOT EXISTS (
    SELECT 1 FROM public.user_version_custom_fields field JOIN LATERAL (
      SELECT 1 FROM public.custom_field_versions definition
      WHERE definition.organization_id=field.organization_id AND definition.field_id=field.field_id
        AND definition.revision=field.field_revision AND definition.validate_uniqueness LIMIT 1
    ) definition ON true
    WHERE field.organization_id=target_organization AND field.subject_user_id=target_user AND field.revision=target_revision
  ) THEN RETURN; END IF;
  IF EXISTS (
    SELECT field.field_id,public.masters_product_custom_field_unique_text(field.is_array,value.raw_kind,value.raw_text,value.raw_number,value.raw_boolean,value.raw_number_text)
    FROM public.user_version_custom_fields field JOIN LATERAL (
      SELECT 1 FROM public.custom_field_versions definition
      WHERE definition.organization_id=field.organization_id AND definition.field_id=field.field_id
        AND definition.revision=field.field_revision AND definition.validate_uniqueness LIMIT 1
    ) definition ON true
    JOIN LATERAL (
      SELECT raw_kind,raw_text,raw_number,raw_boolean,raw_number_text FROM public.user_version_custom_field_values value
      WHERE value.organization_id=field.organization_id AND value.subject_user_id=field.subject_user_id
        AND value.revision=field.revision AND value.field_id=field.field_id OFFSET 0
    ) value ON true
    WHERE field.organization_id=target_organization AND field.subject_user_id=target_user AND field.revision=target_revision
      AND public.masters_product_custom_field_unique_text(field.is_array,value.raw_kind,value.raw_text,value.raw_number,value.raw_boolean,value.raw_number_text) IS NOT NULL
    GROUP BY field.field_id,public.masters_product_custom_field_unique_text(field.is_array,value.raw_kind,value.raw_text,value.raw_number,value.raw_boolean,value.raw_number_text)
    HAVING count(*)>1
  ) THEN RAISE EXCEPTION 'A unique Custom Field contains duplicate values' USING ERRCODE='23514',CONSTRAINT='user_custom_field_unique'; END IF;
  IF EXISTS (
    -- Normalize each bounded incoming item once before probing all historical definitions with its saved key.
    WITH incoming AS MATERIALIZED (
      SELECT definition.key,
        public.masters_product_custom_field_unique_text(field.is_array,value.raw_kind,value.raw_text,value.raw_number,value.raw_boolean,value.raw_number_text) AS text
      FROM public.user_version_custom_fields field JOIN LATERAL (
        SELECT key FROM public.custom_field_versions definition
        WHERE definition.organization_id=field.organization_id AND definition.field_id=field.field_id
          AND definition.revision=field.field_revision AND definition.validate_uniqueness LIMIT 1
      ) definition ON true
      JOIN LATERAL (
        SELECT raw_kind,raw_text,raw_number,raw_boolean,raw_number_text FROM public.user_version_custom_field_values value
        WHERE value.organization_id=field.organization_id AND value.subject_user_id=field.subject_user_id
          AND value.revision=field.revision AND value.field_id=field.field_id OFFSET 0
      ) value ON true
      WHERE field.organization_id=target_organization AND field.subject_user_id=target_user AND field.revision=target_revision
    )
    SELECT 1 FROM incoming JOIN LATERAL (
      SELECT field_id,revision FROM public.custom_field_versions saved_definition
      WHERE saved_definition.organization_id=target_organization AND saved_definition.key=incoming.key OFFSET 0
    ) saved_definition ON true
    JOIN LATERAL (
      SELECT subject_user_id,revision FROM public.user_version_custom_field_values existing
      WHERE existing.organization_id=target_organization AND existing.field_id=saved_definition.field_id
        AND existing.raw_text IS NOT NULL AND md5(existing.raw_text)=md5(incoming.text) AND existing.raw_text=incoming.text
        AND existing.subject_user_id<>target_user OFFSET 0
    ) existing ON true
    JOIN LATERAL (
      SELECT 1 FROM public.user_version_custom_fields saved_field
      WHERE saved_field.organization_id=target_organization AND saved_field.field_id=saved_definition.field_id
        AND saved_field.subject_user_id=existing.subject_user_id AND saved_field.revision=existing.revision
        AND saved_field.field_revision=saved_definition.revision LIMIT 1
    ) saved_field ON true
    JOIN LATERAL (
      SELECT 1 FROM public.memberships member
      WHERE member.organization_id=target_organization AND member.user_id=existing.subject_user_id
        AND member.custom_field_revision=existing.revision LIMIT 1
    ) member ON true
    WHERE incoming.text IS NOT NULL
  ) THEN RAISE EXCEPTION 'A unique Custom Field value is already in use' USING ERRCODE='23514',CONSTRAINT='user_custom_field_unique'; END IF;
END $$;


--
-- Name: users_assert_custom_fields(uuid, uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_assert_custom_fields(target_organization uuid, target_user uuid, target_revision integer, check_definition_set boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.user_field_value_versions; field_count integer; minimum_position integer; maximum_position integer; item_count integer;
BEGIN
  SELECT * INTO version FROM public.user_field_value_versions
    WHERE organization_id=target_organization AND subject_user_id=target_user AND revision=target_revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'User Custom Field history is missing' USING ERRCODE='23514',CONSTRAINT='user_custom_field_complete'; END IF;
  SELECT count(*),min(position),max(position),coalesce(sum(value_count),0) INTO field_count,minimum_position,maximum_position,item_count
    FROM public.user_version_custom_fields
    WHERE organization_id=target_organization AND subject_user_id=target_user AND revision=target_revision;
  IF field_count<>version.custom_field_count OR item_count>5000
    OR (field_count>0 AND (minimum_position<>0 OR maximum_position<>field_count-1)) THEN
    RAISE EXCEPTION 'User Custom Fields require a complete ordered version' USING ERRCODE='23514',CONSTRAINT='user_custom_field_complete';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.user_version_custom_fields field LEFT JOIN LATERAL (
      SELECT count(*) AS count,min(position) AS minimum,max(position) AS maximum
      FROM public.user_version_custom_field_values value
      WHERE value.organization_id=field.organization_id AND value.subject_user_id=field.subject_user_id
        AND value.revision=field.revision AND value.field_id=field.field_id
    ) items ON true
    WHERE field.organization_id=target_organization AND field.subject_user_id=target_user AND field.revision=target_revision
      AND (items.count<>field.value_count OR (items.count>0 AND (items.minimum<>0 OR items.maximum<>items.count-1)))
  ) THEN RAISE EXCEPTION 'User Custom Field items require a complete ordered version' USING ERRCODE='23514',CONSTRAINT='user_custom_value_complete'; END IF;
    IF check_definition_set AND (EXISTS (
      SELECT id,revision FROM public.custom_field_definitions WHERE organization_id=target_organization AND active AND associated_with='users'
      EXCEPT SELECT field_id,field_revision FROM public.user_version_custom_fields
        WHERE organization_id=target_organization AND subject_user_id=target_user AND revision=target_revision
    ) OR EXISTS (
      SELECT field_id,field_revision FROM public.user_version_custom_fields
        WHERE organization_id=target_organization AND subject_user_id=target_user AND revision=target_revision
      EXCEPT SELECT id,revision FROM public.custom_field_definitions WHERE organization_id=target_organization AND active AND associated_with='users'
    )) THEN RAISE EXCEPTION 'User Custom Field definitions changed' USING ERRCODE='23514',CONSTRAINT='user_custom_field_definition_set'; END IF;
    IF EXISTS (
      SELECT 1 FROM public.user_version_custom_fields field JOIN public.custom_field_versions definition
        ON definition.organization_id=field.organization_id AND definition.field_id=field.field_id AND definition.revision=field.field_revision
      WHERE field.organization_id=target_organization AND field.subject_user_id=target_user AND field.revision=target_revision AND definition.is_required
      AND NOT (
        (field.is_array AND definition.field_type<>'multi_user_select'
          AND (NOT definition.allows_multiple OR definition.field_type='attachment'))
        OR EXISTS (
        SELECT 1 FROM public.user_version_custom_field_values value
        WHERE value.organization_id=field.organization_id AND value.subject_user_id=field.subject_user_id AND value.revision=field.revision AND value.field_id=field.field_id
          AND CASE
            WHEN definition.field_type='multi_user_select'
              OR (definition.allows_multiple AND definition.field_type IN ('select','lookup')) THEN field.is_array
            WHEN definition.allows_multiple AND definition.field_type<>'attachment' AND NOT field.is_array THEN false
            WHEN NOT field.is_array THEN value.raw_kind<>'text' OR value.raw_text<>''
            WHEN value.raw_kind='boolean' THEN value.raw_boolean
            WHEN value.raw_kind='number' THEN true
            ELSE public.masters_custom_field_trim(value.raw_text)<>''
          END
        )
      )
    ) THEN RAISE EXCEPTION 'A required User Custom Field is empty' USING ERRCODE='23514',CONSTRAINT='user_custom_field_required'; END IF;
  IF (version.time_zone IS NOT NULL) IS DISTINCT FROM EXISTS (
    SELECT 1 FROM public.user_version_custom_fields WHERE organization_id=target_organization AND subject_user_id=target_user
      AND revision=target_revision AND field_type IN ('date','date_time')
  ) THEN RAISE EXCEPTION 'Capture time zone requires its date fields' USING ERRCODE='23514',CONSTRAINT='user_custom_field_timezone'; END IF;
END $$;


--
-- Name: users_assert_profile(uuid, uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_assert_profile(org uuid, target uuid, target_revision integer, check_head boolean) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.user_profile_versions; head public.user_profiles; role_ids uuid[]; selected_count integer;
BEGIN
  SELECT * INTO version FROM public.user_profile_versions WHERE organization_id=org AND user_id=target AND revision=target_revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'Profile revision is missing' USING ERRCODE='23514'; END IF;
  SELECT array_agg(role_id ORDER BY role_id),count(*) FILTER (WHERE explicitly_selected)::integer INTO role_ids,selected_count
    FROM public.user_profile_version_roles WHERE organization_id=org AND user_id=target AND revision=target_revision;
  IF coalesce(cardinality(role_ids),0)<>version.role_count OR NOT version.default_role_id=ANY(role_ids)
    OR (version.roles_provided AND selected_count NOT BETWEEN 1 AND 100) OR (NOT version.roles_provided AND selected_count<>0)
    OR (version.previous_revision IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.user_profile_versions
      WHERE organization_id=org AND user_id=target AND revision=version.previous_revision)) THEN
    RAISE EXCEPTION 'Profile history requires its prior revision and complete role observations' USING ERRCODE='23514';
  END IF;
  IF check_head THEN
    SELECT * INTO head FROM public.user_profiles WHERE organization_id=org AND user_id=target;
    IF (head.revision,head.employee_code,head.phone,head.designation,head.can_manage_people,head.business_unit_id,head.default_role_id,head.laboratory_id,head.reporting_manager_id)
      IS DISTINCT FROM (version.revision,version.employee_code,version.phone,version.designation,version.can_manage_people,version.business_unit_id,version.default_role_id,version.laboratory_id,version.reporting_manager_id)
      OR role_ids IS DISTINCT FROM ARRAY(SELECT role_id FROM public.membership_roles WHERE organization_id=org AND user_id=target ORDER BY role_id) THEN
      RAISE EXCEPTION 'Current profile and role assignments must match their saved revision' USING ERRCODE='23514';
    END IF;
  END IF;
END $$;


--
-- Name: users_assert_saved_field_uniqueness(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_assert_saved_field_uniqueness(target_organization uuid, target_user uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- Omission preserves the saved dictionary but source users.update validates its keys against current unique definitions.
  IF EXISTS (
    WITH incoming AS MATERIALIZED (
      SELECT saved_definition.key,
        public.masters_product_custom_field_unique_text(field.is_array,value.raw_kind,value.raw_text,value.raw_number,value.raw_boolean,value.raw_number_text) AS text
      FROM public.memberships member JOIN public.user_version_custom_fields field
        ON field.organization_id=member.organization_id AND field.subject_user_id=member.user_id AND field.revision=member.custom_field_revision
      JOIN public.custom_field_versions saved_definition ON saved_definition.organization_id=field.organization_id
        AND saved_definition.field_id=field.field_id AND saved_definition.revision=field.field_revision
      JOIN public.custom_field_definitions current_definition ON current_definition.organization_id=field.organization_id
        AND current_definition.key=saved_definition.key AND current_definition.active AND current_definition.associated_with='users' AND current_definition.validate_uniqueness
      JOIN public.user_version_custom_field_values value ON value.organization_id=field.organization_id AND value.subject_user_id=field.subject_user_id
        AND value.revision=field.revision AND value.field_id=field.field_id
      WHERE member.organization_id=target_organization AND member.user_id=target_user
    )
    SELECT 1 FROM incoming WHERE text IS NOT NULL GROUP BY key,text HAVING count(*)>1
    UNION ALL
    SELECT 1 FROM incoming
    JOIN public.custom_field_versions saved_definition ON saved_definition.organization_id=target_organization AND saved_definition.key=incoming.key
    JOIN public.user_version_custom_fields field ON field.organization_id=saved_definition.organization_id
      AND field.field_id=saved_definition.field_id AND field.field_revision=saved_definition.revision
    JOIN public.memberships member ON member.organization_id=field.organization_id AND member.user_id=field.subject_user_id AND member.custom_field_revision=field.revision
    JOIN public.user_version_custom_field_values value ON value.organization_id=field.organization_id AND value.subject_user_id=field.subject_user_id
      AND value.revision=field.revision AND value.field_id=field.field_id AND value.raw_text IS NOT NULL
      AND md5(value.raw_text)=md5(incoming.text) AND value.raw_text=incoming.text
    WHERE incoming.text IS NOT NULL AND field.subject_user_id<>target_user
  ) THEN RAISE EXCEPTION 'A unique Custom Field value is already in use' USING ERRCODE='23514',CONSTRAINT='user_custom_field_unique'; END IF;
END $$;


--
-- Name: users_begin_field_capture(uuid, integer, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_begin_field_capture(target uuid, expected_revision integer, requested_id uuid, requested_count integer, requested_zone text) RETURNS TABLE(saved_revision integer, replayed boolean, previous_field_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; actor uuid; prior public.user_field_value_versions;
  head_revision integer; old_count integer:=0; definition_count integer;
BEGIN
  actor:=public.users_require_manager();
  IF target IS NULL OR expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 2147483646 OR requested_id IS NULL
    OR requested_count IS NULL OR requested_count NOT BETWEEN 0 AND 500
    OR (requested_zone IS NOT NULL AND (requested_count=0 OR length(requested_zone) NOT BETWEEN 1 AND 100)) THEN
    RAISE EXCEPTION 'Invalid user field capture' USING ERRCODE='23514',CONSTRAINT='user_custom_field_invalid_input';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=target) THEN
    RAISE EXCEPTION 'User was not found' USING ERRCODE='P0002',CONSTRAINT='user_profile_not_found';
  END IF;
  -- Definition writers hold their advisory lock before acquiring organization foreign-key locks.
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('custom-field-definitions:'||org::text,0));
  actor:=public.users_require_manager();
  PERFORM 1 FROM public.users WHERE id=ANY(ARRAY[actor,target]) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
  PERFORM 1 FROM public.memberships WHERE organization_id=org AND user_id=ANY(ARRAY[actor,target]) ORDER BY user_id FOR SHARE;
  PERFORM 1 FROM public.sessions WHERE id=nullif(current_setting('app.session_id',true),'')::uuid FOR SHARE;
  actor:=public.users_require_manager();
  SELECT * INTO prior FROM public.user_field_value_versions WHERE organization_id=org AND request_id=requested_id;
  IF FOUND THEN
    IF (prior.subject_user_id,prior.saved_by,prior.previous_revision,prior.custom_field_count,prior.time_zone)
      IS DISTINCT FROM (target,actor,expected_revision,requested_count,requested_zone) THEN
      RAISE EXCEPTION 'Save request already used for another capture' USING ERRCODE='23514',CONSTRAINT='user_custom_field_request_reused';
    END IF;
    -- The service compares the complete immutable raw values before accepting a replay.
    RETURN QUERY SELECT prior.revision,true,NULL::integer; RETURN;
  END IF;
  SELECT custom_field_revision INTO head_revision FROM public.memberships WHERE organization_id=org AND user_id=target;
  IF NOT FOUND THEN RAISE EXCEPTION 'User was not found' USING ERRCODE='P0002',CONSTRAINT='user_profile_not_found'; END IF;
  IF head_revision<>expected_revision THEN
    RAISE EXCEPTION 'User fields changed; reload before saving' USING ERRCODE='23514',CONSTRAINT='user_custom_field_stale';
  END IF;
  IF head_revision>0 THEN
    SELECT custom_field_count INTO old_count FROM public.user_field_value_versions WHERE organization_id=org AND subject_user_id=target AND revision=head_revision;
    IF NOT FOUND THEN RAISE EXCEPTION 'User field history is missing' USING ERRCODE='23514',CONSTRAINT='user_custom_field_complete'; END IF;
    PERFORM public.users_assert_custom_fields(org,target,head_revision);
  END IF;
  SELECT count(*) INTO definition_count FROM public.custom_field_definitions WHERE organization_id=org AND active AND associated_with='users';
  IF definition_count>500 THEN RAISE EXCEPTION 'This form supports at most 500 Custom Fields' USING ERRCODE='23514',CONSTRAINT='user_custom_field_limit'; END IF;
  IF definition_count<>requested_count THEN
    RAISE EXCEPTION 'Provide the current user Custom Fields' USING ERRCODE='23514',CONSTRAINT='user_custom_field_definition_set';
  END IF;
  UPDATE public.memberships SET custom_field_revision=expected_revision+1 WHERE organization_id=org AND user_id=target;
  INSERT INTO public.user_field_value_versions(organization_id,subject_user_id,revision,previous_revision,request_id,custom_field_count,time_zone,
    username,display_name,saved_by,saved_by_username,saved_by_name)
    SELECT org,target,expected_revision+1,expected_revision,requested_id,requested_count,requested_zone,person.username,person.display_name,
      actor,editor.username,editor.display_name FROM public.users person JOIN public.users editor ON editor.id=actor WHERE person.id=target;
  RETURN QUERY SELECT expected_revision+1,false,old_count;
END $$;


--
-- Name: users_check_business_unit_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_check_business_unit_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- Preexisting support rows have no invented history. Once authored, every change must retain its actual version.
  IF EXISTS (SELECT 1 FROM public.business_unit_versions WHERE organization_id=NEW.organization_id AND unit_id=NEW.id)
    AND NOT EXISTS (SELECT 1 FROM public.business_units unit JOIN public.business_unit_versions version
      ON version.organization_id=unit.organization_id AND version.unit_id=unit.id AND version.revision=unit.revision
      WHERE unit.organization_id=NEW.organization_id AND unit.id=NEW.id
      AND version.created_transaction_id=pg_current_xact_id()
      AND (unit.code,unit.name,unit.description,unit.active,unit.updated_at)
        IS NOT DISTINCT FROM (version.code,version.name,version.description,version.active,version.saved_at)) THEN
    RAISE EXCEPTION 'Business unit changes require complete save history' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: users_check_custom_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_check_custom_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  PERFORM public.users_assert_custom_fields(NEW.organization_id,NEW.subject_user_id,NEW.revision,true);
  PERFORM public.users_assert_custom_field_uniqueness(NEW.organization_id,NEW.subject_user_id,NEW.revision);
  RETURN NULL;
END $$;


--
-- Name: users_check_laboratory_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_check_laboratory_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- Synthetic/imported support rows can predate authoring; only actual later saves create history.
  IF EXISTS (SELECT 1 FROM public.laboratory_versions WHERE organization_id=NEW.organization_id AND laboratory_id=NEW.id)
    AND NOT EXISTS (SELECT 1 FROM public.laboratories lab JOIN public.laboratory_versions version
      ON version.organization_id=lab.organization_id AND version.laboratory_id=lab.id AND version.revision=lab.revision
      WHERE lab.organization_id=NEW.organization_id AND lab.id=NEW.id AND version.created_transaction_id=pg_current_xact_id()
      AND (lab.code, lab.name, lab.description, lab.abbreviation, lab.business_unit_id, lab.head_user_id, lab.delegate_user_id, lab.minimum_temperature_text, lab.maximum_temperature_text, lab.minimum_humidity_text, lab.maximum_humidity_text, lab.active,lab.updated_at) IS NOT DISTINCT FROM (version.code, version.name, version.description, version.abbreviation, version.business_unit_id, version.head_user_id, version.delegate_user_id, version.minimum_temperature_text, version.maximum_temperature_text, version.minimum_humidity_text, version.maximum_humidity_text, version.active,version.saved_at)) THEN
    RAISE EXCEPTION 'Lab changes require complete save history' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: users_check_profile_complete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_check_profile_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid; target uuid; head_revision integer;
BEGIN
  org:=CASE WHEN TG_OP='DELETE' THEN OLD.organization_id ELSE NEW.organization_id END;
  target:=CASE WHEN TG_OP='DELETE' THEN OLD.user_id ELSE NEW.user_id END;
  SELECT revision INTO head_revision FROM public.user_profiles WHERE organization_id=org AND user_id=target;
  IF TG_TABLE_NAME='membership_roles' THEN
    -- A profile write already schedules full head/version assertions. Do not rescan the full role set once per assignment.
    IF head_revision IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.user_profile_versions
      WHERE organization_id=org AND user_id=target AND revision=head_revision AND created_transaction_id=pg_current_xact_id()) THEN
      RAISE EXCEPTION 'Role assignments require a new profile revision' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
  END IF;
  IF TG_TABLE_NAME='user_profile_versions' THEN
    PERFORM public.users_assert_profile(org,target,NEW.revision,head_revision=NEW.revision);
  ELSIF head_revision IS NOT NULL THEN PERFORM public.users_assert_profile(org,target,head_revision,true); END IF;
  RETURN NULL;
END $$;


--
-- Name: users_create_account(uuid, uuid, bytea, text, text, text, text, text, boolean, text, boolean, text, boolean, boolean, boolean, uuid, boolean, uuid, uuid, uuid, boolean, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_create_account(target uuid, requested_id uuid, requested_fingerprint bytea, requested_username text, requested_email text, requested_name text, requested_password_hash text, employee_code_value text, employee_code_provided boolean, phone_value text, phone_provided boolean, designation_value text, designation_provided boolean, can_manage_value boolean, can_manage_provided boolean, unit_value uuid, unit_provided boolean, default_role_value uuid, laboratory_value uuid, manager_value uuid, manager_provided boolean, selected_roles uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE actor uuid; org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; prior public.user_creation_commands; saved_revision integer;
BEGIN
  actor:=public.users_require_manager();
  IF target IS NULL OR requested_id IS NULL OR requested_fingerprint IS NULL OR octet_length(requested_fingerprint)<>32
    OR requested_username IS NULL OR length(requested_username) NOT BETWEEN 1 AND 100 OR requested_username<>trim(requested_username)
    OR requested_name IS NULL OR length(requested_name) NOT BETWEEN 1 AND 200 OR requested_name<>trim(requested_name)
    OR requested_email IS NULL OR length(requested_email) NOT BETWEEN 1 AND 320 OR requested_email<>trim(requested_email)
    OR requested_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
    OR requested_password_hash IS NULL OR requested_password_hash !~ '^scrypt[$]1[$]32768[$]8[$]1[$][A-Za-z0-9_-]{22}[$][A-Za-z0-9_-]{86}$'
    OR default_role_value IS NULL OR laboratory_value IS NULL THEN
    RAISE EXCEPTION 'Invalid new account' USING ERRCODE='23514',CONSTRAINT='user_creation_invalid_input';
  END IF;
  IF manager_value IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=manager_value) THEN
    RAISE EXCEPTION 'Reporting manager is unavailable' USING ERRCODE='23514',CONSTRAINT='user_profile_manager_unavailable';
  END IF;
  -- Take the definition lock before account/profile row locks, including on exact retries.
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('custom-field-definitions:'||org::text,0));
  actor:=public.users_require_manager();
  -- A new target is absent; an exact creation retry can compose a later field-capture command.
  -- Lock an existing scoped target with the actor/manager before the organization in both paths.
  PERFORM 1 FROM public.users WHERE id=ANY(ARRAY[actor,manager_value])
    OR (id=target AND EXISTS (SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=target))
    ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
  PERFORM 1 FROM public.memberships WHERE organization_id=org AND user_id=ANY(ARRAY[actor,manager_value]) ORDER BY user_id FOR SHARE;
  PERFORM 1 FROM public.sessions WHERE id=nullif(current_setting('app.session_id',true),'')::uuid FOR SHARE;
  actor:=public.users_require_manager();
  SELECT * INTO prior FROM public.user_creation_commands WHERE organization_id=org AND request_id=requested_id;
  IF FOUND THEN
    IF prior.user_id<>target OR prior.created_by<>actor OR prior.fingerprint<>requested_fingerprint
      OR (prior.username,prior.email,prior.display_name) IS DISTINCT FROM (requested_username,requested_email,requested_name) THEN
      RAISE EXCEPTION 'Creation request already used for a different account' USING ERRCODE='23514',CONSTRAINT='user_creation_request_reused';
    END IF;
    RETURN prior.profile_revision;
  END IF;
  IF EXISTS (SELECT 1 FROM public.users WHERE id=target) THEN
    RAISE EXCEPTION 'Account identity already exists' USING ERRCODE='23514',CONSTRAINT='user_creation_identity_exists';
  END IF;
  PERFORM public.auth_lock_login_aliases(ARRAY[requested_username,requested_email]);
  actor:=public.users_require_manager();
  IF EXISTS (SELECT 1 FROM public.users WHERE lower(username)=ANY(ARRAY[lower(requested_username),lower(requested_email)])
    OR lower(email)=ANY(ARRAY[lower(requested_username),lower(requested_email)])) THEN
    RAISE EXCEPTION 'A sign-in identifier is already in use' USING ERRCODE='23514',CONSTRAINT='user_creation_identifier_taken';
  END IF;
  INSERT INTO public.users(id,username,email,display_name) VALUES(target,requested_username,requested_email,requested_name);
  INSERT INTO public.credentials(user_id,password_hash) VALUES(target,requested_password_hash);
  INSERT INTO public.memberships(organization_id,user_id,is_default) VALUES(org,target,true);
  saved_revision:=public.users_write_profile(target,0,requested_id,employee_code_value,employee_code_provided,phone_value,phone_provided,
    designation_value,designation_provided,can_manage_value,can_manage_provided,unit_value,unit_provided,default_role_value,true,laboratory_value,true,manager_value,manager_provided,selected_roles);
  INSERT INTO public.user_creation_commands(organization_id,user_id,request_id,fingerprint,profile_revision,username,email,display_name,created_by)
    VALUES(org,target,requested_id,requested_fingerprint,saved_revision,requested_username,requested_email,requested_name,actor);
  RETURN saved_revision;
END $_$;


--
-- Name: users_directory_organization(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_directory_organization() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT session.organization_id FROM public.sessions session
  JOIN public.users person ON person.id=session.user_id AND person.active AND NOT person.must_change_password
  JOIN public.credentials credential ON credential.user_id=person.id AND credential.revision=session.credential_revision
  JOIN public.memberships membership ON membership.organization_id=session.organization_id AND membership.user_id=person.id AND membership.active
  JOIN public.organizations organization ON organization.id=session.organization_id AND organization.active
  WHERE session.id=nullif(current_setting('app.session_id',true),'')::uuid
    AND session.user_id=nullif(current_setting('app.user_id',true),'')::uuid
    AND session.organization_id=nullif(current_setting('app.organization_id',true),'')::uuid
    AND session.revoked_at IS NULL AND session.expires_at>clock_timestamp()
    AND (public.app_has_permission('users.read') OR public.app_has_permission('users.manage'))
$$;


--
-- Name: users_guard_account_command(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_guard_account_command() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Account administration history is immutable' USING ERRCODE='55000'; END IF;
  IF NEW.saved_by IS DISTINCT FROM public.users_require_manager()
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR NEW.saved_at<>transaction_timestamp() OR NEW.created_transaction_id<>pg_current_xact_id()
    OR NOT EXISTS (
      SELECT 1 FROM public.users person JOIN public.credentials credential ON credential.user_id=person.id
      JOIN public.users actor ON actor.id=NEW.saved_by WHERE person.id=NEW.user_id
        AND (person.revision,person.username,person.email,person.display_name,credential.revision,actor.username,actor.display_name)
          IS NOT DISTINCT FROM (NEW.previous_revision,NEW.previous_username,NEW.previous_email,NEW.previous_display_name,NEW.previous_credential_revision,NEW.saved_by_username,NEW.saved_by_name)
    ) THEN RAISE EXCEPTION 'Account history requires the actual preceding identity and editor' USING ERRCODE='23514'; END IF;
  IF (NEW.form_profile_revision IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.user_profile_versions profile WHERE profile.organization_id=NEW.organization_id AND profile.user_id=NEW.user_id
      AND profile.revision=NEW.form_profile_revision AND profile.request_id=NEW.request_id AND profile.saved_by=NEW.saved_by
      AND profile.created_transaction_id=NEW.created_transaction_id
  )) OR (NEW.form_custom_field_revision IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.user_field_value_versions capture WHERE capture.organization_id=NEW.organization_id AND capture.subject_user_id=NEW.user_id
      AND capture.revision=NEW.form_custom_field_revision AND capture.request_id=NEW.request_id AND capture.saved_by=NEW.saved_by
      AND capture.created_transaction_id=NEW.created_transaction_id
  )) THEN RAISE EXCEPTION 'Form versions must belong to the same actual command' USING ERRCODE='23514',CONSTRAINT='user_account_request_reused'; END IF;
  RETURN NEW;
END $$;


--
-- Name: users_guard_business_unit_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_guard_business_unit_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Business unit history is immutable' USING ERRCODE='23514'; END IF;
  IF NEW.organization_id IS DISTINCT FROM public.users_directory_organization()
    OR NEW.saved_by IS DISTINCT FROM public.users_require_manager()
    OR NEW.saved_at IS DISTINCT FROM transaction_timestamp()
    OR NEW.created_transaction_id IS DISTINCT FROM pg_current_xact_id()
    OR NOT EXISTS (SELECT 1 FROM public.business_units unit JOIN public.users editor ON editor.id=NEW.saved_by
      WHERE unit.organization_id=NEW.organization_id AND unit.id=NEW.unit_id AND unit.revision=NEW.revision
      AND unit.updated_at=transaction_timestamp()
      AND (unit.code,unit.name,unit.description,unit.active,editor.username,editor.display_name)
        IS NOT DISTINCT FROM (NEW.code,NEW.name,NEW.description,NEW.active,NEW.saved_by_username,NEW.saved_by_name)) THEN
    RAISE EXCEPTION 'History must describe the actual current unit save' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: users_guard_creation_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_guard_creation_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Account creation history is immutable' USING ERRCODE='55000'; END IF;
  IF NEW.created_by IS DISTINCT FROM public.users_require_manager()
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR NEW.created_at<>transaction_timestamp() OR NEW.created_transaction_id<>pg_current_xact_id()
    OR NOT EXISTS (
      SELECT 1 FROM public.users person JOIN public.credentials credential ON credential.user_id=person.id
      JOIN public.memberships membership ON membership.user_id=person.id AND membership.organization_id=NEW.organization_id
      JOIN public.user_profile_versions profile ON profile.organization_id=membership.organization_id AND profile.user_id=person.id AND profile.revision=1
      WHERE person.id=NEW.user_id AND person.active AND NOT person.must_change_password AND person.revision=1
        AND membership.active AND membership.is_default AND credential.revision=1
        AND person.created_at=transaction_timestamp() AND membership.created_at=transaction_timestamp() AND credential.updated_at=transaction_timestamp()
        AND profile.saved_by=NEW.created_by AND profile.saved_at=transaction_timestamp() AND profile.created_transaction_id=pg_current_xact_id()
        AND profile.request_id=NEW.request_id AND profile.previous_revision IS NULL
        AND (person.username,person.email,person.display_name) IS NOT DISTINCT FROM (NEW.username,NEW.email,NEW.display_name)
    ) THEN RAISE EXCEPTION 'Creation history requires the actual new account, profile and creator transaction' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: users_guard_custom_field_head(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_guard_custom_field_head() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.custom_field_revision<>0 THEN RAISE EXCEPTION 'New memberships have no invented field captures' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.custom_field_revision=OLD.custom_field_revision THEN RETURN NEW; END IF;
  IF (NEW.organization_id,NEW.user_id) IS DISTINCT FROM (OLD.organization_id,OLD.user_id)
    OR OLD.custom_field_revision=2147483647 OR NEW.custom_field_revision<>OLD.custom_field_revision+1 THEN
    RAISE EXCEPTION 'A field capture requires its next membership revision' USING ERRCODE='23514';
  END IF;
  PERFORM public.users_require_manager();
  IF NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Field capture belongs to another organization' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: users_guard_custom_field_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_guard_custom_field_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE version public.user_field_value_versions; field public.user_version_custom_fields; definition public.custom_field_versions;
  related_count integer; previous_field_ids uuid[]; current_field_key text;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'User Custom Field history is immutable' USING ERRCODE='55000'; END IF;
  SELECT * INTO version FROM public.user_field_value_versions WHERE organization_id=NEW.organization_id AND subject_user_id=NEW.subject_user_id AND revision=NEW.revision;
  IF version.subject_user_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
    OR version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR NOT EXISTS (SELECT 1 FROM public.memberships WHERE organization_id=NEW.organization_id AND user_id=NEW.subject_user_id AND custom_field_revision=NEW.revision) THEN
    RAISE EXCEPTION 'User Custom Fields require their actual new version transaction' USING ERRCODE='23514',CONSTRAINT='user_custom_field_transaction';
  END IF;
  IF TG_TABLE_NAME='user_version_custom_fields' THEN
    IF NEW.position>=version.custom_field_count THEN RAISE EXCEPTION 'User Custom Field position exceeds its saved count' USING ERRCODE='23514'; END IF;
    SELECT * INTO definition FROM public.custom_field_versions
      WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=NEW.field_revision;
    IF NOT FOUND OR definition.field_type<>NEW.field_type THEN
      RAISE EXCEPTION 'User Custom Field type must match its definition' USING ERRCODE='23514',CONSTRAINT='user_custom_field_type';
    END IF;
    IF NEW.field_type IN ('date','date_time') AND NEW.time_zone IS DISTINCT FROM version.time_zone THEN
      RAISE EXCEPTION 'Date fields require their capture time zone' USING ERRCODE='23514',CONSTRAINT='user_custom_field_timezone';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.custom_field_definitions WHERE organization_id=NEW.organization_id AND id=NEW.field_id
        AND revision=NEW.field_revision AND associated_with='users' AND active
    ) THEN RAISE EXCEPTION 'Select the current User Custom Field revision' USING ERRCODE='23514',CONSTRAINT='user_custom_field_definition_set'; END IF;
  ELSE
    SELECT * INTO field FROM public.user_version_custom_fields
      WHERE organization_id=NEW.organization_id AND subject_user_id=NEW.subject_user_id AND revision=NEW.revision AND field_id=NEW.field_id;
    IF NOT FOUND OR NEW.position>=field.value_count THEN
      RAISE EXCEPTION 'User Custom Field items require their declared field and count' USING ERRCODE='23514',CONSTRAINT='user_custom_value_complete';
    END IF;
    IF field.is_array AND NEW.raw_kind='text' AND public.masters_custom_field_trim(NEW.raw_text)='' THEN
      RAISE EXCEPTION 'Remove blank repeated User Custom Field items' USING ERRCODE='23514';
    END IF;
    NEW.user_username:=NULL; NEW.user_name:=NULL;
    IF field.field_type='lookup' THEN
      SELECT * INTO definition FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      current_field_key:=definition.key;
    END IF;
    related_count := num_nonnulls(NEW.parsed_number,NEW.parsed_boolean,NEW.parsed_date,NEW.parsed_timestamp,NEW.option_id,NEW.option_revision,NEW.user_id,NEW.attachment_id,NEW.lookup_source_id,NEW.lookup_revision,NEW.lookup_line_id);
    IF version.previous_revision>0 AND (
      field.field_type='select' AND (NEW.interpretation_state='invalid' OR NEW.interpretation_state='valid' AND NEW.option_revision<>field.field_revision)
      OR field.field_type='attachment' AND NEW.interpretation_state='valid'
      OR field.field_type='lookup' AND NEW.interpretation_state='invalid'
    ) THEN
      -- Bound retained-item checks by saved-key field IDs before inspecting potentially thousands of prior items.
      IF current_field_key IS NULL THEN
        SELECT key INTO current_field_key FROM public.custom_field_versions
        WHERE organization_id=NEW.organization_id AND field_id=NEW.field_id AND revision=field.field_revision;
      END IF;
      WITH key_definitions AS MATERIALIZED (
        SELECT field_id,revision FROM public.custom_field_versions WHERE organization_id=NEW.organization_id AND key=current_field_key
      ) SELECT array_agg(previous_field.field_id) INTO previous_field_ids
        FROM key_definitions previous_definition JOIN LATERAL (
          -- Each captured field has one primary-key row; keep this lookup parameterized in cached plans.
          SELECT field_id FROM public.user_version_custom_fields
            WHERE organization_id=NEW.organization_id AND subject_user_id=NEW.subject_user_id AND revision=version.previous_revision
              AND field_id=previous_definition.field_id AND field_revision=previous_definition.revision LIMIT 1
        ) previous_field ON true;
    END IF;
    IF NEW.interpretation_state='valid' THEN
      CASE field.field_type
        WHEN 'number' THEN
          IF NEW.parsed_number IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A numeric field requires its typed numeric interpretation' USING ERRCODE='23514'; END IF;
        WHEN 'checkbox' THEN
          IF NEW.parsed_boolean IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A checkbox requires its typed boolean interpretation' USING ERRCODE='23514'; END IF;
        WHEN 'date' THEN
          IF NEW.parsed_date IS NULL OR NEW.parsed_timestamp IS NULL OR related_count<>2 THEN RAISE EXCEPTION 'A date requires its local date and parsed instant' USING ERRCODE='23514'; END IF;
        WHEN 'date_time' THEN
          IF NEW.parsed_timestamp IS NULL OR related_count<>1 THEN RAISE EXCEPTION 'A date-time field requires its parsed instant' USING ERRCODE='23514'; END IF;
        WHEN 'select' THEN
          IF NEW.option_id IS NULL OR NEW.option_revision IS NULL OR related_count<>2 OR NOT EXISTS (
            SELECT 1 FROM public.custom_field_version_options option WHERE option.organization_id=NEW.organization_id
              AND option.field_id=NEW.field_id AND option.revision=NEW.option_revision AND option.id=NEW.option_id
              AND option.key=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
          ) THEN RAISE EXCEPTION 'A selection requires its exact field option' USING ERRCODE='23514',CONSTRAINT='user_custom_value_option'; END IF;
          IF NEW.option_revision<>field.field_revision AND NOT EXISTS (
            SELECT 1 FROM public.user_version_custom_field_values previous
            WHERE previous.organization_id=NEW.organization_id AND previous.subject_user_id=NEW.subject_user_id AND previous.revision=version.previous_revision
              AND previous.field_id=ANY(previous_field_ids)
              AND previous.field_id=NEW.field_id AND previous.option_id=NEW.option_id AND previous.option_revision=NEW.option_revision
              AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
                IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
          ) THEN RAISE EXCEPTION 'An older selection must belong to the previous User revision' USING ERRCODE='23514',CONSTRAINT='user_custom_value_option'; END IF;
        WHEN 'multi_user_select' THEN
          IF NEW.user_id IS NULL OR related_count<>1 OR NEW.raw_kind<>'text' OR lower(NEW.raw_text)<>NEW.user_id::text THEN
            RAISE EXCEPTION 'A user selection requires its member reference' USING ERRCODE='23514',CONSTRAINT='user_custom_value_user';
          END IF;
          SELECT person.username,person.display_name INTO NEW.user_username,NEW.user_name
            FROM public.memberships member JOIN public.users person ON person.id=member.user_id
            WHERE member.organization_id=NEW.organization_id AND member.user_id=NEW.user_id;
          IF NOT FOUND THEN RAISE EXCEPTION 'Select users in this organization' USING ERRCODE='23514',CONSTRAINT='user_custom_value_user'; END IF;
        WHEN 'attachment' THEN
          IF NEW.attachment_id IS NULL OR related_count<>1 OR NEW.raw_kind<>'text' OR lower(NEW.raw_text)<>NEW.attachment_id::text OR NOT EXISTS (
            SELECT 1 FROM public.custom_field_attachments attachment JOIN public.custom_field_versions uploaded_definition
              ON uploaded_definition.organization_id=attachment.organization_id AND uploaded_definition.field_id=attachment.field_id AND uploaded_definition.revision=attachment.field_revision
              WHERE attachment.organization_id=NEW.organization_id AND attachment.id=NEW.attachment_id
                AND (attachment.field_id=NEW.field_id
                  -- The original uploaded definition records the draft's saved key even before its first capture.
                  OR uploaded_definition.key=coalesce(current_field_key, (
                    SELECT key FROM public.custom_field_versions WHERE organization_id=NEW.organization_id
                      AND field_id=NEW.field_id AND revision=field.field_revision
                  )) OR EXISTS (
                  SELECT 1 FROM public.user_version_custom_field_values previous
                  WHERE previous.organization_id=NEW.organization_id AND previous.subject_user_id=NEW.subject_user_id AND previous.revision=version.previous_revision
                    AND previous.field_id=ANY(previous_field_ids)
                    AND previous.attachment_id=NEW.attachment_id
                ))
                AND uploaded_definition.associated_with='users' AND uploaded_definition.field_type='attachment'
          ) THEN RAISE EXCEPTION 'An attachment must belong to its Custom Field' USING ERRCODE='23514',CONSTRAINT='user_custom_value_attachment'; END IF;
        WHEN 'lookup' THEN
          IF NEW.lookup_source_id IS NULL OR NEW.lookup_revision IS NULL OR NEW.lookup_line_id IS NULL OR related_count<>3
            OR definition.lookup_source_id IS DISTINCT FROM NEW.lookup_source_id
            OR NEW.lookup_line_id IS DISTINCT FROM (CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END)
            OR NOT EXISTS (
              SELECT 1 FROM public.custom_field_lookup_lines line JOIN public.custom_field_lookup_sources source
                ON source.organization_id=line.organization_id AND source.id=line.source_id AND source.revision=line.revision
              WHERE line.organization_id=NEW.organization_id AND line.source_id=NEW.lookup_source_id
                AND line.revision=NEW.lookup_revision AND line.original_line_id=NEW.lookup_line_id
            ) THEN RAISE EXCEPTION 'A lookup requires the current observed line of its field source' USING ERRCODE='23514',CONSTRAINT='user_custom_value_lookup'; END IF;
        ELSE
          IF related_count<>0 THEN RAISE EXCEPTION 'Text fields cannot contain another field type interpretation' USING ERRCODE='23514'; END IF;
      END CASE;
    ELSIF NEW.interpretation_state='invalid' AND field.field_type='select' THEN
      -- Preserve an unresolved previous raw value by saved key, without inventing a cross-definition option reference.
      IF EXISTS (
        SELECT 1 FROM public.custom_field_version_options option WHERE option.organization_id=NEW.organization_id
          AND option.field_id=NEW.field_id AND option.revision=field.field_revision
          AND option.key=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
      ) OR NOT EXISTS (
        SELECT 1 FROM public.user_version_custom_field_values previous
          WHERE previous.organization_id=NEW.organization_id AND previous.subject_user_id=NEW.subject_user_id AND previous.revision=version.previous_revision
          AND previous.field_id=ANY(previous_field_ids)
          AND (previous.field_id<>NEW.field_id OR previous.option_id IS NULL)
          AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
            IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
      ) THEN RAISE EXCEPTION 'An unresolved selection requires the same previous saved-key value' USING ERRCODE='23514',CONSTRAINT='user_custom_value_option'; END IF;
    ELSIF NEW.interpretation_state='invalid' AND field.field_type='lookup' THEN
      IF EXISTS (
        SELECT 1 FROM public.custom_field_lookup_lines line JOIN public.custom_field_lookup_sources source
          ON source.organization_id=line.organization_id AND source.id=line.source_id AND source.revision=line.revision
        WHERE line.organization_id=NEW.organization_id AND line.source_id=definition.lookup_source_id
          AND line.original_line_id=CASE NEW.raw_kind WHEN 'text' THEN NEW.raw_text WHEN 'number' THEN NEW.raw_number_text ELSE NEW.raw_boolean::text END
      ) OR NOT EXISTS (
        SELECT 1 FROM public.user_version_custom_field_values previous
          WHERE previous.organization_id=NEW.organization_id AND previous.subject_user_id=NEW.subject_user_id AND previous.revision=version.previous_revision
            AND previous.field_id=ANY(previous_field_ids)
            AND (previous.raw_kind,previous.raw_text,previous.raw_number,previous.raw_boolean,previous.raw_number_text)
              IS NOT DISTINCT FROM (NEW.raw_kind,NEW.raw_text,NEW.raw_number,NEW.raw_boolean,NEW.raw_number_text)
      ) THEN RAISE EXCEPTION 'An unavailable lookup requires the same previous saved-key value' USING ERRCODE='23514',CONSTRAINT='user_custom_value_lookup'; END IF;
    ELSIF NEW.interpretation_state IN ('invalid','out_of_range') AND field.field_type NOT IN ('number','date','date_time') THEN
      RAISE EXCEPTION 'Only numeric and date fields retain invalid interpretations' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: users_guard_custom_field_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_guard_custom_field_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'User field capture history is immutable' USING ERRCODE='55000'; END IF;
  IF NEW.saved_by IS DISTINCT FROM public.users_require_manager()
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR NEW.saved_at<>transaction_timestamp() OR NEW.created_transaction_id<>pg_current_xact_id()
    OR NOT EXISTS (
      SELECT 1 FROM public.memberships member JOIN public.users person ON person.id=member.user_id JOIN public.users editor ON editor.id=NEW.saved_by
      WHERE member.organization_id=NEW.organization_id AND member.user_id=NEW.subject_user_id AND member.custom_field_revision=NEW.revision
        AND (NEW.username,NEW.display_name,NEW.saved_by_username,NEW.saved_by_name)
          IS NOT DISTINCT FROM (person.username,person.display_name,editor.username,editor.display_name)
    ) OR (NEW.previous_revision>0 AND NOT EXISTS (
      SELECT 1 FROM public.user_field_value_versions WHERE organization_id=NEW.organization_id AND subject_user_id=NEW.subject_user_id AND revision=NEW.previous_revision
    )) THEN RAISE EXCEPTION 'A user capture requires its actual subject, editor and version transaction' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: users_guard_laboratory_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_guard_laboratory_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Laboratory history is immutable' USING ERRCODE='23514'; END IF;
  IF NEW.organization_id IS DISTINCT FROM public.users_directory_organization()
    OR NEW.saved_by IS DISTINCT FROM public.users_require_manager()
    OR NEW.saved_at IS DISTINCT FROM transaction_timestamp() OR NEW.created_transaction_id IS DISTINCT FROM pg_current_xact_id()
    OR NOT EXISTS (SELECT 1 FROM public.laboratories lab
      JOIN public.users editor ON editor.id=NEW.saved_by
      LEFT JOIN public.business_units unit ON unit.organization_id=lab.organization_id AND unit.id=lab.business_unit_id
      LEFT JOIN public.users hod ON hod.id=lab.head_user_id
      LEFT JOIN public.users delegate ON delegate.id=lab.delegate_user_id
      WHERE lab.organization_id=NEW.organization_id AND lab.id=NEW.laboratory_id AND lab.revision=NEW.revision AND lab.updated_at=transaction_timestamp()
      AND (lab.code, lab.name, lab.description, lab.abbreviation, lab.business_unit_id, lab.head_user_id, lab.delegate_user_id, lab.minimum_temperature_text, lab.maximum_temperature_text, lab.minimum_humidity_text, lab.maximum_humidity_text, lab.active,unit.code,unit.name,hod.username,hod.display_name,delegate.username,delegate.display_name,editor.username,editor.display_name)
        IS NOT DISTINCT FROM (NEW.code, NEW.name, NEW.description, NEW.abbreviation, NEW.business_unit_id, NEW.head_user_id, NEW.delegate_user_id, NEW.minimum_temperature_text, NEW.maximum_temperature_text, NEW.minimum_humidity_text, NEW.maximum_humidity_text, NEW.active,NEW.business_unit_code, NEW.business_unit_name, NEW.head_username, NEW.head_user_name, NEW.delegate_username, NEW.delegate_user_name,NEW.saved_by_username,NEW.saved_by_name)) THEN
    RAISE EXCEPTION 'History must describe the actual current Lab save' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: users_guard_membership_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_guard_membership_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.status_revision<>0 THEN RAISE EXCEPTION 'New memberships have no invented status history' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  IF (NEW.organization_id,NEW.user_id) IS DISTINCT FROM (OLD.organization_id,OLD.user_id) THEN
    RAISE EXCEPTION 'Membership identity cannot change' USING ERRCODE='55000';
  END IF;
  IF (NEW.active,NEW.status_revision) IS NOT DISTINCT FROM (OLD.active,OLD.status_revision) THEN RETURN NEW; END IF;
  -- Owner-only unrecorded observations remain importable. Restricted roles have no direct membership writes.
  IF OLD.status_revision=0 AND NEW.status_revision=0 THEN RETURN NEW; END IF;
  IF OLD.status_revision=2147483647 OR NEW.status_revision<>OLD.status_revision+1 OR NEW.active=OLD.active THEN
    RAISE EXCEPTION 'A recorded status change requires its next revision' USING ERRCODE='23514';
  END IF;
  IF NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR (public.users_require_manager()=NEW.user_id AND NOT NEW.active) THEN
    RAISE EXCEPTION 'Cannot disable yourself or change another organization' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: users_guard_profile_head(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_guard_profile_head() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Recorded profiles cannot be deleted' USING ERRCODE='55000'; END IF;
  PERFORM public.users_require_manager();
  IF NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR (TG_OP='INSERT' AND NEW.revision<>1)
    OR (TG_OP='UPDATE' AND ((NEW.organization_id,NEW.user_id) IS DISTINCT FROM (OLD.organization_id,OLD.user_id) OR NEW.revision<>OLD.revision+1)) THEN
    RAISE EXCEPTION 'Profile identity and consecutive revisions are required' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: users_guard_profile_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_guard_profile_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE head public.user_profiles; version public.user_profile_versions; role public.roles;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'User profile history is immutable' USING ERRCODE='55000'; END IF;
  IF TG_TABLE_NAME='user_profile_versions' THEN
    SELECT * INTO head FROM public.user_profiles WHERE organization_id=NEW.organization_id AND user_id=NEW.user_id;
    IF NEW.saved_by IS DISTINCT FROM public.users_require_manager()
      OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
      OR NEW.created_transaction_id<>pg_current_xact_id() OR NEW.saved_at<>transaction_timestamp()
      OR (NEW.revision,NEW.employee_code,NEW.phone,NEW.designation,NEW.can_manage_people,NEW.business_unit_id,NEW.default_role_id,NEW.laboratory_id,NEW.reporting_manager_id)
        IS DISTINCT FROM (head.revision,head.employee_code,head.phone,head.designation,head.can_manage_people,head.business_unit_id,head.default_role_id,head.laboratory_id,head.reporting_manager_id)
      OR NOT EXISTS (SELECT 1 FROM public.users editor JOIN public.laboratories lab ON lab.organization_id=NEW.organization_id AND lab.id=NEW.laboratory_id
        LEFT JOIN public.business_units unit ON unit.organization_id=NEW.organization_id AND unit.id=NEW.business_unit_id
        LEFT JOIN public.users manager ON manager.id=NEW.reporting_manager_id
        WHERE editor.id=NEW.saved_by AND
          (NEW.saved_by_username,NEW.saved_by_name,NEW.laboratory_code,NEW.laboratory_name,NEW.business_unit_code,NEW.business_unit_name,NEW.reporting_manager_username,NEW.reporting_manager_name)
          IS NOT DISTINCT FROM (editor.username,editor.display_name,lab.code,lab.name,unit.code,unit.name,manager.username,manager.display_name)) THEN
      RAISE EXCEPTION 'History requires the actual profile, actor, reference observations and save transaction' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO version FROM public.user_profile_versions WHERE organization_id=NEW.organization_id AND user_id=NEW.user_id AND revision=NEW.revision;
    SELECT * INTO role FROM public.roles WHERE organization_id=NEW.organization_id AND id=NEW.role_id;
    IF version.user_id IS NULL OR version.created_transaction_id<>pg_current_xact_id()
      OR version.saved_by IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
      OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
      OR (NEW.recorded_role_revision,NEW.name,NEW.description,NEW.active) IS DISTINCT FROM (nullif(role.revision,0),role.name,role.description,role.active)
      OR (NEW.explicitly_selected AND NOT version.roles_provided) THEN
      RAISE EXCEPTION 'Role observations require their actual profile revision transaction' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: users_guard_signature_head(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_guard_signature_head() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.signature_revision<>0 THEN RAISE EXCEPTION 'New memberships have no invented signature history' USING ERRCODE='23514'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.signature_revision=OLD.signature_revision THEN RETURN NEW; END IF;
  IF OLD.signature_revision=2147483647 OR NEW.signature_revision<>OLD.signature_revision+1 THEN
    RAISE EXCEPTION 'A signature change requires its next revision' USING ERRCODE='23514';
  END IF;
  PERFORM public.users_require_manager();
  IF NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Signature belongs to another organization' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: users_guard_signature_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_guard_signature_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Signature files and history are immutable' USING ERRCODE='55000'; END IF;
  IF NEW.saved_by IS DISTINCT FROM public.users_require_manager()
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR NEW.saved_at<>transaction_timestamp() OR NEW.created_transaction_id<>pg_current_xact_id()
    OR NOT EXISTS (
      SELECT 1 FROM public.memberships membership JOIN public.users person ON person.id=membership.user_id
      JOIN public.users editor ON editor.id=NEW.saved_by
      WHERE membership.organization_id=NEW.organization_id AND membership.user_id=NEW.user_id AND membership.signature_revision=NEW.revision
        AND (NEW.username,NEW.display_name,NEW.saved_by_username,NEW.saved_by_name)
          IS NOT DISTINCT FROM (person.username,person.display_name,editor.username,editor.display_name)
    ) OR (NEW.previous_revision>0 AND NOT EXISTS (
      SELECT 1 FROM public.user_signature_versions previous WHERE previous.organization_id=NEW.organization_id AND previous.user_id=NEW.user_id
        AND previous.revision=NEW.previous_revision AND (NEW.operation<>'remove' OR previous.operation='upload')
    )) OR (NEW.previous_revision=0 AND NEW.operation='remove') THEN
    RAISE EXCEPTION 'Signature history requires the actual preceding file selection and editor' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: users_guard_status_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_guard_status_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Membership status history is immutable' USING ERRCODE='55000'; END IF;
  IF NEW.saved_by IS DISTINCT FROM public.users_require_manager()
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR NEW.saved_at<>transaction_timestamp() OR NEW.created_transaction_id<>pg_current_xact_id()
    OR NOT EXISTS (
      SELECT 1 FROM public.memberships membership JOIN public.users person ON person.id=membership.user_id
      JOIN public.users editor ON editor.id=NEW.saved_by
      WHERE membership.organization_id=NEW.organization_id AND membership.user_id=NEW.user_id
        AND membership.status_revision=NEW.revision AND membership.active=NEW.active
        AND (NEW.username,NEW.display_name,NEW.saved_by_username,NEW.saved_by_name)
          IS NOT DISTINCT FROM (person.username,person.display_name,editor.username,editor.display_name)
    ) THEN RAISE EXCEPTION 'Status history requires the actual membership change and editor' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: users_prepare_field_form(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_prepare_field_form() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  PERFORM public.users_require_manager();
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('custom-field-definitions:'||nullif(current_setting('app.organization_id',true),'')::uuid::text,0));
  PERFORM public.users_require_manager();
END $$;


--
-- Name: users_require_account_result(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_require_account_result() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.users person JOIN public.credentials credential ON credential.user_id=person.id
    WHERE person.id=NEW.user_id AND (person.revision,person.username,person.email,person.display_name,credential.revision)
      IS NOT DISTINCT FROM (NEW.revision,NEW.username,NEW.email,NEW.display_name,NEW.credential_revision)
      AND (NOT NEW.password_changed OR (NOT person.must_change_password
        AND NOT EXISTS (SELECT 1 FROM public.sessions session WHERE session.user_id=person.id AND session.revoked_at IS NULL)
        AND NOT EXISTS (SELECT 1 FROM public.password_resets reset WHERE reset.user_id=person.id AND reset.used_at IS NULL)))
  ) THEN RAISE EXCEPTION 'Account command requires its complete identity and credential result' USING ERRCODE='23514'; END IF;
  IF (NEW.form_profile_revision IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.user_profiles profile WHERE profile.organization_id=NEW.organization_id AND profile.user_id=NEW.user_id AND profile.revision=NEW.form_profile_revision
  )) OR (NEW.form_custom_field_revision IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.memberships member WHERE member.organization_id=NEW.organization_id AND member.user_id=NEW.user_id AND member.custom_field_revision=NEW.form_custom_field_revision
  )) THEN RAISE EXCEPTION 'Form command requires its complete profile and field result' USING ERRCODE='23514',CONSTRAINT='user_account_request_reused'; END IF;
  RETURN NULL;
END $$;


--
-- Name: users_require_custom_field_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_require_custom_field_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.custom_field_revision IS DISTINCT FROM OLD.custom_field_revision AND NOT EXISTS (
    SELECT 1 FROM public.user_field_value_versions WHERE organization_id=NEW.organization_id AND subject_user_id=NEW.user_id
      AND revision=NEW.custom_field_revision AND previous_revision=OLD.custom_field_revision AND created_transaction_id=pg_current_xact_id()
  ) THEN RAISE EXCEPTION 'Membership fields require their actual capture event' USING ERRCODE='23514',CONSTRAINT='user_custom_field_complete'; END IF;
  RETURN NULL;
END $$;


--
-- Name: users_require_manager(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_require_manager() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
BEGIN
  IF public.users_directory_organization() IS NULL OR NOT public.app_has_permission('users.manage') THEN
    RAISE EXCEPTION 'Active user management session required' USING ERRCODE='42501',CONSTRAINT='user_profile_session_required';
  END IF;
  RETURN actor;
END $$;


--
-- Name: users_require_signature_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_require_signature_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.signature_revision IS DISTINCT FROM OLD.signature_revision AND NOT EXISTS (
    SELECT 1 FROM public.user_signature_versions version WHERE version.organization_id=NEW.organization_id AND version.user_id=NEW.user_id
      AND version.revision=NEW.signature_revision AND version.previous_revision=OLD.signature_revision AND version.created_transaction_id=pg_current_xact_id()
  ) THEN RAISE EXCEPTION 'Membership signature requires its actual immutable event' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END $$;


--
-- Name: users_require_status_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_require_status_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.status_revision>0 AND NEW.status_revision IS DISTINCT FROM OLD.status_revision AND NOT EXISTS (
    SELECT 1 FROM public.user_status_versions version WHERE version.organization_id=NEW.organization_id AND version.user_id=NEW.user_id
      AND version.revision=NEW.status_revision AND version.previous_revision=OLD.status_revision
      AND version.active=NEW.active AND version.previous_active=OLD.active AND version.created_transaction_id=pg_current_xact_id()
  ) THEN RAISE EXCEPTION 'Membership status requires its actual immutable transition' USING ERRCODE='23514'; END IF;
  RETURN NULL;
END $$;


--
-- Name: users_scheme_context(boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_scheme_context(include_users boolean, include_samples boolean) RETURNS TABLE("currentYearDigits" text, "nextYearDigits" text, separator text, "currentMonthFormat" text, "nonNablStartNumber" text, "userCount" double precision, "sampleCount" double precision)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=public.users_directory_organization();
BEGIN
  IF org IS NULL OR NOT public.app_has_permission('users.manage') THEN
    RAISE EXCEPTION 'User scheme generation requires permission' USING ERRCODE='42501';
  END IF;
  RETURN QUERY SELECT settings.scheme_current_year_digits,settings.scheme_next_year_digits,settings.scheme_separator,
    settings.scheme_month_format,settings.scheme_non_nabl_start_number,
    CASE WHEN include_users THEN (SELECT count(*)::double precision FROM public.memberships member WHERE member.organization_id=org) ELSE 0::double precision END,
    CASE WHEN include_samples THEN (SELECT count(*)::double precision FROM public.samples sample WHERE sample.organization_id=org) ELSE 0::double precision END
  FROM public.organizations organization LEFT JOIN public.organization_laboratory_settings settings ON settings.organization_id=organization.id
  WHERE organization.id=org;
END $$;


--
-- Name: users_upload_field_attachment(uuid, uuid, integer, text, text, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_upload_field_attachment(requested_id uuid, target_field uuid, expected_revision integer, requested_name text, requested_type text, requested_content bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; actor uuid; prior record;
  definition public.custom_field_definitions; requested_sha256 text; requested_length integer;
BEGIN
  actor:=public.users_require_manager();
  IF requested_id IS NULL OR target_field IS NULL OR expected_revision IS NULL OR expected_revision NOT BETWEEN 1 AND 2147483647
    OR requested_name IS NULL OR requested_type IS NULL OR requested_content IS NULL OR octet_length(requested_content)>20971520 THEN
    RAISE EXCEPTION 'Invalid user field attachment' USING ERRCODE='23514',CONSTRAINT='user_field_attachment_invalid_input';
  END IF;
  -- Master uploads acquire this same request namespace before their organization FK locks.
  PERFORM pg_advisory_xact_lock(hashtextextended('custom-field-upload:'||org::text||':'||requested_id::text,0));
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('custom-field-definitions:'||org::text,0));
  actor:=public.users_require_manager();
  PERFORM 1 FROM public.users WHERE id=actor FOR UPDATE;
  PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
  PERFORM 1 FROM public.memberships WHERE organization_id=org AND user_id=actor FOR SHARE;
  PERFORM 1 FROM public.sessions WHERE id=nullif(current_setting('app.session_id',true),'')::uuid FOR SHARE;
  actor:=public.users_require_manager();
  requested_sha256:=encode(sha256(requested_content),'hex'); requested_length:=octet_length(requested_content);
  -- Compare the actual digest without selecting an old binary payload. Retry precedes current-field checks.
  SELECT file.field_id,file.field_revision,file.original_name,file.media_type,file.byte_length,file.sha256,file.uploaded_by,
    version.associated_with INTO prior FROM public.custom_field_attachments file JOIN public.custom_field_versions version
      ON version.organization_id=file.organization_id AND version.field_id=file.field_id AND version.revision=file.field_revision
    WHERE file.organization_id=org AND file.id=requested_id;
  IF FOUND THEN
    IF prior.associated_with<>'users' OR
      (prior.field_id,prior.field_revision,prior.original_name,prior.media_type,prior.byte_length,prior.sha256,prior.uploaded_by)
        IS DISTINCT FROM (target_field,expected_revision,requested_name,requested_type,requested_length,requested_sha256,actor) THEN
      RAISE EXCEPTION 'Upload request already used with different details' USING ERRCODE='23514',CONSTRAINT='user_field_attachment_request_reused';
    END IF;
    RETURN true;
  END IF;
  SELECT * INTO definition FROM public.custom_field_definitions WHERE organization_id=org AND id=target_field;
  actor:=public.users_require_manager();
  IF definition.id IS NULL OR NOT definition.active OR definition.associated_with<>'users' OR definition.field_type<>'attachment' THEN
    RAISE EXCEPTION 'User attachment field was not found' USING ERRCODE='P0002',CONSTRAINT='user_field_attachment_field_missing';
  END IF;
  IF definition.revision<>expected_revision THEN
    RAISE EXCEPTION 'Custom Field changed; reload before uploading' USING ERRCODE='23514',CONSTRAINT='user_field_attachment_stale';
  END IF;
  INSERT INTO public.custom_field_attachments(organization_id,id,field_id,field_revision,original_name,media_type,content,byte_length,sha256,uploaded_by)
    VALUES(org,requested_id,target_field,expected_revision,requested_name,requested_type,requested_content,requested_length,requested_sha256,actor);
  RETURN false;
END $$;


--
-- Name: users_write_account(uuid, integer, uuid, bytea, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_write_account(target uuid, expected_revision integer, requested_id uuid, requested_fingerprint bytea, requested_username text, requested_email text, requested_name text, requested_password_hash text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  RETURN public.users_write_account_command(target,expected_revision,requested_id,requested_fingerprint,requested_username,requested_email,requested_name,requested_password_hash,NULL,NULL,NULL);
END $$;


--
-- Name: users_write_account_command(uuid, integer, uuid, bytea, text, text, text, text, bytea, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_write_account_command(target uuid, expected_revision integer, requested_id uuid, requested_fingerprint bytea, requested_username text, requested_email text, requested_name text, requested_password_hash text, requested_form_fingerprint bytea, requested_profile_revision integer, requested_custom_field_revision integer) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; actor uuid; prior public.user_account_commands;
  person public.users; old_credential_revision integer; changes_identity boolean;
BEGIN
  actor:=public.users_require_manager();
  IF target IS NULL OR expected_revision IS NULL OR expected_revision NOT BETWEEN 1 AND 2147483646 OR requested_id IS NULL
    OR requested_fingerprint IS NULL OR octet_length(requested_fingerprint)<>32
    OR requested_username IS NULL OR length(requested_username) NOT BETWEEN 1 AND 100 OR requested_username<>trim(requested_username)
    OR requested_name IS NULL OR length(requested_name) NOT BETWEEN 1 AND 200 OR requested_name<>trim(requested_name)
    OR requested_email IS NULL OR length(requested_email) NOT BETWEEN 1 AND 320 OR requested_email<>trim(requested_email)
    OR requested_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
    OR (requested_password_hash IS NOT NULL AND requested_password_hash !~ '^scrypt[$]1[$]32768[$]8[$]1[$][A-Za-z0-9_-]{22}[$][A-Za-z0-9_-]{86}$') THEN
    RAISE EXCEPTION 'Invalid account command' USING ERRCODE='23514',CONSTRAINT='user_account_invalid_input';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=target) THEN
    RAISE EXCEPTION 'User was not found' USING ERRCODE='P0002',CONSTRAINT='user_profile_not_found';
  END IF;
  IF (requested_form_fingerprint IS NULL AND num_nonnulls(requested_profile_revision,requested_custom_field_revision)>0)
    OR (requested_form_fingerprint IS NOT NULL AND (octet_length(requested_form_fingerprint)<>32
      OR requested_profile_revision<=0 OR requested_custom_field_revision<=0)) THEN
    RAISE EXCEPTION 'Invalid form command' USING ERRCODE='23514',CONSTRAINT='user_account_form_invalid';
  END IF;
  IF requested_form_fingerprint IS NOT NULL THEN PERFORM public.users_prepare_field_form(); END IF;
  -- A global user lock also serializes new memberships and platform grants through their user foreign keys.
  PERFORM 1 FROM public.users WHERE id=ANY(ARRAY[actor,target]) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.credentials WHERE user_id=ANY(ARRAY[actor,target]) ORDER BY user_id FOR UPDATE;
  PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
  PERFORM 1 FROM public.memberships WHERE organization_id=org AND user_id=ANY(ARRAY[actor,target]) ORDER BY user_id FOR SHARE;
  PERFORM 1 FROM public.sessions WHERE id=nullif(current_setting('app.session_id',true),'')::uuid FOR SHARE;
  actor:=public.users_require_manager();
  SELECT * INTO prior FROM public.user_account_commands WHERE organization_id=org AND request_id=requested_id;
  IF FOUND THEN
    IF (prior.user_id,prior.saved_by,prior.previous_revision,prior.fingerprint,prior.username,prior.email,prior.display_name,prior.password_changed)
      IS DISTINCT FROM (target,actor,expected_revision,requested_fingerprint,requested_username,requested_email,requested_name,requested_password_hash IS NOT NULL) THEN
      RAISE EXCEPTION 'Save request already used for a different account change' USING ERRCODE='23514',CONSTRAINT='user_account_request_reused';
    END IF;
    IF prior.form_fingerprint IS NOT NULL THEN
      IF (prior.form_fingerprint,prior.form_profile_revision,prior.form_custom_field_revision)
        IS DISTINCT FROM (requested_form_fingerprint,requested_profile_revision,requested_custom_field_revision) THEN
        RAISE EXCEPTION 'Save request already used for a different form' USING ERRCODE='23514',CONSTRAINT='user_account_request_reused';
      END IF;
    ELSIF requested_form_fingerprint IS NOT NULL THEN
      -- Legacy receipts have no invented form fingerprint; actual co-transaction history establishes profile presence.
      IF requested_custom_field_revision IS NOT NULL OR
        (requested_profile_revision IS NOT NULL AND NOT EXISTS (
          SELECT 1 FROM public.user_profile_versions profile WHERE profile.organization_id=org AND profile.user_id=target
            AND profile.request_id=requested_id AND profile.revision=requested_profile_revision AND profile.saved_by=actor
            AND profile.created_transaction_id=prior.created_transaction_id
        )) OR (requested_profile_revision IS NULL AND EXISTS (
          SELECT 1 FROM public.user_profile_versions profile WHERE profile.organization_id=org AND profile.user_id=target
            AND profile.request_id=requested_id AND profile.saved_by=actor AND profile.created_transaction_id=prior.created_transaction_id
        )) THEN RAISE EXCEPTION 'Save request already used for a different form' USING ERRCODE='23514',CONSTRAINT='user_account_request_reused'; END IF;
    END IF;
    RETURN prior.revision;
  END IF;
  SELECT * INTO person FROM public.users WHERE id=target;
  IF person.revision<>expected_revision THEN RAISE EXCEPTION 'Account changed; reload before saving' USING ERRCODE='23514',CONSTRAINT='user_account_stale'; END IF;
  SELECT revision INTO old_credential_revision FROM public.credentials WHERE user_id=target;
  IF old_credential_revision IS NULL OR (requested_password_hash IS NOT NULL AND old_credential_revision=2147483647) THEN
    RAISE EXCEPTION 'Account credential is unavailable' USING ERRCODE='23514',CONSTRAINT='user_account_invalid_input';
  END IF;
  changes_identity:=(person.username,person.email,person.display_name) IS DISTINCT FROM (requested_username,requested_email,requested_name) OR requested_password_hash IS NOT NULL;
  IF changes_identity AND target<>actor THEN
    PERFORM 1 FROM public.platform_administrators WHERE (organization_id=org AND user_id=actor) OR user_id=target ORDER BY organization_id,user_id FOR SHARE;
    IF (EXISTS (SELECT 1 FROM public.memberships WHERE user_id=target AND organization_id<>org)
      OR EXISTS (SELECT 1 FROM public.platform_administrators WHERE user_id=target)) AND NOT public.auth_is_platform_administrator() THEN
      RAISE EXCEPTION 'Shared and platform identities require their owner or a platform administrator' USING ERRCODE='42501',CONSTRAINT='user_account_protected';
    END IF;
  END IF;
  -- Match creation and My Account ordering: organization/session locks precede alias locks.
  PERFORM public.auth_lock_login_aliases(ARRAY[requested_username,requested_email]);
  actor:=public.users_require_manager();
  IF requested_password_hash IS NOT NULL THEN
    PERFORM 1 FROM public.password_resets WHERE user_id=target AND used_at IS NULL ORDER BY id FOR UPDATE;
    PERFORM 1 FROM public.sessions WHERE user_id=target AND revoked_at IS NULL ORDER BY id FOR UPDATE;
    actor:=public.users_require_manager();
  END IF;
  IF (person.username IS DISTINCT FROM requested_username AND EXISTS (
      SELECT 1 FROM public.users WHERE id<>target AND (lower(username)=lower(requested_username) OR lower(email)=lower(requested_username))))
    OR (person.email IS DISTINCT FROM requested_email AND EXISTS (
      SELECT 1 FROM public.users WHERE id<>target AND (lower(username)=lower(requested_email) OR lower(email)=lower(requested_email)))) THEN
    RAISE EXCEPTION 'Username or email conflicts with a sign-in identifier' USING ERRCODE='23505',CONSTRAINT='user_account_identifier_taken';
  END IF;
  IF requested_form_fingerprint IS NOT NULL AND requested_custom_field_revision IS NULL THEN
    PERFORM public.users_assert_saved_field_uniqueness(org,target);
  END IF;
  INSERT INTO public.user_account_commands(organization_id,user_id,request_id,fingerprint,revision,previous_revision,credential_revision,previous_credential_revision,
    password_changed,username,email,display_name,previous_username,previous_email,previous_display_name,saved_by,saved_by_username,saved_by_name,form_fingerprint,form_profile_revision,form_custom_field_revision)
    SELECT org,target,requested_id,requested_fingerprint,expected_revision+1,expected_revision,
      old_credential_revision+CASE WHEN requested_password_hash IS NOT NULL THEN 1 ELSE 0 END,old_credential_revision,
      requested_password_hash IS NOT NULL,requested_username,requested_email,requested_name,person.username,person.email,person.display_name,actor,editor.username,editor.display_name,requested_form_fingerprint,requested_profile_revision,requested_custom_field_revision
    FROM public.users editor WHERE editor.id=actor;
  UPDATE public.users SET username=requested_username,email=requested_email,display_name=requested_name,revision=expected_revision+1,updated_at=transaction_timestamp(),
    must_change_password=CASE WHEN requested_password_hash IS NOT NULL THEN false ELSE must_change_password END WHERE id=target;
  IF requested_password_hash IS NOT NULL THEN
    UPDATE public.credentials SET password_hash=requested_password_hash,revision=old_credential_revision+1,updated_at=transaction_timestamp() WHERE user_id=target;
    UPDATE public.password_resets SET used_at=transaction_timestamp() WHERE user_id=target AND used_at IS NULL;
    UPDATE public.sessions SET revoked_at=transaction_timestamp() WHERE user_id=target AND revoked_at IS NULL;
  END IF;
  RETURN expected_revision+1;
END $_$;


--
-- Name: users_write_business_unit(uuid, integer, uuid, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_write_business_unit(target uuid, expected_revision integer, requested_id uuid, requested_code text, requested_name text, requested_description text, requested_active boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; actor uuid;
  head public.business_units; prior public.business_unit_versions;
BEGIN
  actor:=public.users_require_manager();
  IF target IS NULL OR requested_id IS NULL OR expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 2147483646
    OR requested_code IS NULL OR length(requested_code) NOT BETWEEN 1 AND 64 OR requested_code !~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$'
    OR requested_name IS NULL OR length(requested_name) NOT BETWEEN 1 AND 200 OR requested_name<>trim(requested_name) OR trim(requested_name)=''
    OR (requested_description IS NOT NULL AND (length(requested_description)>2000 OR requested_description<>trim(requested_description) OR requested_description=''))
    OR requested_active IS NULL THEN
    RAISE EXCEPTION 'Invalid business unit command' USING ERRCODE='23514',CONSTRAINT='business_unit_invalid_input';
  END IF;
  -- Match existing identity administration's user-before-organization lock order and recheck the live session after waiting.
  PERFORM 1 FROM public.users WHERE id=actor FOR NO KEY UPDATE;
  PERFORM 1 FROM public.organizations WHERE id=org FOR NO KEY UPDATE;
  PERFORM 1 FROM public.memberships WHERE organization_id=org AND user_id=actor FOR SHARE;
  PERFORM 1 FROM public.sessions WHERE id=nullif(current_setting('app.session_id',true),'')::uuid FOR SHARE;
  actor:=public.users_require_manager();
  SELECT * INTO prior FROM public.business_unit_versions WHERE organization_id=org AND request_id=requested_id;
  IF FOUND THEN
    IF (prior.unit_id,coalesce(prior.previous_revision,0),prior.saved_by,prior.code,prior.name,prior.description,prior.active)
      IS DISTINCT FROM (target,expected_revision,actor,requested_code,requested_name,requested_description,requested_active) THEN
      RAISE EXCEPTION 'Save request already used for another unit change' USING ERRCODE='23514',CONSTRAINT='business_unit_request_reused';
    END IF;
    RETURN prior.revision;
  END IF;
  SELECT * INTO head FROM public.business_units WHERE organization_id=org AND id=target FOR UPDATE;
  IF head.id IS NULL AND expected_revision>0 THEN
    RAISE EXCEPTION 'Unit was not found' USING ERRCODE='P0002',CONSTRAINT='business_unit_not_found';
  END IF;
  IF coalesce(head.revision,0)<>expected_revision THEN
    RAISE EXCEPTION 'Unit changed; reload before saving' USING ERRCODE='23514',CONSTRAINT='business_unit_stale';
  END IF;
  IF expected_revision=0 THEN
    INSERT INTO public.business_units(organization_id,id,code,name,description,active)
      VALUES(org,target,requested_code,requested_name,requested_description,requested_active);
  ELSE
    UPDATE public.business_units SET code=requested_code,name=requested_name,description=requested_description,active=requested_active,revision=revision+1
      WHERE organization_id=org AND id=target;
  END IF;
  INSERT INTO public.business_unit_versions(organization_id,unit_id,revision,previous_revision,request_id,code,name,description,active,saved_by,saved_by_username,saved_by_name)
    SELECT org,target,expected_revision+1,nullif(expected_revision,0),requested_id,requested_code,requested_name,requested_description,requested_active,
      actor,username,display_name FROM public.users WHERE id=actor;
  RETURN expected_revision+1;
END $_$;


--
-- Name: users_write_form_account(uuid, integer, uuid, bytea, text, text, text, text, bytea, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_write_form_account(target uuid, expected_revision integer, requested_id uuid, requested_fingerprint bytea, requested_username text, requested_email text, requested_name text, requested_password_hash text, requested_form_fingerprint bytea, requested_profile_revision integer, requested_custom_field_revision integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF requested_form_fingerprint IS NULL THEN RAISE EXCEPTION 'A form fingerprint is required' USING ERRCODE='23514',CONSTRAINT='user_account_form_invalid'; END IF;
  RETURN public.users_write_account_command(target,expected_revision,requested_id,requested_fingerprint,requested_username,requested_email,requested_name,requested_password_hash,requested_form_fingerprint,requested_profile_revision,requested_custom_field_revision);
END $$;


--
-- Name: users_write_laboratory(text, uuid, integer, uuid, text, text, text, text, uuid, uuid, uuid, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_write_laboratory(requested_operation text, target uuid, expected_revision integer, requested_id uuid, requested_code text, requested_name text, requested_description text, requested_abbreviation text, requested_business_unit_id uuid, requested_head_user_id uuid, requested_delegate_user_id uuid, requested_minimum_temperature_text text, requested_maximum_temperature_text text, requested_minimum_humidity_text text, requested_maximum_humidity_text text, requested_active boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; actor uuid;
  head public.laboratories; next_lab public.laboratories; prior public.laboratory_versions;
  observed_head uuid; observed_delegate uuid; operation_value text;
BEGIN
  actor:=public.users_require_manager();
  IF requested_operation IS NULL OR requested_operation NOT IN ('save','retire') OR target IS NULL OR requested_id IS NULL
    OR expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 2147483646
    OR (requested_operation='retire' AND (expected_revision=0 OR ROW(requested_code, requested_name, requested_description, requested_abbreviation, requested_business_unit_id, requested_head_user_id, requested_delegate_user_id, requested_minimum_temperature_text, requested_maximum_temperature_text, requested_minimum_humidity_text, requested_maximum_humidity_text, requested_active) IS DISTINCT FROM ROW(NULL::text, NULL::text, NULL::text, NULL::text, NULL::uuid, NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::text, NULL::text, NULL::boolean)))
    OR (requested_operation='save' AND (requested_code IS NULL OR requested_name IS NULL OR requested_active IS NULL)) THEN
    RAISE EXCEPTION 'Invalid Lab command' USING ERRCODE='23514',CONSTRAINT='laboratory_invalid_input';
  END IF;
  operation_value:=CASE WHEN requested_operation='retire' THEN 'retire' WHEN expected_revision=0 THEN 'create' ELSE 'update' END;
  IF requested_operation='retire' THEN
    SELECT head_user_id,delegate_user_id INTO observed_head,observed_delegate FROM public.laboratories WHERE organization_id=org AND id=target;
  ELSE observed_head:=requested_head_user_id; observed_delegate:=requested_delegate_user_id; END IF;
  -- Match identity administration: all observed people first, in a stable order, then the organization mutex.
  PERFORM 1 FROM public.users person WHERE person.id=ANY(ARRAY[actor,observed_head,observed_delegate])
    AND EXISTS (SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=person.id) ORDER BY person.id FOR NO KEY UPDATE;
  PERFORM 1 FROM public.organizations WHERE id=org FOR NO KEY UPDATE;
  PERFORM 1 FROM public.memberships WHERE organization_id=org AND user_id=ANY(ARRAY[actor,observed_head,observed_delegate]) ORDER BY user_id FOR SHARE;
  PERFORM 1 FROM public.sessions WHERE id=nullif(current_setting('app.session_id',true),'')::uuid FOR SHARE;
  actor:=public.users_require_manager();
  SELECT * INTO prior FROM public.laboratory_versions WHERE organization_id=org AND request_id=requested_id;
  IF FOUND THEN
    IF (prior.laboratory_id,coalesce(prior.previous_revision,0),prior.saved_by,prior.operation) IS DISTINCT FROM (target,expected_revision,actor,operation_value)
      OR (requested_operation='save' AND (prior.code, prior.name, prior.description, prior.abbreviation, prior.business_unit_id, prior.head_user_id, prior.delegate_user_id, prior.minimum_temperature_text, prior.maximum_temperature_text, prior.minimum_humidity_text, prior.maximum_humidity_text, prior.active) IS DISTINCT FROM (requested_code, requested_name, requested_description, requested_abbreviation, requested_business_unit_id, requested_head_user_id, requested_delegate_user_id, requested_minimum_temperature_text, requested_maximum_temperature_text, requested_minimum_humidity_text, requested_maximum_humidity_text, requested_active)) THEN
      RAISE EXCEPTION 'Save request already used for another Lab change' USING ERRCODE='23514',CONSTRAINT='laboratory_request_reused';
    END IF;
    RETURN prior.revision;
  END IF;
  SELECT * INTO head FROM public.laboratories WHERE organization_id=org AND id=target FOR UPDATE;
  IF head.id IS NULL AND expected_revision>0 THEN RAISE EXCEPTION 'Lab was not found' USING ERRCODE='P0002',CONSTRAINT='laboratory_not_found'; END IF;
  IF coalesce(head.revision,0)<>expected_revision THEN RAISE EXCEPTION 'Lab changed' USING ERRCODE='23514',CONSTRAINT='laboratory_stale'; END IF;
  next_lab:=head;
  IF requested_operation='retire' THEN
    IF NOT head.active THEN RAISE EXCEPTION 'Lab is already retired' USING ERRCODE='23514',CONSTRAINT='laboratory_stale'; END IF;
    next_lab.active:=false;
  ELSE
    -- Preserve exact, unchanged older values. New/changed values use the source authoring bounds.
    IF ((head.id IS NULL OR requested_code IS DISTINCT FROM head.code) AND (length(requested_code) NOT BETWEEN 1 AND 64 OR requested_code !~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$'))
      OR ((head.id IS NULL OR requested_name IS DISTINCT FROM head.name) AND length(trim(requested_name)) NOT BETWEEN 1 AND 200)
      OR ((head.id IS NULL OR requested_description IS DISTINCT FROM head.description) AND (requested_description IS NOT NULL AND length(requested_description)>2000))
      OR ((head.id IS NULL OR requested_abbreviation IS DISTINCT FROM head.abbreviation) AND (requested_abbreviation IS NOT NULL AND length(requested_abbreviation)>20))
      OR ((head.id IS NULL OR requested_minimum_temperature_text IS DISTINCT FROM head.minimum_temperature_text) AND (requested_minimum_temperature_text IS NULL OR requested_minimum_temperature_text='' OR length(requested_minimum_temperature_text)>2000))
      OR ((head.id IS NULL OR requested_maximum_temperature_text IS DISTINCT FROM head.maximum_temperature_text) AND (requested_maximum_temperature_text IS NULL OR requested_maximum_temperature_text='' OR length(requested_maximum_temperature_text)>2000))
      OR ((head.id IS NULL OR requested_minimum_humidity_text IS DISTINCT FROM head.minimum_humidity_text) AND (requested_minimum_humidity_text IS NULL OR requested_minimum_humidity_text='' OR length(requested_minimum_humidity_text)>2000))
      OR ((head.id IS NULL OR requested_maximum_humidity_text IS DISTINCT FROM head.maximum_humidity_text) AND (requested_maximum_humidity_text IS NULL OR requested_maximum_humidity_text='' OR length(requested_maximum_humidity_text)>2000)) THEN
      RAISE EXCEPTION 'Lab details are invalid' USING ERRCODE='23514',CONSTRAINT='laboratory_invalid_input';
    END IF;
    next_lab.code := requested_code;
    next_lab.name := requested_name;
    next_lab.description := requested_description;
    next_lab.abbreviation := requested_abbreviation;
    next_lab.business_unit_id := requested_business_unit_id;
    next_lab.head_user_id := requested_head_user_id;
    next_lab.delegate_user_id := requested_delegate_user_id;
    next_lab.minimum_temperature_text := requested_minimum_temperature_text;
    next_lab.maximum_temperature_text := requested_maximum_temperature_text;
    next_lab.minimum_humidity_text := requested_minimum_humidity_text;
    next_lab.maximum_humidity_text := requested_maximum_humidity_text;
    next_lab.active := requested_active;
  END IF;
  IF (next_lab.head_user_id,next_lab.delegate_user_id) IS DISTINCT FROM (observed_head,observed_delegate) THEN
    RAISE EXCEPTION 'Lab references changed' USING ERRCODE='23514',CONSTRAINT='laboratory_stale';
  END IF;
  IF (next_lab.head_user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=next_lab.head_user_id))
    OR (next_lab.delegate_user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=next_lab.delegate_user_id)) THEN
    RAISE EXCEPTION 'Select a user in this organization' USING ERRCODE='23514',CONSTRAINT='laboratory_user_unavailable';
  END IF;
  IF next_lab.business_unit_id IS NOT NULL THEN
    PERFORM 1 FROM public.business_units WHERE organization_id=org AND id=next_lab.business_unit_id
      AND (active OR (head.id IS NOT NULL AND head.business_unit_id=next_lab.business_unit_id)) FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Business unit is unavailable' USING ERRCODE='23514',CONSTRAINT='laboratory_unit_unavailable'; END IF;
  END IF;
  IF expected_revision=0 THEN
    INSERT INTO public.laboratories(organization_id,id,code, name, description, abbreviation, business_unit_id, head_user_id, delegate_user_id, minimum_temperature_text, maximum_temperature_text, minimum_humidity_text, maximum_humidity_text, active) VALUES(org,target,next_lab.code, next_lab.name, next_lab.description, next_lab.abbreviation, next_lab.business_unit_id, next_lab.head_user_id, next_lab.delegate_user_id, next_lab.minimum_temperature_text, next_lab.maximum_temperature_text, next_lab.minimum_humidity_text, next_lab.maximum_humidity_text, next_lab.active);
  ELSE
    UPDATE public.laboratories SET code=next_lab.code, name=next_lab.name, description=next_lab.description, abbreviation=next_lab.abbreviation, business_unit_id=next_lab.business_unit_id, head_user_id=next_lab.head_user_id, delegate_user_id=next_lab.delegate_user_id, minimum_temperature_text=next_lab.minimum_temperature_text, maximum_temperature_text=next_lab.maximum_temperature_text, minimum_humidity_text=next_lab.minimum_humidity_text, maximum_humidity_text=next_lab.maximum_humidity_text, active=next_lab.active,revision=revision+1
      WHERE organization_id=org AND id=target;
  END IF;
  INSERT INTO public.laboratory_versions(organization_id,laboratory_id,revision,previous_revision,request_id,operation,code, name, description, abbreviation, business_unit_id, head_user_id, delegate_user_id, minimum_temperature_text, maximum_temperature_text, minimum_humidity_text, maximum_humidity_text, active,business_unit_code, business_unit_name, head_username, head_user_name, delegate_username, delegate_user_name,saved_by,saved_by_username,saved_by_name)
    SELECT org,target,expected_revision+1,nullif(expected_revision,0),requested_id,operation_value,next_lab.code, next_lab.name, next_lab.description, next_lab.abbreviation, next_lab.business_unit_id, next_lab.head_user_id, next_lab.delegate_user_id, next_lab.minimum_temperature_text, next_lab.maximum_temperature_text, next_lab.minimum_humidity_text, next_lab.maximum_humidity_text, next_lab.active,unit.code,unit.name,hod.username,hod.display_name,delegate.username,delegate.display_name,actor,editor.username,editor.display_name
      FROM public.users editor
      LEFT JOIN public.business_units unit ON unit.organization_id=org AND unit.id=next_lab.business_unit_id
      LEFT JOIN public.users hod ON hod.id=next_lab.head_user_id
      LEFT JOIN public.users delegate ON delegate.id=next_lab.delegate_user_id WHERE editor.id=actor;
  RETURN expected_revision+1;
END $_$;


--
-- Name: users_write_profile(uuid, integer, uuid, text, boolean, text, boolean, text, boolean, boolean, boolean, uuid, boolean, uuid, boolean, uuid, boolean, uuid, boolean, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_write_profile(target uuid, expected_revision integer, requested_id uuid, employee_code_value text, employee_code_provided boolean, phone_value text, phone_provided boolean, designation_value text, designation_provided boolean, can_manage_value boolean, can_manage_provided boolean, unit_value uuid, unit_provided boolean, default_role_value uuid, default_role_provided boolean, laboratory_value uuid, laboratory_provided boolean, manager_value uuid, manager_provided boolean, selected_roles uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; actor uuid;
  head public.user_profiles; prior public.user_profile_versions; next_profile public.user_profiles;
  next_roles uuid[]; next_revision integer; protected_permission text; locked_head_revision integer; observed_manager uuid;
BEGIN
  actor:=public.users_require_manager();
  IF target IS NULL OR requested_id IS NULL OR expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 2147483646
    OR num_nulls(employee_code_provided,phone_provided,designation_provided,can_manage_provided,unit_provided,default_role_provided,laboratory_provided,manager_provided)>0
    OR NOT (employee_code_provided OR phone_provided OR designation_provided OR can_manage_provided OR unit_provided OR default_role_provided OR laboratory_provided OR manager_provided OR selected_roles IS NOT NULL)
    OR (NOT employee_code_provided AND employee_code_value IS NOT NULL) OR (employee_code_value IS NOT NULL AND (length(employee_code_value) NOT BETWEEN 1 AND 100 OR employee_code_value<>trim(employee_code_value)))
    OR (NOT phone_provided AND phone_value IS NOT NULL) OR (phone_value IS NOT NULL AND (length(phone_value) NOT BETWEEN 1 AND 50 OR phone_value<>trim(phone_value)))
    OR (NOT designation_provided AND designation_value IS NOT NULL) OR (designation_value IS NOT NULL AND (length(designation_value) NOT BETWEEN 1 AND 150 OR designation_value<>trim(designation_value)))
    OR (can_manage_provided<>(can_manage_value IS NOT NULL)) OR (NOT unit_provided AND unit_value IS NOT NULL)
    OR (default_role_provided<>(default_role_value IS NOT NULL)) OR (laboratory_provided<>(laboratory_value IS NOT NULL))
    OR (NOT manager_provided AND manager_value IS NOT NULL)
    OR (selected_roles IS NOT NULL AND (array_ndims(selected_roles) IS DISTINCT FROM 1 OR cardinality(selected_roles) NOT BETWEEN 1 AND 100
      OR cardinality(selected_roles)<>(SELECT count(DISTINCT role_id) FROM unnest(selected_roles) role_id))) THEN
    RAISE EXCEPTION 'Invalid membership profile command' USING ERRCODE='23514',CONSTRAINT='user_profile_invalid_input';
  END IF;
  -- Scope is checked before locking global identities. Keep the same user-before-organization order as sign-in/password changes.
  IF NOT EXISTS (SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=target) THEN
    RAISE EXCEPTION 'User was not found' USING ERRCODE='P0002',CONSTRAINT='user_profile_not_found';
  END IF;
  IF manager_value IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=manager_value) THEN
    RAISE EXCEPTION 'Reporting manager is unavailable' USING ERRCODE='23514',CONSTRAINT='user_profile_manager_unavailable';
  END IF;
  SELECT * INTO head FROM public.user_profiles WHERE organization_id=org AND user_id=target;
  locked_head_revision:=coalesce(head.revision,0);
  observed_manager:=CASE WHEN manager_provided THEN manager_value ELSE head.reporting_manager_id END;
  PERFORM 1 FROM public.users WHERE id=ANY(ARRAY[actor,target,observed_manager]) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
  PERFORM 1 FROM public.memberships WHERE organization_id=org AND user_id=ANY(ARRAY[actor,target,observed_manager]) ORDER BY user_id FOR SHARE;
  PERFORM 1 FROM public.sessions WHERE id=nullif(current_setting('app.session_id',true),'')::uuid FOR SHARE;
  actor:=public.users_require_manager();
  IF NOT EXISTS (SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=target) THEN
    RAISE EXCEPTION 'User was not found' USING ERRCODE='P0002',CONSTRAINT='user_profile_not_found';
  END IF;
  -- Compare the actual sparse command, including its explicit role set, before current reference availability/revision checks.
  SELECT * INTO prior FROM public.user_profile_versions WHERE organization_id=org AND request_id=requested_id;
  IF FOUND THEN
    IF prior.user_id<>target OR prior.saved_by<>actor OR coalesce(prior.previous_revision,0)<>expected_revision
      OR (prior.employee_code_provided,prior.phone_provided,prior.designation_provided,prior.can_manage_people_provided,prior.business_unit_provided,
        prior.default_role_provided,prior.laboratory_provided,prior.reporting_manager_provided,prior.roles_provided)
        IS DISTINCT FROM (employee_code_provided,phone_provided,designation_provided,can_manage_provided,unit_provided,default_role_provided,laboratory_provided,manager_provided,selected_roles IS NOT NULL)
      OR (employee_code_provided AND prior.employee_code IS DISTINCT FROM employee_code_value)
      OR (phone_provided AND prior.phone IS DISTINCT FROM phone_value) OR (designation_provided AND prior.designation IS DISTINCT FROM designation_value)
      OR (can_manage_provided AND prior.can_manage_people IS DISTINCT FROM can_manage_value)
      OR (unit_provided AND prior.business_unit_id IS DISTINCT FROM unit_value) OR (default_role_provided AND prior.default_role_id IS DISTINCT FROM default_role_value)
      OR (laboratory_provided AND prior.laboratory_id IS DISTINCT FROM laboratory_value) OR (manager_provided AND prior.reporting_manager_id IS DISTINCT FROM manager_value)
      OR (selected_roles IS NOT NULL AND ARRAY(SELECT role_id FROM unnest(selected_roles) role_id ORDER BY role_id)
        IS DISTINCT FROM ARRAY(SELECT role_id FROM public.user_profile_version_roles WHERE organization_id=org AND user_id=target AND revision=prior.revision AND explicitly_selected ORDER BY role_id)) THEN
      RAISE EXCEPTION 'Save request already used for a different profile change' USING ERRCODE='23514',CONSTRAINT='user_profile_request_reused';
    END IF;
    RETURN prior.revision;
  END IF;
  SELECT * INTO head FROM public.user_profiles WHERE organization_id=org AND user_id=target FOR UPDATE;
  IF coalesce(head.revision,0)<>expected_revision OR coalesce(head.revision,0)<>locked_head_revision THEN
    RAISE EXCEPTION 'Profile changed; reload before saving' USING ERRCODE='23514',CONSTRAINT='user_profile_stale';
  END IF;
  IF head.user_id IS NULL AND NOT (default_role_provided AND laboratory_provided) THEN
    RAISE EXCEPTION 'Choose a default role and laboratory for this profile' USING ERRCODE='23514',CONSTRAINT='user_profile_initial_references';
  END IF;
  next_profile:=head; next_revision:=expected_revision+1;
  next_profile.employee_code:=CASE WHEN employee_code_provided THEN employee_code_value ELSE head.employee_code END;
  next_profile.phone:=CASE WHEN phone_provided THEN phone_value ELSE head.phone END;
  next_profile.designation:=CASE WHEN designation_provided THEN designation_value ELSE head.designation END;
  next_profile.can_manage_people:=CASE WHEN can_manage_provided THEN can_manage_value ELSE coalesce(head.can_manage_people,false) END;
  next_profile.business_unit_id:=CASE WHEN unit_provided THEN unit_value ELSE head.business_unit_id END;
  next_profile.default_role_id:=CASE WHEN default_role_provided THEN default_role_value ELSE head.default_role_id END;
  next_profile.laboratory_id:=CASE WHEN laboratory_provided THEN laboratory_value ELSE head.laboratory_id END;
  next_profile.reporting_manager_id:=CASE WHEN manager_provided THEN manager_value ELSE head.reporting_manager_id END;
  -- Source form preserves hidden assignments and always adds its explicitly chosen default role.
  next_roles:=ARRAY(SELECT role_id FROM (
    SELECT unnest(coalesce(selected_roles,ARRAY(SELECT role_id FROM public.membership_roles WHERE organization_id=org AND user_id=target))) AS role_id
    UNION SELECT next_profile.default_role_id) selected ORDER BY role_id);
  IF next_profile.reporting_manager_id=target THEN
    RAISE EXCEPTION 'A user cannot report to themselves' USING ERRCODE='23514',CONSTRAINT='user_profile_own_manager';
  END IF;
  -- Lock even omitted references while observing their current labels. Availability checks below apply only to explicit selections.
  PERFORM 1 FROM public.business_units WHERE organization_id=org AND id=next_profile.business_unit_id FOR SHARE;
  PERFORM 1 FROM public.laboratories WHERE organization_id=org AND id=next_profile.laboratory_id FOR SHARE;
  IF unit_provided AND unit_value IS NOT NULL THEN
    PERFORM 1 FROM public.business_units WHERE organization_id=org AND id=unit_value AND active FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Business unit is unavailable' USING ERRCODE='23514',CONSTRAINT='user_profile_unit_unavailable'; END IF;
  END IF;
  IF laboratory_provided THEN
    PERFORM 1 FROM public.laboratories WHERE organization_id=org AND id=laboratory_value AND active FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Laboratory is unavailable' USING ERRCODE='23514',CONSTRAINT='user_profile_lab_unavailable'; END IF;
  END IF;
  IF manager_provided AND manager_value IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.memberships membership JOIN public.users person ON person.id=membership.user_id AND person.active
    WHERE membership.organization_id=org AND membership.user_id=manager_value AND membership.active) THEN
    RAISE EXCEPTION 'Reporting manager is unavailable' USING ERRCODE='23514',CONSTRAINT='user_profile_manager_unavailable';
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(coalesce(selected_roles,ARRAY[]::uuid[]) || CASE WHEN default_role_provided THEN ARRAY[default_role_value] ELSE ARRAY[]::uuid[] END) candidate(id)
    WHERE NOT EXISTS (SELECT 1 FROM public.roles role WHERE role.organization_id=org AND role.id=candidate.id AND role.active)) THEN
    RAISE EXCEPTION 'Select active roles in this organization' USING ERRCODE='23514',CONSTRAINT='user_profile_role_unavailable';
  END IF;
  -- Match role management's organization lock and retain each existing administration capability.
  FOREACH protected_permission IN ARRAY ARRAY['roles.manage','users.manage'] LOOP
    IF EXISTS (
      SELECT 1 FROM public.membership_roles assignment JOIN public.roles role ON role.organization_id=assignment.organization_id AND role.id=assignment.role_id AND role.active
      JOIN public.memberships membership ON membership.organization_id=assignment.organization_id AND membership.user_id=assignment.user_id AND membership.active
      JOIN public.users person ON person.id=membership.user_id AND person.active
      JOIN public.role_permissions permission ON permission.organization_id=role.organization_id AND permission.role_id=role.id AND permission.permission_code=protected_permission
      WHERE assignment.organization_id=org
    ) AND NOT EXISTS (
      SELECT 1 FROM public.memberships membership JOIN public.users person ON person.id=membership.user_id AND person.active
      JOIN public.roles role ON role.organization_id=membership.organization_id AND role.active
      JOIN public.role_permissions permission ON permission.organization_id=role.organization_id AND permission.role_id=role.id AND permission.permission_code=protected_permission
      WHERE membership.organization_id=org AND membership.active AND
        ((membership.user_id=target AND role.id=ANY(next_roles)) OR (membership.user_id<>target AND EXISTS
          (SELECT 1 FROM public.membership_roles assignment WHERE assignment.organization_id=org AND assignment.user_id=membership.user_id AND assignment.role_id=role.id)))
    ) THEN RAISE EXCEPTION 'The last active administrator must be retained' USING ERRCODE='23514',CONSTRAINT='user_profile_last_administrator'; END IF;
  END LOOP;
  INSERT INTO public.membership_roles(organization_id,user_id,role_id)
    SELECT org,target,candidate.id FROM unnest(next_roles) candidate(id)
    WHERE NOT EXISTS (SELECT 1 FROM public.membership_roles assignment WHERE assignment.organization_id=org AND assignment.user_id=target AND assignment.role_id=candidate.id);
  IF head.user_id IS NULL THEN
    INSERT INTO public.user_profiles(organization_id,user_id,revision,employee_code,phone,designation,can_manage_people,business_unit_id,default_role_id,laboratory_id,reporting_manager_id)
      VALUES(org,target,next_revision,next_profile.employee_code,next_profile.phone,next_profile.designation,next_profile.can_manage_people,
        next_profile.business_unit_id,next_profile.default_role_id,next_profile.laboratory_id,next_profile.reporting_manager_id);
  ELSE
    UPDATE public.user_profiles SET revision=next_revision,employee_code=next_profile.employee_code,phone=next_profile.phone,
      designation=next_profile.designation,can_manage_people=next_profile.can_manage_people,business_unit_id=next_profile.business_unit_id,
      default_role_id=next_profile.default_role_id,laboratory_id=next_profile.laboratory_id,reporting_manager_id=next_profile.reporting_manager_id
      WHERE organization_id=org AND user_id=target;
  END IF;
  INSERT INTO public.user_profile_versions(organization_id,user_id,revision,previous_revision,request_id,employee_code,phone,designation,can_manage_people,
    business_unit_id,default_role_id,laboratory_id,reporting_manager_id,employee_code_provided,phone_provided,designation_provided,can_manage_people_provided,
    business_unit_provided,default_role_provided,laboratory_provided,reporting_manager_provided,roles_provided,
    business_unit_code,business_unit_name,laboratory_code,laboratory_name,reporting_manager_username,reporting_manager_name,
    role_count,saved_by,saved_by_username,saved_by_name)
    SELECT org,target,next_revision,nullif(expected_revision,0),requested_id,next_profile.employee_code,next_profile.phone,next_profile.designation,next_profile.can_manage_people,
      next_profile.business_unit_id,next_profile.default_role_id,next_profile.laboratory_id,next_profile.reporting_manager_id,
      employee_code_provided,phone_provided,designation_provided,can_manage_provided,unit_provided,default_role_provided,laboratory_provided,manager_provided,selected_roles IS NOT NULL,
      unit.code,unit.name,lab.code,lab.name,manager.username,manager.display_name,cardinality(next_roles),actor,editor.username,editor.display_name
    FROM public.users editor JOIN public.laboratories lab ON lab.organization_id=org AND lab.id=next_profile.laboratory_id
    LEFT JOIN public.business_units unit ON unit.organization_id=org AND unit.id=next_profile.business_unit_id
    LEFT JOIN public.users manager ON manager.id=next_profile.reporting_manager_id WHERE editor.id=actor;
  INSERT INTO public.user_profile_version_roles(organization_id,user_id,revision,role_id,recorded_role_revision,name,description,active,explicitly_selected)
    SELECT org,target,next_revision,role.id,nullif(role.revision,0),role.name,role.description,role.active,coalesce(role.id=ANY(selected_roles),false)
    FROM public.roles role WHERE role.organization_id=org AND role.id=ANY(next_roles);
  -- The head's default assignment now exists. Removing old roles last also permits a successful self-permission change.
  DELETE FROM public.membership_roles WHERE organization_id=org AND user_id=target AND NOT role_id=ANY(next_roles);
  RETURN next_revision;
END $$;


--
-- Name: users_write_signature(uuid, integer, uuid, text, text, text, bytea, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_write_signature(target uuid, expected_revision integer, requested_id uuid, requested_operation text, requested_name text, requested_type text, requested_content bytea, requested_length integer, requested_sha256 text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; actor uuid; head_revision integer; head_operation text; prior record;
BEGIN
  actor:=public.users_require_manager();
  IF target IS NULL OR expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 2147483646 OR requested_id IS NULL
    OR requested_operation IS NULL OR requested_operation NOT IN ('upload','remove')
    OR (requested_operation='upload' AND (num_nonnulls(requested_name,requested_type,requested_content,requested_length,requested_sha256)<>5
      OR requested_length NOT BETWEEN 0 AND 20971520 OR requested_length<>octet_length(requested_content)))
    OR (requested_operation='remove' AND num_nonnulls(requested_name,requested_type,requested_content,requested_length,requested_sha256)<>0) THEN
    RAISE EXCEPTION 'Invalid signature command' USING ERRCODE='23514',CONSTRAINT='user_signature_invalid_input';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=target) THEN
    RAISE EXCEPTION 'User was not found' USING ERRCODE='P0002',CONSTRAINT='user_profile_not_found';
  END IF;
  PERFORM 1 FROM public.users WHERE id=ANY(ARRAY[actor,target]) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
  PERFORM 1 FROM public.memberships WHERE organization_id=org AND user_id=ANY(ARRAY[actor,target]) ORDER BY user_id FOR UPDATE;
  PERFORM 1 FROM public.sessions WHERE id=nullif(current_setting('app.session_id',true),'')::uuid FOR SHARE;
  actor:=public.users_require_manager();
  -- Request comparison and metadata reads never select an old BYTEA payload.
  SELECT user_id,saved_by,previous_revision,revision,operation,original_name,media_type,byte_length,sha256 INTO prior
    FROM public.user_signature_versions WHERE organization_id=org AND request_id=requested_id;
  IF FOUND THEN
    IF (prior.user_id,prior.saved_by,prior.previous_revision,prior.operation,prior.original_name,prior.media_type,prior.byte_length,prior.sha256)
      IS DISTINCT FROM (target,actor,expected_revision,requested_operation,requested_name,requested_type,requested_length,requested_sha256)
      OR (requested_operation='upload' AND requested_sha256 IS DISTINCT FROM encode(sha256(requested_content),'hex')) THEN
      RAISE EXCEPTION 'Save request already used for another signature change' USING ERRCODE='23514',CONSTRAINT='user_signature_request_reused';
    END IF;
    RETURN prior.revision;
  END IF;
  SELECT signature_revision INTO head_revision FROM public.memberships WHERE organization_id=org AND user_id=target;
  IF NOT FOUND THEN RAISE EXCEPTION 'User was not found' USING ERRCODE='P0002',CONSTRAINT='user_profile_not_found'; END IF;
  IF head_revision<>expected_revision THEN
    RAISE EXCEPTION 'Signature changed; reload before saving' USING ERRCODE='23514',CONSTRAINT='user_signature_stale';
  END IF;
  SELECT operation INTO head_operation FROM public.user_signature_versions WHERE organization_id=org AND user_id=target AND revision=head_revision;
  IF requested_operation='remove' AND head_operation IS DISTINCT FROM 'upload' THEN
    RAISE EXCEPTION 'This membership has no signature file to remove' USING ERRCODE='23514',CONSTRAINT='user_signature_empty';
  END IF;
  UPDATE public.memberships SET signature_revision=expected_revision+1 WHERE organization_id=org AND user_id=target;
  INSERT INTO public.user_signature_versions(organization_id,user_id,revision,previous_revision,request_id,operation,original_name,media_type,content,byte_length,sha256,
    username,display_name,saved_by,saved_by_username,saved_by_name)
    SELECT org,target,expected_revision+1,expected_revision,requested_id,requested_operation,requested_name,requested_type,requested_content,requested_length,requested_sha256,
      person.username,person.display_name,actor,editor.username,editor.display_name
    FROM public.users person JOIN public.users editor ON editor.id=actor WHERE person.id=target;
  RETURN expected_revision+1;
END $$;


--
-- Name: users_write_status(uuid, integer, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.users_write_status(target uuid, expected_revision integer, requested_id uuid, requested_active boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; actor uuid;
  head public.memberships; prior public.user_status_versions; protected_permission text;
BEGIN
  actor:=public.users_require_manager();
  IF target IS NULL OR expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 2147483646 OR requested_id IS NULL OR requested_active IS NULL THEN
    RAISE EXCEPTION 'Invalid membership status change' USING ERRCODE='23514',CONSTRAINT='user_status_invalid_input';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=target) THEN
    RAISE EXCEPTION 'User was not found' USING ERRCODE='P0002',CONSTRAINT='user_profile_not_found';
  END IF;
  PERFORM 1 FROM public.users WHERE id=ANY(ARRAY[actor,target]) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
  PERFORM 1 FROM public.memberships WHERE organization_id=org AND user_id=ANY(ARRAY[actor,target]) ORDER BY user_id FOR UPDATE;
  PERFORM 1 FROM public.sessions WHERE id=nullif(current_setting('app.session_id',true),'')::uuid FOR SHARE;
  actor:=public.users_require_manager();
  SELECT * INTO prior FROM public.user_status_versions WHERE organization_id=org AND request_id=requested_id;
  IF FOUND THEN
    IF (prior.user_id,prior.saved_by,prior.previous_revision,prior.active) IS DISTINCT FROM (target,actor,expected_revision,requested_active) THEN
      RAISE EXCEPTION 'Save request already used for another status change' USING ERRCODE='23514',CONSTRAINT='user_status_request_reused';
    END IF;
    RETURN prior.revision;
  END IF;
  SELECT * INTO head FROM public.memberships WHERE organization_id=org AND user_id=target;
  IF NOT FOUND THEN RAISE EXCEPTION 'User was not found' USING ERRCODE='P0002',CONSTRAINT='user_profile_not_found'; END IF;
  IF target=actor AND NOT requested_active THEN
    RAISE EXCEPTION 'You cannot disable your own account' USING ERRCODE='23514',CONSTRAINT='user_status_cannot_disable_self';
  END IF;
  IF head.status_revision<>expected_revision THEN
    RAISE EXCEPTION 'Status changed; reload before saving' USING ERRCODE='23514',CONSTRAINT='user_status_stale';
  END IF;
  IF head.active=requested_active THEN
    RAISE EXCEPTION 'Membership already has that status' USING ERRCODE='23514',CONSTRAINT='user_status_unchanged';
  END IF;
  IF NOT requested_active THEN
    FOREACH protected_permission IN ARRAY ARRAY['roles.manage','users.manage'] LOOP
      IF EXISTS (
        SELECT 1 FROM public.membership_roles assignment JOIN public.roles role ON role.organization_id=assignment.organization_id AND role.id=assignment.role_id AND role.active
        JOIN public.role_permissions permission ON permission.organization_id=role.organization_id AND permission.role_id=role.id AND permission.permission_code=protected_permission
        JOIN public.users person ON person.id=assignment.user_id AND person.active
        WHERE assignment.organization_id=org AND assignment.user_id=target
      ) AND NOT EXISTS (
        SELECT 1 FROM public.membership_roles assignment JOIN public.roles role ON role.organization_id=assignment.organization_id AND role.id=assignment.role_id AND role.active
        JOIN public.role_permissions permission ON permission.organization_id=role.organization_id AND permission.role_id=role.id AND permission.permission_code=protected_permission
        JOIN public.memberships membership ON membership.organization_id=assignment.organization_id AND membership.user_id=assignment.user_id AND membership.active
        JOIN public.users person ON person.id=membership.user_id AND person.active
        WHERE assignment.organization_id=org AND assignment.user_id<>target
      ) THEN RAISE EXCEPTION 'The last active administrator must be retained' USING ERRCODE='23514',CONSTRAINT='user_profile_last_administrator'; END IF;
    END LOOP;
  END IF;
  UPDATE public.memberships SET active=requested_active,status_revision=expected_revision+1 WHERE organization_id=org AND user_id=target;
  IF NOT requested_active THEN
    UPDATE public.sessions SET revoked_at=now() WHERE organization_id=org AND user_id=target AND revoked_at IS NULL;
  END IF;
  -- The insert revalidates the actual actor even if revocation waited for a target session lock.
  INSERT INTO public.user_status_versions(organization_id,user_id,revision,previous_revision,request_id,active,previous_active,
    username,display_name,saved_by,saved_by_username,saved_by_name)
    SELECT org,target,expected_revision+1,expected_revision,requested_id,requested_active,head.active,
      person.username,person.display_name,actor,editor.username,editor.display_name
    FROM public.users person JOIN public.users editor ON editor.id=actor WHERE person.id=target;
  RETURN expected_revision+1;
END $$;


--
-- Name: workflow_apply_document_transition(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_apply_document_transition(selected_run uuid, selected_transition uuid, expected_revision integer, remarks text) RETURNS TABLE(revision integer, status text, history_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  run public.workflow_runs; transition public.workflow_transitions; target public.workflow_states; approved boolean; next_status text; recorded_history uuid;
BEGIN
  IF NOT public.workflow_lock_run(selected_run) OR actor IS NULL OR length(remarks)>5000 THEN
    RAISE EXCEPTION 'Invalid workflow transition request' USING ERRCODE='42501';
  END IF;
  SELECT * INTO run FROM public.workflow_runs WHERE organization_id=org AND id=selected_run;
  SELECT * INTO transition FROM public.workflow_transitions WHERE organization_id=org AND id=selected_transition
    AND workflow_version_id=run.workflow_version_id AND source_state_id=run.current_state_id;
  IF run.status<>'active' OR run.revision<>expected_revision OR run.document_id IS NULL OR transition.id IS NULL
    OR EXISTS (SELECT 1 FROM public.approval_cases pending WHERE pending.organization_id=org AND pending.workflow_run_id=run.id AND pending.status='pending') THEN
    RAISE EXCEPTION 'Workflow changed or an approval is pending' USING ERRCODE='23514';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.approval_cases approval JOIN public.approval_stages stage
    ON stage.organization_id=approval.organization_id AND stage.approval_case_id=approval.id
    JOIN public.approval_assignments assignment ON assignment.organization_id=stage.organization_id AND assignment.approval_stage_id=stage.id
    JOIN public.approval_decisions decision ON decision.organization_id=assignment.organization_id AND decision.approval_assignment_id=assignment.id
    WHERE approval.organization_id=org AND approval.workflow_run_id=run.id AND approval.transition_id=transition.id AND approval.run_revision=expected_revision
      AND approval.status='approved' AND approval.resolved_at=transaction_timestamp() AND decision.decided_by=actor AND decision.decided_at=transaction_timestamp()) INTO approved;
  IF NOT ((transition.approval_mode='none' AND public.workflow_can_request(transition.id)) OR (approved AND public.app_has_permission('approvals.respond'))) THEN
    RAISE EXCEPTION 'This transition requires its configured approval' USING ERRCODE='42501';
  END IF;
  IF transition.require_comment AND nullif(trim(remarks),'') IS NULL THEN RAISE EXCEPTION 'A transition comment is required' USING ERRCODE='23514'; END IF;
  SELECT * INTO target FROM public.workflow_states WHERE organization_id=org AND id=transition.target_state_id;
  next_status:=CASE WHEN target.state_type='cancelled' THEN 'cancelled' WHEN target.state_type='final' THEN 'completed' ELSE 'active' END;
  UPDATE public.workflow_runs stored SET current_state_id=target.id, status=next_status, revision=stored.revision+1,
    completed_at=CASE WHEN next_status<>'active' THEN transaction_timestamp() ELSE NULL END WHERE stored.organization_id=org AND stored.id=run.id;
  INSERT INTO public.workflow_run_history(organization_id,workflow_run_id,workflow_version_id,from_state_id,to_state_id,transition_id,action,actor_user_id,comment)
    VALUES(org,run.id,run.workflow_version_id,run.current_state_id,target.id,transition.id,
      CASE WHEN next_status='completed' THEN 'completed' WHEN next_status='cancelled' THEN 'cancelled' WHEN approved THEN 'approved' ELSE 'transitioned' END,actor,remarks) RETURNING id INTO recorded_history;
  RETURN QUERY SELECT expected_revision+1,next_status,recorded_history;
END $$;


--
-- Name: workflow_apply_job_effects(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_apply_job_effects(history_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  parent_history public.workflow_run_history; parent_run public.workflow_runs; target public.workflow_states;
  job_id uuid; member record; applied integer:=0; next_status text;
BEGIN
  SELECT * INTO parent_history FROM public.workflow_run_history WHERE organization_id=org AND id=history_id;
  SELECT * INTO parent_run FROM public.workflow_runs WHERE organization_id=org AND id=parent_history.workflow_run_id;
  SELECT id INTO job_id FROM public.test_requests WHERE organization_id=org AND id=parent_run.test_request_id AND is_job;
  IF job_id IS NULL THEN RETURN 0; END IF;
  IF parent_history.actor_user_id IS DISTINCT FROM actor OR parent_history.to_state_id IS DISTINCT FROM parent_run.current_state_id
    OR parent_history.action NOT IN ('completed','cancelled','approved','transitioned','rejected')
    OR NOT EXISTS (SELECT 1 FROM public.workflow_run_history WHERE organization_id=org AND id=history_id AND xmin::text=pg_current_xact_id()::text) THEN
    RAISE EXCEPTION 'Job effects require this actual parent transition' USING ERRCODE='23514';
  END IF;
  SELECT * INTO target FROM public.workflow_states WHERE organization_id=org AND id=parent_history.to_state_id;
  next_status:=CASE WHEN target.state_type='cancelled' THEN 'cancelled' WHEN target.state_type='final' THEN 'completed' ELSE 'active' END;
  PERFORM 1 FROM public.test_requests WHERE organization_id=org AND parent_test_request_id=job_id ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.workflow_runs run JOIN public.test_requests child ON child.organization_id=run.organization_id AND child.id=run.test_request_id
    WHERE child.organization_id=org AND child.parent_test_request_id=job_id ORDER BY run.id FOR UPDATE OF run;
  FOR member IN SELECT chosen.id AS member_id,chosen.submission_id,child.id AS request_id,child.status AS request_status,child.sample_test_id,
      child.final_datasheet_id,submission.datasheet_id,sheet.latest_submission_id,sheet.status AS sheet_status,
      run.id AS run_id,run.workflow_version_id,run.current_state_id,run.revision AS run_revision,run.status AS run_status
    FROM public.job_submission_members chosen JOIN public.test_requests child ON child.organization_id=chosen.organization_id AND child.id=chosen.test_request_id
    JOIN public.datasheet_submissions submission ON submission.organization_id=chosen.organization_id AND submission.id=chosen.submission_id
    JOIN public.datasheets sheet ON sheet.organization_id=submission.organization_id AND sheet.id=submission.datasheet_id
    LEFT JOIN public.workflow_runs run ON run.organization_id=child.organization_id AND run.test_request_id=child.id
    WHERE chosen.organization_id=org AND chosen.parent_submission_id=parent_history.datasheet_submission_id AND child.parent_test_request_id=job_id
    ORDER BY child.id LOOP
    IF EXISTS (SELECT 1 FROM public.approval_cases WHERE organization_id=org AND workflow_run_id=member.run_id AND status='pending') THEN
      RAISE EXCEPTION 'A linked test request has an independent approval pending' USING ERRCODE='23514';
    END IF;
    IF (next_status='cancelled' AND member.request_status='cancelled') OR (next_status<>'cancelled' AND member.request_status='approved') THEN CONTINUE; END IF;
    IF member.final_datasheet_id IS DISTINCT FROM member.datasheet_id OR member.latest_submission_id IS DISTINCT FROM member.submission_id
      OR member.sheet_status NOT IN ('under_review','approved') OR member.request_status NOT IN ('under_review','approved')
      OR (next_status<>'cancelled' AND member.run_id IS NOT NULL AND member.run_status<>'active') THEN
      RAISE EXCEPTION 'A job decision must govern its unchanged submitted child results' USING ERRCODE='23514';
    END IF;
    INSERT INTO public.job_workflow_effects(organization_id,parent_history_id,parent_run_revision,job_submission_member_id,
      child_workflow_run_id,child_workflow_version_id,child_state_id,child_run_revision)
      VALUES(org,history_id,parent_run.revision,member.member_id,member.run_id,member.workflow_version_id,member.current_state_id,member.run_revision);
    IF parent_history.action='rejected' THEN
      UPDATE public.test_requests SET status='rejected',revision=revision+1 WHERE organization_id=org AND id=member.request_id;
      UPDATE public.datasheets SET status='rejected',revision=revision+1 WHERE organization_id=org AND test_request_id=member.request_id AND status<>'void';
    ELSIF next_status='completed' THEN
      UPDATE public.test_requests SET status='approved',completed_at=parent_history.occurred_at,revision=revision+1 WHERE organization_id=org AND id=member.request_id;
      UPDATE public.datasheets SET status='approved',revision=revision+1 WHERE organization_id=org AND id=member.datasheet_id;
      UPDATE public.sample_tests SET status='completed' WHERE organization_id=org AND id=member.sample_test_id;
    ELSIF next_status='cancelled' THEN
      UPDATE public.test_requests SET status='cancelled',revision=revision+1 WHERE organization_id=org AND id=member.request_id;
      UPDATE public.datasheets SET status='void',revision=revision+1 WHERE organization_id=org AND test_request_id=member.request_id AND status<>'void';
    END IF;
    IF member.run_id IS NOT NULL THEN
      UPDATE public.workflow_runs SET status=next_status,revision=revision+1,
        completed_at=CASE WHEN next_status='active' THEN NULL ELSE parent_history.occurred_at END
        WHERE organization_id=org AND id=member.run_id;
    END IF;
    applied:=applied+1;
  END LOOP;
  RETURN applied;
END $$;


--
-- Name: workflow_apply_sample_transition(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_apply_sample_transition(selected_run uuid, selected_transition uuid, expected_revision integer, remarks text) RETURNS TABLE(revision integer, status text, history_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  run public.workflow_runs; transition public.workflow_transitions; target public.workflow_states; approved boolean; next_status text;
  total_count bigint; allocated_count bigint; approved_count bigint; recorded_history uuid;
BEGIN
  IF NOT public.workflow_lock_run(selected_run) OR actor IS NULL OR length(remarks)>5000 THEN
    RAISE EXCEPTION 'Invalid workflow transition request' USING ERRCODE='42501';
  END IF;
  SELECT * INTO run FROM public.workflow_runs WHERE organization_id=org AND id=selected_run;
  SELECT * INTO transition FROM public.workflow_transitions WHERE organization_id=org AND id=selected_transition
    AND workflow_version_id=run.workflow_version_id AND source_state_id=run.current_state_id;
  IF run.status<>'active' OR run.revision<>expected_revision OR run.sample_id IS NULL OR transition.id IS NULL
    OR EXISTS (SELECT 1 FROM public.approval_cases pending WHERE pending.organization_id=org AND pending.workflow_run_id=run.id AND pending.status='pending') THEN
    RAISE EXCEPTION 'Workflow changed or an approval is pending' USING ERRCODE='23514';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.approval_cases approval JOIN public.approval_stages stage
    ON stage.organization_id=approval.organization_id AND stage.approval_case_id=approval.id
    JOIN public.approval_assignments assignment ON assignment.organization_id=stage.organization_id AND assignment.approval_stage_id=stage.id
    JOIN public.approval_decisions decision ON decision.organization_id=assignment.organization_id AND decision.approval_assignment_id=assignment.id
    WHERE approval.organization_id=org AND approval.workflow_run_id=run.id AND approval.transition_id=transition.id AND approval.run_revision=expected_revision
      AND approval.status='approved' AND approval.resolved_at=transaction_timestamp() AND decision.decided_by=actor AND decision.decided_at=transaction_timestamp()) INTO approved;
  IF NOT ((transition.approval_mode='none' AND public.workflow_can_request(transition.id)) OR (approved AND public.app_has_permission('approvals.respond'))) THEN
    RAISE EXCEPTION 'This transition requires its configured approval' USING ERRCODE='42501';
  END IF;
  IF transition.require_comment AND nullif(trim(remarks),'') IS NULL THEN RAISE EXCEPTION 'A transition comment is required' USING ERRCODE='23514'; END IF;
  SELECT * INTO target FROM public.workflow_states WHERE organization_id=org AND id=transition.target_state_id;
  IF target.require_all_test_requests_allocated OR target.require_all_test_requests_approved THEN
    PERFORM request.id FROM public.test_requests request JOIN public.sample_tests selected ON selected.organization_id=request.organization_id AND selected.id=request.sample_test_id
      JOIN public.sample_products product ON product.organization_id=selected.organization_id AND product.id=selected.sample_product_id
      WHERE request.organization_id=org AND product.sample_id=run.sample_id ORDER BY request.id FOR SHARE OF request;
    SELECT count(*), count(*) FILTER (WHERE EXISTS (SELECT 1 FROM public.test_request_assignments assignment
        WHERE assignment.organization_id=request.organization_id AND assignment.test_request_id=request.id AND assignment.assignment_type='analyst' AND assignment.unassigned_at IS NULL)),
      count(*) FILTER (WHERE request.status='approved') INTO total_count,allocated_count,approved_count
      FROM public.test_requests request JOIN public.sample_tests selected ON selected.organization_id=request.organization_id AND selected.id=request.sample_test_id
      JOIN public.sample_products product ON product.organization_id=selected.organization_id AND product.id=selected.sample_product_id
      WHERE request.organization_id=org AND product.sample_id=run.sample_id AND request.status<>'cancelled';
    IF total_count=0 OR (target.require_all_test_requests_allocated AND allocated_count<>total_count) OR (target.require_all_test_requests_approved AND approved_count<>total_count) THEN
      RAISE EXCEPTION 'Required test requests are not allocated or approved' USING ERRCODE='23514';
    END IF;
  END IF;
  next_status:=CASE WHEN target.state_type='cancelled' THEN 'cancelled' WHEN target.state_type='final' THEN 'completed' ELSE 'active' END;
  UPDATE public.workflow_runs stored SET current_state_id=target.id, status=next_status, revision=stored.revision+1,
    completed_at=CASE WHEN next_status<>'active' THEN transaction_timestamp() ELSE NULL END WHERE stored.organization_id=org AND stored.id=run.id;
  IF next_status<>'active' THEN UPDATE public.samples SET status=next_status, revision=samples.revision+1, updated_at=now() WHERE organization_id=org AND id=run.sample_id; END IF;
  INSERT INTO public.workflow_run_history(organization_id,workflow_run_id,workflow_version_id,from_state_id,to_state_id,transition_id,action,actor_user_id,comment)
    VALUES(org,run.id,run.workflow_version_id,run.current_state_id,target.id,transition.id,
      CASE WHEN next_status='completed' THEN 'completed' WHEN next_status='cancelled' THEN 'cancelled' WHEN approved THEN 'approved' ELSE 'transitioned' END,actor,remarks) RETURNING id INTO recorded_history;
  RETURN QUERY SELECT expected_revision+1,next_status,recorded_history;
END $$;


--
-- Name: workflow_apply_test_request_transition(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_apply_test_request_transition(selected_run uuid, selected_transition uuid, expected_revision integer, remarks text) RETURNS TABLE(revision integer, status text, history_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  run public.workflow_runs; transition public.workflow_transitions; target public.workflow_states;
  approved boolean; next_status text; recorded_history uuid; result_id uuid;
BEGIN
  IF NOT public.workflow_lock_run(selected_run) OR actor IS NULL OR length(remarks)>5000 THEN RAISE EXCEPTION 'Invalid workflow transition request' USING ERRCODE='42501'; END IF;
  SELECT * INTO run FROM public.workflow_runs WHERE organization_id=org AND id=selected_run;
  SELECT * INTO transition FROM public.workflow_transitions WHERE organization_id=org AND id=selected_transition
    AND workflow_version_id=run.workflow_version_id AND source_state_id=run.current_state_id;
  IF run.status<>'active' OR run.revision<>expected_revision OR run.test_request_id IS NULL OR transition.id IS NULL
    OR EXISTS (SELECT 1 FROM public.approval_cases pending WHERE pending.organization_id=org AND pending.workflow_run_id=run.id AND pending.status='pending') THEN
    RAISE EXCEPTION 'Workflow changed or an approval is pending' USING ERRCODE='23514';
  END IF;
  result_id:=public.workflow_test_request_submission(run.test_request_id);
  IF result_id IS NULL THEN RAISE EXCEPTION 'A frozen submitted result and analyst allocation are required' USING ERRCODE='23514'; END IF;
  SELECT EXISTS (SELECT 1 FROM public.approval_cases approval JOIN public.workflow_run_history request_history ON request_history.organization_id=approval.organization_id AND request_history.id=approval.request_history_id
    JOIN public.approval_stages stage ON stage.organization_id=approval.organization_id AND stage.approval_case_id=approval.id
    JOIN public.approval_assignments assignment ON assignment.organization_id=stage.organization_id AND assignment.approval_stage_id=stage.id
    JOIN public.approval_decisions decision ON decision.organization_id=assignment.organization_id AND decision.approval_assignment_id=assignment.id
    WHERE approval.organization_id=org AND approval.workflow_run_id=run.id AND approval.transition_id=transition.id AND approval.run_revision=expected_revision
      AND approval.status='approved' AND approval.resolved_at=transaction_timestamp() AND decision.decided_by=actor AND decision.decided_at=transaction_timestamp()
      AND request_history.datasheet_submission_id=result_id) INTO approved;
  IF NOT ((transition.approval_mode='none' AND public.workflow_can_request(transition.id)) OR (approved AND public.app_has_permission('approvals.respond'))) THEN
    RAISE EXCEPTION 'This transition requires its configured approval for this result' USING ERRCODE='42501';
  END IF;
  IF transition.require_comment AND nullif(trim(remarks),'') IS NULL THEN RAISE EXCEPTION 'A transition comment is required' USING ERRCODE='23514'; END IF;
  SELECT * INTO target FROM public.workflow_states WHERE organization_id=org AND id=transition.target_state_id;
  next_status:=CASE WHEN target.state_type='cancelled' THEN 'cancelled' WHEN target.state_type='final' THEN 'completed' ELSE 'active' END;
  UPDATE public.workflow_runs stored SET current_state_id=target.id,status=next_status,revision=stored.revision+1,
    completed_at=CASE WHEN next_status<>'active' THEN transaction_timestamp() ELSE NULL END WHERE stored.organization_id=org AND stored.id=run.id;
  IF next_status='completed' THEN
    UPDATE public.test_requests request SET status='approved',completed_at=now(),revision=request.revision+1 WHERE request.organization_id=org AND request.id=run.test_request_id;
    -- Only the selected, submitted datasheet was approved by this transition.
    -- An unsubmitted alternative must never acquire invented approval evidence.
    UPDATE public.datasheets sheet SET status='approved',revision=sheet.revision+1 FROM public.test_requests request
      WHERE request.organization_id=org AND request.id=run.test_request_id AND sheet.organization_id=org AND sheet.id=request.final_datasheet_id;
    UPDATE public.sample_tests selected SET status='completed' FROM public.test_requests request
      WHERE request.organization_id=org AND request.id=run.test_request_id AND selected.organization_id=org AND selected.id=request.sample_test_id;
  ELSIF next_status='cancelled' THEN
    UPDATE public.test_requests request SET status='cancelled',revision=request.revision+1 WHERE request.organization_id=org AND request.id=run.test_request_id;
    UPDATE public.datasheets sheet SET status='void',revision=sheet.revision+1 WHERE sheet.organization_id=org AND sheet.test_request_id=run.test_request_id AND sheet.status<>'void';
  END IF;
  INSERT INTO public.workflow_run_history(organization_id,workflow_run_id,workflow_version_id,from_state_id,to_state_id,transition_id,datasheet_submission_id,action,actor_user_id,comment)
    VALUES(org,run.id,run.workflow_version_id,run.current_state_id,target.id,transition.id,result_id,
      CASE WHEN next_status='completed' THEN 'completed' WHEN next_status='cancelled' THEN 'cancelled' WHEN approved THEN 'approved' ELSE 'transitioned' END,actor,remarks) RETURNING id INTO recorded_history;
  PERFORM public.workflow_apply_job_effects(recorded_history);
  RETURN QUERY SELECT expected_revision+1,next_status,recorded_history;
END $$;


--
-- Name: workflow_approver_candidates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_approver_candidates(selected_transition uuid) RETURNS TABLE(stage_number integer, role_id uuid, user_id uuid, display_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT configured.stage_number, configured.role_id, membership.user_id, person.display_name
    FROM public.workflow_transition_approver_roles configured JOIN public.membership_roles assignment
      ON assignment.organization_id = configured.organization_id AND assignment.role_id = configured.role_id
    JOIN public.memberships membership ON membership.organization_id = assignment.organization_id AND membership.user_id = assignment.user_id AND membership.active
    JOIN public.users person ON person.id = membership.user_id AND person.active
    WHERE configured.organization_id = nullif(current_setting('app.organization_id', true), '')::uuid AND configured.transition_id = selected_transition
      AND (public.laboratory_can_read() OR public.app_has_permission('workflows.manage'))
    ORDER BY configured.stage_number, membership.user_id, configured.role_id
$$;


--
-- Name: workflow_can_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_can_request(selected_transition uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT (public.app_has_permission('samples.manage') OR public.app_has_permission('datasheets.execute')
      OR public.app_has_permission('approvals.respond') OR public.app_has_permission('documents.manage'))
    AND EXISTS (SELECT 1 FROM public.workflow_transitions transition
      WHERE transition.organization_id=nullif(current_setting('app.organization_id',true),'')::uuid AND transition.id=selected_transition
      AND (NOT EXISTS (SELECT 1 FROM public.workflow_transition_creator_roles creator WHERE creator.organization_id=transition.organization_id AND creator.transition_id=transition.id)
        OR EXISTS (SELECT 1 FROM public.workflow_transition_creator_roles creator JOIN public.membership_roles membership
          ON membership.organization_id=creator.organization_id AND membership.role_id=creator.role_id
          WHERE creator.organization_id=transition.organization_id AND creator.transition_id=transition.id
            AND membership.user_id=nullif(current_setting('app.user_id',true),'')::uuid)))
$$;


--
-- Name: workflow_complete_job_effect(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_complete_job_effect() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE target_type text; member_request uuid; member_sheet uuid; parent_time timestamptz; parent_action text;
BEGIN
  SELECT target.state_type,chosen.test_request_id,submission.datasheet_id,history.occurred_at,history.action
    INTO target_type,member_request,member_sheet,parent_time,parent_action
    FROM public.job_submission_members chosen JOIN public.datasheet_submissions submission ON submission.organization_id=chosen.organization_id AND submission.id=chosen.submission_id
    JOIN public.workflow_run_history history ON history.organization_id=chosen.organization_id AND history.datasheet_submission_id=chosen.parent_submission_id AND history.id=NEW.parent_history_id
    JOIN public.workflow_states target ON target.organization_id=history.organization_id AND target.id=history.to_state_id
    WHERE chosen.organization_id=NEW.organization_id AND chosen.id=NEW.job_submission_member_id;
  IF member_request IS NULL OR parent_action NOT IN ('completed','cancelled','approved','transitioned','rejected') THEN
    RAISE EXCEPTION 'Job effect does not match its actual parent decision and child submission' USING ERRCODE='23514';
  END IF;
  -- A later transition in the same transaction may supersede the current status.
  IF EXISTS (SELECT 1 FROM public.job_workflow_effects WHERE organization_id=NEW.organization_id
    AND job_submission_member_id=NEW.job_submission_member_id AND parent_run_revision>NEW.parent_run_revision) THEN RETURN NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.test_requests request JOIN public.datasheets sheet ON sheet.organization_id=request.organization_id AND sheet.id=member_sheet
      WHERE request.organization_id=NEW.organization_id AND request.id=member_request
        AND ((parent_action='rejected' AND request.status='rejected' AND sheet.status='rejected')
          OR (target_type='final' AND request.status='approved' AND sheet.status='approved' AND request.completed_at=parent_time)
          OR (target_type='cancelled' AND request.status='cancelled' AND sheet.status='void')
          OR (parent_action<>'rejected' AND target_type NOT IN ('final','cancelled') AND request.status='under_review' AND sheet.status='under_review')))
    OR (NEW.child_workflow_run_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.workflow_runs
      WHERE organization_id=NEW.organization_id AND id=NEW.child_workflow_run_id AND test_request_id=member_request
        AND workflow_version_id=NEW.child_workflow_version_id AND current_state_id=NEW.child_state_id AND revision=NEW.child_run_revision+1
        AND status=CASE WHEN target_type='final' THEN 'completed' WHEN target_type='cancelled' THEN 'cancelled' ELSE 'active' END
        AND completed_at IS NOT DISTINCT FROM CASE WHEN target_type IN ('final','cancelled') THEN parent_time ELSE NULL END)) THEN
    RAISE EXCEPTION 'Actual child state changes and parent workflow evidence must commit together' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: workflow_editor_command_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_editor_command_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid; master public.workflows; source public.workflow_versions; target public.workflow_versions; present boolean;
BEGIN
  IF TG_OP<>'INSERT' THEN
    RAISE EXCEPTION 'Workflow command receipts are immutable' USING ERRCODE='55000',CONSTRAINT='workflow_editor_command_immutable';
  END IF;
  actor:=public.workflow_metadata_require_actor();
  IF NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid OR NEW.saved_by IS DISTINCT FROM actor THEN
    RAISE EXCEPTION 'Workflow command actor does not match the active session' USING ERRCODE='42501',CONSTRAINT='workflow_metadata_session_required';
  END IF;
  SELECT * INTO master FROM public.workflows WHERE organization_id=NEW.organization_id AND id=NEW.workflow_id FOR UPDATE;
  SELECT * INTO source FROM public.workflow_versions WHERE organization_id=NEW.organization_id AND id=NEW.source_version_id FOR UPDATE;
  IF NEW.workflow_version_id=NEW.source_version_id THEN target:=source;
  ELSE SELECT * INTO target FROM public.workflow_versions WHERE organization_id=NEW.organization_id AND id=NEW.workflow_version_id FOR UPDATE;
  END IF;
  PERFORM public.workflow_metadata_require_actor();
  IF master.id IS NULL OR NOT master.active OR source.workflow_id IS DISTINCT FROM master.id OR target.workflow_id IS DISTINCT FROM master.id
    OR target.revision IS DISTINCT FROM NEW.revision
    OR target.status IS DISTINCT FROM (CASE WHEN NEW.operation='publish' THEN 'published' ELSE 'draft' END) THEN
    RAISE EXCEPTION 'Workflow command result does not match the saved version' USING ERRCODE='23514',CONSTRAINT='workflow_editor_command_result';
  END IF;
  IF NEW.source_version_id<>NEW.workflow_version_id AND
    (source.status<>'published' OR source.revision<>NEW.source_revision OR target.created_by<>actor OR target.created_at<>transaction_timestamp()) THEN
    RAISE EXCEPTION 'Workflow command draft must be created from the requested published version in this transaction'
      USING ERRCODE='23514',CONSTRAINT='workflow_editor_command_source';
  END IF;
  IF NEW.operation IN ('create_state','patch_state') THEN
    SELECT EXISTS(SELECT 1 FROM public.workflow_states WHERE organization_id=NEW.organization_id AND workflow_version_id=NEW.workflow_version_id AND id=NEW.element_id) INTO present;
  ELSIF NEW.operation IN ('create_transition','patch_transition') THEN
    SELECT EXISTS(SELECT 1 FROM public.workflow_transitions WHERE organization_id=NEW.organization_id AND workflow_version_id=NEW.workflow_version_id AND id=NEW.element_id) INTO present;
  ELSIF NEW.operation='delete_state' THEN
    SELECT NOT EXISTS(SELECT 1 FROM public.workflow_states WHERE organization_id=NEW.organization_id AND id=NEW.element_id) INTO present;
  ELSIF NEW.operation='delete_transition' THEN
    SELECT NOT EXISTS(SELECT 1 FROM public.workflow_transitions WHERE organization_id=NEW.organization_id AND id=NEW.element_id) INTO present;
  ELSE present:=NEW.operation IN ('publish','save_draft');
  END IF;
  IF NOT present THEN
    RAISE EXCEPTION 'Workflow command element does not match the saved result' USING ERRCODE='23514',CONSTRAINT='workflow_editor_command_result';
  END IF;
  IF NEW.source_version_id<>NEW.workflow_version_id AND NEW.source_element_id IS NOT NULL THEN
    IF NEW.operation IN ('patch_state','delete_state') THEN
      SELECT EXISTS(SELECT 1 FROM public.workflow_states WHERE organization_id=NEW.organization_id AND workflow_version_id=NEW.source_version_id AND id=NEW.source_element_id) INTO present;
    ELSE
      SELECT EXISTS(SELECT 1 FROM public.workflow_transitions WHERE organization_id=NEW.organization_id AND workflow_version_id=NEW.source_version_id AND id=NEW.source_element_id) INTO present;
    END IF;
    IF NOT present THEN
      RAISE EXCEPTION 'Workflow command source element is unavailable' USING ERRCODE='23514',CONSTRAINT='workflow_editor_command_source';
    END IF;
  END IF;
  NEW.saved_at:=clock_timestamp(); NEW.created_transaction_id:=pg_current_xact_id();
  RETURN NEW;
END $$;


--
-- Name: workflow_generating_sample(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_generating_sample() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT run.sample_id FROM public.workflow_runs run JOIN public.workflow_states state
    ON state.organization_id=run.organization_id AND state.id=run.current_state_id
    WHERE run.organization_id=nullif(current_setting('app.organization_id',true),'')::uuid
      AND run.id=nullif(current_setting('app.workflow_generation_run_id',true),'')::uuid AND run.sample_id IS NOT NULL AND state.generate_test_requests
      AND (public.app_has_permission('samples.manage') OR public.app_has_permission('datasheets.execute') OR public.app_has_permission('approvals.respond'))
      AND EXISTS (SELECT 1 FROM public.workflow_run_history history WHERE history.organization_id=run.organization_id AND history.workflow_run_id=run.id
        AND history.to_state_id=run.current_state_id AND history.action IN ('transitioned','approved','completed')
        AND history.actor_user_id=nullif(current_setting('app.user_id',true),'')::uuid AND history.occurred_at=transaction_timestamp())
$$;


--
-- Name: workflow_guard_active_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_guard_active_reference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE target uuid; initial_creation boolean:=false;
BEGIN
  IF session_user='sampleify_app' AND NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid THEN
    RAISE EXCEPTION 'Workflow references require the current organization' USING ERRCODE='42501';
  END IF;
  IF TG_TABLE_NAME='organization_laboratory_settings' THEN target:=NEW.job_workflow_id;
  ELSIF TG_TABLE_NAME='workflow_runs' THEN
    SELECT workflow_id INTO target FROM public.workflow_versions WHERE organization_id=NEW.organization_id AND id=NEW.workflow_version_id;
  ELSE
    target:=NEW.workflow_id;
    IF TG_TABLE_NAME='workflow_versions' THEN initial_creation:=TG_OP='INSERT' AND NEW.number=1; END IF;
  END IF;
  IF target IS NULL THEN RETURN NEW; END IF;
  PERFORM 1 FROM public.workflows workflow WHERE workflow.organization_id=NEW.organization_id AND workflow.id=target
    AND (workflow.active OR (initial_creation AND workflow.metadata_revision=1 AND workflow.created_at=transaction_timestamp()
      AND workflow.created_by=nullif(current_setting('app.user_id',true),'')::uuid AND NOT EXISTS (
        SELECT 1 FROM public.workflow_metadata_versions history WHERE history.organization_id=workflow.organization_id AND history.workflow_id=workflow.id))) FOR SHARE OF workflow;
  IF NOT FOUND THEN RAISE EXCEPTION 'Select an active workflow' USING ERRCODE='23514',CONSTRAINT='workflow_active_reference'; END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_guard_approval_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_guard_approval_assignment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE selected_transition uuid; selected_stage integer; history_id uuid; history public.workflow_run_history; decision public.approval_decisions;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT approval.transition_id, stage.stage_number, request.id INTO selected_transition, selected_stage, history_id
      FROM public.approval_stages stage JOIN public.approval_cases approval ON approval.organization_id = stage.organization_id AND approval.id = stage.approval_case_id
      JOIN public.workflow_run_history request ON request.organization_id = approval.organization_id AND request.id = approval.request_history_id
      WHERE stage.organization_id = NEW.organization_id AND stage.id = NEW.approval_stage_id AND approval.status = 'pending';
    SELECT * INTO history FROM public.workflow_run_history WHERE organization_id = NEW.organization_id AND id = history_id;
    IF NEW.status <> 'pending' OR selected_transition IS NULL
      OR (current_user = 'sampleify_app' AND (history.actor_user_id IS DISTINCT FROM nullif(current_setting('app.user_id', true), '')::uuid OR history.occurred_at <> transaction_timestamp()
        OR NOT EXISTS (SELECT 1 FROM public.workflow_approver_candidates(selected_transition) candidate
          WHERE candidate.stage_number = selected_stage AND candidate.role_id = NEW.source_role_id AND candidate.user_id = NEW.assigned_user_id))) THEN
      RAISE EXCEPTION 'Approval assignments must be active configured request recipients' USING ERRCODE = '42501';
    END IF;
    IF current_user = 'sampleify_app' THEN NEW.assigned_at := transaction_timestamp(); END IF;
  ELSE
    IF OLD.status <> 'pending' OR (NEW.organization_id, NEW.id, NEW.approval_stage_id, NEW.assigned_user_id, NEW.source_role_id, NEW.assigned_at)
      IS DISTINCT FROM (OLD.organization_id, OLD.id, OLD.approval_stage_id, OLD.assigned_user_id, OLD.source_role_id, OLD.assigned_at) THEN
      RAISE EXCEPTION 'Approval assignment identity and responses are immutable' USING ERRCODE = '55000';
    END IF;
    IF NEW.status IN ('approved', 'rejected') THEN
      SELECT * INTO decision FROM public.approval_decisions WHERE organization_id = NEW.organization_id AND approval_assignment_id = NEW.id;
      IF decision.id IS NULL OR NEW.status <> (CASE WHEN decision.decision = 'approve' THEN 'approved' ELSE 'rejected' END) THEN
        RAISE EXCEPTION 'Assignment responses require their actual decision' USING ERRCODE = '23514';
      END IF;
      NEW.responded_at := decision.decided_at;
    ELSIF NEW.status <> 'cancelled' THEN RAISE EXCEPTION 'Assignments require a decision or cancellation' USING ERRCODE = '23514'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_guard_approval_case(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_guard_approval_case() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE run public.workflow_runs; history public.workflow_run_history;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO run FROM public.workflow_runs WHERE organization_id = NEW.organization_id AND id = NEW.workflow_run_id;
    SELECT * INTO history FROM public.workflow_run_history WHERE organization_id = NEW.organization_id AND id = NEW.request_history_id;
    IF NEW.status <> 'pending' OR run.status IS DISTINCT FROM 'active' OR run.revision IS DISTINCT FROM NEW.run_revision
      OR history.workflow_run_id IS DISTINCT FROM run.id OR history.action IS DISTINCT FROM 'requested'
      OR history.from_state_id IS DISTINCT FROM run.current_state_id
      OR (current_user = 'sampleify_app' AND (history.actor_user_id IS DISTINCT FROM nullif(current_setting('app.user_id', true), '')::uuid OR history.occurred_at <> transaction_timestamp())) THEN
      RAISE EXCEPTION 'Approval case requires a current recorded request' USING ERRCODE = '23514';
    END IF;
  ELSE
    IF OLD.status <> 'pending' OR (NEW.organization_id, NEW.id, NEW.workflow_run_id, NEW.workflow_version_id, NEW.transition_id, NEW.request_history_id, NEW.run_revision)
      IS DISTINCT FROM (OLD.organization_id, OLD.id, OLD.workflow_run_id, OLD.workflow_version_id, OLD.transition_id, OLD.request_history_id, OLD.run_revision) THEN
      RAISE EXCEPTION 'Approval case identity and completed evidence are immutable' USING ERRCODE = '55000';
    END IF;
    IF NEW.status = 'approved' AND (NOT EXISTS (SELECT 1 FROM public.approval_stages WHERE organization_id = NEW.organization_id AND approval_case_id = NEW.id)
      OR EXISTS (SELECT 1 FROM public.approval_stages WHERE organization_id = NEW.organization_id AND approval_case_id = NEW.id AND status <> 'approved')) THEN
      RAISE EXCEPTION 'Every approval stage must be approved' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'rejected' AND NOT EXISTS (SELECT 1 FROM public.approval_stages WHERE organization_id = NEW.organization_id AND approval_case_id = NEW.id AND status = 'rejected') THEN
      RAISE EXCEPTION 'Rejection requires an actual rejected stage' USING ERRCODE = '23514';
    END IF;
    IF current_user = 'sampleify_app' AND NEW.status <> 'pending' THEN NEW.resolved_at := transaction_timestamp(); END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_guard_approval_decision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_guard_approval_decision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF current_user = 'sampleify_app' AND (NEW.decided_by IS DISTINCT FROM nullif(current_setting('app.user_id', true), '')::uuid OR NOT public.app_has_permission('approvals.respond')) THEN
    RAISE EXCEPTION 'Approval decision requires the actual authorized responder' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.approval_assignments assignment JOIN public.approval_stages stage
    ON stage.organization_id = assignment.organization_id AND stage.id = assignment.approval_stage_id
    JOIN public.approval_cases approval ON approval.organization_id = stage.organization_id AND approval.id = stage.approval_case_id
    JOIN public.workflow_runs run ON run.organization_id = approval.organization_id AND run.id = approval.workflow_run_id
    WHERE assignment.organization_id = NEW.organization_id AND assignment.id = NEW.approval_assignment_id AND assignment.assigned_user_id = NEW.decided_by
      AND assignment.status = 'pending' AND stage.status = 'pending' AND approval.status = 'pending' AND run.status = 'active' AND run.revision = approval.run_revision) THEN
    RAISE EXCEPTION 'Only the active assigned approver may respond' USING ERRCODE = '42501';
  END IF;
  IF current_user = 'sampleify_app' THEN NEW.decided_at := transaction_timestamp(); END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_guard_approval_publication(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_guard_approval_publication() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.status = 'published' AND OLD.status = 'draft' AND EXISTS (
    SELECT 1 FROM public.workflow_transitions transition WHERE transition.organization_id = NEW.organization_id AND transition.workflow_version_id = NEW.id AND
      ((transition.approval_mode = 'none') = EXISTS (SELECT 1 FROM public.workflow_transition_approver_roles role
        WHERE role.organization_id = transition.organization_id AND role.transition_id = transition.id)
      OR (transition.approval_mode <> 'sequential' AND EXISTS (SELECT 1 FROM public.workflow_transition_approver_roles role
        WHERE role.organization_id = transition.organization_id AND role.transition_id = transition.id AND role.stage_number <> 1)))) THEN
    RAISE EXCEPTION 'Approval modes require matching configured stages' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_guard_approval_stage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_guard_approval_stage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE approval public.approval_cases; history public.workflow_run_history; mode text;
BEGIN
  SELECT * INTO approval FROM public.approval_cases WHERE organization_id = NEW.organization_id AND id = NEW.approval_case_id;
  IF approval.status IS DISTINCT FROM 'pending' THEN RAISE EXCEPTION 'Completed approval stages are immutable' USING ERRCODE = '55000'; END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO history FROM public.workflow_run_history WHERE organization_id = NEW.organization_id AND id = approval.request_history_id;
    SELECT approval_mode INTO mode FROM public.workflow_transitions WHERE organization_id = NEW.organization_id AND id = approval.transition_id;
    IF NEW.status NOT IN ('pending', 'waiting') OR NEW.completion_rule <> (CASE WHEN mode = 'any' THEN 'any' ELSE 'all' END)
      OR NOT EXISTS (SELECT 1 FROM public.workflow_transition_approver_roles WHERE organization_id = NEW.organization_id AND transition_id = approval.transition_id AND stage_number = NEW.stage_number)
      OR (current_user = 'sampleify_app' AND (history.actor_user_id IS DISTINCT FROM nullif(current_setting('app.user_id', true), '')::uuid OR history.occurred_at <> transaction_timestamp())) THEN
      RAISE EXCEPTION 'Approval stages must match the recorded request' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'pending' AND EXISTS (SELECT 1 FROM public.workflow_transition_approver_roles
      WHERE organization_id = NEW.organization_id AND transition_id = approval.transition_id AND stage_number < NEW.stage_number) THEN
      RAISE EXCEPTION 'Only the first approval stage may start pending' USING ERRCODE = '23514';
    END IF;
  ELSE
    IF OLD.status NOT IN ('pending', 'waiting') OR (NEW.organization_id, NEW.id, NEW.approval_case_id, NEW.stage_number, NEW.completion_rule)
      IS DISTINCT FROM (OLD.organization_id, OLD.id, OLD.approval_case_id, OLD.stage_number, OLD.completion_rule)
      OR (OLD.status = 'pending' AND NEW.activated_at IS DISTINCT FROM OLD.activated_at) THEN
      RAISE EXCEPTION 'Approval stage identity and completed evidence are immutable' USING ERRCODE = '55000';
    END IF;
    IF NEW.status = 'pending' AND (OLD.status <> 'waiting' OR EXISTS (SELECT 1 FROM public.approval_stages
      WHERE organization_id = NEW.organization_id AND approval_case_id = NEW.approval_case_id AND stage_number < NEW.stage_number AND status <> 'approved')) THEN
      RAISE EXCEPTION 'Earlier stages must approve before the next stage starts' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'approved' AND (OLD.status <> 'pending'
      OR NOT EXISTS (SELECT 1 FROM public.approval_assignments WHERE organization_id = NEW.organization_id AND approval_stage_id = NEW.id AND status = 'approved')
      OR (NEW.completion_rule = 'all' AND EXISTS (SELECT 1 FROM public.approval_assignments WHERE organization_id = NEW.organization_id AND approval_stage_id = NEW.id AND status <> 'approved'))) THEN
      RAISE EXCEPTION 'Stage approval requires its recorded quorum' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'rejected' AND (OLD.status <> 'pending' OR NOT EXISTS (SELECT 1 FROM public.approval_assignments
      WHERE organization_id = NEW.organization_id AND approval_stage_id = NEW.id AND status = 'rejected')) THEN
      RAISE EXCEPTION 'Stage rejection requires a recorded rejection' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'waiting' THEN RAISE EXCEPTION 'Approval stages cannot return to waiting' USING ERRCODE = '23514'; END IF;
  END IF;
  IF current_user = 'sampleify_app' THEN
    IF NEW.status = 'pending' AND (TG_OP = 'INSERT' OR OLD.status = 'waiting') THEN NEW.activated_at := transaction_timestamp(); END IF;
    IF NEW.status IN ('approved', 'rejected', 'cancelled') THEN NEW.resolved_at := transaction_timestamp(); END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_guard_checklist_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_guard_checklist_reference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.checklist_master_id IS NOT NULL THEN
    -- Inactive masters remain valid historical references during either clone.
    PERFORM 1 FROM public.checklists WHERE organization_id=NEW.organization_id AND id=NEW.checklist_master_id AND retired_at IS NULL FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Workflow checklist is retired or unavailable' USING ERRCODE='23514',CONSTRAINT='workflow_checklist_unavailable'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_guard_clone_origin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_guard_clone_origin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE source_version public.workflow_versions; target_version public.workflow_versions;
  source_workflow public.workflows; creation public.workflow_metadata_versions;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Workflow clone origins are immutable' USING ERRCODE='55000'; END IF;
  SELECT * INTO source_version FROM public.workflow_versions WHERE organization_id=NEW.organization_id AND id=NEW.source_version_id;
  SELECT * INTO target_version FROM public.workflow_versions WHERE organization_id=NEW.organization_id AND id=NEW.workflow_version_id;
  SELECT * INTO source_workflow FROM public.workflows WHERE organization_id=NEW.organization_id AND id=NEW.source_workflow_id;
  SELECT * INTO creation FROM public.workflow_metadata_versions WHERE organization_id=NEW.organization_id AND request_id=NEW.request_id;
  IF NEW.created_by IS DISTINCT FROM public.workflow_metadata_require_actor()
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR NEW.created_at<>transaction_timestamp() OR NEW.created_transaction_id<>pg_current_xact_id()
    OR NOT source_workflow.active OR source_workflow.metadata_revision IS DISTINCT FROM NEW.source_metadata_revision
    OR (source_version.workflow_id,source_version.revision) IS DISTINCT FROM (NEW.source_workflow_id,NEW.source_revision)
    OR (NEW.requested_source_version_id IS NOT NULL AND NEW.requested_source_version_id<>NEW.source_version_id)
    OR (target_version.workflow_id,target_version.number,target_version.revision,target_version.status,target_version.created_by,target_version.created_at)
      IS DISTINCT FROM (NEW.workflow_id,1,NEW.cloned_revision,'draft'::text,NEW.created_by,NEW.created_at)
    OR (creation.workflow_id,creation.revision,creation.operation,creation.initial_version_id,creation.saved_by,creation.saved_at,creation.created_transaction_id)
      IS DISTINCT FROM (NEW.workflow_id,1,'create'::text,NEW.workflow_version_id,NEW.created_by,NEW.created_at,NEW.created_transaction_id) THEN
    RAISE EXCEPTION 'A workflow clone requires its actual source, creation and transaction' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_guard_decision_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_guard_decision_check() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actual_transition uuid; actor uuid; decided timestamptz;
BEGIN
  SELECT approval.transition_id, decision.decided_by, decision.decided_at INTO actual_transition,actor,decided
    FROM public.approval_decisions decision JOIN public.approval_assignments assignment ON assignment.organization_id=decision.organization_id AND assignment.id=decision.approval_assignment_id
    JOIN public.approval_stages stage ON stage.organization_id=assignment.organization_id AND stage.id=assignment.approval_stage_id
    JOIN public.approval_cases approval ON approval.organization_id=stage.organization_id AND approval.id=stage.approval_case_id
    WHERE decision.organization_id=NEW.organization_id AND decision.id=NEW.decision_id;
  IF actual_transition IS DISTINCT FROM NEW.transition_id OR (session_user='sampleify_app' AND
    (actor IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid OR decided<>transaction_timestamp())) THEN
    RAISE EXCEPTION 'Checklist evidence belongs to the actual current decision' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_guard_request_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_guard_request_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE history public.workflow_run_history;
BEGIN
  IF TG_TABLE_NAME = 'workflow_run_history' THEN
    IF NEW.transition_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.workflow_transitions transition
      WHERE transition.organization_id = NEW.organization_id AND transition.workflow_version_id = NEW.workflow_version_id AND transition.id = NEW.transition_id
        AND transition.source_state_id = NEW.from_state_id AND (transition.target_state_id = NEW.to_state_id OR (NEW.action = 'rejected' AND NEW.from_state_id = NEW.to_state_id))) THEN
      RAISE EXCEPTION 'History must identify the actual workflow edge' USING ERRCODE = '23514';
    END IF;
    IF current_user = 'sampleify_app' THEN NEW.occurred_at := transaction_timestamp(); END IF;
  ELSE
    SELECT * INTO history FROM public.workflow_run_history WHERE organization_id = NEW.organization_id AND id = NEW.history_id;
    IF history.transition_id IS DISTINCT FROM NEW.transition_id OR history.action NOT IN ('requested', 'transitioned', 'completed', 'cancelled')
      OR (current_user = 'sampleify_app' AND (history.actor_user_id IS DISTINCT FROM nullif(current_setting('app.user_id', true), '')::uuid OR history.occurred_at <> transaction_timestamp())) THEN
      RAISE EXCEPTION 'Checklist answers belong to the actual request' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_guard_result_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_guard_result_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE run public.workflow_runs;
BEGIN
  SELECT * INTO run FROM public.workflow_runs WHERE organization_id=NEW.organization_id AND id=NEW.workflow_run_id;
  IF NEW.datasheet_submission_id IS NOT NULL AND (run.test_request_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.datasheet_submissions submission JOIN public.datasheets sheet
    ON sheet.organization_id=submission.organization_id AND sheet.id=submission.datasheet_id WHERE submission.organization_id=NEW.organization_id
      AND submission.id=NEW.datasheet_submission_id AND sheet.test_request_id=run.test_request_id)) THEN
    RAISE EXCEPTION 'Workflow result evidence must belong to its test request' USING ERRCODE='23514';
  END IF;
  IF session_user='sampleify_app' AND run.test_request_id IS NOT NULL AND NEW.action IN ('requested','transitioned','approved','completed','cancelled')
    AND (NEW.datasheet_submission_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.test_requests request JOIN public.datasheets sheet
      ON sheet.organization_id=request.organization_id AND sheet.id=request.final_datasheet_id AND sheet.test_request_id=request.id
      JOIN public.datasheet_submissions submission ON submission.organization_id=sheet.organization_id AND submission.id=sheet.latest_submission_id
      JOIN public.template_instances capture ON capture.organization_id=sheet.organization_id AND capture.id=submission.instance_id
      WHERE request.organization_id=NEW.organization_id AND request.id=run.test_request_id AND submission.id=NEW.datasheet_submission_id
        AND capture.status='frozen' AND capture.revision=submission.capture_revision)) THEN
    RAISE EXCEPTION 'A transition must retain its actual frozen submitted result' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_guard_result_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_guard_result_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE request_id uuid; result_id uuid;
BEGIN
  IF session_user<>'sampleify_app' THEN RETURN NEW; END IF;
  SELECT run.test_request_id, history.datasheet_submission_id INTO request_id,result_id FROM public.workflow_runs run JOIN public.workflow_run_history history
    ON history.organization_id=run.organization_id AND history.workflow_run_id=run.id AND history.id=NEW.request_history_id
    WHERE run.organization_id=NEW.organization_id AND run.id=NEW.workflow_run_id;
  IF request_id IS NOT NULL THEN
    PERFORM 1 FROM public.test_requests WHERE organization_id=NEW.organization_id AND id=request_id FOR UPDATE;
    IF result_id IS NULL OR result_id IS DISTINCT FROM public.workflow_test_request_submission(request_id) THEN
      RAISE EXCEPTION 'Approval request must identify the submitted test request result' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_guard_transition_detail(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_guard_transition_detail() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid; selected_transition uuid; version_status text;
BEGIN
  IF TG_OP = 'DELETE' THEN org := OLD.organization_id; selected_transition := OLD.transition_id;
  ELSE org := NEW.organization_id; selected_transition := NEW.transition_id; END IF;
  IF TG_OP = 'UPDATE' AND (NEW.organization_id, NEW.transition_id) IS DISTINCT FROM (OLD.organization_id, OLD.transition_id) THEN
    RAISE EXCEPTION 'Workflow detail ownership is immutable' USING ERRCODE = '23514';
  END IF;
  SELECT version.status INTO version_status FROM public.workflow_versions version JOIN public.workflow_transitions transition
    ON transition.organization_id = version.organization_id AND transition.workflow_version_id = version.id
    WHERE transition.organization_id = org AND transition.id = selected_transition FOR UPDATE OF version;
  IF version_status IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'Only draft workflow details may change' USING ERRCODE = '55000'; END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_lock_run(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_lock_run(selected_run uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; run public.workflow_runs;
BEGIN
  IF org IS NULL OR NOT (public.app_has_permission('samples.manage') OR public.app_has_permission('datasheets.execute')
    OR public.app_has_permission('approvals.respond') OR public.app_has_permission('documents.manage')) THEN
    RAISE EXCEPTION 'Workflow action permission required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO run FROM public.workflow_runs WHERE organization_id=org AND id=selected_run;
  IF run.id IS NULL THEN RETURN false; END IF;
  IF run.sample_id IS NOT NULL THEN
    PERFORM 1 FROM public.samples WHERE organization_id=org AND id=run.sample_id FOR UPDATE;
  ELSIF run.document_id IS NOT NULL THEN
    PERFORM 1 FROM public.documents WHERE organization_id=org AND id=run.document_id FOR UPDATE;
  ELSE
    PERFORM public.laboratory_lock_request_sample(run.test_request_id);
    PERFORM 1 FROM public.test_requests WHERE organization_id=org AND id=run.test_request_id FOR UPDATE;
  END IF;
  PERFORM 1 FROM public.workflow_runs WHERE organization_id=org AND id=selected_run FOR UPDATE;
  IF EXISTS (SELECT 1 FROM public.laboratory_job_workflow_effects effect
    WHERE effect.organization_id=org AND effect.child_workflow_run_id=selected_run AND effect.is_current
      AND effect.action<>'rejected' AND effect.target_state_type NOT IN ('final','cancelled')) THEN
    RAISE EXCEPTION 'Continue this review from the parent job' USING ERRCODE='23514', CONSTRAINT='workflow_parent_job_controls';
  END IF;
  RETURN true;
END $$;


--
-- Name: workflow_master_clone(uuid, uuid, uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_master_clone(source_id uuid, target_id uuid, requested_id uuid, requested_version uuid, observed_metadata_revision integer, code_base text) RETURNS TABLE(workflow_id uuid, version_id uuid, metadata_revision integer, revision integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE actor uuid; org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
  source_workflow public.workflows; source_version public.workflow_versions; prior public.workflow_clone_origins;
  copied_version uuid; copied_revision integer; name_base text; next_name text; suffix integer:=2;
  state_ids uuid[]; state_copy_ids uuid[]; transition_ids uuid[]; transition_copy_ids uuid[];
BEGIN
  actor:=public.workflow_metadata_require_actor();
  PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
  actor:=public.workflow_metadata_require_actor();
  IF source_id IS NULL OR target_id IS NULL OR requested_id IS NULL OR source_id=target_id THEN
    RAISE EXCEPTION 'Invalid workflow clone identity' USING ERRCODE='23514',CONSTRAINT='workflow_clone_input';
  END IF;
  SELECT * INTO prior FROM public.workflow_clone_origins origin WHERE origin.organization_id=org AND origin.request_id=requested_id;
  IF FOUND THEN
    IF (prior.workflow_id,prior.source_workflow_id,prior.requested_source_version_id,prior.created_by)
      IS DISTINCT FROM (target_id,source_id,requested_version,actor) THEN
      RAISE EXCEPTION 'The clone request was already used for a different change' USING ERRCODE='23514',CONSTRAINT='workflow_clone_request_reused';
    END IF;
    RETURN QUERY SELECT prior.workflow_id,prior.workflow_version_id,1,prior.cloned_revision; RETURN;
  END IF;
  IF EXISTS(SELECT 1 FROM public.workflow_metadata_versions history WHERE history.organization_id=org AND history.request_id=requested_id) THEN
    RAISE EXCEPTION 'The clone request was already used for another workflow command' USING ERRCODE='23514',CONSTRAINT='workflow_clone_request_reused';
  END IF;
  SELECT * INTO source_workflow FROM public.workflows workflow WHERE workflow.organization_id=org AND workflow.id=source_id AND workflow.active FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Workflow was not found' USING ERRCODE='P0002',CONSTRAINT='workflow_metadata_not_found'; END IF;
  IF observed_metadata_revision IS DISTINCT FROM source_workflow.metadata_revision THEN
    RAISE EXCEPTION 'Workflow details changed before cloning' USING ERRCODE='23514',CONSTRAINT='workflow_metadata_stale';
  END IF;
  IF code_base IS NULL OR length(code_base) NOT BETWEEN 1 AND 56 OR code_base !~ '^[-A-Z0-9._/]+$' THEN
    RAISE EXCEPTION 'Invalid workflow clone code' USING ERRCODE='23514',CONSTRAINT='workflow_clone_input';
  END IF;
  SELECT * INTO source_version FROM public.workflow_versions version
    WHERE version.organization_id=org AND version.workflow_id=source_id
      AND ((requested_version IS NOT NULL AND version.id=requested_version) OR (requested_version IS NULL AND version.status IN ('draft','published')))
    ORDER BY CASE version.status WHEN 'draft' THEN 0 ELSE 1 END,version.number DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN
    IF requested_version IS NULL THEN RAISE EXCEPTION 'The workflow has no version to clone' USING ERRCODE='23514',CONSTRAINT='workflow_clone_version_required';
    ELSE RAISE EXCEPTION 'The selected version does not belong to this workflow' USING ERRCODE='23514',CONSTRAINT='workflow_clone_invalid_version'; END IF;
  END IF;
  name_base:=source_workflow.name||' - Copy'; next_name:=name_base;
  WHILE EXISTS(SELECT 1 FROM public.workflows workflow WHERE workflow.organization_id=org AND workflow.active AND workflow.name=next_name) LOOP
    next_name:=name_base||' '||suffix::text; suffix:=suffix+1;
  END LOOP;
  IF length(next_name)>200 THEN RAISE EXCEPTION 'Shorten the workflow name before cloning' USING ERRCODE='23514',CONSTRAINT='workflow_clone_name_too_long'; END IF;
  SELECT created.initial_version_id INTO copied_version FROM public.workflows_metadata_write(
    'create',target_id,0,requested_id,next_name,source_workflow.description,true,code_base,true,source_workflow.applies_to,true) created;
  UPDATE public.workflow_versions SET change_summary='Cloned from '||source_workflow.code,revision=workflow_versions.revision+1
    WHERE organization_id=org AND id=copied_version RETURNING workflow_versions.revision INTO copied_revision;

  SELECT coalesce(array_agg(id ORDER BY id),'{}'::uuid[]),coalesce(array_agg(new_id ORDER BY id),'{}'::uuid[])
    INTO state_ids,state_copy_ids FROM (SELECT state.id,gen_random_uuid() new_id FROM public.workflow_states state
      WHERE state.organization_id=org AND state.workflow_version_id=source_version.id) identities;
  SELECT coalesce(array_agg(id ORDER BY id),'{}'::uuid[]),coalesce(array_agg(new_id ORDER BY id),'{}'::uuid[])
    INTO transition_ids,transition_copy_ids FROM (SELECT transition.id,gen_random_uuid() new_id FROM public.workflow_transitions transition
      WHERE transition.organization_id=org AND transition.workflow_version_id=source_version.id) identities;

  INSERT INTO public.workflow_states("organization_id","id","workflow_version_id","code","name","description","state_type","display_order","color","canvas_x","canvas_y","input_count","output_count","badge_style","legacy_tr_state","template_id","show_sample_edit","show_sample_retest","show_sample_reissue","enable_template_validation","enable_critical_parameters_validation","show_add_result","generate_test_requests","require_all_test_requests_allocated","require_all_test_requests_approved","fetch_environment_data","can_work_on_test_request","is_positive_termination","enable_job_card")
    SELECT source."organization_id",map.new_id,copied_version,source."code",source."name",source."description",source."state_type",source."display_order",source."color",source."canvas_x",source."canvas_y",source."input_count",source."output_count",source."badge_style",source."legacy_tr_state",source."template_id",source."show_sample_edit",source."show_sample_retest",source."show_sample_reissue",source."enable_template_validation",source."enable_critical_parameters_validation",source."show_add_result",source."generate_test_requests",source."require_all_test_requests_allocated",source."require_all_test_requests_approved",source."fetch_environment_data",source."can_work_on_test_request",source."is_positive_termination",source."enable_job_card"
    FROM public.workflow_states source JOIN unnest(state_ids,state_copy_ids) AS map(id,new_id) ON map.id=source.id WHERE source.organization_id=org;
  INSERT INTO public.workflow_state_capability_roles("organization_id","workflow_state_id","capability","role_id")
    SELECT source."organization_id",map.new_id,source."capability",source."role_id"
    FROM public.workflow_state_capability_roles source JOIN unnest(state_ids,state_copy_ids) AS map(id,new_id) ON map.id=source.workflow_state_id WHERE source.organization_id=org;
  INSERT INTO public.workflow_transitions("organization_id","id","workflow_version_id","code","name","source_state_id","target_state_id","approval_mode","source_port","target_port","auto_execute","require_comment","display_order","checklist_master_id","checklist_master_revision","auto_move_mode")
    SELECT source."organization_id",map.new_id,copied_version,source."code",source."name",source_map.new_id,target_map.new_id,source."approval_mode",source."source_port",source."target_port",source."auto_execute",source."require_comment",source."display_order",source."checklist_master_id",source."checklist_master_revision",source."auto_move_mode"
    FROM public.workflow_transitions source JOIN unnest(transition_ids,transition_copy_ids) AS map(id,new_id) ON map.id=source.id
      JOIN unnest(state_ids,state_copy_ids) AS source_map(id,new_id) ON source_map.id=source.source_state_id
      JOIN unnest(state_ids,state_copy_ids) AS target_map(id,new_id) ON target_map.id=source.target_state_id WHERE source.organization_id=org;
  INSERT INTO public.workflow_transition_creator_roles("organization_id","transition_id","role_id")
    SELECT source."organization_id",map.new_id,source."role_id"
    FROM public.workflow_transition_creator_roles source JOIN unnest(transition_ids,transition_copy_ids) AS map(id,new_id) ON map.id=source.transition_id WHERE source.organization_id=org;
  INSERT INTO public.workflow_transition_approver_roles("organization_id","transition_id","role_id","stage_number")
    SELECT source."organization_id",map.new_id,source."role_id",source."stage_number"
    FROM public.workflow_transition_approver_roles source JOIN unnest(transition_ids,transition_copy_ids) AS map(id,new_id) ON map.id=source.transition_id WHERE source.organization_id=org;
  INSERT INTO public.workflow_transition_cc_roles("organization_id","transition_id","role_id")
    SELECT source."organization_id",map.new_id,source."role_id"
    FROM public.workflow_transition_cc_roles source JOIN unnest(transition_ids,transition_copy_ids) AS map(id,new_id) ON map.id=source.transition_id WHERE source.organization_id=org;
  INSERT INTO public.workflow_transition_cc_emails("organization_id","transition_id","email")
    SELECT source."organization_id",map.new_id,source."email"
    FROM public.workflow_transition_cc_emails source JOIN unnest(transition_ids,transition_copy_ids) AS map(id,new_id) ON map.id=source.transition_id WHERE source.organization_id=org;
  INSERT INTO public.workflow_transition_conditions("organization_id","id","transition_id","source_field","operator","comparison_text","comparison_number","comparison_boolean","comparison_date","display_order")
    SELECT source."organization_id",gen_random_uuid(),map.new_id,source."source_field",source."operator",source."comparison_text",source."comparison_number",source."comparison_boolean",source."comparison_date",source."display_order"
    FROM public.workflow_transition_conditions source JOIN unnest(transition_ids,transition_copy_ids) AS map(id,new_id) ON map.id=source.transition_id WHERE source.organization_id=org;
  INSERT INTO public.workflow_transition_checklist_items("organization_id","id","transition_id","prompt","is_required","display_order")
    SELECT source."organization_id",gen_random_uuid(),map.new_id,source."prompt",source."is_required",source."display_order"
    FROM public.workflow_transition_checklist_items source JOIN unnest(transition_ids,transition_copy_ids) AS map(id,new_id) ON map.id=source.transition_id WHERE source.organization_id=org;

  INSERT INTO public.sample_category_workflows(organization_id,sample_category_id,workflow_id,applies_to,is_default)
    SELECT org,assignment.sample_category_id,target_id,assignment.applies_to,false FROM public.sample_category_workflows assignment
    WHERE assignment.organization_id=org AND assignment.workflow_id=source_id;
  INSERT INTO public.workflow_clone_origins(organization_id,workflow_id,workflow_version_id,cloned_revision,source_workflow_id,source_version_id,
    source_revision,source_metadata_revision,requested_source_version_id,request_id,created_by)
    VALUES(org,target_id,copied_version,copied_revision,source_id,source_version.id,source_version.revision,source_workflow.metadata_revision,requested_version,requested_id,actor);
  RETURN QUERY SELECT target_id,copied_version,1,copied_revision;
END $_$;


--
-- Name: workflow_metadata_check_head(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_metadata_check_head() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE head public.workflows; version public.workflow_metadata_versions;
BEGIN
  SELECT * INTO head FROM public.workflows WHERE organization_id=NEW.organization_id AND id=NEW.id;
  IF head.metadata_revision>0 THEN
    SELECT * INTO version FROM public.workflow_metadata_versions WHERE organization_id=head.organization_id AND workflow_id=head.id AND revision=head.metadata_revision;
    IF version.workflow_id IS NULL OR (head.metadata_revision,head.code,head.name,head.description,head.applies_to,head.active,head.updated_by,head.updated_at)
      IS DISTINCT FROM (version.revision,version.code,version.name,version.description,version.applies_to,version.active,version.saved_by,version.saved_at) THEN
      RAISE EXCEPTION 'Workflow metadata requires complete matching history' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: workflow_metadata_guard_head(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_metadata_guard_head() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Workflows are retired without deleting history' USING ERRCODE='55000'; END IF;
  IF (NEW.organization_id,NEW.id,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.organization_id,OLD.id,OLD.created_by,OLD.created_at)
    OR NEW.metadata_revision<>OLD.metadata_revision+1 OR NOT OLD.active THEN
    RAISE EXCEPTION 'Workflow metadata identity and revision are immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_metadata_guard_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_metadata_guard_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE head public.workflows; initial public.workflow_versions;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Workflow metadata history is immutable' USING ERRCODE='55000'; END IF;
  SELECT * INTO head FROM public.workflows WHERE organization_id=NEW.organization_id AND id=NEW.workflow_id;
  IF NEW.saved_by IS DISTINCT FROM public.workflow_metadata_require_actor()
    OR NEW.organization_id IS DISTINCT FROM nullif(current_setting('app.organization_id',true),'')::uuid
    OR NEW.saved_at<>transaction_timestamp() OR NEW.created_transaction_id<>pg_current_xact_id()
    OR (NEW.revision,NEW.code,NEW.name,NEW.description,NEW.applies_to,NEW.active,NEW.saved_by,NEW.saved_at)
      IS DISTINCT FROM (head.metadata_revision,head.code,head.name,head.description,head.applies_to,head.active,head.updated_by,head.updated_at) THEN
    RAISE EXCEPTION 'Workflow history requires its current metadata, actual actor and transaction' USING ERRCODE='23514';
  END IF;
  IF NEW.operation='create' THEN
    SELECT * INTO initial FROM public.workflow_versions WHERE organization_id=NEW.organization_id AND id=NEW.initial_version_id;
    IF head.created_by IS DISTINCT FROM NEW.saved_by OR head.created_at<>NEW.saved_at
      OR initial.workflow_id IS DISTINCT FROM NEW.workflow_id OR initial.number<>1 OR initial.status<>'draft'
      OR initial.created_by IS DISTINCT FROM NEW.saved_by OR initial.created_at<>NEW.saved_at THEN
      RAISE EXCEPTION 'New workflow history requires its actual creation and initial draft' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: workflow_metadata_require_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_metadata_require_actor() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.sessions session
    JOIN public.users person ON person.id=session.user_id AND person.active AND NOT person.must_change_password
    JOIN public.credentials credential ON credential.user_id=person.id AND credential.revision=session.credential_revision
    JOIN public.memberships membership ON membership.organization_id=session.organization_id AND membership.user_id=person.id AND membership.active
    JOIN public.organizations organization ON organization.id=session.organization_id AND organization.active
    WHERE session.id=nullif(current_setting('app.session_id',true),'')::uuid AND session.user_id=actor AND session.organization_id=org
      AND session.revoked_at IS NULL AND session.expires_at>clock_timestamp()
  ) OR NOT public.app_has_permission('workflows.manage') THEN
    RAISE EXCEPTION 'Active workflow management session required' USING ERRCODE='42501',CONSTRAINT='workflow_metadata_session_required';
  END IF;
  RETURN actor;
END $$;


--
-- Name: workflow_reference_organization(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_reference_organization() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT session.organization_id FROM public.sessions session
  JOIN public.users person ON person.id=session.user_id AND person.active AND NOT person.must_change_password
  JOIN public.credentials credential ON credential.user_id=person.id AND credential.revision=session.credential_revision
  JOIN public.memberships membership ON membership.organization_id=session.organization_id AND membership.user_id=person.id AND membership.active
  JOIN public.organizations organization ON organization.id=session.organization_id AND organization.active
  WHERE session.id=nullif(current_setting('app.session_id',true),'')::uuid
    AND session.user_id=nullif(current_setting('app.user_id',true),'')::uuid
    AND session.organization_id=nullif(current_setting('app.organization_id',true),'')::uuid
    AND session.revoked_at IS NULL AND session.expires_at>clock_timestamp()
    AND (public.app_has_permission('workflows.read') OR public.app_has_permission('workflows.manage'))
$$;


--
-- Name: workflow_reject_approval(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_reject_approval(p_assignment uuid, p_comment text, p_checked uuid[]) RETURNS TABLE(workflow_run_id uuid, revision integer, history_id uuid, approval_case_id uuid, state_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=public.organization_module_scope(); actor uuid:=nullif(current_setting('app.user_id',true),'')::uuid;
  selected_run uuid; assignment public.approval_assignments; stage public.approval_stages; approval public.approval_cases;
  run public.workflow_runs; requested public.workflow_run_history; decision public.approval_decisions;
  recorded_history uuid; recorded_decision uuid;
BEGIN
  IF org IS NULL OR NOT public.app_has_permission('approvals.respond') THEN
    RAISE EXCEPTION 'Approval response permission and a current session are required' USING ERRCODE='42501',CONSTRAINT='workflow_response_session';
  END IF;
  IF p_assignment IS NULL OR nullif(trim(p_comment),'') IS NULL OR length(p_comment)>5000
    OR cardinality(p_checked) IS NULL OR cardinality(p_checked)>500
    OR (cardinality(p_checked)>0 AND array_ndims(p_checked) IS DISTINCT FROM 1)
    OR array_position(p_checked,NULL) IS NOT NULL
    OR (SELECT count(DISTINCT item) FROM unnest(p_checked) item)<>cardinality(p_checked) THEN
    RAISE EXCEPTION 'Rejection requires a comment and distinct bounded checklist items' USING ERRCODE='23514',CONSTRAINT='workflow_response_input';
  END IF;
  p_comment:=trim(p_comment);
  SELECT c.workflow_run_id INTO selected_run FROM public.approval_assignments a
    JOIN public.approval_stages s ON s.organization_id=a.organization_id AND s.id=a.approval_stage_id
    JOIN public.approval_cases c ON c.organization_id=s.organization_id AND c.id=s.approval_case_id
    WHERE a.organization_id=org AND a.id=p_assignment;
  IF selected_run IS NULL THEN
    RAISE EXCEPTION 'Approval assignment was not found' USING ERRCODE='23514',CONSTRAINT='workflow_response_not_found';
  END IF;
  -- An already committed response is immutable. Its exact retry must still work
  -- after later workflow activity, without trying to execute the old edge again.
  IF NOT EXISTS (SELECT 1 FROM public.approval_decisions WHERE organization_id=org AND approval_assignment_id=p_assignment) THEN
    PERFORM public.workflow_lock_run(selected_run);
  END IF;
  SELECT a.* INTO assignment FROM public.approval_assignments a WHERE a.organization_id=org AND a.id=p_assignment FOR UPDATE;
  SELECT s.* INTO stage FROM public.approval_stages s WHERE s.organization_id=org AND s.id=assignment.approval_stage_id FOR UPDATE;
  SELECT c.* INTO approval FROM public.approval_cases c WHERE c.organization_id=org AND c.id=stage.approval_case_id FOR UPDATE;
  IF public.organization_module_scope() IS DISTINCT FROM org OR NOT public.app_has_permission('approvals.respond') THEN
    RAISE EXCEPTION 'Approval response access changed' USING ERRCODE='42501',CONSTRAINT='workflow_response_session';
  END IF;
  IF assignment.assigned_user_id IS DISTINCT FROM actor THEN
    RAISE EXCEPTION 'Only the assigned approver may respond' USING ERRCODE='42501',CONSTRAINT='workflow_response_assignee';
  END IF;
  SELECT d.* INTO decision FROM public.approval_decisions d WHERE d.organization_id=org AND d.approval_assignment_id=p_assignment;
  SELECT h.* INTO requested FROM public.workflow_run_history h WHERE h.organization_id=org AND h.id=approval.request_history_id;
  IF decision.id IS NOT NULL THEN
    IF decision.decision<>'reject' OR decision.decided_by<>actor OR decision.comment IS DISTINCT FROM p_comment
      OR approval.status<>'rejected' OR approval.rejection_history_id IS NULL
      OR (SELECT coalesce(array_agg(answer.checklist_item_id ORDER BY answer.checklist_item_id),'{}'::uuid[])
        FROM public.approval_decision_checklist_answers answer WHERE answer.organization_id=org AND answer.decision_id=decision.id AND answer.is_checked)
        IS DISTINCT FROM (SELECT coalesce(array_agg(item ORDER BY item),'{}'::uuid[]) FROM unnest(p_checked) item) THEN
      RAISE EXCEPTION 'This assignment already has a different response' USING ERRCODE='23514',CONSTRAINT='workflow_response_conflict';
    END IF;
    RETURN QUERY SELECT approval.workflow_run_id,approval.run_revision+1,approval.rejection_history_id,approval.id,requested.from_state_id;
    RETURN;
  END IF;
  SELECT r.* INTO run FROM public.workflow_runs r WHERE r.organization_id=org AND r.id=selected_run;
  IF assignment.status<>'pending' OR stage.status<>'pending' OR approval.status<>'pending'
    OR run.status<>'active' OR run.revision<>approval.run_revision OR run.current_state_id IS DISTINCT FROM requested.from_state_id THEN
    RAISE EXCEPTION 'This approval is no longer waiting for a response' USING ERRCODE='23514',CONSTRAINT='workflow_response_not_pending';
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(p_checked) selected(id) WHERE NOT EXISTS (
    SELECT 1 FROM public.workflow_transition_checklist_items item WHERE item.organization_id=org AND item.transition_id=approval.transition_id AND item.id=selected.id)) THEN
    RAISE EXCEPTION 'A selected checklist item does not belong to this transition' USING ERRCODE='23514',CONSTRAINT='workflow_response_checklist';
  END IF;
  -- Rejection does not require positive transition conditions, allocation or
  -- checked positive assertions. It still refers to the exact submitted result.
  IF run.test_request_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.test_requests request JOIN public.datasheets sheet
      ON sheet.organization_id=request.organization_id AND sheet.id=request.final_datasheet_id AND sheet.test_request_id=request.id
    JOIN public.datasheet_submissions submission ON submission.organization_id=sheet.organization_id AND submission.id=sheet.latest_submission_id
    JOIN public.template_instances capture ON capture.organization_id=submission.organization_id AND capture.id=submission.instance_id
    WHERE request.organization_id=org AND request.id=run.test_request_id AND submission.id=requested.datasheet_submission_id
      AND capture.status='frozen' AND capture.revision=submission.capture_revision
      AND request.status IN ('under_review','approved') AND sheet.status IN ('under_review','approved')) THEN
    RAISE EXCEPTION 'The submitted result differs from this approval request' USING ERRCODE='23514',CONSTRAINT='workflow_response_result';
  END IF;
  INSERT INTO public.approval_decisions(organization_id,approval_assignment_id,decision,decided_by,comment)
    VALUES(org,p_assignment,'reject',actor,p_comment) RETURNING id INTO recorded_decision;
  INSERT INTO public.approval_decision_checklist_answers(organization_id,decision_id,transition_id,checklist_item_id,is_checked)
    SELECT org,recorded_decision,approval.transition_id,item.id,item.id=ANY(p_checked)
    FROM public.workflow_transition_checklist_items item WHERE item.organization_id=org AND item.transition_id=approval.transition_id;
  UPDATE public.approval_assignments SET status='rejected',responded_at=transaction_timestamp() WHERE organization_id=org AND id=p_assignment;
  UPDATE public.approval_assignments a SET status='cancelled' FROM public.approval_stages s
    WHERE a.organization_id=org AND s.organization_id=org AND a.approval_stage_id=s.id AND s.approval_case_id=approval.id AND a.status='pending';
  UPDATE public.approval_stages SET status='rejected',resolved_at=transaction_timestamp() WHERE organization_id=org AND id=stage.id;
  UPDATE public.approval_stages s SET status='cancelled',resolved_at=transaction_timestamp()
    WHERE s.organization_id=org AND s.approval_case_id=approval.id AND s.status='waiting';
  UPDATE public.workflow_runs r SET revision=r.revision+1 WHERE r.organization_id=org AND r.id=run.id;
  INSERT INTO public.workflow_run_history(organization_id,workflow_run_id,workflow_version_id,from_state_id,to_state_id,transition_id,datasheet_submission_id,action,actor_user_id,comment)
    VALUES(org,run.id,run.workflow_version_id,run.current_state_id,run.current_state_id,approval.transition_id,requested.datasheet_submission_id,'rejected',actor,p_comment)
    RETURNING id INTO recorded_history;
  UPDATE public.approval_cases SET status='rejected',resolved_at=transaction_timestamp(),rejection_history_id=recorded_history
    WHERE organization_id=org AND id=approval.id;
  IF run.sample_id IS NOT NULL THEN
    UPDATE public.samples SET status='rejected',revision=samples.revision+1 WHERE organization_id=org AND id=run.sample_id;
  ELSE
    UPDATE public.test_requests SET status='rejected',revision=test_requests.revision+1 WHERE organization_id=org AND id=run.test_request_id;
    UPDATE public.datasheets SET status='rejected',revision=datasheets.revision+1
      WHERE organization_id=org AND test_request_id=run.test_request_id AND status<>'void';
    PERFORM public.workflow_apply_job_effects(recorded_history);
  END IF;
  RETURN QUERY SELECT run.id,run.revision+1,recorded_history,approval.id,run.current_state_id;
END $$;


--
-- Name: workflow_reserve_request(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_reserve_request(selected_run uuid, selected_transition uuid, expected_revision integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; next_revision integer;
BEGIN
  IF NOT public.workflow_lock_run(selected_run) OR NOT public.workflow_can_request(selected_transition) THEN
    RAISE EXCEPTION 'Workflow transition permission required' USING ERRCODE='42501';
  END IF;
  IF EXISTS (SELECT 1 FROM public.approval_cases WHERE organization_id=org AND workflow_run_id=selected_run AND status='pending') THEN
    RAISE EXCEPTION 'A workflow approval is already pending' USING ERRCODE='23514';
  END IF;
  UPDATE public.workflow_runs run SET revision=revision+1 WHERE run.organization_id=org AND run.id=selected_run
    AND run.status='active' AND run.revision=expected_revision AND EXISTS (SELECT 1 FROM public.workflow_transitions transition
      WHERE transition.organization_id=org AND transition.id=selected_transition AND transition.workflow_version_id=run.workflow_version_id
        AND transition.source_state_id=run.current_state_id AND transition.approval_mode<>'none') RETURNING revision INTO next_revision;
  RETURN next_revision;
END $$;


--
-- Name: workflow_select_checklist(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_select_checklist(selected_checklist uuid) RETURNS TABLE(master_revision integer, prompt text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; head public.checklists;
BEGIN
  PERFORM public.workflow_metadata_require_actor();
  SELECT * INTO head FROM public.checklists WHERE organization_id=org AND id=selected_checklist FOR SHARE;
  PERFORM public.workflow_metadata_require_actor();
  IF head.id IS NULL OR NOT head.is_active OR head.retired_at IS NOT NULL THEN
    RAISE EXCEPTION 'Select an active checklist in this organization' USING ERRCODE='23514',CONSTRAINT='workflow_checklist_unavailable';
  END IF;
  IF head.revision>0 THEN PERFORM public.checklists_assert_version(org,selected_checklist,head.revision,true); END IF;
  IF (SELECT count(*) FROM public.checklist_items WHERE organization_id=org AND checklist_id=selected_checklist) NOT BETWEEN 1 AND 200
    OR EXISTS (SELECT 1 FROM public.checklist_items item WHERE item.organization_id=org AND item.checklist_id=selected_checklist
      AND length(trim(item.prompt)) NOT BETWEEN 1 AND 500) THEN
    RAISE EXCEPTION 'Checklist items are outside the authoring bounds' USING ERRCODE='23514',CONSTRAINT='workflow_checklist_unavailable';
  END IF;
  RETURN QUERY SELECT head.revision,item.prompt FROM public.checklist_items item
    WHERE item.organization_id=org AND item.checklist_id=selected_checklist ORDER BY item.display_order,item.id;
END $$;


--
-- Name: workflow_select_template(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_select_template(selected_template uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; selected_id uuid;
BEGIN
  PERFORM public.workflow_metadata_require_actor();
  SELECT id INTO selected_id FROM public.templates
    WHERE organization_id=org AND id=selected_template AND active FOR SHARE;
  PERFORM public.workflow_metadata_require_actor();
  IF selected_id IS NULL THEN
    RAISE EXCEPTION 'Select an active template in this organization' USING ERRCODE='23514',CONSTRAINT='workflow_template_unavailable';
  END IF;
  RETURN selected_id;
END $$;


--
-- Name: workflow_test_request_submission(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_test_request_submission(request_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT submission.id FROM public.test_requests request JOIN public.datasheets sheet
    ON sheet.organization_id=request.organization_id AND sheet.test_request_id=request.id AND sheet.id=request.final_datasheet_id
    JOIN public.datasheet_submissions submission ON submission.organization_id=sheet.organization_id AND submission.datasheet_id=sheet.id AND submission.id=sheet.latest_submission_id
    JOIN public.template_instances capture ON capture.organization_id=sheet.organization_id AND capture.id=submission.instance_id
    WHERE request.organization_id=nullif(current_setting('app.organization_id',true),'')::uuid AND request.id=request_id AND public.laboratory_can_read()
      AND request.status IN ('under_review','approved') AND sheet.status IN ('under_review','approved') AND capture.status='frozen' AND capture.revision=submission.capture_revision
      AND EXISTS (SELECT 1 FROM public.test_request_assignments WHERE organization_id=request.organization_id AND test_request_id=request.id AND assignment_type='analyst' AND unassigned_at IS NULL)
$$;


--
-- Name: workflow_validate_approved_case(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_validate_approved_case() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF session_user='sampleify_app' AND NEW.status='approved' AND NOT EXISTS (
    SELECT 1 FROM public.workflow_runs run JOIN public.workflow_run_history history ON history.organization_id=run.organization_id AND history.workflow_run_id=run.id
      JOIN public.workflow_transitions transition ON transition.organization_id=history.organization_id AND transition.id=history.transition_id
    WHERE run.organization_id=NEW.organization_id AND run.id=NEW.workflow_run_id AND run.revision>NEW.run_revision
      AND history.transition_id=NEW.transition_id AND history.occurred_at=NEW.resolved_at AND history.to_state_id=transition.target_state_id
      AND history.action IN ('approved','completed','cancelled')) THEN
    RAISE EXCEPTION 'Approval and its resulting workflow transition must commit together' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: workflow_validate_checklist_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_validate_checklist_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE org uuid; target uuid; connection public.workflow_transitions;
  item_id uuid; current_item public.workflow_transition_checklist_items; expected_prompt text; expected_count integer;
BEGIN
  org:=CASE WHEN TG_OP='DELETE' THEN OLD.organization_id ELSE NEW.organization_id END;
  IF TG_TABLE_NAME='workflow_transitions' THEN target:=NEW.id;
  ELSE target:=CASE WHEN TG_OP='DELETE' THEN OLD.transition_id ELSE NEW.transition_id END; END IF;
  SELECT * INTO connection FROM public.workflow_transitions WHERE organization_id=org AND id=target;
  -- NULL records an unbound graph or an imported master without a known version.
  -- Its copied workflow prompts remain frozen by the existing version guards.
  IF NOT FOUND OR connection.checklist_master_revision IS NULL THEN RETURN NULL; END IF;
  IF TG_TABLE_NAME='workflow_transition_checklist_items' THEN
    -- Validate each changed item and the final count. The parent trigger below
    -- validates the whole snapshot whenever its master or version can change.
    -- Item ownership is immutable, so a deleted/replaced row cannot escape both
    -- this count check and the replacement row's ordered prompt check.
    SELECT item_count INTO expected_count FROM public.checklist_versions
      WHERE organization_id=org AND checklist_id=connection.checklist_master_id AND revision=connection.checklist_master_revision;
    IF (SELECT count(*) FROM public.workflow_transition_checklist_items WHERE organization_id=org AND transition_id=target) IS DISTINCT FROM expected_count THEN
      RAISE EXCEPTION 'Workflow checklist must contain its complete recorded master version'
        USING ERRCODE='23514',CONSTRAINT='workflow_checklist_snapshot';
    END IF;
    item_id:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;
    SELECT * INTO current_item FROM public.workflow_transition_checklist_items WHERE organization_id=org AND transition_id=target AND id=item_id;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT prompt INTO expected_prompt FROM public.checklist_version_items
      WHERE organization_id=org AND checklist_id=connection.checklist_master_id AND revision=connection.checklist_master_revision
      ORDER BY display_order,id OFFSET current_item.display_order LIMIT 1;
    IF NOT FOUND OR current_item.prompt IS DISTINCT FROM expected_prompt OR NOT current_item.is_required THEN
      RAISE EXCEPTION 'Workflow checklist item must match its ordered recorded master prompt'
        USING ERRCODE='23514',CONSTRAINT='workflow_checklist_snapshot';
    END IF;
    RETURN NULL;
  END IF;
  IF EXISTS (
    WITH expected AS (
      SELECT prompt,true AS is_required,(row_number() OVER (ORDER BY display_order,id)-1)::integer AS display_order
      FROM public.checklist_version_items WHERE organization_id=org AND checklist_id=connection.checklist_master_id AND revision=connection.checklist_master_revision
    ), actual AS (
      SELECT prompt,is_required,display_order FROM public.workflow_transition_checklist_items WHERE organization_id=org AND transition_id=target
    )
    (SELECT * FROM expected EXCEPT ALL SELECT * FROM actual)
    UNION ALL (SELECT * FROM actual EXCEPT ALL SELECT * FROM expected)
  ) THEN
    RAISE EXCEPTION 'Workflow checklist must match its complete recorded master version'
      USING ERRCODE='23514',CONSTRAINT='workflow_checklist_snapshot';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: workflow_validate_decision_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_validate_decision_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actual_transition uuid; assignment_status text;
BEGIN
  -- Imported history with no recorded checklist answers remains absent. The
  -- application role must submit actual checked items for each new decision.
  IF session_user<>'sampleify_app' THEN RETURN NULL; END IF;
  SELECT approval.transition_id,assignment.status INTO actual_transition,assignment_status
    FROM public.approval_assignments assignment JOIN public.approval_stages stage ON stage.organization_id=assignment.organization_id AND stage.id=assignment.approval_stage_id
    JOIN public.approval_cases approval ON approval.organization_id=stage.organization_id AND approval.id=stage.approval_case_id
    WHERE assignment.organization_id=NEW.organization_id AND assignment.id=NEW.approval_assignment_id;
  IF nullif(trim(NEW.comment),'') IS NULL OR assignment_status IS DISTINCT FROM (CASE WHEN NEW.decision='approve' THEN 'approved' ELSE 'rejected' END) THEN
    RAISE EXCEPTION 'A response requires its comment and matching assignment state' USING ERRCODE='23514';
  END IF;
  IF NEW.decision='approve' AND EXISTS (SELECT 1 FROM public.workflow_transition_checklist_items item
    WHERE item.organization_id=NEW.organization_id AND item.transition_id=actual_transition AND item.is_required
    AND NOT EXISTS (SELECT 1 FROM public.approval_decision_checklist_answers answer WHERE answer.organization_id=item.organization_id
      AND answer.decision_id=NEW.id AND answer.checklist_item_id=item.id AND answer.is_checked)) THEN
    RAISE EXCEPTION 'Approval requires its recorded required checklist answers' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: workflow_validate_new_case(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_validate_new_case() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE requester uuid; mode text;
BEGIN
  SELECT actor_user_id INTO requester FROM public.workflow_run_history WHERE organization_id=NEW.organization_id AND id=NEW.request_history_id;
  SELECT approval_mode INTO mode FROM public.workflow_transitions WHERE organization_id=NEW.organization_id AND id=NEW.transition_id;
  IF mode IS NULL OR mode='none' THEN RAISE EXCEPTION 'This transition does not define approval' USING ERRCODE='23514'; END IF;
  IF EXISTS (SELECT 1 FROM public.workflow_transition_creator_roles WHERE organization_id=NEW.organization_id AND transition_id=NEW.transition_id)
    AND NOT EXISTS (SELECT 1 FROM public.workflow_transition_creator_roles creator JOIN public.membership_roles membership
      ON membership.organization_id=creator.organization_id AND membership.role_id=creator.role_id
      WHERE creator.organization_id=NEW.organization_id AND creator.transition_id=NEW.transition_id AND membership.user_id=requester) THEN
    RAISE EXCEPTION 'The requester must hold a configured creator role' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.workflow_transition_approver_roles WHERE organization_id=NEW.organization_id AND transition_id=NEW.transition_id)
    OR EXISTS (SELECT 1 FROM public.workflow_transition_approver_roles configured WHERE configured.organization_id=NEW.organization_id AND configured.transition_id=NEW.transition_id
      AND NOT EXISTS (SELECT 1 FROM public.approval_stages stage WHERE stage.organization_id=NEW.organization_id AND stage.approval_case_id=NEW.id AND stage.stage_number=configured.stage_number))
    OR EXISTS (SELECT 1 FROM public.approval_stages stage WHERE stage.organization_id=NEW.organization_id AND stage.approval_case_id=NEW.id
      AND NOT EXISTS (SELECT 1 FROM public.approval_assignments assignment WHERE assignment.organization_id=stage.organization_id AND assignment.approval_stage_id=stage.id)) THEN
    RAISE EXCEPTION 'Every configured approval stage requires assigned users' USING ERRCODE='23514';
  END IF;
  IF current_user='sampleify_app' AND EXISTS (SELECT 1 FROM public.workflow_approver_candidates(NEW.transition_id) candidate
    WHERE NOT EXISTS (SELECT 1 FROM public.approval_stages stage JOIN public.approval_assignments assignment
      ON assignment.organization_id=stage.organization_id AND assignment.approval_stage_id=stage.id
      WHERE stage.organization_id=NEW.organization_id AND stage.approval_case_id=NEW.id AND stage.stage_number=candidate.stage_number AND assignment.assigned_user_id=candidate.user_id)) THEN
    RAISE EXCEPTION 'All configured active approvers must be included in the request' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: workflow_validate_ports(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_validate_ports() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.workflow_transitions connection
    JOIN public.workflow_states source ON source.organization_id=connection.organization_id AND source.id=connection.source_state_id
    JOIN public.workflow_states target ON target.organization_id=connection.organization_id AND target.id=connection.target_state_id
    WHERE connection.organization_id=NEW.organization_id AND connection.workflow_version_id=NEW.workflow_version_id
      AND ((TG_TABLE_NAME='workflow_states' AND (connection.source_state_id=NEW.id OR connection.target_state_id=NEW.id))
        OR (TG_TABLE_NAME='workflow_transitions' AND connection.id=NEW.id))
      AND (coalesce(connection.source_port,1)>coalesce(source.output_count,1) OR coalesce(connection.target_port,1)>coalesce(target.input_count,1))
  ) THEN
    RAISE EXCEPTION 'Workflow connections require available source and target ports'
      USING ERRCODE='23514',CONSTRAINT='workflow_connection_port';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: workflow_validate_rejection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_validate_rejection() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE approval public.approval_cases; requested public.workflow_run_history; history public.workflow_run_history;
  run public.workflow_runs; decision public.approval_decisions;
BEGIN
  IF session_user<>'sampleify_app' THEN RETURN NULL; END IF;
  IF TG_TABLE_NAME='approval_cases' THEN
    IF NEW.status<>'rejected' THEN RETURN NULL; END IF;
    SELECT * INTO approval FROM public.approval_cases WHERE organization_id=NEW.organization_id AND id=NEW.id;
  ELSIF TG_TABLE_NAME='workflow_run_history' THEN
    IF NEW.action<>'rejected' THEN RETURN NULL; END IF;
    SELECT * INTO approval FROM public.approval_cases WHERE organization_id=NEW.organization_id AND rejection_history_id=NEW.id;
  ELSE
    IF NEW.decision<>'reject' THEN RETURN NULL; END IF;
    SELECT c.* INTO approval FROM public.approval_assignments a JOIN public.approval_stages s
      ON s.organization_id=a.organization_id AND s.id=a.approval_stage_id
      JOIN public.approval_cases c ON c.organization_id=s.organization_id AND c.id=s.approval_case_id
      WHERE a.organization_id=NEW.organization_id AND a.id=NEW.approval_assignment_id;
  END IF;
  SELECT * INTO requested FROM public.workflow_run_history WHERE organization_id=approval.organization_id AND id=approval.request_history_id;
  SELECT * INTO history FROM public.workflow_run_history WHERE organization_id=approval.organization_id AND id=approval.rejection_history_id;
  SELECT * INTO run FROM public.workflow_runs WHERE organization_id=approval.organization_id AND id=approval.workflow_run_id;
  SELECT d.* INTO decision FROM public.approval_decisions d JOIN public.approval_assignments a
    ON a.organization_id=d.organization_id AND a.id=d.approval_assignment_id
    JOIN public.approval_stages s ON s.organization_id=a.organization_id AND s.id=a.approval_stage_id
    WHERE d.organization_id=approval.organization_id AND s.approval_case_id=approval.id AND d.decision='reject';
  IF approval.id IS NULL OR approval.status<>'rejected' OR history.id IS NULL OR decision.id IS NULL
    OR public.organization_module_scope() IS DISTINCT FROM approval.organization_id OR NOT public.app_has_permission('approvals.respond')
    OR (history.workflow_run_id,history.workflow_version_id,history.transition_id,history.from_state_id,history.to_state_id,history.datasheet_submission_id)
      IS DISTINCT FROM (run.id,approval.workflow_version_id,approval.transition_id,requested.from_state_id,requested.from_state_id,requested.datasheet_submission_id)
    OR history.action<>'rejected' OR history.actor_user_id IS DISTINCT FROM nullif(current_setting('app.user_id',true),'')::uuid
    OR history.actor_user_id IS DISTINCT FROM decision.decided_by OR history.comment IS DISTINCT FROM decision.comment
    OR nullif(trim(decision.comment),'') IS NULL OR approval.resolved_at<>history.occurred_at OR decision.decided_at<>history.occurred_at
    OR history.occurred_at<>transaction_timestamp() OR run.revision<>approval.run_revision+1
    OR run.current_state_id IS DISTINCT FROM requested.from_state_id OR run.status<>'active'
    OR NOT EXISTS (SELECT 1 FROM public.workflow_run_history WHERE organization_id=history.organization_id AND id=history.id AND xmin::text=pg_current_xact_id()::text)
    OR NOT EXISTS (SELECT 1 FROM public.approval_decisions WHERE organization_id=decision.organization_id AND id=decision.id AND xmin::text=pg_current_xact_id()::text)
    OR (SELECT count(*) FROM public.approval_stages WHERE organization_id=approval.organization_id AND approval_case_id=approval.id AND status='rejected')<>1
    OR EXISTS (SELECT 1 FROM public.approval_stages WHERE organization_id=approval.organization_id AND approval_case_id=approval.id AND status IN ('pending','waiting'))
    OR (SELECT count(*) FROM public.approval_decisions d JOIN public.approval_assignments a ON a.organization_id=d.organization_id AND a.id=d.approval_assignment_id
      JOIN public.approval_stages s ON s.organization_id=a.organization_id AND s.id=a.approval_stage_id
      WHERE d.organization_id=approval.organization_id AND s.approval_case_id=approval.id AND d.decision='reject')<>1
    OR EXISTS (SELECT 1 FROM public.approval_assignments a JOIN public.approval_stages s ON s.organization_id=a.organization_id AND s.id=a.approval_stage_id
      WHERE a.organization_id=approval.organization_id AND s.approval_case_id=approval.id AND a.status='pending')
    OR NOT EXISTS (SELECT 1 FROM public.approval_assignments a JOIN public.approval_stages s ON s.organization_id=a.organization_id AND s.id=a.approval_stage_id
      WHERE a.organization_id=approval.organization_id AND a.id=decision.approval_assignment_id AND a.status='rejected'
        AND a.assigned_user_id=decision.decided_by AND a.responded_at=decision.decided_at AND s.status='rejected' AND s.resolved_at=decision.decided_at)
    OR EXISTS (SELECT 1 FROM public.workflow_transition_checklist_items item WHERE item.organization_id=approval.organization_id AND item.transition_id=approval.transition_id
      AND NOT EXISTS (SELECT 1 FROM public.approval_decision_checklist_answers answer WHERE answer.organization_id=item.organization_id AND answer.decision_id=decision.id AND answer.checklist_item_id=item.id)) THEN
    RAISE EXCEPTION 'First rejection, cancellation and actual history must commit together' USING ERRCODE='23514',CONSTRAINT='workflow_rejection_evidence';
  END IF;
  IF (run.sample_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.samples WHERE organization_id=run.organization_id AND id=run.sample_id AND status='rejected'))
    OR (run.test_request_id IS NOT NULL AND (NOT EXISTS (
      SELECT 1 FROM public.test_requests request JOIN public.datasheets sheet ON sheet.organization_id=request.organization_id AND sheet.id=request.final_datasheet_id
      JOIN public.datasheet_submissions submission ON submission.organization_id=sheet.organization_id AND submission.id=sheet.latest_submission_id
      JOIN public.template_instances capture ON capture.organization_id=submission.organization_id AND capture.id=submission.instance_id
      WHERE request.organization_id=run.organization_id AND request.id=run.test_request_id AND request.status='rejected' AND sheet.status='rejected'
        AND submission.id=requested.datasheet_submission_id AND capture.status='frozen' AND capture.revision=submission.capture_revision)
      OR EXISTS (SELECT 1 FROM public.datasheets WHERE organization_id=run.organization_id AND test_request_id=run.test_request_id AND status NOT IN ('rejected','void')))) THEN
    RAISE EXCEPTION 'Rejection must preserve its frozen result and update its actual owner' USING ERRCODE='23514',CONSTRAINT='workflow_rejection_owner';
  END IF;
  IF run.test_request_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.job_submission_members chosen JOIN public.test_requests child
      ON child.organization_id=chosen.organization_id AND child.id=chosen.test_request_id
    WHERE chosen.organization_id=run.organization_id AND chosen.parent_submission_id=requested.datasheet_submission_id
      AND child.parent_test_request_id=run.test_request_id AND child.status<>'approved'
      AND NOT EXISTS (SELECT 1 FROM public.job_workflow_effects effect WHERE effect.organization_id=chosen.organization_id
        AND effect.job_submission_member_id=chosen.id AND effect.parent_history_id=history.id)) THEN
    RAISE EXCEPTION 'Job rejection must record every covered child effect' USING ERRCODE='23514',CONSTRAINT='workflow_rejection_children';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: workflow_validate_request_checks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflow_validate_request_checks() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF session_user<>'sampleify_app' OR NEW.transition_id IS NULL THEN RETURN NULL; END IF;
  IF (NEW.action='requested' OR (NEW.action IN ('transitioned','completed','cancelled') AND EXISTS (SELECT 1 FROM public.workflow_transitions
    WHERE organization_id=NEW.organization_id AND id=NEW.transition_id AND approval_mode='none')))
    AND EXISTS (SELECT 1 FROM public.workflow_transition_checklist_items item WHERE item.organization_id=NEW.organization_id AND item.transition_id=NEW.transition_id AND item.is_required
      AND NOT EXISTS (SELECT 1 FROM public.workflow_checklist_answers answer WHERE answer.organization_id=item.organization_id AND answer.history_id=NEW.id AND answer.checklist_item_id=item.id AND answer.is_checked)) THEN
    RAISE EXCEPTION 'Transition requires its recorded required checklist answers' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: workflows_metadata_write(text, uuid, integer, uuid, text, text, boolean, text, boolean, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workflows_metadata_write(operation text, target uuid, expected_revision integer, requested_id uuid, requested_name text, requested_description text, description_provided boolean, requested_code text, generate_code boolean, requested_type text, requested_active boolean) RETURNS TABLE(metadata_revision integer, initial_version_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE actor uuid; org uuid:=nullif(current_setting('app.organization_id',true),'')::uuid; head public.workflows;
  prior public.workflow_metadata_versions; next_revision integer; next_code text; next_name text; next_description text; next_type text; next_active boolean;
  created_version uuid; suffix integer:=2; used boolean;
BEGIN
  actor:=public.workflow_metadata_require_actor();
  PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
  actor:=public.workflow_metadata_require_actor();
  IF operation IS NULL OR operation NOT IN ('create','update','retire') OR target IS NULL OR requested_id IS NULL
    OR expected_revision IS NULL OR expected_revision NOT BETWEEN 0 AND 2147483646 OR (operation='create' AND expected_revision<>0)
    OR description_provided IS NULL OR generate_code IS NULL OR (generate_code AND operation<>'create')
    OR (NOT description_provided AND requested_description IS NOT NULL) OR (description_provided AND requested_description IS NULL)
    OR length(requested_description)>10000
    OR (requested_code IS NOT NULL AND (length(trim(requested_code)) NOT BETWEEN 1 AND 64 OR requested_code<>trim(requested_code)))
    OR (requested_type IS NOT NULL AND requested_type NOT IN ('sample','test_request','instrument_service','document'))
    OR (operation='create' AND (requested_code IS NULL OR requested_type IS NULL))
    OR (operation='retire' AND (num_nonnulls(requested_name,requested_description,requested_code,requested_type,requested_active)<>0 OR description_provided OR generate_code))
    OR (operation<>'retire' AND (requested_name IS NULL OR length(trim(requested_name)) NOT BETWEEN 1 AND 200 OR requested_name<>trim(requested_name))) THEN
    RAISE EXCEPTION 'Invalid workflow metadata command' USING ERRCODE='23514',CONSTRAINT='workflow_metadata_input';
  END IF;
  SELECT * INTO prior FROM public.workflow_metadata_versions history WHERE history.organization_id=org AND history.request_id=requested_id;
  IF FOUND THEN
    IF prior.workflow_id<>target OR prior.operation<>operation OR coalesce(prior.previous_revision,0)<>expected_revision OR prior.saved_by<>actor
      OR prior.description_provided<>description_provided OR prior.generated_code<>generate_code
      OR prior.requested_code IS DISTINCT FROM requested_code OR prior.requested_applies_to IS DISTINCT FROM requested_type
      OR prior.requested_active IS DISTINCT FROM requested_active OR (operation<>'retire' AND prior.name IS DISTINCT FROM requested_name)
      OR (description_provided AND prior.description IS DISTINCT FROM requested_description) THEN
      RAISE EXCEPTION 'Workflow request was already used for a different change' USING ERRCODE='23514',CONSTRAINT='workflow_metadata_request_reused';
    END IF;
    RETURN QUERY SELECT prior.revision,prior.initial_version_id; RETURN;
  END IF;
  SELECT * INTO head FROM public.workflows WHERE organization_id=org AND id=target FOR UPDATE;
  IF operation='create' AND FOUND THEN RAISE EXCEPTION 'Workflow already exists' USING ERRCODE='23514',CONSTRAINT='workflow_metadata_identity_exists'; END IF;
  IF operation<>'create' AND (head.id IS NULL OR NOT head.active) THEN
    RAISE EXCEPTION 'Workflow was not found' USING ERRCODE='P0002',CONSTRAINT='workflow_metadata_not_found';
  END IF;
  IF operation<>'create' AND head.metadata_revision<>expected_revision THEN
    RAISE EXCEPTION 'Workflow details changed; reload before saving' USING ERRCODE='23514',CONSTRAINT='workflow_metadata_stale';
  END IF;
  next_name:=CASE WHEN operation='retire' THEN head.name ELSE requested_name END;
  next_description:=CASE WHEN description_provided THEN requested_description ELSE coalesce(head.description,'') END;
  next_code:=coalesce(requested_code,head.code); next_type:=coalesce(requested_type,head.applies_to);
  next_active:=CASE WHEN operation='retire' THEN false ELSE coalesce(requested_active,head.active,true) END;
  IF next_active AND (operation='create' OR next_name IS DISTINCT FROM head.name) AND EXISTS (
    SELECT 1 FROM public.workflows WHERE organization_id=org AND id<>target AND active AND name=next_name
  ) THEN RAISE EXCEPTION 'A workflow with this name already exists' USING ERRCODE='23514',CONSTRAINT='workflow_name_exists'; END IF;
  IF generate_code THEN
    WHILE EXISTS (SELECT 1 FROM public.workflows WHERE organization_id=org AND lower(code)=lower(next_code)) LOOP
      next_code:=left(requested_code,60-length(suffix::text))||'-'||suffix::text; suffix:=suffix+1;
    END LOOP;
  END IF;
  IF operation<>'create' AND (NOT next_active OR next_type IS DISTINCT FROM head.applies_to) THEN
    SELECT EXISTS (SELECT 1 FROM public.workflow_runs run JOIN public.workflow_versions version
      ON version.organization_id=run.organization_id AND version.id=run.workflow_version_id WHERE version.organization_id=org AND version.workflow_id=target)
      OR EXISTS (SELECT 1 FROM public.sample_category_workflows WHERE organization_id=org AND workflow_id=target)
      OR EXISTS (SELECT 1 FROM public.organization_laboratory_settings WHERE organization_id=org
        AND target IN (test_request_workflow_id,job_workflow_id,sample_workflow_base_id,sample_workflow_iqc_id,sample_workflow_ilc_id,sample_workflow_pt_id,sample_workflow_amendment_id,sample_workflow_complaint_id))
      OR EXISTS (SELECT 1 FROM public.document_categories WHERE organization_id=org AND workflow_id=target) INTO used;
    IF used THEN
      IF NOT next_active THEN RAISE EXCEPTION 'Workflow is currently used' USING ERRCODE='23514',CONSTRAINT='workflow_metadata_in_use';
      ELSE RAISE EXCEPTION 'Used workflow entity type is immutable' USING ERRCODE='23514',CONSTRAINT='workflow_type_in_use'; END IF;
    END IF;
  END IF;
  next_revision:=expected_revision+1;
  IF operation='create' THEN
    INSERT INTO public.workflows(organization_id,id,code,name,description,applies_to,active,metadata_revision,created_by,updated_by,updated_at)
      VALUES(org,target,next_code,next_name,next_description,next_type,next_active,next_revision,actor,actor,transaction_timestamp());
    created_version:=gen_random_uuid();
    INSERT INTO public.workflow_versions(organization_id,id,workflow_id,number,created_by,change_summary)
      VALUES(org,created_version,target,1,actor,'Initial draft');
  ELSE
    UPDATE public.workflows SET code=next_code,name=next_name,description=next_description,applies_to=next_type,active=next_active,
      metadata_revision=next_revision,updated_by=actor,updated_at=transaction_timestamp() WHERE organization_id=org AND id=target;
  END IF;
  INSERT INTO public.workflow_metadata_versions(organization_id,workflow_id,revision,request_id,previous_revision,operation,initial_version_id,
    code,name,description,applies_to,active,requested_code,generated_code,description_provided,requested_applies_to,requested_active,saved_by)
    VALUES(org,target,next_revision,requested_id,CASE WHEN operation='create' THEN NULL ELSE expected_revision END,operation,created_version,
      next_code,next_name,next_description,next_type,next_active,requested_code,generate_code,description_provided,requested_type,requested_active,actor);
  RETURN QUERY SELECT next_revision,created_version;
END $$;


--
-- Name: account_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    organization_id uuid,
    kind text NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT account_events_kind CHECK ((kind = ANY (ARRAY['sign_in'::text, 'sign_out'::text, 'profile_changed'::text, 'password_changed'::text, 'password_reset'::text, 'mfa_enabled'::text, 'mfa_disabled'::text])))
);


--
-- Name: analytical_specification_limits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analytical_specification_limits (
    organization_id uuid NOT NULL,
    specification_id uuid NOT NULL,
    id uuid NOT NULL,
    lower_limit numeric,
    upper_limit numeric,
    lower_inclusive boolean NOT NULL,
    upper_inclusive boolean NOT NULL,
    outcome text NOT NULL,
    narration text,
    display_order integer NOT NULL,
    CONSTRAINT analytical_specification_limit_bounds CHECK (((num_nonnulls(lower_limit, upper_limit) >= 1) AND (lower_limit <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])) AND (upper_limit <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])) AND ((lower_limit IS NULL) OR (upper_limit IS NULL) OR (lower_limit <= upper_limit)) AND (display_order >= 0)))
);


--
-- Name: analytical_specifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.analytical_specifications (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    test_parameter_id uuid NOT NULL,
    parameter_revision integer NOT NULL,
    parameter_code text NOT NULL,
    parameter_name text NOT NULL,
    parameter_master_key text NOT NULL,
    parameter_scale integer NOT NULL,
    method_id uuid NOT NULL,
    method_revision integer NOT NULL,
    method_code text NOT NULL,
    method_name text NOT NULL,
    method_description text NOT NULL,
    method_uuid text NOT NULL,
    decimal_scale integer NOT NULL,
    parse_number boolean NOT NULL,
    measurement_unit_id uuid,
    unit_revision integer,
    unit_code text,
    unit_name text,
    unit_symbol text,
    unit_dimension text,
    decision_rule_id uuid,
    rule_revision integer,
    rule_code text,
    rule_name text,
    template_id uuid,
    cutoff_value numeric,
    greater_than_text text,
    less_than_text text,
    minimum_text text,
    maximum_text text,
    unit_of_measure text,
    result_representation text,
    default_narration text,
    detectable_upper_limit numeric,
    detectable_lower_limit numeric,
    detectable_upper_limit_text text,
    detectable_lower_limit_text text,
    show_detectable_limit_text boolean DEFAULT false NOT NULL,
    show_standard_limit_text boolean DEFAULT false NOT NULL,
    conformance_limit numeric,
    recorded_by uuid NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL,
    basis_specification_id uuid,
    CONSTRAINT analytical_spec_basis_identity CHECK ((basis_specification_id IS DISTINCT FROM id)),
    CONSTRAINT analytical_specification_numbers CHECK (((cutoff_value <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])) AND (detectable_upper_limit <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])) AND (detectable_lower_limit <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])) AND (conformance_limit <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])))),
    CONSTRAINT analytical_specification_revisions CHECK (((parameter_revision > 0) AND (method_revision > 0) AND ((parameter_scale >= 0) AND (parameter_scale <= 12)) AND ((decimal_scale >= 0) AND (decimal_scale <= 12)))),
    CONSTRAINT analytical_specification_rule CHECK ((((decision_rule_id IS NULL) AND (rule_revision IS NULL) AND (rule_code IS NULL) AND (rule_name IS NULL)) OR ((decision_rule_id IS NOT NULL) AND (rule_revision IS NOT NULL) AND (rule_revision > 0) AND (rule_code IS NOT NULL) AND (rule_name IS NOT NULL)))),
    CONSTRAINT analytical_specification_unit CHECK ((((measurement_unit_id IS NULL) AND (num_nonnulls(unit_revision, unit_code, unit_name, unit_symbol, unit_dimension) = 0)) OR ((measurement_unit_id IS NOT NULL) AND (unit_revision IS NOT NULL) AND (unit_revision > 0) AND (unit_code IS NOT NULL) AND (unit_name IS NOT NULL) AND (unit_symbol IS NOT NULL))))
);


--
-- Name: approval_assignments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_assignments (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    approval_stage_id uuid NOT NULL,
    assigned_user_id uuid NOT NULL,
    source_role_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    responded_at timestamp with time zone,
    CONSTRAINT approval_assignment_state CHECK ((((status = ANY (ARRAY['pending'::text, 'cancelled'::text])) AND (responded_at IS NULL)) OR ((status = ANY (ARRAY['approved'::text, 'rejected'::text])) AND (responded_at IS NOT NULL) AND (responded_at >= assigned_at))))
);


--
-- Name: approval_cases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_cases (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workflow_run_id uuid NOT NULL,
    workflow_version_id uuid NOT NULL,
    transition_id uuid NOT NULL,
    request_history_id uuid NOT NULL,
    run_revision integer NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    resolved_at timestamp with time zone,
    rejection_history_id uuid,
    CONSTRAINT approval_case_rejection_state CHECK (((rejection_history_id IS NULL) OR (status = 'rejected'::text))),
    CONSTRAINT approval_case_state CHECK (((run_revision > 0) AND (((status = 'pending'::text) AND (resolved_at IS NULL)) OR ((status = ANY (ARRAY['approved'::text, 'rejected'::text, 'cancelled'::text])) AND (resolved_at IS NOT NULL)))))
);


--
-- Name: approval_decision_checklist_answers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_decision_checklist_answers (
    organization_id uuid NOT NULL,
    decision_id uuid NOT NULL,
    transition_id uuid NOT NULL,
    checklist_item_id uuid NOT NULL,
    is_checked boolean NOT NULL
);


--
-- Name: approval_decisions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_decisions (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    approval_assignment_id uuid NOT NULL,
    decision text NOT NULL,
    decided_by uuid NOT NULL,
    comment text,
    decided_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT approval_decision_details CHECK (((decision = ANY (ARRAY['approve'::text, 'reject'::text])) AND ((comment IS NULL) OR (length(comment) <= 5000))))
);


--
-- Name: approval_stages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_stages (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    approval_case_id uuid NOT NULL,
    stage_number integer NOT NULL,
    completion_rule text NOT NULL,
    status text DEFAULT 'waiting'::text NOT NULL,
    activated_at timestamp with time zone,
    resolved_at timestamp with time zone,
    CONSTRAINT approval_stage_details CHECK ((((stage_number >= 1) AND (stage_number <= 100)) AND (completion_rule = ANY (ARRAY['any'::text, 'all'::text])) AND (((status = 'waiting'::text) AND (activated_at IS NULL) AND (resolved_at IS NULL)) OR ((status = 'pending'::text) AND (activated_at IS NOT NULL) AND (resolved_at IS NULL)) OR ((status = ANY (ARRAY['approved'::text, 'rejected'::text])) AND (activated_at IS NOT NULL) AND (resolved_at IS NOT NULL) AND (resolved_at >= activated_at)) OR ((status = 'cancelled'::text) AND (resolved_at IS NOT NULL) AND ((activated_at IS NULL) OR (resolved_at >= activated_at))))))
);


--
-- Name: assessment_answers; Type: TABLE; Schema: public; Owner: -
