    assessment_id uuid NOT NULL,
    user_id uuid NOT NULL,
    started_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    submitted_at timestamp with time zone,
    total_score integer,
    max_score integer NOT NULL,
    CONSTRAINT assessment_attempt_fields CHECK (((max_score >= 0) AND (((submitted_at IS NULL) AND (total_score IS NULL)) OR ((submitted_at IS NOT NULL) AND (submitted_at >= started_at) AND (total_score IS NOT NULL) AND ((total_score >= 0) AND (total_score <= max_score))))))
);

ALTER TABLE ONLY public.assessment_attempts FORCE ROW LEVEL SECURITY;


--
-- Name: assessment_question_options; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.assessment_question_options (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    question_id uuid NOT NULL,
    display_order integer NOT NULL,
    option_text text NOT NULL,
    is_correct boolean DEFAULT false NOT NULL,
    CONSTRAINT assessment_option_fields CHECK ((((length(TRIM(BOTH FROM option_text)) >= 1) AND (length(TRIM(BOTH FROM option_text)) <= 500)) AND (display_order >= 0)))
);

ALTER TABLE ONLY public.assessment_question_options FORCE ROW LEVEL SECURITY;


--
-- Name: assessment_questions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.assessment_questions (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    assessment_id uuid NOT NULL,
    display_order integer NOT NULL,
    question_text text NOT NULL,
    points integer DEFAULT 1 NOT NULL,
    CONSTRAINT assessment_question_fields CHECK ((((length(TRIM(BOTH FROM question_text)) >= 1) AND (length(TRIM(BOTH FROM question_text)) <= 2000)) AND ((points >= 1) AND (points <= 100)) AND (display_order >= 0)))
);

ALTER TABLE ONLY public.assessment_questions FORCE ROW LEVEL SECURITY;


--
-- Name: assessments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.assessments (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    description text,
    from_date timestamp with time zone NOT NULL,
    to_date timestamp with time zone NOT NULL,
    time_limit_minutes integer,
    is_released boolean DEFAULT false NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    updated_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT assessment_fields CHECK ((((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 200)) AND ((description IS NULL) OR ((length(description) >= 1) AND (length(description) <= 10000))) AND (to_date >= from_date) AND ((time_limit_minutes IS NULL) OR ((time_limit_minutes >= 1) AND (time_limit_minutes <= 1440))) AND (revision > 0)))
);

ALTER TABLE ONLY public.assessments FORCE ROW LEVEL SECURITY;


--
-- Name: business_units; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.business_units (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    description text,
    active boolean DEFAULT true NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_unit_fields CHECK ((((length(TRIM(BOTH FROM code)) >= 1) AND (length(TRIM(BOTH FROM code)) <= 64)) AND ((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 200)) AND ((description IS NULL) OR (length(description) <= 2000)) AND (revision > 0)))
);


--
-- Name: business_unit_directory; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.business_unit_directory WITH (security_barrier='true', security_invoker='false') AS
 SELECT organization_id,
    id,
    code,
    name,
    description,
    active,
    revision,
    created_at,
    updated_at
   FROM public.business_units
  WHERE (organization_id = ( SELECT public.users_directory_organization() AS users_directory_organization));


--
-- Name: business_unit_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.business_unit_versions (
    organization_id uuid NOT NULL,
    unit_id uuid NOT NULL,
    revision integer NOT NULL,
    previous_revision integer,
    request_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    description text,
    active boolean NOT NULL,
    saved_by uuid NOT NULL,
    saved_by_username text NOT NULL,
    saved_by_name text NOT NULL,
    saved_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT business_unit_version_fields CHECK ((((length(code) >= 1) AND (length(code) <= 64)) AND (code ~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$'::text) AND ((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 200)) AND ((description IS NULL) OR (length(description) <= 2000)))),
    CONSTRAINT business_unit_version_revision CHECK ((((previous_revision IS NULL) AND (revision = 1)) OR ((previous_revision IS NOT NULL) AND (previous_revision > 0) AND (revision = (previous_revision + 1)))))
);


--
-- Name: business_unit_history; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.business_unit_history WITH (security_barrier='true', security_invoker='false') AS
 SELECT organization_id,
    unit_id,
    revision,
    previous_revision,
    request_id,
    code,
    name,
    description,
    active,
    saved_by,
    saved_by_username,
    saved_by_name,
    saved_at
   FROM public.business_unit_versions
  WHERE (organization_id = ( SELECT public.users_directory_organization() AS users_directory_organization));


