--

CREATE TABLE public.customer_version_custom_field_values (
    organization_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    revision integer NOT NULL,
    field_id uuid NOT NULL,
    "position" integer NOT NULL,
    raw_kind text NOT NULL,
    raw_text text,
    raw_number double precision,
    raw_boolean boolean,
    raw_number_text text,
    interpretation_state text CONSTRAINT customer_version_custom_field_val_interpretation_state_not_null NOT NULL,
    parsed_number double precision,
    parsed_boolean boolean,
    parsed_date date,
    parsed_timestamp timestamp with time zone,
    option_id uuid,
    option_revision integer,
    user_id uuid,
    attachment_id uuid,
    lookup_source_id uuid,
    lookup_revision integer,
    lookup_line_id text,
    CONSTRAINT customer_custom_value_interpretation CHECK (((interpretation_state = ANY (ARRAY['empty'::text, 'valid'::text, 'invalid'::text, 'out_of_range'::text])) AND ((parsed_number IS NULL) OR ((parsed_number >= '-1.7976931348623157e+308'::double precision) AND (parsed_number <= '1.7976931348623157e+308'::double precision))) AND ((parsed_timestamp IS NULL) OR isfinite(parsed_timestamp)) AND ((parsed_date IS NULL) OR isfinite(parsed_date)) AND (((option_id IS NULL) AND (option_revision IS NULL)) OR ((option_id IS NOT NULL) AND (option_revision IS NOT NULL) AND (option_revision > 0))) AND ((interpretation_state = 'valid'::text) OR (num_nonnulls(parsed_number, parsed_boolean, parsed_date, parsed_timestamp, option_id, option_revision, user_id, attachment_id, lookup_source_id, lookup_revision, lookup_line_id) = 0)) AND ((interpretation_state = 'empty'::text) = ((raw_kind = 'text'::text) AND (raw_text = ''::text))))),
    CONSTRAINT customer_custom_value_lookup_reference CHECK (((num_nonnulls(lookup_source_id, lookup_revision, lookup_line_id) = 0) OR ((lookup_source_id IS NOT NULL) AND (lookup_revision IS NOT NULL) AND (lookup_revision > 0) AND (lookup_line_id IS NOT NULL)))),
    CONSTRAINT customer_custom_value_number_text CHECK (
CASE
    WHEN (raw_kind = 'number'::text) THEN ((raw_number_text IS NOT NULL) AND ((length(raw_number_text) >= 1) AND (length(raw_number_text) <= 32)) AND
    CASE
        WHEN (raw_number_text ~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?(e[+-]?[0-9]+)?$'::text) THEN ((raw_number_text)::double precision = raw_number)
        ELSE false
    END)
    ELSE (raw_number_text IS NULL)
END),
    CONSTRAINT customer_custom_value_raw CHECK (((("position" >= 0) AND ("position" <= 499)) AND (num_nonnulls(raw_text, raw_number, raw_boolean) = 1) AND (((raw_kind = 'text'::text) AND (raw_text IS NOT NULL) AND (length(raw_text) <= 16000)) OR ((raw_kind = 'number'::text) AND (raw_number IS NOT NULL) AND ((raw_number >= '-1.7976931348623157e+308'::double precision) AND (raw_number <= '1.7976931348623157e+308'::double precision))) OR ((raw_kind = 'boolean'::text) AND (raw_boolean IS NOT NULL)))))
);

