    CONSTRAINT customer_version_revision CHECK ((((operation = 'create'::text) AND (previous_revision IS NULL) AND (revision = 1)) OR ((operation = ANY (ARRAY['update'::text, 'retire'::text])) AND (previous_revision IS NOT NULL) AND (previous_revision > 0) AND (revision = (previous_revision + 1)))))
