    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    updated_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT dynamic_api_fields CHECK ((((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 200)) AND (url_key ~ '^[a-z0-9]([a-z0-9-]{0,98}[a-z0-9])?$'::text) AND (http_method = ANY (ARRAY['GET'::text, 'POST'::text, 'PUT'::text, 'PATCH'::text, 'DELETE'::text])) AND ((length(draft_code) >= 1) AND (length(draft_code) <= 65536)) AND ((live_code IS NULL) OR ((length(live_code) >= 1) AND (length(live_code) <= 65536))) AND (((published_by IS NULL) AND (published_at IS NULL) AND (live_code IS NULL)) OR ((published_by IS NOT NULL) AND (published_at IS NOT NULL) AND (live_code IS NOT NULL))) AND (revision > 0)))
);

