    source.id,
    source.revision,
    source.line_count,
    observation.line_count AS observed_line_count
   FROM (public.custom_field_lookup_sources source
     LEFT JOIN public.custom_field_lookup_versions observation ON (((observation.organization_id = source.organization_id) AND (observation.source_id = source.id) AND (observation.revision = source.revision))))
  WHERE ((source.organization_id = ( SELECT public.organization_module_scope() AS organization_module_scope)) AND ( SELECT public.instruments_can_read(NULL::uuid) AS instruments_can_read) AND (EXISTS ( SELECT 1
           FROM public.custom_field_definitions field
          WHERE ((field.organization_id = source.organization_id) AND field.active AND (field.associated_with = 'instrument'::text) AND (field.field_type = 'lookup'::text) AND (field.lookup_source_id = source.id)))));


