--
-- Name: template_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.template_versions (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    template_id uuid NOT NULL,
    number integer NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    name text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    kind text NOT NULL,
    semantics text DEFAULT 'hyperformula-v1'::text NOT NULL,
    source_version_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid NOT NULL,
    frozen_at timestamp with time zone,
    frozen_by uuid,
    template_type text,
    snapshot_source_id uuid,
    snapshot_source_revision integer,
    header_document_id uuid,
    footer_document_id uuid,
    nabl_header_document_id uuid,
    nabl_footer_document_id uuid,
    CONSTRAINT template_snapshot_source CHECK ((((snapshot_source_id IS NULL) AND (snapshot_source_revision IS NULL) AND (status <> 'building'::text)) OR ((snapshot_source_id IS NOT NULL) AND (snapshot_source_revision IS NOT NULL) AND (snapshot_source_revision > 0) AND (snapshot_source_id <> id) AND (status = ANY (ARRAY['building'::text, 'frozen'::text]))))),
    CONSTRAINT template_source_type CHECK (((template_type IS NULL) OR ((template_type = 'sample_coa'::text) AND (kind = 'report'::text)) OR ((template_type = ANY (ARRAY['job_template'::text, 'test_request'::text])) AND (kind = 'datasheet'::text)))),
    CONSTRAINT template_version_metadata CHECK (((number > 0) AND (revision > 0) AND ((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 200)) AND (length(description) <= 10000) AND (kind = ANY (ARRAY['sample'::text, 'datasheet'::text, 'report'::text, 'label'::text, 'equipment_service_log'::text])) AND (semantics = 'hyperformula-v1'::text))),
    CONSTRAINT template_version_state CHECK ((((status = ANY (ARRAY['draft'::text, 'building'::text])) AND (frozen_at IS NULL) AND (frozen_by IS NULL)) OR ((status = 'frozen'::text) AND (frozen_at IS NOT NULL) AND (frozen_by IS NOT NULL))))
);


