--
-- Name: instrument_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.instrument_versions (
    organization_id uuid NOT NULL,
    instrument_id uuid NOT NULL,
    revision integer NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    description text,
    laboratory_id uuid,
    make text,
    model_name text,
    serial_number text,
    date_of_installation date,
    calibration_agency text,
    calibrated boolean DEFAULT true NOT NULL,
    cost_of_equipment numeric(18,2),
    purchase_file_id uuid,
    current_location text,
    manufacturer_supplier text,
    active boolean DEFAULT true NOT NULL,
    retired boolean DEFAULT false NOT NULL,
    status text DEFAULT 'available'::text NOT NULL,
    current_status text DEFAULT 'is_working'::text NOT NULL,
    laboratory_name text,
    request_id uuid NOT NULL,
    request_fingerprint text NOT NULL,
    previous_revision integer,
    operation text NOT NULL,
    user_count integer NOT NULL,
    service_count integer NOT NULL,
    users_provided boolean NOT NULL,
    services_provided boolean NOT NULL,
    saved_by uuid NOT NULL,
    saved_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    custom_field_count integer DEFAULT 0 NOT NULL,
    custom_fields_provided boolean DEFAULT false NOT NULL,
    CONSTRAINT instrument_version_command CHECK (((request_fingerprint ~ '^[a-f0-9]{64}$'::text) AND ((user_count >= 1) AND (user_count <= 500)) AND ((service_count >= 0) AND (service_count <= 100)) AND (retired = (operation = 'retire'::text)) AND ((operation <> 'retire'::text) OR ((NOT users_provided) AND (NOT services_provided))))),
    CONSTRAINT instrument_version_revision CHECK ((((operation = 'create'::text) AND (previous_revision IS NULL) AND (revision = 1)) OR ((operation = ANY (ARRAY['update'::text, 'retire'::text])) AND (previous_revision > 0) AND (previous_revision IS NOT NULL) AND (revision = (previous_revision + 1))))),
    CONSTRAINT instrument_version_values CHECK ((((length(TRIM(BOTH FROM code)) >= 1) AND (length(TRIM(BOTH FROM code)) <= 64)) AND (code ~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$'::text) AND ((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 200)) AND ((description IS NULL) OR (length(description) <= 5000)) AND ((make IS NULL) OR (length(make) <= 200)) AND ((model_name IS NULL) OR (length(model_name) <= 200)) AND ((serial_number IS NULL) OR (length(serial_number) <= 200)) AND ((calibration_agency IS NULL) OR (length(calibration_agency) <= 250)) AND ((current_location IS NULL) OR (length(current_location) <= 250)) AND ((manufacturer_supplier IS NULL) OR (length(manufacturer_supplier) <= 250)) AND ((date_of_installation IS NULL) OR ((date_of_installation >= '0001-01-01'::date) AND (date_of_installation <= '9999-12-31'::date))) AND ((cost_of_equipment IS NULL) OR ((cost_of_equipment >= (0)::numeric) AND (cost_of_equipment <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])))) AND (status = ANY (ARRAY['available'::text, 'in_use'::text, 'maintenance'::text, 'out_of_service'::text, 'retired'::text])) AND (current_status = ANY (ARRAY['is_working'::text, 'in_breakdown'::text])) AND ((NOT retired) OR (NOT active)) AND (active OR (status = 'retired'::text)) AND ((custom_field_count >= 0) AND (custom_field_count <= 500)) AND ((NOT retired) OR (NOT custom_fields_provided))))
);

ALTER TABLE ONLY public.instrument_versions FORCE ROW LEVEL SECURITY;


