--
-- Name: laboratory_directory; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.laboratory_directory WITH (security_barrier='true', security_invoker='false') AS
 SELECT lab.organization_id,
    lab.id,
    lab.code,
    lab.name,
    lab.active,
    lab.revision,
    lab.created_at,
    lab.updated_at,
    lab.description,
    lab.abbreviation,
    lab.business_unit_id,
    lab.head_user_id,
    lab.delegate_user_id,
    lab.minimum_temperature_text,
    lab.maximum_temperature_text,
    lab.minimum_humidity_text,
    lab.maximum_humidity_text,
    unit.code AS business_unit_code,
    unit.name AS business_unit_name,
    hod.username AS head_username,
    hod.display_name AS head_user_name,
    delegate.username AS delegate_username,
    delegate.display_name AS delegate_user_name
   FROM (((public.laboratories lab
     LEFT JOIN public.business_units unit ON (((unit.organization_id = lab.organization_id) AND (unit.id = lab.business_unit_id))))
     LEFT JOIN public.users hod ON ((hod.id = lab.head_user_id)))
     LEFT JOIN public.users delegate ON ((delegate.id = lab.delegate_user_id)))
  WHERE (lab.organization_id = ( SELECT public.users_directory_organization() AS users_directory_organization));


