    saved_by_name text NOT NULL,
    saved_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT laboratory_version_fields CHECK ((((length(TRIM(BOTH FROM code)) >= 1) AND (length(TRIM(BOTH FROM code)) <= 64)) AND ((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 250)) AND ((operation <> 'retire'::text) OR (NOT active)))),
    CONSTRAINT laboratory_version_labels CHECK (((((business_unit_id IS NULL) AND (business_unit_code IS NULL) AND (business_unit_name IS NULL)) OR ((business_unit_id IS NOT NULL) AND (business_unit_code IS NOT NULL) AND (business_unit_name IS NOT NULL))) AND (((head_user_id IS NULL) AND (head_username IS NULL) AND (head_user_name IS NULL)) OR ((head_user_id IS NOT NULL) AND (head_username IS NOT NULL) AND (head_user_name IS NOT NULL))) AND (((delegate_user_id IS NULL) AND (delegate_username IS NULL) AND (delegate_user_name IS NULL)) OR ((delegate_user_id IS NOT NULL) AND (delegate_username IS NOT NULL) AND (delegate_user_name IS NOT NULL))))),
    CONSTRAINT laboratory_version_revision CHECK ((((operation = 'create'::text) AND (previous_revision IS NULL) AND (revision = 1)) OR ((operation = ANY (ARRAY['update'::text, 'retire'::text])) AND (previous_revision IS NOT NULL) AND (previous_revision > 0) AND (revision = (previous_revision + 1)))))
);


