--
-- Name: test_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.test_requests (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_number text NOT NULL,
    sample_test_id uuid,
    specification_id uuid,
    parent_test_request_id uuid,
    attempt_number integer DEFAULT 1 NOT NULL,
    status text DEFAULT 'created'::text NOT NULL,
    priority text DEFAULT 'normal'::text NOT NULL,
    due_at timestamp with time zone,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    datasheet_template_id uuid,
    final_datasheet_id uuid,
    revision integer DEFAULT 1 NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    is_job boolean DEFAULT false NOT NULL,
    is_auto_created boolean DEFAULT false NOT NULL,
    job_sample_product_id uuid,
    job_member_position integer,
    job_linked_by uuid,
    job_linked_at timestamp with time zone,
    using_dynamic_workflow boolean DEFAULT true,
    CONSTRAINT test_request_dates CHECK (((completed_at IS NULL) OR (started_at IS NULL) OR (completed_at >= started_at))),
    CONSTRAINT test_request_job_link_shape CHECK ((((parent_test_request_id IS NULL) AND (num_nonnulls(job_member_position, job_linked_by, job_linked_at) = 0)) OR ((parent_test_request_id IS NOT NULL) AND (job_member_position IS NOT NULL) AND (job_member_position >= 0) AND (job_linked_by IS NOT NULL) AND (job_linked_at IS NOT NULL) AND (parent_test_request_id <> id)))),
    CONSTRAINT test_request_kind_shape CHECK (((is_job AND (sample_test_id IS NULL) AND (specification_id IS NULL) AND (job_sample_product_id IS NOT NULL) AND (parent_test_request_id IS NULL)) OR ((NOT is_job) AND (NOT is_auto_created) AND (sample_test_id IS NOT NULL) AND (specification_id IS NOT NULL) AND (job_sample_product_id IS NULL)))),
    CONSTRAINT test_request_parent CHECK ((parent_test_request_id IS DISTINCT FROM id)),
    CONSTRAINT test_request_state CHECK (((status = ANY (ARRAY['created'::text, 'allocated'::text, 'in_progress'::text, 'under_review'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text])) AND (priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text])) AND (revision > 0) AND (attempt_number > 0)))
);


