    input_count integer,
    output_count integer,
    badge_style text,
    legacy_tr_state text,
    CONSTRAINT workflow_state_details CHECK (((state_type = ANY (ARRAY['initial'::text, 'normal'::text, 'final'::text, 'cancelled'::text])) AND (display_order >= 0) AND ((length(TRIM(BOTH FROM code)) >= 1) AND (length(TRIM(BOTH FROM code)) <= 64)) AND ((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 150)))),
    CONSTRAINT workflow_state_layout CHECK ((((canvas_x IS NULL) OR ((canvas_x >= 0) AND (canvas_x <= 100000))) AND ((canvas_y IS NULL) OR ((canvas_y >= 0) AND (canvas_y <= 100000))) AND ((input_count IS NULL) OR ((input_count >= 0) AND (input_count <= 8))) AND ((output_count IS NULL) OR ((output_count >= 0) AND (output_count <= 8))) AND ((badge_style IS NULL) OR (badge_style = ANY (ARRAY['light'::text, 'dark'::text]))))),
    CONSTRAINT workflow_state_legacy_tr_state CHECK (((legacy_tr_state IS NULL) OR (length(legacy_tr_state) <= 150)))
);


--
-- Name: laboratory_job_workflow_effects; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.laboratory_job_workflow_effects WITH (security_invoker='true') AS
 SELECT effect.organization_id,
    effect.id,
    effect.parent_run_revision,
    effect.child_workflow_run_id,
    effect.child_run_revision,
    member.test_request_id,
    history.id AS parent_history_id,
    history.workflow_run_id AS parent_workflow_run_id,
    job.id AS parent_request_id,
    job.request_number AS parent_job_number,
    history.action,
    history.actor_user_id,
    history.comment,
    history.occurred_at,
    history.transition_id,
    target.id AS target_state_id,
    target.name AS target_state_name,
    target.state_type AS target_state_type,
    target.color AS target_color,
    source.name AS source_state_name,
    ((child.final_datasheet_id = submission.datasheet_id) AND (sheet.latest_submission_id = member.submission_id) AND ((effect.child_workflow_run_id IS NULL) OR (child_run.revision = (effect.child_run_revision + 1)))) AS is_current
   FROM ((((((((((public.job_workflow_effects effect
     JOIN public.job_submission_members member ON (((member.organization_id = effect.organization_id) AND (member.id = effect.job_submission_member_id))))
     JOIN public.test_requests child ON (((child.organization_id = member.organization_id) AND (child.id = member.test_request_id))))
     JOIN public.datasheet_submissions submission ON (((submission.organization_id = member.organization_id) AND (submission.id = member.submission_id))))
     JOIN public.datasheets sheet ON (((sheet.organization_id = submission.organization_id) AND (sheet.id = submission.datasheet_id))))
     LEFT JOIN public.workflow_runs child_run ON (((child_run.organization_id = effect.organization_id) AND (child_run.id = effect.child_workflow_run_id))))
     JOIN public.workflow_run_history history ON (((history.organization_id = effect.organization_id) AND (history.id = effect.parent_history_id))))
     JOIN public.workflow_runs parent_run ON (((parent_run.organization_id = history.organization_id) AND (parent_run.id = history.workflow_run_id))))
     JOIN public.test_requests job ON (((job.organization_id = parent_run.organization_id) AND (job.id = parent_run.test_request_id))))
     JOIN public.workflow_states target ON (((target.organization_id = history.organization_id) AND (target.id = history.to_state_id))))
     LEFT JOIN public.workflow_states source ON (((source.organization_id = history.organization_id) AND (source.id = history.from_state_id))));


--
-- Name: sample_report_tests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sample_report_tests (
    organization_id uuid NOT NULL,
