    decision_limit_id uuid,
    display_order integer NOT NULL,
    product_code text NOT NULL,
    product_name text NOT NULL,
    request_number text NOT NULL,
    analyst_name text NOT NULL,
    is_accredited boolean NOT NULL,
    request_status text NOT NULL,
    datasheet_status text NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT report_test_state CHECK (((display_order >= 0) AND (request_status = ANY (ARRAY['under_review'::text, 'approved'::text])) AND (datasheet_status = ANY (ARRAY['under_review'::text, 'approved'::text]))))
);


--
-- Name: test_parameter_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.test_parameter_versions (
    organization_id uuid NOT NULL,
    parameter_id uuid NOT NULL,
    revision integer NOT NULL,
    request_id uuid NOT NULL,
    previous_revision integer,
    operation text NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    description text NOT NULL,
    master_key text NOT NULL,
    scheme_abbreviation text NOT NULL,
    display_order integer NOT NULL,
    active boolean NOT NULL,
    laboratory_id uuid,
    measurement_unit_id uuid,
    default_scale integer NOT NULL,
    has_uncertainty boolean NOT NULL,
    saved_by uuid NOT NULL,
    saved_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    custom_field_count integer DEFAULT 0 NOT NULL,
    custom_fields_provided boolean DEFAULT false NOT NULL,
    laboratory_name text,
    CONSTRAINT parameter_version_custom_fields CHECK ((((custom_field_count >= 0) AND (custom_field_count <= 500)) AND ((operation <> 'retire'::text) OR (NOT custom_fields_provided)))),
    CONSTRAINT parameter_version_laboratory_label CHECK (((laboratory_id IS NOT NULL) OR (laboratory_name IS NULL))),
    CONSTRAINT test_parameter_version_fields CHECK ((((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 250)) AND ((operation = 'retire'::text) OR ((length(TRIM(BOTH FROM name)) <= 200) AND (length(description) <= 16000))) AND ((length(TRIM(BOTH FROM code)) >= 1) AND (length(TRIM(BOTH FROM code)) <= 64)) AND ((length(TRIM(BOTH FROM master_key)) >= 1) AND (length(TRIM(BOTH FROM master_key)) <= 64)) AND ((length(TRIM(BOTH FROM scheme_abbreviation)) >= 1) AND (length(TRIM(BOTH FROM scheme_abbreviation)) <= 64)) AND (display_order >= 0) AND ((default_scale >= 0) AND (default_scale <= 12)) AND ((operation <> 'retire'::text) OR (NOT active)))),
    CONSTRAINT test_parameter_version_revision CHECK ((((operation = 'create'::text) AND (previous_revision IS NULL) AND (revision = 1)) OR ((operation = ANY (ARRAY['update'::text, 'retire'::text])) AND (previous_revision IS NOT NULL) AND (previous_revision > 0) AND (revision = (previous_revision + 1)))))
);


--
-- Name: laboratory_parameter_context; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.laboratory_parameter_context WITH (security_barrier='true', security_invoker='false') AS
 WITH scope AS MATERIALIZED (
         SELECT laboratory_parameter_read_scope.organization_id,
            laboratory_parameter_read_scope.report_id,
            laboratory_parameter_read_scope.specification_id
           FROM public.laboratory_parameter_read_scope() laboratory_parameter_read_scope(organization_id, report_id, specification_id)
        )
 SELECT specification.organization_id,
    specification.id AS specification_id,
    specification.test_parameter_id AS parameter_id,
    specification.parameter_revision,
    (version.revision IS NOT NULL) AS history_available,
    version.description,
    version.display_order,
    version.scheme_abbreviation,
    version.laboratory_id,
    version.custom_field_count,
    specification.parameter_name,
    specification.parameter_master_key
   FROM ((scope
     JOIN public.analytical_specifications specification ON (((specification.organization_id = scope.organization_id) AND ((scope.specification_id IS NULL) OR (specification.id = scope.specification_id)) AND ((scope.report_id IS NULL) OR (EXISTS ( SELECT 1
           FROM public.sample_report_tests chosen
          WHERE ((chosen.organization_id = scope.organization_id) AND (chosen.report_id = scope.report_id) AND (chosen.specification_id = specification.id))))))))
     LEFT JOIN public.test_parameter_versions version ON (((version.organization_id = specification.organization_id) AND (version.parameter_id = specification.test_parameter_id) AND (version.revision = specification.parameter_revision))));


--
-- Name: parameter_version_custom_fields; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.parameter_version_custom_fields (
    organization_id uuid NOT NULL,
    parameter_id uuid NOT NULL,
    revision integer NOT NULL,
    field_id uuid NOT NULL,
    field_revision integer NOT NULL,
    field_type text NOT NULL,
    "position" integer NOT NULL,
    is_array boolean NOT NULL,
    value_count integer NOT NULL,
    display_kind text NOT NULL,
    display_text text,
    display_number double precision,
    display_boolean boolean,
    time_zone text,
    time_zone_data_version text,
    date_parser_version text,
    CONSTRAINT parameter_custom_field_display CHECK (((num_nonnulls(display_text, display_number, display_boolean) = 1) AND (((display_kind = 'text'::text) AND (display_text IS NOT NULL) AND (length(display_text) <= 8000998)) OR ((display_kind = 'number'::text) AND (display_number IS NOT NULL) AND ((display_number >= '-1.7976931348623157e+308'::double precision) AND (display_number <= '1.7976931348623157e+308'::double precision))) OR ((display_kind = 'boolean'::text) AND (display_boolean IS NOT NULL))) AND ((NOT is_array) OR (display_kind = 'text'::text)))),
    CONSTRAINT parameter_custom_field_shape CHECK (((("position" >= 0) AND ("position" <= 499)) AND ((value_count >= 0) AND (value_count <= 500)) AND (is_array OR (value_count = 1)) AND (field_type = ANY (ARRAY['text'::text, 'number'::text, 'date'::text, 'select'::text, 'lookup'::text, 'longtext'::text, 'attachment'::text, 'multi_user_select'::text, 'date_time'::text, 'checkbox'::text, 'email'::text])))),
    CONSTRAINT parameter_custom_field_zone CHECK ((((field_type = ANY (ARRAY['date'::text, 'date_time'::text])) AND (time_zone IS NOT NULL) AND ((length(time_zone) >= 1) AND (length(time_zone) <= 100)) AND (time_zone_data_version IS NOT NULL) AND ((length(time_zone_data_version) >= 1) AND (length(time_zone_data_version) <= 40)) AND (date_parser_version IS NOT NULL) AND ((length(date_parser_version) >= 1) AND (length(date_parser_version) <= 80))) OR ((field_type <> ALL (ARRAY['date'::text, 'date_time'::text])) AND (num_nonnulls(time_zone, time_zone_data_version, date_parser_version) = 0))))
);

ALTER TABLE ONLY public.parameter_version_custom_fields FORCE ROW LEVEL SECURITY;


--
-- Name: laboratory_parameter_field_context; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.laboratory_parameter_field_context WITH (security_barrier='true', security_invoker='false') AS
 WITH scope AS MATERIALIZED (
         SELECT laboratory_parameter_read_scope.organization_id,
            laboratory_parameter_read_scope.report_id,
            laboratory_parameter_read_scope.specification_id
           FROM public.laboratory_parameter_read_scope() laboratory_parameter_read_scope(organization_id, report_id, specification_id)
        )
 SELECT field.organization_id,
    field.parameter_id,
    field.revision AS parameter_revision,
    field.field_id,
    field.field_revision,
    field.field_type,
    field."position",
    field.is_array,
    field.value_count,
    field.display_kind,
    field.display_text,
    field.display_number,
    field.display_boolean,
    definition.key AS field_key,
    definition.label,
    definition.scheme,
    definition.padded_number,
    definition.splitter,
    definition.date_format,
    definition.datetime_format
   FROM ((scope
     JOIN public.parameter_version_custom_fields field ON ((field.organization_id = scope.organization_id)))
     JOIN public.custom_field_versions definition ON (((definition.organization_id = field.organization_id) AND (definition.field_id = field.field_id) AND (definition.revision = field.field_revision))))
  WHERE (EXISTS ( SELECT 1
           FROM public.analytical_specifications specification
          WHERE ((specification.organization_id = field.organization_id) AND (specification.test_parameter_id = field.parameter_id) AND (specification.parameter_revision = field.revision) AND ((scope.specification_id IS NULL) OR (specification.id = scope.specification_id)) AND ((scope.report_id IS NULL) OR (EXISTS ( SELECT 1
                   FROM public.sample_report_tests chosen
                  WHERE ((chosen.organization_id = scope.organization_id) AND (chosen.report_id = scope.report_id) AND (chosen.specification_id = specification.id))))))));


--
-- Name: test_parameter_version_methods; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.test_parameter_version_methods (
    organization_id uuid NOT NULL,
    parameter_id uuid NOT NULL,
    revision integer NOT NULL,
    method_id uuid NOT NULL,
    is_default boolean NOT NULL,
    method_revision integer,
    method_name text,
    CONSTRAINT test_parameter_version_method_observation CHECK ((((method_revision IS NULL) AND (method_name IS NULL)) OR ((method_revision IS NOT NULL) AND (method_name IS NOT NULL) AND (method_revision > 0) AND ((length(TRIM(BOTH FROM method_name)) >= 1) AND (length(TRIM(BOTH FROM method_name)) <= 250)))))
);


--
-- Name: laboratory_parameter_method_context; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.laboratory_parameter_method_context WITH (security_barrier='true', security_invoker='false') AS
 WITH scope AS MATERIALIZED (
         SELECT laboratory_parameter_read_scope.organization_id,
            laboratory_parameter_read_scope.report_id,
            laboratory_parameter_read_scope.specification_id
           FROM public.laboratory_parameter_read_scope() laboratory_parameter_read_scope(organization_id, report_id, specification_id)
        )
 SELECT method.organization_id,
    method.parameter_id,
    method.revision AS parameter_revision,
    method.method_id,
    method.is_default,
    method.method_revision,
    method.method_name
   FROM (scope
     JOIN public.test_parameter_version_methods method ON ((method.organization_id = scope.organization_id)))
  WHERE (EXISTS ( SELECT 1
           FROM public.analytical_specifications specification
          WHERE ((specification.organization_id = method.organization_id) AND (specification.test_parameter_id = method.parameter_id) AND (specification.parameter_revision = method.revision) AND ((scope.specification_id IS NULL) OR (specification.id = scope.specification_id)) AND ((scope.report_id IS NULL) OR (EXISTS ( SELECT 1
                   FROM public.sample_report_tests chosen
                  WHERE ((chosen.organization_id = scope.organization_id) AND (chosen.report_id = scope.report_id) AND (chosen.specification_id = specification.id))))))));


--
-- Name: parameter_version_custom_field_values; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.parameter_version_custom_field_values (
    organization_id uuid NOT NULL,
    parameter_id uuid NOT NULL,
    revision integer NOT NULL,
    field_id uuid NOT NULL,
    "position" integer NOT NULL,
    raw_kind text NOT NULL,
    raw_text text,
    raw_number double precision,
    raw_boolean boolean,
    raw_number_text text,
    interpretation_state text CONSTRAINT parameter_version_custom_field_va_interpretation_state_not_null NOT NULL,
    parsed_number double precision,
    parsed_boolean boolean,
    parsed_date date,
    parsed_timestamp timestamp with time zone,
    option_id uuid,
    option_revision integer,
    user_id uuid,
    attachment_id uuid,
    lookup_source_id uuid,
    lookup_revision integer,
    lookup_line_id text,
    CONSTRAINT parameter_custom_value_interpretation CHECK (((interpretation_state = ANY (ARRAY['empty'::text, 'valid'::text, 'invalid'::text, 'out_of_range'::text])) AND ((parsed_number IS NULL) OR ((parsed_number >= '-1.7976931348623157e+308'::double precision) AND (parsed_number <= '1.7976931348623157e+308'::double precision))) AND ((parsed_timestamp IS NULL) OR isfinite(parsed_timestamp)) AND ((parsed_date IS NULL) OR isfinite(parsed_date)) AND (((option_id IS NULL) AND (option_revision IS NULL)) OR ((option_id IS NOT NULL) AND (option_revision IS NOT NULL) AND (option_revision > 0))) AND ((interpretation_state = 'valid'::text) OR (num_nonnulls(parsed_number, parsed_boolean, parsed_date, parsed_timestamp, option_id, option_revision, user_id, attachment_id, lookup_source_id, lookup_revision, lookup_line_id) = 0)) AND ((interpretation_state = 'empty'::text) = ((raw_kind = 'text'::text) AND (raw_text = ''::text))))),
    CONSTRAINT parameter_custom_value_lookup_reference CHECK (((num_nonnulls(lookup_source_id, lookup_revision, lookup_line_id) = 0) OR ((lookup_source_id IS NOT NULL) AND (lookup_revision IS NOT NULL) AND (lookup_revision > 0) AND (lookup_line_id IS NOT NULL)))),
    CONSTRAINT parameter_custom_value_number_text CHECK (
CASE
    WHEN (raw_kind = 'number'::text) THEN ((raw_number_text IS NOT NULL) AND ((length(raw_number_text) >= 1) AND (length(raw_number_text) <= 32)) AND
    CASE
        WHEN (raw_number_text ~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?(e[+-]?[0-9]+)?$'::text) THEN ((raw_number_text)::double precision = raw_number)
        ELSE false
    END)
    ELSE (raw_number_text IS NULL)
END),
    CONSTRAINT parameter_custom_value_raw CHECK (((("position" >= 0) AND ("position" <= 499)) AND (num_nonnulls(raw_text, raw_number, raw_boolean) = 1) AND (((raw_kind = 'text'::text) AND (raw_text IS NOT NULL) AND (length(raw_text) <= 16000)) OR ((raw_kind = 'number'::text) AND (raw_number IS NOT NULL) AND ((raw_number >= '-1.7976931348623157e+308'::double precision) AND (raw_number <= '1.7976931348623157e+308'::double precision))) OR ((raw_kind = 'boolean'::text) AND (raw_boolean IS NOT NULL)))))
);

ALTER TABLE ONLY public.parameter_version_custom_field_values FORCE ROW LEVEL SECURITY;


--
-- Name: laboratory_parameter_value_context; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.laboratory_parameter_value_context WITH (security_barrier='true', security_invoker='false') AS
 SELECT field.organization_id,
    field.parameter_id,
    field.parameter_revision,
    field.field_key,
    item.field_id,
    item."position",
    item.raw_kind,
    item.raw_text,
    item.raw_number,
    item.raw_boolean
   FROM (public.laboratory_parameter_field_context field
     JOIN public.parameter_version_custom_field_values item ON (((item.organization_id = field.organization_id) AND (item.parameter_id = field.parameter_id) AND (item.revision = field.parameter_revision) AND (item.field_id = field.field_id))));


--
-- Name: product_version_custom_fields; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.product_version_custom_fields (
    organization_id uuid NOT NULL,
