    display_number double precision,
    display_boolean boolean,
    time_zone text,
    time_zone_data_version text,
    date_parser_version text,
    CONSTRAINT product_custom_field_display CHECK (((num_nonnulls(display_text, display_number, display_boolean) = 1) AND (((display_kind = 'text'::text) AND (display_text IS NOT NULL) AND (length(display_text) <= 8000998)) OR ((display_kind = 'number'::text) AND (display_number IS NOT NULL) AND ((display_number >= '-1.7976931348623157e+308'::double precision) AND (display_number <= '1.7976931348623157e+308'::double precision))) OR ((display_kind = 'boolean'::text) AND (display_boolean IS NOT NULL))) AND ((NOT is_array) OR (display_kind = 'text'::text)))),
    CONSTRAINT product_custom_field_shape CHECK (((("position" >= 0) AND ("position" <= 499)) AND ((value_count >= 0) AND (value_count <= 500)) AND (is_array OR (value_count = 1)) AND (field_type = ANY (ARRAY['text'::text, 'number'::text, 'date'::text, 'select'::text, 'lookup'::text, 'longtext'::text, 'attachment'::text, 'multi_user_select'::text, 'date_time'::text, 'checkbox'::text, 'email'::text])))),
    CONSTRAINT product_custom_field_zone CHECK ((((field_type = ANY (ARRAY['date'::text, 'date_time'::text])) AND (time_zone IS NOT NULL) AND ((length(time_zone) >= 1) AND (length(time_zone) <= 100)) AND (time_zone_data_version IS NOT NULL) AND ((length(time_zone_data_version) >= 1) AND (length(time_zone_data_version) <= 40)) AND (date_parser_version IS NOT NULL) AND ((length(date_parser_version) >= 1) AND (length(date_parser_version) <= 80))) OR ((field_type <> ALL (ARRAY['date'::text, 'date_time'::text])) AND (num_nonnulls(time_zone, time_zone_data_version, date_parser_version) = 0))))
);

ALTER TABLE ONLY public.product_version_custom_fields FORCE ROW LEVEL SECURITY;


