--
-- Name: product_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.product_versions (
    organization_id uuid NOT NULL,
    product_id uuid NOT NULL,
    revision integer NOT NULL,
    request_id uuid NOT NULL,
    previous_revision integer,
    operation text NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    description text NOT NULL,
    abbreviation text,
    job_template_id uuid,
    active boolean NOT NULL,
    tag_count integer NOT NULL,
    saved_by uuid NOT NULL,
    saved_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    custom_field_count integer DEFAULT 0 NOT NULL,
    custom_fields_provided boolean DEFAULT false NOT NULL,
    CONSTRAINT product_version_custom_fields CHECK ((((custom_field_count >= 0) AND (custom_field_count <= 500)) AND ((operation <> 'retire'::text) OR (NOT custom_fields_provided)))),
    CONSTRAINT product_version_fields CHECK ((((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 250)) AND ((length(TRIM(BOTH FROM code)) >= 1) AND (length(TRIM(BOTH FROM code)) <= 64)) AND (tag_count >= 0) AND ((operation = 'retire'::text) OR ((length(TRIM(BOTH FROM name)) <= 200) AND (length(description) <= 16000) AND (tag_count <= 500) AND ((abbreviation IS NULL) OR (length(abbreviation) <= 64)) AND (code ~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$'::text))) AND ((operation <> 'retire'::text) OR (NOT active)))),
    CONSTRAINT product_version_revision CHECK ((((operation = 'create'::text) AND (previous_revision IS NULL) AND (revision = 1)) OR ((operation = ANY (ARRAY['update'::text, 'retire'::text])) AND (previous_revision IS NOT NULL) AND (previous_revision > 0) AND (revision = (previous_revision + 1)))))
);


