    vendor_id uuid,
    CONSTRAINT master_bulk_attempt_fields CHECK (((committed AND (num_nonnulls(product_id, parameter_id, method_id, user_id, customer_id, vendor_id) = 1) AND (result_revision IS NOT NULL) AND (result_revision > 0) AND (error_code IS NULL) AND (error_message IS NULL)) OR ((NOT committed) AND (num_nonnulls(product_id, parameter_id, method_id, user_id, customer_id, vendor_id, result_revision) = 0) AND (error_code IS NOT NULL) AND ((length(error_code) >= 1) AND (length(error_code) <= 100)) AND (error_message IS NOT NULL) AND ((length(error_message) >= 1) AND (length(error_message) <= 2000)))))
);

ALTER TABLE ONLY public.master_bulk_attempts FORCE ROW LEVEL SECURITY;


