--
-- Name: master_bulk_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.master_bulk_batches (
    organization_id uuid NOT NULL,
    id uuid NOT NULL,
    resource text NOT NULL,
    file_name text NOT NULL,
    file_format text NOT NULL,
    source_sha256 text,
    time_zone text NOT NULL,
    header_row_number integer NOT NULL,
    sheet_name text,
    sheet_count integer,
    date_1904 boolean,
    column_count integer NOT NULL,
    row_count integer NOT NULL,
    saved_by uuid NOT NULL,
    saved_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    source_hmac_sha256 text,
    CONSTRAINT master_bulk_batch_fields CHECK (((resource = ANY (ARRAY['products'::text, 'test-parameters'::text, 'methods'::text, 'users'::text, 'customers'::text, 'vendors'::text])) AND ((length(file_name) >= 1) AND (length(file_name) <= 250)) AND (file_format = ANY (ARRAY['csv'::text, 'xlsx'::text])) AND (((resource = 'users'::text) AND (source_sha256 IS NULL) AND (source_hmac_sha256 IS NOT NULL) AND (source_hmac_sha256 ~ '^[a-f0-9]{64}$'::text)) OR ((resource <> 'users'::text) AND (source_hmac_sha256 IS NULL) AND (source_sha256 IS NOT NULL) AND (source_sha256 ~ '^[a-f0-9]{64}$'::text))) AND ((length(time_zone) >= 1) AND (length(time_zone) <= 100)) AND (header_row_number > 0) AND ((column_count >= 1) AND (column_count <= 250)) AND ((row_count >= 1) AND (row_count <= 2500)) AND (((file_format = 'csv'::text) AND (num_nonnulls(sheet_name, sheet_count, date_1904) = 0)) OR ((file_format = 'xlsx'::text) AND (sheet_name IS NOT NULL) AND ((length(sheet_name) >= 1) AND (length(sheet_name) <= 100)) AND (sheet_count IS NOT NULL) AND ((sheet_count >= 1) AND (sheet_count <= 512)) AND (date_1904 IS NOT NULL)))))
);

ALTER TABLE ONLY public.master_bulk_batches FORCE ROW LEVEL SECURITY;


--
-- Name: master_bulk_cells; Type: TABLE; Schema: public; Owner: -
