    revision integer NOT NULL,
    column_number integer NOT NULL,
    value_kind text NOT NULL,
    text_value text,
    number_value double precision,
    boolean_value boolean,
    date_value timestamp with time zone,
    source_type text,
    formula text,
    has_result boolean,
    error_code text,
    hyperlink text,
    number_format text,
    CONSTRAINT master_bulk_cell_source CHECK ((((source_type IS NULL) OR (source_type = ANY (ARRAY['formula'::text, 'error'::text, 'hyperlink'::text, 'rich_text'::text, 'formatted'::text, 'date'::text]))) AND ((formula IS NULL) OR (length(formula) <= 16000)) AND ((error_code IS NULL) OR (length(error_code) <= 16000)) AND ((hyperlink IS NULL) OR (length(hyperlink) <= 16000)) AND ((number_format IS NULL) OR (length(number_format) <= 16000)))),
    CONSTRAINT master_bulk_cell_value CHECK ((((value_kind = 'missing'::text) AND (num_nonnulls(text_value, number_value, boolean_value, date_value) = 0)) OR ((num_nonnulls(text_value, number_value, boolean_value, date_value) = 1) AND (((value_kind = 'text'::text) AND (text_value IS NOT NULL) AND (length(text_value) <= 16000)) OR ((value_kind = 'number'::text) AND (number_value IS NOT NULL) AND ((number_value >= '-1.7976931348623157e+308'::double precision) AND (number_value <= '1.7976931348623157e+308'::double precision))) OR ((value_kind = 'boolean'::text) AND (boolean_value IS NOT NULL)) OR ((value_kind = 'date'::text) AND (date_value IS NOT NULL) AND isfinite(date_value))))))
);

ALTER TABLE ONLY public.master_bulk_cells FORCE ROW LEVEL SECURITY;


