);

ALTER TABLE ONLY public.master_bulk_columns FORCE ROW LEVEL SECURITY;


--
-- Name: master_bulk_reviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.master_bulk_reviews (
    organization_id uuid NOT NULL,
    id uuid NOT NULL,
    batch_id uuid NOT NULL,
    row_id uuid NOT NULL,
    input_revision integer NOT NULL,
    sequence bigint NOT NULL,
    valid boolean NOT NULL,
    candidate_id uuid,
    expected_revision integer,
    operation text,
    definitions_sha256 text,
    command_sha256 text,
    error_code text,
    error_message text,
    saved_by uuid NOT NULL,
    saved_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT master_bulk_review_fields CHECK (((valid AND (candidate_id IS NOT NULL) AND (expected_revision IS NOT NULL) AND (expected_revision >= 0) AND (operation IS NOT NULL) AND (operation = ANY (ARRAY['create'::text, 'update'::text, 'reactivate'::text, 'update_retired'::text])) AND (definitions_sha256 IS NOT NULL) AND (definitions_sha256 ~ '^[a-f0-9]{64}$'::text) AND (command_sha256 IS NOT NULL) AND (command_sha256 ~ '^[a-f0-9]{64}$'::text) AND (error_code IS NULL) AND (error_message IS NULL) AND ((operation = 'create'::text) = (expected_revision = 0))) OR ((NOT valid) AND (num_nonnulls(candidate_id, expected_revision, operation, definitions_sha256, command_sha256) = 0) AND (error_code IS NOT NULL) AND ((length(error_code) >= 1) AND (length(error_code) <= 100)) AND (error_message IS NOT NULL) AND ((length(error_message) >= 1) AND (length(error_message) <= 2000)))))
);

ALTER TABLE ONLY public.master_bulk_reviews FORCE ROW LEVEL SECURITY;


