--
-- Name: master_bulk_user_credentials; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.master_bulk_user_credentials (
    organization_id uuid NOT NULL,
    batch_id uuid NOT NULL,
    row_id uuid NOT NULL,
    input_revision integer NOT NULL,
    state text NOT NULL,
    fingerprint bytea NOT NULL,
    password_hash text,
    saved_by uuid NOT NULL,
    saved_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT master_bulk_user_credential_fields CHECK (((octet_length(fingerprint) = 32) AND (((state = 'valid'::text) AND (password_hash IS NOT NULL) AND (password_hash ~ '^scrypt[$]1[$]32768[$]8[$]1[$][A-Za-z0-9_-]{22}[$][A-Za-z0-9_-]{86}$'::text)) OR ((state = ANY (ARRAY['missing'::text, 'invalid'::text])) AND (password_hash IS NULL)))))
);

ALTER TABLE ONLY public.master_bulk_user_credentials FORCE ROW LEVEL SECURITY;


--
-- Name: master_bulk_user_credential_states; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.master_bulk_user_credential_states WITH (security_barrier='true') AS
 SELECT organization_id,
    batch_id,
    row_id,
    input_revision,
    state,
    encode(fingerprint, 'hex'::text) AS fingerprint
   FROM public.master_bulk_user_credentials
  WHERE ((NOT (organization_id IS DISTINCT FROM (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid)) AND ( SELECT public.app_has_permission('users.manage'::text) AS app_has_permission));


--
-- Name: master_bulk_user_labels; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.master_bulk_user_labels WITH (security_barrier='true') AS
 SELECT member.organization_id,
    person.id,
    person.username,
    person.email,
    person.display_name,
    (member.active AND person.active) AS active
   FROM (public.memberships member
     JOIN public.users person ON ((person.id = member.user_id)))
  WHERE ((member.organization_id = (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid) AND ( SELECT public.app_has_permission('masters.manage'::text) AS app_has_permission));


