    CONSTRAINT material_category_fields CHECK ((((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 200)) AND (length(description) <= 16000) AND (revision > 0)))
);


--
-- Name: material_category_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.material_category_versions (
    organization_id uuid NOT NULL,
    category_id uuid NOT NULL,
    revision integer NOT NULL,
    request_id uuid NOT NULL,
    previous_revision integer,
    operation text NOT NULL,
    name text NOT NULL,
    description text NOT NULL,
    reusable boolean NOT NULL,
    expirable boolean NOT NULL,
    active boolean NOT NULL,
    saved_by uuid NOT NULL,
    saved_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT material_category_version_fields CHECK ((((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 200)) AND (length(description) <= 16000))),
    CONSTRAINT material_category_version_revision CHECK ((((operation = 'create'::text) AND (previous_revision IS NULL) AND (revision = 1) AND active) OR ((operation = ANY (ARRAY['update'::text, 'retire'::text])) AND (previous_revision IS NOT NULL) AND (previous_revision > 0) AND (revision = (previous_revision + 1)) AND (active = (operation = 'update'::text)))))
);


--
