    CONSTRAINT material_transaction_amounts CHECK (((quantity > (0)::numeric) AND (quantity <= ''::numeric) AND (((transaction_type = 'in'::text) AND (cost IS NOT NULL) AND ((cost >= (0)::numeric) AND (cost <= ''::numeric))) OR ((transaction_type <> 'in'::text) AND (cost IS NULL) AND (expiry_date IS NULL))))),
    CONSTRAINT material_transaction_expiry CHECK (((expiry_date IS NULL) OR ((expiry_date >= '0001-01-01'::date) AND (expiry_date <= '9999-12-31'::date)))),
    CONSTRAINT material_transaction_fields CHECK (((transaction_type = ANY (ARRAY['in'::text, 'out'::text, 'out_damaged'::text])) AND ((length(TRIM(BOTH FROM batch_serial_number)) >= 1) AND (length(TRIM(BOTH FROM batch_serial_number)) <= 150)) AND (length(supplier) <= 250)))
);


