    CONSTRAINT material_fields CHECK ((((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 200)) AND ((length(TRIM(BOTH FROM code)) >= 1) AND (length(TRIM(BOTH FROM code)) <= 64)) AND (length(description) <= 16000) AND (revision > 0))),
    CONSTRAINT material_opening_identity CHECK ((((initial_quantity = (0)::numeric) AND (initial_stock_id IS NULL) AND (initial_stock_created_at IS NULL) AND (initial_stock_created_by IS NULL)) OR ((initial_quantity > (0)::numeric) AND (initial_stock_id IS NOT NULL) AND (initial_stock_created_at IS NOT NULL))))
);


