--

CREATE VIEW public.method_access_user_labels WITH (security_barrier='true', security_invoker='false') AS
 SELECT member.organization_id,
    person.id AS user_id,
    person.display_name,
    (member.active AND person.active) AS active
   FROM (public.memberships member
     JOIN public.users person ON ((person.id = member.user_id)))
  WHERE ((member.organization_id = (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid) AND ( SELECT (public.app_has_permission('masters.read'::text) OR public.app_has_permission('masters.manage'::text))));


--
-- Name: method_version_custom_field_values; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.method_version_custom_field_values (
    organization_id uuid NOT NULL,
    method_id uuid NOT NULL,
    revision integer NOT NULL,
    field_id uuid NOT NULL,
    "position" integer NOT NULL,
    raw_kind text NOT NULL,
    raw_text text,
    raw_number double precision,
    raw_boolean boolean,
    raw_number_text text,
    interpretation_state text CONSTRAINT method_version_custom_field_value_interpretation_state_not_null NOT NULL,
    parsed_number double precision,
    parsed_boolean boolean,
    parsed_date date,
    parsed_timestamp timestamp with time zone,
    option_id uuid,
    option_revision integer,
    user_id uuid,
    attachment_id uuid,
    lookup_source_id uuid,
    lookup_revision integer,
    lookup_line_id text,
    CONSTRAINT method_custom_value_interpretation CHECK (((interpretation_state = ANY (ARRAY['empty'::text, 'valid'::text, 'invalid'::text, 'out_of_range'::text])) AND ((parsed_number IS NULL) OR ((parsed_number >= '-1.7976931348623157e+308'::double precision) AND (parsed_number <= '1.7976931348623157e+308'::double precision))) AND ((parsed_timestamp IS NULL) OR isfinite(parsed_timestamp)) AND ((parsed_date IS NULL) OR isfinite(parsed_date)) AND (((option_id IS NULL) AND (option_revision IS NULL)) OR ((option_id IS NOT NULL) AND (option_revision IS NOT NULL) AND (option_revision > 0))) AND ((interpretation_state = 'valid'::text) OR (num_nonnulls(parsed_number, parsed_boolean, parsed_date, parsed_timestamp, option_id, option_revision, user_id, attachment_id, lookup_source_id, lookup_revision, lookup_line_id) = 0)) AND ((interpretation_state = 'empty'::text) = ((raw_kind = 'text'::text) AND (raw_text = ''::text))))),
    CONSTRAINT method_custom_value_lookup_reference CHECK (((num_nonnulls(lookup_source_id, lookup_revision, lookup_line_id) = 0) OR ((lookup_source_id IS NOT NULL) AND (lookup_revision IS NOT NULL) AND (lookup_revision > 0) AND (lookup_line_id IS NOT NULL)))),
    CONSTRAINT method_custom_value_number_text CHECK (
CASE
    WHEN (raw_kind = 'number'::text) THEN ((raw_number_text IS NOT NULL) AND ((length(raw_number_text) >= 1) AND (length(raw_number_text) <= 32)) AND
    CASE
        WHEN (raw_number_text ~ '^-?(0|[1-9][0-9]*)([.][0-9]+)?(e[+-]?[0-9]+)?$'::text) THEN ((raw_number_text)::double precision = raw_number)
        ELSE false
    END)
    ELSE (raw_number_text IS NULL)
END),
    CONSTRAINT method_custom_value_raw CHECK (((("position" >= 0) AND ("position" <= 499)) AND (num_nonnulls(raw_text, raw_number, raw_boolean) = 1) AND (((raw_kind = 'text'::text) AND (raw_text IS NOT NULL) AND (length(raw_text) <= 16000)) OR ((raw_kind = 'number'::text) AND (raw_number IS NOT NULL) AND ((raw_number >= '-1.7976931348623157e+308'::double precision) AND (raw_number <= '1.7976931348623157e+308'::double precision))) OR ((raw_kind = 'boolean'::text) AND (raw_boolean IS NOT NULL)))))
);

ALTER TABLE ONLY public.method_version_custom_field_values FORCE ROW LEVEL SECURITY;


--
-- Name: method_version_custom_fields; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.method_version_custom_fields (
    organization_id uuid NOT NULL,
    method_id uuid NOT NULL,
    revision integer NOT NULL,
    field_id uuid NOT NULL,
    field_revision integer NOT NULL,
    field_type text NOT NULL,
    "position" integer NOT NULL,
    is_array boolean NOT NULL,
    value_count integer NOT NULL,
    display_kind text NOT NULL,
    display_text text,
    display_number double precision,
    display_boolean boolean,
    time_zone text,
    time_zone_data_version text,
    date_parser_version text,
    CONSTRAINT method_custom_field_display CHECK (((num_nonnulls(display_text, display_number, display_boolean) = 1) AND (((display_kind = 'text'::text) AND (display_text IS NOT NULL) AND (length(display_text) <= 8000998)) OR ((display_kind = 'number'::text) AND (display_number IS NOT NULL) AND ((display_number >= '-1.7976931348623157e+308'::double precision) AND (display_number <= '1.7976931348623157e+308'::double precision))) OR ((display_kind = 'boolean'::text) AND (display_boolean IS NOT NULL))) AND ((NOT is_array) OR (display_kind = 'text'::text)))),
    CONSTRAINT method_custom_field_shape CHECK (((("position" >= 0) AND ("position" <= 499)) AND ((value_count >= 0) AND (value_count <= 500)) AND (is_array OR (value_count = 1)) AND (field_type = ANY (ARRAY['text'::text, 'number'::text, 'date'::text, 'select'::text, 'lookup'::text, 'longtext'::text, 'attachment'::text, 'multi_user_select'::text, 'date_time'::text, 'checkbox'::text, 'email'::text])))),
    CONSTRAINT method_custom_field_zone CHECK ((((field_type = ANY (ARRAY['date'::text, 'date_time'::text])) AND (time_zone IS NOT NULL) AND ((length(time_zone) >= 1) AND (length(time_zone) <= 100)) AND (time_zone_data_version IS NOT NULL) AND ((length(time_zone_data_version) >= 1) AND (length(time_zone_data_version) <= 40)) AND (date_parser_version IS NOT NULL) AND ((length(date_parser_version) >= 1) AND (length(date_parser_version) <= 80))) OR ((field_type <> ALL (ARRAY['date'::text, 'date_time'::text])) AND (num_nonnulls(time_zone, time_zone_data_version, date_parser_version) = 0))))
);

ALTER TABLE ONLY public.method_version_custom_fields FORCE ROW LEVEL SECURITY;


