    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    custom_field_count integer DEFAULT 0 NOT NULL,
    custom_fields_provided boolean DEFAULT false NOT NULL,
    CONSTRAINT method_version_custom_fields CHECK ((((custom_field_count >= 0) AND (custom_field_count <= 500)) AND ((operation <> 'retire'::text) OR (NOT custom_fields_provided)))),
    CONSTRAINT method_version_fields CHECK ((((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 250)) AND ((operation = 'retire'::text) OR ((length(TRIM(BOTH FROM name)) <= 200) AND (length(description) <= 16000))) AND ((length(TRIM(BOTH FROM code)) >= 1) AND (length(TRIM(BOTH FROM code)) <= 64)) AND ((length(TRIM(BOTH FROM method_uuid)) >= 1) AND (length(TRIM(BOTH FROM method_uuid)) <= 100)) AND ((decimal_scale >= 0) AND (decimal_scale <= 12)) AND ((access_user_count >= 0) AND (access_user_count <= 500)) AND ((operation <> 'retire'::text) OR (NOT active)))),
    CONSTRAINT method_version_revision CHECK ((((operation = 'create'::text) AND (previous_revision IS NULL) AND (revision = 1)) OR ((operation = ANY (ARRAY['update'::text, 'retire'::text])) AND (previous_revision IS NOT NULL) AND (previous_revision > 0) AND (revision = (previous_revision + 1)))))
);


