);


--
-- Name: nabl_certificate_directory; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.nabl_certificate_directory WITH (security_barrier='true', security_invoker='false') AS
 SELECT version.organization_id,
    version.certification_id,
    version.revision,
    version.previous_revision,
    version.request_id,
    version.operation,
    version.valid_from,
    version.valid_to,
    version.scope_file_id,
    version.certificate_file_id,
    version.scope_count,
    version.active,
    version.saved_by,
    version.saved_by_username,
    version.saved_by_name,
    version.saved_at,
    version.created_transaction_id,
    version.scope_file_name,
    version.scope_file_type,
    version.scope_file_length,
    version.scope_file_sha256,
    version.certificate_file_name,
    version.certificate_file_type,
    version.certificate_file_length,
    version.certificate_file_sha256,
    head.created_at,
    head.updated_at
   FROM (public.nabl_certificate_history version
     JOIN public.nabl_certifications head ON (((head.organization_id = version.organization_id) AND (head.id = version.certification_id) AND (head.revision = version.revision))))
  WHERE (head.active AND (head.organization_id = ( SELECT public.nabl_scope_organization() AS nabl_scope_organization)));


--
-- Name: nabl_file_content; Type: VIEW; Schema: public; Owner: -
