    zebra_printing_enabled boolean DEFAULT false CONSTRAINT organization_laboratory_setting_zebra_printing_enabled_not_null NOT NULL,
    scrollable_sample_listing boolean DEFAULT true CONSTRAINT organization_laboratory_sett_scrollable_sample_listing_not_null NOT NULL,
    auto_initialize_samples boolean DEFAULT false CONSTRAINT organization_laboratory_settin_auto_initialize_samples_not_null NOT NULL,
    show_barcode_section boolean DEFAULT true NOT NULL,
    show_jobcard_actions boolean DEFAULT true NOT NULL,
    show_datasheet_actions boolean DEFAULT true CONSTRAINT organization_laboratory_setting_show_datasheet_actions_not_null NOT NULL,
    show_workflow_nodes boolean DEFAULT true NOT NULL,
    use_templatized_acknowledgement boolean DEFAULT false CONSTRAINT organization_laboratory_set_use_templatized_acknowledg_not_null NOT NULL,
    directly_print_coa boolean DEFAULT false NOT NULL,
    allow_manual_results boolean DEFAULT false NOT NULL,
    non_lims_mode boolean DEFAULT false NOT NULL,
    lims_label text,
    sample_association_mode text DEFAULT 'single'::text CONSTRAINT organization_laboratory_settin_sample_association_mode_not_null NOT NULL,
    default_sample_category_id uuid,
    sample_number_scheme text DEFAULT 'SMP-{current_year:yyyy}-{sample_counter}'::text NOT NULL,
    test_request_number_scheme text DEFAULT 'TR-{current_year:yyyy}-{tr_counter}'::text CONSTRAINT organization_laboratory_set_test_request_number_scheme_not_null NOT NULL,
    job_number_scheme text DEFAULT 'JOB-{current_year:yyyy}-{job_countall}'::text NOT NULL,
    sample_number_start integer DEFAULT 1 NOT NULL,
    test_request_number_start integer DEFAULT 1 CONSTRAINT organization_laboratory_sett_test_request_number_start_not_null NOT NULL,
    instrument_breakdown_validation_enabled boolean DEFAULT true CONSTRAINT organization_laboratory_set_instrument_breakdown_valid_not_null NOT NULL,
    minimum_material_validation_enabled boolean DEFAULT true CONSTRAINT organization_laboratory_set_minimum_material_validatio_not_null NOT NULL,
    measurement_uncertainty_enabled boolean DEFAULT false CONSTRAINT organization_laboratory_set_measurement_uncertainty_en_not_null NOT NULL,
    reminder_before_minutes integer DEFAULT 60 CONSTRAINT organization_laboratory_settin_reminder_before_minutes_not_null NOT NULL,
    print_nabl_on_non_nabl boolean DEFAULT false CONSTRAINT organization_laboratory_setting_print_nabl_on_non_nabl_not_null NOT NULL,
    on_demand_ulr boolean DEFAULT false NOT NULL,
    generate_ulr_for_amendment boolean DEFAULT false CONSTRAINT organization_laboratory_set_generate_ulr_for_amendment_not_null NOT NULL,
    ulr_start_number integer DEFAULT 1 NOT NULL,
    include_f_in_ulr boolean DEFAULT false NOT NULL,
    ulr_number_padding integer DEFAULT 6 NOT NULL,
    retention_days integer DEFAULT 0 NOT NULL,
    company_legal_name text,
    company_identification_number text,
    company_tax_identifier text,
    company_address text,
    default_retention_period integer DEFAULT 0 CONSTRAINT organization_laboratory_setti_default_retention_period_not_null NOT NULL,
    default_classification text,
    product_label text DEFAULT 'Product'::text NOT NULL,
    sample_label text DEFAULT 'Sample'::text NOT NULL,
    customer_label text DEFAULT 'Customer'::text NOT NULL,
    vendor_label text DEFAULT 'Vendor'::text NOT NULL,
    sample_scheme text,
    minimum_password_length integer DEFAULT 12 CONSTRAINT organization_laboratory_settin_minimum_password_length_not_null NOT NULL,
    maximum_login_attempts integer DEFAULT 5 CONSTRAINT organization_laboratory_setting_maximum_login_attempts_not_null NOT NULL,
    support_slug text,
    operating_start_time time without time zone,
    operating_end_time time without time zone,
    environment_data_interval_minutes integer,
    project_default_page text,
    CONSTRAINT lab_settings_accounting_fields CHECK (((length(company_legal_name) <= 250) AND (length(company_identification_number) <= 100) AND (length(company_tax_identifier) <= 100) AND (length(company_address) <= 4000))),
    CONSTRAINT lab_settings_date_format CHECK ((length(date_format) <= 40)),
    CONSTRAINT lab_settings_datetime_format CHECK ((length(datetime_format) <= 60)),
    CONSTRAINT lab_settings_identity_fields CHECK (((length(display_name) <= 200) AND (length(description) <= 4000) AND (length(tagline) <= 300) AND (length(brand_color) <= 20) AND (length(nabl_number) <= 100) AND (length(location_code) <= 64) AND ((length(entity_name) >= 1) AND (length(entity_name) <= 100)) AND ((length(product_entity_name) >= 1) AND (length(product_entity_name) <= 100)) AND ((header_style IS NULL) OR (header_style = ANY (ARRAY['fixed'::text, 'floating'::text]))))),
    CONSTRAINT lab_settings_nabl_fields CHECK (((ulr_start_number > 0) AND ((ulr_number_padding >= 1) AND (ulr_number_padding <= 20)) AND (retention_days >= 0))),
    CONSTRAINT lab_settings_numbering_fields CHECK ((((length(sample_number_scheme) >= 1) AND (length(sample_number_scheme) <= 200)) AND ((length(test_request_number_scheme) >= 1) AND (length(test_request_number_scheme) <= 200)) AND ((length(job_number_scheme) >= 1) AND (length(job_number_scheme) <= 200)) AND (sample_number_start > 0) AND (test_request_number_start > 0))),
    CONSTRAINT lab_settings_revision CHECK ((revision > 0)),
    CONSTRAINT lab_settings_sample_page_fields CHECK ((((lims_label IS NULL) OR (length(lims_label) <= 100)) AND (sample_association_mode = ANY (ARRAY['single'::text, 'multiple'::text])))),
    CONSTRAINT lab_settings_scheme_values CHECK (((length(scheme_current_year_digits) <= 128) AND (length(scheme_next_year_digits) <= 128) AND (length(scheme_separator) <= 250) AND (length(scheme_non_nabl_start_number) <= 128) AND ((scheme_month_format IS NULL) OR (scheme_month_format = ANY (ARRAY[''::text, 'number'::text, 'short'::text, 'long'::text]))))),
    CONSTRAINT lab_settings_tenant_fields CHECK (((default_retention_period >= 0) AND (length(default_classification) <= 150) AND ((length(product_label) >= 1) AND (length(product_label) <= 100)) AND ((length(sample_label) >= 1) AND (length(sample_label) <= 100)) AND ((length(customer_label) >= 1) AND (length(customer_label) <= 100)) AND ((length(vendor_label) >= 1) AND (length(vendor_label) <= 100)) AND (length(sample_scheme) <= 200) AND ((minimum_password_length >= 8) AND (minimum_password_length <= 200)) AND ((maximum_login_attempts >= 1) AND (maximum_login_attempts <= 20)) AND (length(support_slug) <= 100) AND ((environment_data_interval_minutes IS NULL) OR (environment_data_interval_minutes > 0)) AND ((operating_start_time IS NULL) OR (operating_end_time IS NULL) OR (operating_start_time <> operating_end_time)) AND ((project_default_page IS NULL) OR (project_default_page = ANY (ARRAY['overview'::text, 'stages'::text, 'files'::text, 'update_history'::text, 'workflow'::text, 'team'::text, 'requests'::text, 'planner'::text, 'critical_params'::text, 'project_metadata'::text, 'project_rationale'::text, 'activity_log'::text])))))
);


