-- Name: organization_module_role_catalog; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.organization_module_role_catalog WITH (security_barrier='true', security_invoker='false') AS
 SELECT organization_id,
    id,
    name AS label,
    active
   FROM public.roles role
  WHERE ((organization_id = public.organization_module_scope()) AND (public.app_has_permission('settings.read'::text) OR public.app_has_permission('settings.manage'::text)));


--
-- Name: organization_module_user_catalog; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.organization_module_user_catalog WITH (security_barrier='true', security_invoker='false') AS
 SELECT membership.organization_id,
    person.id,
    COALESCE(NULLIF(person.display_name, ''::text), NULLIF(person.email, ''::text), (person.id)::text) AS label,
    person.username,
    (person.active AND membership.active) AS active
   FROM (public.memberships membership
     JOIN public.users person ON ((person.id = membership.user_id)))
  WHERE ((membership.organization_id = public.organization_module_scope()) AND (public.app_has_permission('settings.read'::text) OR public.app_has_permission('settings.manage'::text)));


