--
-- Name: organizations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.organizations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    domain text,
    status text DEFAULT 'active'::text NOT NULL,
    active_from_date date,
    active_till_date date,
    account_type text DEFAULT 'saas'::text NOT NULL,
    purchase_order_number text,
    address text,
    contact_person text,
    contact_phone text,
    project_manager text,
    sales_person text,
    pricing_plan text,
    subscription_cost numeric,
    custom_development_cost numeric,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT organization_account_type CHECK ((account_type = ANY (ARRAY['saas'::text, 'enterprise'::text]))),
    CONSTRAINT organization_active_dates CHECK (((active_from_date IS NULL) OR (active_till_date IS NULL) OR (active_from_date <= active_till_date))),
    CONSTRAINT organization_active_matches_status CHECK ((active = (status = 'active'::text))),
    CONSTRAINT organization_costs CHECK ((((subscription_cost IS NULL) OR ((subscription_cost >= (0)::numeric) AND (subscription_cost <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])))) AND ((custom_development_cost IS NULL) OR ((custom_development_cost >= (0)::numeric) AND (custom_development_cost <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])))))),
    CONSTRAINT organization_status CHECK ((status = ANY (ARRAY['active'::text, 'suspended'::text, 'archived'::text]))),
    CONSTRAINT organization_text_fields CHECK ((((domain IS NULL) OR ((length(domain) >= 1) AND (length(domain) <= 200))) AND ((purchase_order_number IS NULL) OR (length(purchase_order_number) <= 100)) AND ((address IS NULL) OR (length(address) <= 4000)) AND ((contact_person IS NULL) OR (length(contact_person) <= 200)) AND ((contact_phone IS NULL) OR (length(contact_phone) <= 50)) AND ((project_manager IS NULL) OR (length(project_manager) <= 200)) AND ((sales_person IS NULL) OR (length(sales_person) <= 200)) AND ((pricing_plan IS NULL) OR (length(pricing_plan) <= 200))))
);


