--
-- Name: product_template_labels; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.product_template_labels WITH (security_barrier='true', security_invoker='false') AS
 SELECT template.organization_id,
    template.id AS template_id,
    template.code,
    version.name,
    version.kind,
    template.active
   FROM (public.templates template
     JOIN LATERAL ( SELECT version_1.name,
            version_1.kind
           FROM public.template_versions version_1
          WHERE ((version_1.organization_id = template.organization_id) AND (version_1.template_id = template.id) AND (version_1.status <> 'building'::text))
          ORDER BY (version_1.status = 'draft'::text) DESC, version_1.number DESC
         LIMIT 1) version ON (true))
  WHERE ((template.organization_id = (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid) AND ( SELECT (public.app_has_permission('masters.read'::text) OR public.app_has_permission('masters.manage'::text))));


