--
-- Name: report_image_assets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.report_image_assets (
    organization_id uuid NOT NULL,
    id uuid NOT NULL,
    original_name text NOT NULL,
    media_type text NOT NULL,
    content bytea NOT NULL,
    byte_length integer NOT NULL,
    sha256 text NOT NULL,
    width integer NOT NULL,
    height integer NOT NULL,
    uploaded_by uuid NOT NULL,
    uploaded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT report_image_asset_shape CHECK (((media_type = ANY (ARRAY['image/png'::text, 'image/jpeg'::text, 'image/webp'::text, 'image/svg+xml'::text])) AND ((length(TRIM(BOTH FROM original_name)) >= 1) AND (length(TRIM(BOTH FROM original_name)) <= 255)) AND (sha256 ~ '^[a-f0-9]{64}$'::text) AND ((byte_length >= 1) AND (byte_length <= 10485760)) AND (byte_length = octet_length(content)) AND ((width >= 1) AND (width <= 10000)) AND ((height >= 1) AND (height <= 10000)) AND (((width)::bigint * (height)::bigint) <= 40000000)))
);

ALTER TABLE ONLY public.report_image_assets FORCE ROW LEVEL SECURITY;


--
-- Name: report_pdf_artifacts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.report_pdf_artifacts (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    report_id uuid NOT NULL,
    job_id uuid NOT NULL,
    attempt_number integer NOT NULL,
    content_type text DEFAULT 'application/pdf'::text NOT NULL,
    byte_length integer NOT NULL,
    sha256 bytea NOT NULL,
    content bytea NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT report_pdf_artifact_bytes CHECK (((content_type = 'application/pdf'::text) AND (byte_length = octet_length(content)) AND ((byte_length >= 100) AND (byte_length <= 52428800)) AND (octet_length(sha256) = 32) AND (sha256 = sha256(content)) AND (SUBSTRING(content FROM 1 FOR 5) = convert_to('%PDF-'::text, 'UTF8'::name))))
);


--
-- Name: report_pdf_attempts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.report_pdf_attempts (
    organization_id uuid NOT NULL,
    job_id uuid NOT NULL,
    attempt_number integer NOT NULL,
    worker_id uuid NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    status text DEFAULT 'running'::text NOT NULL,
    error_code text,
    error_message text,
    CONSTRAINT report_pdf_attempt_dates CHECK (((completed_at IS NULL) OR (completed_at >= started_at))),
    CONSTRAINT report_pdf_attempt_number CHECK (((attempt_number >= 1) AND (attempt_number <= 5))),
    CONSTRAINT report_pdf_attempt_state CHECK ((((status = 'running'::text) AND (completed_at IS NULL) AND (error_code IS NULL) AND (error_message IS NULL)) OR ((status = 'succeeded'::text) AND (completed_at IS NOT NULL) AND (error_code IS NULL) AND (error_message IS NULL)) OR ((status = ANY (ARRAY['failed'::text, 'expired'::text])) AND (completed_at IS NOT NULL) AND (error_code IS NOT NULL) AND (error_message IS NOT NULL) AND (error_code ~ '^[a-z0-9_]{1,80}$'::text) AND ((length(error_message) >= 1) AND (length(error_message) <= 2000)))))
);


