    transaction_id xid8 NOT NULL,
    CONSTRAINT report_watermark_version_shape CHECK (((revision > 0) AND ((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 200)) AND ((opacity >= (0)::numeric) AND (opacity <= (1)::numeric)) AND ((width >= 1) AND (width <= 10000)) AND ((height >= 1) AND (height <= 10000)) AND (rotation = ANY (ARRAY[0, 90, 180, 270, 360]))))
);

