);


--
-- Name: role_management_settings; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.role_management_settings WITH (security_barrier='true', security_invoker='false') AS
 SELECT organization.id AS organization_id,
    COALESCE(settings.self_allocation_enabled, false) AS self_allocation_enabled
   FROM (public.organizations organization
     LEFT JOIN public.organization_laboratory_settings settings ON ((settings.organization_id = organization.id)))
  WHERE ((organization.id = (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid) AND ( SELECT (public.app_has_permission('roles.read'::text) OR public.app_has_permission('roles.manage'::text))));


