--
-- Name: role_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.role_versions (
    organization_id uuid NOT NULL,
    role_id uuid NOT NULL,
    revision integer NOT NULL,
    request_id uuid NOT NULL,
    previous_revision integer,
    operation text NOT NULL,
    name text NOT NULL,
    description text NOT NULL,
    default_path text,
    active boolean NOT NULL,
    protected boolean NOT NULL,
    permission_count integer NOT NULL,
    capability_count integer NOT NULL,
    description_provided boolean NOT NULL,
    default_path_provided boolean NOT NULL,
    permissions_provided boolean NOT NULL,
    capabilities_provided boolean NOT NULL,
    saved_by uuid NOT NULL,
    saved_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT role_version_fields CHECK ((((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 150)) AND (length(description) <= 2000) AND ((default_path IS NULL) OR (length(default_path) <= 300)) AND (active = (operation <> 'retire'::text)) AND ((NOT protected) OR active) AND ((permission_count >= 0) AND (permission_count <= 500)) AND ((capability_count >= 0) AND (capability_count <= 18)) AND ((operation <> 'retire'::text) OR (NOT (description_provided OR default_path_provided OR permissions_provided OR capabilities_provided))))),
    CONSTRAINT role_version_revision CHECK ((((operation = 'create'::text) AND (previous_revision IS NULL) AND (revision = 1)) OR ((operation = ANY (ARRAY['update'::text, 'retire'::text])) AND (previous_revision IS NOT NULL) AND (previous_revision >= 0) AND (revision = (previous_revision + 1)))))
);


