    enable_events boolean DEFAULT false NOT NULL,
    enable_reissue boolean DEFAULT false NOT NULL,
    save_request_id uuid,
    CONSTRAINT sample_categories_estimate_finite CHECK ((estimated_time_in_days <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision]))),
    CONSTRAINT sample_categories_metadata CHECK ((((length(TRIM(BOTH FROM code)) >= 1) AND (length(TRIM(BOTH FROM code)) <= 64)) AND ((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 250)) AND (revision > 0))),
    CONSTRAINT sample_categories_settings CHECK (((length(TRIM(BOTH FROM abbreviation)) >= 1) AND (length(TRIM(BOTH FROM abbreviation)) <= 64) AND (retention_days >= 0) AND (estimated_time_in_days >= (0)::double precision)))
);


