--
-- Name: sample_category_user_labels; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.sample_category_user_labels WITH (security_barrier='true', security_invoker='false') AS
 SELECT member.organization_id,
    person.id,
    person.username,
    person.display_name,
    (member.active AND person.active) AS active
   FROM (public.memberships member
     JOIN public.users person ON ((person.id = member.user_id)))
  WHERE ((member.organization_id = (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid) AND ( SELECT (public.app_has_permission('masters.read'::text) OR public.app_has_permission('masters.manage'::text))));


