--
-- Name: sample_category_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sample_category_versions (
    organization_id uuid NOT NULL,
    sample_category_id uuid NOT NULL,
    revision integer NOT NULL,
    request_id uuid NOT NULL,
    previous_revision integer,
    operation text NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    description text NOT NULL,
    abbreviation text NOT NULL,
    retention_days integer,
    estimated_time_in_days double precision NOT NULL,
    enable_events boolean NOT NULL,
    enable_reissue boolean NOT NULL,
    active boolean NOT NULL,
    saved_by uuid NOT NULL,
    saved_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT sample_category_version_fields CHECK ((((length(TRIM(BOTH FROM code)) >= 1) AND (length(TRIM(BOTH FROM code)) <= 64)) AND ((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 250)) AND ((operation = 'retire'::text) OR ((length(TRIM(BOTH FROM name)) <= 200) AND (length(description) <= 16000) AND ((length(TRIM(BOTH FROM abbreviation)) >= 1) AND (length(TRIM(BOTH FROM abbreviation)) <= 64)) AND (retention_days >= 0) AND (estimated_time_in_days >= (0)::double precision) AND (estimated_time_in_days <> ALL (ARRAY['NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision])))) AND ((operation <> 'retire'::text) OR (NOT active)))),
    CONSTRAINT sample_category_version_revision CHECK ((((operation = 'create'::text) AND (previous_revision IS NULL) AND (revision = 1)) OR ((operation = ANY (ARRAY['update'::text, 'retire'::text])) AND (previous_revision IS NOT NULL) AND (previous_revision > 0) AND (revision = (previous_revision + 1)))))
);

