    CONSTRAINT sample_event_type CHECK ((event_type = ANY (ARRAY['sample_registered'::text, 'test_requests_generated'::text, 'test_request_assigned'::text, 'datasheet_created'::text, 'datasheet_submitted'::text, 'reports_generated'::text, 'reports_finalized'::text, 'report_issued'::text, 'report_reissued'::text, 'datasheet_method_added'::text, 'datasheet_method_voided'::text, 'test_request_job_created'::text, 'sample_updated'::text])))
);


