    CONSTRAINT report_print_settings_shape CHECK (((page_size = ANY (ARRAY['A3'::text, 'A4'::text, 'A5'::text, 'Letter'::text, 'Legal'::text])) AND ((scale >= 0.1) AND (scale <= (1)::numeric)) AND ((x_margin >= (0)::numeric) AND (x_margin <= (500)::numeric)) AND ((top_margin >= (0)::numeric) AND (top_margin <= (500)::numeric)) AND ((bottom_margin >= (0)::numeric) AND (bottom_margin <= (500)::numeric))))
);


--
-- Name: sample_reports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sample_reports (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sample_id uuid NOT NULL,
    template_version_id uuid NOT NULL,
    report_number text NOT NULL,
    revision integer NOT NULL,
    report_type text NOT NULL,
    group_key text NOT NULL,
    sample_product_id uuid,
    sample_test_id uuid,
    status text DEFAULT 'draft'::text NOT NULL,
    generated_by uuid NOT NULL,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    issued_by uuid,
    issued_at timestamp with time zone,
    sample_revision integer NOT NULL,
    sample_number text NOT NULL,
    sample_type text NOT NULL,
    sample_category_name text NOT NULL,
    customer_name text,
    customer_address text,
    customer_reference text,
    received_at timestamp with time zone NOT NULL,
    registered_at timestamp with time zone NOT NULL,
    due_at timestamp with time zone,
    description text,
    generated_event_id uuid NOT NULL,
    is_finalized boolean DEFAULT false NOT NULL,
    product_context_line_id uuid,
    is_nabl boolean NOT NULL,
    is_reissued boolean DEFAULT false NOT NULL,
    reissue_source_id uuid,
    reissue_batch_id uuid,
    reissued_by uuid,
    reissued_at timestamp with time zone,
    CONSTRAINT report_group CHECK ((((report_type = 'consolidated'::text) AND (group_key = ('consolidated:'::text ||
CASE
    WHEN is_nabl THEN 'nabl'::text
    ELSE 'non_nabl'::text
END)) AND (sample_product_id IS NULL) AND (sample_test_id IS NULL)) OR ((report_type = 'product_wise'::text) AND (sample_product_id IS NOT NULL) AND (sample_test_id IS NULL) AND (group_key = ((('product:'::text || (sample_product_id)::text) || ':'::text) ||
CASE
    WHEN is_nabl THEN 'nabl'::text
    ELSE 'non_nabl'::text
END))) OR ((report_type = 'parameter_wise'::text) AND (sample_product_id IS NOT NULL) AND (sample_test_id IS NOT NULL) AND (group_key = ((('parameter:'::text || (sample_test_id)::text) || ':'::text) ||
CASE
    WHEN is_nabl THEN 'nabl'::text
    ELSE 'non_nabl'::text
END))))),
    CONSTRAINT report_reissue CHECK ((((NOT is_reissued) AND (reissue_source_id IS NULL) AND (reissue_batch_id IS NULL) AND (reissued_by IS NULL) AND (reissued_at IS NULL)) OR (is_reissued AND (reissue_source_id IS NOT NULL) AND (reissue_source_id <> id) AND (reissue_batch_id IS NOT NULL) AND (reissued_by IS NOT NULL) AND (reissued_at IS NOT NULL) AND (reissued_at >= generated_at) AND is_finalized))),
    CONSTRAINT report_revision CHECK (((revision > 0) AND (sample_revision > 0) AND ((length(TRIM(BOTH FROM report_number)) >= 1) AND (length(TRIM(BOTH FROM report_number)) <= 100)))),
    CONSTRAINT report_status CHECK ((((status = 'draft'::text) AND (issued_by IS NULL) AND (issued_at IS NULL)) OR ((status = ANY (ARRAY['issued'::text, 'superseded'::text])) AND (issued_by IS NOT NULL) AND (issued_at IS NOT NULL) AND (issued_at >= generated_at))))
);


--
-- Name: samples; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.samples (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sample_number text NOT NULL,
    sample_category_id uuid NOT NULL,
    customer_id uuid,
    customer_quotation_id uuid,
    category_code text NOT NULL,
    category_name text NOT NULL,
    category_abbreviation text NOT NULL,
    customer_code text,
    customer_name text,
    customer_legal_name text,
    customer_address text,
    customer_reference text,
    sample_type text DEFAULT 'customer'::text NOT NULL,
    status text DEFAULT 'registered'::text NOT NULL,
    received_at timestamp with time zone NOT NULL,
    registered_at timestamp with time zone DEFAULT now() NOT NULL,
    due_at timestamp with time zone,
    quantity numeric,
    description text,
    storage_location text,
    retention_due_on date,
    iqc_type text,
    participant_count integer,
    ilc_mode text,
    mode_of_receipt text,
    total_amount numeric,
    currency_code text,
    received_by_name text,
    collection_details text,
    amendment_remarks text,
    complaint_remarks text,
    revision integer DEFAULT 1 NOT NULL,
    registered_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    template_instance_id uuid,
    complaint_rca text,
    complaint_capa text,
    CONSTRAINT sample_amount CHECK ((((total_amount IS NULL) AND (currency_code IS NULL)) OR ((total_amount IS NOT NULL) AND (currency_code IS NOT NULL) AND (total_amount >= (0)::numeric) AND (total_amount <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])) AND (currency_code ~ '^[A-Z]{3}$'::text)))),
    CONSTRAINT sample_customer CHECK ((((sample_type <> 'customer'::text) OR (customer_id IS NOT NULL)) AND ((customer_quotation_id IS NULL) OR (customer_id IS NOT NULL)) AND (((customer_id IS NULL) AND (num_nonnulls(customer_code, customer_name, customer_legal_name) = 0)) OR ((customer_id IS NOT NULL) AND (customer_code IS NOT NULL) AND (customer_name IS NOT NULL) AND (customer_legal_name IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM customer_address), ''::text) IS NOT NULL))))),
    CONSTRAINT sample_dates_quantity CHECK ((((due_at IS NULL) OR (due_at >= received_at)) AND ((quantity IS NULL) OR ((quantity > (0)::numeric) AND (quantity <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])))))),
    CONSTRAINT sample_ilc CHECK ((((ilc_mode IS NULL) OR (ilc_mode = ANY (ARRAY['organizer'::text, 'participant'::text]))) AND ((sample_type = 'interlaboratory'::text) OR (ilc_mode IS NULL)))),
    CONSTRAINT sample_iqc CHECK ((((iqc_type IS NULL) OR (iqc_type = ANY (ARRAY['repetition'::text, 'retest'::text, 'blind'::text, 'int_lab'::text]))) AND ((participant_count IS NULL) OR (participant_count > 0)) AND ((sample_type = 'quality_control'::text) OR ((iqc_type IS NULL) AND (participant_count IS NULL))) AND ((iqc_type IS DISTINCT FROM 'int_lab'::text) OR (participant_count IS NOT NULL)))),
    CONSTRAINT sample_required_variant_details CHECK ((((sample_type <> 'quality_control'::text) OR (iqc_type IS NOT NULL)) AND ((sample_type <> 'interlaboratory'::text) OR (ilc_mode IS NOT NULL)))),
    CONSTRAINT sample_status CHECK (((status = ANY (ARRAY['registered'::text, 'in_progress'::text, 'on_hold'::text, 'completed'::text, 'rejected'::text, 'cancelled'::text])) AND (revision > 0))),
    CONSTRAINT sample_type CHECK ((sample_type = ANY (ARRAY['customer'::text, 'internal'::text, 'quality_control'::text, 'proficiency'::text, 'interlaboratory'::text, 'amendment'::text, 'complaint'::text])))
);


