);


--
-- Name: service_agreement_files; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.service_agreement_files (
    organization_id uuid NOT NULL,
    id uuid NOT NULL,
    original_name text NOT NULL,
    media_type text NOT NULL,
    content bytea NOT NULL,
    byte_length integer NOT NULL,
    sha256 text NOT NULL,
    uploaded_by uuid NOT NULL,
    uploaded_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT service_agreement_file_values CHECK ((((length(original_name) >= 1) AND (length(original_name) <= 500)) AND (original_name = TRIM(BOTH FROM original_name)) AND (original_name !~ '[[:cntrl:]]'::text) AND (POSITION(('/'::text) IN (original_name)) = 0) AND (POSITION((chr(92)) IN (original_name)) = 0) AND (media_type = ANY (ARRAY['application/pdf'::text, 'image/jpeg'::text, 'image/png'::text, 'image/webp'::text, 'text/plain'::text, 'text/csv'::text, 'application/msword'::text, 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'::text, 'application/vnd.ms-excel'::text, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'::text])) AND ((byte_length >= 1) AND (byte_length <= 26214400)) AND (byte_length = octet_length(content)) AND (sha256 = encode(sha256(content), 'hex'::text))))
);

ALTER TABLE ONLY public.service_agreement_files FORCE ROW LEVEL SECURITY;


--
-- Name: service_agreement_instrument_catalog; Type: VIEW; Schema: public; Owner: -
