 SELECT organization_id,
    id,
    revision,
    code,
    name,
    active
   FROM public.instruments
  WHERE ((organization_id = ( SELECT public.organization_module_scope() AS organization_module_scope)) AND ( SELECT public.service_agreements_can_read() AS service_agreements_can_read) AND (NOT retired));


