    name text NOT NULL,
    legal_name text NOT NULL,
    abbreviation text,
    tax_identifier text,
    total_balance numeric(18,2) DEFAULT '0'::numeric NOT NULL,
    active boolean DEFAULT true NOT NULL,
    retired boolean DEFAULT false NOT NULL,
    custom_field_count integer DEFAULT 0 NOT NULL,
    custom_fields_provided boolean DEFAULT false NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    save_request_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT vendor_revision CHECK ((revision > 0)),
    CONSTRAINT vendor_values CHECK ((((length(TRIM(BOTH FROM code)) >= 1) AND (length(TRIM(BOTH FROM code)) <= 64)) AND (code ~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$'::text) AND ((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 250)) AND ((length(TRIM(BOTH FROM legal_name)) >= 1) AND (length(TRIM(BOTH FROM legal_name)) <= 250)) AND ((abbreviation IS NULL) OR (length(abbreviation) <= 64)) AND ((tax_identifier IS NULL) OR (length(tax_identifier) <= 100)) AND (total_balance <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])) AND ((NOT retired) OR (NOT active)) AND ((custom_field_count >= 0) AND (custom_field_count <= 500))))
);

