--
-- Name: service_agreement_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.service_agreement_versions (
    organization_id uuid NOT NULL,
    agreement_id uuid NOT NULL,
    revision integer NOT NULL,
    vendor_id uuid NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    no_of_services integer DEFAULT 0 NOT NULL,
    cost numeric(18,2) DEFAULT '0'::numeric NOT NULL,
    notes text,
    in_effect boolean DEFAULT false NOT NULL,
    attachment_file_id uuid,
    retired boolean DEFAULT false NOT NULL,
    vendor_revision integer NOT NULL,
    vendor_name text NOT NULL,
    request_id uuid NOT NULL,
    request_fingerprint text NOT NULL,
    previous_revision integer,
    operation text NOT NULL,
    instrument_count integer NOT NULL,
    service_count integer NOT NULL,
    instruments_provided boolean NOT NULL,
    services_provided boolean NOT NULL,
    saved_by uuid NOT NULL,
    saved_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT service_agreement_version_command CHECK (((request_fingerprint ~ '^[a-f0-9]{64}$'::text) AND (vendor_revision > 0) AND ((instrument_count >= 1) AND (instrument_count <= 500)) AND ((service_count >= 0) AND (service_count <= 3)) AND (retired = (operation = 'retire'::text)) AND ((operation <> 'retire'::text) OR ((NOT instruments_provided) AND (NOT services_provided))))),
    CONSTRAINT service_agreement_version_revision CHECK ((((operation = 'create'::text) AND (previous_revision IS NULL) AND (revision = 1)) OR ((operation = ANY (ARRAY['update'::text, 'retire'::text])) AND (previous_revision > 0) AND (previous_revision IS NOT NULL) AND (revision = (previous_revision + 1))))),
    CONSTRAINT service_agreement_version_values CHECK ((((start_date >= '0001-01-01'::date) AND (start_date <= '9999-12-31'::date)) AND ((end_date >= '0001-01-01'::date) AND (end_date <= '9999-12-31'::date)) AND (start_date <= end_date) AND (no_of_services >= 0) AND (cost >= (0)::numeric) AND (cost <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])) AND ((notes IS NULL) OR (length(notes) <= 10000)) AND ((NOT retired) OR (NOT in_effect))))
);

ALTER TABLE ONLY public.service_agreement_versions FORCE ROW LEVEL SECURITY;


