    CONSTRAINT service_agreement_revision CHECK ((revision > 0)),
    CONSTRAINT service_agreement_values CHECK ((((start_date >= '0001-01-01'::date) AND (start_date <= '9999-12-31'::date)) AND ((end_date >= '0001-01-01'::date) AND (end_date <= '9999-12-31'::date)) AND (start_date <= end_date) AND (no_of_services >= 0) AND (cost >= (0)::numeric) AND (cost <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])) AND ((notes IS NULL) OR (length(notes) <= 10000)) AND ((NOT retired) OR (NOT in_effect))))
);

