    CONSTRAINT template_default_lexical CHECK (((default_lexical IS NULL) OR ((widget = 'result_widget'::text) AND (default_state = 'present'::text) AND (default_number IS NOT NULL) AND ((length(default_lexical) >= 1) AND (length(default_lexical) <= 1000)) AND
CASE
    WHEN (default_lexical ~ '^-?[0-9]+([.][0-9]+)?$'::text) THEN (default_number = (default_lexical)::numeric)
    ELSE false
END))),
    CONSTRAINT template_field_alias CHECK (((alias ~ '^[A-Za-z0-9_]*$'::text) AND (length(alias) <= 200))),
    CONSTRAINT template_field_context CHECK ((((source_field IS NULL) OR ((widget = 'sample_line_item_data_widget'::text) AND (source_field = ANY (ARRAY['custom_category'::text, 'custom_product'::text, 'custom_description'::text, 'custom_sample_quantity'::text, 'custom_sample_size'::text, 'custom_quality'::text, 'custom_indentification_mark'::text, 'custom_condition'::text]))) OR ((widget = 'sample_details_widget_v2'::text) AND (source_field = ANY (ARRAY['sampleNumber'::text, 'customerName'::text, 'customerAddress'::text, 'sampleCategoryName'::text, 'productName'::text, 'receivedAt'::text, 'registeredAt'::text, 'dueAt'::text, 'description'::text, 'customerReference'::text]))) OR ((widget = 'tr_data_widget'::text) AND (source_field = ANY (ARRAY['requestNumber'::text, 'parameterName'::text, 'productName'::text, 'methodName'::text, 'analystName'::text, 'submittedAt'::text, 'completedAt'::text]))) OR ((widget = 'decision_rule_widget'::text) AND (source_field = ANY (ARRAY['specification'::text, 'measurementUnit'::text, 'parameterName'::text, 'productName'::text, 'methodName'::text, 'decisionOutcome'::text])))) AND ((serial_padding IS NULL) OR ((widget = 'sno_widget'::text) AND ((serial_padding >= 0) AND (serial_padding <= 100)))) AND ((widget <> ALL (ARRAY['sample_details_widget_v2'::text, 'product_detail_widget'::text, 'sample_line_item_data_widget'::text, 'tr_data_widget'::text, 'decision_rule_widget'::text, 'tr_result_widget'::text, 'sno_widget'::text])) OR (NOT editable)))),
    CONSTRAINT template_field_default CHECK ((((default_state = ANY (ARRAY['absent'::text, 'empty'::text])) AND (num_nonnulls(default_text, default_number, default_boolean, default_date, default_image_id) = 0)) OR ((default_state = 'present'::text) AND (num_nonnulls(default_text, default_number, default_boolean, default_date, default_image_id) = 1) AND (((value_type = ANY (ARRAY['text'::text, 'result'::text, 'parameter_detail'::text])) AND (default_text IS NOT NULL)) OR ((value_type = ANY (ARRAY['numeric'::text, 'result'::text])) AND (default_number IS NOT NULL) AND ((default_number)::text <> ALL (ARRAY['NaN'::text, 'Infinity'::text, '-Infinity'::text]))) OR ((value_type = 'boolean'::text) AND (default_boolean IS NOT NULL)) OR ((value_type = 'date'::text) AND (default_date IS NOT NULL)) OR ((value_type = 'image'::text) AND (default_image_id IS NOT NULL)))))),
    CONSTRAINT template_formula_error_handling CHECK (((formula_on_missing_value = ANY (ARRAY['zero'::text, 'blank'::text, 'error'::text])) AND (formula_on_error = ANY (ARRAY['show_error'::text, 'blank'::text])) AND ((widget = 'formula_widget'::text) OR ((formula_on_missing_value = 'error'::text) AND (formula_on_error = 'show_error'::text))))),
    CONSTRAINT template_image_readonly CHECK (((widget <> 'template_image_widget'::text) OR (NOT editable))),
    CONSTRAINT template_parameter_detail_readonly CHECK (((widget <> 'parameter_detail_widget'::text) OR (NOT editable))),
    CONSTRAINT template_vertical_text_readonly CHECK (((widget <> 'vertical_text_widget'::text) OR (NOT editable))),
    CONSTRAINT template_widget_type CHECK ((((widget = ANY (ARRAY['text_widget'::text, 'vertical_text_widget'::text, 'input_widget'::text, 'paragraph_widget'::text, 'sample_details_widget_v2'::text, 'product_detail_widget'::text, 'sample_line_item_data_widget'::text, 'tr_data_widget'::text, 'decision_rule_widget'::text, 'tr_result_widget'::text, 'sno_widget'::text, 'qr_code_widget'::text])) AND (value_type = 'text'::text)) OR ((widget = ANY (ARRAY['number_widget'::text, 'formula_widget'::text])) AND (value_type = 'numeric'::text)) OR ((widget = 'result_widget'::text) AND (value_type = ANY (ARRAY['numeric'::text, 'result'::text]))) OR ((widget = 'checkbox_widget'::text) AND (value_type = 'boolean'::text)) OR ((widget = 'datepicker_widget'::text) AND (value_type = 'date'::text)) OR ((widget = 'dropdown_widget'::text) AND (value_type = 'option'::text)) OR ((widget = 'template_image_widget'::text) AND (value_type = 'image'::text)) OR ((widget = 'parameter_detail_widget'::text) AND (value_type = 'parameter_detail'::text))))
);


