    CONSTRAINT template_parameter_detail_value CHECK ((((value_type <> 'parameter_detail'::text) AND (origin <> 'parameter'::text) AND (num_nonnulls(parameter_detail_kind, parameter_detail_item_count, parameter_detail_specification_id) = 0)) OR ((value_type = 'parameter_detail'::text) AND (origin = 'parameter'::text) AND (parameter_detail_kind IS NOT NULL) AND (parameter_detail_item_count IS NOT NULL) AND (parameter_detail_specification_id IS NOT NULL) AND (lexical IS NULL) AND (state = ANY (ARRAY['present'::text, 'empty'::text])) AND (((parameter_detail_kind = 'array'::text) AND (state = 'present'::text) AND ((parameter_detail_item_count >= 0) AND (parameter_detail_item_count <= 1000)) AND (num_nonnulls(number_value, text_value, boolean_value, date_value, option_id, image_id) = 0)) OR ((parameter_detail_item_count = 0) AND (((parameter_detail_kind = 'text'::text) AND (((state = 'empty'::text) AND (text_value IS NULL)) OR ((state = 'present'::text) AND (text_value IS NOT NULL) AND (length(text_value) <= 16000)))) OR ((parameter_detail_kind = 'numeric'::text) AND (state = 'present'::text) AND (number_value IS NOT NULL)) OR ((parameter_detail_kind = 'boolean'::text) AND (state = 'present'::text) AND (boolean_value IS NOT NULL)))))))),
    CONSTRAINT template_value_payload CHECK (((((state = ANY (ARRAY['absent'::text, 'empty'::text, 'not_applicable'::text, 'invalid'::text])) AND (num_nonnulls(number_value, text_value, boolean_value, date_value, option_id, image_id) = 0)) OR ((state = 'present'::text) AND (num_nonnulls(number_value, text_value, boolean_value, date_value, option_id, image_id) = 1) AND (((value_type = ANY (ARRAY['numeric'::text, 'result'::text, 'parameter_detail'::text])) AND (number_value IS NOT NULL) AND ((number_value)::text <> ALL (ARRAY['NaN'::text, 'Infinity'::text, '-Infinity'::text]))) OR ((value_type = ANY (ARRAY['text'::text, 'result'::text, 'parameter_detail'::text])) AND (text_value IS NOT NULL)) OR ((value_type = ANY (ARRAY['boolean'::text, 'parameter_detail'::text])) AND (boolean_value IS NOT NULL)) OR ((value_type = 'date'::text) AND (date_value IS NOT NULL)) OR ((value_type = 'option'::text) AND (option_id IS NOT NULL)) OR ((value_type = 'image'::text) AND (image_id IS NOT NULL)))) OR ((state = 'present'::text) AND (value_type = 'parameter_detail'::text) AND (parameter_detail_kind = 'array'::text) AND (num_nonnulls(number_value, text_value, boolean_value, date_value, option_id, image_id) = 0))) AND (((state = 'invalid'::text) AND (error_code IS NOT NULL) AND (error_message IS NOT NULL)) OR ((state <> 'invalid'::text) AND (error_code IS NULL) AND (error_message IS NULL))))),
    CONSTRAINT template_value_revision CHECK (((revision > 0) AND (origin = ANY (ARRAY['entered'::text, 'calculated'::text, 'default'::text, 'parameter'::text]))))
);


