--
-- Name: user_account_commands; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_account_commands (
    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    request_id uuid NOT NULL,
    fingerprint bytea NOT NULL,
    revision integer NOT NULL,
    previous_revision integer NOT NULL,
    credential_revision integer NOT NULL,
    previous_credential_revision integer NOT NULL,
    password_changed boolean NOT NULL,
    username text NOT NULL,
    email text NOT NULL,
    display_name text NOT NULL,
    previous_username text NOT NULL,
    previous_email text NOT NULL,
    previous_display_name text NOT NULL,
    saved_by uuid NOT NULL,
    saved_by_username text NOT NULL,
    saved_by_name text NOT NULL,
    saved_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    form_fingerprint bytea,
    form_profile_revision integer,
    form_custom_field_revision integer,
    CONSTRAINT user_account_form_shape CHECK ((((form_fingerprint IS NULL) AND (num_nonnulls(form_profile_revision, form_custom_field_revision) = 0)) OR ((form_fingerprint IS NOT NULL) AND (octet_length(form_fingerprint) = 32) AND ((form_profile_revision IS NULL) OR (form_profile_revision > 0)) AND ((form_custom_field_revision IS NULL) OR (form_custom_field_revision > 0))))),
    CONSTRAINT user_account_identity CHECK (((octet_length(fingerprint) = 32) AND ((length(TRIM(BOTH FROM username)) >= 1) AND (length(TRIM(BOTH FROM username)) <= 100)) AND ((length(TRIM(BOTH FROM email)) >= 1) AND (length(TRIM(BOTH FROM email)) <= 320)) AND ((length(TRIM(BOTH FROM display_name)) >= 1) AND (length(TRIM(BOTH FROM display_name)) <= 200)) AND ((length(TRIM(BOTH FROM saved_by_username)) >= 1) AND (length(TRIM(BOTH FROM saved_by_username)) <= 100)) AND ((length(TRIM(BOTH FROM saved_by_name)) >= 1) AND (length(TRIM(BOTH FROM saved_by_name)) <= 200)))),
    CONSTRAINT user_account_revisions CHECK (((previous_revision > 0) AND (revision = (previous_revision + 1)) AND (previous_credential_revision > 0) AND (credential_revision = (previous_credential_revision +
CASE
    WHEN password_changed THEN 1
    ELSE 0
END))))
);


--
-- Name: user_account_heads; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_account_heads WITH (security_barrier='true', security_invoker='false') AS
 SELECT membership.organization_id,
    person.id,
    person.revision,
    person.username,
    person.email,
    person.display_name,
    (public.app_has_permission('users.manage'::text) AND ((person.id = (NULLIF(current_setting('app.user_id'::text, true), ''::text))::uuid) OR public.auth_is_platform_administrator() OR ((NOT (EXISTS ( SELECT 1
           FROM public.memberships other
          WHERE ((other.user_id = person.id) AND (other.organization_id <> membership.organization_id))))) AND (NOT (EXISTS ( SELECT 1
           FROM public.platform_administrators administrator
          WHERE (administrator.user_id = person.id))))))) AS can_edit_identity
   FROM (public.memberships membership
     JOIN public.users person ON ((person.id = membership.user_id)))
  WHERE (membership.organization_id = ( SELECT public.users_directory_organization() AS users_directory_organization));


--
-- Name: user_account_history; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_account_history WITH (security_barrier='true', security_invoker='false') AS
 SELECT organization_id,
    user_id,
    revision,
    previous_revision,
    username,
    email,
    display_name,
    previous_username,
    previous_email,
    previous_display_name,
    password_changed,
    saved_by,
    saved_by_username,
    saved_by_name,
    saved_at
   FROM public.user_account_commands
  WHERE (organization_id = ( SELECT public.users_directory_organization() AS users_directory_organization));


