    certificate_file_id uuid,
    reviewer_id uuid,
    revision integer DEFAULT 1 NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    updated_by uuid NOT NULL,
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT user_certification_fields CHECK ((((length(TRIM(BOTH FROM certification_name)) >= 1) AND (length(TRIM(BOTH FROM certification_name)) <= 200)) AND (completion_status = ANY (ARRAY['pending'::text, 'completed'::text, 'expired'::text])) AND ((valid_till IS NULL) OR (valid_till >= valid_from)) AND (revision > 0)))
);

ALTER TABLE ONLY public.user_certifications FORCE ROW LEVEL SECURITY;


--
