    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT user_creation_fields CHECK (((octet_length(fingerprint) = 32) AND (profile_revision = 1) AND ((length(TRIM(BOTH FROM username)) >= 1) AND (length(TRIM(BOTH FROM username)) <= 100)) AND ((length(TRIM(BOTH FROM email)) >= 1) AND (length(TRIM(BOTH FROM email)) <= 320)) AND ((length(TRIM(BOTH FROM display_name)) >= 1) AND (length(TRIM(BOTH FROM display_name)) <= 200))))
);


