    file.content
   FROM (public.custom_field_attachments file
     JOIN public.custom_field_versions version ON (((version.organization_id = file.organization_id) AND (version.field_id = file.field_id) AND (version.revision = file.field_revision))))
  WHERE ((file.organization_id = ( SELECT public.users_directory_organization() AS users_directory_organization)) AND (version.associated_with = 'users'::text) AND (version.field_type = 'attachment'::text));


