--
-- Name: user_custom_field_lookup_lines; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_custom_field_lookup_lines WITH (security_barrier='true', security_invoker='false') AS
 SELECT line.organization_id,
    line.source_id,
    line.revision,
    line.original_line_id,
    line."position",
    line.label_kind,
    line.label_text,
    line.label_number,
    line.label_boolean
   FROM (public.custom_field_lookup_lines line
     JOIN public.custom_field_lookup_sources source ON (((source.organization_id = line.organization_id) AND (source.id = line.source_id) AND (source.revision = line.revision))))
  WHERE ((line.organization_id = ( SELECT public.users_directory_organization() AS users_directory_organization)) AND (EXISTS ( SELECT 1
           FROM public.custom_field_definitions field
          WHERE ((field.organization_id = line.organization_id) AND field.active AND (field.associated_with = 'users'::text) AND (field.field_type = 'lookup'::text) AND (field.lookup_source_id = line.source_id)))));


--
-- Name: user_custom_field_version_options; Type: VIEW; Schema: public; Owner: -
