    explicitly_selected boolean NOT NULL,
    CONSTRAINT user_profile_observed_role_revision CHECK (((recorded_role_revision IS NULL) OR (recorded_role_revision > 0)))
);


--
-- Name: user_profile_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_profile_versions (
    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    employee_code text,
    phone text,
    designation text,
    can_manage_people boolean NOT NULL,
    business_unit_id uuid,
    default_role_id uuid NOT NULL,
    laboratory_id uuid NOT NULL,
    reporting_manager_id uuid,
    revision integer NOT NULL,
    previous_revision integer,
    request_id uuid NOT NULL,
    employee_code_provided boolean NOT NULL,
    phone_provided boolean NOT NULL,
    designation_provided boolean NOT NULL,
    can_manage_people_provided boolean NOT NULL,
    business_unit_provided boolean NOT NULL,
    default_role_provided boolean NOT NULL,
    laboratory_provided boolean NOT NULL,
    reporting_manager_provided boolean NOT NULL,
    roles_provided boolean NOT NULL,
    business_unit_code text,
    business_unit_name text,
    laboratory_code text NOT NULL,
    laboratory_name text NOT NULL,
    reporting_manager_username text,
    reporting_manager_name text,
    role_count integer NOT NULL,
    saved_by uuid NOT NULL,
    saved_by_username text NOT NULL,
    saved_by_name text NOT NULL,
    saved_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT user_profile_version_details CHECK (((role_count > 0) AND (((business_unit_id IS NULL) AND (num_nonnulls(business_unit_code, business_unit_name) = 0)) OR ((business_unit_id IS NOT NULL) AND (num_nonnulls(business_unit_code, business_unit_name) = 2))) AND (((reporting_manager_id IS NULL) AND (num_nonnulls(reporting_manager_username, reporting_manager_name) = 0)) OR ((reporting_manager_id IS NOT NULL) AND (num_nonnulls(reporting_manager_username, reporting_manager_name) = 2))) AND (employee_code_provided OR phone_provided OR designation_provided OR can_manage_people_provided OR business_unit_provided OR default_role_provided OR laboratory_provided OR reporting_manager_provided OR roles_provided))),
    CONSTRAINT user_profile_version_fields CHECK ((((employee_code IS NULL) OR ((length(employee_code) >= 1) AND (length(employee_code) <= 100))) AND ((phone IS NULL) OR ((length(phone) >= 1) AND (length(phone) <= 50))) AND ((designation IS NULL) OR ((length(designation) >= 1) AND (length(designation) <= 150))) AND (reporting_manager_id IS DISTINCT FROM user_id))),
    CONSTRAINT user_profile_version_revision CHECK ((((previous_revision IS NULL) AND (revision = 1)) OR ((previous_revision IS NOT NULL) AND (previous_revision > 0) AND (revision = (previous_revision + 1)))))
);


--
-- Name: user_profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_profiles (
