    laboratory_id uuid NOT NULL,
    reporting_manager_id uuid,
    revision integer NOT NULL,
    CONSTRAINT user_profile_fields CHECK ((((employee_code IS NULL) OR ((length(employee_code) >= 1) AND (length(employee_code) <= 100))) AND ((phone IS NULL) OR ((length(phone) >= 1) AND (length(phone) <= 50))) AND ((designation IS NULL) OR ((length(designation) >= 1) AND (length(designation) <= 150))) AND (reporting_manager_id IS DISTINCT FROM user_id))),
    CONSTRAINT user_profile_revision CHECK ((revision > 0))
);


--
-- Name: user_directory; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_directory WITH (security_barrier='true', security_invoker='false') AS
 SELECT membership.organization_id,
    person.id,
    person.username,
    person.email,
    person.display_name,
    (person.active AND membership.active) AS active,
    membership.created_at,
    organization.name AS organization_name,
    membership.active AS membership_active,
    person.active AS identity_active,
    membership.status_revision,
    person.created_at AS identity_created_at,
    version.default_role_id,
    observed.name AS default_role_name,
    role.description AS default_role_description,
    version.business_unit_id,
    version.business_unit_name,
    activity.last_login_at,
    activity.last_logout_at
   FROM (((((((public.memberships membership
     JOIN public.users person ON ((person.id = membership.user_id)))
     JOIN public.organizations organization ON ((organization.id = membership.organization_id)))
     LEFT JOIN public.user_profiles profile ON (((profile.organization_id = membership.organization_id) AND (profile.user_id = person.id))))
     LEFT JOIN public.user_profile_versions version ON (((version.organization_id = profile.organization_id) AND (version.user_id = profile.user_id) AND (version.revision = profile.revision))))
     LEFT JOIN public.user_profile_version_roles observed ON (((observed.organization_id = version.organization_id) AND (observed.user_id = version.user_id) AND (observed.revision = version.revision) AND (observed.role_id = version.default_role_id))))
     LEFT JOIN public.roles role ON (((role.organization_id = version.organization_id) AND (role.id = version.default_role_id))))
     LEFT JOIN LATERAL ( SELECT max(event.occurred_at) FILTER (WHERE (event.kind = 'sign_in'::text)) AS last_login_at,
            max(event.occurred_at) FILTER (WHERE (event.kind = 'sign_out'::text)) AS last_logout_at
           FROM public.account_events event
          WHERE ((event.organization_id = membership.organization_id) AND (event.user_id = person.id) AND (event.kind = ANY (ARRAY['sign_in'::text, 'sign_out'::text])))) activity ON (true))
  WHERE (membership.organization_id = ( SELECT public.users_directory_organization() AS users_directory_organization));


--
-- Name: user_directory_activity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_directory_activity WITH (security_barrier='true', security_invoker='false') AS
 SELECT event.organization_id,
    event.user_id,
    event.kind,
    event.occurred_at
   FROM (public.account_events event
     JOIN public.memberships membership ON (((membership.organization_id = event.organization_id) AND (membership.user_id = event.user_id))))
  WHERE ((event.organization_id = ( SELECT public.users_directory_organization() AS users_directory_organization)) AND (event.kind = ANY (ARRAY['sign_in'::text, 'sign_out'::text])));


--
-- Name: user_directory_roles; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_directory_roles WITH (security_barrier='true', security_invoker='false') AS
 SELECT assignment.organization_id,
    assignment.user_id,
    role.id AS role_id,
    role.name,
    role.description,
    role.active
   FROM (public.membership_roles assignment
     JOIN public.roles role ON (((role.organization_id = assignment.organization_id) AND (role.id = assignment.role_id))))
  WHERE (assignment.organization_id = ( SELECT public.users_directory_organization() AS users_directory_organization));


