-- Name: user_field_capture_heads; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_field_capture_heads WITH (security_barrier='true', security_invoker='false') AS
 SELECT organization_id,
    user_id AS subject_user_id,
