   FROM public.memberships member
  WHERE (organization_id = ( SELECT public.users_directory_organization() AS users_directory_organization));


--
-- Name: user_field_value_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_field_value_versions (
    organization_id uuid NOT NULL,
    subject_user_id uuid NOT NULL,
    revision integer NOT NULL,
    request_id uuid NOT NULL,
    previous_revision integer NOT NULL,
    custom_field_count integer NOT NULL,
    time_zone text,
    username text NOT NULL,
    display_name text NOT NULL,
    saved_by uuid NOT NULL,
    saved_by_username text NOT NULL,
    saved_by_name text NOT NULL,
    saved_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT user_field_value_labels CHECK ((((length(TRIM(BOTH FROM username)) >= 1) AND (length(TRIM(BOTH FROM username)) <= 100)) AND ((length(TRIM(BOTH FROM display_name)) >= 1) AND (length(TRIM(BOTH FROM display_name)) <= 200)) AND ((length(TRIM(BOTH FROM saved_by_username)) >= 1) AND (length(TRIM(BOTH FROM saved_by_username)) <= 100)) AND ((length(TRIM(BOTH FROM saved_by_name)) >= 1) AND (length(TRIM(BOTH FROM saved_by_name)) <= 200)))),
    CONSTRAINT user_field_value_version CHECK (((previous_revision >= 0) AND (revision = (previous_revision + 1)) AND ((custom_field_count >= 0) AND (custom_field_count <= 500)) AND ((time_zone IS NULL) OR ((custom_field_count > 0) AND ((length(time_zone) >= 1) AND (length(time_zone) <= 100))))))
);


--
-- Name: user_field_capture_history; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_field_capture_history WITH (security_barrier='true', security_invoker='false') AS
 SELECT organization_id,
    subject_user_id,
    revision,
    previous_revision,
    custom_field_count,
    time_zone,
    username,
    display_name,
    saved_by,
    saved_by_username,
    saved_by_name,
    saved_at
   FROM public.user_field_value_versions
  WHERE (organization_id = ( SELECT public.users_directory_organization() AS users_directory_organization));


--
-- Name: user_version_custom_fields; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_version_custom_fields (
    organization_id uuid NOT NULL,
    subject_user_id uuid NOT NULL,
    revision integer NOT NULL,
    field_id uuid NOT NULL,
    field_revision integer NOT NULL,
    field_type text NOT NULL,
    "position" integer NOT NULL,
    is_array boolean NOT NULL,
    value_count integer NOT NULL,
    display_kind text NOT NULL,
    display_text text,
    display_number double precision,
    display_boolean boolean,
    time_zone text,
    time_zone_data_version text,
    date_parser_version text,
    CONSTRAINT user_custom_field_display CHECK (((num_nonnulls(display_text, display_number, display_boolean) = 1) AND (((display_kind = 'text'::text) AND (display_text IS NOT NULL) AND (length(display_text) <= 8000998)) OR ((display_kind = 'number'::text) AND (display_number IS NOT NULL) AND ((display_number >= '-1.7976931348623157e+308'::double precision) AND (display_number <= '1.7976931348623157e+308'::double precision))) OR ((display_kind = 'boolean'::text) AND (display_boolean IS NOT NULL))) AND ((NOT is_array) OR (display_kind = 'text'::text)))),
    CONSTRAINT user_custom_field_shape CHECK (((("position" >= 0) AND ("position" <= 499)) AND ((value_count >= 0) AND (value_count <= 500)) AND (is_array OR (value_count = 1)) AND (field_type = ANY (ARRAY['text'::text, 'number'::text, 'date'::text, 'select'::text, 'lookup'::text, 'longtext'::text, 'attachment'::text, 'multi_user_select'::text, 'date_time'::text, 'checkbox'::text, 'email'::text])))),
    CONSTRAINT user_custom_field_zone CHECK ((((field_type = ANY (ARRAY['date'::text, 'date_time'::text])) AND (time_zone IS NOT NULL) AND ((length(time_zone) >= 1) AND (length(time_zone) <= 100)) AND (time_zone_data_version IS NOT NULL) AND ((length(time_zone_data_version) >= 1) AND (length(time_zone_data_version) <= 40)) AND (date_parser_version IS NOT NULL) AND ((length(date_parser_version) >= 1) AND (length(date_parser_version) <= 80))) OR ((field_type <> ALL (ARRAY['date'::text, 'date_time'::text])) AND (num_nonnulls(time_zone, time_zone_data_version, date_parser_version) = 0))))
);

ALTER TABLE ONLY public.user_version_custom_fields FORCE ROW LEVEL SECURITY;


--
-- Name: user_field_generation_values; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.user_field_generation_values WITH (security_barrier='true', security_invoker='false') AS
 SELECT member.organization_id,
    member.user_id AS subject_user_id,
    person.created_at,
    capture.saved_at AS updated_at,
    definition.key AS field_key,
    field.display_text
   FROM ((((public.memberships member
     JOIN public.users person ON ((person.id = member.user_id)))
     JOIN public.user_field_value_versions capture ON (((capture.organization_id = member.organization_id) AND (capture.subject_user_id = member.user_id) AND (capture.revision = member.custom_field_revision))))
     JOIN public.user_version_custom_fields field ON (((field.organization_id = capture.organization_id) AND (field.subject_user_id = capture.subject_user_id) AND (field.revision = capture.revision))))
     JOIN public.custom_field_versions definition ON (((definition.organization_id = field.organization_id) AND (definition.field_id = field.field_id) AND (definition.revision = field.field_revision))))
  WHERE ((member.organization_id = ( SELECT public.users_directory_organization() AS users_directory_organization)) AND ( SELECT public.app_has_permission('users.manage'::text) AS app_has_permission) AND (field.display_kind = 'text'::text));


--
-- Name: user_mfa; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_mfa (
    user_id uuid NOT NULL,
    encrypted_secret text,
    enabled boolean DEFAULT false NOT NULL,
    last_used_step bigint DEFAULT '-1'::integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    change_id uuid,
    change_session_id uuid,
    CONSTRAINT user_mfa_change_identity CHECK (((change_id IS NULL) = (change_session_id IS NULL))),
    CONSTRAINT user_mfa_revision_positive CHECK ((revision > 0)),
    CONSTRAINT user_mfa_secret_state CHECK (((enabled AND (encrypted_secret IS NOT NULL) AND (last_used_step >= '-1'::integer)) OR ((NOT enabled) AND (encrypted_secret IS NULL) AND (last_used_step = '-1'::integer))))
);


--
-- Name: user_mfa_setups; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_mfa_setups (
    session_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    encrypted_secret text NOT NULL,
    credential_revision integer NOT NULL,
    mfa_revision integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    CONSTRAINT user_mfa_setups_ciphertext CHECK ((encrypted_secret ~ '^[A-Za-z0-9_-]{60,220}$'::text)),
    CONSTRAINT user_mfa_setups_expiry CHECK ((expires_at > created_at)),
    CONSTRAINT user_mfa_setups_revisions CHECK (((credential_revision > 0) AND (mfa_revision >= 0)))
);


--
-- Name: user_profile_heads; Type: VIEW; Schema: public; Owner: -
