    saved_by_name text NOT NULL,
    saved_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT user_status_labels CHECK ((((length(TRIM(BOTH FROM username)) >= 1) AND (length(TRIM(BOTH FROM username)) <= 100)) AND ((length(TRIM(BOTH FROM display_name)) >= 1) AND (length(TRIM(BOTH FROM display_name)) <= 200)) AND ((length(TRIM(BOTH FROM saved_by_username)) >= 1) AND (length(TRIM(BOTH FROM saved_by_username)) <= 100)) AND ((length(TRIM(BOTH FROM saved_by_name)) >= 1) AND (length(TRIM(BOTH FROM saved_by_name)) <= 200)))),
    CONSTRAINT user_status_transition CHECK (((previous_revision >= 0) AND (revision = (previous_revision + 1)) AND (active <> previous_active)))
);


