    phone text NOT NULL,
    is_primary boolean DEFAULT false NOT NULL,
    CONSTRAINT vendor_contact_values CHECK ((((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 200)) AND ((length(email) >= 3) AND (length(email) <= 320)) AND (email ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'::text) AND ((length(TRIM(BOTH FROM phone)) >= 1) AND (length(TRIM(BOTH FROM phone)) <= 50))))
);

