    CONSTRAINT vendor_custom_value_lookup_reference CHECK (((num_nonnulls(lookup_source_id, lookup_revision, lookup_line_id) = 0) OR ((lookup_source_id IS NOT NULL) AND (lookup_revision IS NOT NULL) AND (lookup_revision > 0) AND (lookup_line_id IS NOT NULL)))),
