END),
    CONSTRAINT vendor_custom_value_raw CHECK (((("position" >= 0) AND ("position" <= 499)) AND (num_nonnulls(raw_text, raw_number, raw_boolean) = 1) AND (((raw_kind = 'text'::text) AND (raw_text IS NOT NULL) AND (length(raw_text) <= 16000)) OR ((raw_kind = 'number'::text) AND (raw_number IS NOT NULL) AND ((raw_number >= '-1.7976931348623157e+308'::double precision) AND (raw_number <= '1.7976931348623157e+308'::double precision))) OR ((raw_kind = 'boolean'::text) AND (raw_boolean IS NOT NULL)))))
);

