--
-- Name: vendor_version_custom_fields; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vendor_version_custom_fields (
    organization_id uuid NOT NULL,
    vendor_id uuid NOT NULL,
    revision integer NOT NULL,
    field_id uuid NOT NULL,
    field_revision integer NOT NULL,
    field_type text NOT NULL,
    "position" integer NOT NULL,
    is_array boolean NOT NULL,
    value_count integer NOT NULL,
    display_kind text NOT NULL,
    display_text text,
    display_number double precision,
    display_boolean boolean,
    time_zone text,
    time_zone_data_version text,
    date_parser_version text,
    CONSTRAINT vendor_custom_field_display CHECK (((num_nonnulls(display_text, display_number, display_boolean) = 1) AND (((display_kind = 'text'::text) AND (display_text IS NOT NULL) AND (length(display_text) <= 8000998)) OR ((display_kind = 'number'::text) AND (display_number IS NOT NULL) AND ((display_number >= '-1.7976931348623157e+308'::double precision) AND (display_number <= '1.7976931348623157e+308'::double precision))) OR ((display_kind = 'boolean'::text) AND (display_boolean IS NOT NULL))) AND ((NOT is_array) OR (display_kind = 'text'::text)))),
    CONSTRAINT vendor_custom_field_shape CHECK (((("position" >= 0) AND ("position" <= 499)) AND ((value_count >= 0) AND (value_count <= 500)) AND (is_array OR (value_count = 1)) AND (field_type = ANY (ARRAY['text'::text, 'number'::text, 'date'::text, 'select'::text, 'lookup'::text, 'longtext'::text, 'attachment'::text, 'multi_user_select'::text, 'date_time'::text, 'checkbox'::text, 'email'::text])))),
    CONSTRAINT vendor_custom_field_zone CHECK ((((field_type = ANY (ARRAY['date'::text, 'date_time'::text])) AND (time_zone IS NOT NULL) AND ((length(time_zone) >= 1) AND (length(time_zone) <= 100)) AND (time_zone_data_version IS NOT NULL) AND ((length(time_zone_data_version) >= 1) AND (length(time_zone_data_version) <= 40)) AND (date_parser_version IS NOT NULL) AND ((length(date_parser_version) >= 1) AND (length(date_parser_version) <= 80))) OR ((field_type <> ALL (ARRAY['date'::text, 'date_time'::text])) AND (num_nonnulls(time_zone, time_zone_data_version, date_parser_version) = 0))))
);

ALTER TABLE ONLY public.vendor_version_custom_fields FORCE ROW LEVEL SECURITY;


--
-- Name: vendor_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vendor_versions (
    organization_id uuid NOT NULL,
    vendor_id uuid NOT NULL,
    revision integer NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    legal_name text NOT NULL,
    abbreviation text,
    tax_identifier text,
    total_balance numeric(18,2) DEFAULT '0'::numeric NOT NULL,
    active boolean DEFAULT true NOT NULL,
    retired boolean DEFAULT false NOT NULL,
    custom_field_count integer DEFAULT 0 NOT NULL,
    custom_fields_provided boolean DEFAULT false NOT NULL,
    request_id uuid NOT NULL,
    request_fingerprint text NOT NULL,
    previous_revision integer,
    operation text NOT NULL,
    contact_count integer NOT NULL,
    saved_by uuid NOT NULL,
    saved_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT vendor_version_command CHECK (((request_fingerprint ~ '^[a-f0-9]{64}$'::text) AND ((contact_count >= 1) AND (contact_count <= 100)) AND (retired = (operation = 'retire'::text)) AND ((NOT retired) OR (NOT custom_fields_provided)))),
    CONSTRAINT vendor_version_revision CHECK ((((operation = 'create'::text) AND (previous_revision IS NULL) AND (revision = 1)) OR ((operation = ANY (ARRAY['update'::text, 'retire'::text])) AND (previous_revision > 0) AND (previous_revision IS NOT NULL) AND (revision = (previous_revision + 1))))),
    CONSTRAINT vendor_version_values CHECK ((((length(TRIM(BOTH FROM code)) >= 1) AND (length(TRIM(BOTH FROM code)) <= 64)) AND (code ~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$'::text) AND ((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 250)) AND ((length(TRIM(BOTH FROM legal_name)) >= 1) AND (length(TRIM(BOTH FROM legal_name)) <= 250)) AND ((abbreviation IS NULL) OR (length(abbreviation) <= 64)) AND ((tax_identifier IS NULL) OR (length(tax_identifier) <= 100)) AND (total_balance <> ALL (ARRAY['NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric])) AND ((NOT retired) OR (NOT active)) AND ((custom_field_count >= 0) AND (custom_field_count <= 500))))
);

ALTER TABLE ONLY public.vendor_versions FORCE ROW LEVEL SECURITY;


