-- Name: workflow_checklist_labels; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.workflow_checklist_labels WITH (security_barrier='true', security_invoker='false') AS
 SELECT organization_id,
    id,
    name,
    is_active,
    revision
   FROM public.checklists
  WHERE ((retired_at IS NULL) AND (organization_id = (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid) AND ( SELECT (public.app_has_permission('workflows.read'::text) OR public.app_has_permission('workflows.manage'::text))));


--
-- Name: workflow_clone_origins; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_clone_origins (
    organization_id uuid NOT NULL,
    workflow_id uuid NOT NULL,
    workflow_version_id uuid NOT NULL,
    cloned_revision integer NOT NULL,
    source_workflow_id uuid NOT NULL,
    source_version_id uuid NOT NULL,
    source_revision integer NOT NULL,
    source_metadata_revision integer NOT NULL,
    requested_source_version_id uuid,
    request_id uuid NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT workflow_clone_origin_identity CHECK (((workflow_id <> source_workflow_id) AND (workflow_version_id <> source_version_id) AND (cloned_revision > 0) AND (source_revision > 0) AND (source_metadata_revision >= 0)))
);


--
-- Name: workflow_editor_commands; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_editor_commands (
    organization_id uuid NOT NULL,
    request_id uuid NOT NULL,
    workflow_id uuid NOT NULL,
    source_version_id uuid NOT NULL,
    source_revision integer NOT NULL,
    workflow_version_id uuid NOT NULL,
    revision integer NOT NULL,
    operation text NOT NULL,
    source_element_id uuid,
    element_id uuid,
    fingerprint bytea NOT NULL,
    saved_by uuid NOT NULL,
    saved_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT workflow_editor_command_elements CHECK ((((operation = ANY (ARRAY['patch_state'::text, 'delete_state'::text, 'patch_transition'::text, 'delete_transition'::text])) AND (source_element_id IS NOT NULL) AND (element_id IS NOT NULL) AND ((source_version_id <> workflow_version_id) OR (source_element_id = element_id))) OR ((operation = ANY (ARRAY['create_state'::text, 'create_transition'::text])) AND (source_element_id IS NULL) AND (element_id IS NOT NULL)) OR ((operation = ANY (ARRAY['publish'::text, 'save_draft'::text])) AND (source_element_id IS NULL) AND (element_id IS NULL)))),
    CONSTRAINT workflow_editor_command_fingerprint CHECK ((octet_length(fingerprint) = 32)),
    CONSTRAINT workflow_editor_command_operation CHECK ((operation = ANY (ARRAY['create_state'::text, 'patch_state'::text, 'delete_state'::text, 'create_transition'::text, 'patch_transition'::text, 'delete_transition'::text, 'publish'::text, 'save_draft'::text]))),
    CONSTRAINT workflow_editor_command_revision CHECK (((source_revision > 0) AND (revision > 1) AND (((source_version_id = workflow_version_id) AND (revision = (source_revision + 1))) OR ((source_version_id <> workflow_version_id) AND (revision = 2) AND (operation <> ALL (ARRAY['publish'::text, 'save_draft'::text]))))))
);


--
-- Name: workflow_metadata_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_metadata_versions (
    organization_id uuid NOT NULL,
    workflow_id uuid NOT NULL,
    revision integer NOT NULL,
    request_id uuid NOT NULL,
    previous_revision integer,
    operation text NOT NULL,
    initial_version_id uuid,
    code text NOT NULL,
    name text NOT NULL,
    description text NOT NULL,
    applies_to text NOT NULL,
    active boolean NOT NULL,
    requested_code text,
    generated_code boolean NOT NULL,
    description_provided boolean NOT NULL,
    requested_applies_to text,
    requested_active boolean,
    saved_by uuid NOT NULL,
    saved_at timestamp with time zone DEFAULT now() NOT NULL,
    created_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT workflow_metadata_history_fields CHECK ((((length(TRIM(BOTH FROM code)) >= 1) AND (length(TRIM(BOTH FROM code)) <= 64)) AND ((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 200)) AND (applies_to = ANY (ARRAY['sample'::text, 'test_request'::text, 'instrument_service'::text, 'document'::text])) AND ((requested_applies_to IS NULL) OR (requested_applies_to = ANY (ARRAY['sample'::text, 'test_request'::text, 'instrument_service'::text, 'document'::text]))) AND ((NOT generated_code) OR ((operation = 'create'::text) AND (requested_code IS NOT NULL))) AND ((operation <> 'retire'::text) OR ((NOT active) AND (NOT description_provided) AND (NOT generated_code) AND (num_nonnulls(requested_code, requested_applies_to, requested_active) = 0))))),
    CONSTRAINT workflow_metadata_history_revision CHECK ((((operation = 'create'::text) AND (previous_revision IS NULL) AND (revision = 1) AND (initial_version_id IS NOT NULL)) OR ((operation = ANY (ARRAY['update'::text, 'retire'::text])) AND (previous_revision IS NOT NULL) AND (previous_revision >= 0) AND (revision = (previous_revision + 1)) AND (initial_version_id IS NULL))))
);


