--
-- Name: workflow_state_capability_roles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_state_capability_roles (
    organization_id uuid NOT NULL,
    workflow_state_id uuid NOT NULL,
    capability text NOT NULL,
    role_id uuid NOT NULL,
    CONSTRAINT workflow_state_capability CHECK ((capability = ANY (ARRAY['view'::text, 'edit'::text, 'allocate'::text, 'execute'::text, 'review'::text, 'approve'::text, 'cancel'::text, 'download_report'::text])))
);


--
-- Name: workflow_template_labels; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.workflow_template_labels WITH (security_barrier='true', security_invoker='false') AS
 SELECT template.organization_id,
    template.id,
    version.name,
    template.active
   FROM (public.templates template
     JOIN LATERAL ( SELECT version_1.name
           FROM public.template_versions version_1
          WHERE ((version_1.organization_id = template.organization_id) AND (version_1.template_id = template.id) AND (version_1.status <> 'building'::text))
          ORDER BY (version_1.status = 'draft'::text) DESC, version_1.number DESC
         LIMIT 1) version ON (true))
  WHERE (template.organization_id = ( SELECT public.workflow_reference_organization() AS workflow_reference_organization));


