    stage_number integer NOT NULL,
    CONSTRAINT workflow_approver_stage_number CHECK (((stage_number >= 1) AND (stage_number <= 100)))
);


--
-- Name: workflow_transition_cc_emails; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_transition_cc_emails (
    organization_id uuid NOT NULL,
    transition_id uuid NOT NULL,
    email text NOT NULL,
    CONSTRAINT workflow_cc_email CHECK ((((length(email) >= 3) AND (length(email) <= 320)) AND (email = lower(TRIM(BOTH FROM email))) AND (email ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'::text)))
);


