--
-- Name: workflow_transition_checklist_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_transition_checklist_items (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    transition_id uuid NOT NULL,
    prompt text NOT NULL,
    is_required boolean DEFAULT true NOT NULL,
    display_order integer DEFAULT 0 NOT NULL,
    CONSTRAINT workflow_checklist_details CHECK ((((length(TRIM(BOTH FROM prompt)) >= 1) AND (length(TRIM(BOTH FROM prompt)) <= 500)) AND (display_order >= 0)))
);


--
-- Name: workflow_transition_conditions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_transition_conditions (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    transition_id uuid NOT NULL,
    source_field text NOT NULL,
    operator text NOT NULL,
    comparison_text text,
    comparison_number numeric,
    comparison_boolean boolean,
    comparison_date date,
    display_order integer DEFAULT 0 NOT NULL,
    CONSTRAINT workflow_condition_details CHECK ((((length(TRIM(BOTH FROM source_field)) >= 1) AND (length(TRIM(BOTH FROM source_field)) <= 150)) AND (operator = ANY (ARRAY['eq'::text, 'neq'::text, 'gt'::text, 'gte'::text, 'lt'::text, 'lte'::text, 'contains'::text, 'in'::text, 'is_null'::text, 'is_not_null'::text])) AND (display_order >= 0) AND (num_nonnulls(comparison_text, comparison_number, comparison_boolean, comparison_date) <= 1) AND ((comparison_text IS NULL) OR (length(comparison_text) <= 5000)) AND ((comparison_number IS NULL) OR ((comparison_number)::text <> ALL (ARRAY['NaN'::text, 'Infinity'::text, '-Infinity'::text])))))
);


