);


--
-- Name: workflow_transitions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_transitions (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workflow_version_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    source_state_id uuid NOT NULL,
    target_state_id uuid NOT NULL,
    approval_mode text DEFAULT 'none'::text NOT NULL,
    auto_execute boolean DEFAULT false NOT NULL,
    require_comment boolean DEFAULT false NOT NULL,
    display_order integer DEFAULT 0 NOT NULL,
    source_port integer,
    target_port integer,
    checklist_master_id uuid,
    checklist_master_revision integer,
    auto_move_mode text,
    CONSTRAINT workflow_transition_auto_move_mode CHECK (((auto_move_mode IS NULL) OR (auto_move_mode = ANY (ARRAY['yes'::text, 'no'::text, 'all_trs_allocated'::text, 'all_trs_approved'::text])))),
    CONSTRAINT workflow_transition_auto_move_pair CHECK (((auto_move_mode IS NULL) OR (auto_execute = (auto_move_mode = 'yes'::text)))),
    CONSTRAINT workflow_transition_checklist_binding CHECK (((checklist_master_revision IS NULL) OR ((checklist_master_id IS NOT NULL) AND (checklist_master_revision > 0)))),
    CONSTRAINT workflow_transition_details CHECK (((source_state_id <> target_state_id) AND (approval_mode = ANY (ARRAY['none'::text, 'any'::text, 'all'::text, 'sequential'::text])) AND (display_order >= 0) AND ((length(TRIM(BOTH FROM code)) >= 1) AND (length(TRIM(BOTH FROM code)) <= 64)) AND ((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 150)))),
    CONSTRAINT workflow_transition_ports CHECK ((((source_port IS NULL) OR ((source_port >= 1) AND (source_port <= 8))) AND ((target_port IS NULL) OR ((target_port >= 1) AND (target_port <= 8)))))
);


--
-- Name: workflow_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workflow_versions (
    organization_id uuid NOT NULL,
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workflow_id uuid NOT NULL,
    number integer NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    change_summary text DEFAULT ''::text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    published_by uuid,
    published_at timestamp with time zone,
    retired_at timestamp with time zone,
    CONSTRAINT workflow_version_revision CHECK (((number > 0) AND (revision > 0))),
    CONSTRAINT workflow_version_status CHECK ((((status = 'draft'::text) AND (published_by IS NULL) AND (published_at IS NULL) AND (retired_at IS NULL)) OR ((status = 'published'::text) AND (published_by IS NOT NULL) AND (published_at IS NOT NULL) AND (retired_at IS NULL)) OR ((status = 'retired'::text) AND (published_by IS NOT NULL) AND (published_at IS NOT NULL) AND (retired_at IS NOT NULL) AND (retired_at >= published_at))))
);


