CREATE POLICY custom_field_attachment_read ON public.custom_field_attachments FOR SELECT TO sampleify_app USING (((NOT (organization_id IS DISTINCT FROM ( SELECT public.organization_module_scope() AS organization_module_scope))) AND ( SELECT (public.app_has_permission('masters.read'::text) OR public.app_has_permission('masters.manage'::text))) AND (EXISTS ( SELECT 1
   FROM public.custom_field_versions definition
  WHERE ((definition.organization_id = custom_field_attachments.organization_id) AND (definition.field_id = custom_field_attachments.field_id) AND (definition.revision = custom_field_attachments.field_revision) AND (definition.field_type = 'attachment'::text) AND ((definition.associated_with = ANY (ARRAY['product'::text, 'parameter'::text, 'method_of_analysis'::text])) OR ((definition.associated_with = 'customer'::text) AND ( SELECT public.masters_can_read_party('customer'::text) AS masters_can_read_party)) OR ((definition.associated_with = 'vendor'::text) AND ( SELECT public.masters_can_read_party('vendor'::text) AS masters_can_read_party))))))));


