--
-- Name: template_parameter_detail_items parameter_detail_item_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY parameter_detail_item_insert ON public.template_parameter_detail_items FOR INSERT TO sampleify_app WITH CHECK (((organization_id = (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid) AND (EXISTS ( SELECT 1
   FROM public.template_values value
  WHERE ((value.organization_id = template_parameter_detail_items.organization_id) AND (value.instance_id = template_parameter_detail_items.instance_id) AND (value.field_id = template_parameter_detail_items.field_id) AND (value.occurrence_id = template_parameter_detail_items.occurrence_id) AND (value.revision = template_parameter_detail_items.revision))))));


--
-- Name: template_parameter_detail_items parameter_detail_item_read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY parameter_detail_item_read ON public.template_parameter_detail_items FOR SELECT TO sampleify_app, sampleify_report_worker USING ((EXISTS ( SELECT 1
   FROM public.template_values value
  WHERE ((value.organization_id = template_parameter_detail_items.organization_id) AND (value.instance_id = template_parameter_detail_items.instance_id) AND (value.field_id = template_parameter_detail_items.field_id) AND (value.occurrence_id = template_parameter_detail_items.occurrence_id) AND (value.revision = template_parameter_detail_items.revision)))));


--
-- Name: template_values parameter_detail_worker_read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY parameter_detail_worker_read ON public.template_values AS RESTRICTIVE FOR SELECT TO sampleify_report_worker USING (((value_type <> 'parameter_detail'::text) OR (EXISTS ( SELECT 1
   FROM (public.sample_report_tests chosen
     JOIN public.datasheet_submissions submission ON (((submission.organization_id = chosen.organization_id) AND (submission.id = chosen.submission_id))))
  WHERE ((chosen.organization_id = template_values.organization_id) AND (chosen.report_id = ( SELECT laboratory_parameter_context_scope.report_id
           FROM public.laboratory_parameter_context_scope() laboratory_parameter_context_scope(organization_id, report_id))) AND (submission.source = 'section'::text) AND (chosen.specification_id = template_values.parameter_detail_specification_id) AND (submission.instance_id = template_values.instance_id) AND (template_values.revision <= submission.capture_revision))))));


