-- Name: sample_tests registration_generate; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY registration_generate ON public.sample_tests FOR UPDATE TO sampleify_app USING (((organization_id = (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid) AND (status = 'planned'::text) AND (EXISTS ( SELECT 1
   FROM public.sample_products p
