--

CREATE POLICY workflow_generation_insert ON public.analytical_specification_limits FOR INSERT TO sampleify_app WITH CHECK (((organization_id = (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid) AND (EXISTS ( SELECT 1
   FROM public.analytical_specifications s
  WHERE ((s.organization_id = analytical_specification_limits.organization_id) AND (s.id = analytical_specification_limits.specification_id) AND (s.recorded_by = (NULLIF(current_setting('app.user_id'::text, true), ''::text))::uuid) AND (s.recorded_at = transaction_timestamp()) AND (( SELECT public.workflow_generating_sample() AS workflow_generating_sample) IS NOT NULL))))));


