--
-- Name: test_requests workflow_generation_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY workflow_generation_insert ON public.test_requests FOR INSERT TO sampleify_app WITH CHECK (((organization_id = (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid) AND (EXISTS ( SELECT 1
   FROM (public.sample_tests t
     JOIN public.sample_products p ON (((p.organization_id = t.organization_id) AND (p.id = t.sample_product_id))))
  WHERE ((t.organization_id = test_requests.organization_id) AND (t.id = test_requests.sample_test_id) AND (p.sample_id = ( SELECT public.workflow_generating_sample() AS workflow_generating_sample)))))));


--
-- Name: sample_tests workflow_generation_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY workflow_generation_update ON public.sample_tests FOR UPDATE TO sampleify_app USING (((organization_id = (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid) AND (status = 'planned'::text) AND (EXISTS ( SELECT 1
   FROM public.sample_products product
  WHERE ((product.organization_id = sample_tests.organization_id) AND (product.id = sample_tests.sample_product_id) AND (product.sample_id = ( SELECT public.workflow_generating_sample() AS workflow_generating_sample))))))) WITH CHECK (((organization_id = (NULLIF(current_setting('app.organization_id'::text, true), ''::text))::uuid) AND (status = 'requested'::text) AND (EXISTS ( SELECT 1
   FROM public.sample_products product
  WHERE ((product.organization_id = sample_tests.organization_id) AND (product.id = sample_tests.sample_product_id) AND (product.sample_id = ( SELECT public.workflow_generating_sample() AS workflow_generating_sample)))))));


